#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define ADS1115_CONV   0x00
#define ADS1115_CONFIG 0x01

#define CONFIG_OS      0x8000
#define CONFIG_MUX_AIN0 0x4000
#define CONFIG_PGA_4_096V 0x0200
#define CONFIG_MODE_SINGLE 0x0100
#define CONFIG_DR_128SPS 0x0080
#define CONFIG_CQUE_NONE 0x0003

#define VREF 4.096
#define SENSITIVITY 0.005
#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_read(int fd, float *current) {
    uint16_t config = CONFIG_OS | CONFIG_MUX_AIN0 | CONFIG_PGA_4_096V |
                      CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_CQUE_NONE;
    if (i2c_write16(fd, ADS1115_CONFIG, config) < 0) {
        return -1;
    }

    uint16_t cfg_readback;
    for (int i = 0; i < 10; i++) {
        if (i2c_read16(fd, ADS1115_CONFIG, &cfg_readback) < 0) {
            return -1;
        }
        if (cfg_readback & CONFIG_OS) {
            break;
        }
        usleep(10000);
    }
    if (!(cfg_readback & CONFIG_OS)) {
        fprintf(stderr, "ADS1115 conversion timeout\n");
        return -1;
    }

    uint16_t raw;
    if (i2c_read16(fd, ADS1115_CONV, &raw) < 0) {
        return -1;
    }

    int16_t signed_raw = (int16_t)raw;
    float voltage = (signed_raw * VREF) / 32768.0f;
    *current = voltage / SENSITIVITY;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    uint16_t cfg_check;
    if (i2c_read16(fd, ADS1115_CONFIG, &cfg_check) < 0) {
        fprintf(stderr, "ADS1115 not responding at address 0x%02X\n", ADS1115_ADDR);
        close(fd);
        return 1;
    }

    while (g_running) {
        float current;
        if (ads1115_read(fd, &current) < 0) {
            fprintf(stderr, "Error reading current from ADS1115\n");
        } else {
            printf("Current: %.3f A\n", current);
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    close(fd);
    printf("\nExiting gracefully.\n");
    return 0;
}

