#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_CONFIG_BASE 0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128 0x0080
#define TEMP_THRESHOLD 60.0
#define BUZZER_DURATION_MS 2000
#define POLL_INTERVAL_US 100000
#define DEBOUNCE_DELAY_US 50000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fflush(log_file);
    }
}

static int read_temperature(void) {
    if (i2c_handle < 0) return -1;
    uint16_t config = ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128;
    char cfg[3];
    cfg[0] = ADS1115_REG_CONFIG;
    cfg[1] = (config >> 8) & 0xFF;
    cfg[2] = config & 0xFF;
    if (i2cWriteI2CBlockData(i2c_handle, ADS1115_REG_CONFIG, cfg + 1, 2) < 0) {
