    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];

    /* Sensor-absent / bus-error heuristics */
    if (value == 0 || value == ADC_MAX) {
        fprintf(stderr, "Warning: ADC saturated (0x%03X) — sensor absent or wiring fault\n", value);
    }

    *out_value = value;
    return 0;
}

/* ------------------------------- Logging --------------------------------- */
static int log_data(int adc_value)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, ADC: %d\n", ts, adc_value);
    fclose(fp);
    return 0;
}

/* ------------------------------- Fan GPIO -------------------------------- */
static int fan_init(void)
{
    g_chip = gpiod_chip_open_by_name(FAN_CHIP_NAME);
    if (!g_chip) {
        /* Try the fallback chip on older Pi models */
        g_chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        return -1;
    }

    g_fan = gpiod_chip_get_line(g_chip, FAN_GPIO_LINE);
    if (!g_fan) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", FAN_GPIO_LINE, strerror(errno));
        gpiod_chip_close(g_chip); g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_fan, FAN_CONSUMER, 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        g_fan = NULL; /* not acquired */
        gpiod_chip_close(g_chip); g_chip = NULL;
        return -1;
    }

    return 0;
}

static void fan_set(int on)
{
    if (g_fan) {
        if (gpiod_line_set_value(g_fan, on ? 1 : 0) < 0) {
            fprintf(stderr, "gpiod_line_set_value: %s\n", strerror(errno));
        }
    }
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    /* Ensure fan is off before releasing resources */
    if (g_fan) {
        gpiod_line_set_value(g_fan, 0);
        gpiod_line_release(g_fan);
        g_fan = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    if (fan_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = 0;

        if (read_adc(ADC_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "ADC read failed; continuing\n");
        } else {
            if (log_data(adc_value) < 0) {
                fprintf(stderr, "Logging failed\n");
            }

            fan_set(adc_value > CURRENT_THRESHOLD ? 1 : 0);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    cleanup();
    printf("Current monitoring stopped.\n");
    return EXIT_SUCCESS;
}

