#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL 5

/* Calibration parameters (replace with actual sensor calibration data) */
#define R0 10000.0
#define A 0.0001
#define B 0.01
#define C 0.5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read 16-bit raw ADC value from the sensor via I2C */
static int read_raw_co(int handle, int *raw_out) {
    char buf[2];
    int bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        return -1;
    }
    *raw_out = ((buf[0] << 8) | buf[1]) & 0xFFFF;
    return 0;
}

/* Convert raw ADC value to CO concentration in ppm using a logarithmic curve */
static float calculate_co_ppm(int raw) {
    if (raw <= 0) {
        return 0.0f;
    }
    float resistance = R0 * (1023.0f / (float)raw - 1.0f);
    if (resistance <= 0.0f) {
        return 0.0f;
    }
    float ppm = A * powf(resistance, 2) + B * resistance + C;
    if (ppm < 0.0f) {
        ppm = 0.0f;
    }
    return ppm;
}

/* Log CO concentration to file with timestamp */
static int log_co_data(float co_ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s, %.2f ppm\n", timestamp, co_ppm);
    fclose(fp);
    return 0;
}

int main(void) {
    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C connection to the sensor */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection to 0x%02X: %d\n", I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("CO sensor monitoring started. Logging to %s every %d seconds.\n", LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        int raw_co = 0;

        if (read_raw_co(i2c_handle, &raw_co) != 0) {
            fprintf(stderr, "Error reading CO sensor data (I2C read failure). Retrying in %d seconds.\n", SAMPLE_INTERVAL);
        } else {
            float co_ppm = calculate_co_ppm(raw_co);

            if (log_co_data(co_ppm) != 0) {
                fprintf(stderr, "Error logging CO data.\n");
            } else {
                printf("CO: %.2f ppm (raw: %d)\n", co_ppm, raw_co);
            }
        }

        /* Sleep for the sample interval, checking running flag every second */
        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    /* Clean up resources on exit */
    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

