#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>
#include <sys/socket.h>
#include <sys/un.h>
#include <sys/stat.h>

#define FLAME_SENSOR_GPIO 4
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define LOG_FILE "flame_data.csv"
#define ERROR_LOG_FILE "error.log"
#define UNIX_SOCKET_PATH "/tmp/flame_socket"

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static int gpio_fd = -1;
static int server_fd = -1;
static FILE *log_file = NULL;
static FILE *error_log_file = NULL;

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (error_log_file) {
        fprintf(error_log_file, "%s: %s (errno: %d - %s)\n", timestamp, message, errno, strerror(errno));
        fflush(error_log_file);
    }
    fprintf(stderr, "%s: %s (errno: %d - %s)\n", timestamp, message, errno, strerror(errno));
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_error("Invalid MCP3008 channel");
        return -1;
    }
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        log_error("SPI transfer failed");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int read_flame_sensor(void) {
    uint32_t val = 0;
    for (int i = 0; i < 10; i++) {
        uint32_t v = 0;
        if (ioctl(gpio_fd, GPIO_GET_LINE_VALUE, &FLAME_SENSOR_GPIO) < 0) {
            log_error("Failed to read flame sensor GPIO");
            return -1;
        }
        val += v;
        usleep(1000);
    }
    return (val > 0) ? 1 : 0;
}

static void log_data(int flame_detected, int temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (log_file) {
        fprintf(log_file, "%s,%d,%d\n", timestamp, flame_detected, temperature);
        fflush(log_file);
    }
}

static void send_data_to_server(int flame_detected, int temperature) {
    if (server_fd < 0) return;
    char buffer[64];
    int len = snprintf(buffer, sizeof(buffer), "%d,%d\n", flame_detected, temperature);
    if (len > 0) {
        if (send(server_fd, buffer, len, 0) < 0) {
            log_error("Failed to send data to server");
        }
    }
}

static void cleanup(void) {
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (gpio_fd >= 0) {
        close(gpio_fd);
        gpio_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (error_log_file) {
        fclose(error_log_file);
        error_log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (!error_log_file) {
        perror("fopen error log");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file");
        cleanup();
        return 1;
    }

    gpio_fd = open("/dev/gpiochip0", 0);
    if (gpio_fd < 0) {
        log_error("Failed to open /dev/gpiochip0");
        cleanup();
        return 1;
    }

    struct gpiohandle_request gpio_req;
    memset(&gpio_req, 0, sizeof(gpio_req));
    gpio_req.lineoffsets[0] = FLAME_SENSOR_GPIO;
    gpio_req.lineflags[0] = GPIOHANDLE_REQUEST_INPUT;
    gpio_req.flags = 0;
    strncpy(gpio_req.consumer_label, "flame_sensor", sizeof(gpio_req.consumer_label) - 1);
    if (ioctl(gpio_fd, GPIO_GET_LINEHANDLE_IOCTL, &gpio_req) < 0) {
        log_error("Failed to get GPIO line handle");
        cleanup();
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        log_error("Failed to open SPI device");
        cleanup();
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        log_error("Failed to set SPI mode");
        cleanup();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        log_error("Failed to set SPI bits per word");
        cleanup();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        log_error("Failed to set SPI speed");
        cleanup();
        return 1;
    }

    struct sockaddr_un addr;
    memset(&addr, 0, sizeof(addr));
    addr.sun_family = AF_UNIX;
    strncpy(addr.sun_path, UNIX_SOCKET_PATH, sizeof(addr.sun_path) - 1);
    unlink(UNIX_SOCKET_PATH);
    server_fd = socket(AF_UNIX, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_error("Failed to create socket");
        cleanup();
        return 1;
    }
    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        log_error("Failed to bind socket");
        cleanup();
        return 1;
    }
    if (listen(server_fd, 5) < 0) {
        log_error("Failed to listen on socket");
        cleanup();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int flame_detected = read_flame_sensor();
        if (flame_detected < 0) {
            log_error("Failed to read flame sensor");
            sleep(1);
            continue;
        }
        int temperature = read_mcp3008(MCP3008_CHANNEL);
        if (temperature < 0) {
            log_error("Failed to read temperature sensor");
            sleep(1);
            continue;
        }
        log_data(flame_detected, temperature);
        send_data_to_server(flame_detected, temperature);
        sleep(1);
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

