#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x45
#define CO_NO2_REG 0x00
#define CO_ALERT_THRESHOLD 25.0
#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mics4514(int handle, uint16_t *ox, uint16_t *red) {
    char buf[4];
    int bytes = i2cReadI2CBlockData(handle, CO_NO2_REG, buf, 4);
    if (bytes != 4) {
        fprintf(stderr, "Error reading I2C block data: %d\n", bytes);
        return -1;
    }
    *ox = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint16_t)(buf[1] & 0xFF);
    *red = ((uint16_t)(buf[2] & 0xFF) << 8) | (uint16_t)(buf[3] & 0xFF);
    return 0;
}

static float calculate_co_ppm(uint16_t ox) {
    return (float)ox * 0.1f;
}

static int log_data(const char *filename, float co_ppm) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, CO: %.2f ppm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    fclose(fp);
    return 0;
}

static int log_alert(float co_ppm) {
    FILE *fp = fopen(ALERT_FILE, "a");
    if (!fp) {
        perror("Error opening alert log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, ALERT: CO concentration exceeded threshold (%.2f ppm)\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("MICS-4514 CO/NO2 sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t ox = 0, red = 0;
        if (read_mics4514(i2c_handle, &ox, &red) == 0) {
            float co_ppm = calculate_co_ppm(ox);
            printf("CO: %.2f ppm, NO2: %.2f ppm\n", co_ppm, (float)red * 0.1f);

            if (log_data(LOG_FILE, co_ppm) != 0) {
                fprintf(stderr, "Error logging data to file.\n");
            }

            if (co_ppm > CO_ALERT_THRESHOLD) {
                if (log_alert(co_ppm) != 0) {
                    fprintf(stderr, "Error logging alert to file.\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

