    gpioSetMode(GPIO_SDA, PI_ALT0);
    gpioSetMode(GPIO_SCL, PI_ALT0);

    i2c_handle_1 = i2cOpen(I2C_BUS, I2C_ADDR_1, 0);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Failed to open I2C device 1 (addr 0x%02X): %d\n", I2C_ADDR_1, i2c_handle_1);
        gpioTerminate();
