    result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read error on handle %d: %d\n", handle, result);
        return ERROR_VALUE;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
