        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_i2c() != 0) {
        return 1;
    }

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float level1 = read_sound_level(i2c_handle_1);
        float level2 = read_sound_level(i2c_handle_2);

        float avg = calculate_average(level1, level2);
        log_data(avg);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    printf("Audio monitoring stopped.\n");
    return 0;
}

