#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define SPI_CHANNEL_0 0
#define SPI_CHANNEL_1 1
#define SPI_SPEED 1000000
#define SPI_FLAGS 0

#define LED_GPIO 27
#define SAMPLE_RATE 1000
#define WINDOW_SIZE_MS 100
#define WINDOW_SIZE_SAMPLES (SAMPLE_RATE * WINDOW_SIZE_MS / 1000)
#define HIGH_LEVEL_THRESHOLD 1000.0
#define LED_ON_DURATION_MS 500

static volatile sig_atomic_t running = 1;
static int spi_handle_0 = -1;
static int spi_handle_1 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on handle %d\n", spi_handle);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static double calculate_rms(const int *samples, int num_samples) {
    double sum_sq = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double v = (double)samples[i];
        sum_sq += v * v;
    }
    return sqrt(sum_sq / num_samples);
}

