/*
 * Raspberry Pi 4 Model B – MLX91204 Hall-effect current sensor monitor
 *
 * Hardware:
 *   - ADS1115 ADC on I2C bus 1 (SDA=GPIO2, SCL=GPIO3, ADDR->GND)
 *   - MLX91204 analog output wired to ADS1115 A0
 *   - Warning LED on GPIO17 (BCM)
 *
 * Build:  gcc -O2 -Wall -o current_monitor current_monitor.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48

#define ADS1115_REG_CONVERSION  0x00
#define ADS1115_REG_CONFIG      0x01

/* Config: single-shot, A0 single-ended, PGA ±4.096 V, 128 SPS, no comp */
#define ADS1115_CFG_BASE        0x8000  /* OS bit */
#define ADS1115_CFG_MUX_A0      0x4000  /* MUX[14:12] = 100 */
#define ADS1115_CFG_PGA_4096   0x0200  /* PGA[11:9] = 001 */
#define ADS1115_CFG_MODE_SS    0x0100  /* MODE[8] = 1 */
#define ADS1115_CFG_DR_128     0x0080  /* DR[7:5] = 100 */
#define ADS1115_CFG_CQUE_NONE  0x0003  /* COMP_QUE[1:0] = 11 (disable) */

#define LED_PIN        17
#define BUFFER_SIZE    100
#define SAMPLE_HZ      10
#define SAMPLE_US      (1000000 / SAMPLE_HZ)
#define CURRENT_THRESHOLD 50.0f

/* ADS1115 PGA ±4.096 V -> 1 bit = 125 µV */
#define ADS1115_PGA_4096_LSB_UV 125.0f

/* MLX91204: 100 mV/A sensitivity, 0.0 V offset */
#define MLX91204_SENSITIVITY 0.1f
#define MLX91204_OFFSET     0.0f

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit value to an ADS1115 register */
static int ads1115_write_reg(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit value from an ADS1115 register */
static int ads1115_read_reg(int fd, uint8_t reg, uint16_t *val)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* Trigger a single-shot conversion and read the raw result */
static int ads1115_read_raw(int fd, int16_t *raw)
{
    uint16_t cfg = ADS1115_CFG_BASE | ADS1115_CFG_MUX_A0 |
                   ADS1115_CFG_PGA_4096 | ADS1115_CFG_MODE_SS |
                   ADS1115_CFG_DR_128 | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg(fd, ADS1115_REG_CONFIG, cfg) < 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);

    uint16_t val;
    if (ads1115_read_reg(fd, ADS1115_REG_CONVERSION, &val) < 0)
        return -1;

    *raw = (int16_t)val;
    return 0;
}

/* Convert raw ADC value to current (A) */
static float raw_to_current(int16_t raw)
{
    float voltage = (float)raw * ADS1115_PGA_4096_LSB_UV / 1000000.0f;
    return (voltage - MLX91204_OFFSET) / MLX91204_SENSITIVITY;
}

int main(void)
{
    int i2c_fd = -1;
    int led_fd = -1;
    int ret = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus and claim ADS1115 --- */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Verify ADS1115 is present by reading the config register */
    uint16_t cfg_check;
    if (ads1115_read_reg(i2c_fd, ADS1115_REG_CONFIG, &cfg_check) < 0) {
        fprintf(stderr, "ADS1115 not responding on 0x%02X – check wiring.\n",
                ADS1115_ADDR);
        goto cleanup;
    }

    /* --- Open GPIO for LED (sysfs) --- */
    led_fd = open("/sys/class/gpio/export", O_WRONLY);
    if (led_fd < 0) {
        if (errno != EBUSY) {
            fprintf(stderr, "Cannot open /sys/class/gpio/export: %s\n",
                    strerror(errno));
            goto cleanup;
        }
        /* Already exported – try opening the value file directly */
        led_fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
        if (led_fd < 0) {
            fprintf(stderr, "Cannot open LED GPIO 17: %s\n", strerror(errno));
            goto cleanup;
        }
    } else {
        char pin_str[4];
        snprintf(pin_str, sizeof(pin_str), "%d", LED_PIN);
        if (write(led_fd, pin_str, strlen(pin_str)) < 0) {
            fprintf(stderr, "Cannot export GPIO 17: %s\n", strerror(errno));
            close(led_fd);
            led_fd = -1;
            goto cleanup;
        }
        close(led_fd);
        led_fd = -1;

        /* Open the value file */
        led_fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
        if (led_fd < 0) {
            fprintf(stderr, "Cannot open LED GPIO 17 value: %s\n",
                    strerror(errno));
            goto cleanup;
        }

        /* Set direction to output */
        int dir_fd = open("/sys/class/gpio/gpio17/direction", O_WRONLY);
        if (dir_fd < 0) {
            fprintf(stderr, "Cannot open LED GPIO 17 direction: %s\n",
                    strerror(errno));
            goto cleanup;
        }
        if (write(dir_fd, "out", 3) < 0) {
            fprintf(stderr, "Cannot set LED GPIO 17 as output: %s\n",
                    strerror(errno));
            close(dir_fd);
            goto cleanup;
        }
        close(dir_fd);
    }

    /* --- Initialize circular buffer --- */
    float current_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_count = 0;

    printf("Monitoring current (A) on ADS1115 A0. Threshold: %.1f A. Press Ctrl+C to exit.\n",
           CURRENT_THRESHOLD);

    /* --- Main sampling loop --- */
    while (g_running) {
        int16_t raw;
        if (ads1115_read_raw(i2c_fd, &raw) < 0) {
            fprintf(stderr, "ADC read error – continuing.\n");
            usleep(SAMPLE_US);
            continue;
        }

        float current = raw_to_current(raw);

        /* Store in circular buffer */
        current_buffer[buffer_index] = current;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        if (buffer_count < BUFFER_SIZE)
            buffer_count++;

        /* Compute average */
        float average = 0.0f;
        for (int i = 0; i < buffer_count; i++)
            average += current_buffer[i];
        average /= (float)buffer_count;

        /* Threshold check */
        bool threshold_exceeded = (average > CURRENT_THRESHOLD);

        /* Drive LED */
        if (write(led_fd, threshold_exceeded ? "1" : "0", 1) < 0) {
            fprintf(stderr, "Warning LED write failed: %s\n", strerror(errno));
        }

        printf("Current: %.2f A | Avg: %.2f A | LED: %s\n",
               current, average, threshold_exceeded ? "ON" : "OFF");

        usleep(SAMPLE_US);
    }

    printf("\nShutting down gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Turn off LED */
    if (led_fd >= 0) {
        write(led_fd, "0", 1);
        close(led_fd);
    }

    /* Unexport GPIO */
    int unexport_fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (unexport_fd >= 0) {
        char pin_str[4];
        snprintf(pin_str, sizeof(pin_str), "%d", LED_PIN);
        write(unexport_fd, pin_str, strlen(pin_str));
        close(unexport_fd);
    }

    if (i2c_fd >= 0)
        close(i2c_fd);

    return ret;
}

