        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Verify ADS1115 is present by reading the config register */
    uint16_t cfg_check;
    if (ads1115_read_reg(i2c_fd, ADS1115_REG_CONFIG, &cfg_check) < 0) {
        fprintf(stderr, "ADS1115 not responding on 0x%02X – check wiring.\n",
                ADS1115_ADDR);
        goto cleanup;
    }

    /* --- Open GPIO for LED (sysfs) --- */
    led_fd = open("/sys/class/gpio/export", O_WRONLY);
    if (led_fd < 0) {
        if (errno != EBUSY) {
            fprintf(stderr, "Cannot open /sys/class/gpio/export: %s\n",
                    strerror(errno));
            goto cleanup;
        }
        /* Already exported – try opening the value file directly */
        led_fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
        if (led_fd < 0) {
            fprintf(stderr, "Cannot open LED GPIO 17: %s\n", strerror(errno));
            goto cleanup;
        }
    } else {
        char pin_str[4];
        snprintf(pin_str, sizeof(pin_str), "%d", LED_PIN);
        if (write(led_fd, pin_str, strlen(pin_str)) < 0) {
            fprintf(stderr, "Cannot export GPIO 17: %s\n", strerror(errno));
            close(led_fd);
            led_fd = -1;
            goto cleanup;
        }
        close(led_fd);
        led_fd = -1;

        /* Open the value file */
        led_fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
        if (led_fd < 0) {
            fprintf(stderr, "Cannot open LED GPIO 17 value: %s\n",
                    strerror(errno));
            goto cleanup;
        }

        /* Set direction to output */
        int dir_fd = open("/sys/class/gpio/gpio17/direction", O_WRONLY);
        if (dir_fd < 0) {
            fprintf(stderr, "Cannot open LED GPIO 17 direction: %s\n",
                    strerror(errno));
            goto cleanup;
        }
        if (write(dir_fd, "out", 3) < 0) {
            fprintf(stderr, "Cannot set LED GPIO 17 as output: %s\n",
                    strerror(errno));
            close(dir_fd);
            goto cleanup;
        }
        close(dir_fd);
    }

    /* --- Initialize circular buffer --- */
    float current_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_count = 0;

    printf("Monitoring current (A) on ADS1115 A0. Threshold: %.1f A. Press Ctrl+C to exit.\n",
           CURRENT_THRESHOLD);

    /* --- Main sampling loop --- */
    while (g_running) {
        int16_t raw;
        if (ads1115_read_raw(i2c_fd, &raw) < 0) {
            fprintf(stderr, "ADC read error – continuing.\n");
            usleep(SAMPLE_US);
            continue;
        }

        float current = raw_to_current(raw);

        /* Store in circular buffer */
        current_buffer[buffer_index] = current;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        if (buffer_count < BUFFER_SIZE)
            buffer_count++;

        /* Compute average */
        float average = 0.0f;
        for (int i = 0; i < buffer_count; i++)
            average += current_buffer[i];
        average /= (float)buffer_count;

        /* Threshold check */
        bool threshold_exceeded = (average > CURRENT_THRESHOLD);

        /* Drive LED */
        if (write(led_fd, threshold_exceeded ? "1" : "0", 1) < 0) {
            fprintf(stderr, "Warning LED write failed: %s\n", strerror(errno));
        }

        printf("Current: %.2f A | Avg: %.2f A | LED: %s\n",
               current, average, threshold_exceeded ? "ON" : "OFF");

        usleep(SAMPLE_US);
    }

    printf("\nShutting down gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Turn off LED */
    if (led_fd >= 0) {
        write(led_fd, "0", 1);
        close(led_fd);
    }

    /* Unexport GPIO */
    int unexport_fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (unexport_fd >= 0) {
        char pin_str[4];
        snprintf(pin_str, sizeof(pin_str), "%d", LED_PIN);
        write(unexport_fd, pin_str, strlen(pin_str));
        close(unexport_fd);
    }

    if (i2c_fd >= 0)
        close(i2c_fd);

    return ret;
}

