#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#include "tcs34725.h"

#define I2C_BUS        1
#define I2C_ADDR       0x29
#define LOG_FILE       "color_log.csv"
#define POLL_INTERVAL  1.0
#define MAX_I2C_ERRORS 3

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int file_exists(const char *path)
{
    FILE *f = fopen(path, "r");
    if (f) {
        fclose(f);
        return 1;
    }
    return 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm);
    } else {
        snprintf(buf, len, "1970-01-01 00:00:00");
    }
}

int main(void)
{
    int i2c_handle = -1;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        goto cleanup_gpio;
    }

    if (tcs34725_init(i2c_handle) != 0) {
        fprintf(stderr, "TCS34725 initialization failed (ID mismatch or bus error)\n");
        goto cleanup_i2c;
    }

    if (!file_exists(LOG_FILE)) {
        fp = fopen(LOG_FILE, "w");
        if (!fp) {
            fprintf(stderr, "Error creating log file '%s': %s\n",
                    LOG_FILE, strerror(errno));
            goto cleanup_i2c;
        }
        fprintf(fp, "timestamp,clear,red,green,blue\n");
        fflush(fp);
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        goto cleanup_i2c;
    }

    int consecutive_errors = 0;

    while (g_running) {
        unsigned int clear, red, green, blue;

        if (tcs34725_read(i2c_handle, &clear, &red, &green, &blue) == 0) {
            consecutive_errors = 0;

            char ts[32];
            get_timestamp(ts, sizeof(ts));

            if (fprintf(fp, "%s,%u,%u,%u,%u\n", ts, clear, red, green, blue) < 0) {
                fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            } else {
                fflush(fp);
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Warning: I2C read error (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_I2C_ERRORS) {
                fprintf(stderr, "Too many consecutive I2C errors, exiting.\n");
                break;
            }
        }

        time_sleep(POLL_INTERVAL);
    }

    ret = EXIT_SUCCESS;

    if (fp) {
        fflush(fp);
        fclose(fp);
    }

cleanup_i2c:
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

cleanup_gpio:
    gpioTerminate();
    return ret;
}

