/*
 * MLX90817 absolute pressure sensor logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   MLX90817 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   MLX90817 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   MLX90817 VDD  -> 3.3 V
 *   MLX90817 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90817_log mlx90817_log.c -lpigpio -lrt
 * Run:    sudo ./mlx90817_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- MLX90817 constants (datasheet) ---- */
#define MLX90817_ADDR        0x24          /* 7-bit I2C address (ADDR pin tied to GND) */
#define MLX90817_REG_PRESS   0x00          /* Pressure data register (16-bit, big-endian) */
#define MLX90817_REG_TEMP    0x02          /* Temperature data register (16-bit, big-endian) */
#define MLX90817_REG_ID      0x0C          /* Device ID register (16-bit, big-endian) */
#define MLX90817_ID_EXPECTED 0x0100        /* Expected device ID for MLX90817 */

/* ---- Application constants ---- */
#define I2C_BUS              1
#define LOG_FILE             "pressure_log.csv"
#define SAMPLE_PERIOD_US     1000000       /* 1 second */
#define MAX_CONSECUTIVE_ERRS 10            /* abort after this many consecutive I2C failures */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;            /* let main loop exit cleanly */
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian register from the MLX90817.
 * Returns 0 on success and stores the value in *out; -1 on error.   */
static int read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cWriteByte(handle, reg) < 0) {
        fprintf(stderr, "[I2C] write reg 0x%02X failed (pigpio err %d)\n",
                reg, i2cWriteByte(handle, reg));
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed\n", reg);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Verify the sensor is present by reading the device ID register.    */
static int verify_sensor(int handle)
{
    uint16_t id;
    if (read_reg16(handle, MLX90817_REG_ID, &id) != 0) {
        fprintf(stderr, "[I2C] cannot read device ID register — sensor absent or bus error\n");
        return -1;
    }
    if (id != MLX90817_ID_EXPECTED) {
        fprintf(stderr, "[I2C] unexpected device ID 0x%04X (expected 0x%04X)\n",
                id, MLX90817_ID_EXPECTED);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw pressure to kPa (datasheet formula).                   */
static float raw_to_kPa(uint16_t raw)
{
    /* MLX90817: pressure = (raw / 65535.0) * 100.0 kPa */
    return ((float)raw / 65535.0f) * 100.0f;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[pigpio] initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, MLX90817_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[I2C] open failed on bus %d addr 0x%02X (pigpio err %d)\n",
                I2C_BUS, MLX90817_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor presence ---- */
    if (verify_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "[MLX90817] sensor not detected or not responding\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file (append mode) ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("[file] cannot open " LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp_utc,pressure_kPa\n");
        fflush(g_log_file);
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90817 logging started. Press Ctrl-C to stop.\n");

    /* ---- Main sampling loop ---- */
    int consecutive_errors = 0;

    while (g_running) {
        uint16_t raw_pressure;

        if (read_reg16(g_i2c_handle, MLX90817_REG_PRESS, &raw_pressure) != 0) {
            consecutive_errors++;
            fprintf(stderr, "[I2C] pressure read failed (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRS) {
                fprintf(stderr, "[I2C] too many consecutive failures — aborting\n");
                break;
            }
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        consecutive_errors = 0;

        float pressure_kPa = raw_to_kPa(raw_pressure);

        /* ---- Timestamp (ISO 8601 UTC) ---- */
        time_t now = time(NULL);
        struct tm tm_utc;
        gmtime_r(&now, &tm_utc);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

        /* ---- Log to CSV ---- */
        if (fprintf(g_log_file, "%s,%.2f\n", ts, pressure_kPa) < 0) {
            perror("[file] write failed");
            break;
        }
        if (fflush(g_log_file) != 0) {
            perror("[file] flush failed");
            break;
        }

        printf("%s  %.2f kPa\n", ts, pressure_kPa);

        gpioDelay(SAMPLE_PERIOD_US);   /* 1 s */
    }

    /* ---- Clean shutdown ---- */
    cleanup();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

