    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("[file] cannot open " LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp_utc,pressure_kPa\n");
        fflush(g_log_file);
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90817 logging started. Press Ctrl-C to stop.\n");

    /* ---- Main sampling loop ---- */
    int consecutive_errors = 0;

    while (g_running) {
        uint16_t raw_pressure;

        if (read_reg16(g_i2c_handle, MLX90817_REG_PRESS, &raw_pressure) != 0) {
            consecutive_errors++;
            fprintf(stderr, "[I2C] pressure read failed (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRS) {
                fprintf(stderr, "[I2C] too many consecutive failures — aborting\n");
                break;
            }
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        consecutive_errors = 0;

        float pressure_kPa = raw_to_kPa(raw_pressure);

        /* ---- Timestamp (ISO 8601 UTC) ---- */
        time_t now = time(NULL);
        struct tm tm_utc;
        gmtime_r(&now, &tm_utc);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

        /* ---- Log to CSV ---- */
        if (fprintf(g_log_file, "%s,%.2f\n", ts, pressure_kPa) < 0) {
            perror("[file] write failed");
            break;
        }
        if (fflush(g_log_file) != 0) {
            perror("[file] flush failed");
            break;
        }

        printf("%s  %.2f kPa\n", ts, pressure_kPa);

        gpioDelay(SAMPLE_PERIOD_US);   /* 1 s */
    }

    /* ---- Clean shutdown ---- */
    cleanup();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

