#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define ADS1115_ADDR   0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

#define ADS1115_CONFIG_OS      0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_MUX_AIN1 0x5000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080

#define LED_GPIO        17
#define PRESSURE_THRESHOLD 105.0f
#define MAX_RETRIES     3
#define SAMPLE_PERIOD_US 1000000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int16_t read_ads1115_channel(int handle, uint16_t mux) {
    uint16_t config = ADS1115_CONFIG_OS | mux | ADS1115_CONFIG_PGA_4_096V |
                      ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS;

    char cfg[3];
    cfg[0] = (char)ADS1115_REG_CONFIG;
    cfg[1] = (char)(config >> 8);
    cfg[2] = (char)(config & 0xFF);

    if (i2cWriteDevice(handle, cfg, 3) < 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config.\n");
        return -1;
    }

    for (int i = 0; i < 10; i++) {
        gpioDelay(10000);
        char reg = (char)ADS1115_REG_CONFIG;
        if (i2cWriteDevice(handle, &reg, 1) < 0) {
            fprintf(stderr, "Error: failed to set config pointer.\n");
            return -1;
        }
        char buf[2];
        if (i2cReadDevice(handle, buf, 2) == 2) {
            uint16_t val = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            if (val & ADS1115_CONFIG_OS) {
                return (int16_t)val;
            }
        }
    }

    fprintf(stderr, "Error: ADS1115 conversion timeout.\n");
    return -1;
}

static float convert_to_pressure(int16_t raw) {
    float voltage = (raw / 32767.0f) * 4.096f;
    return (voltage - 0.5f) * 100.0f;
}

static float convert_to_temperature(int16_t raw) {
    float voltage = (raw / 32767.0f) * 4.096f;
    return (voltage - 0.5f) * 100.0f;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at addr 0x%02X.\n", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    while (g_running) {
        int16_t raw_pressure = -1, raw_temp = -1;
        bool ok = false;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            raw_pressure = read_ads1115_channel(g_i2c_handle, ADS1115_CONFIG_MUX_AIN0);
            if (raw_pressure < 0) {
                gpioDelay(100000);
                continue;
            }
            raw_temp = read_ads1115_channel(g_i2c_handle, ADS1115_CONFIG_MUX_AIN1);
            if (raw_temp < 0) {
                gpioDelay(100000);
                continue;
            }
            ok = true;
            break;
        }

        if (!ok) {
            fprintf(stderr, "Error: sensor read failed after %d retries.\n", MAX_RETRIES);
            gpioWrite(LED_GPIO, 0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float pressure = convert_to_pressure(raw_pressure);
        float temperature = convert_to_temperature(raw_temp);

        printf("Pressure: %.2f kPa, Temperature: %.2f C\n", pressure, temperature);

        if (pressure > PRESSURE_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

