#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define ADC_CHANNEL    0
#define OVERCURRENT_THRESHOLD 10.0
#define SHUTDOWN_PIN   27
#define LOG_FILE       "current_log.txt"
#define SAMPLE_US      100000

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double adc_to_current(int adc_value)
{
    return (double)adc_value * 10.0 / 1023.0;
}

static void log_data(FILE *fp, double current)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, Current: %.2f A\n", ts, current) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
    }
}

static void shutdown_motor(void)
{
    if (gpioWrite(SHUTDOWN_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set shutdown pin HIGH\n");
    }
}

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioWrite(SHUTDOWN_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set shutdown pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(SHUTDOWN_PIN, 0);

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring motor current... (Ctrl+C to exit)\n");

    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, retrying...\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        double current = adc_to_current(adc_value);

        log_data(g_log_file, current);
        printf("Current: %.2f A\n", current);

        if (current > OVERCURRENT_THRESHOLD) {
            fprintf(stderr, "OVERCURRENT DETECTED! Shutting down motor.\n");
            log_data(g_log_file, current);
            shutdown_motor();
            break;
        }

        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

