    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("Error getting local time");
        fclose(fp);
        return;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f ppm\n", timestamp, ppm);
    fclose(fp);
}

static void check_threshold(float ppm) {
    if (ppm > THRESHOLD) {
        fprintf(stderr, "ALARM: Methane concentration exceeded threshold (%.2f ppm > %.0f ppm)\n", ppm, THRESHOLD);
    }
}

