            log_data(ppm);
            check_threshold(ppm);
        }
        gpioDelay(SAMPLE_US);
    }

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
    }
    gpioTerminate();
    printf("Methane monitoring stopped.\n");
    return 0;
}

