#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

/* ADS1115 I2C address (ADDR pin tied to GND) */
#define ADS1115_ADDR 0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config register bit masks */
#define ADS1115_CFG_OS_BEGIN   0x8000
#define ADS1115_CFG_MUX_AIN0   0x4000
#define ADS1115_CFG_PGA_4_096V 0x0200
#define ADS1115_CFG_MODE_CONT  0x0000
#define ADS1115_CFG_DR_128SPS  0x0080

/* MLX90830 pressure range (kPa) */
#define MIN_PRESSURE 0.0
#define MAX_PRESSURE 100.0

/* ADC full-scale range for PGA = +/-4.096 V */
#define ADC_FULL_SCALE 4.096

/* ADC resolution for 16-bit signed */
#define ADC_RESOLUTION 32768.0

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 1000000

/* Global flag for graceful shutdown */
static volatile sig_atomic_t program_running = 1;

/* Signal handler for SIGINT */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Write a 16-bit value to an ADS1115 register */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (i2cWriteDevice(handle, buf, 3) < 0) {
        return -1;
    }
    return 0;
}

/* Read a 16-bit value from an ADS1115 register */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) {
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* Initialize the ADS1115 for continuous conversion on AIN0 */
static int ads1115_init(int handle) {
    uint16_t config = ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_AIN0 |
                      ADS1115_CFG_PGA_4_096V | ADS1115_CFG_MODE_CONT |
                      ADS1115_CFG_DR_128SPS;
    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Error: Failed to write ADS1115 config register.\n");
        return -1;
    }
    return 0;
}

/* Read the raw ADC value from the ADS1115 */
static int ads1115_read_raw(int handle, int16_t *raw_value) {
    uint16_t value;
    if (ads1115_read_reg(handle, ADS1115_REG_CONVERSION, &value) < 0) {
        fprintf(stderr, "Error: Failed to read ADS1115 conversion register.\n");
        return -1;
    }
    *raw_value = (int16_t)value;
    return 0;
}

/* Convert raw ADC value to pressure (kPa) */
static float convert_to_pressure(int16_t raw_value) {
    float voltage = ((float)raw_value / ADC_RESOLUTION) * ADC_FULL_SCALE;
    float pressure = (voltage / 5.0) * 100.0;
    return pressure;
}

/* Validate pressure reading */
static int validate_pressure(float pressure) {
    if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
        fprintf(stderr, "Warning: Pressure reading out of range: %.2f kPa\n", pressure);
        return -1;
    }
    return 0;
}

/* Log pressure data to file */
static int log_pressure_data(float pressure) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open pressure_log.txt for writing.\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: Failed to get local time.\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f kPa\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

int main() {
    int i2c_handle = -1;
    int exit_code = 1;

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to register signal handler.\n");
        return 1;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    /* Open I2C bus 1 at ADS1115 address */
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X.\n", ADS1115_ADDR);
        goto cleanup_gpio;
    }

    /* Initialize ADS1115 */
    if (ads1115_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: ADS1115 initialization failed.\n");
        goto cleanup_i2c;
    }

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (program_running) {
        int16_t raw_value;
        float pressure;

        /* Read raw ADC value */
        if (ads1115_read_raw(i2c_handle, &raw_value) < 0) {
            fprintf(stderr, "Error: Failed to read ADC value.\n");
            goto cleanup_i2c;
        }

        /* Convert to pressure */
        pressure = convert_to_pressure(raw_value);

        /* Validate pressure reading */
        if (validate_pressure(pressure) < 0) {
            fprintf(stderr, "Error: Invalid pressure reading.\n");
            goto cleanup_i2c;
        }

        /* Log pressure data */
        if (log_pressure_data(pressure) < 0) {
            fprintf(stderr, "Error: Failed to log pressure data.\n");
            goto cleanup_i2c;
        }

        /* Print pressure reading to console */
        printf("Pressure: %.2f kPa\n", pressure);

        /* Wait for 1 second */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nPressure monitoring stopped.\n");
    exit_code = 0;

cleanup_i2c:
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

cleanup_gpio:
    gpioTerminate();
    return exit_code;
}

