#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0

#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com"

#define ADC_CHANNEL_HUMIDITY 0
#define ADC_CHANNEL_TEMPERATURE 1

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    int bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float convert_to_humidity(int adc_value) {
    float voltage = (float)adc_value * 3.3 / 4095.0;
    float humidity = (voltage - 0.16) / 0.0062;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

static float convert_to_temperature(int adc_value) {
    float voltage = (float)adc_value * 3.3 / 4095.0;
    float temperature = (voltage - 0.5) / 0.01;
    return temperature;
}

static int log_data(float humidity, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        perror("Failed to get local time");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            return -1;
        }
    }

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature) < 0) {
        perror("Failed to write to log file");
        return -1;
    }

    if (fflush(log_file) != 0) {
        perror("Failed to flush log file");
        return -1;
    }

    return 0;
}

static int send_email_alert(float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    char command[512];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        perror("Failed to get local time");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(command, sizeof(command),
             "echo \"Subject: Humidity Alert\n\nHumidity exceeded threshold: %.2f%% at %s\" | ssmtp %s",
             humidity, timestamp, EMAIL_RECIPIENT);

    int result = system(command);
    if (result == -1) {
        perror("Failed to execute ssmtp command");
        return -1;
    } else if (WIFEXITED(result) && WEXITSTATUS(result) != 0) {
        fprintf(stderr, "ssmtp exited with status %d\n", WEXITSTATUS(result));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_humidity = read_adc(ADC_CHANNEL_HUMIDITY);
        if (adc_humidity < 0) {
            fprintf(stderr, "Failed to read humidity ADC value\n");
            sleep(5);
            continue;
        }

        int adc_temperature = read_adc(ADC_CHANNEL_TEMPERATURE);
        if (adc_temperature < 0) {
            fprintf(stderr, "Failed to read temperature ADC value\n");
            sleep(5);
            continue;
        }

        float humidity = convert_to_humidity(adc_humidity);
        float temperature = convert_to_temperature(adc_temperature);

        if (log_data(humidity, temperature) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        if (humidity > HUMIDITY_THRESHOLD) {
            if (send_email_alert(humidity) < 0) {
                fprintf(stderr, "Failed to send email alert\n");
            }
        }

        sleep(5);
    }

    cleanup();
    printf("Humidity monitoring stopped.\n");
    return 0;
}

