/*
 * TMP36 temperature logger via MCP3208 ADC on Raspberry Pi 5.
 *
 * Wiring:
 *   MCP3208 VDD  -> 3.3 V (pin 1)
 *   MCP3208 VREF -> 3.3 V (pin 1)
 *   MCP3208 AGND -> GND
 *   MCP3208 DGND -> GND
 *   MCP3208 CLK  -> GPIO11 (BCM 11, SPI0 SCLK)
 *   MCP3208 DOUT -> GPIO9  (BCM 9,  SPI0 MISO)
 *   MCP3208 DIN  -> GPIO10 (BCM 10, SPI0 MOSI)
 *   MCP3208 CS   -> GPIO8  (BCM 8,  SPI0 CE0)
 *   MCP3208 CH0  -> TMP36 VOUT
 *   TMP36 VCC    -> 3.3 V
 *   TMP36 GND    -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o tmp36_logger tmp36_logger.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define GPIO_CHIP       "gpiochip4"   /* RP1 GPIO controller on Pi 5 */
#define GPIO_CS         8            /* BCM 8 = SPI0 CE0 */

#define ADC_CHANNEL     0            /* MCP3208 CH0 */
#define ADC_MAX         4095         /* 12-bit */
#define ADC_VREF        3.3f         /* VDD = VREF = 3.3 V */

#define TMP36_OFFSET    0.5f         /* 500 mV at 0 °C */
#define TMP36_SLOPE     10.0f        /* 10 mV/°C */

#define LOG_FILE        "temperature_log.csv"
#define SAMPLE_PERIOD_S 1            /* 1 Hz */
#define MIN_TEMP_C      (-40.0f)
#define MAX_TEMP_C      125.0f

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * MCP3208 single-ended read (3-byte transfer, mode 0, MSB-first).
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padding)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *   rx[1] bits 1..0  + rx[2] bits 7..0  -> 12-bit result
 */
static int mcp3208_read(int spi_fd, struct gpiod_line *cs_line, int channel,
                        int *adc_out)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    /* Assert CS (active low) */
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("gpiod_line_set_value(0)");
        return -1;
    }

    /* Full-duplex transfer */
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        gpiod_line_set_value(cs_line, 1); /* release CS on error */
        return -1;
    }

    /* Deassert CS */
    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("gpiod_line_set_value(1)");
        return -1;
    }

    int raw = ((rx[1] & 0x03) << 8) | rx[2];
    *adc_out = raw;
    return 0;
}

static float adc_to_celsius(int adc)
{
    float voltage = (float)adc * (ADC_VREF / (float)ADC_MAX);
    return (voltage - TMP36_OFFSET) / TMP36_SLOPE;
}

static int log_temperature(FILE *fp, float temp_c)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, temp_c) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

int main(void)
{
    int spi_fd = -1;
    FILE *log_fp = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() < 0) {
        goto cleanup;
    }

    /* --- Open SPI device --- */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        goto cleanup;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        goto cleanup;
    }

    /* --- Open GPIO chip and request CS line --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name(" GPIO_CHIP ")");
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, GPIO_CS);
    if (!cs_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "mcp3208-cs", 1) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    /* --- Open log file (append); write header if empty --- */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

    long pos = ftell(log_fp);
    if (pos == 0) {
        if (fprintf(log_fp, "timestamp,temperature_celsius\n") < 0) {
            perror("fprintf(header)");
            goto cleanup;
        }
        fflush(log_fp);
    }

    printf("TMP36 logger started. Logging to %s at 1 Hz. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc = 0;
        if (mcp3208_read(spi_fd, cs_line, ADC_CHANNEL, &adc) < 0) {
            fprintf(stderr, "SPI transfer failed; retrying next cycle.\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        float temp_c = adc_to_celsius(adc);

        if (temp_c < MIN_TEMP_C || temp_c > MAX_TEMP_C) {
            fprintf(stderr,
                    "Warning: temperature %.2f C out of range [%.0f, %.0f] - "
                    "sensor absent or wiring fault?\n",
                    temp_c, MIN_TEMP_C, MAX_TEMP_C);
        }

        if (log_temperature(log_fp, temp_c) < 0) {
            fprintf(stderr, "Failed to log temperature.\n");
        }

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp) {
        fclose(log_fp);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return ret;
}

