/*
 * Si1172-A30-GMR Optical Heart Rate Sensor reader for Raspberry Pi Zero W
 *
 * NOTE: The Si1172-A30-GMR is a proprietary Silicon Labs sensor that
 * requires a closed-source algorithm to convert raw PPG samples into
 * true Heart Rate (bpm) and SpO2 (%).  This program reads the raw
 * 16-bit IR and RED ADC values as proxy values and logs them to
 * biometric_log.csv.  The raw values are returned as HR and SpO2
 * placeholders; real HR/SpO2 computation must be done by the sensor
 * firmware or a Silicon Labs reference implementation.
 *
 * Wiring:
 *   Si1172 SDA  -> GPIO2 (I2C1 SDA, pin 3)
 *   Si1172 SCL  -> GPIO3 (I2C1 SCL, pin 5)
 *   Si1172 VDD  -> 3.3 V
 *   Si1172 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si1172_logger si1172_logger.c -lpigpio -lrt
 *   (pigpio must be installed; run as root or with appropriate permissions.)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si1172-A30-GMR I2C address ---- */
#define SI1172_I2C_ADDR 0x53

/* ---- Register addresses (Si1172-A30-GMR) ---- */
#define SI1172_REG_PART_ID      0x00
#define SI1172_REG_HW_REV       0x01
#define SI1172_REG_SEQ_ID       0x02
#define SI1172_REG_INT_CFG      0x03
#define SI1172_REG_INT_STATUS   0x04
#define SI1172_REG_IRQ_ENABLE   0x05
#define SI1172_REG_IRQ_STATUS   0x06
#define SI1172_REG_HW_KEY       0x07
#define SI1172_REG_MEAS_RATE    0x08
#define SI1172_REG_ALS_RATE     0x09
#define SI1172_REG_PS_RATE      0x0A
#define SI1172_REG_PS_LED21     0x0B
#define SI1172_REG_PS_LED3      0x0C
#define SI1172_REG_PS1_ADCMUX   0x0D
#define SI1172_REG_PS2_ADCMUX   0x0E
#define SI1172_REG_PS3_ADCMUX   0x0F
#define SI1172_REG_PS1_DATA0    0x10
#define SI1172_REG_PS1_DATA1    0x11
#define SI1172_REG_PS2_DATA0    0x12
#define SI1172_REG_PS2_DATA1    0x13
#define SI1172_REG_PS3_DATA0    0x14
#define SI1172_REG_PS3_DATA1    0x15
#define SI1172_REG_ALS_DATA0    0x16
#define SI1172_REG_ALS_DATA1    0x17
#define SI1172_REG_ALS_DATA2    0x18
#define SI1172_REG_ALS_DATA3    0x19
#define SI1172_REG_COMMAND      0x18  /* write-only command register */

/* ---- Command codes ---- */
#define SI1172_CMD_RESET        0x01
#define SI1172_CMD_ALS_FORCE    0x06
#define SI1172_CMD_PS_FORCE     0x07
#define SI1172_CMD_PS_AUTO      0x0F

/* ---- Expected part ID ---- */
#define SI1172_PART_ID_EXPECTED 0x72

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                                */
/* ------------------------------------------------------------------ */

/*
 * Write a single byte to a register.
 * Returns 0 on success, -1 on failure.
 */
static int si1172_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[I2C] write reg 0x%02X val 0x%02X failed (rc=%d)\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from a register.
 * Returns 0 on success and stores the value in *out, -1 on failure.
 */
static int si1172_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed (rc=%d)\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/*
 * Read a 16-bit little-endian register pair.
 * Returns 0 on success and stores the value in *out, -1 on failure.
 */
static int si1172_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[I2C] read reg16 0x%02X failed (rc=%d)\n", reg, rc);
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor driver                                                        */
/* ------------------------------------------------------------------ */

/*
 * Probe the sensor to confirm it is present and initialized.
 * Returns 0 on success, -1 on failure.
 */
static int si1172_probe(int handle)
{
    uint8_t part_id = 0;

    /* Read PART_ID to verify the sensor is responding. */
    if (si1172_read_reg(handle, SI1172_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "[Si1172] Cannot read PART_ID - sensor absent or bus error\n");
        return -1;
    }

    if (part_id != SI1172_PART_ID_EXPECTED) {
        fprintf(stderr, "[Si1172] Unexpected PART_ID 0x%02X (expected 0x%02X)\n",
                part_id, SI1172_PART_ID_EXPECTED);
        return -1;
    }

    printf("[Si1172] PART_ID = 0x%02X, HW_REV = 0x%02X, SEQ_ID = 0x%02X\n",
           part_id,
           (uint8_t)i2cReadByteData(handle, SI1172_REG_HW_REV),
           (uint8_t)i2cReadByteData(handle, SI1172_REG_SEQ_ID));

    return 0;
}

