    if (si1172_write_reg(handle, SI1172_REG_COMMAND, SI1172_CMD_RESET) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    /* 2. Write HW_KEY to enable the device */
    if (si1172_write_reg(handle, SI1172_REG_HW_KEY, 0x00) != 0)
        return -1;

    /* 3. Configure LED currents for PS1 (IR) and PS2 (RED) */
    if (si1172_write_reg(handle, SI1172_REG_PS_LED21, 0x0F) != 0) /* ~6.4 mA */
        return -1;
    if (si1172_write_reg(handle, SI1172_REG_PS_LED3, 0x0F) != 0)   /* ~6.4 mA */
        return -1;

    /* 4. Set ADC mux: PS1 = IR, PS2 = RED, PS3 = unused */
    if (si1172_write_reg(handle, SI1172_REG_PS1_ADCMUX, 0x03) != 0) /* IR  */
        return -1;
    if (si1172_write_reg(handle, SI1172_REG_PS2_ADCMUX, 0x02) != 0) /* RED */
        return -1;
    if (si1172_write_reg(handle, SI1172_REG_PS3_ADCMUX, 0x00) != 0) /* disabled */
        return -1;

    /* 5. Set measurement rate (100 ms) */
    if (si1172_write_reg(handle, SI1172_REG_MEAS_RATE, 0x0A) != 0)
        return -1;

    /* 6. Start autonomous PS sampling */
    if (si1172_write_reg(handle, SI1172_REG_COMMAND, SI1172_CMD_PS_AUTO) != 0)
        return -1;

    gpioDelay(20000); /* 20 ms for first sample to be ready */
    return 0;
}

/*
 * Read the latest raw PPG samples.
 * NOTE: This returns the raw 16-bit ADC values as placeholders.
 * Real HR/SpO2 computation requires a proprietary Silicon Labs
 * algorithm and is NOT performed here.
 * Returns 0 on success, -1 on I2C failure.
 */
static int si1172_read_ppg(int handle, uint16_t *ir, uint16_t *red)
{
    if (si1172_read_reg16(handle, SI1172_REG_PS1_DATA0, ir) != 0)
        return -1;
    if (si1172_read_reg16(handle, SI1172_REG_PS2_DATA0, red) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                              */
/* ------------------------------------------------------------------ */
static void log_sample(FILE *fp, time_t ts, uint16_t hr, uint16_t spo2,
                       uint8_t err)
{
    fprintf(fp, "%ld,%u,%u,%u\n", (long)ts, hr, spo2, err);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at the Si1172 address ---- */
    g_i2c_handle = i2cOpen(1, SI1172_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (rc=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Probe sensor ---- */
    if (si1172_probe(g_i2c_handle) != 0) {
        fprintf(stderr, "Si1172 probe failed - sensor absent or not responding\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (si1172_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Si1172 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen("biometric_log.csv", "a");
    if (!g_log_file) {
        perror("fopen(biometric_log.csv)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,hr_bpm,spo2_pct,error_flag\n");
        fflush(g_log_file);
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si1172 logging started. Press Ctrl-C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        time_t now = time(NULL);
        uint16_t ir = 0, red = 0;
        uint8_t err = 0;

        if (si1172_read_ppg(g_i2c_handle, &ir, &red) != 0) {
            /* Transient I2C error: log with error flag 1 */
            fprintf(stderr, "[Si1172] PPG read failed\n");
            log_sample(g_log_file, now, 0, 0, 1);
        } else {
            /* NOTE: ir and red are raw ADC values, NOT true HR/SpO2.
             * Real computation requires a Silicon Labs algorithm. */
            log_sample(g_log_file, now, ir, red, 0);
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

