/*
 * Raspberry Pi Zero W – TDK ICP-10125 high-precision temperature & pressure logger.
 *
 * Wiring:
 *   ICP-10125 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   ICP-10125 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   ICP-10125 VDD  -> 3.3 V
 *   ICP-10125 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o icp10125_logger icp10125_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x60          /* ICP-10125 default 7-bit address */
#define CSV_FILE       "environmental_data.csv"
#define SAMPLE_PERIOD  5             /* seconds between samples */

/* ICP-10125 high-precision measurement command (0x3600) */
#define CMD_HP_MEAS_MSB 0x36
#define CMD_HP_MEAS_LSB 0x00

/* Raw ADC ranges for high-precision mode */
#define RAW_T_MIN  0x0000
#define RAW_T_MAX  0xFFFF
#define RAW_P_MIN  0x0000
#define RAW_P_MAX  0xFFFF

/* Calibration coefficients (example values – replace with your sensor's
 * calibrated constants from the datasheet or a calibration routine). */
static const float c0 =  0.0f;
static const float c1 =  0.0f;
static const float c00 = 0.0f;
static const float c10 = 0.0f;
static const float c01 = 0.0f;
static const float c11 = 0.0f;
static const float c20 = 0.0f;
static const float c21 = 0.0f;
static const float c30 = 0.0f;

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint8_t msb, uint8_t lsb)
{
    uint8_t buf[2] = { msb, lsb };
    ssize_t n = write(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X%02X): %s\n",
                msb, lsb, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_sensor(int fd, float *temperature, float *pressure)
{
    /* Issue high-precision measurement command */
    if (i2c_write_cmd(fd, CMD_HP_MEAS_MSB, CMD_HP_MEAS_LSB) != 0)
        return -1;

    /* Conversion time for high-precision mode is ~10 ms; wait 15 ms to be safe */
    usleep(15000);

    /* Read 6 bytes: pressure MSB, pressure LSB, temp MSB, temp LSB, CRC1, CRC2 */
    uint8_t data[6];
    if (i2c_read_bytes(fd, data, sizeof(data)) != 0)
        return -1;

    uint16_t raw_p = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_t = ((uint16_t)data[2] << 8) | data[3];

    /* Apply official ICP-10125 calibration formulas */
    float t = c0 * 0.5f + c1 * (float)raw_t;
    float p = c00 + c10 * (float)raw_p + c01 * (float)raw_t +
              c11 * (float)raw_p * (float)raw_t +
              c20 * (float)raw_p * (float)raw_p +
              c21 * (float)raw_p * (float)raw_p * (float)raw_t +
              c30 * (float)raw_p * (float)raw_p * (float)raw_p;

    *temperature = t;
    *pressure    = p;
    return 0;
}

/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float temperature, float pressure)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, pressure) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV log file in append mode */
    g_log_fp = fopen(CSV_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,temperature_c,pressure_pa\n");
        fflush(g_log_fp);
    }

    printf("ICP-10125 logger started. Logging to %s every %d s.\n",
           CSV_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature, pressure;

        if (read_sensor(g_i2c_fd, &temperature, &pressure) == 0) {
            if (log_data(g_log_fp, temperature, pressure) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            } else {
                printf("%s  T = %.2f °C  P = %.2f Pa\n",
                       "sample", temperature, pressure);
            }
        } else {
            fprintf(stderr, "Sensor read failed; will retry in %d s.\n",
                    SAMPLE_PERIOD);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

