#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        0
#define SPI_BITS        8

#define FLAME_CHANNEL   0
#define BUZZER_GPIO     18
#define LOG_FILE        "flame_log.txt"
#define TEMP_FILE       "ambient_temp.txt"
#define SAMPLE_DELAY_US 500000
#define MAX_RETRIES     3

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n",
                SPI_DEVICE, strerror(errno));
        return -1;
    }

    unsigned int mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    unsigned int bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_mcp3008(int fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float read_ambient_temperature(void)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s; using default 25.0 C\n",
                TEMP_FILE, strerror(errno));
        return 25.0f;
    }

    float temp = 25.0f;
    if (fscanf(fp, "%f", &temp) != 1) {
        fprintf(stderr, "Warning: invalid temperature in %s; using default 25.0 C\n",
                TEMP_FILE);
        temp = 25.0f;
    }
    fclose(fp);
    return temp;
}

static float compensate_voltage(int raw, float ambient_temp)
{
    float v = (float)raw * 3.3f / 1024.0f;
    float t = ambient_temp;
    if (t < 0.0f) t = 0.0f;
    if (t > 100.0f) t = 100.0f;
    return v * (1.0f + t * 0.001f);
}

static void log_data(FILE *fp, int raw, float voltage, float comp, float temp, int flame)
{
    time_t now = time(NULL);
    struct tm tmv;
    char ts[32];
    localtime_r(&now, &tmv);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
    fprintf(fp, "%s,%d,%.3f,%.3f,%.2f,%d\n", ts, raw, voltage, comp, temp, flame);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", BUZZER_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioWrite(BUZZER_GPIO, 0);

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_spi_fd);
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int raw = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && g_running) {
            raw = read_mcp3008(g_spi_fd, FLAME_CHANNEL);
            if (raw >= 0) break;
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "SPI read failed (attempt %d/%d), retrying...\n",
                        retries, MAX_RETRIES);
                usleep(100000);
            }
        }

        if (raw < 0) {
            fprintf(stderr, "SPI read failed after %d attempts; aborting iteration.\n",
                    MAX_RETRIES);
            gpioWrite(BUZZER_GPIO, 0);
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        if (raw < 0 || raw > 1023) {
            fprintf(stderr, "Invalid ADC value: %d\n", raw);
            gpioWrite(BUZZER_GPIO, 0);
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        float ambient = read_ambient_temperature();
        float voltage = (float)raw * 3.3f / 1024.0f;
        float comp    = compensate_voltage(raw, ambient);
        int flame     = (comp > 2.0f) ? 1 : 0;

        gpioWrite(BUZZER_GPIO, flame ? 1 : 0);
        log_data(g_log_fp, raw, voltage, comp, ambient, flame);

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

