#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define SPI_FLAGS      0
#define LED_PIN        17
#define WATER_THRESHOLD 75
#define DRY_THRESHOLD  70
#define SLEEP_INTERVAL 5
#define SAMPLE_DELAY   100000  /* microseconds (100 ms) */

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *json_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_water_level(int adc_value) {
    return (float)adc_value / 1023.0f * 100.0f;
}

static void log_water_level(float water_level) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(json_file, "{\"timestamp\": \"%s.%03ld\", \"water_level\": %.2f},\n",
            timestamp, ts.tv_nsec / 1000000, water_level);
    fflush(json_file);
}

static void control_led(float water_level) {
    if (water_level > WATER_THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else if (water_level < DRY_THRESHOLD) {
        gpioWrite(LED_PIN, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set LED pin mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    json_file = fopen("water_levels.json", "w");
    if (json_file == NULL) {
        fprintf(stderr, "Error: Failed to open water_levels.json for writing\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(json_file, "[\n");
    fflush(json_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        } else {
            float water_level = calculate_water_level(adc_value);
            log_water_level(water_level);
            control_led(water_level);
            printf("Water Level: %.2f%%\n", water_level);
        }

        for (int i = 0; i < SLEEP_INTERVAL * 10 && running; i++) {
            gpioDelay(SAMPLE_DELAY);
        }
    }

    fprintf(json_file, "\b\b]\n");
    fflush(json_file);
    fclose(json_file);
    spiClose(spi_handle);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

