#define MAX_CALIBRATION 800
#define MOISTURE_THRESHOLD 30
#define LOGGING_INTERVAL 60
#define EMAIL_RECIPIENT "recipient@example.com"
#define MSMTP_CONFIG_FILE "/etc/msmtprc"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_moisture_percentage(int adc_value, int min_calibration, int max_calibration) {
    if (max_calibration <= min_calibration) {
        fprintf(stderr, "Error: Invalid calibration values (max <= min)\n");
        return -1.0f;
    }
    return 100.0f - ((float)(adc_value - min_calibration) / (float)(max_calibration - min_calibration) * 100.0f);
}

static void log_data(float moisture_percentage) {
    FILE *fp = fopen("plant_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open plant_data.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage);
    fclose(fp);
}

static void send_email_alert(float moisture_percentage, const char *recipient, const char *msmtp_config) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error: localtime() failed in email alert\n");
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error: strftime() failed in email alert\n");
        return;
    }

    char command[512];
    int n = snprintf(command, sizeof(command),
        "msmtp -t -C %s <<EOF\nTo: %s\nSubject: Plant Moisture Alert\n\n"
        "Plant moisture level is critically low: %.2f%%\nTimestamp: %s\nEOF",
        msmtp_config, recipient, moisture_percentage, timestamp);
    if (n < 0 || (size_t)n >= sizeof(command)) {
        fprintf(stderr, "Error: Email command buffer too small\n");
        return;
    }

    FILE *fp = popen(command, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to execute msmtp via popen\n");
        return;
    }

    int status = pclose(fp);
    if (status == -1) {
        fprintf(stderr, "Error: pclose() failed\n");
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: msmtp exited with status %d\n", WEXITSTATUS(status));
    } else if (WIFSIGNALED(status)) {
        fprintf(stderr, "Error: msmtp killed by signal %d\n", WTERMSIG(status));
    }
}

int main(int argc, char *argv[]) {
    int spi_channel = SPI_CHANNEL;
    int adc_channel = ADC_CHANNEL;
    int min_calibration = MIN_CALIBRATION;
    int max_calibration = MAX_CALIBRATION;
    int moisture_threshold = MOISTURE_THRESHOLD;
    int logging_interval = LOGGING_INTERVAL;
    char email_recipient[256] = EMAIL_RECIPIENT;
    char msmtp_config[512] = MSMTP_CONFIG_FILE;

    if (argc > 1) spi_channel = atoi(argv[1]);
    if (argc > 2) adc_channel = atoi(argv[2]);
    if (argc > 3) min_calibration = atoi(argv[3]);
    if (argc > 4) max_calibration = atoi(argv[4]);
    if (argc > 5) moisture_threshold = atoi(argv[5]);
    if (argc > 6) logging_interval = atoi(argv[6]);
    if (argc > 7) strncpy(email_recipient, argv[7], sizeof(email_recipient) - 1);
    if (argc > 8) strncpy(msmtp_config, argv[8], sizeof(msmtp_config) - 1);

    email_recipient[sizeof(email_recipient) - 1] = '\0';
    msmtp_config[sizeof(msmtp_config) - 1] = '\0';

    if (logging_interval <= 0) {
        fprintf(stderr, "Error: Logging interval must be positive\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(spi_channel, 500000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Plant monitoring started. Press Ctrl+C to exit.\n");
    printf("SPI channel: %d, ADC channel: %d, Calibration: [%d, %d], Threshold: %d%%, Interval: %ds, Recipient: %s, MSMTP: %s\n",
           spi_channel, adc_channel, min_calibration, max_calibration, moisture_threshold, logging_interval, email_recipient, msmtp_config);

    while (running) {
        int adc_value = read_mcp3008(spi_handle, adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        } else {
            float moisture_percentage = calculate_moisture_percentage(adc_value, min_calibration, max_calibration);
            if (moisture_percentage < 0.0f) {
                fprintf(stderr, "Error: Invalid moisture percentage\n");
            } else {
                log_data(moisture_percentage);
                printf("Moisture: %.2f%%\n", moisture_percentage);

                if (moisture_percentage < moisture_threshold) {
                    send_email_alert(moisture_percentage, email_recipient, msmtp_config);
                }
            }
        }

        for (int i = 0; i < logging_interval && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Plant monitoring stopped.\n");
    return 0;
}

