/*
 * MLX90823 Pressure Sensor Reader via MCP3008 ADC on Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3V (Pin 1)
 *   MCP3008 VREF -> 3.3V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO11 (SCLK, Pin 23)
 *   MCP3008 DOUT -> GPIO9  (MISO, Pin 21)
 *   MCP3008 DIN  -> GPIO10 (MOSI, Pin 19)
 *   MCP3008 CS   -> GPIO8  (CE0,  Pin 24)
 *   MCP3008 CH0  -> MLX90823 VOUT
 *
 * Build: gcc -O2 -Wall -Wextra -o mlx90823_reader mlx90823_reader.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define ADC_CHANNEL    0          /* MCP3008 CH0 */
#define ADC_MAX        1023       /* 10-bit ADC */
#define VREF           3.3f       /* Reference voltage */

#define SAMPLE_PERIOD  1.0        /* Seconds between readings */

#define MIN_PRESSURE   0.0f       /* Pa */
#define MAX_PRESSURE   100000.0f  /* Pa */

#define SENSOR_MIN_V   0.0f       /* V — sensor absent at 0 V */
#define SENSOR_MAX_V   3.3f       /* V — sensor absent at VREF */

#define LOG_FILE       "pressure_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel select)
     *   Byte 2: 0x00  (don't care, clocks out low 2 bits)
     *
     * Response:
     *   rx[0] = ignored
     *   rx[1] = [null, null, null, B9, B8, B7, B6, B5]
     *   rx[2] = [B4, B3, B2, B1, B0, 0, 0, 0]
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Voltage conversion                                                  */
/* ------------------------------------------------------------------ */
static float adc_to_voltage(int adc_value)
{
    return ((float)adc_value / (float)ADC_MAX) * VREF;
}

/* ------------------------------------------------------------------ */
/* Pressure conversion (linear placeholder)                           */
/* ------------------------------------------------------------------ */
static float voltage_to_pressure(float voltage)
{
    return (voltage / VREF) * MAX_PRESSURE;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float pressure, const char *status)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s, Pressure: %.2f Pa, Status: %s\n", ts, pressure, status);
        fclose(fp);
    } else {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90823 Pressure Sensor Reader\n");
    printf("SPI channel %d, speed %d Hz, ADC channel %d\n",
           SPI_CHANNEL, SPI_SPEED, ADC_CHANNEL);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            log_data(0.0f, "SPI_ERROR");
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float pressure = voltage_to_pressure(voltage);

        char ts[32];
        get_timestamp(ts, sizeof(ts));

        /* --- Range validation --- */
        bool out_of_range = false;
        if (voltage <= SENSOR_MIN_V + 0.01f || voltage >= SENSOR_MAX_V - 0.01f) {
            fprintf(stderr, "%s - WARNING: Sensor absent or wiring fault "
                            "(V=%.3f, ADC=%d)\n", ts, voltage, adc_value);
            out_of_range = true;
        } else if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
            fprintf(stderr, "%s - WARNING: Pressure out of range "
                            "(%.2f Pa, V=%.3f, ADC=%d)\n",
                    ts, pressure, voltage, adc_value);
            out_of_range = true;
        }

        printf("%s - Pressure: %.2f Pa (V=%.3f, ADC=%d) %s\n",
               ts, pressure, voltage, adc_value,
               out_of_range ? "[OUT OF RANGE]" : "");

        log_data(pressure, out_of_range ? "OUT_OF_RANGE" : "OK");

        time_sleep(SAMPLE_PERIOD);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

