            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float pressure = voltage_to_pressure(voltage);

        char ts[32];
        get_timestamp(ts, sizeof(ts));

        /* --- Range validation --- */
        bool out_of_range = false;
        if (voltage <= SENSOR_MIN_V + 0.01f || voltage >= SENSOR_MAX_V - 0.01f) {
            fprintf(stderr, "%s - WARNING: Sensor absent or wiring fault "
                            "(V=%.3f, ADC=%d)\n", ts, voltage, adc_value);
            out_of_range = true;
        } else if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
            fprintf(stderr, "%s - WARNING: Pressure out of range "
                            "(%.2f Pa, V=%.3f, ADC=%d)\n",
                    ts, pressure, voltage, adc_value);
            out_of_range = true;
        }

        printf("%s - Pressure: %.2f Pa (V=%.3f, ADC=%d) %s\n",
               ts, pressure, voltage, adc_value,
               out_of_range ? "[OUT OF RANGE]" : "");

        log_data(pressure, out_of_range ? "OUT_OF_RANGE" : "OK");

        time_sleep(SAMPLE_PERIOD);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

