/*
 * Raspberry Pi Zero W — SEN0193 Capacitive Soil Moisture Sensor via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (BCM 11, SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (BCM 9,  SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (BCM 10, SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (BCM 8,  SPI0 CE0)
 *   MCP3008 CH0  -> SEN0193 analog output
 *   SEN0193 VCC  -> 3.3 V
 *   SEN0193 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o soil_moisture soil_moisture.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz — well within MCP3008 spec */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define MCP3008_CHANNEL 0          /* Single-ended channel 0 */
#define SAMPLE_PERIOD_S 5          /* Seconds between readings */
#define MAX_CONSECUTIVE_ERRORS 10  /* Fail-safe threshold */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_open(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * MCP3008 single-ended read.
 * Protocol (3-byte transfer, SPI Mode 0, MSB-first):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *   rx[1] bits 1..0 + rx[2] bits 7..0  -> 10-bit result
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_reading(int adc_value)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
    } else {
        strncpy(timestamp, "UNKNOWN", sizeof(timestamp));
        timestamp[sizeof(timestamp) - 1] = '\0';
    }

    printf("[%s] ADC Value: %d\n", timestamp, adc_value);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int fd = -1;
    int ret_code = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        goto done;
    }

    fd = spi_open(SPI_DEVICE);
    if (fd < 0) {
        goto done;
    }

    printf("Soil Moisture Sensor Monitoring (MCP3008 CH0, SPI0 CE0)\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    int consecutive_errors = 0;

    while (g_running) {
        int adc_value = mcp3008_read(fd, MCP3008_CHANNEL);

        if (adc_value < 0) {
            consecutive_errors++;
            fprintf(stderr, "SPI read error (%d consecutive)\n", consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Too many consecutive SPI errors — aborting.\n");
                goto done;
            }
        } else {
            /* Sensor-absent / wiring-fault heuristic: rail-stuck values */
            if (adc_value == 0 || adc_value == 1023) {
                fprintf(stderr,
                        "Warning: ADC value at rail (%d) — sensor absent or wiring fault.\n",
                        adc_value);
            }

            log_reading(adc_value);
            consecutive_errors = 0;
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S && g_running; i++) {
            sleep(1);
        }
    }

    ret_code = EXIT_SUCCESS;

done:
    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting gracefully.\n");
    return ret_code;
}

