    printf("Sampling every %d seconds. Press Ctrl+C to exit.\n\n",
           SAMPLE_INTERVAL);

    while (g_running) {
        int adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in %d s...\n",
