        }

        float moisture = calculate_moisture_percentage(adc_value);
        printf("ADC Value: %4d | Moisture: %5.1f%%\n", adc_value, moisture);
        fflush(stdout);

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nExiting gracefully...\n");
    if (close(spi_fd) < 0) {
        fprintf(stderr, "Error closing SPI device: %s\n", strerror(errno));
    }

    return EXIT_SUCCESS;
}

