#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define SPI_FLAGS      0
#define PUMP_GPIO      17
#define LOW_THRESHOLD  300
#define HIGH_THRESHOLD 600
#define BUFFER_SIZE    20
#define SAMPLE_PERIOD  5

typedef struct {
    time_t timestamp;
    int    moisture_level;
    int    pump_state;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int      buffer_index = 0;
static int      buffer_count = 0;
static int      pump_state   = 0;
static int      spi_handle   = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void control_pump(int moisture_level) {
    if (moisture_level < LOW_THRESHOLD && pump_state == 0) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            pump_state = 1;
            printf("Pump turned ON (moisture: %d)\n", moisture_level);
        } else {
            fprintf(stderr, "Error: Failed to turn pump ON\n");
        }
    } else if (moisture_level > HIGH_THRESHOLD && pump_state == 1) {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            pump_state = 0;
            printf("Pump turned OFF (moisture: %d)\n", moisture_level);
        } else {
            fprintf(stderr, "Error: Failed to turn pump OFF\n");
        }
    }
}

static void log_data(int moisture_level) {
    time(&log_buffer[buffer_index].timestamp);
    log_buffer[buffer_index].moisture_level = moisture_level;
    log_buffer[buffer_index].pump_state     = pump_state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_log_buffer(void) {
    printf("\n--- Log Buffer (%d entries) ---\n", buffer_count);
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&log_buffer[idx].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(time_str, "UNKNOWN", sizeof(time_str));
        }
        printf("[%s] Moisture: %d, Pump: %s\n",
               time_str,
               log_buffer[idx].moisture_level,
               log_buffer[idx].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log Buffer ---\n\n");
}

static void timer_callback(void *userdata) {
    (void)userdata;
    int moisture_level = read_mcp3008(0);
    if (moisture_level < 0) {
        fprintf(stderr, "Error: Failed to read moisture level\n");
        return;
    }
    control_pump(moisture_level);
    log_data(moisture_level);
    print_log_buffer();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set pump GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(PUMP_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialise pump GPIO state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handlers\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetTimerFuncEx(0, SAMPLE_PERIOD, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set timer function\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Monitoring System started. Press Ctrl+C to exit.\n");

    while (running) {
        sleep(1);
    }

    printf("\nShutting down...\n");
    gpioSetTimerFuncEx(0, SAMPLE_PERIOD, NULL, NULL);
    gpioWrite(PUMP_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

