#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x57

#define REG_INTR_STATUS_1 0x00
#define REG_INTR_STATUS_2 0x01
#define REG_INTR_ENABLE_1 0x02
#define REG_INTR_ENABLE_2 0x03
#define REG_FIFO_WR_PTR 0x04
#define REG_OVF_COUNTER 0x05
#define REG_FIFO_RD_PTR 0x06
#define REG_FIFO_DATA 0x07
#define REG_FIFO_CONFIG 0x08
#define REG_MODE_CONFIG 0x09
#define REG_SPO2_CONFIG 0x0A
#define REG_LED1_PA 0x0C
#define REG_LED2_PA 0x0E
#define REG_PART_ID 0xFF

#define PART_ID_EXPECTED 0x15

#define SAMPLE_RATE 100
#define ADC_RANGE 4096
#define PULSE_WIDTH_411 0x03
#define LED_CURRENT_27_1MA 0x1F

#define SPO2_THRESHOLD 95
#define HEART_RATE_THRESHOLD 100

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int init_max30102(int handle) {
    uint8_t part_id;
    if (read_register(handle, REG_PART_ID, &part_id) != 0) {
        return -1;
    }
    if (part_id != PART_ID_EXPECTED) {
        fprintf(stderr, "MAX30102 not detected (Part ID: 0x%02X, expected: 0x%02X)\n", part_id, PART_ID_EXPECTED);
        return -1;
    }

    if (write_register(handle, REG_MODE_CONFIG, 0x40) != 0) return -1;
    gpioDelay(10000);

    if (write_register(handle, REG_INTR_ENABLE_1, 0x00) != 0) return -1;
    if (write_register(handle, REG_INTR_ENABLE_2, 0x00) != 0) return -1;
    if (write_register(handle, REG_FIFO_WR_PTR, 0x00) != 0) return -1;
    if (write_register(handle, REG_OVF_COUNTER, 0x00) != 0) return -1;
    if (write_register(handle, REG_FIFO_RD_PTR, 0x00) != 0) return -1;
    if (write_register(handle, REG_FIFO_CONFIG, 0x4F) != 0) return -1;
    if (write_register(handle, REG_MODE_CONFIG, 0x03) != 0) return -1;
    if (write_register(handle, REG_SPO2_CONFIG, (SAMPLE_RATE << 5) | (PULSE_WIDTH_411 << 2) | 0x03) != 0) return -1;
    if (write_register(handle, REG_LED1_PA, LED_CURRENT_27_1MA) != 0) return -1;
    if (write_register(handle, REG_LED2_PA, LED_CURRENT_27_1MA) != 0) return -1;

    return 0;
}

static int read_fifo_data(int handle, uint32_t *red, uint32_t *ir) {
    uint8_t buffer[6];
    int result = i2cReadI2CBlockData(handle, REG_FIFO_DATA, (char *)buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading FIFO data: %d\n", result);
        return -1;
    }
    *red = ((uint32_t)buffer[0] << 16) | ((uint32_t)buffer[1] << 8) | buffer[2];
    *ir = ((uint32_t)buffer[3] << 16) | ((uint32_t)buffer[4] << 8) | buffer[5];
    return 0;
}

static int calculate_spo2(uint32_t red, uint32_t ir, int *spo2, int *heart_rate) {
    if (red == 0 || ir == 0) return -1;

    int32_t r = (int32_t)red;
    int32_t i = (int32_t)ir;

    int32_t r_diff = r - 2048;
    int32_t i_diff = i - 2048;

    int32_t r_sq = r_diff * r_diff;
    int32_t i_sq = i_diff * i_diff;

    int32_t spo2_raw = 110 - (r_sq - i_sq) * 18 / (r_sq + i_sq);

    if (spo2_raw < 0) spo2_raw = 0;
    if (spo2_raw > 100) spo2_raw = 100;

    *spo2 = spo2_raw;
    *heart_rate = 70 + (r_diff * 100 / 2048);
    return 0;
}

static void log_health_data(int spo2, int heart_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("health_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening health_log.txt for writing\n");
        return;
    }
    fprintf(fp, "%s, SpO2: %d%%, Heart Rate: %d BPM\n", timestamp, spo2, heart_rate);
    fclose(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_max30102(i2c_handle) != 0) {
        fprintf(stderr, "MAX30102 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MAX30102 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint32_t red, ir;
        if (read_fifo_data(i2c_handle, &red, &ir) == 0) {
            int spo2, heart_rate;
            if (calculate_spo2(red, ir, &spo2, &heart_rate) == 0) {
                printf("SpO2: %d%%, Heart Rate: %d BPM\n", spo2, heart_rate);
                if (spo2 < SPO2_THRESHOLD || heart_rate > HEART_RATE_THRESHOLD) {
                    log_health_data(spo2, heart_rate);
                }
            }
        }
        gpioDelay(1000000);
    }

    printf("\nCleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

