#define ADS1115_REG_CONFIG 0x01

/* Config word: single-shot, A0, ±4.096 V, 128 SPS, no comparator */
#define ADS1115_CFG_BASE   0x8000  /* OS bit */
#define ADS1115_CFG_MUX_A0 0x4000  /* MUX[14:12] = 100 (AIN0 vs GND) */
#define ADS1115_CFG_PGA_4V 0x0200  /* PGA[11:9] = 001 (±4.096 V) */
#define ADS1115_CFG_DR_128 0x0080  /* DR[7:5] = 100 (128 SPS) */
#define ADS1115_CFG_CQUE_1 0x0001  /* CQUE[1:0] = 001 (disable comparator) */
#define ADS1115_CFG        (ADS1115_CFG_BASE | ADS1115_CFG_MUX_A0 | \
                           ADS1115_CFG_PGA_4V | ADS1115_CFG_DR_128 | \
                           ADS1115_CFG_CQUE_1)

#define RELAY_GPIO         17
#define DOOR_SENSOR_GPIO   27

#define CALIBRATION_SAMPLES 10
#define SAMPLE_DELAY_MS     50
#define MONITOR_DELAY_MS    200
#define RELAY_PULSE_MS      3000
#define LOG_FILE            "/var/log/door_events.log"

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static int  g_relay_gpio = RELAY_GPIO;
static int  g_door_gpio  = DOOR_SENSOR_GPIO;
static int  g_log_fd     = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void  signal_handler(int sig);
static void  msleep(unsigned ms);
static int   i2c_write16(int fd, uint8_t reg, uint16_t val);
static int   i2c_read16(int fd, uint8_t reg, uint16_t *out);
static int   ads1115_read(int fd, uint16_t *raw);
static int   calibrate_threshold(int fd, float *threshold_out);
static int   read_distance(int fd, float threshold, int *below_out);
static void  pulse_relay(int gpio);
static int   read_door_sensor(int gpio);
static void  log_event(const char *msg);
static void  cleanup(void);

/* ----------------------------- Implementation ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void msleep(unsigned ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

/*
 * Write a 16-bit big-endian value to an ADS1115 register.
 * Returns 0 on success, -1 on error.
 */
static int i2c_write16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write16(reg=0x%02X): write failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit big-endian value from an ADS1115 register.
 * Returns 0 on success, -1 on error.
 */
static int i2c_read16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    struct i2c_msg msgs[2] = {
        { .addr = ADS1115_ADDR, .flags = 0,            .len = 1, .buf = &reg },
        { .addr = ADS1115_ADDR, .flags = I2C_M_RD,     .len = 2, .buf = buf  }
    };
    struct i2c_rdwr_ioctl_data data = { .msgs = msgs, .nmsgs = 2 };

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "i2c_read16(reg=0x%02X): I2C_RDWR failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Trigger a single-shot conversion on A0 and return the raw ADC count.
 * Returns 0 on success, -1 on error.
 */
static int ads1115_read(int fd, uint16_t *raw)
{
    if (i2c_write16(fd, ADS1115_REG_CONFIG, ADS1115_CFG) < 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    msleep(10);

    uint16_t cfg;
    for (int i = 0; i < 10; i++) {
        if (i2c_read16(fd, ADS1115_REG_CONFIG, &cfg) < 0)
            return -1;
        if (cfg & 0x8000)            /* OS bit set => conversion ready */
            break;
        msleep(5);
    }
    if (!(cfg & 0x8000)) {
        fprintf(stderr, "ads1115_read: conversion timeout\n");
        return -1;
    }

    return i2c_read16(fd, ADS1115_REG_CONV, raw);
}

/*
 * Take CALIBRATION_SAMPLES readings and compute the average as the
 * calibrated threshold.  Returns 0 on success, -1 on error.
 */
static int calibrate_threshold(int fd, float *threshold_out)
{
    long sum = 0;
    int ok = 0;

    printf("Calibrating threshold (keep sensor at the desired distance)...\n");
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        uint16_t raw;
        if (ads1115_read(fd, &raw) < 0) {
            fprintf(stderr, "Calibration sample %d failed: %s\n",
                    i + 1, strerror(errno));
            msleep(SAMPLE_DELAY_MS);
            continue;
        }
        sum += raw;
        ok++;
        msleep(SAMPLE_DELAY_MS);
    }

    if (ok == 0) {
        fprintf(stderr, "Calibration failed: no valid samples\n");
        return -1;
    }

    *threshold_out = (float)sum / ok;
    printf("Calibration complete. Threshold = %.2f\n", *threshold_out);
    return 0;
}

/*
 * Returns 1 if the raw ADC value is below the threshold (object detected),
 * 0 otherwise, -1 on I2C error.
 */
static int read_distance(int fd, float threshold, int *below_out)
{
    uint16_t raw;
    if (ads1115_read(fd, &raw) < 0)
        return -1;

    *below_out = (raw < (uint16_t)threshold) ? 1 : 0;
    return 0;
}

static void pulse_relay(int gpio)
{
    if (gpio < 0) return;

    if (gpio_write(gpio, 1) < 0) {
        fprintf(stderr, "Failed to energize relay (GPIO %d): %s\n",
                gpio, strerror(errno));
        return;
    }
    printf("Relay energized (door lock released)\n");

    msleep(RELAY_PULSE_MS);

    if (gpio_write(gpio, 0) < 0) {
        fprintf(stderr, "Failed to de-energize relay (GPIO %d): %s\n",
                gpio, strerror(errno));
        return;
    }
    printf("Relay de-energized (door lock re-secured)\n");
}

static int read_door_sensor(int gpio)
{
    if (gpio < 0) return 0;
    int v = gpio_read(gpio);
    if (v < 0) {
        fprintf(stderr, "Failed to read door sensor (GPIO %d): %s\n",
                gpio, strerror(errno));
        return 0;
    }
    return (v == 0) ? 1 : 0;   /* active-low */
}

static void log_event(const char *msg)
{
    if (g_log_fd < 0) return;

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);

    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);

    char line[256];
    int len = snprintf(line, sizeof(line), "%s.%03ld: %s\n",
                       tbuf, ts.tv_nsec / 1000000L, msg);
    if (len > 0) {
        if (write(g_log_fd, line, (size_t)len) != (ssize_t)len)
            fprintf(stderr, "log write failed: %s\n", strerror(errno));
        fsync(g_log_fd);
    }
}

static void cleanup(void)
{
    if (g_relay_gpio >= 0)
        gpio_write(g_relay_gpio, 0);

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fd >= 0) {
        close(g_log_fd);
        g_log_fd = -1;
    }
}

int main(void)
{
    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (g_log_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- GPIO setup (sysfs via gpio_write/gpio_read helpers) --- */
    /* In a production build these would be replaced with real sysfs calls;
     * here we use the kernel GPIO character device interface. */
    int gpio_export(int pin) {
        char path[64], buf[8];
        int fd = open("/sys/class/gpio/export", O_WRONLY);
        if (fd < 0) return -1;
        snprintf(buf, sizeof(buf), "%d", pin);
        ssize_t n = write(fd, buf, strlen(buf));
        close(fd);
        if (n < 0) return -1;
        return 0;
    }
    int gpio_unexport(int pin) {
        char path[64], buf[8];
        int fd = open("/sys/class/gpio/unexport", O_WRONLY);
        if (fd < 0) return -1;
        snprintf(buf, sizeof(buf), "%d", pin);
        ssize_t n = write(fd, buf, strlen(buf));
        close(fd);
        return (n < 0) ? -1 : 0;
    }
    int gpio_set_dir(int pin, const char *dir) {
        char path[64];
        snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
        int fd = open(path, O_WRONLY);
        if (fd < 0) return -1;
        ssize_t n = write(fd, dir, strlen(dir));
        close(fd);
        return (n < 0) ? -1 : 0;
    }
    int gpio_write(int pin, int val) {
        char path[64], buf[2];
        snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
        int fd = open(path, O_WRONLY);
        if (fd < 0) return -1;
        snprintf(buf, sizeof(buf), "%d", val);
        ssize_t n = write(fd, buf, 1);
        close(fd);
        return (n < 0) ? -1 : 0;
    }
    int gpio_read(int pin) {
        char path[64], buf[2];
        snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
        int fd = open(path, O_RDONLY);
        if (fd < 0) return -1;
        ssize_t n = read(fd, buf, sizeof(buf) - 1);
        close(fd);
        if (n < 0) return -1;
        buf[n] = '\0';
        return (buf[0] == '0') ? 0 : 1;
    }

    if (gpio_export(g_relay_gpio) < 0) {
        fprintf(stderr, "Failed to export GPIO %d: %s\n",
                g_relay_gpio, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpio_export(g_door_gpio) < 0) {
        fprintf(stderr, "Failed to export GPIO %d: %s\n",
                g_door_gpio, strerror(errno));
        gpio_unexport(g_relay_gpio);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpio_set_dir(g_relay_gpio, "out") < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n",
                g_relay_gpio, strerror(errno));
        goto gpio_fail;
    }
    if (gpio_set_dir(g_door_gpio, "in") < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n",
                g_door_gpio, strerror(errno));
        goto gpio_fail;
    }

    /* --- Calibration --- */
    float threshold;
    if (calibrate_threshold(g_i2c_fd, &threshold) < 0) {
        fprintf(stderr, "Calibration failed. Exiting.\n");
        goto gpio_fail;
    }

    printf("Monitoring distance (threshold %.2f)...\n", threshold);

    /* --- Main loop --- */
    while (g_running) {
        int below;
        int rc = read_distance(g_i2c_fd, threshold, &below);
        if (rc < 0) {
            fprintf(stderr, "Distance read failed: %s\n", strerror(errno));
            log_event("Sensor read error");
            msleep(MONITOR_DELAY_MS);
            continue;
        }

        if (below) {
            printf("Object detected below threshold!\n");
            pulse_relay(g_relay_gpio);

            int door_open = read_door_sensor(g_door_gpio);
            if (door_open)
                log_event("door opened");
            else
                log_event("door not opened");
        }

        msleep(MONITOR_DELAY_MS);
    }

    printf("\nShutting down...\n");
    log_event("program terminated");
    cleanup();
    gpio_unexport(g_relay_gpio);
    gpio_unexport(g_door_gpio);
    return EXIT_SUCCESS;

gpio_fail:
    gpio_unexport(g_relay_gpio);
    gpio_unexport(g_door_gpio);
    cleanup();
    return EXIT_FAILURE;
}

