#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8

#define CS0_PIN         8
#define CS1_PIN         7
#define CS2_PIN         25

#define ADC_CHANNEL     0
#define LOG_FILE        "soil_moisture_log.csv"
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n",
                SPI_DEVICE, strerror(errno));
        return -1;
    }

    unsigned int mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    unsigned int bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int cs_pin, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0 */
    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    gpioWrite(cs_pin, 0);
    gpioDelay(100); /* 100 us CS setup */

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0
    };

    int ret = ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr);
    gpioWrite(cs_pin, 1);

    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed on CS%d: %s\n",
                cs_pin, strerror(errno));
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void log_data(FILE *fp, int s1, int s2, int s3)
{
    time_t rawtime;
    struct tm timeinfo;
    char ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%d,%d,%d\n", ts, s1, s2, s3);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (spi_init() < 0) {
        gpioTerminate();
        return 1;
    }

    int cs_pins[3] = {CS0_PIN, CS1_PIN, CS2_PIN};
    for (int i = 0; i < 3; i++) {
        if (gpioSetMode(cs_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set CS%d as output\n", cs_pins[i]);
            goto cleanup;
        }
        gpioWrite(cs_pins[i], 1); /* CS inactive (high) */
    }

    int file_exists = (access(LOG_FILE, F_OK) == 0);
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n",
                LOG_FILE, strerror(errno));
        goto cleanup;
    }

    if (!file_exists) {
        fprintf(g_log_fp, "timestamp,sensor1,sensor2,sensor3\n");
        fflush(g_log_fp);
    }

    printf("Soil moisture logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int s1 = read_mcp3008(CS0_PIN, ADC_CHANNEL);
        int s2 = read_mcp3008(CS1_PIN, ADC_CHANNEL);
        int s3 = read_mcp3008(CS2_PIN, ADC_CHANNEL);

        log_data(g_log_fp, s1, s2, s3);

        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

cleanup:
    printf("\nShutting down...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioTerminate();
    return 0;
}

