#define DEFAULT_THRESHOLD 30.0
#define DEFAULT_PUMP_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PUMP_GPIO 18
#define LOG_FILE "irrigation.log"
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %d\n",
                attempt + 1, MAX_RETRIES, ret);
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(100000);
        }
    }
    return -1;
}

static double adc_to_moisture(int adc_value) {
    return ((double)adc_value / 1023.0) * 100.0;
}

static void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    log_message(state ? "Pump activated" : "Pump deactivated");
}

int main(int argc, char *argv[]) {
    int opt;
    double threshold = DEFAULT_THRESHOLD;
    int pump_duration = DEFAULT_PUMP_DURATION;
    int sleep_interval = DEFAULT_SLEEP_INTERVAL;

    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't': threshold = atof(optarg); break;
            case 'd': pump_duration = atoi(optarg); break;
            case 's': sleep_interval = atoi(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d pump_duration] [-s sleep_interval]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (threshold < 0.0 || threshold > 100.0) {
        fprintf(stderr, "Threshold must be between 0 and 100\n");
        return EXIT_FAILURE;
    }
    if (pump_duration <= 0) {
        fprintf(stderr, "Pump duration must be positive\n");
        return EXIT_FAILURE;
    }
    if (sleep_interval <= 0) {
        fprintf(stderr, "Sleep interval must be positive\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    control_pump(0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Irrigation system started");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_message("Failed to read ADC value after retries");
        } else {
            double moisture = adc_to_moisture(adc_value);
            char log_buf[128];
            snprintf(log_buf, sizeof(log_buf), "Moisture level: %.2f%%", moisture);
            log_message(log_buf);

            if (moisture < threshold) {
                log_message("Moisture below threshold, activating pump");
                control_pump(1);
                gpioDelay(pump_duration * 1000000);
                control_pump(0);
            }
        }

        for (int i = 0; i < sleep_interval && running; i++) {
            sleep(1);
        }
    }

    control_pump(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    log_message("Irrigation system stopped");
    return EXIT_SUCCESS;
}

