#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8591_ADDR   0x48
#define PCF8591_AIN0    0x00
#define SAMPLE_MS      100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t *out)
{
    uint8_t buf;
    ssize_t n = read(fd, &buf, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    *out = buf;
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE (0x%02X) failed: %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /* First write: select AIN0, single-ended, auto-increment off. */
    if (i2c_write_byte(fd, PCF8591_AIN0) < 0)
        goto cleanup;

    while (g_running) {
        /* Dummy read: PCF8591 returns the result of the previous conversion. */
        uint8_t dummy;
        if (i2c_read_byte(fd, &dummy) < 0)
            goto cleanup;

        /* Real read: current 8-bit sample. */
        uint8_t value;
        if (i2c_read_byte(fd, &value) < 0)
            goto cleanup;

        printf("AIN0: %u\n", (unsigned int)value);
        fflush(stdout);

        usleep(SAMPLE_MS * 1000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

