    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE (0x%02X) failed: %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /* First write: select AIN0, single-ended, auto-increment off. */
    if (i2c_write_byte(fd, PCF8591_AIN0) < 0)
        goto cleanup;

    while (g_running) {
        /* Dummy read: PCF8591 returns the result of the previous conversion. */
        uint8_t dummy;
        if (i2c_read_byte(fd, &dummy) < 0)
            goto cleanup;

        /* Real read: current 8-bit sample. */
        uint8_t value;
        if (i2c_read_byte(fd, &value) < 0)
            goto cleanup;

        printf("AIN0: %u\n", (unsigned int)value);
        fflush(stdout);

        usleep(SAMPLE_MS * 1000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

