/*
 * Raspberry Pi 3 Model B+ — SS49E Hall-effect sensor monitor via ADS1115 ADC.
 *
 * Hardware:
 *   - Honeywell SS49E linear Hall-effect sensor (VCC = 3.3 V, GND = GND)
 *   - ADS1115 ADC on I2C bus 1, address 0x48, single-ended AIN0
 *   - GPIO27 (BCM) driven HIGH on threshold breach to simulate motor shutdown
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hall_monitor hall_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./hall_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define ADS1115_ADDR         0x48

#define ADS1115_REG_CONV     0x00
#define ADS1115_REG_CONFIG   0x01

/*
 * Config word (16-bit, big-endian on the bus):
 *   Bit 15    OS          = 1  (begin single conversion)
 *   Bits14:12 MUX         = 100 (AIN0 single-ended, GND)
 *   Bits11:9  PGA         = 001 (±4.096 V)
 *   Bit  8    MODE        = 1  (single-shot)
 *   Bits7:5   DR          = 100 (128 SPS)
 *   Bit  4    COMP_MODE   = 0
 *   Bit  3    COMP_POL    = 0
 *   Bit  2    COMP_LAT    = 0
 *   Bits1:0   COMP_QUE    = 11 (disable comparator)
 * => 0x8483
 */
#define ADS1115_CONFIG_BASE  0x8483

#define GPIO_SHUTDOWN        27
#define THRESHOLD_GAUSS      500.0f
#define SAMPLE_PERIOD_US     1000000  /* 1 Hz */
#define BUFFER_SIZE          10
#define ADC_VREF             4.096f
#define ADC_MAX_COUNT        32767.0f
#define ADC_PGA              4.096f
#define SENSOR_VMAX          3.3f
#define SENSOR_VMIN          0.0f
#define SENSOR_GMAX          1000.0f
#define SENSOR_GMIN          0.0f

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static bool g_pigpio_inited = false;
static bool g_i2c_opened   = false;

/* --------------------------- Forward declarations ------------------------ */

static void signal_handler(int sig);
static int  ads1115_read(int handle, int16_t *out);
static float voltage_to_gauss(float v);
static void shutdown_motor(void);
static void cleanup(void);

/* ------------------------------- Signal ---------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ ADS1115 ---------------------------------- */

/*
 * Trigger a single-shot conversion on AIN0 and read the 16-bit result.
 * Returns 0 on success, -1 on I2C error.
 */
static int ads1115_read(int handle, int16_t *out)
{
    char cfg[2];
    char reg;
    char rx[2];
    int  rc;

    /* Write config: OS=1, MUX=AIN0, PGA=±4.096 V, single-shot, 128 SPS */
    cfg[0] = (ADS1115_CONFIG_BASE >> 8) & 0xFF;
    cfg[1] = ADS1115_CONFIG_BASE & 0xFF;

    rc = i2cWriteI2CBlockData(handle, ADS1115_REG_CONFIG, cfg, 2);
    if (rc < 0) {
        syslog(LOG_ERR, "ADS1115 config write failed: %s", strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    gpioDelay(10000);

    /* Point to conversion register and read 2 bytes */
    reg = ADS1115_REG_CONV;
    rc = i2cReadI2CBlockData(handle, reg, rx, 2);
    if (rc != 2) {
        syslog(LOG_ERR, "ADS1115 conversion read failed: %s", strerror(errno));
        return -1;
    }

    *out = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* --------------------------- Conversion helpers -------------------------- */

static float voltage_to_gauss(float v)
{
    if (v < SENSOR_VMIN || v > SENSOR_VMAX) {
        syslog(LOG_ERR, "Voltage out of range: %.4f V", v);
        return 0.0f;
    }
    return SENSOR_GMIN + (v - SENSOR_VMIN) * (SENSOR_GMAX - SENSOR_GMIN) /
           (SENSOR_VMAX - SENSOR_VMIN);
}

static void shutdown_motor(void)
{
    if (gpioWrite(GPIO_SHUTDOWN, 1) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d HIGH: %s", GPIO_SHUTDOWN, strerror(errno));
    } else {
        syslog(LOG_WARNING, "Motor shutdown initiated (GPIO%d HIGH)", GPIO_SHUTDOWN);
    }
}

/* ------------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    if (g_i2c_opened) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        g_i2c_opened = false;
    }
    if (g_pigpio_inited) {
        gpioWrite(GPIO_SHUTDOWN, 0);
        gpioTerminate();
        g_pigpio_inited = false;
    }
    closelog();
}

/* --------------------------------- Main ---------------------------------- */

int main(void)
{
    float buffer[BUFFER_SIZE];
    int   idx = 0;
    int   count = 0;
    float sum = 0.0f;
    bool  motor_armed = false;

    openlog("hall_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }
    g_pigpio_inited = true;

    if (gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output: %s", GPIO_SHUTDOWN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_SHUTDOWN, 0);

    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        syslog(LOG_ERR, "i2cOpen failed (bus %d, addr 0x%02X): %s",
               I2C_BUS, ADS1115_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    g_i2c_opened = true;

    syslog(LOG_INFO, "Hall monitor started (ADS1115 @ 0x%02X, GPIO%d shutdown)",
           ADS1115_ADDR, GPIO_SHUTDOWN);

    while (g_running) {
        int16_t raw;
        float   voltage;
        float   gauss;
        float   avg;

        if (ads1115_read(g_i2c_handle, &raw) != 0) {
            syslog(LOG_ERR, "ADC read failed; skipping sample");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        voltage = (float)raw * ADC_PGA / ADC_MAX_COUNT;
        gauss   = voltage_to_gauss(voltage);

        buffer[idx] = gauss;
        sum += gauss;
        if (count < BUFFER_SIZE) {
            count++;
        } else {
            sum -= buffer[idx];
        }
        idx = (idx + 1) % BUFFER_SIZE;

        avg = (count > 0) ? (sum / (float)count) : 0.0f;

        syslog(LOG_INFO, "Gauss: %.2f | Avg: %.2f | Raw: %d | V: %.4f",
               gauss, avg, raw, voltage);

        if (gauss > THRESHOLD_GAUSS && !motor_armed) {
            shutdown_motor();
            motor_armed = true;
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

