/*
 * Soil Moisture Monitor and Automated Watering System
 * Board:  Raspberry Pi Zero W
 * ADC:    MCP3008 on SPI0 CE0 (1 MHz, SPI mode 0)
 * Sensor: Vegetronix VH400 on MCP3008 channel 0
 * Pump:   Relay on GPIO18 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o watering watering.c -lpigpio -lrt
 * Run:    sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* SPI0 CE0 */
#define SPI_SPEED        1000000    /* 1 MHz   */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */

#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE    1023       /* 10-bit ADC */

#define MOISTURE_THRESHOLD 300      /* 10-bit units; below => water */
#define WATERING_DURATION  10       /* seconds */
#define POLL_INTERVAL      60       /* seconds between readings */

#define PUMP_GPIO          18        /* BCM 18 */
#define LOG_FILE           "watering_events.txt"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static bool g_pump_active = false;

/* --------------------------- Forward declarations ------------------------- */
static int  read_mcp3008(int channel, int *out_value);
static int  control_pump(bool activate);
static void log_event(int moisture_level);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- MCP3008 --------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer, SPI mode 0):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d (must be 0-7)\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    if (value < 0 || value > ADC_MAX_VALUE) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", value);
        return -1;
    }

    *out_value = value;
    return 0;
}

/* ------------------------------- Pump control ---------------------------- */
static int control_pump(bool activate)
{
    if (gpioWrite(PUMP_GPIO, activate ? 1 : 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed\n", PUMP_GPIO, activate);
        return -1;
    }
    g_pump_active = activate;
    return 0;
}

/* --------------------------------- Logging -------------------------------- */
static void log_event(int moisture_level)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Moisture: %d (threshold %d) - Pump: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            moisture_level, MOISTURE_THRESHOLD,
            g_pump_active ? "ON" : "OFF");

    fclose(fp);
}

/* ------------------------------ Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    /* Ensure pump is OFF before releasing resources */
    if (g_pump_active) {
        gpioWrite(PUMP_GPIO, 0);
        g_pump_active = false;
    }

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    gpioTerminate();
}

/* --------------------------------- Main ----------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pump GPIO */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (control_pump(false) < 0) {
        fprintf(stderr, "Error: failed to initialise pump GPIO to OFF\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open SPI */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen(CE%d, %d, 0) failed: %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error: sigaction failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Monitoring System started.\n");
    printf("  SPI: CE%d @ %d Hz | ADC channel: %d | Threshold: %d | Pump: BCM %d\n",
           SPI_CHANNEL, SPI_SPEED, ADC_CHANNEL, MOISTURE_THRESHOLD, PUMP_GPIO);
    printf("  Poll interval: %d s | Watering duration: %d s\n",
           POLL_INTERVAL, WATERING_DURATION);
    printf("  Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int moisture_level = 0;

        if (read_mcp3008(ADC_CHANNEL, &moisture_level) < 0) {
            fprintf(stderr, "Error: failed to read moisture level; retrying in %d s\n",
                    POLL_INTERVAL);
            sleep(POLL_INTERVAL);
            continue;
        }

