#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0         /* Mode 0, active-low CE */
#define ADC_CHANNEL 0        /* MCP3008 single-ended channel 0 */
#define SAMPLE_US  1000000   /* 1 second */

/* YL-83: higher voltage = more water = higher intensity */
static const char *intensity_str(int adc) {
    if (adc < 200)  return "Low";
    if (adc < 500)  return "Medium";
    if (adc < 800)  return "High";
    return "Very High";
}

static void log_data(int adc, const char *intensity) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] ADC: %4d  Rainfall: %s\n", ts, adc, intensity);
    fflush(stdout);
}

int main(void) {
    int spi_handle = -1;
    int rc = EXIT_FAILURE;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0, mode 0, 1 MHz --- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, pigpio_error(spi_handle));
        goto cleanup_gpio;
    }

    /* --- Install SIGINT handler for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = SIG_DFL;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (1) {
        unsigned char tx[3] = {
            0x01,                       /* Start bit */
            (unsigned char)(0x80 | (ADC_CHANNEL << 4)), /* SGL/DIFF=1, D2..D0 */
            0x00                        /* padding */
        };
        unsigned char rx[3] = {0};

        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret != 3) {
            fprintf(stderr, "Error: spiXfer failed: %s\n",
                    ret < 0 ? pigpio_error(ret) : "short transfer");
            /* Skip this sample; retry next cycle */
            gpioDelay(SAMPLE_US);
            continue;
        }

        /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
        int adc = ((rx[1] & 0x03) << 8) | rx[2];

        const char *intensity = intensity_str(adc);
        log_data(adc, intensity);

        gpioDelay(SAMPLE_US);
    }

    rc = EXIT_SUCCESS;

    /* --- Cleanup --- */
    spiClose(spi_handle);
cleanup_gpio:
    gpioTerminate();
    return rc;
}

