#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define LED_GPIO       17
#define THRESHOLD_GAUSS 100.0f
#define SAMPLE_US      100000
#define BLINK_ON_US    50000
#define BLINK_OFF_US   50000
#define BLINK_TOTAL_US 1000000

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

#define ADS1115_CFG_OS_SINGLE  0x8000
#define ADS1115_CFG_MUX_AIN0  0x4000
#define ADS1115_CFG_PGA_4_096 0x0200
#define ADS1115_CFG_MODE_SS   0x0100
#define ADS1115_CFG_DR_128    0x0080

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int16_t read_ads1115(int handle) {
    char cfg[2];
    cfg[0] = (char)((ADS1115_CFG_OS_SINGLE | ADS1115_CFG_MUX_AIN0 |
                     ADS1115_CFG_PGA_4_096 | ADS1115_CFG_MODE_SS |
                     ADS1115_CFG_DR_128) >> 8);
    cfg[1] = (char)((ADS1115_CFG_OS_SINGLE | ADS1115_CFG_MUX_AIN0 |
                     ADS1115_CFG_PGA_4_096 | ADS1115_CFG_MODE_SS |
                     ADS1115_CFG_DR_128) & 0xFF);

    if (i2cWriteI2CBlockData(handle, ADS1115_REG_CONFIG, cfg, 2) < 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config.\n");
        return -1;
    }

    gpioDelay(10000);

    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(handle, &reg, 1) < 0) {
        fprintf(stderr, "Error: failed to set ADS1115 conversion pointer.\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: failed to read ADS1115 conversion.\n");
        return -1;
    }

    return (int16_t)(((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1]);
}

static float convert_to_gauss(int16_t raw) {
    float voltage = (raw * 4.096f) / 32768.0f;
    return voltage * 100.0f;
}

static void blink_led(int gpio) {
    uint32_t elapsed = 0;
    while (elapsed < BLINK_TOTAL_US && g_running) {
        gpioWrite(gpio, 1);
        gpioDelay(BLINK_ON_US);
        gpioWrite(gpio, 0);
        gpioDelay(BLINK_OFF_US);
        elapsed += BLINK_ON_US + BLINK_OFF_US;
    }
}

int main(int argc, char *argv[]) {
