#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <pigpio.h>
#include <mosquitto.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define PUMP_GPIO 17
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC_SOIL "soil_moisture"
#define MQTT_TOPIC_PUMP "pump_control"
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define POLL_INTERVAL_SEC 60
#define MAX_SPI_RETRIES 3
#define SENSOR_MIN_VALID 0
#define SENSOR_MAX_VALID 100

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static struct mosquitto *mosq = NULL;
static int pump_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            if (adc_value < SENSOR_MIN_VALID || adc_value > SENSOR_MAX_VALID) {
                syslog(LOG_WARNING, "ADC value out of range: %d (attempt %d)", adc_value, attempt + 1);
            }
            return adc_value;
        }
        syslog(LOG_WARNING, "SPI transfer failed (attempt %d/%d): %d", attempt + 1, MAX_SPI_RETRIES, ret);
        usleep(10000);
    }

    syslog(LOG_ERR, "SPI transfer failed after %d attempts", MAX_SPI_RETRIES);
    return -1;
}

static int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write GPIO %d: %s", PUMP_GPIO, strerror(errno));
        return -1;
    }
    pump_state = state;
    syslog(LOG_INFO, "Pump %s", state ? "activated" : "deactivated");
    return 0;
}

static void publish_moisture(int moisture) {
    char payload[16];
    snprintf(payload, sizeof(payload), "%d", moisture);
    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC_SOIL, (int)strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(ret));
    } else {
        syslog(LOG_INFO, "Published moisture: %s", payload);
    }
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        int ret = mosquitto_subscribe(m, NULL, MQTT_TOPIC_PUMP, 0);
        if (ret != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT subscribe failed: %s", mosquitto_strerror(ret));
        } else {
            syslog(LOG_INFO, "Subscribed to %s", MQTT_TOPIC_PUMP);
        }
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(result));
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;
    if (message->payloadlen > 0) {
        char payload[64] = { 0 };
        int len = message->payloadlen < (int)sizeof(payload) - 1 ? message->payloadlen : (int)sizeof(payload) - 1;
        memcpy(payload, message->payload, len);
        syslog(LOG_INFO, "Received MQTT message: %s", payload);

        if (strcmp(payload, "pump_on") == 0) {
            if (control_pump(1) == 0) {
                int ret = mosquitto_publish(m, NULL, MQTT_TOPIC_PUMP, 8, "pump_on", 0, false);
                if (ret != MOSQ_ERR_SUCCESS) {
                    syslog(LOG_ERR, "MQTT publish pump_on failed: %s", mosquitto_strerror(ret));
                }
            }
        } else if (strcmp(payload, "pump_off") == 0) {
            if (control_pump(0) == 0) {
                int ret = mosquitto_publish(m, NULL, MQTT_TOPIC_PUMP, 8, "pump_off", 0, false);
                if (ret != MOSQ_ERR_SUCCESS) {
                    syslog(LOG_ERR, "MQTT publish pump_off failed: %s", mosquitto_strerror(ret));
                }
            }
        } else {
            syslog(LOG_WARNING, "Unknown MQTT command: %s", payload);
        }
    }
}

static void cleanup(void) {
    if (pump_state) {
        gpioWrite(PUMP_GPIO, 0);
        pump_state = 0;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("soil_moisture_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        closelog();
        return 1;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output: %s", PUMP_GPIO, strerror(errno));
        gpioTerminate();
        closelog();
        return 1;
    }
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI initialisation failed: %d", spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);

    int ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosq = NULL;
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_loop_start(mosq);

    while (running) {
        int moisture = read_mcp3008(MCP3008_CHANNEL);
        if (moisture < 0) {
            syslog(LOG_ERR, "Failed to read moisture sensor");
        } else {
            publish_moisture(moisture);
            if (moisture < MOISTURE_THRESHOLD_LOW && !pump_state) {
                control_pump(1);
            } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_state) {
                control_pump(0);
            }
        }
        sleep(POLL_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

