#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define VREF        3.3
#define NUM_CHANNELS 3
#define LOG_FILE    "sensor_data.csv"
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int log_data(FILE *fp, float v0, float v1, float v2) {
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error: time() failed\n");
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return -1;
    }

    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, v0, v1, v2) < 0) {
        fprintf(stderr, "Error: fprintf() failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush() failed\n");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error: fopen(" LOG_FILE ")");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int adc[NUM_CHANNELS];
        int err = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            adc[i] = read_mcp3008(spi_handle, i);
            if (adc[i] < 0) {
                err = 1;
                break;
            }
        }

        if (err) {
            fprintf(stderr, "Error: ADC read failed, skipping sample\n");
        } else {
            float v0 = (float)adc[0] * VREF / 1023.0f;
            float v1 = (float)adc[1] * VREF / 1023.0f;
            float v2 = (float)adc[2] * VREF / 1023.0f;

            if (log_data(fp, v0, v1, v2) != 0) {
                fprintf(stderr, "Error: logging failed\n");
            }
        }

        for (int s = 0; s < SAMPLE_INTERVAL && running; s++) {
            sleep(1);
        }
    }

    if (fclose(fp) != 0) {
        perror("Warning: fclose(" LOG_FILE ")");
    }
    if (spiClose(spi_handle) != 0) {
        fprintf(stderr, "Warning: spiClose() failed\n");
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

