/*
 * Vibration Motor Control via MAX9814 + MCP3008 ADC
 * Board:  Raspberry Pi 3 Model B+
 * SPI:    /dev/spidev0.0 (CE0) -> MCP3008
 * PWM:    GPIO17 (BCM) and GPIO27 (BCM) -> 3 V vibration motors
 *
 * Build:  gcc -O2 -Wall -o vib_ctrl vib_ctrl.c -lpigpio -lrt
 * Run:    sudo ./vib_ctrl
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000U   /* 1 MHz */
#define SPI_BITS_PER_WORD 8U
#define SPI_MODE          SPI_MODE_0

#define ADC_CHANNEL       0          /* MCP3008 channel 0 */
#define ADC_MAX           1023       /* 10-bit ADC */

#define MOTOR1_PIN        17         /* BCM 17 */
#define MOTOR2_PIN        27         /* BCM 27 */
#define PWM_FREQUENCY     100        /* Hz */
#define PWM_RANGE         255        /* 8-bit duty resolution */
#define NOISE_THRESHOLD   500        /* ADC count threshold */
#define SAMPLE_PERIOD_US  10000      /* 10 ms */
#define LOG_FILE          "vibration_log.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI                                                                 */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        goto fail;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        goto fail;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        goto fail;
    }

    return 0;

fail:
    close(g_spi_fd);
    g_spi_fd = -1;
    return -1;
}

/*
 * MCP3008 single-ended read.
 * Protocol (3 bytes):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int mcp3008_read(uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "mcp3008_read: invalid channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | rx[2];
    return adc;
}

/* ------------------------------------------------------------------ */
/* PWM / motor control                                                 */
/* ------------------------------------------------------------------ */
static void motor_set_duty(int pin, int duty)
{
    if (duty < 0)        duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "gpioPWM(pin=%d, duty=%d): %s\n",
                pin, duty, pigpio_error(gpioGetMode(pin)));
    }
}

static void motors_off(void)
{
    motor_set_duty(MOTOR1_PIN, 0);
    motor_set_duty(MOTOR2_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    if (!g_log_fp) return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_fp, "%s: %s\n", ts, msg);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    motors_off();

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR1_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR2_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR1_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR2_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    motors_off();

    /* ---- SPI init ---- */
    if (spi_init() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Vibration control system started");

    /* ---- Main loop ---- */
    while (g_running) {
        int adc = mcp3008_read(ADC_CHANNEL);
        if (adc < 0) {
            log_event("ADC read error; skipping iteration");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        int duty = (adc > NOISE_THRESHOLD) ? (adc - NOISE_THRESHOLD) : 0;
        motor_set_duty(MOTOR1_PIN, duty);
        motor_set_duty(MOTOR2_PIN, duty);

        if (adc > NOISE_THRESHOLD) {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "Vibration event: ADC=%d, duty=%d", adc, duty);
            log_event(msg);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    log_event("Vibration control system shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

