#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_ADDR 0x23
#define BH1750_CONT_HRES_MODE 0x10
#define BH1750_MEASUREMENT_DELAY_MS 180

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0

#define LOG_FILE "tamper_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(const char *device, int addr) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

static int init_spi(const char *device, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }
    int mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }
    return fd;
}

static int read_bh1750(int fd) {
    unsigned char cmd = BH1750_CONT_HRES_MODE;
    if (write(fd, &cmd, 1) != 1) {
        perror("Failed to write BH1750 command");
        return -1;
    }
    usleep(BH1750_MEASUREMENT_DELAY_MS * 1000);
    unsigned char buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read BH1750 data");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

static int read_mcp3008(int fd, int channel) {
    unsigned char tx[3] = { 0x01, (0x08 | channel) << 4, 0x00 };
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void log_data(FILE *fp, int sound_level, int light_level, int error_code) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%d,%d,%d\n", timestamp, sound_level, light_level, error_code);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = init_i2c("/dev/i2c-1", BH1750_ADDR);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    spi_fd = init_spi(SPI_DEVICE, SPI_SPEED);
    if (spi_fd < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        int sound_level = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        int light_level = read_bh1750(i2c_fd);
        int error_code = (sound_level < 0 || light_level < 0) ? 1 : 0;
        log_data(log_file, sound_level, light_level, error_code);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (log_file) fclose(log_file);
    if (spi_fd >= 0) close(spi_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    return EXIT_SUCCESS;
}

