/*
 * Raspberry Pi 4 Model B – Soil Moisture Monitor & Pump Controller
 *
 * Hardware:
 *   - Vegetronix VH400 soil moisture sensor  -> MCP3008 CH0 (0-3 V)
 *   - MCP3008 ADC                            -> SPI0 CE0 (BCM 8), 1 MHz
 *   - Relay / pump control                   -> BCM 17 (active-high)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o soil_monitor soil_monitor.c -lpigpio -lrt
 *   (run as root, or ensure pigpiod is stopped / gpio group access configured)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* CE0 on SPI0 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX        1023       /* 10-bit ADC */

#define PUMP_GPIO      17         /* BCM 17 – active-high relay */

#define MOISTURE_THRESHOLD 30.0f  /* % – pump ON below this */
#define SAMPLE_INTERVAL_S  60     /* seconds between readings */
#define MAX_RETRIES        3

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static int  initialize(void);
static void cleanup(void);
static int  read_mcp3008(int channel, int *out_value);
static float adc_to_moisture_pct(int adc_value);
static void control_pump(bool activate);
static void log_reading(float moisture_pct, int adc_value);
static void signal_handler(int sig);

/* ----------------------------- Implementation ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int initialize(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed.\n");
        return -1;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "[ERROR] spiOpen failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, pigpio_error(g_spi_handle));
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d, PI_OUTPUT) failed.\n", PUMP_GPIO);
        cleanup();
        return -1;
    }
    gpioWrite(PUMP_GPIO, 0);  /* pump OFF at startup */

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    return 0;
}

static void cleanup(void)
{
    /* Ensure pump is OFF before releasing resources */
    if (g_spi_handle >= 0) {
        gpioWrite(PUMP_GPIO, 0);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0 on success (value stored in *out_value), -1 on failure.
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "[ERROR] Invalid ADC channel %d.\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit value
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "[ERROR] spiXfer returned %d: %s\n",
                ret, pigpio_error(ret));
        return -1;
    }

    *out_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return 0;
}

static float adc_to_moisture_pct(int adc_value)
{
    /*
     * Vegetronix VH400 (analog) – empirical calibration.
     * 0 V  -> ~0 %  (dry)
     * 3 V  -> ~100 % (saturated)
     * 10-bit ADC: 0-1023 maps to 0-3 V.
     */
    float voltage = (float)adc_value / (float)ADC_MAX * 3.0f;
    float pct = (voltage / 3.0f) * 100.0f;

    if (pct < 0.0f)   pct = 0.0f;
    if (pct > 100.0f) pct = 100.0f;
    return pct;
}

static void control_pump(bool activate)
{
    if (gpioWrite(PUMP_GPIO, activate ? 1 : 0) < 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%d, %d) failed.\n",
                PUMP_GPIO, activate ? 1 : 0);
    }
}

static void log_reading(float moisture_pct, int adc_value)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    printf("[%s] ADC=%4d  Moisture=%5.1f%%  %s\n",
           ts, adc_value, moisture_pct,
           moisture_pct < MOISTURE_THRESHOLD ? "PUMP ON" : "PUMP OFF");
    fflush(stdout);
}

int main(void)
{
    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Monitor started.  Sampling every %d s.  Ctrl+C to exit.\n",
           SAMPLE_INTERVAL_S);
    fflush(stdout);

    while (g_running) {
        int adc_value = -1;
        bool read_ok = false;

        for (int attempt = 1; attempt <= MAX_RETRIES && g_running; ++attempt) {
            if (read_mcp3008(ADC_CHANNEL, &adc_value) == 0) {
                read_ok = true;
                break;
            }
            fprintf(stderr, "[WARN] ADC read attempt %d/%d failed.\n",
                    attempt, MAX_RETRIES);
            if (attempt < MAX_RETRIES) {
                sleep(1);
            }
        }

        if (!read_ok) {
            fprintf(stderr, "[ERROR] ADC read failed after %d attempts – skipping cycle.\n",
                    MAX_RETRIES);
            /* Keep pump OFF on sensor failure for safety */
            control_pump(false);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        float moisture_pct = adc_to_moisture_pct(adc_value);
        log_reading(moisture_pct, adc_value);

        bool pump_on = (moisture_pct < MOISTURE_THRESHOLD);
        control_pump(pump_on);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int s = 0; s < SAMPLE_INTERVAL_S && g_running; ++s) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

