        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler\n");
    }

    printf("Door monitoring system started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        float distance = adc_to_distance(adc_value);

        if (distance < DISTANCE_THRESHOLD) {
            printf("Object detected at %.2f cm. Opening door.\n", distance);
            if (gpioWrite(RELAY_GPIO, 1) != 0) {
                fprintf(stderr, "Error: Failed to activate relay\n");
            }
            log_event(distance);
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            if (gpioWrite(RELAY_GPIO, 0) != 0) {
                fprintf(stderr, "Error: Failed to deactivate relay\n");
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

