    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Irrigation control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int valid = 0;
        int sum = 0;

        for (int i = 0; i < SAMPLES; i++) {
            int val = read_mcp3008(0);
            if (val < 0) {
                fprintf(stderr, "Warning: Failed to read ADC sample %d\n", i + 1);
                continue;
            }
            samples[i] = val;
            sum += val;
            valid++;
            if (i < SAMPLES - 1) {
                gpioDelay(SAMPLE_DELAY_US);
            }
        }

