            fprintf(stderr, "Error: All ADC reads failed; skipping cycle\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        avg = sum / valid;

        if (avg < 200) {
            valve_pos = 100;
        } else if (avg < 400) {
            valve_pos = 50;
        } else {
            valve_pos = 0;
        }

        if (set_valve_position(valve_pos) != 0) {
            fprintf(stderr, "Error: Failed to set valve position\n");
        }

        log_data(samples, avg, valve_pos);
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    set_valve_position(0);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

