#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define LOG_FILE "soil_data.txt"
#define MAX_RETRIES 5
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_moisture(int adc_value) {
    return 100.0f - ((float)adc_value / 1023.0f) * 100.0f;
}

static void log_data(const char *timestamp, float moisture, int adc_value, int error) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    if (error) {
        fprintf(fp, "%s, ERROR, ADC: %d\n", timestamp, adc_value);
    } else {
        fprintf(fp, "%s, %.2f, ADC: %d\n", timestamp, moisture, adc_value);
    }

    fclose(fp);
}

static void get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", timeinfo);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed on channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = -1;
        int retries = 0;
        int delay_ms = 100;

        while (retries < MAX_RETRIES && running) {
            adc_value = read_mcp3008(spi_handle, MCP3008_CHANNEL);
            if (adc_value >= 0) {
                break;
            }
            retries++;
            fprintf(stderr, "SPI read failed (attempt %d/%d)\n", retries, MAX_RETRIES);
            gpioDelay(delay_ms * 1000);
            delay_ms *= 2;
        }

        char timestamp[20];
        get_timestamp(timestamp, sizeof(timestamp));

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value after %d retries\n", MAX_RETRIES);
            log_data(timestamp, 0.0f, -1, 1);
        } else if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            log_data(timestamp, 0.0f, adc_value, 1);
        } else {
            float moisture = adc_to_moisture(adc_value);
            log_data(timestamp, moisture, adc_value, 0);
            printf("%s - Moisture: %.2f%%, ADC: %d\n", timestamp, moisture, adc_value);
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("\nSoil moisture monitoring stopped.\n");
    return EXIT_SUCCESS;
}

