#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <sys/stat.h>
#include <sys/types.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_CHIP 0
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 10000000
#define SPI_DEVICE "/dev/spidev0.0"
#define CONFIG_FILE "theremin_config.txt"
#define MAX_DISTANCE 400.0
#define MIN_DISTANCE 2.0
#define MAX_VOLUME 100
#define MIN_VOLUME 0
#define TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;
static int pwm_exported = 0;
static int spi_fd = -1;
static float min_distance = 2.0;
static float max_distance = 400.0;
static int min_volume = 0;
static int max_volume = 100;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_file(const char *path, const char *value) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    int ret = write(fd, value, strlen(value));
    close(fd);
    return (ret < 0) ? -1 : 0;
}

static int read_file(const char *path, char *buf, size_t len) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) return -1;
    int ret = read(fd, buf, len - 1);
    close(fd);
    if (ret < 0) return -1;
    buf[ret] = '\0';
    return 0;
}

static int export_pwm(void) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d", PWM_CHIP, PWM_CHANNEL);
    if (access(path, F_OK) == 0) return 0;
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/export", PWM_CHIP);
    if (write_file(path, "0") < 0) return -1;
    usleep(100000);
    return 0;
}

static int setup_pwm(void) {
    if (export_pwm() < 0) return -1;
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_CHANNEL);
    if (write_file(path, "10000000") < 0) return -1;
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    if (write_file(path, "0") < 0) return -1;
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
    if (write_file(path, "1") < 0) return -1;
    pwm_exported = 1;
    return 0;
}

static void cleanup_pwm(void) {
    if (pwm_exported) {
        char path[64];
        snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
        write_file(path, "0");
