    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Alcohol sensor monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_adc_with_retry(ADC_CHANNEL);

        if (adc_value < 0) {
            log_data(g_log_fp, -1, "ADC read error");
        } else if (adc_value == SENSOR_LOW || adc_value == SENSOR_HIGH) {
            fprintf(stderr, "Warning: ADC reading at extreme (%d) - sensor may be absent or disconnected\n", adc_value);
            log_data(g_log_fp, adc_value, "Sensor absent or disconnected");
        } else {
            const char *status;
            if (adc_value > ALCOHOL_HIGH) {
                status = "Alcohol detected! Limit exceeded.";
            } else if (adc_value < ALCOHOL_LOW) {
                status = "Sobriety confirmed.";
            } else {
                status = "Alcohol level within acceptable range.";
            }
            log_data(g_log_fp, adc_value, status);
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

