#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ----------------------------- Pin Definitions ----------------------------- */
#define MOTOR1_ENABLE_PIN    18
#define MOTOR1_DIRECTION_PIN 23
#define MOTOR2_ENABLE_PIN    24
#define MOTOR2_DIRECTION_PIN 25

#define SPI_CHANNEL          0
#define SPI_SPEED            1000000  /* 1 MHz */
#define SPI_FLAGS            0        /* Mode 0, active-low CE */

/* ----------------------------- Constants ---------------------------------- */
#define ACCELERATION_STEPS   10
#define DECELERATION_STEPS   10
#define ACCELERATION_DELAY_US 10000   /* 10 ms */
#define DECELERATION_DELAY_US 10000   /* 10 ms */
#define SPEED_HOLD_DELAY_US  2000000  /* 2 s */
#define LOOP_DELAY_US        5000000  /* 5 s */
#define PWM_RANGE            1000
#define PWM_FREQ             1000     /* 1 kHz */

/* ----------------------------- Globals ------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ----------------------------- Prototypes --------------------------------- */
static int  initialize_gpio(void);
static int  initialize_spi(void);
static int  read_potentiometer(int channel);
static int  map_potentiometer_to_speed(int pot_value);
static void set_motor_speed(int motor, int speed);
static void set_motor_direction(int motor, int direction);
static void accelerate_motor(int motor, int target_speed);
static void decelerate_motor(int motor);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- Signal Handler ------------------------------ */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Initialization ------------------------------ */
static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    int motor_pins[] = {
        MOTOR1_ENABLE_PIN, MOTOR1_DIRECTION_PIN,
        MOTOR2_ENABLE_PIN, MOTOR2_DIRECTION_PIN
    };
    for (size_t i = 0; i < sizeof(motor_pins) / sizeof(motor_pins[0]); ++i) {
        if (gpioSetMode(motor_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", motor_pins[i]);
            return -1;
        }
    }

    if (gpioSetPWMrange(MOTOR1_ENABLE_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR2_ENABLE_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed.\n");
        return -1;
    }

    if (gpioSetPWMfrequency(MOTOR1_ENABLE_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(MOTOR2_ENABLE_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed.\n");
        return -1;
    }

    /* Ensure motors are off at start */
    gpioPWM(MOTOR1_ENABLE_PIN, 0);
    gpioPWM(MOTOR2_ENABLE_PIN, 0);
    gpioWrite(MOTOR1_DIRECTION_PIN, 0);
    gpioWrite(MOTOR2_DIRECTION_PIN, 0);

    return 0;
}

static int initialize_spi(void) {
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- MCP3008 Read -------------------------------- */
static int read_potentiometer(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d.\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = (0x08 | channel) << 4  (single-ended + channel)
     *   tx[2] = 0x00  (don't care)
     * Result: 10-bit value assembled from rx[1] (lower 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(g_spi_handle, tx, rx, 3) < 0) {
        fprintf(stderr, "Error: spiXfer failed on channel %d: %s\n",
                channel, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ----------------------------- Speed Mapping ------------------------------- */
static int map_potentiometer_to_speed(int pot_value) {
    if (pot_value < 0)   pot_value = 0;
    if (pot_value > 1023) pot_value = 1023;
    return (int)(((float)pot_value / 1023.0f) * (PWM_RANGE - 1));
}

/* ----------------------------- Motor Control ------------------------------- */
static void set_motor_speed(int motor, int speed) {
    if (speed < 0)   speed = 0;
    if (speed > PWM_RANGE - 1) speed = PWM_RANGE - 1;

    int enable_pin = (motor == 1) ? MOTOR1_ENABLE_PIN : MOTOR2_ENABLE_PIN;
    if (gpioPWM(enable_pin, speed) < 0) {
        fprintf(stderr, "Warning: gpioPWM failed for motor %d (pin %d).\n",
                motor, enable_pin);
    }
}

static void set_motor_direction(int motor, int direction) {
    int dir_pin = (motor == 1) ? MOTOR1_DIRECTION_PIN : MOTOR2_DIRECTION_PIN;
    if (gpioWrite(dir_pin, direction ? 1 : 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite failed for motor %d direction (pin %d).\n",
                motor, dir_pin);
    }
}

static void accelerate_motor(int motor, int target_speed) {
    int current_speed = 0;
    int increment = target_speed / ACCELERATION_STEPS;
    if (increment == 0) increment = 1;

    while (current_speed < target_speed) {
        current_speed += increment;
        if (current_speed > target_speed) current_speed = target_speed;
        set_motor_speed(motor, current_speed);
        gpioDelay(ACCELERATION_DELAY_US);
    }
}

static void decelerate_motor(int motor) {
    int current_speed = PWM_RANGE - 1;
    int decrement = current_speed / DECELERATION_STEPS;
    if (decrement == 0) decrement = 1;

    while (current_speed > 0) {
        current_speed -= decrement;
        if (current_speed < 0) current_speed = 0;
        set_motor_speed(motor, current_speed);
        gpioDelay(DECELERATION_DELAY_US);
    }
}

/* ----------------------------- Cleanup ------------------------------------- */
static void cleanup(void) {
    /* Stop motors */
    gpioPWM(MOTOR1_ENABLE_PIN, 0);
    gpioPWM(MOTOR2_ENABLE_PIN, 0);

    /* Close SPI */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

/* ----------------------------- Main ---------------------------------------- */
int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_spi() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Motor control program started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int pot1 = read_potentiometer(0);
        int pot2 = read_potentiometer(1);

        if (pot1 < 0 || pot2 < 0) {
            fprintf(stderr, "Error: Failed to read potentiometer(s). Retrying...\n");
            gpioDelay(100000);
            continue;
        }

        int speed1 = map_potentiometer_to_speed(pot1);
        int speed2 = map_potentiometer_to_speed(pot2);

        /* Accelerate */
        accelerate_motor(1, speed1);
        accelerate_motor(2, speed2);

        /* Hold speed for 2 seconds */
        gpioDelay(SPEED_HOLD_DELAY_US);

        /* Decelerate */
        decelerate_motor(1);
        decelerate_motor(2);

        /* Pause for 5 seconds */
        gpioDelay(LOOP_DELAY_US);

        /* Reverse direction */
        set_motor_direction(1, 1);
        set_motor_direction(2, 0);

        /* Accelerate */
        accelerate_motor(1, speed1);
        accelerate_motor(2, speed2);

        /* Hold speed for 2 seconds */
        gpioDelay(SPEED_HOLD_DELAY_US);

        /* Decelerate */
        decelerate_motor(1);
        decelerate_motor(2);

        /* Pause for 5 seconds */
        gpioDelay(LOOP_DELAY_US);

        /* Restore forward direction */
        set_motor_direction(1, 0);
        set_motor_direction(2, 1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

