#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LED_PIN 17
#define SOUND_THRESHOLD 500
#define DEBOUNCE_DELAY_MS 10
#define CALIBRATION_DURATION 5
#define SAMPLE_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calibrate_noise_level(int duration) {
    int sum = 0;
    int samples = 0;
    time_t start = time(NULL);

    while (running && (time(NULL) - start) < duration) {
        int val = read_mcp3008(0);
        if (val < 0) return -1;
        sum += val;
        samples++;
        gpioDelay(SAMPLE_DELAY_US);
    }

    if (samples == 0) return -1;
    return sum / samples;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Calibrating noise level for %d seconds...\n", CALIBRATION_DURATION);
    int baseline = calibrate_noise_level(CALIBRATION_DURATION);
    if (baseline < 0) {
        fprintf(stderr, "Calibration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Noise level calibrated: %d\n", baseline);

    while (running) {
        int sound_level = read_mcp3008(0);
        if (sound_level < 0) {
            fprintf(stderr, "Failed to read sound level\n");
            break;
        }

        if (sound_level > baseline + SOUND_THRESHOLD) {
            gpioWrite(LED_PIN, 1);
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            while (running) {
                int val = read_mcp3008(0);
                if (val < 0) break;
                if (val <= baseline + SOUND_THRESHOLD) {
                    gpioWrite(LED_PIN, 0);
                    break;
                }
                gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            }
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

