    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Calibrating noise level for %d seconds...\n", CALIBRATION_DURATION);
    int baseline = calibrate_noise_level(CALIBRATION_DURATION);
    if (baseline < 0) {
        fprintf(stderr, "Calibration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Noise level calibrated: %d\n", baseline);

    while (running) {
        int sound_level = read_mcp3008(0);
        if (sound_level < 0) {
            fprintf(stderr, "Failed to read sound level\n");
            break;
        }

        if (sound_level > baseline + SOUND_THRESHOLD) {
            gpioWrite(LED_PIN, 1);
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            while (running) {
                int val = read_mcp3008(0);
                if (val < 0) break;
                if (val <= baseline + SOUND_THRESHOLD) {
                    gpioWrite(LED_PIN, 0);
                    break;
                }
                gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            }
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

