#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>
#include <linux/gpio/consumer.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define GPIO_CS_OFFSET  8
#define LOG_FILE        "audio_log.txt"
#define SAMPLE_RATE_HZ  1000
#define SAMPLE_PERIOD_NS (1000000000ULL / SAMPLE_RATE_HZ)
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int spi_open(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("open(SPI device)");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return -1;
    }

    return fd;
}

static int gpio_request_cs(const char *chip_path, unsigned int offset)
{
    int fd = open(chip_path, O_RDWR);
    if (fd < 0) {
        perror("open(GPIO chip)");
        return -1;
    }

    struct gpiohandle_request req;
    memset(&req, 0, sizeof(req));
    req.lineoffsets[0] = offset;
    req.flags = GPIOHANDLE_REQUEST_OUTPUT;
    req.default_values[0] = 1;
    req.consumer_label = "mcp3008_cs";
    req.lines = 1;

    if (ioctl(fd, GPIO_GET_LINEHANDLE_IOCTL, &req) < 0) {
        perror("ioctl(GPIO_GET_LINEHANDLE_IOCTL)");
        close(fd);
        return -1;
    }

    return req.fd;
}

static int mcp3008_read(int spi_fd, int cs_fd, uint8_t channel, uint16_t *out)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    *out = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

int main(void)
{
    int spi_fd = -1;
    int cs_fd = -1;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() < 0) {
        goto cleanup;
    }

    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        goto cleanup;
    }

    cs_fd = gpio_request_cs(GPIO_CHIP, GPIO_CS_OFFSET);
    if (cs_fd < 0) {
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "w");
    if (!log_fp) {
        perror("fopen(log)");
        goto cleanup;
    }

    struct timespec next_deadline;
    clock_gettime(CLOCK_MONOTONIC, &next_deadline);

    while (g_running) {
        next_deadline.tv_nsec += SAMPLE_PERIOD_NS;
        if (next_deadline.tv_nsec >= 1000000000L) {
            next_deadline.tv_sec += 1;
            next_deadline.tv_nsec -= 1000000000L;
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        if (now.tv_sec > next_deadline.tv_sec ||
            (now.tv_sec == next_deadline.tv_sec && now.tv_nsec > next_deadline.tv_nsec)) {
            next_deadline = now;
        }

        struct timespec sleep_ts;
        sleep_ts.tv_sec = next_deadline.tv_sec - now.tv_sec;
        sleep_ts.tv_nsec = next_deadline.tv_nsec - now.tv_nsec;
        if (sleep_ts.tv_nsec < 0) {
            sleep_ts.tv_sec -= 1;
            sleep_ts.tv_nsec += 1000000000L;
        }

        if (sleep_ts.tv_sec > 0 || sleep_ts.tv_nsec > 0) {
            nanosleep(&sleep_ts, NULL);
        }

        if (!g_running) {
            break;
        }

        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
        uint64_t ts_ns = (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;

        uint16_t adc_value = 0;
        if (mcp3008_read(spi_fd, cs_fd, 0, &adc_value) < 0) {
            fprintf(stderr, "ADC read failed\n");
            continue;
        }

        if (fprintf(log_fp, "%llu|%u\n", (unsigned long long)ts_ns, adc_value) < 0) {
            perror("fprintf");
            goto cleanup;
        }

        if (fflush(log_fp) != 0) {
            perror("fflush");
            goto cleanup;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp) {
        fclose(log_fp);
    }
    if (cs_fd >= 0) {
        close(cs_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return ret;
}

