#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0

#define X_CHANNEL 0
#define Y_CHANNEL 1
#define Z_CHANNEL 2

#define VCC 3.3
#define SENSITIVITY 0.3
#define OFFSET 0.5

#define DT 0.1
#define Q 0.001
#define R 0.01

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

typedef struct {
    double x, y, z;
    double Pxx, Pyy, Pzz;
} KalmanState;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static double kalman_update(double measurement, double *state, double *P, double Q, double R) {
    *P = *P + Q;
    double K = *P / (*P + R);
    double new_state = *state + K * (measurement - *state);
    *P = (1.0 - K) * *P;
    *state = new_state;
    return new_state;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    KalmanState state = {0};
    state.Pxx = state.Pyy = state.Pzz = 0.1;

    while (running) {
        int x_raw = read_mcp3008(X_CHANNEL);
        int y_raw = read_mcp3008(Y_CHANNEL);
        int z_raw = read_mcp3008(Z_CHANNEL);

        if (x_raw < 0 || y_raw < 0 || z_raw < 0) {
            fprintf(stderr, "Error reading ADC values. Retrying...\n");
            time_sleep(0.1);
            continue;
        }

        double x_v = (x_raw / 1023.0) * VCC;
        double y_v = (y_raw / 1023.0) * VCC;
        double z_v = (z_raw / 1023.0) * VCC;

        double x_g = (x_v - OFFSET) / SENSITIVITY;
        double y_g = (y_v - OFFSET) / SENSITIVITY;
        double z_g = (z_v - OFFSET) / SENSITIVITY;

        state.x = kalman_update(x_g, &state.x, &state.Pxx, Q, R);
        state.y = kalman_update(y_g, &state.y, &state.Pyy, Q, R);
        state.z = kalman_update(z_g, &state.z, &state.Pzz, Q, R);

        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", state.x, state.y, state.z);
        fflush(stdout);

        time_sleep(DT);
    }

    cleanup();
    return EXIT_SUCCESS;
}

