#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_US 100000
#define VOLTAGE_HIGH 3.3
#define VOLTAGE_LOW 0.0
#define MIN_FIELD_MT -100.0
#define MAX_FIELD_MT 100.0

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, pigpio_error(value));
        return -1;
    }
    return value;
}

static double calculate_magnetic_field(int sensor_value) {
    double voltage = (sensor_value == 1) ? VOLTAGE_HIGH : VOLTAGE_LOW;
    return voltage * 100.0;
}

static int log_data(double sensor1_mT, double sensor2_mT, double sensor3_mT) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }
    fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    fflush(fp);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR3_GPIO, PI_INPUT);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Magnetic field monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = read_sensor(SENSOR1_GPIO);
        int sensor2_value = read_sensor(SENSOR2_GPIO);
        int sensor3_value = read_sensor(SENSOR3_GPIO);

        if (sensor1_value < 0 || sensor2_value < 0 || sensor3_value < 0) {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double sensor1_mT = calculate_magnetic_field(sensor1_value);
        double sensor2_mT = calculate_magnetic_field(sensor2_value);
        double sensor3_mT = calculate_magnetic_field(sensor3_value);

        if (sensor1_mT < MIN_FIELD_MT || sensor1_mT > MAX_FIELD_MT ||
            sensor2_mT < MIN_FIELD_MT || sensor2_mT > MAX_FIELD_MT ||
            sensor3_mT < MIN_FIELD_MT || sensor3_mT > MAX_FIELD_MT) {
            fprintf(stderr, "Warning: Magnetic field out of range: s1=%.2f, s2=%.2f, s3=%.2f\n",
                    sensor1_mT, sensor2_mT, sensor3_mT);
        }

        if (log_data(sensor1_mT, sensor2_mT, sensor3_mT) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioTerminate();
    printf("Magnetic field monitoring stopped.\n");
    return EXIT_SUCCESS;
}

