#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      500000
#define SPI_FLAGS      0
#define PUMP_GPIO      17
#define MOISTURE_THRESHOLD 30
#define LOG_FILE       "watering.log"
#define SAMPLE_INTERVAL 60

static volatile sig_atomic_t g_running = 1;

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[unknown time] %s\n", message);
    }
    fclose(fp);
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Invalid channel requested");
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };
    int ret = spiXfer(SPI_CHANNEL, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        log_event("SPI transfer failed");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int adc_to_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) return -1;
    return (int)(((float)adc_value / 1023.0f) * 100.0f);
}

static void control_pump(int moisture_level) {
    static int pump_state = -1;
    int new_state = (moisture_level < MOISTURE_THRESHOLD) ? 1 : 0;
    if (new_state != pump_state) {
        if (gpioWrite(PUMP_GPIO, new_state) == 0) {
            pump_state = new_state;
            log_event(new_state ? "Pump turned ON" : "Pump turned OFF");
        } else {
            log_event("Failed to write pump GPIO");
        }
    }
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set pump GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioWrite(PUMP_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Program started");

    while (g_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_event("ADC read failed, skipping cycle");
        } else {
            int moisture_level = adc_to_moisture(adc_value);
            if (moisture_level < 0) {
                log_event("Invalid ADC value, skipping cycle");
            } else {
                char msg[128];
                snprintf(msg, sizeof(msg), "Moisture level: %d%%", moisture_level);
