    if (!payload_copy) {
        log_error("Failed to allocate memory for payload copy");
        return;
    }
    memcpy(payload_copy, payload, payload_len);
    payload_copy[payload_len] = '\0';

    JSONValue *json_value = parse_json(payload_copy);
    free(payload_copy);

    if (!json_value) {
        log_error("Failed to parse JSON payload");
        return;
    }

    if (json_value->type != JSON_OBJECT) {
        log_error("Invalid JSON format: root is not an object");
        free_json_value(json_value);
        return;
    }

    JSONValue *led_state_value = get_json_object_value(json_value, "led_state");
    if (!led_state_value) {
        log_error("Missing 'led_state' key in JSON payload");
        free_json_value(json_value);
        return;
    }

    if (led_state_value->type != JSON_BOOLEAN) {
        log_error("Invalid type for 'led_state': expected boolean");
        free_json_value(json_value);
        return;
    }

    bool led_state = led_state_value->boolean_value;
    int rc = gpioWrite(GPIO_PIN, led_state ? 1 : 0);
    if (rc != 0) {
        log_error("Failed to write to GPIO pin");
    } else {
        printf("LED set to %s\n", led_state ? "ON" : "OFF");
    }

    free_json_value(json_value);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    if (gpioWrite(GPIO_PIN, 0) != 0) {
        log_error("Failed to set initial GPIO state");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

static int connect_mqtt(void) {
    g_mqtt_client = MQTTClient_create(MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, MQTT_CLIENT_ID);
    if (!g_mqtt_client) {
        log_error("Failed to create MQTT client");
        return -1;
    }

    if (MQTTClient_set_connection_callback(g_mqtt_client, mqtt_connection_callback, NULL) != MQTTCLIENT_SUCCESS) {
        log_error("Failed to set connection callback");
        MQTTClient_destroy(g_mqtt_client);
        g_mqtt_client = NULL;
        return -1;
    }

    if (MQTTClient_set_message_callback(g_mqtt_client, mqtt_message_callback, NULL) != MQTTCLIENT_SUCCESS) {
        log_error("Failed to set message callback");
        MQTTClient_destroy(g_mqtt_client);
        g_mqtt_client = NULL;
        return -1;
    }

    if (MQTTClient_connect(g_mqtt_client) != MQTTCLIENT_SUCCESS) {
        log_error("Failed to connect to MQTT broker");
        MQTTClient_destroy(g_mqtt_client);
        g_mqtt_client = NULL;
        return -1;
    }

    g_mqtt_connected = 1;
    return 0;
}

static void disconnect_mqtt(void) {
    if (g_mqtt_client) {
        MQTTClient_disconnect(g_mqtt_client);
        MQTTClient_destroy(g_mqtt_client);
        g_mqtt_client = NULL;
        g_mqtt_connected = 0;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_error("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("Failed to register SIGTERM handler");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    if (connect_mqtt() != 0) {
        cleanup_gpio();
        return 1;
    }

    printf("LED control system started. Listening on %s\n", MQTT_TOPIC);

    while (g_running) {
        if (g_mqtt_connected) {
            g_reconnect_delay = INITIAL_RECONNECT_DELAY;
        } else {
            disconnect_mqtt();
            sleep(g_reconnect_delay);
            if (connect_mqtt() != 0) {
                g_reconnect_delay *= 2;
                if (g_reconnect_delay > MAX_RECONNECT_DELAY) {
                    g_reconnect_delay = MAX_RECONNECT_DELAY;
                }
            }
        }
        sleep(1);
    }

    printf("\nShutting down...\n");
    disconnect_mqtt();
    cleanup_gpio();
    printf("Cleanup complete. Exiting.\n");
    return 0;
}

