#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN    18
#define CHIP_NAME        "gpiochip4"
#define POLL_DELAY_MS    100
#define ALARM_DURATION_S 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sound_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (sound_line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", SOUND_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (led_line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", ALARM_LED_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(sound_line, "ky038-sound") < 0) {
        fprintf(stderr, "Failed to request sound sensor line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "ky038-alarm", 0) < 0) {
        fprintf(stderr, "Failed to request alarm LED line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Monitoring sound sensor on GPIO%d (DO). Press Ctrl+C to exit.\n", SOUND_SENSOR_PIN);

    while (program_running) {
        int val = gpiod_line_get_value(sound_line);
        if (val < 0) {
            fprintf(stderr, "Error reading sound sensor: %s\n", strerror(errno));
            goto cleanup;
        }

        printf("Sound Level: %d\n", val);

        if (val == 0) {
            printf("Sound detected! Triggering alarm.\n");
            if (gpiod_line_set_value(led_line, 1) < 0) {
                fprintf(stderr, "Failed to turn on alarm LED: %s\n", strerror(errno));
                goto cleanup;
            }
            sleep(ALARM_DURATION_S);
            if (gpiod_line_set_value(led_line, 0) < 0) {
                fprintf(stderr, "Failed to turn off alarm LED: %s\n", strerror(errno));
                goto cleanup;
            }
        }

        usleep(POLL_DELAY_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line != NULL) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (sound_line != NULL) {
        gpiod_line_release(sound_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

