/*
 * SW-420 vibration-triggered shutdown monitor for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SW-420 VCC  -> 3V3 (pin 1)
 *   SW-420 GND  -> GND (pin 9)
 *   SW-420 DO   -> GPIO17 (BCM, pin 11)
 *
 * The SW-420 DO output is active-low (open-collector): idle HIGH, pulls LOW
 * when vibration exceeds the threshold.  We request falling-edge events so
 * that every DO transition to LOW is captured.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vibration_shutdown vibration_shutdown.c
 *
 * Run (requires root for /dev/gpiochip0 access and shutdown):
 *   sudo ./vibration_shutdown
 */

#include <errno.h>
#include <fcntl.h>
#include <gpiod.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#define GPIO_CHIP_NAME  "/dev/gpiochip0"
#define GPIO_LINE_OFFSET 17          /* BCM 17, physical pin 11 */
#define LOG_FILE        "/var/log/vibration_shutdown.log"
#define CONSUMER_LABEL  "vibration-monitor"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_event(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, message) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Shutdown                                                            */
/* ------------------------------------------------------------------ */
static void initiate_shutdown(void)
{
    printf("Vibration detected! Initiating shutdown...\n");
    fflush(stdout);

    if (log_event("Vibration detected! Initiating shutdown.") != 0) {
        fprintf(stderr, "Warning: failed to log shutdown event.\n");
    }

    int rc = system("sudo shutdown -h now");
    if (rc == -1) {
        perror("system(shutdown)");
    } else if (rc != 0) {
        fprintf(stderr, "shutdown command returned status %d\n", rc);
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open(" GPIO_CHIP_NAME ")");
        return EXIT_FAILURE;
    }

    /* Get the line for BCM 17 */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line()");
        goto cleanup;
    }

    /* Request falling-edge events on the line (SW-420 DO is active-low) */
    if (gpiod_line_request_falling_edge_events(line, CONSUMER_LABEL) < 0) {
        perror("gpiod_line_request_falling_edge_events()");
        goto cleanup;
    }

    printf("Vibration monitoring started on GPIO%d (BCM). Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);
    fflush(stdout);

    /* Main event loop */
    while (g_running) {
        /* Block for up to 1 s so we can re-check g_running periodically */
        int ev = gpiod_line_event_wait(line, &(struct timespec){1, 0});
        if (ev < 0) {
            if (errno == EINTR) {
                continue;  /* signal interrupted — re-check g_running */
            }
            perror("gpiod_line_event_wait()");
            goto cleanup;
        }
        if (ev == 0) {
            continue;  /* timeout, no event */
        }

        /* Read the event to clear it from the kernel buffer */
        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            perror("gpiod_line_event_read()");
            goto cleanup;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            initiate_shutdown();
            break;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("Vibration monitoring stopped.\n");
    }
    return ret;
}

