    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int i2c_init(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MCP4725_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MCP4725_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float convert_to_celsius(int adc_value) {
    return (adc_value * 5.0f / 1024.0f) - 40.0f;
}

static int write_mcp4725(float voltage) {
    if (voltage < 0.0f || voltage > 5.0f) {
        fprintf(stderr, "Invalid DAC voltage: %.2f V\n", voltage);
        return -1;
    }

    uint16_t dac_value = (uint16_t)((voltage / 5.0f) * 4095.0f);
    uint8_t tx[3] = { 0x40, (uint8_t)((dac_value >> 8) & 0xFF), (uint8_t)(dac_value & 0xFF) };

    if (write(i2c_fd, tx, 3) != 3) {
        fprintf(stderr, "Error writing to MCP4725: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int log_temperature(float temperature, int adc_value, float dac_voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
            return -1;
        }
    }

    if (fprintf(log_file, "%s, ADC: %d, Temp: %.2f C, DAC: %.2f V\n", timestamp, adc_value, temperature, dac_voltage) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        cleanup();
        return 1;
    }

    if (i2c_init() < 0) {
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = -1;
        float temperature = -1000.0f;
        float dac_voltage = -1.0f;
        int retries = 0;

        while (retries < MAX_RETRIES && running) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value >= 0) {
                temperature = convert_to_celsius(adc_value);
                dac_voltage = temperature + 40.0f;
                if (dac_voltage < 0.0f) dac_voltage = 0.0f;
                if (dac_voltage > 5.0f) dac_voltage = 5.0f;

                if (write_mcp4725(dac_voltage) == 0) {
                    break;
                }
            } else {
                fprintf(stderr, "Error reading ADC or writing DAC. Retrying (%d/%d)...\n", retries + 1, MAX_RETRIES);
            }
            retries++;
            usleep(100000);
        }

        if (adc_value >= 0 && temperature > -999.0f && dac_voltage >= 0.0f) {
            if (log_temperature(temperature, adc_value, dac_voltage) < 0) {
                fprintf(stderr, "Error logging temperature data.\n");
            }
            printf("ADC: %d, Temp: %.2f C, DAC: %.2f V\n", adc_value, temperature, dac_voltage);
        } else {
            fprintf(stderr, "Failed to read ADC or write DAC after %d retries. Skipping sample.\n", MAX_RETRIES);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

