#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

#define RELAY_ACTIVE 1
#define RELAY_INACTIVE 0

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(pins[i], RELAY_INACTIVE) != 0) {
            fprintf(stderr, "Error: failed to initialise GPIO %d to LOW\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void deactivate_all_relays(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioWrite(pins[i], RELAY_INACTIVE) != 0) {
            fprintf(stderr, "Warning: failed to deactivate relay on GPIO %d\n", pins[i]);
        }
    }
}

static void cleanup_gpio(void) {
    deactivate_all_relays();
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    size_t num_pins = sizeof(pins) / sizeof(pins[0]);

    while (program_running) {
        for (size_t i = 0; i < num_pins && program_running; i++) {
            if (gpioWrite(pins[i], RELAY_ACTIVE) != 0) {
                fprintf(stderr, "Error: failed to activate relay on GPIO %d\n", pins[i]);
                cleanup_gpio();
                return EXIT_FAILURE;
            }
            printf("Relay %zu (GPIO %d) activated\n", i + 1, pins[i]);
            fflush(stdout);

            sleep(1);

            if (gpioWrite(pins[i], RELAY_INACTIVE) != 0) {
                fprintf(stderr, "Error: failed to deactivate relay on GPIO %d\n", pins[i]);
                cleanup_gpio();
                return EXIT_FAILURE;
            }
            printf("Relay %zu (GPIO %d) deactivated\n", i + 1, pins[i]);
            fflush(stdout);

            if (i < num_pins - 1 && program_running) {
                sleep(1);
            }
        }
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

