#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0

#define RAIN_THRESHOLD 5
#define MOTOR_FORWARD 1
#define MOTOR_BACKWARD 0
#define MOTOR_PWM_DUTY 150
#define MOTOR_PWM_RANGE 255
#define MOTOR_RUN_TIME 3

#define IN1 17
#define IN2 18
#define ENA 27

static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    int bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int init_motor_driver(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(IN1, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set IN1 mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(IN2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set IN2 mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ENA, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set ENA mode\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(ENA, MOTOR_PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return -1;
    }
    if (gpioPWM(ENA, 0) < 0) {
        fprintf(stderr, "Failed to set initial PWM duty\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void control_motor(int direction) {
    if (direction == MOTOR_FORWARD) {
        if (gpioWrite(IN1, 1) < 0) return;
        if (gpioWrite(IN2, 0) < 0) return;
    } else {
        if (gpioWrite(IN1, 0) < 0) return;
        if (gpioWrite(IN2, 1) < 0) return;
    }

    if (gpioPWM(ENA, MOTOR_PWM_DUTY) < 0) return;

    time_sleep(MOTOR_RUN_TIME);

    if (gpioPWM(ENA, 0) < 0) return;
}

static void log_data(int rain_level, int window_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Rain Level: %d, Window State: %d\n", timestamp, rain_level, window_state);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_spi() < 0) {
        return 1;
    }

    if (init_motor_driver() < 0) {
        close(spi_fd);
        spi_fd = -1;
        return 1;
    }

    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    int window_state = 1; /* Assume window is initially open */

    while (program_running) {
        int rain_level = read_mcp3008(0);
        if (rain_level < 0) {
            fprintf(stderr, "Error reading rain sensor, retrying...\n");
            time_sleep(1.0);
            continue;
        }

        log_data(rain_level, window_state);

        if (rain_level > RAIN_THRESHOLD) {
            if (window_state == 1) {
                control_motor(MOTOR_BACKWARD);
                window_state = 0;
                log_data(rain_level, window_state);
            }
        } else {
            if (window_state == 0) {
                control_motor(MOTOR_FORWARD);
                window_state = 1;
                log_data(rain_level, window_state);
            }
        }

        time_sleep(1.0);
    }

    /* Stop motor before cleanup */
    gpioPWM(ENA, 0);

    cleanup();
    return 0;
}

