/*
 * Clap Detector using MAX9814 (AGC) and bit-banged ADC on Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - MAX9814 electret microphone amplifier with AGC (analog output)
 *   - Bit-banged ADC sampling on BCM GPIO26 (CLK) and BCM GPIO16 (DATA)
 *   - LED on BCM GPIO16 (active-high)
 *
 * Behavior:
 *   - Continuously samples the ADC; when a clap is detected (peak > threshold
 *     and within the debounce interval), the LED is turned on for 500 ms and
 *     a timestamped message is printed.
 *   - SIGINT (Ctrl+C) triggers a clean shutdown: LED off, resources released.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define ADC_CLK_PIN  26
#define ADC_DATA_PIN 16
#define LED_PIN      16

#define CLAP_THRESHOLD  1000
#define DEBOUNCE_MS     50
#define LED_ON_MS       500
#define SAMPLE_DELAY_US 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a 10-bit value from the MAX9814 via bit-banged SPI.
 * Returns 0-1023 on success, -1 on error.
 */
static int read_adc(void) {
    uint16_t value = 0;

    /* Start bit: CLK low, DATA low */
    if (gpioWrite(ADC_CLK_PIN, 0) < 0) return -1;
    if (gpioDelay(1) < 0) return -1;
    if (gpioWrite(ADC_DATA_PIN, 0) < 0) return -1;
    if (gpioDelay(1) < 0) return -1;

    /* Read 10 data bits (MSB first) */
    for (int i = 0; i < 10; i++) {
        if (gpioWrite(ADC_CLK_PIN, 1) < 0) return -1;
        if (gpioDelay(1) < 0) return -1;

        int bit = gpioRead(ADC_DATA_PIN);
        if (bit < 0) return -1;

        value = (value << 1) | (uint16_t)bit;

        if (gpioWrite(ADC_CLK_PIN, 0) < 0) return -1;
        if (gpioDelay(1) < 0) return -1;
    }

    /* Read 2 null bits to complete the frame */
    for (int i = 0; i < 2; i++) {
        if (gpioWrite(ADC_CLK_PIN, 1) < 0) return -1;
        if (gpioDelay(1) < 0) return -1;
        if (gpioWrite(ADC_CLK_PIN, 0) < 0) return -1;
        if (gpioDelay(1) < 0) return -1;
    }

    return (int)value;
}

static void log_clap(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Clap detected!\n", timestamp);
    fflush(stdout);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure ADC pins */
    if (gpioSetMode(ADC_CLK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set ADC_CLK_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ADC_DATA_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set ADC_DATA_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set LED_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to initialize LED_PIN state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set SIGINT handler\n");
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Clap detection started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    uint32_t last_clap_tick = 0;

    while (running) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed (sensor absent or bus error)\n");
            break;
        }

        if (adc_value > CLAP_THRESHOLD) {
            uint32_t current_tick = gpioTick();
            if (current_tick - last_clap_tick > DEBOUNCE_MS * 1000) {
                log_clap();
                last_clap_tick = current_tick;

                if (gpioWrite(LED_PIN, 1) < 0) {
                    fprintf(stderr, "Error: Failed to turn on LED\n");
                    break;
                }
                gpioDelay(LED_ON_MS * 1000);
                if (gpioWrite(LED_PIN, 0) < 0) {
                    fprintf(stderr, "Error: Failed to turn off LED\n");
                    break;
                }
            }
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    /* Clean up */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

