#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 200
#define LOG_FILE "distance_log.txt"
#define GPIO_EXPORT_PATH "/sys/class/gpio/export"
#define GPIO_UNEXPORT_PATH "/sys/class/gpio/unexport"
#define GPIO_DIRECTION_PATH "/sys/class/gpio/gpio%d/direction"
#define GPIO_VALUE_PATH "/sys/class/gpio/gpio%d/value"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int gpio_export(int pin) {
    FILE *fp = fopen(GPIO_EXPORT_PATH, "w");
    if (fp == NULL) {
        perror("Error opening GPIO export file");
        return -1;
    }
    if (fprintf(fp, "%d", pin) < 0) {
        perror("Error writing to GPIO export file");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

int gpio_unexport(int pin) {
    FILE *fp = fopen(GPIO_UNEXPORT_PATH, "w");
    if (fp == NULL) {
        perror("Error opening GPIO unexport file");
        return -1;
    }
    if (fprintf(fp, "%d", pin) < 0) {
        perror("Error writing to GPIO unexport file");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    snprintf(path, sizeof(path), GPIO_DIRECTION_PATH, pin);
    FILE *fp = fopen(path, "w");
    if (fp == NULL) {
        perror("Error opening GPIO direction file");
        return -1;
    }
    if (fprintf(fp, "%s", direction) < 0) {
        perror("Error writing to GPIO direction file");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

int gpio_read_value(int pin) {
    char path[64];
    snprintf(path, sizeof(path), GPIO_VALUE_PATH, pin);
    FILE *fp = fopen(path, "r");
    if (fp == NULL) {
        perror("Error opening GPIO value file");
        return -1;
    }
    int value = fgetc(fp);
    fclose(fp);
    if (value == '0') return 0;
    if (value == '1') return 1;
    return -1;
}

int log_distance(int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s, Distance: %d mm\n", timestamp, distance) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Error setting SIGTERM handler");
        return 1;
    }

    if (gpio_export(GPIO_PIN) == -1) {
        fprintf(stderr, "Failed to export GPIO %d\n", GPIO_PIN);
        return 1;
    }
    if (gpio_set_direction(GPIO_PIN, "in") == -1) {
        fprintf(stderr, "Failed to set GPIO %d direction\n", GPIO_PIN);
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    printf("Distance sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int distance = gpio_read_value(GPIO_PIN);
        if (distance == -1) {
            fprintf(stderr, "Error reading GPIO %d, retrying in 1 second...\n", GPIO_PIN);
            sleep(1);
            continue;
        }

        if (log_distance(distance) == -1) {
            fprintf(stderr, "Error logging distance, retrying in 1 second...\n");
            sleep(1);
            continue;
        }

        if (distance < DISTANCE_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(1);
    }

    gpio_unexport(GPIO_PIN);
    printf("Distance sensor monitoring stopped.\n");
    return 0;
}

