#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30.0
#define LOG_FILE "soil_moisture.log"
#define SAMPLE_INTERVAL 60

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_moisture(int adc_value) {
    if (adc_value < 0) return -1.0f;
    if (adc_value > 1023) return 100.0f;
    return ((float)adc_value / 1023.0f) * 100.0f;
}

static void control_pump(float moisture) {
    int state = (moisture < MOISTURE_THRESHOLD) ? 1 : 0;
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Failed to write pump GPIO\n");
    }
}

static void log_data(float moisture, int pump_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Moisture: %.2f%%, Pump: %s\n",
            timestamp, moisture, pump_state ? "ON" : "OFF");
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set pump GPIO mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register signal handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Sensor read failed, retrying in %d seconds\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float moisture = adc_to_moisture(adc_value);
        control_pump(moisture);
        log_data(moisture, gpioRead(PUMP_GPIO));

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

