/*
 * DRV5055-A1 Hall-effect sensor reader via MCP3008 ADC on Raspberry Pi Zero W.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V
 *   MCP3008 VREF -> 3.3 V
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (BCM 11, SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO10 (BCM 10, SPI0 MISO)
 *   MCP3008 DIN  -> GPIO9  (BCM 9,  SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (BCM 8,  SPI0 CE0)
 *   MCP3008 CH0  -> DRV5055-A1 VOUT
 *   DRV5055-A1 VCC -> 3.3 V
 *   DRV5055-A1 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o drv5055_log drv5055_log.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000U
#define SPI_BITS_PER_WORD 8U
#define SPI_MODE          0U

#define GPIO_CHIP_NAME    "gpiochip0"
#define CS_BCM_PIN        8U          /* BCM 8 -> SPI0 CE0 */

#define ADC_CHANNEL       0U
#define ADC_MAX           1023U       /* 10-bit ADC */
#define VREF_MV           3300U       /* 3.3 V reference */
#define SAMPLE_PERIOD_MS  500U
#define LOG_FILE          "magnetic_log.txt"

/*
 * DRV5055-A1 transfer function (mT per mV).
 * 3.3 V -> ~1023 counts -> ~3300 mV VOUT.
 * With 3.3 V VREF, 1023 counts -> 3300 mV.
 * Transfer: B(mT) = VOUT(mV) * 0.00012345679  (approx 1/8000).
 * Using integer arithmetic: B(mT) = VOUT(mV) * 12345679 / 1000000000.
 * Simplify: B(mT) = VOUT(mV) * 12345679 / 1000000000 -> B(mT) = VOUT(mV) * 12345679 / 1000000000.
 * For two-decimal output, scale by 100: B(mT*100) = VOUT(mV) * 12345679 / 1000000000 * 100.
 * Simplify: B(mT*100) = VOUT(mV) * 12345679 / 10000000.
 */
#define B_PER_VOUT_MV     12345679L
#define B_SCALE           10000000L

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0-1023 on success, -1 on error.
 */
static int mcp3008_read(int spi_fd, struct gpiod_line *cs_line, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI frame (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  -> single-ended + channel, upper nibble
     *   Byte 2: 0x00  (don't care, clocks out low 8 bits)
     *
     * Response:
     *   rx[0] = ignored
     *   rx[1] = [null, null, null, B2, B1, B0, B9, B8]  -> bits 9..8
     *   rx[2] = bits 7..0
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("gpiod_line_set_value(CS low)");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        gpiod_line_set_value(cs_line, 1); /* best-effort CS release */
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("gpiod_line_set_value(CS high)");
        return -1;
    }

    int raw = ((rx[1] & 0x03) << 8) | rx[2];
    return raw;
}

static int spi_init(int *spi_fd_out)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(fd);
        return -1;
    }

    *spi_fd_out = fd;
    return 0;
}

int main(void)
{
    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() < 0) {
        goto cleanup;
    }

    /* Open GPIO chip and request CS line */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, CS_BCM_PIN);
    if (!cs_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "drv5055_log", 1) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    /* Initialize SPI */
    if (spi_init(&spi_fd) < 0) {
        goto cleanup;
    }

    /* Open log file */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

    printf("DRV5055-A1 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int raw = mcp3008_read(spi_fd, cs_line, ADC_CHANNEL);
        if (raw < 0) {
            fprintf(stderr, "ADC read failed; skipping sample\n");
        } else {
            /*
             * Convert raw 10-bit value to mV.
             * VREF = 3300 mV, 1023 counts = full-scale.
             * VOUT_mV = raw * 3300 / 1023.
             */
            long vout_mv = (long)raw * VREF_MV / (long)ADC_MAX;

            /*
             * Convert VOUT (mV) to magnetic field strength (mT).
             * B(mT) = VOUT(mV) * 12345679 / 1000000000.
             * For two-decimal output, scale by 100:
             *   B(mT*100) = VOUT(mV) * 12345679 / 10000000.
             */
            long b_mt_scaled = vout_mv * B_PER_VOUT_MV / B_SCALE;

            time_t now = time(NULL);
            if (now == (time_t)-1) {
                perror("time");
            } else {
                if (fprintf(log_fp, "%ld,%ld\n", (long)now, b_mt_scaled) < 0) {
                    perror("fprintf");
                } else {
                    fflush(log_fp);
                }
            }

            printf("raw=%4d  VOUT=%5ld mV  B=%.2f mT\n",
                   raw, vout_mv, (double)b_mt_scaled / 100.0);
        }

        /* Sleep SAMPLE_PERIOD_MS, but wake early on signal */
        for (int ms = 0; ms < SAMPLE_PERIOD_MS && g_running; ms += 10) {
            usleep(10000); /* 10 ms */
        }
    }

    printf("\nShutting down cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp) {
        fclose(log_fp);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

