#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <driverlib.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define LED_GPIO 21
#define THRESHOLD 10.0
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_US 100000

static int spi_fd = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (SPI_transfer(spi_fd, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_magnetic_field(int adc_value) {
    float voltage = (adc_value / 1023.0f) * 3.3f;
    return voltage * 10.0f;
}

static void log_data(float magnetic_field) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f mT\n", timestamp, magnetic_field);
    fclose(fp);
}

int main(void) {
    if (GPIO_setup() != 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    if (GPIO_setMode(LED_GPIO, GPIO_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED GPIO mode\n");
        GPIO_terminate();
        return 1;
    }
    GPIO_write(LED_GPIO, 0);

    spi_fd = SPI_open(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI channel %d: %s\n", SPI_CHANNEL, strerror(errno));
        GPIO_terminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        SPI_close(spi_fd);
        GPIO_terminate();
        return 1;
    }

    printf("Magnetic field monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, retrying...\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float magnetic_field = adc_to_magnetic_field(adc_value);
        log_data(magnetic_field);

        if (fabsf(magnetic_field) > THRESHOLD) {
            GPIO_write(LED_GPIO, 1);
        } else {
            GPIO_write(LED_GPIO, 0);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    GPIO_write(LED_GPIO, 0);
    SPI_close(spi_fd);
    GPIO_terminate();
    printf("Cleanup complete.\n");
    return 0;
}

