#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* Hardware connections (Raspberry Pi Zero W, SPI0):
 *   MCP3008 CE0  -> GPIO8  (physical 24, SPI0 CE0)
 *   MCP3008 VDD  -> Pi 5V  (physical 2 or 4)
 *   MCP3008 VREF -> Pi 3V3 (physical 1 or 17)
 *   MCP3008 AGND -> Pi GND (physical 6)
 *   MCP3008 DGND -> Pi GND (physical 6)
 *   MCP3008 CLK  -> GPIO11 (physical 23, SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (physical 21, SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (physical 19, SPI0 MOSI)
 *   MLX91211 VDD -> Pi 5V
 *   MLX91211 OUT -> MCP3008 CH0
 */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000          /* 1 MHz, mode 0 */
#define ADC_CHANNEL 0
#define VREF        3.3              /* MCP3008 VREF tied to Pi 3V3 */
#define LOG_FILE    "current_log.txt"
#define SAMPLE_US   100000           /* 100 ms */

/* Globals for cleanup in signal handler */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; async-signal-safe                    */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample from the MCP3008 (single-ended, channel 0–7).        */
/* Returns 0–1023 on success, -1 on error.                              */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer.
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (spiXfer returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
