#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_US 2000
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_debounced(int gpio_pin) {
    int high_count = 0;
    int low_count = 0;

    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int level = gpioRead(gpio_pin);
        if (level < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", gpio_pin);
            return -1;
        }
        if (level == 1) {
            high_count++;
        } else {
            low_count++;
        }
        if (i < DEBOUNCE_SAMPLES - 1) {
            gpioDelay(DEBOUNCE_DELAY_US);
        }
    }

    return (high_count > low_count) ? 1 : 0;
}

static void log_sensor_data(int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Sensor 1: %d, Sensor 2: %d\n", timestamp, sensor1_state, sensor2_state);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring sensors on GPIO %d and GPIO %d. Press Ctrl+C to exit.\n",
           SENSOR_1_GPIO, SENSOR_2_GPIO);
    fflush(stdout);

    while (running) {
        int sensor1_state = read_sensor_debounced(SENSOR_1_GPIO);
        int sensor2_state = read_sensor_debounced(SENSOR_2_GPIO);

        if (sensor1_state < 0 || sensor2_state < 0) {
            fprintf(stderr, "Error reading sensor data, exiting\n");
            break;
        }

        log_sensor_data(sensor1_state, sensor2_state);

        if (sensor1_state == 0 && sensor2_state == 0) {
            printf("ALERT: Both sensors detect object\n");
            fflush(stdout);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

