#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <driver_library.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

static int spi_handle = -1;
static volatile sig_atomic_t program_running = 1;

int read_mcp3008(int channel);
double calculate_moisture_level(int adc_value);
void log_data(double moisture_level);
void signal_handler(int signal);
int spi_setup(spi_config_t config);

int read_mcp3008(int channel) {
    unsigned char tx[3] = {0x01, (0x08 | channel) << 4, 0x00};
    unsigned char rx[3] = {0, 0, 0};
    if (spi_transfer(spi_handle, tx, rx, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) + rx[2];
}

double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC) adc_value = MIN_ADC;
    if (adc_value > MAX_ADC) adc_value = MAX_ADC;
    return 100.0 - ((double)(adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
}

void log_data(double moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    FILE *fp;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, moisture_level);
    fclose(fp);

    printf("%s,%.2f\n", timestamp, moisture_level);
}

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    if (spi_handle >= 0) {
        spi_close(spi_handle);
        spi_handle = -1;
    }
    driver_library_terminate();
    exit(0);
}

int spi_setup(spi_config_t config) {
    spi_handle = spi_open(config);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        driver_library_terminate();
        return -1;
    }
    return 0;
}

int main() {
    spi_config_t spi_config;
    spi_config.channel = SPI_CHANNEL;
    spi_config.baud = SPI_BAUD;

    if (driver_library_init() != 0) {
        fprintf(stderr, "Error: Driver library initialization failed\n");
        return 1;
    }

    if (spi_setup(spi_config) != 0) {
        fprintf(stderr, "Error: SPI setup failed\n");
        driver_library_terminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (program_running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            double moisture_level = calculate_moisture_level(adc_value);
            log_data(moisture_level);
        } else {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %d seconds...\n", READ_DELAY);
        }
        sleep(READ_DELAY);
    }

    if (spi_handle >= 0) {
        spi_close(spi_handle);
    }
    driver_library_terminate();
    return 0;
}

