#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>
#include <pigpio.h>

#define PIR_GPIO 17
#define DEBOUNCE_DELAY_US 200000
#define POLL_DELAY_US 50000
#define CAPTURE_DELAY_US 500000
#define IMAGE_DIR "/home/pi/security_cam/"
#define MAX_FILENAME_LEN 256
#define MAX_PATH_LEN 512

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        syslog(LOG_ERR, "Path '%s' exists but is not a directory", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0 && errno != EEXIST) {
        syslog(LOG_ERR, "Failed to create directory '%s': %s", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork() failed: %s", strerror(errno));
        return -1;
    }
    if (pid == 0) {
        char *const argv[] = {"libcamera-still", "-o", (char *)filename, "--nopreview", NULL};
        execvp("libcamera-still", argv);
        syslog(LOG_ERR, "execvp(libcamera-still) failed: %s", strerror(errno));
        _exit(127);
    }
    int status = 0;
    while (waitpid(pid, &status, 0) < 0) {
        if (errno == EINTR) continue;
        syslog(LOG_ERR, "waitpid() failed: %s", strerror(errno));
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) return 0;
    syslog(LOG_ERR, "libcamera-still exited with status %d", WIFEXITED(status) ? WEXITSTATUS(status) : -1);
    return -1;
}

int main(void) {
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction() failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as input", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        syslog(LOG_ERR, "Failed to set pull-down on GPIO%d", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (ensure_directory(IMAGE_DIR) != 0) {
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Security camera started on GPIO%d", PIR_GPIO);

    int last_state = 0;
    int motion_active = 0;

    while (program_running) {
        int current_state = gpioRead(PIR_GPIO);
        if (current_state < 0) {
            syslog(LOG_ERR, "gpioRead(%d) failed", PIR_GPIO);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (current_state != last_state) {
            gpioDelay(DEBOUNCE_DELAY_US);
            int confirmed = gpioRead(PIR_GPIO);
            if (confirmed < 0) {
                syslog(LOG_ERR, "gpioRead(%d) failed during debounce", PIR_GPIO);
                last_state = current_state;
                continue;
            }
            if (confirmed == current_state) {
                last_state = current_state;
                if (current_state == 1 && !motion_active) {
                    motion_active = 1;
                    syslog(LOG_INFO, "Motion detected on GPIO%d", PIR_GPIO);
                    time_t rawtime = time(NULL);
                    if (rawtime == (time_t)-1) {
                        syslog(LOG_ERR, "time() failed: %s", strerror(errno));
                    } else {
                        struct tm timeinfo;
                        if (localtime_r(&rawtime, &timeinfo) == NULL) {
                            syslog(LOG_ERR, "localtime_r() failed");
                        } else {
                            char timestamp[32];
                            if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H-%M-%S", &timeinfo) == 0) {
                                syslog(LOG_ERR, "strftime() failed");
                            } else {
                                char filename[MAX_FILENAME_LEN];
                                char filepath[MAX_PATH_LEN];
                                snprintf(filename, sizeof(filename), "motion_%s.jpg", timestamp);
                                snprintf(filepath, sizeof(filepath), "%s%s", IMAGE_DIR, filename);
                                syslog(LOG_INFO, "Capturing image: %s", filepath);
                                if (capture_image(filepath) == 0) {
                                    syslog(LOG_INFO, "Image captured successfully: %s", filepath);
                                } else {
                                    syslog(LOG_ERR, "Failed to capture image: %s", filepath);
                                }
                            }
                        }
                    }
                } else if (current_state == 0 && motion_active) {
                    motion_active = 0;
                    syslog(LOG_INFO, "Motion stopped on GPIO%d", PIR_GPIO);
                }
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    syslog(LOG_INFO, "Shutting down security camera");
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

