/*
 * V4L2 CSI camera capture → UDP fragment streamer for Raspberry Pi (BCM2711).
 *
 * Build:  gcc -O2 -Wall -Wextra -o cam_udp cam_udp.c
 * Run:    ./cam_udp <target_ip> <target_port>
 *
 * Captures YUYV frames from /dev/video0, fragments each frame into UDP
 * datagrams (max 65 000 bytes payload), and sends them to the given address.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE      "/dev/video0"
#define NUM_BUFFERS       4
#define UDP_MTU           65000
#define HEADER_SIZE       12          /* uint32_t frame_idx, frag_idx, frag_count, payload_size */
#define MAX_FRAG_PAYLOAD  (UDP_MTU - HEADER_SIZE)

typedef struct {
    uint32_t frame_idx;
    uint32_t frag_idx;
    uint32_t frag_count;
    uint32_t payload_size;
} __attribute__((packed)) udp_header_t;

typedef struct {
    char   *buffer;
    size_t  length;
    void   *start;
    size_t  offset;
    bool    mapped;
} buffer_t;

static volatile sig_atomic_t g_stop = 0;
static int g_fd = -1;
static buffer_t g_buffers[NUM_BUFFERS];
static int g_n_buffers = 0;
static int g_socket = -1;

static void handle_signal(int sig)
{
    (void)sig;
    g_stop = 1;
}

static void cleanup(void)
{
    if (g_socket != -1) {
        close(g_socket);
        g_socket = -1;
    }
    if (g_fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        ioctl(g_fd, VIDIOC_STREAMOFF, &type);
        for (int i = 0; i < g_n_buffers; i++) {
            if (g_buffers[i].mapped && g_buffers[i].start != MAP_FAILED)
                munmap(g_buffers[i].start, g_buffers[i].length);
        }
        close(g_fd);
        g_fd = -1;
    }
}

static int xioctl(int fd, unsigned long request, void *arg)
{
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(const char *device)
{
    g_fd = open(device, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(g_fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP: %s\n", strerror(errno));
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s does not support video capture\n", device);
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", device);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(g_fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT: %s\n", strerror(errno));
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(g_fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS: %s\n", strerror(errno));
        return -1;
    }
    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }
    g_n_buffers = (int)req.count;

    for (int i = 0; i < g_n_buffers; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = (unsigned int)i;
        if (xioctl(g_fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QUERYBUF(%d): %s\n", i, strerror(errno));
            return -1;
        }
        g_buffers[i].length = buf.length;
        g_buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE,
                                  MAP_SHARED, g_fd, buf.m.offset);
        if (g_buffers[i].start == MAP_FAILED) {
            fprintf(stderr, "mmap(%d): %s\n", i, strerror(errno));
            return -1;
        }
        g_buffers[i].mapped = true;
        g_buffers[i].buffer = NULL;
        g_buffers[i].offset = 0;
    }

    for (int i = 0; i < g_n_buffers; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = (unsigned int)i;
        if (xioctl(g_fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QBUF(%d): %s\n", i, strerror(errno));
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(g_fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_frame(void)
{
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(g_fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_DQBUF: %s\n", strerror(errno));
        return -1;
    }

    int idx = (int)buf.index;
    g_buffers[idx].buffer = (char *)g_buffers[idx].start;
    g_buffers[idx].offset = 0;
    g_buffers[idx].length = buf.bytesused;

    if (xioctl(g_fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QBUF: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int send_udp_fragment(const char *data, size_t size, uint32_t frame_idx,
                             uint32_t frag_idx, uint32_t frag_count)
{
    udp_header_t header;
    header.frame_idx  = frame_idx;
    header.frag_idx   = frag_idx;
    header.frag_count = frag_count;
    header.payload_size = (uint32_t)size;

    size_t total = HEADER_SIZE + size;
    char *packet = malloc(total);
    if (!packet) {
        fprintf(stderr, "malloc: %s\n", strerror(errno));
        return -1;
    }
    memcpy(packet, &header, HEADER_SIZE);
    memcpy(packet + HEADER_SIZE, data, size);

    ssize_t sent = sendto(g_socket, packet, total, 0, NULL, 0);
    free(packet);
    if (sent < 0) {
        fprintf(stderr, "sendto: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)sent != total) {
        fprintf(stderr, "sendto: partial send (%zd/%zu)\n", sent, total);
        return -1;
    }
    return 0;
}

static int send_frame(const char *frame, size_t frame_size, uint32_t frame_idx)
{
    size_t frag_count = (frame_size + MAX_FRAG_PAYLOAD - 1) / MAX_FRAG_PAYLOAD;
    for (size_t i = 0; i < frag_count; i++) {
        size_t frag_size = (i < frag_count - 1) ? MAX_FRAG_PAYLOAD
                                                : frame_size - i * MAX_FRAG_PAYLOAD;
        if (send_udp_fragment(frame + i * MAX_FRAG_PAYLOAD, frag_size,
                              frame_idx, (uint32_t)i, (uint32_t)frag_count) < 0)
            return -1;
    }
    return 0;
}

int main(int argc, char *argv[])
{
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <target_ip> <target_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *target_ip = argv[1];
    int target_port = atoi(argv[2]);
    if (target_port <= 0 || target_port > 65535) {
        fprintf(stderr, "Invalid port: %s\n", argv[2]);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (g_socket < 0) {
        fprintf(stderr, "socket: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons((uint16_t)target_port);
    if (inet_pton(AF_INET, target_ip, &addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid IP address: %s\n", target_ip);
        cleanup();
        return EXIT_FAILURE;
    }
    if (connect(g_socket, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "connect: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_camera(VIDEO_DEVICE) < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    uint32_t frame_idx = 0;
    while (!g_stop) {
        if (capture_frame() < 0) {
            fprintf(stderr, "Frame capture failed\n");
            break;
        }
        if (g_buffers[0].buffer && g_buffers[0].length > 0) {
            if (send_frame(g_buffers[0].buffer, g_buffers[0].length, frame_idx) < 0) {
                fprintf(stderr, "Frame send failed\n");
                break;
            }
            frame_idx++;
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

