/*
 * V4L2 CSI camera capture → UDP fragment streamer for Raspberry Pi (BCM2711).
 *
 * Build:  gcc -O2 -Wall -Wextra -o cam_udp cam_udp.c
 * Run:    ./cam_udp <target_ip> <target_port>
 *
 * Captures YUYV frames from /dev/video0, fragments each frame into UDP
 * datagrams (max 65 000 bytes payload), and sends them to the given address.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <errno.h>
#include <signal.h>
