#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN    4
#define TILT_SERVO_PIN   5
#define TILT_UP_PIN      6
#define TILT_DOWN_PIN    7
#define PAN_LEFT_PIN     8
#define PAN_RIGHT_PIN    9

#define PWM_FREQ_HZ      50
#define PWM_RANGE        1000
#define MIN_PULSE_US     1000
#define MAX_PULSE_US     2000
#define MIN_DUTY         50
#define MAX_DUTY         100
#define MID_POSITION     75
#define STEP             5
#define MIN_POSITION     25
#define MAX_POSITION     125
#define POLL_DELAY_US    50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_servo(int pin, int position) {
    if (position < MIN_POSITION) position = MIN_POSITION;
    if (position > MAX_POSITION) position = MAX_POSITION;

    int duty = MIN_DUTY + (position - MIN_POSITION) * (MAX_DUTY - MIN_DUTY) /
               (MAX_POSITION - MIN_POSITION);

    if (gpioServo(pin, duty) < 0) {
        fprintf(stderr, "Error: gpioServo(pin=%d, duty=%d) failed\n", pin, duty);
        return -1;
    }
    return 0;
}

static int read_button(int pin) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(pin=%d) failed\n", pin);
        return -1;
    }
    return v;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: could not register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(PAN_SERVO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TILT_SERVO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TILT_UP_PIN, PI_INPUT) < 0 ||
        gpioSetMode(TILT_DOWN_PIN, PI_INPUT) < 0 ||
        gpioSetMode(PAN_LEFT_PIN, PI_INPUT) < 0 ||
        gpioSetMode(PAN_RIGHT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(button) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TILT_UP_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(TILT_DOWN_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(PAN_LEFT_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(PAN_RIGHT_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pan_pos  = MID_POSITION;
    int tilt_pos = MID_POSITION;

    if (set_servo(PAN_SERVO_PIN, pan_pos) < 0 ||
        set_servo(TILT_SERVO_PIN, tilt_pos) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int tilt_up   = read_button(TILT_UP_PIN);
        int tilt_down = read_button(TILT_DOWN_PIN);
        int pan_left  = read_button(PAN_LEFT_PIN);
        int pan_right = read_button(PAN_RIGHT_PIN);

        if (tilt_up < 0 || tilt_down < 0 || pan_left < 0 || pan_right < 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (tilt_up == 0) {
            tilt_pos += STEP;
            if (tilt_pos > MAX_POSITION) tilt_pos = MAX_POSITION;
            if (set_servo(TILT_SERVO_PIN, tilt_pos) < 0) {
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        if (tilt_down == 0) {
            tilt_pos -= STEP;
            if (tilt_pos < MIN_POSITION) tilt_pos = MIN_POSITION;
            if (set_servo(TILT_SERVO_PIN, tilt_pos) < 0) {
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        if (pan_left == 0) {
            pan_pos -= STEP;
            if (pan_pos < MIN_POSITION) pan_pos = MIN_POSITION;
            if (set_servo(PAN_SERVO_PIN, pan_pos) < 0) {
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        if (pan_right == 0) {
            pan_pos += STEP;
            if (pan_pos > MAX_POSITION) pan_pos = MAX_POSITION;
            if (set_servo(PAN_SERVO_PIN, pan_pos) < 0) {
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

