#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"
#define CAPTURE_TIMEOUT_SEC 2
#define JPEG_QUALITY 75

static volatile sig_atomic_t g_stop = 0;

static void sigint_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static void yuyv_to_rgb24(const unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    for (int i = 0; i < width * height * 2; i += 4) {
        int y0 = yuyv[i];
        int u = yuyv[i + 1];
        int y1 = yuyv[i + 2];
        int v = yuyv[i + 3];
        int r0 = y0 + (1402 * (v - 128)) / 1000;
        int g0 = y0 - (344 * (u - 128)) / 1000 - (714 * (v - 128)) / 1000;
        int b0 = y0 + (1772 * (u - 128)) / 1000;
        int r1 = y1 + (1402 * (v - 128)) / 1000;
        int g1 = y1 - (344 * (u - 128)) / 1000 - (714 * (v - 128)) / 1000;
        int b1 = y1 + (1772 * (u - 128)) / 1000;
        if (r0 < 0) r0 = 0; if (r0 > 255) r0 = 255;
        if (g0 < 0) g0 = 0; if (g0 > 255) g0 = 255;
        if (b0 < 0) b0 = 0; if (b0 > 255) b0 = 255;
        if (r1 < 0) r1 = 0; if (r1 > 255) r1 = 255;
        if (g1 < 0) g1 = 0; if (g1 > 255) g1 = 255;
        if (b1 < 0) b1 = 0; if (b1 > 255) b1 = 255;
        int idx = i / 2 * 3;
        rgb[idx + 0] = (unsigned char)r0;
        rgb[idx + 1] = (unsigned char)g0;
        rgb[idx + 2] = (unsigned char)b0;
        rgb[idx + 3] = (unsigned char)r1;
        rgb[idx + 4] = (unsigned char)g1;
        rgb[idx + 5] = (unsigned char)b1;
    }
}

static void blur_image(unsigned char *rgb, int width, int height) {
    unsigned char *tmp = malloc((size_t)width * height * 3);
    if (!tmp) return;
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            int r = 0, g = 0, b = 0, count = 0;
            for (int dy = -1; dy <= 1; dy++) {
                for (int dx = -1; dx <= 1; dx++) {
                    int nx = x + dx, ny = y + dy;
                    if (nx >= 0 && nx < width && ny >= 0 && ny < height) {
                        int idx = (ny * width + nx) * 3;
                        r += rgb[idx + 0];
                        g += rgb[idx + 1];
                        b += rgb[idx + 2];
                        count++;
                    }
                }
            }
            int idx = (y * width + x) * 3;
            tmp[idx + 0] = (unsigned char)(r / count);
            tmp[idx + 1] = (unsigned char)(g / count);
            tmp[idx + 2] = (unsigned char)(b / count);
        }
    }
    memcpy(rgb, tmp, (size_t)width * height * 3);
    free(tmp);
}

static int encode_jpeg(const unsigned char *rgb, int width, int height, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) { fprintf(stderr, "fopen(%s): %s\n", filename, strerror(errno)); return -1; }
    unsigned char header[22] = {
        0xFF, 0xD8, 0xFF, 0xE0, 0x00, 0x10, 0x4A, 0x46, 0x49, 0x46, 0x00, 0x01,
        0x01, 0x01, 0x00, 0x48, 0x00, 0x48, 0x00, 0x00
    };
    unsigned char quant[64] = {
        0x06, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04,
        0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04,
        0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04,
        0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04,
        0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04,
        0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04,
        0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04,
        0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04
    };
    unsigned char huffman[176];
    memset(huffman, 0, sizeof(huffman));
    unsigned char sof[14] = {
        0xFF, 0xC0, 0x00, 0x11, 0x08, 0x00, (unsigned char)(height >> 8), (unsigned char)(height & 0xFF),
        0x00, (unsigned char)(width >> 8), (unsigned char)(width & 0xFF), 0x03, 0x01, 0x22, 0x00, 0x02, 0x11, 0x01, 0x03, 0x11, 0x01
    };
    unsigned char sos[12] = {0xFF, 0xDA, 0x00, 0x0C, 0x03, 0x01, 0x00, 0x02, 0x11, 0x03, 0x11, 0x00, 0x3F, 0x00};
    unsigned char eoi[2] = {0xFF, 0xD9};
    if (fwrite(header, 1, sizeof(header), fp) != sizeof(header)) goto fail;
    if (fwrite(quant, 1, sizeof(quant), fp) != sizeof(quant)) goto fail;
    if (fwrite(huffman, 1, sizeof(huffman), fp) != sizeof(huffman)) goto fail;
    if (fwrite(sof, 1, sizeof(sof), fp) != sizeof(sof)) goto fail;
    if (fwrite(sos, 1, sizeof(sos), fp) != sizeof(sos)) goto fail;
    int mcus = (width * 3 + 7) / 8;
    int row_size = mcus * 8;
    unsigned char *row = malloc((size_t)row_size);
    if (!row) goto fail;
    for (int y = 0; y < height; y++) {
        memset(row, 0xFF, row_size);
        for (int x = 0; x < width; x++) {
            int idx = (y * width + x) * 3;
            row[x * 3 + 0] = rgb[idx + 0];
            row[x * 3 + 1] = rgb[idx + 1];
            row[x * 3 + 2] = rgb[idx + 2];
        }
        if (fwrite(row, 1, row_size, fp) != row_size) goto fail;
    }
    free(row);
    if (fwrite(eoi, 1, sizeof(eoi), fp) != sizeof(eoi)) goto fail;
    fclose(fp);
    return 0;
fail:
    fprintf(stderr, "JPEG write failed\n");
    fclose(fp);
    return -1;
}

int main(void) {
