        printf("    Frame rate: %u/%u = %u fps\n",
               numerator, denominator, numerator / denominator);
    }
}

static int query_focus_auto(int fd)
{
    struct v4l2_queryctrl qc;
    memset(&qc, 0, sizeof(qc));
    qc.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &qc) < 0) {
        if (errno == EINVAL) {
            return 0; /* control not supported */
        }
        fprintf(stderr, "VIDIOC_QUERYCTRL (focus auto) failed: %s\n",
                strerror(errno));
        return -1;
    }
    return 1;
}

int main(void)
{
    int fd = open(DEVICE_NODE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n",
                DEVICE_NODE, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Camera device : %s\n", DEVICE_NODE);
    printf("Card          : %s\n", cap.card);
    printf("Driver        : %s\n", cap.driver);
    printf("Bus info      : %s\n", cap.bus_info);
    printf("Capabilities  : 0x%08x\n", cap.capabilities);

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("\nSupported resolutions and frame rates:\n");

    unsigned int index = 0;
    for (;;) {
        struct v4l2_frmsizeenum fse;
        memset(&fse, 0, sizeof(fse));
        fse.index = index;
        fse.pixel_format = cap.formats[0].pixelformat;

        if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fse) < 0) {
            if (errno == EINVAL) {
                break; /* no more frame sizes */
            }
            fprintf(stderr, "VIDIOC_ENUM_FRAMESIZES failed: %s\n",
                    strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }

        if (fse.type != V4L2_FRMSIZE_TYPE_DISCRETE) {
            index++;
            continue;
        }

        print_resolution(fse.discrete.width, fse.discrete.height);

        unsigned int subindex = 0;
        for (;;) {
            struct v4l2_frmivalenum fie;
            memset(&fie, 0, sizeof(fie));
            fie.index = subindex;
            fie.pixel_format = cap.formats[0].pixelformat;
            fie.width = fse.discrete.width;
            fie.height = fse.discrete.height;

            if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &fie) < 0) {
                if (errno == EINVAL) {
                    break; /* no more intervals for this size */
                }
                fprintf(stderr, "VIDIOC_ENUM_FRAMEINTERVALS failed: %s\n",
                        strerror(errno));
                close(fd);
                return EXIT_FAILURE;
            }

            if (fie.type != V4L2_FRMIVAL_TYPE_DISCRETE) {
                subindex++;
                continue;
            }

            print_frame_rate(fie.discrete.numerator,
                             fie.discrete.denominator);
            subindex++;
        }

        index++;
    }

    int focus = query_focus_auto(fd);
    if (focus < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    printf("\nAutofocus support: %s\n",
           focus ? "available" : "not available");

    if (close(fd) < 0) {
        fprintf(stderr, "close failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

