#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN    4
#define TILT_SERVO_PIN   5
#define UP_BUTTON_PIN    6
#define DOWN_BUTTON_PIN  7
#define LEFT_BUTTON_PIN  8
#define RIGHT_BUTTON_PIN 9

#define SERVO_MIN_PULSE  1000
#define SERVO_MAX_PULSE  2000
#define SERVO_CENTER    1500
#define SERVO_STEP      10
#define LOOP_DELAY_US   50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_servo_pulse(int pin, int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE) pulse_width = SERVO_MIN_PULSE;
    if (pulse_width > SERVO_MAX_PULSE) pulse_width = SERVO_MAX_PULSE;
    if (gpioServo(pin, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int read_button(int pin) {
    return (gpioRead(pin) == 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(UP_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pan_pulse  = SERVO_CENTER;
    int tilt_pulse = SERVO_CENTER;

    if (set_servo_pulse(PAN_SERVO_PIN, pan_pulse) < 0 ||
        set_servo_pulse(TILT_SERVO_PIN, tilt_pulse) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Pan-tilt control started. Press Ctrl+C to exit.\n");
    printf("PAN: GPIO%d, TILT: GPIO%d, UP: GPIO%d, DOWN: GPIO%d, LEFT: GPIO%d, RIGHT: GPIO%d\n",
           PAN_SERVO_PIN, TILT_SERVO_PIN, UP_BUTTON_PIN, DOWN_BUTTON_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);
    printf("Center position: %d us\n", SERVO_CENTER);

    while (g_running) {
        if (read_button(UP_BUTTON_PIN))    { tilt_pulse -= SERVO_STEP; set_servo_pulse(TILT_SERVO_PIN, tilt_pulse); }
        if (read_button(DOWN_BUTTON_PIN))  { tilt_pulse += SERVO_STEP; set_servo_pulse(TILT_SERVO_PIN, tilt_pulse); }
        if (read_button(LEFT_BUTTON_PIN))  { pan_pulse  -= SERVO_STEP; set_servo_pulse(PAN_SERVO_PIN, pan_pulse);  }
        if (read_button(RIGHT_BUTTON_PIN)) { pan_pulse  += SERVO_STEP; set_servo_pulse(PAN_SERVO_PIN, pan_pulse);  }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    printf("\nPan-tilt control stopped.\n");
    return EXIT_SUCCESS;
}

