#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define PIR_GPIO 17
#define DEBOUNCE_TIME 2
#define POLL_INTERVAL_MS 100
#define IMAGE_QUALITY 85
#define MOTION_CAPTURE_DIR "motion_captures"
#define MAX_FILENAME_LEN 256
#define MAX_JSON_LEN 512
#define MAX_URL_LEN 256

static volatile sig_atomic_t program_running = 1;
static CURL *curl_handle = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0 && errno != EEXIST) {
        fprintf(stderr, "Error creating directory '%s': %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[512];
    snprintf(command, sizeof(command),
             "raspistill -o %s -q %d -n -t 1000 2>/dev/null",
             filename, IMAGE_QUALITY);
    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Error executing raspistill: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(result) || WEXITSTATUS(result) != 0) {
        fprintf(stderr, "raspistill failed (status=%d)\n", result);
        return -1;
    }
    return 0;
}

static int get_iso8601_timestamp(char *buf, size_t len) {
    struct timeval tv;
    struct tm tm_info;
    if (gettimeofday(&tv, NULL) != 0) return -1;
    if (localtime_r(&tv.tv_sec, &tm_info) == NULL) return -1;
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) return -1;
    size_t used = strlen(buf);
    if (used + 8 >= len) return -1;
    snprintf(buf + used, len - used, ".%06ldZ", (long)tv.tv_usec);
    return 0;
}

static int compose_json(const char *filename, const char *timestamp,
                        const char *motion_status, int gpio_pin,
                        char *json, size_t json_len) {
    return snprintf(json, json_len,
                    "{\"filename\":\"%s\",\"timestamp\":\"%s\","
                    "\"motion_status\":\"%s\",\"gpio_pin\":%d}",
                    filename, timestamp, motion_status, gpio_pin);
}

static size_t write_cb(char *ptr, size_t size, size_t nmemb, void *userdata) {
    (void)ptr; (void)userdata;
    return size * nmemb;
}

static int post_data(const char *url, const char *json, const char *filename) {
    struct curl_httppost *formpost = NULL, *lastptr = NULL;
    struct curl_slist *headers = NULL;
    CURLcode res;
    long response_code = 0;
    int ret = -1;

    curl_formadd(&formpost, &lastptr,
                 CURLFORM_COPYNAME, "json",
                 CURLFORM_COPYCONTENTS, json,
                 CURLFORM_END);
    curl_formadd(&formpost, &lastptr,
                 CURLFORM_COPYNAME, "image",
                 CURLFORM_FILE, filename,
                 CURLFORM_END);

    headers = curl_slist_append(headers, "Expect:");
    if (!headers) {
        fprintf(stderr, "Error: curl_slist_append failed\n");
        goto cleanup;
    }

    curl_easy_setopt(curl_handle, CURLOPT_URL, url);
    curl_easy_setopt(curl_handle, CURLOPT_HTTPPOST, formpost);
    curl_easy_setopt(curl_handle, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl_handle, CURLOPT_WRITEFUNCTION, write_cb);
    curl_easy_setopt(curl_handle, CURLOPT_TIMEOUT, 30L);
    curl_easy_setopt(curl_handle, CURLOPT_CONNECTTIMEOUT, 10L);

    res = curl_easy_perform(curl_handle);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        goto cleanup;
    }

    curl_easy_getinfo(curl_handle, CURLINFO_RESPONSE_CODE, &response_code);
    if (response_code < 200 || response_code >= 300) {
        fprintf(stderr, "HTTP POST failed with status %ld\n", response_code);
        goto cleanup;
    }

    ret = 0;

cleanup:
    if (formpost) curl_formfree(formpost);
    if (headers) curl_slist_free_all(headers);
    return ret;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <ip_address> <port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char url[MAX_URL_LEN];
    snprintf(url, sizeof(url), "http://%s:%s/upload", argv[1], argv[2]);

    if (ensure_directory(MOTION_CAPTURE_DIR) != 0) return EXIT_FAILURE;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);

    if (curl_global_init(CURL_GLOBAL_ALL) != CURLE_OK) {
        fprintf(stderr, "curl_global_init() failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    curl_handle = curl_easy_init();
    if (!curl_handle) {
        fprintf(stderr, "curl_easy_init() failed\n");
        curl_global_cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        curl_easy_cleanup(curl_handle);
        curl_global_cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    time_t last_motion_time = 0;
    int last_pir_state = 0;

    while (program_running) {
        int pir_state = gpioRead(PIR_GPIO);
        if (pir_state < 0) {
            fprintf(stderr, "Error reading GPIO%d\n", PIR_GPIO);
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (pir_state == 1 && last_pir_state == 0) {
            time_t current_time = time(NULL);
            if (current_time == (time_t)-1) {
                fprintf(stderr, "time() failed: %s\n", strerror(errno));
            } else if (difftime(current_time, last_motion_time) >= DEBOUNCE_TIME) {
                last_motion_time = current_time;

                char timestamp[64];
                if (get_iso8601_timestamp(timestamp, sizeof(timestamp)) != 0) {
                    fprintf(stderr, "Error getting timestamp\n");
                    continue;
                }

                char filename[MAX_FILENAME_LEN];
                snprintf(filename, sizeof(filename), "%s/motion_%s.jpg",
                         MOTION_CAPTURE_DIR, timestamp);

                if (capture_image(filename) == 0) {
                    char json[MAX_JSON_LEN];
                    if (compose_json(filename, timestamp, "Motion Detected",
                                     PIR_GPIO, json, sizeof(json)) > 0) {
                        if (post_data(url, json, filename) == 0) {
                            printf("Motion detected and data posted to %s\n", url);
                        } else {
                            fprintf(stderr, "Failed to post data to %s\n", url);
                        }
                    } else {
                        fprintf(stderr, "Error composing JSON payload\n");
                    }
                } else {
                    fprintf(stderr, "Failed to capture image\n");
                }
            }
        }
        last_pir_state = pir_state;
        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    curl_easy_cleanup(curl_handle);
    curl_global_cleanup();
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

