#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <poll.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define PIR_PIN 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_MS 50
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[unknown] %s\n", message);
    }
    fclose(fp);
}

static int capture_image(void) {
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        log_message("localtime_r failed");
        return -1;
    }
    char filename[256];
    snprintf(filename, sizeof(filename), "%s/%04d%02d%02d_%02d%02d%02d_%03d.jpg",
             IMAGE_DIR,
             tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
             tm.tm_hour, tm.tm_min, tm.tm_sec,
             (int)(t % 1000));

    char command[512];
    snprintf(command, sizeof(command),
             "raspistill -o '%s' --width 640 --height 480 -q 85 --timeout 2000 --nopreview",
             filename);

    int ret = system(command);
    if (ret == -1) {
        log_message("system() failed to launch raspistill");
        return -1;
    }
    if (!WIFEXITED(ret) || WEXITSTATUS(ret) != 0) {
        char msg[300];
        snprintf(msg, sizeof(msg), "raspistill failed (status=%d)", ret);
        log_message(msg);
        return -1;
    }

    char msg[300];
    snprintf(msg, sizeof(msg), "Image captured: %s", filename);
    log_message(msg);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    int gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("open(/dev/gpiochip0)");
        return 1;
    }

    struct gpiochip_info chip_info;
    if (ioctl(gpio_fd, GPIO_GET_CHIPINFO_IOCTL, &chip_info) < 0) {
        perror("ioctl(GPIO_GET_CHIPINFO_IOCTL)");
        close(gpio_fd);
        return 1;
    }

    struct gpio_line_info line_info;
    memset(&line_info, 0, sizeof(line_info));
    line_info.line_offset = PIR_PIN;
    if (ioctl(gpio_fd, GPIO_GET_LINEINFO_IOCTL, &line_info) < 0) {
        perror("ioctl(GPIO_GET_LINEINFO_IOCTL)");
        close(gpio_fd);
        return 1;
    }

    struct gpio_line_request req;
    memset(&req, 0, sizeof(req));
    req.line_offset = PIR_PIN;
    req.config.flags = GPIO_LINE_REQUEST_FLAG_BIAS_PULL_DOWN;
    req.config.request_type = GPIO_LINE_REQUEST_EVENT_RISING_EDGE;
    req.config.consumer = "motion_capture";

    if (ioctl(gpio_fd, GPIO_GET_LINEEVENT_IOCTL, &req) < 0) {
        perror("ioctl(GPIO_GET_LINEEVENT_IOCTL)");
        close(gpio_fd);
        return 1;
    }

    log_message("Motion detection started on GPIO17 (rising edge).");

    while (running) {
        struct pollfd pfd;
        pfd.fd = gpio_fd;
        pfd.events = POLLIN;
        pfd.revents = 0;

        int pr = poll(&pfd, 1, POLL_TIMEOUT_MS);
        if (pr < 0) {
            if (errno == EINTR) continue;
            perror("poll");
            break;
        }
        if (pr == 0) continue;

        if (pfd.revents & POLLIN) {
            struct gpioevent_data event;
            ssize_t n = read(gpio_fd, &event, sizeof(event));
            if (n < 0) {
                if (errno == EINTR) continue;
                perror("read(gpioevent)");
                continue;
            }
            if (n != sizeof(event)) {
                fprintf(stderr, "Short read on gpioevent: %zd bytes\n", n);
                continue;
            }

            struct timespec ts_start = event.timestamp;
            struct timespec ts_now;
            clock_gettime(CLOCK_MONOTONIC, &ts_now);

            long elapsed_ms = (ts_now.tv_sec - ts_start.tv_sec) * 1000L +
                              (ts_now.tv_nsec - ts_start.tv_nsec) / 1000000L;

            if (elapsed_ms < DEBOUNCE_MS) {
                continue;
            }

            log_message("Motion detected!");
            if (capture_image() != 0) {
                log_message("Failed to capture image.");
            }
        }
    }

    log_message("Shutting down.");
    close(gpio_fd);
    return 0;
}

