code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define OUTPUT_FILE "cropped.yuv"
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define CAPTURE_TIMEOUT_SEC 2

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd, struct v4l2_format *fmt, struct v4l2_buffer *buf,
                       void **buffer_start, size_t *buffer_size) {
    *fd = open(DEVICE_NAME, O_RDWR);
    if (*fd < 0) {
        perror("open");
        return -1;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(*fd);
        return -1;
    }

    memset(fmt, 0, sizeof(*fmt));
    fmt->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt->fmt.pix.width = 640;
    fmt->fmt.pix.height = 480;
    fmt->fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt->fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, fmt) < 0) {
        perror("VIDIOC_S_FMT");
        close(*fd);
        return -1;
    }

    if (fmt->fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Device does not support YUYV format\n");
        close(*fd);
        return -1;
    }

    struct v4l2_requestbuffers reqbuf;
    memset(&reqbuf, 0, sizeof(reqbuf));
    reqbuf.count = 1;
    reqbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    reqbuf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, &reqbuf) < 0) {
        perror("VIDIOC_REQBUFS");
        close(*fd);
        return -1;
    }

    memset(buf, 0, sizeof(*buf));
    buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf->memory = V4L2_MEMORY_MMAP;
    buf->index = 0;

    if (xioctl(*fd, VIDIOC_QUERYBUF, buf) < 0) {
        perror("VIDIOC_QUERYBUF");
        close(*fd);
        return -1;
    }

    *buffer_size = buf->length;
    *buffer_start = mmap(NULL, buf->length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf->m.offset);
    if (*buffer_start == MAP_FAILED) {
        perror("mmap");
        close(*fd);
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QBUF, buf) < 0) {
        perror("VIDIOC_QBUF");
        munmap(*buffer_start, buf->length);
        close(*fd);
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(*fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        munmap(*buffer_start, buf->length);
        close(*fd);
        return -1;
    }

    return 0;
}

static int capture_frame(int fd, struct v4l2_buffer *buf, void *buffer_start, size_t buffer_size,
                         unsigned char *yuv_data, int crop_width, int crop_height) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = CAPTURE_TIMEOUT_SEC;
    tv.tv_usec = 0;

    do {
        r = select(fd + 1, &fds, NULL, NULL, &tv);
    } while (r == -1 && errno == EINTR && !g_stop);

    if (r == -1) {
        if (g_stop) return -1;
        perror("select");
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    if (xioctl(fd, VIDIOC_DQBUF, buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    if (buf->bytesused < (size_t)(crop_width * crop_height * 2)) {
        fprintf(stderr, "Insufficient data: %u bytes\n", buf->bytesused);
        if (xioctl(fd, VIDIOC_QBUF, buf) < 0) perror("VIDIOC_QBUF");
        return -1;
    }

    if (buf->width != 640 || buf->height != 480 || buf->field != V4L2_FIELD_NONE) {
        fprintf(stderr, "Unexpected frame format: %ux%u, field=%u\n", buf->width, buf->height, buf->field);
        if (xioctl(fd, VIDIOC_QBUF, buf) < 0) perror("VIDIOC_QBUF");
        return -1;
    }

    int src_width = 640;
    int src_height = 480;
    int src_stride = src_width * 2;

    for (int i = 0; i < crop_height; i++) {
        for (int j = 0; j < crop_width; j++) {
            int src_x = (src_width - crop_width) / 2 + j;
            int src_y = (src_height - crop_height) / 2 + i;
            int src_index = (src_y * src_stride) + (src_x * 2);
            int dst_index = (i * crop_width + j) * 2;
            yuv_data[dst_index] = ((unsigned char *)buffer_start)[src_index];
            yuv_data[dst_index + 1] = ((unsigned char *)buffer_start)[src_index + 1];
        }
    }

    if (xioctl(fd, VIDIOC_QBUF, buf) < 0) {
        perror("VIDIOC_QBUF");
        return -1;
    }

    return 0;
}

static int save_yuv_data(const char *filename, const unsigned char *yuv_data, int width, int height) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    size_t expected = (size_t)width * height * 2;
    size_t written = fwrite(yuv_data, 1, expected, fp);
    if (written != expected) {
        fprintf(stderr, "fwrite: wrote %zu of %zu bytes\n", written, expected);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    int fd = -1;
    struct v4l2_format fmt;
    struct v4l2_buffer buf;
    void *buffer_start = NULL;
    size_t buffer_size = 0;
    unsigned char *yuv_data = NULL;

    if (init_camera(&fd, &fmt, &buf, &buffer_start, &buffer_size) < 0) {
        return EXIT_FAILURE;
    }

    yuv_data = (unsigned char *)malloc((size_t)CROP_WIDTH * CROP_HEIGHT * 2);
    if (!yuv_data) {
        perror("malloc");
        goto cleanup;
    }

    if (capture_frame(fd, &buf, buffer_start, buffer_size, yuv_data, CROP_WIDTH, CROP_HEIGHT) < 0) {
        goto cleanup;
    }

    if (save_yuv_data(OUTPUT_FILE, yuv_data, CROP_WIDTH, CROP_HEIGHT) < 0) {
        goto cleanup;
    }

    printf("Cropped YUV data saved to %s\n", OUTPUT_FILE);

cleanup:
    if (yuv_data) free(yuv_data);
    if (buffer_start && buffer_start != MAP_FAILED) munmap(buffer_start, buffer_size);
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) perror("VIDIOC_STREAMOFF");
