#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN  17
#define TILT_SERVO_PIN 18

#define SERVO_FREQ 50
#define SERVO_RANGE 2000000  /* 2 MHz range for 50 Hz PWM */

#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define NEUTRAL_ANGLE 90
#define STEP_SIZE 5
#define DELAY_MS 100

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int angle_to_pulsewidth(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle %d out of range [%d, %d].\n",
                angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    /* SG90: 0° → 500 µs, 90° → 1500 µs, 180° → 2500 µs */
    return 500000 + (angle * 10000);
}

static int set_servo_angle(int pin, int angle) {
    int pw = angle_to_pulsewidth(angle);
    if (pw < 0) {
        return -1;
    }
    if (gpioServo(pin, pw) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d (pw=%d).\n", pin, pw);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    int pan_angle  = NEUTRAL_ANGLE;
    int tilt_angle = NEUTRAL_ANGLE;

    if (set_servo_angle(PAN_SERVO_PIN, pan_angle) != 0 ||
        set_servo_angle(TILT_SERVO_PIN, tilt_angle) != 0) {
        fprintf(stderr, "Error: Failed to initialize servos to neutral position.\n");
        gpioTerminate();
        return 1;
    }

    printf("Servo control started. Press arrow keys to move, 'q' to quit.\n");
    printf("PAN: %d° | TILT: %d°\n", pan_angle, tilt_angle);

    while (g_running) {
        int c = getchar();
        if (c == EOF) {
            break;
        }

        switch (c) {
            case 'q':
            case 'Q':
                g_running = 0;
                break;

            case 27: { /* Escape */
                int esc = getchar();
                if (esc == '[') {
                    int arrow = getchar();
                    switch (arrow) {
                        case 'A': /* Up */
                            if (tilt_angle + STEP_SIZE <= MAX_ANGLE) {
                                tilt_angle += STEP_SIZE;
                            } else {
                                fprintf(stderr, "Error: Tilt angle exceeds maximum (%d°).\n", MAX_ANGLE);
                            }
                            break;
                        case 'B': /* Down */
                            if (tilt_angle - STEP_SIZE >= MIN_ANGLE) {
                                tilt_angle -= STEP_SIZE;
                            } else {
                                fprintf(stderr, "Error: Tilt angle below minimum (%d°).\n", MIN_ANGLE);
                            }
                            break;
                        case 'C': /* Right */
                            if (pan_angle + STEP_SIZE <= MAX_ANGLE) {
                                pan_angle += STEP_SIZE;
                            } else {
                                fprintf(stderr, "Error: Pan angle exceeds maximum (%d°).\n", MAX_ANGLE);
                            }
                            break;
                        case 'D': /* Left */
                            if (pan_angle - STEP_SIZE >= MIN_ANGLE) {
                                pan_angle -= STEP_SIZE;
                            } else {
                                fprintf(stderr, "Error: Pan angle below minimum (%d°).\n", MIN_ANGLE);
                            }
                            break;
                    }
                }
                break;
            }
        }

        if (g_running) {
            if (set_servo_angle(PAN_SERVO_PIN, pan_angle) != 0 ||
                set_servo_angle(TILT_SERVO_PIN, tilt_angle) != 0) {
                fprintf(stderr, "Error: Failed to update servo positions.\n");
                g_running = 0;
            } else {
                printf("PAN: %d° | TILT: %d°\n", pan_angle, tilt_angle);
            }
            gpioDelay(DELAY_MS * 1000);
        }
    }

    /* Cleanup: set servos to neutral and terminate pigpio */
    set_servo_angle(PAN_SERVO_PIN, NEUTRAL_ANGLE);
    set_servo_angle(TILT_SERVO_PIN, NEUTRAL_ANGLE);
    gpioTerminate();
    printf("Servo control terminated.\n");
    return 0;
}

