#define LCD_WIDTH 16

#define LCD_CLEARDISPLAY 0x01
#define LCD_RETURNHOME 0x02
#define LCD_ENTRYMODESET 0x04
#define LCD_DISPLAYCONTROL 0x08
#define LCD_FUNCTIONSET 0x20
#define LCD_SETDDRAMADDR 0x80

#define LCD_ENTRYLEFT 0x02
#define LCD_ENTRYSHIFTDECREMENT 0x00
#define LCD_DISPLAYON 0x04
#define LCD_CURSOROFF 0x00
#define LCD_BLINKOFF 0x00
#define LCD_4BITMODE 0x00
#define LCD_2LINE 0x08
#define LCD_5x8DOTS 0x00

#define FLOW_SCALING_FACTOR 1.0
#define SAMPLE_INTERVAL_US 1000000
#define LCD_UPDATE_INTERVAL_S 10

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_count = 0;
static double total_volume = 0.0;
static time_t last_sample_time = 0;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    pulse_count++;
}

static int lcd_send_nibble(int handle, uint8_t nibble, uint8_t rs) {
    uint8_t data = (nibble & 0xF0) | rs | 0x08;
    if (i2cWriteByte(handle, data) < 0) return -1;
    gpioDelay(1000);
    data |= 0x04;
    if (i2cWriteByte(handle, data) < 0) return -1;
    gpioDelay(1000);
    data &= ~0x04;
    if (i2cWriteByte(handle, data) < 0) return -1;
    gpioDelay(1000);
    return 0;
}

static int lcd_send_byte(int handle, uint8_t val, uint8_t rs) {
    if (lcd_send_nibble(handle, val & 0xF0, rs) < 0) return -1;
    if (lcd_send_nibble(handle, (val << 4) & 0xF0, rs) < 0) return -1;
    return 0;
}

static int lcd_command(int handle, uint8_t cmd) {
    return lcd_send_byte(handle, cmd, 0);
}

static int lcd_data(int handle, uint8_t data) {
    return lcd_send_byte(handle, data, 0x01);
}

static int lcd_init(int handle) {
    gpioDelay(50000);
    if (lcd_send_nibble(handle, 0x30, 0) < 0) return -1;
