#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define ANEMOMETER_GPIO 17
#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 1000000
#define I2C_BUS 1
#define I2C_ADDR 0x27
#define LCD_WIDTH 16
#define SAMPLE_WINDOW_MS 500
#define PULSES_PER_REV 2.0f
#define DIA_CIRCUMFERENCE 0.955f
#define WIND_DIR_ADC_CHANNEL 0

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t pulse_count = 0;

static int spi_fd = -1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void anemometer_isr(void) {
    pulse_count++;
}

static int spi0SPIOpen(int bus, int device, int speed) {
    char path[32];
    snprintf(path, sizeof(path), "/dev/spidev%d.%d", bus, device);
    int fd = open(path, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", path, strerror(errno));
        return -1;
    }
    uint32_t speed_val = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int spi0ReadByte(int fd, int channel) {
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | (channel & 0x07)) << 4), 0x00 };
    uint8_t rx[3] = { 0 };
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int i2c0Open(int bus, int addr) {
    char path[20];
    snprintf(path, sizeof(path), "/dev/i2c-%d", bus);
    int fd = open(path, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c0WriteByte(int fd, uint8_t val) {
    if (write(fd, &val, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int lcdWriteByte(int fd, uint8_t val) {
    return i2c0WriteByte(fd, val);
}

static void lcdSend4Bits(int fd, uint8_t nibble, uint8_t rs) {
    uint8_t high = (nibble & 0xF0) | rs;
    uint8_t low = ((nibble << 4) & 0xF0) | rs;
    lcdWriteByte(fd, high | 0x04);
    lcdWriteByte(fd, high);
    lcdWriteByte(fd, low | 0x04);
    lcdWriteByte(fd, low);
    usleep(1);
}

static void lcdCommand(int fd, uint8_t cmd) {
    lcdSend4Bits(fd, cmd, 0x00);
    if (cmd == 0x01 || cmd == 0x02) {
        usleep(2000);
    }
}

static void lcdData(int fd, uint8_t data) {
    lcdSend4Bits(fd, data, 0x01);
}

static void lcdInit(int fd) {
    usleep(50000);
    lcdSend4Bits(fd, 0x30, 0x00);
    usleep(4500);
    lcdSend4Bits(fd, 0x30, 0x00);
    usleep(150);
    lcdSend4Bits(fd, 0x30, 0x00);
    usleep(150);
    lcdSend4Bits(fd, 0x20, 0x00);
    usleep(150);
    lcdCommand(fd, 0x28);
    lcdCommand(fd, 0x08);
    lcdCommand(fd, 0x01);
    lcdCommand(fd, 0x06);
    lcdCommand(fd, 0x0C);
}

static void lcdClear(int fd) {
    lcdCommand(fd, 0x01);
    usleep(2000);
}

static void lcdSetCursor(int fd, int col, int row) {
    int addr = (row == 0) ? 0x00 : 0x40;
    lcdCommand(fd, 0x80 | (col + addr));
}

static void lcdPrint(int fd, const char *str) {
    while (*str) {
        lcdData(fd, (uint8_t)*str++);
    }
}

static float calculateWindSpeed(int pulses) {
    float time_sec = (float)SAMPLE_WINDOW_MS / 1000.0f;
    float revs = (float)pulses / PULSES_PER_REV;
    return (revs * DIA_CIRCUMFERENCE) / time_sec;
}

static const char *getWindDirection(int adcValue) {
    if (adcValue < 100) return "N";
    if (adcValue < 200) return "NE";
    if (adcValue < 300) return "E";
    if (adcValue < 400) return "SE";
    if (adcValue < 500) return "S";
    if (adcValue < 600) return "SW";
    if (adcValue < 700) return "W";
    if (adcValue < 800) return "NW";
    return "N";
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return 1;
    }

    spi_fd = spi0SPIOpen(SPI_BUS, SPI_DEVICE, SPI_SPEED);
    if (spi_fd < 0) {
        return 1;
    }

    i2c_fd = i2c0Open(I2C_BUS, I2C_ADDR);
    if (i2c_fd < 0) {
        close(spi_fd);
        return 1;
    }

    lcdInit(i2c_fd);
    lcdClear(i2c_fd);

    printf("Anemometer and wind vane monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adcValue = spi0ReadByte(spi_fd, WIND_DIR_ADC_CHANNEL);
        if (adcValue < 0) {
            fprintf(stderr, "Error reading ADC value.\n");
            adcValue = 0;
        } else if (adcValue == 0 || adcValue == 1023) {
            fprintf(stderr, "Warning: ADC reading at extreme (%d). Sensor absent or wiring fault.\n", adcValue);
        }

        int currentPulses = pulse_count;
        pulse_count = 0;

        float windSpeed = calculateWindSpeed(currentPulses);
        const char *windDirection = getWindDirection(adcValue);

        char speedStr[16];
        char dirStr[16];
        snprintf(speedStr, sizeof(speedStr), "Speed: %.2f m/s", windSpeed);
        snprintf(dirStr, sizeof(dirStr), "Dir: %s", windDirection);

        lcdClear(i2c_fd);
        lcdSetCursor(i2c_fd, 0, 0);
        lcdPrint(i2c_fd, speedStr);
        lcdSetCursor(i2c_fd, 0, 1);
        lcdPrint(i2c_fd, dirStr);

        printf("Wind Speed: %.2f m/s, Direction: %s, ADC: %d\n", windSpeed, windDirection, adcValue);

        usleep(SAMPLE_WINDOW_MS * 1000);
    }

    printf("\nShutting down...\n");
    lcdClear(i2c_fd);
    lcdSetCursor(i2c_fd, 0, 0);
    lcdPrint(i2c_fd, "Shutting down...");

    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return 0;
}

