    if (adcValue < 500) return "S";
    if (adcValue < 600) return "SW";
    if (adcValue < 700) return "W";
    if (adcValue < 800) return "NW";
    return "N";
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return 1;
    }

    spi_fd = spi0SPIOpen(SPI_BUS, SPI_DEVICE, SPI_SPEED);
    if (spi_fd < 0) {
        return 1;
    }

    i2c_fd = i2c0Open(I2C_BUS, I2C_ADDR);
    if (i2c_fd < 0) {
        close(spi_fd);
        return 1;
    }

    lcdInit(i2c_fd);
    lcdClear(i2c_fd);

    printf("Anemometer and wind vane monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adcValue = spi0ReadByte(spi_fd, WIND_DIR_ADC_CHANNEL);
        if (adcValue < 0) {
            fprintf(stderr, "Error reading ADC value.\n");
            adcValue = 0;
        } else if (adcValue == 0 || adcValue == 1023) {
            fprintf(stderr, "Warning: ADC reading at extreme (%d). Sensor absent or wiring fault.\n", adcValue);
        }

        int currentPulses = pulse_count;
        pulse_count = 0;

        float windSpeed = calculateWindSpeed(currentPulses);
        const char *windDirection = getWindDirection(adcValue);

        char speedStr[16];
        char dirStr[16];
        snprintf(speedStr, sizeof(speedStr), "Speed: %.2f m/s", windSpeed);
        snprintf(dirStr, sizeof(dirStr), "Dir: %s", windDirection);

        lcdClear(i2c_fd);
        lcdSetCursor(i2c_fd, 0, 0);
        lcdPrint(i2c_fd, speedStr);
        lcdSetCursor(i2c_fd, 0, 1);
        lcdPrint(i2c_fd, dirStr);

        printf("Wind Speed: %.2f m/s, Direction: %s, ADC: %d\n", windSpeed, windDirection, adcValue);

        usleep(SAMPLE_WINDOW_MS * 1000);
    }

    printf("\nShutting down...\n");
    lcdClear(i2c_fd);
    lcdSetCursor(i2c_fd, 0, 0);
    lcdPrint(i2c_fd, "Shutting down...");

    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return 0;
}

