#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_BACKLIGHT 0x08
#define ENABLE 0x04
#define PULSES_PER_LITER 450.0
#define SAMPLE_INTERVAL_SEC 1
#define SENSOR_TIMEOUT_SEC 5

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void flow_sensor_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    pulse_count++;
}

static int lcd_write_byte(int fd, uint8_t bits, uint8_t mode) {
    uint8_t high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    uint8_t low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;

    if (i2cWriteByte(fd, high) < 0) return -1;
    if (i2cWriteByte(fd, high | ENABLE) < 0) return -1;
    gpioDelay(1000);
    if (i2cWriteByte(fd, high & ~ENABLE) < 0) return -1;
    gpioDelay(1000);

    if (i2cWriteByte(fd, low) < 0) return -1;
    if (i2cWriteByte(fd, low | ENABLE) < 0) return -1;
    gpioDelay(1000);
    if (i2cWriteByte(fd, low & ~ENABLE) < 0) return -1;
    gpioDelay(1000);
    return 0;
}

static int lcd_send_command(int fd, uint8_t cmd) {
    return lcd_write_byte(fd, cmd, LCD_CMD);
}

static int lcd_send_data(int fd, uint8_t data) {
    return lcd_write_byte(fd, data, LCD_CHR);
}

static int lcd_init(int fd) {
    gpioDelay(50000);
    if (lcd_send_command(fd, 0x33) < 0) return -1;
    if (lcd_send_command(fd, 0x32) < 0) return -1;
    if (lcd_send_command(fd, 0x28) < 0) return -1;
    if (lcd_send_command(fd, 0x0C) < 0) return -1;
    if (lcd_send_command(fd, 0x06) < 0) return -1;
    if (lcd_send_command(fd, 0x01) < 0) return -1;
    gpioDelay(2000);
    return 0;
}

static int lcd_clear(int fd) {
    if (lcd_send_command(fd, 0x01) < 0) return -1;
    gpioDelay(2000);
    return 0;
}

static int lcd_set_cursor(int fd, uint8_t line) {
    return lcd_send_command(fd, line);
}

static int lcd_print(int fd, const char *str) {
    for (int i = 0; str[i] != '\0'; i++) {
        if (lcd_send_data(fd, (uint8_t)str[i]) < 0) return -1;
    }
    return 0;
}

static int lcd_display_flow_rate(int fd, float flow_rate) {
    char buffer[17];
    snprintf(buffer, sizeof(buffer), "Flow Rate: %.2f L/min", flow_rate);

    if (lcd_set_cursor(fd, LCD_LINE_1) < 0) return -1;
    if (lcd_print(fd, "Flow Rate:") < 0) return -1;

    if (lcd_set_cursor(fd, LCD_LINE_2) < 0) return -1;
    if (lcd_print(fd, buffer) < 0) return -1;
    return 0;
}

int main(void) {
    int i2c_fd = -1;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", FLOW_SENSOR_GPIO);
        goto cleanup_gpio;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO%d.\n", FLOW_SENSOR_GPIO);
        goto cleanup_gpio;
    }

    if (gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, flow_sensor_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set alert function on GPIO%d.\n", FLOW_SENSOR_GPIO);
        goto cleanup_gpio;
    }

    i2c_fd = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (code %d).\n", I2C_BUS, LCD_ADDR, i2c_fd);
        goto cleanup_gpio;
    }

    if (lcd_init(i2c_fd) < 0) {
        fprintf(stderr, "Error: Failed to initialize LCD1602 at address 0x%02X.\n", LCD_ADDR);
        goto cleanup_i2c;
    }

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    time_t last_pulse_time = time(NULL);

    while (running) {
        uint32_t current_pulses = pulse_count;
        pulse_count = 0;

        float flow_rate = (float)current_pulses / PULSES_PER_LITER * 60.0;

        if (lcd_display_flow_rate(i2c_fd, flow_rate) < 0) {
            fprintf(stderr, "Error: Failed to write to LCD.\n");
            break;
        }

        if (current_pulses == 0) {
            time_t now = time(NULL);
            if (difftime(now, last_pulse_time) > SENSOR_TIMEOUT_SEC) {
                fprintf(stderr, "Warning: No flow detected for %d seconds. Sensor may be absent or disconnected.\n", SENSOR_TIMEOUT_SEC);
                last_pulse_time = now;
            }
        } else {
            last_pulse_time = time(NULL);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    ret = 0;

cleanup_i2c:
    if (i2c_fd >= 0) {
        lcd_clear(i2c_fd);
        i2cClose(i2c_fd);
    }

cleanup_gpio:
    gpioTerminate();

    printf("Water flow monitoring stopped.\n");
    return ret;
}

