#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define ROWS 8
#define COLS 8
#define DELAY_US 800

static const int row_pins[ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
static const int col_pins[COLS] = {5, 6, 12, 13, 19, 16, 26, 20};

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < ROWS; i++) {
        if (gpioSetMode(row_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set row pin %d as output\n", row_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(row_pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to initialise row pin %d low\n", row_pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    for (int i = 0; i < COLS; i++) {
        if (gpioSetMode(col_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set column pin %d as output\n", col_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(col_pins[i], 1) != 0) {
            fprintf(stderr, "Error: failed to initialise column pin %d high\n", col_pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

static void clear_display(void) {
    for (int i = 0; i < ROWS; i++) {
        gpioWrite(row_pins[i], 0);
    }
    for (int i = 0; i < COLS; i++) {
        gpioWrite(col_pins[i], 1);
    }
}

static void display_frame(const int frame[ROWS][COLS]) {
    for (int row = 0; row < ROWS; row++) {
        for (int col = 0; col < COLS; col++) {
            gpioWrite(col_pins[col], frame[row][col] ? 0 : 1);
        }
        gpioWrite(row_pins[row], 1);
        gpioDelay(DELAY_US);
        gpioWrite(row_pins[row], 0);
        for (int col = 0; col < COLS; col++) {
            gpioWrite(col_pins[col], 1);
        }
    }
}

static void generate_left_to_right(int frame[ROWS][COLS], int offset) {
    for (int row = 0; row < ROWS; row++) {
        for (int col = 0; col < COLS; col++) {
            int dist = abs(col - (offset + row) % COLS);
            frame[row][col] = (dist <= 1) ? 1 : 0;
        }
    }
}

static void generate_right_to_left(int frame[ROWS][COLS], int offset) {
    for (int row = 0; row < ROWS; row++) {
        for (int col = 0; col < COLS; col++) {
            int dist = abs(col - ((COLS - 1) - (offset + row) % COLS));
            frame[row][col] = (dist <= 1) ? 1 : 0;
        }
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int left_offset = 0;
    int right_offset = 0;
    int frame[ROWS][COLS];

    while (running) {
        generate_left_to_right(frame, left_offset);
        display_frame(frame);
        left_offset = (left_offset + 1) % COLS;

        generate_right_to_left(frame, right_offset);
        display_frame(frame);
        right_offset = (right_offset + 1) % COLS;
    }

    clear_display();
    gpioTerminate();
    return EXIT_SUCCESS;
}

