/*
 * wave_matrix.c — 8x8 common-anode LED matrix wave animation
 *
 * Build:  gcc -O2 -Wall -Wextra -o wave_matrix wave_matrix.c -lgpiod
 * Run:    sudo ./wave_matrix
 *
 * Hardware:
 *   Row anodes  : GPIO 2, 3, 4, 17, 27, 22, 10, 9  (BCM)
 *   Col cathodes: GPIO 14,15,18,23,24,25, 8, 7  (BCM)
 *   Each column cathode wired through a 220 Ω resistor.
 *
 * Common-anode matrix: a column lights when its cathode is LOW and
 * the corresponding row anode is HIGH.
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define DELAY_MS 150

static const unsigned int row_pins[NUM_ROWS] = {2, 3, 4, 17, 27, 22, 10, 9};
static const unsigned int col_pins[NUM_COLS] = {14, 15, 18, 23, 24, 25, 8, 7};

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig)
{
    (void)sig;
    running = 0;
}

static int set_all(struct gpiod_line_bulk *bulk, int value)
{
    int ret = gpiod_line_set_value_bulk(bulk, value);
    if (ret < 0)
        fprintf(stderr, "set_value_bulk(%d) failed: %s\n",
                value, strerror(errno));
    return ret;
}

static void clear_matrix(struct gpiod_line_bulk *row_bulk,
                         struct gpiod_line_bulk *col_bulk)
{
    /* All columns HIGH (cathodes off) and all rows LOW (anodes off) */
    set_all(col_bulk, 1);
    set_all(row_bulk, 0);
}

static int light_column(struct gpiod_line_bulk *row_bulk,
                        struct gpiod_line_bulk *col_bulk,
                        int col)
{
    /* Turn off all columns (cathodes HIGH) */
    if (set_all(col_bulk, 1) < 0)
        return -1;

    /* Select the column cathode LOW */
    if (gpiod_line_set_value(col_bulk->lines[col], 0) < 0) {
        fprintf(stderr, "set col %d LOW failed: %s\n", col, strerror(errno));
        return -1;
    }

    /* Light the column sequentially: row HIGH = anode HIGH */
    for (int row = 0; row < NUM_ROWS; row++) {
        if (gpiod_line_set_value(row_bulk->lines[row], 1) < 0) {
            fprintf(stderr, "set row %d HIGH failed: %s\n",
                    row, strerror(errno));
            return -1;
        }
        usleep(DELAY_MS * 1000);
        if (gpiod_line_set_value(row_bulk->lines[row], 0) < 0) {
            fprintf(stderr, "set row %d LOW failed: %s\n",
                    row, strerror(errno));
            return -1;
        }
    }

    /* Turn off the column cathode again */
    if (gpiod_line_set_value(col_bulk->lines[col], 1) < 0) {
        fprintf(stderr, "reset col %d HIGH failed: %s\n",
                col, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk row_bulk, col_bulk;
    int ret = EXIT_FAILURE;

    gpiod_line_bulk_init(&row_bulk);
    gpiod_line_bulk_init(&col_bulk);

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get row lines */
    for (int i = 0; i < NUM_ROWS; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, row_pins[i]);
        if (!line) {
            fprintf(stderr, "Failed to get row line %u: %s\n",
                    row_pins[i], strerror(errno));
            goto cleanup;
        }
        gpiod_line_bulk_add(&row_bulk, line);
    }

    /* Get column lines */
    for (int i = 0; i < NUM_COLS; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, col_pins[i]);
        if (!line) {
            fprintf(stderr, "Failed to get col line %u: %s\n",
                    col_pins[i], strerror(errno));
            goto cleanup;
        }
        gpiod_line_bulk_add(&col_bulk, line);
    }

    /* Request row lines as outputs, initial LOW (anodes off) */
    if (gpiod_line_request_bulk_output(&row_bulk, "wave_matrix_row", 0) < 0) {
        fprintf(stderr, "Request row lines failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request column lines as outputs, initial HIGH (cathodes off) */
    if (gpiod_line_request_bulk_output(&col_bulk, "wave_matrix_col", 1) < 0) {
        fprintf(stderr, "Request col lines failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Ensure matrix is blank on start */
    clear_matrix(&row_bulk, &col_bulk);

    /* Main animation loop */
    while (running) {
        for (int col = 0; col < NUM_COLS && running; col++) {
            if (light_column(&row_bulk, &col_bulk, col) < 0) {
                fprintf(stderr, "Column %d animation failed\n", col);
                goto cleanup;
            }
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Turn off all LEDs and release lines */
    clear_matrix(&row_bulk, &col_bulk);
    gpiod_line_release_bulk(&row_bulk);
    gpiod_line_release_bulk(&col_bulk);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

