/*
 * VL53L3CX multi-target ToF sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   VL53L3CX SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   VL53L3CX SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   VL53L3CX VDD  -> 3.3 V (pin 1)
 *   VL53L3CX GND  -> GND  (pin 6)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vl53l3cx_reader vl53l3cx_reader.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./vl53l3cx_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL53L3CX I2C address ---- */
#define VL53L3CX_ADDR 0x52

/* ---- VL53L3CX register map (subset) ---- */
#define VL53L3CX_REG_SOFT_RESET          0x000B
#define VL53L3CX_REG_MODEL_ID            0x010F
#define VL53L3CX_REG_RANGE_START         0x0080
#define VL53L3CX_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L3CX_REG_RESULT_DISTANCE     0x0096
#define VL53L3CX_REG_RESULT_TARGETS      0x0098

#define VL53L3CX_MODEL_ID_EXPECTED       0xEA

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address + 1 byte of data over I2C.         */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int vl53l3cx_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] I2C write to reg 0x%04X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read N bytes starting at a 16-bit register address.                 */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int vl53l3cx_read_reg(int handle, uint16_t reg, uint8_t *data, uint8_t len)
{
    char addr_buf[2];
    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr_buf, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C write (addr) for reg 0x%04X failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)data, len) != len) {
        fprintf(stderr, "[ERROR] I2C read from reg 0x%04X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Verify the sensor model ID.                                        */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int vl53l3cx_verify_model_id(int handle)
{
    uint8_t model_id = 0;
    if (vl53l3cx_read_reg(handle, VL53L3CX_REG_MODEL_ID, &model_id, 1) != 0) {
        return -1;
    }
    if (model_id != VL53L3CX_MODEL_ID_EXPECTED) {
        fprintf(stderr,
                "[ERROR] Unexpected model ID 0x%02X (expected 0x%02X). "
                "Sensor not present or wrong device.\n",
                model_id, VL53L3CX_MODEL_ID_EXPECTED);
        return -1;
    }
    printf("[INFO] VL53L3CX model ID verified (0x%02X).\n", model_id);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Perform the required proprietary firmware download sequence.       */
/* In a production environment this would read the firmware binary     */
/* from a known-good source and write it to the sensor's memory.       */
/* For this example we stub the sequence with a descriptive comment    */
/* so that the I2C communication and error handling remain intact.     */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int vl53l3cx_download_firmware(int handle)
{
    printf("[INFO] Downloading VL53L3CX firmware (stubbed).\n");

    /* Real implementation: read firmware binary, write to sensor RAM */
    /* using the proprietary ST API sequence.                         */

    /* Soft reset to ensure a clean start. */
    if (vl53l3cx_write_reg8(handle, VL53L3CX_REG_SOFT_RESET, 0x00) != 0)
        return -1;
    gpioDelay(2000); /* 2 ms */
    if (vl53l3cx_write_reg8(handle, VL53L3CX_REG_SOFT_RESET, 0x01) != 0)
        return -1;
    gpioDelay(2000); /* 2 ms */

    /* Placeholder: firmware download would happen here. */
    gpioDelay(10000); /* 10 ms for firmware to boot */

    printf("[INFO] Firmware download complete (stubbed).\n");
    return 0;
}

/* ------------------------------------------------------------------ */
/* Start a single-shot ranging measurement.                           */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int vl53l3cx_start_ranging(int handle)
{
    return vl53l3cx_write_reg8(handle, VL53L3CX_REG_RANGE_START, 0x01);
}

/* ------------------------------------------------------------------ */
/* Read the number of detected targets.                               */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int vl53l3cx_get_target_count(int handle, uint8_t *target_count)
{
    return vl53l3cx_read_reg(handle, VL53L3CX_REG_RESULT_TARGETS,
                             target_count, 1);
}

/* ------------------------------------------------------------------ */
/* Read a single target's distance (mm) from the result buffer.        */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int vl53l3cx_get_target_distance(int handle, uint8_t target_idx,
                                        uint16_t *distance_mm)
{
    uint8_t data[2];
    uint16_t reg = VL53L3CX_REG_RESULT_DISTANCE + (target_idx * 2);

    if (vl53l3cx_read_reg(handle, reg, data, 2) != 0)
        return -1;

    *distance_mm = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Print an ISO-8601 timestamp to stdout.                             */
/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
        printf("[%s] ", ts);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper.                                                    */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at the VL53L3CX address ---- */
    g_i2c_handle = i2cOpen(1, VL53L3CX_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor identity ---- */
    if (vl53l3cx_verify_model_id(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] VL53L3CX not detected on bus 1.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Download firmware (stubbed) ---- */
    if (vl53l3cx_download_firmware(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Firmware download failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers for graceful shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] VL53L3CX reader started. Press Ctrl+C to exit.\n");

    /* ---- Main polling loop ---- */
    while (g_running) {
        /* Start a single-shot ranging measurement. */
        if (vl53l3cx_start_ranging(g_i2c_handle) != 0) {
            fprintf(stderr, "[WARN] Failed to start ranging.\n");
            gpioDelay(100000); /* 100 ms backoff */
            continue;
        }

        /* Wait for the measurement to complete (poll status register). */
        uint8_t status = 0;
        int poll_ok = 0;
        for (int i = 0; i < 50; i++) {
            if (vl53l3cx_read_reg(g_i2c_handle, VL53L3CX_REG_RESULT_RANGE_STATUS,
                                 &status, 1) != 0) {
                fprintf(stderr, "[WARN] Failed to read range status.\n");
                break;
            }
            if ((status & 0x01) != 0) { /* data ready */
                poll_ok = 1;
                break;
            }
            gpioDelay(2000); /* 2 ms */
        }

        if (!poll_ok) {
            fprintf(stderr, "[WARN] Ranging measurement timed out.\n");
            continue;
        }

        /* Read number of detected targets. */
        uint8_t target_count = 0;
        if (vl53l3cx_get_target_count(g_i2c_handle, &target_count) != 0) {
            fprintf(stderr, "[WARN] Failed to read target count.\n");
            continue;
        }

        print_timestamp();
        printf("Targets: %u\n", target_count);

        for (uint8_t i = 0; i < target_count; i++) {
            uint16_t distance = 0;
            if (vl53l3cx_get_target_distance(g_i2c_handle, i, &distance) != 0) {
                fprintf(stderr, "[WARN] Failed to read distance for target %u.\n", i);
                continue;
            }
            printf("  Target %u: %u mm\n", i, distance);
        }

        /* 100 ms between polling cycles. */
        gpioDelay(100000);
    }

    /* ---- Graceful shutdown ---- */
    printf("\n[INFO] Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

