#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX75031_ADDR 0x5B
#define LOG_FILE "depth_log.csv"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_mlx75031(int fd) {
    if (i2c_write_reg8(fd, 0x00, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0x01, 0x02) < 0) return -1;
    if (i2c_write_reg8(fd, 0x02, 0x03) < 0) return -1;
    return 0;
}

static int open_i2c(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, MLX75031_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MLX75031_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int read_distance(int fd, int *distance) {
    uint16_t raw;
    if (i2c_read_reg16(fd, 0x10, &raw) < 0) return -1;
    *distance = (int)raw;
    return 0;
}

static int log_data(FILE *fp, int distance) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%d\n", ts, distance) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    fseek(log_fp, 0, SEEK_END);
    long sz = ftell(log_fp);
    if (sz == 0) {
        if (fprintf(log_fp, "timestamp,distance_mm\n") < 0 || fflush(log_fp) != 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            cleanup();
            return 1;
        }
    }

    i2c_fd = open_i2c();
    if (i2c_fd < 0) {
        cleanup();
        return 1;
    }

    if (init_mlx75031(i2c_fd) < 0) {
        fprintf(stderr, "MLX75031 initialization failed\n");
        cleanup();
        return 1;
    }

    printf("MLX75031 logging started. Press Ctrl+C to stop.\n");

    while (running) {
        int distance;
        if (read_distance(i2c_fd, &distance) == 0) {
            if (log_data(log_fp, distance) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Read failed; re-opening I2C.\n");
            if (log_data(log_fp, -1) < 0) {
                fprintf(stderr, "Logging error marker failed.\n");
            }
            close(i2c_fd);
            i2c_fd = -1;
            usleep(100000);
            i2c_fd = open_i2c();
            if (i2c_fd < 0) {
                fprintf(stderr, "Re-open failed; exiting.\n");
                break;
            }
            if (init_mlx75031(i2c_fd) < 0) {
                fprintf(stderr, "Re-init failed; exiting.\n");
                break;
            }
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

