#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x60
#define LOG_FILE       "biometric_log.txt"
#define SAMPLE_PERIOD  500000  /* microseconds (500 ms) */

/* Si1145 register addresses */
#define REG_PART_ID     0x00
#define REG_HW_KEY      0x07
#define REG_MEAS_RATE0  0x08
#define REG_MEAS_RATE1  0x09
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_PS1_DATA0   0x26
#define REG_PS1_DATA1   0x27

#define HW_KEY_VAL      0x17
#define MEAS_RATE0_VAL  0x00
#define MEAS_RATE1_VAL  0x00

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown on SIGINT / SIGTERM             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a Si1145 register; returns 0 on success, -1 on    */
/* I2C error.                                                          */
/* ------------------------------------------------------------------ */
static int si1145_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a Si1145 register; returns 0 on success, -1 on   */
/* I2C error.  Value is stored in *out.                                */
/* ------------------------------------------------------------------ */
static int si1145_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian sample from two consecutive registers.  */
/* ------------------------------------------------------------------ */
static int si1145_read_word(int handle, uint8_t reg_lo, uint16_t *out)
{
    uint8_t lo, hi;
    if (si1145_read_reg(handle, reg_lo, &lo) < 0)  return -1;
    if (si1145_read_reg(handle, reg_lo + 1, &hi) < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the Si1145: verify part ID, write HW_KEY, configure       */
/* measurement rate, and start autonomous measurements.               */
/* ------------------------------------------------------------------ */
static int si1145_init(int handle)
{
    uint8_t part_id;

    /* Verify the device identity */
    if (si1145_read_reg(handle, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "[ERROR] Cannot read PART_ID — sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "[ERROR] Unexpected PART_ID 0x%02X (expected 0x45).\n", part_id);
        return -1;
    }

    /* Mandatory HW_KEY write per datasheet */
    if (si1145_write_reg(handle, REG_HW_KEY, HW_KEY_VAL) < 0)
        return -1;

    /* Measurement rate: 0x0000 → 0 ms (standby) — we will drive via
       command register in the sample loop. */
    if (si1145_write_reg(handle, REG_MEAS_RATE0, MEAS_RATE0_VAL) < 0)
        return -1;
    if (si1145_write_reg(handle, REG_MEAS_RATE1, MEAS_RATE1_VAL) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Append one timestamped data line to the log file.                   */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(fp, "%s, Ambient Light: %u, Proximity: %u\n",
            timestamp, ambient_light, proximity);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times.                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialise sensor --- */
    if (si1145_init(g_i2c_handle) < 0) {
