    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si1145 logging started.  Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t ambient_light = 0, proximity = 0;
        int ok = 1;

        if (si1145_read_word(g_i2c_handle, REG_ALS_VIS_DATA0, &ambient_light) < 0)
            ok = 0;
        if (si1145_read_word(g_i2c_handle, REG_PS1_DATA0, &proximity) < 0)
