#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR_PIN 4
#define LED_PIN 17
#define LOG_FILE "proximity.log"
#define POLL_INTERVAL_US 100000
#define BLINK_DURATION_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_detection(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t rawtime = time(NULL);
    if (rawtime == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&rawtime, &tm_utc) == NULL) {
        perror("gmtime_r()");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s Object detected\n", timestamp) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip4\")");
        return EXIT_FAILURE;
    }

    struct gpiod_line *sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        perror("gpiod_chip_get_line(sensor)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line(led)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor_line, "proximity_sensor") < 0) {
        perror("gpiod_line_request_input(sensor)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "proximity_led", 0) < 0) {
        perror("gpiod_line_request_output(led)");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int last_state = 1;
    int ret = EXIT_SUCCESS;

    while (running) {
        int val = gpiod_line_get_value(sensor_line);
        if (val < 0) {
            perror("gpiod_line_get_value(sensor)");
            ret = EXIT_FAILURE;
            break;
        }

        if (last_state == 1 && val == 0) {
            if (log_detection() < 0) {
                fprintf(stderr, "Failed to log detection.\n");
            }

            if (gpiod_line_set_value(led_line, 1) < 0) {
                perror("gpiod_line_set_value(led, 1)");
                ret = EXIT_FAILURE;
                break;
            }
            usleep(BLINK_DURATION_US);
            if (gpiod_line_set_value(led_line, 0) < 0) {
                perror("gpiod_line_set_value(led, 0)");
                ret = EXIT_FAILURE;
                break;
            }
        }

        last_state = val;
        usleep(POLL_INTERVAL_US);
    }

    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(sensor_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return ret;
}

