#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1145_ADDR 0x60

#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_REV_ID 0x01
#define SI1145_REG_SEQ_ID 0x02
#define SI1145_REG_INT_CFG 0x03
#define SI1145_REG_IRQ_ENABLE 0x04
#define SI1145_REG_IRQ_MODE1 0x05
#define SI1145_REG_IRQ_MODE2 0x06
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_ALS_RATE 0x0A
#define SI1145_REG_PS_RATE 0x0B
#define SI1145_REG_PS_LED21 0x0F
#define SI1145_REG_PS_LED3 0x10
#define SI1145_REG_PARAM_WR 0x17
#define SI1145_REG_COMMAND 0x18
#define SI1145_REG_RESPONSE 0x20
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_PS1_DATA0 0x24
#define SI1145_REG_PS1_DATA1 0x25

#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_PS_FORCE 0x05
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_PSALS_FORCE 0x07
#define SI1145_CMD_PS_AUTO 0x0D
#define SI1145_CMD_ALS_AUTO 0x0E
#define SI1145_CMD_PSALS_AUTO 0x0F

#define SI1145_PARAM_CHLIST 0x01
#define SI1145_PARAM_PSLED12_SELECT 0x02
#define SI1145_PARAM_PSLED3_SELECT 0x03
#define SI1145_PARAM_PS_ENCODING 0x04
#define SI1145_PARAM_ALS_ENCODING 0x05
#define SI1145_PARAM_ALS_IR_ADCMUX 0x06
#define SI1145_PARAM_ALS_VIS_ADCMUX 0x07
#define SI1145_PARAM_ALS_UV_ADCMUX 0x08
#define SI1145_PARAM_PS_ADCMUX 0x09

#define SI1145_CHLIST_EN_ALS_VIS 0x10
#define SI1145_CHLIST_EN_ALS_IR 0x20
#define SI1145_CHLIST_EN_ALS_UV 0x40
#define SI1145_CHLIST_EN_PS1 0x01

#define SI1145_PART_ID 0x45
#define SI1145_HW_KEY_VAL 0x17

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_param(uint8_t param, uint8_t value) {
    if (i2cWriteByteData(i2c_handle, SI1145_REG_PARAM_WR, value) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, param) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int wait_response(uint8_t expected) {
    for (int i = 0; i < 10; i++) {
        int resp = i2cReadByteData(i2c_handle, SI1145_REG_RESPONSE);
        if (resp < 0) return -1;
        if ((resp & 0x0F) == expected) return 0;
        gpioDelay(10000);
    }
    return -1;
}

static int si1145_init(void) {
    int part_id = i2cReadByteData(i2c_handle, SI1145_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error: Failed to read PART_ID (I2C bus error).\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Error: Unexpected PART_ID 0x%02X (expected 0x%02X). Sensor not present?\n", part_id, SI1145_PART_ID);
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) return -1;
    gpioDelay(10000);

    if (i2cWriteByteData(i2c_handle, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) return -1;

    if (write_param(SI1145_PARAM_CHLIST, SI1145_CHLIST_EN_ALS_VIS | SI1145_CHLIST_EN_PS1) < 0) return -1;
    if (write_param(SI1145_PARAM_PSLED12_SELECT, 0x03) < 0) return -1;
    if (write_param(SI1145_PARAM_PS_ENCODING, 0x00) < 0) return -1;
    if (write_param(SI1145_PARAM_ALS_ENCODING, 0x00) < 0) return -1;
    if (write_param(SI1145_PARAM_ALS_VIS_ADCMUX, 0x00) < 0) return -1;
    if (write_param(SI1145_PARAM_PS_ADCMUX, 0x00) < 0) return -1;

    if (i2cWriteByteData(i2c_handle, SI1145_REG_MEAS_RATE0, 0x08) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, SI1145_REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, SI1145_REG_ALS_RATE, 0x08) < 0) return -1;
