#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27

#define SPEED_OF_SOUND_CM_PER_S 34300.0
#define MIN_DISTANCE_CM         2.0
#define MAX_DISTANCE_CM         400.0
#define WATERING_THRESHOLD_CM   15.0
#define LOG_FILE                "distance_log.txt"
#define TRIGGER_PULSE_US        10
#define ECHO_TIMEOUT_US         30000
#define LOOP_DELAY_S            60
#define SAMPLE_DELAY_US         500000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;
    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo);
}

static int log_message(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(fp, "%s %s\n", ts, msg);
    fclose(fp);
    return 0;
}

static int trigger_sensor(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -1;
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1;
    return 0;
}

static double measure_distance(void) {
    uint32_t start_tick = 0, end_tick = 0;
    int timeout;

    if (trigger_sensor() < 0) {
        fprintf(stderr, "Error triggering sensor\n");
        return -1.0;
    }

    timeout = ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0 && timeout > 0) {
        gpioDelay(1);
        timeout--;
    }
    if (timeout <= 0) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1.0;
    }
    start_tick = gpioTick();

    timeout = ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1 && timeout > 0) {
        gpioDelay(1);
        timeout--;
    }
    if (timeout <= 0) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1.0;
    }
    end_tick = gpioTick();

    double pulse_duration = (double)(end_tick - start_tick) / 1000000.0;
    double distance = (pulse_duration * SPEED_OF_SOUND_CM_PER_S) / 2.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1.0;
    }
    return distance;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize TRIGGER_PIN low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Plant watering monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        double distance = measure_distance();

        if (distance >= 0.0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Distance: %.2f cm", distance);
            log_message(msg);

            if (distance < WATERING_THRESHOLD_CM) {
                log_message("Time to water the plant!");
            }
        } else {
            log_message("Error measuring distance");
        }

        for (int i = 0; i < LOOP_DELAY_S && g_running; i++) {
            gpioDelay(SAMPLE_DELAY_US);
        }
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("Plant watering monitor stopped.\n");
    return EXIT_SUCCESS;
}

