#include <pigpio.h>

#define I2C_BUS 1
#define APDS9960_ADDR 0x39
#define PROXIMITY_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"

#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x01
#define APDS9960_PTIME 0x02
#define APDS9960_WTIME 0x03
#define APDS9960_PPULSE 0x0E
#define APDS9960_CONTROL 0x0F
#define APDS9960_CONFIG1 0x60
#define APDS9960_CONFIG2 0x61
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATA 0x9C

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (write(handle, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value) {
    if (write(handle, (char *)&reg, 1) != 1) return -1;
    if (read(handle, (char *)value, 1) != 1) return -1;
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(handle, (char *)&reg, 1) != 1) return -1;
    if (read(handle, (char *)buf, 2) != 2) return -1;
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_apds9960(int handle) {
    uint8_t id;
    if (i2c_read_byte(handle, APDS9960_ID, &id) < 0) {
        fprintf(stderr, "Error: Failed to read APDS9960 ID.\n");
        return -1;
    }
    if (id != 0xAB) {
        fprintf(stderr, "Error: Invalid APDS9960 ID: 0x%02X (expected 0xAB).\n", id);
        return -1;
    }
    if (i2c_write_byte(handle, APDS9960_ENABLE, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_ATIME, 0xFF) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_PTIME, 0xFF) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_WTIME, 0xFF) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_PPULSE, 0x40) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_CONTROL, 0x03) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_CONFIG1, 0x60) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_CONFIG2, 0x01) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_ENABLE, 0x0F) < 0) return -1;
    return 0;
}

static int read_proximity(int handle, uint8_t *proximity) {
    uint8_t status;
    if (i2c_read_byte(handle, APDS9960_STATUS, &status) < 0) return -1;
    if (!(status & 0x04)) return 1;
    if (i2c_read_byte(handle, APDS9960_PDATA, proximity) < 0) return -1;
    return 0;
}

static int read_color(int handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t status;
    if (i2c_read_byte(handle, APDS9960_STATUS, &status) < 0) return -1;
    if (!(status & 0x01)) return 1;
    if (i2c_read_word(handle, APDS9960_CDATAL, clear) < 0) return -1;
    if (i2c_read_word(handle, APDS9960_RDATAL, red) < 0) return -1;
    if (i2c_read_word(handle, APDS9960_GDATAL, green) < 0) return -1;
    if (i2c_read_word(handle, APDS9960_BDATAL, blue) < 0) return -1;
    return 0;
}

static void log_data(FILE *fp, uint16_t r, uint16_t g, uint16_t b, uint8_t prox) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, r, g, b, prox);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    char i2c_dev[20];
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);
    i2c_handle = open(i2c_dev, O_RDWR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d.\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_handle, I2C_SLAVE, APDS9960_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to acquire I2C bus access.\n");
        close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_apds9960(i2c_handle) < 0) {
        fprintf(stderr, "Error: APDS9960 initialization failed.\n");
        close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file %s.\n", LOG_FILE);
        close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        uint8_t prox;
        int ret = read_proximity(i2c_handle, &prox);
        if (ret < 0) {
            fprintf(stderr, "Error: I2C read error during proximity read. Re-initializing...\n");
            close(i2c_handle);
            i2c_handle = open(i2c_dev, O_RDWR);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Failed to re-open I2C bus.\n");
                break;
            }
            if (ioctl(i2c_handle, I2C_SLAVE, APDS9960_ADDR) < 0) {
                fprintf(stderr, "Error: Failed to re-acquire I2C bus access.\n");
                break;
            }
            if (init_apds9960(i2c_handle) < 0) {
                fprintf(stderr, "Error: APDS9960 re-initialization failed.\n");
                break;
            }
            continue;
        }

        if (prox > PROXIMITY_THRESHOLD) {
            uint16_t r, g, b, c;
            ret = read_color(i2c_handle, &c, &r, &g, &b);
            if (ret < 0) {
                fprintf(stderr, "Error: I2C read error during color read.\n");
            } else if (ret == 0) {
                log_data(log_file, r, g, b, prox);
            }
        }
        gpioDelay(100000);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) close(i2c_handle);
    gpioTerminate();
    return 0;
}

