/*
 * VL53L0X Time-of-Flight distance logger for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   VL53L0X SDA  -> GPIO 2  (I2C bus 1 SDA)
 *   VL53L0X SCL  -> GPIO 3  (I2C bus 1 SCL)
 *   VL53L0X VDD  -> 3.3 V
 *   VL53L0X GND  -> GND
 *   Trigger input -> GPIO 17 (BCM), falling edge, pull-up enabled.
 *
 * Build:  gcc -O2 -Wall -Wextra -o vl53l0x_logger vl53l0x_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

/* ---- VL53L0X register definitions (subset) ---- */
#define VL53L0X_ADDR                 0x29
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L0X_REG_SYSTEM_MODE_START        0x0000
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR   0x0015
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS  0x0044
#define VL53L0X_REG_RESULT_RANGE_STATUS      0x0089
#define VL53L0X_REG_RESULT_DISTANCE          0x0096

#define VL53L0X_MODEL_ID              0xEA
#define VL53L0X_CMD_START_SINGLE      0x01
#define VL53L0X_CMD_CLEAR_INT         0x01

/* ---- GPIO 17 (BCM) falling-edge trigger ---- */
#define GPIO_TRIGGER_PIN              17

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static FILE    *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */

static int i2c_write_reg8(int fd, uint16_t reg, uint8_t value)
{
    uint8_t buf[3] = {
        (uint8_t)(reg >> 8),
        (uint8_t)(reg & 0xFF),
        value
    };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write8 to 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint16_t reg, uint8_t *out)
{
    uint8_t addr[2] = {
        (uint8_t)(reg >> 8),
        (uint8_t)(reg & 0xFF)
    };
    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "I2C addr write to 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read8 from 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t addr[2] = {
        (uint8_t)(reg >> 8),
        (uint8_t)(reg & 0xFF)
    };
    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "I2C addr write to 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read16 from 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL53L0X sensor helpers                                             */
/* ------------------------------------------------------------------ */

static int vl53l0x_verify(int fd)
{
    uint8_t id = 0;
    if (i2c_read_reg8(fd, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &id) != 0)
        return -1;
    if (id != VL53L0X_MODEL_ID) {
        fprintf(stderr, "VL53L0X not detected (model ID 0x%02X, expected 0x%02X)\n",
                id, VL53L0X_MODEL_ID);
        return -1;
    }
    return 0;
}

static int vl53l0x_start_single(int fd)
{
    return i2c_write_reg8(fd, VL53L0X_REG_SYSTEM_MODE_START,
                          VL53L0X_CMD_START_SINGLE);
}

static int vl53l0x_clear_int(int fd)
{
    return i2c_write_reg8(fd, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR,
                          VL53L0X_CMD_CLEAR_INT);
}

static int vl53l0x_wait_data_ready(int fd, int timeout_ms)
{
    for (int elapsed = 0; elapsed < timeout_ms; elapsed += 10) {
        uint8_t status = 0;
        if (i2c_read_reg8(fd, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &status) != 0)
            return -1;
        if (status & 0x01)
            return 0;
        usleep(10000); /* 10 ms */
    }
    fprintf(stderr, "VL53L0X data-ready timeout\n");
    return -1;
}

static int vl53l0x_read_distance(int fd, uint16_t *distance_mm)
{
    uint16_t raw = 0;
    if (i2c_read_reg16(fd, VL53L0X_REG_RESULT_DISTANCE, &raw) != 0)
        return -1;
    *distance_mm = raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO edge detection (sysfs-based)                                  */
/* ------------------------------------------------------------------ */

static int gpio_setup(int pin)
{
    char path[128];
    char val;

    /* Export the pin if not already exported */
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    FILE *f = fopen(path, "r");
    if (!f) {
        snprintf(path, sizeof(path), "/sys/class/gpio/export", pin);
        FILE *exp = fopen(path, "w");
        if (!exp) {
            fprintf(stderr, "Failed to export GPIO %d: %s\n", pin, strerror(errno));
            return -1;
        }
        fprintf(exp, "%d", pin);
        fclose(exp);
        /* Give udev a moment to create the sysfs nodes */
        usleep(100000);
    } else {
        fclose(f);
    }

    /* Set direction to input */
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    f = fopen(path, "w");
    if (!f) {
        fprintf(stderr, "Failed to open direction for GPIO %d: %s\n",
                pin, strerror(errno));
        return -1;
    }
    fprintf(f, "in");
    fclose(f);

    /* Enable pull-up */
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    f = fopen(path, "r");
    if (!f) {
        fprintf(stderr, "Failed to open value for GPIO %d: %s\n",
                pin, strerror(errno));
        return -1;
    }
    val = '1';
    if (fwrite(&val, 1, 1, f) != 1) {
        fprintf(stderr, "Failed to write pull-up for GPIO %d: %s\n",
                pin, strerror(errno));
        fclose(f);
        return -1;
    }
    fclose(f);

    return 0;
}

static int gpio_wait_falling_edge(int pin, int timeout_ms)
{
    char path[128];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);

    FILE *f = fopen(path, "r");
    if (!f) {
        fprintf(stderr, "Failed to open GPIO %d value: %s\n",
                pin, strerror(errno));
        return -1;
    }

    int prev = 1; /* assume pull-up high */
    for (int elapsed = 0; elapsed < timeout_ms; elapsed += 10) {
        int cur = fgetc(f);
        if (cur == EOF) {
            fprintf(stderr, "Failed to read GPIO %d: %s\n",
                    pin, strerror(errno));
            fclose(f);
            return -1;
        }
        if (cur == '0' && prev == '1') {
            fclose(f);
            return 0;
        }
        prev = cur;
        usleep(10000); /* 10 ms */
    }

    fclose(f);
    fprintf(stderr, "GPIO %d falling-edge timeout\n", pin);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */

static int log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%u\n", ts, distance_mm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- Open I2C bus 1 ---- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
