#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x50
#define TRIGGER_CMD    0x01
#define READ_CMD       0x02
#define LOG_FILE       "distance_log.txt"
#define SAMPLE_US      200000   /* 200 ms */
#define TRIGGER_US     50000    /* 50 ms  */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        perror("i2c write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t *byte)
{
    if (read(fd, byte, 1) != 1) {
        perror("i2c read failed");
        return -1;
    }
    return 0;
}

static int init_i2c(void)
{
    char dev[32];
    snprintf(dev, sizeof(dev), "/dev/i2c-%d", I2C_BUS);

    g_i2c_fd = open(dev, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open i2c device failed");
        return -1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE failed");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int read_distance(int fd, int *distance_mm)
{
    uint8_t cmd = TRIGGER_CMD;
    uint8_t data;

    if (i2c_write_byte(fd, cmd) < 0)
        return -1;

    gpioDelay(TRIGGER_US);

    cmd = READ_CMD;
    if (i2c_write_byte(fd, cmd) < 0)
        return -1;

    if (i2c_read_byte(fd, &data) < 0)
        return -1;

    *distance_mm = (int)data;
    return 0;
}

static void log_distance(FILE *fp, int distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s, %d\n", timestamp, distance_mm);
    fflush(fp);
    printf("%s, %d\n", timestamp, distance_mm);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction failed");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen log file failed");
        close(g_i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (g_running) {
        int distance_mm;

        if (read_distance(g_i2c_fd, &distance_mm) == 0) {
            log_distance(g_log_fp, distance_mm);
        } else {
            fprintf(stderr, "Error reading distance, skipping sample\n");
        }

        gpioDelay(SAMPLE_US);
    }

    fprintf(stderr, "\nExiting gracefully...\n");

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();

    return 0;
}

