code:
/*
 * Raspberry Pi Zero W – ICU-20201 Ultrasonic ToF Distance Monitor
 *
 * Hardware:
 *   - TDK InvenSense ICU-20201 on I2C bus 1 (address 0x58)
 *   - LED + 330 Ω resistor on GPIO 17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o distance_monitor distance_monitor.c \
 *       -lpigpio -lrt
 *
 * Run:
 *   sudo ./distance_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ICU20201_ADDR        0x58
#define LED_GPIO             17
#define DISTANCE_THRESHOLD   20.0f   /* cm */
#define SAMPLE_PERIOD_US     100000  /* 100 ms */
#define LOG_FILE             "distance_log.txt"

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_distance(float distance)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Warning: time() failed\n");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Warning: localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Warning: strftime() failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s, Distance: %.2f cm\n", ts, distance) < 0) {
        fprintf(stderr, "Warning: fprintf to log file failed\n");
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Warning: fflush on log file failed\n");
    }
}

/* ----------------------------- Sensor driver ----------------------------- */
/*
 * The ICU-20201 exposes a 16-bit distance register (0x00) and a 16-bit
 * temperature register (0x02).  The distance value is in centimetres
 * (Q0.0 format) and is read as two bytes, MSB first.
 */
static int icu20201_read_distance(int handle, float *distance_out)
{
    if (handle < 0 || distance_out == NULL) {
        return -1;
    }

    /*
     * Write the register pointer (0x00) to select the distance register
     * before reading two bytes.
     */
    if (i2cWriteByte(handle, 0x00) < 0) {
        return -1;
    }

    /*
     * Small delay so the sensor has time to latch the register pointer
     * before the master issues a repeated-start read.
     */
    gpioDelay(2000); /* 2 ms */

    char buf[2];
    int  n = i2cReadDevice(handle, buf, 2);
    if (n != 2) {
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *distance_out = (float)raw;
    return 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    /* Ensure LED is off before terminating pigpio */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d) – sensor may be absent\n",
                g_i2c_handle);
        fclose(g_log_file);
        g_log_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure LED GPIO --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed\n");
    }

    printf("Monitoring ICU-20201 distance (threshold %.1f cm). Ctrl+C to exit.\n",
           DISTANCE_THRESHOLD);

    /* --- Main loop --- */
    while (g_running) {
        float distance = 0.0f;

        if (icu20201_read_distance(g_i2c_handle, &distance) != 0) {
            fprintf(stderr, "Error: I2C read failed – continuing\n");
            gpioWrite(LED_GPIO, 0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        log_distance(distance);

        if (distance < DISTANCE_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

