code:
/*
 * Si1182-GMR Proximity & Ambient Light Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   Si1182 SDA  -> GPIO2 (I2C1 SDA, pin 3)
 *   Si1182 SCL  -> GPIO3 (I2C1 SCL, pin 5)
 *   Si1182 VDD  -> 3.3 V
 *   Si1182 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o si1182_logger si1182_logger.c -lpigpio -lrt
 * Run:    sudo ./si1182_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si1182-GMR I2C address ---- */
#define SI1182_I2C_ADDR 0x60

/* ---- Si1182-GMR register addresses ---- */
#define SI1182_REG_PART_ID      0x00
#define SI1182_REG_REV_ID       0x01
#define SI1182_REG_HW_KEY       0x07
#define SI1182_REG_MEAS_RATE0   0x08
#define SI1182_REG_MEAS_RATE1   0x09
#define SI1182_REG_ALS_RATE     0x0A
#define SI1182_REG_PS_RATE      0x0B
#define SI1182_REG_ALS_IR_ADC_GAIN 0x0C
#define SI1182_REG_ALS_VIS_ADC_GAIN 0x0D
#define SI1182_REG_PS_ADC_GAIN   0x0E
#define SI1182_REG_ALS_IR_DATA0 0x10
#define SI1182_REG_ALS_VIS_DATA0 0x12
#define SI1182_REG_PS_DATA0     0x14
#define SI1182_REG_COMMAND      0x30

/* ---- Si1182-GMR command codes ---- */
#define SI1182_CMD_RESET        0x01
#define SI1182_CMD_ALS_PS_FORCE 0x07

/* ---- Expected chip ID ---- */
#define SI1182_PART_ID_EXPECTED 0x82

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a register; returns 0 on success, -1 on error.   */
/* ------------------------------------------------------------------ */
static int si1182_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a register; returns 0 on success, -1 on error.  */
/* ------------------------------------------------------------------ */
static int si1182_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair; returns 0 on success.   */
/* ------------------------------------------------------------------ */
static int si1182_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the Si1182-GMR sensor.                                   */
/* ------------------------------------------------------------------ */
static int si1182_init(int handle)
{
    uint8_t part_id = 0;

    /* 1. Software reset */
    if (si1182_write_reg(handle, SI1182_REG_COMMAND, SI1182_CMD_RESET) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms settle after reset */

    /* 2. Verify chip identity */
    if (si1182_read_reg(handle, SI1182_REG_PART_ID, &part_id) != 0)
        return -1;
    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr, "[ERROR] Unexpected PART_ID: 0x%02X (expected 0x%02X) — "
                        "wrong sensor or not present.\n",
                part_id, SI1182_PART_ID_EXPECTED);
        return -1;
    }
    printf("[INFO] Si1182-GMR detected (PART_ID=0x%02X).\n", part_id);

    /* 3. Write HW_KEY (required by datasheet) */
    if (si1182_write_reg(handle, SI1182_REG_HW_KEY, 0x00) != 0)
        return -1;

    /* 4. Configure ADC gains */
    if (si1182_write_reg(handle, SI1182_REG_ALS_IR_ADC_GAIN,  0x00) != 0) return -1;
    if (si1182_write_reg(handle, SI1182_REG_ALS_VIS_ADC_GAIN, 0x00) != 0) return -1;
    if (si1182_write_reg(handle, SI1182_REG_PS_ADC_GAIN,      0x00) != 0) return -1;

    /* 5. Set measurement rates (0x00 = continuous, 0x00 = 10 ms) */
    if (si1182_write_reg(handle, SI1182_REG_MEAS_RATE0, 0x00) != 0) return -1;
    if (si1182_write_reg(handle, SI1182_REG_MEAS_RATE1, 0x00) != 0) return -1;

    /* 6. Trigger a forced ALS+PS measurement */
    if (si1182_write_reg(handle, SI1182_REG_COMMAND, SI1182_CMD_ALS_PS_FORCE) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read proximity data with retry; returns 0 on success, -1 on error. */
/* ------------------------------------------------------------------ */
static int read_proximity(int handle, uint16_t *proximity)
{
    for (int attempt = 1; attempt <= 3; attempt++) {
        if (si1182_read_reg16(handle, SI1182_REG_PS_DATA0, proximity) == 0)
            return 0;
        fprintf(stderr, "[WARN] Proximity read attempt %d/3 failed.\n", attempt);
        gpioDelay(10000); /* 10 ms back-off */
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read ambient light data with retry; returns 0 on success, -1 on err.*/
/* ------------------------------------------------------------------ */
static int read_ambient_light(int handle, uint16_t *ambient_light)
{
    for (int attempt = 1; attempt <= 3; attempt++) {
        if (si1182_read_reg16(handle, SI1182_REG_ALS_VIS_DATA0, ambient_light) == 0)
            return 0;
        fprintf(stderr, "[WARN] Ambient light read attempt %d/3 failed.\n", attempt);
        gpioDelay(10000); /* 10 ms back-off */
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the log file.                      */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t proximity, uint16_t ambient_light)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s, Proximity: %u, Ambient Light: %u\n",
            timestamp, proximity, ambient_light);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times.                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at the Si1182-GMR address ---- */
    g_i2c_handle = i2cOpen(1, SI1182_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                SI1182_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file in append mode ---- */
    g_log_file = fopen("biometric_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open biometric_log.txt for appending.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (si1182_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Si1182-GMR initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Logging Si1182-GMR data to biometric_log.txt (Ctrl+C to stop).\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint16_t proximity     = 0;
        uint16_t ambient_light = 0;

        if (read_proximity(g_i2c_handle, &proximity) != 0) {
            fprintf(stderr, "[ERROR] Proximity read failed after retries — "
                            "sensor may be disconnected.\n");
        } else if (read_ambient_light(g_i2c_handle, &ambient_light) != 0) {
            fprintf(stderr, "[ERROR] Ambient light read failed after retries.\n");
        } else {
            log_data(g_log_file, proximity, ambient_light);
        }

        /* Sleep 500 ms (500 000 microseconds) */
        gpioDelay(500000);
    }

    /* ---- Graceful shutdown ---- */
    printf("\n[INFO] Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

