/* ------------------------------------------------------------------ */
/* Write one byte to a register; returns 0 on success, -1 on error.   */
/* ------------------------------------------------------------------ */
static int si1182_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a register; returns 0 on success, -1 on error.  */
/* ------------------------------------------------------------------ */
static int si1182_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
