    if (si1182_read_reg(handle, SI1182_REG_PART_ID, &part_id) != 0)
        return -1;
    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr, "[ERROR] Unexpected PART_ID: 0x%02X (expected 0x%02X) — "
                        "wrong sensor or not present.\n",
                part_id, SI1182_PART_ID_EXPECTED);
        return -1;
    }
    printf("[INFO] Si1182-GMR detected (PART_ID=0x%02X).\n", part_id);

    /* 3. Write HW_KEY (required by datasheet) */
    if (si1182_write_reg(handle, SI1182_REG_HW_KEY, 0x00) != 0)
        return -1;

