    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Logging Si1182-GMR data to biometric_log.txt (Ctrl+C to stop).\n");

