/*
 * Raspberry Pi 4 Model B – TDK InvenSense ICU-20201 ToF sensor reader
 *
 * Wiring:
 *   ICU-20201 SDA  -> GPIO 2  (I2C bus 1 SDA)
 *   ICU-20201 SCL  -> GPIO 3  (I2C bus 1 SCL)
 *   ICU-20201 VDD  -> 3.3 V
 *   ICU-20201 GND  -> GND
 *   LED anode      -> GPIO 17 (BCM) via 330 Ω resistor
 *   LED cathode    -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o tof_reader tof_reader.c -lpigpio -lrt
 * Run:    sudo ./tof_reader [threshold_mm]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ICU-20201 register map (representative subset) ---- */
#define ICU20201_I2C_ADDR      0x58
#define ICU20201_REG_WHO_AM_I  0x00
#define ICU20201_REG_DIST_MSB  0x04
#define ICU20201_REG_DIST_LSB  0x05
#define ICU20201_WHO_AM_I_VAL  0x20

#define GPIO_LED              17
#define LOG_FILE              "tof_log.txt"
#define POLL_INTERVAL_US      50000   /* 50 ms */
#define I2C_BUS               1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
static int initialize_sensor(void)
{
    int who = i2cReadByteData(g_i2c_handle, ICU20201_REG_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: I2C read of WHO_AM_I failed (pigpio rc=%d).\n", who);
        return -1;
    }
    if (who != ICU20201_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X). "
                        "Sensor absent or wrong device.\n", who, ICU20201_WHO_AM_I_VAL);
        return -1;
    }

    /* Software reset via register 0x01 (example placeholder) */
    if (i2cWriteByteData(g_i2c_handle, 0x01, 0x01) < 0) {
        fprintf(stderr, "Warning: software reset write failed; continuing.\n");
    }
    gpioDelay(10000); /* 10 ms settle */
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_distance_mm(uint16_t *distance_mm)
{
    int msb = i2cReadByteData(g_i2c_handle, ICU20201_REG_DIST_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error: DIST_MSB read failed (pigpio rc=%d).\n", msb);
        return -1;
    }
    int lsb = i2cReadByteData(g_i2c_handle, ICU20201_REG_DIST_LSB);
    if (lsb < 0) {
        fprintf(stderr, "Error: DIST_LSB read failed (pigpio rc=%d).\n", lsb);
        return -1;
    }
    *distance_mm = ((uint16_t)msb << 8) | (uint16_t)lsb;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(uint16_t distance_mm, int threshold_mm, int below)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %u mm, "
                    "Threshold: %d mm, Below: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                distance_mm, threshold_mm, below ? "YES" : "NO");
    } else {
        fprintf(fp, "(timestamp error), Distance: %u mm, Threshold: %d mm, "
                    "Below: %s\n", distance_mm, threshold_mm, below ? "YES" : "NO");
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int threshold_mm = 100;

    if (argc > 1) {
        threshold_mm = atoi(argv[1]);
        if (threshold_mm <= 0) {
            fprintf(stderr, "Invalid threshold '%s'; using default 100 mm.\n", argv[1]);
            threshold_mm = 100;
        }
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, ICU20201_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio rc=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: ICU-20201 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Warning: sigaction(SIGINT) failed");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Warning: sigaction(SIGTERM) failed");
    }

    printf("ICU-20201 ToF reader started. Threshold: %d mm. Press Ctrl+C to exit.\n",
           threshold_mm);

    /* ---- Main loop ---- */
    while (g_running) {
        uint16_t distance_mm = 0;

        if (read_distance_mm(&distance_mm) == 0) {
            int below = (distance_mm < (uint16_t)threshold_mm);
            gpioWrite(GPIO_LED, below ? 1 : 0);
            log_data(distance_mm, threshold_mm, below);
            printf("Distance: %u mm, Below: %s\n", distance_mm, below ? "YES" : "NO");
        } else {
            fprintf(stderr, "Read error – continuing.\n");
            gpioWrite(GPIO_LED, 0);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

