    gpioDelay(10000); /* 10 ms settle */
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_distance_mm(uint16_t *distance_mm)
{
    int msb = i2cReadByteData(g_i2c_handle, ICU20201_REG_DIST_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error: DIST_MSB read failed (pigpio rc=%d).\n", msb);
        return -1;
    }
    int lsb = i2cReadByteData(g_i2c_handle, ICU20201_REG_DIST_LSB);
    if (lsb < 0) {
        fprintf(stderr, "Error: DIST_LSB read failed (pigpio rc=%d).\n", lsb);
        return -1;
    }
    *distance_mm = ((uint16_t)msb << 8) | (uint16_t)lsb;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(uint16_t distance_mm, int threshold_mm, int below)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %u mm, "
                    "Threshold: %d mm, Below: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                distance_mm, threshold_mm, below ? "YES" : "NO");
    } else {
        fprintf(fp, "(timestamp error), Distance: %u mm, Threshold: %d mm, "
                    "Below: %s\n", distance_mm, threshold_mm, below ? "YES" : "NO");
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int threshold_mm = 100;

    if (argc > 1) {
        threshold_mm = atoi(argv[1]);
        if (threshold_mm <= 0) {
            fprintf(stderr, "Invalid threshold '%s'; using default 100 mm.\n", argv[1]);
            threshold_mm = 100;
        }
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, ICU20201_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio rc=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: ICU-20201 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Warning: sigaction(SIGINT) failed");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Warning: sigaction(SIGTERM) failed");
    }

    printf("ICU-20201 ToF reader started. Threshold: %d mm. Press Ctrl+C to exit.\n",
           threshold_mm);

    /* ---- Main loop ---- */
    while (g_running) {
        uint16_t distance_mm = 0;

        if (read_distance_mm(&distance_mm) == 0) {
            int below = (distance_mm < (uint16_t)threshold_mm);
            gpioWrite(GPIO_LED, below ? 1 : 0);
            log_data(distance_mm, threshold_mm, below);
            printf("Distance: %u mm, Below: %s\n", distance_mm, below ? "YES" : "NO");
        } else {
            fprintf(stderr, "Read error – continuing.\n");
            gpioWrite(GPIO_LED, 0);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

