#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR_ADDR    0x50
#define INTRUSION_THRESHOLD_MM 1000
#define NUM_SAMPLES    10
#define SAMPLE_DELAY_US 100000
#define MEAS_DELAY_US  10000
#define LOG_FILE       "intrusion_log.txt"

/* B5L-LD50-07050 command frame (4 bytes) */
static const uint8_t CMD_FRAME[4] = {0x01, 0x02, 0x03, 0x04};
/* B5L-LD50-07050 response frame (15 bytes) */
#define RESP_LEN       15
#define RESP_HEADER    0x55
#define DIST_HI        11
#define DIST_LO        12

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write(int fd, const uint8_t *buf, size_t len)
{
    ssize_t n = write(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short write: %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int request_measurement(int fd)
{
    return i2c_write(fd, CMD_FRAME, sizeof(CMD_FRAME));
}

static int read_response(int fd, uint8_t *resp)
{
    return i2c_read(fd, resp, RESP_LEN);
}

static int process_response(const uint8_t *resp, int16_t *distance_mm)
{
    if (resp[0] != RESP_HEADER) {
        fprintf(stderr, "Invalid response header: 0x%02X (expected 0x%02X)\n",
                resp[0], RESP_HEADER);
        return -1;
    }
    *distance_mm = (int16_t)((resp[DIST_HI] << 8) | resp[DIST_LO]);
    return 0;
}

static int log_intrusion(float avg_distance)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Average Distance: %.2f mm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, avg_distance);
    } else {
        fprintf(fp, "Timestamp error, Average Distance: %.2f mm\n", avg_distance);
    }
    fclose(fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SENSOR_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float total_distance = 0.0f;
        int valid_samples = 0;

        for (int i = 0; i < NUM_SAMPLES && g_running; i++) {
            if (request_measurement(g_i2c_fd) < 0) {
                usleep(SAMPLE_DELAY_US);
                continue;
            }
            usleep(MEAS_DELAY_US);

            uint8_t resp[RESP_LEN];
            if (read_response(g_i2c_fd, resp) < 0) {
                usleep(SAMPLE_DELAY_US);
                continue;
            }

            int16_t distance;
            if (process_response(resp, &distance) < 0) {
                usleep(SAMPLE_DELAY_US);
                continue;
            }

            total_distance += (float)distance;
            valid_samples++;
            usleep(SAMPLE_DELAY_US);
        }

        if (valid_samples > 0) {
            float avg_distance = total_distance / (float)valid_samples;
            printf("Average Distance: %.2f mm\n", avg_distance);

            if (avg_distance < INTRUSION_THRESHOLD_MM) {
                printf("Intrusion detected!\n");
                if (log_intrusion(avg_distance) < 0) {
                    fprintf(stderr, "Failed to log intrusion.\n");
                }
            }
        } else {
            fprintf(stderr, "No valid samples in this cycle.\n");
        }
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

