#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define VL53L0X_ADDR   0x29

#define REG_MODEL_ID              0x010F
#define EXPECTED_MODEL_ID         0xEA
#define REG_SYSRANGE_START        0x0000
#define REG_RESULT_INTERRUPT_STATUS 0x0044
#define REG_RESULT_RANGE_STATUS   0x0089
#define REG_RESULT_DISTANCE       0x0096

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint16_t reg, uint8_t val) {
    uint8_t buf[3] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF), val };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg8(int fd, uint16_t reg, uint8_t *val) {
    uint8_t buf[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(fd, buf, 2) != 2) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *val) {
    uint8_t buf[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(fd, buf, 2) != 2) return -1;
    uint8_t data[2];
    if (read(fd, data, 2) != 2) return -1;
    *val = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    return 0;
}

static int vl53l0x_init(int fd) {
    uint8_t model_id = 0;
    if (i2c_read_reg8(fd, REG_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0x%02X)\n", model_id, EXPECTED_MODEL_ID);
        return -1;
    }
    return 0;
}

static int vl53l0x_read_distance(int fd, uint16_t *distance) {
    if (i2c_write_reg8(fd, REG_SYSRANGE_START, 0x01) < 0) return -1;

    for (int i = 0; i < 100; i++) {
        uint8_t status = 0;
        if (i2c_read_reg8(fd, REG_RESULT_INTERRUPT_STATUS, &status) < 0) return -1;
        if (status & 0x07) break;
        usleep(1000);
    }

    uint8_t range_status = 0;
    if (i2c_read_reg8(fd, REG_RESULT_RANGE_STATUS, &range_status) < 0) return -1;
    if (range_status & 0x01) {
        uint16_t dist = 0;
        if (i2c_read_reg16(fd, REG_RESULT_DISTANCE, &dist) < 0) return -1;
        *distance = dist;
        return 0;
    }
    return -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_fd, I2C_SLAVE, VL53L0X_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", VL53L0X_ADDR, strerror(errno));
        close(g_fd);
        return 1;
    }

    if (vl53l0x_init(g_fd) < 0) {
        fprintf(stderr, "VL53L0X initialization failed.\n");
        close(g_fd);
        return 1;
    }

    printf("VL53L0X initialized successfully. Reading distance...\n");

    while (g_running) {
        uint16_t distance = 0;
        if (vl53l0x_read_distance(g_fd, &distance) < 0) {
            fprintf(stderr, "Warning: Error reading distance: %s\n", strerror(errno));
        } else {
            time_t rawtime;
            time(&rawtime);
            struct tm *timeinfo = localtime(&rawtime);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s Distance: %u mm\n", timestamp, distance);
            fflush(stdout);
        }
        usleep(500000);
    }

    if (g_fd >= 0) close(g_fd);
    printf("\nExiting gracefully.\n");
    return 0;
}

