/*
 * Si1182 Proximity Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   Si1182 SDA -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   Si1182 SCL -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   Si1182 VDD -> 3.3 V
 *   Si1182 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1182_prox si1182_prox.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x60          /* Si1182 7-bit I2C address (ADDR pin tied to GND) */

/* Si1182 register addresses */
#define SI1182_REG_HW_KEY      0x07
#define SI1182_REG_MEAS_RATE0  0x08
#define SI1182_REG_MEAS_RATE1  0x09
#define SI1182_REG_PS_RATE     0x0A
#define SI1182_REG_PS_LED21    0x0F
#define SI1182_REG_PS1_DATA0   0x10
#define SI1182_REG_PS1_DATA1   0x11
#define SI1182_REG_COMMAND     0x30

/* Si1182 command codes */
#define SI1182_CMD_RESET       0x01
#define SI1182_CMD_PS_FORCE    0x05

/* Expected HW_KEY value after a reset */
#define SI1182_HW_KEY_EXPECTED 0x17

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to a Si1182 register; returns 0 on success, -1 on error. */
static int si1182_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t ret = write(fd, buf, sizeof(buf));
    if (ret != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "write(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a single byte from a Si1182 register; returns 0 on success, -1 on error. */
static int si1182_read_reg(int fd, uint8_t reg, uint8_t *value)
{
    ssize_t ret = write(fd, &reg, 1);
    if (ret != 1) {
        fprintf(stderr, "write(reg=0x%02X) for read failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ret = read(fd, value, 1);
    if (ret != 1) {
        fprintf(stderr, "read(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit little-endian register pair; returns 0 on success, -1 on error. */
static int si1182_read_reg16(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t lo, hi;
    if (si1182_read_reg(fd, reg, &lo) < 0)
        return -1;
    if (si1182_read_reg(fd, reg + 1, &hi) < 0)
        return -1;
    *value = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* Send a command to the Si1182 command register. */
static int si1182_send_command(int fd, uint8_t cmd)
{
    return si1182_write_reg(fd, SI1182_REG_COMMAND, cmd);
}

/* Reset the Si1182 and verify the HW_KEY register. */
static int si1182_reset(int fd)
{
    if (si1182_send_command(fd, SI1182_CMD_RESET) < 0)
        return -1;

    /* Allow the reset to complete (typical 10 ms). */
    usleep(15000);

    uint8_t hw_key = 0;
    if (si1182_read_reg(fd, SI1182_REG_HW_KEY, &hw_key) < 0)
        return -1;

    if (hw_key != SI1182_HW_KEY_EXPECTED) {
        fprintf(stderr, "Unexpected HW_KEY: 0x%02X (expected 0x%02X) - sensor may be absent or wrong part\n",
                hw_key, SI1182_HW_KEY_EXPECTED);
        return -1;
    }

    return 0;
}

/* Configure the Si1182 for forced proximity measurements. */
static int si1182_configure(int fd)
{
    /* Measurement rate: 0x0000 = manual / forced mode. */
    if (si1182_write_reg(fd, SI1182_REG_MEAS_RATE0, 0x00) < 0)
        return -1;
    if (si1182_write_reg(fd, SI1182_REG_MEAS_RATE1, 0x00) < 0)
        return -1;

    /* PS measurement rate: 0x00 = disabled (we use forced mode). */
    if (si1182_write_reg(fd, SI1182_REG_PS_RATE, 0x00) < 0)
        return -1;

    /* PS LED current: LED1 = 100 mA, LED2 = 100 mA. */
    if (si1182_write_reg(fd, SI1182_REG_PS_LED21, 0x03) < 0)
        return -1;

    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus. */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the Si1182 device. */
    if (ioctl(fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI1182_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Reset and verify the sensor. */
    if (si1182_reset(fd) < 0) {
        fprintf(stderr, "Si1182 reset/verification failed - check wiring and address\n");
        goto cleanup;
    }

    /* Configure the sensor. */
    if (si1182_configure(fd) < 0) {
        fprintf(stderr, "Si1182 configuration failed\n");
        goto cleanup;
    }

    printf("Si1182 proximity sensor initialized (addr 0x%02X on %s).\n",
           SI1182_ADDR, I2C_BUS);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop: trigger a forced PS measurement and read the result. */
    while (g_running) {
        if (si1182_send_command(fd, SI1182_CMD_PS_FORCE) < 0) {
            fprintf(stderr, "Failed to trigger PS measurement\n");
            break;
        }

        /* Wait for the conversion to complete (typical 10 ms). */
        usleep(15000);

        uint16_t proximity = 0;
        if (si1182_read_reg16(fd, SI1182_REG_PS1_DATA0, &proximity) < 0) {
            fprintf(stderr, "Failed to read proximity data\n");
            break;
        }

        printf("Proximity: %u\n", (unsigned)proximity);
        fflush(stdout);

        /* 500 ms loop period. */
        usleep(500000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

