#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75030_ADDR  0x50
#define DIST_REG       0x00
#define POLL_MS        500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int setup_signals(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int read_distance(int fd, uint16_t *distance)
{
    uint8_t reg = DIST_REG;
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select): %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (distance): %s\n", strerror(errno));
        return -1;
    }
    *distance = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (setup_signals() != 0)
        goto out;

    fd = i2c_open(I2C_BUS, MLX75030_ADDR);
    if (fd < 0)
        goto out;

    printf("MLX75030 distance sensor ready on %s (addr 0x%02X).\n",
           I2C_BUS, MLX75030_ADDR);
    fflush(stdout);

    while (g_running) {
        uint16_t dist;
        if (read_distance(fd, &dist) == 0) {
            printf("Distance: %u mm\n", dist);
            fflush(stdout);
        } else {
            fprintf(stderr, "Read failed; continuing.\n");
        }

        struct timespec ts = { 0, POLL_MS * 1000000L };
        while (nanosleep(&ts, &ts) == -1 && errno == EINTR && g_running)
            ;
    }

    rc = EXIT_SUCCESS;

out:
    if (fd >= 0)
        close(fd);
    return rc;
}

