/*
 * OPT3101 Time-of-Flight sensor reader for Raspberry Pi Zero W
 * Bus: I2C-1 (GPIO2=SDA, GPIO3=SCL), address 0x44
 * Reads channel 0 distance and ambient light every 500 ms.
 * Handles I2C errors and exits cleanly on SIGINT.
 *
 * Build: gcc -O2 -Wall -o opt3101_reader opt3101_reader.c -lpigpio -lrt
 * Run:   sudo ./opt3101_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define OPT3101_ADDR        0x44
#define I2C_BUS             1
#define SAMPLE_PERIOD_US    500000  /* 500 ms */

/* OPT3101 register addresses */
#define REG_DEVICE_ID       0x00
#define REG_RESULT_CH0      0x10
#define REG_RESULT_CH1      0x12
#define REG_AMBIENT         0x14
#define REG_ERROR_FLAGS     0x16
#define REG_CONFIG          0x0A

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
