/*
 * HC-SR04 Ultrasonic Distance Sensor Reader
 * Board:  Raspberry Pi 3 Model B+
 * Trigger: GPIO 17 (BCM)
 * Echo:    GPIO 18 (BCM)
 *
 * NOTE: The HC-SR04 operates at 5 V and the Raspberry Pi GPIO is only
 * 3.3 V tolerant. A 1 kOhm resistor must be placed on the echo line
 * to protect the Pi. This is a library-level API call() and the
 * resistor must be wired externally.
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 µs trigger pulse            */
#define ECHO_TIMEOUT_US  200000      /* 200 ms max wait for echo edges */
#define MAX_DISTANCE_CM  400.0       /* HC-SR04 max range              */
#define SPEED_OF_SOUND   34300.0     /* cm/s at 20 °C                  */
#define SAMPLE_PERIOD_S  1.0         /* 1 Hz sampling                  */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/* Return elapsed microseconds between two pigpio ticks (32-bit wrap). */
static uint32_t tick_diff(uint32_t start, uint32_t end)
{
    return (uint32_t)(end - start);  /* unsigned subtraction wraps */
}

/* Return a static timestamp string: YYYY-MM-DD HH:MM:SS */
static const char *timestamp_str(void)
{
    static char buf[20];
    time_t now = time(NULL);
    struct tm tmv;
    if (localtime_r(&now, &tmv) != NULL) {
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tmv);
    } else {
        snprintf(buf, sizeof(buf), "----");
    }
    return buf;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */

/*
 * Read distance in centimetres from the HC-SR04.
 *
 * Returns:
 *   >= 0.0  valid distance in cm
 *   -1.0    echo rising-edge timeout
 *   -2.0    echo falling-edge timeout
 *   -3.0    pulse duration out of HC-SR04 range (<= 0 or > 38 ms)
 */
static double read_distance(void)
{
    uint32_t start_tick, end_tick;
    uint32_t pulse_us;

    /* Issue 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 1) failed\n");
        return -3.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -3.0;
    }

    /* Wait for echo rising edge */
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > ECHO_TIMEOUT_US) {
            return -1.0;  /* rising-edge timeout */
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - echo_start > ECHO_TIMEOUT_US) {
            return -2.0;  /* falling-edge timeout */
        }
    }
    end_tick = gpioTick();

    pulse_us = tick_diff(echo_start, end_tick);

    /* Validate pulse duration (HC-SR04 max range ~38 ms) */
    if (pulse_us <= 0 || pulse_us > 38000) {
        return -3.0;
    }

    /* distance = (pulse_us * speed_of_sound) / 2 */
    return (double)pulse_us * SPEED_OF_SOUND / 2000000.0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) initial failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow sensor to settle */
    gpioDelay(100000);  /* 100 ms */

    printf("HC-SR04 distance sensor started.\n");
    printf("Trigger: GPIO %d | Echo: GPIO %d | Sample: %.1f Hz\n",
           TRIGGER_PIN, ECHO_PIN, 1.0 / SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main sampling loop */
    while (g_running) {
        double distance = read_distance();

        if (distance >= 0.0) {
            printf("[%s] Distance: %.2f cm\n", timestamp_str(), distance);
        } else {
            const char *reason;
            switch ((int)distance) {
                case -1: reason = "echo rising-edge timeout";  break;
                case -2: reason = "echo falling-edge timeout"; break;
                case -3: reason = "pulse out of range";         break;
                default: reason = "unknown error";              break;
            }
            fprintf(stderr, "[%s] Error: %s\n", timestamp_str(), reason);
        }

        time_sleep(SAMPLE_PERIOD_S);
    }

    /* Graceful cleanup */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

