static const uint8_t MAGIC_WORD[MAGIC_WORD_SIZE] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_exact(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "UART read error: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART read timeout\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int find_magic_word(int fd) {
    uint8_t byte;
    int match_idx = 0;

    while (running) {
        if (read_exact(fd, &byte, 1) != 0) return -1;

        if (byte == MAGIC_WORD[match_idx]) {
            match_idx++;
            if (match_idx == MAGIC_WORD_SIZE) return 0;
        } else {
            match_idx = 0;
        }
    }
    return -1;
}

static int decode_range_profile(int fd, float *distances, int num_bins) {
    uint8_t raw_data[DATA_FRAME_SIZE];
    if (read_exact(fd, raw_data, DATA_FRAME_SIZE) != 0) return -1;

    for (int i = 0; i < num_bins; i++) {
        int16_t magnitude = (int16_t)((raw_data[2 * i + 1] << 8) | raw_data[2 * i]);
        distances[i] = (float)abs(magnitude) * 0.01f;
    }
    return 0;
}

static int check_threshold(const float *distances, int num_bins, float threshold) {
    for (int i = 0; i < num_bins; i++) {
        if (distances[i] <= threshold) return 1;
    }
    return 0;
}

static int log_intrusion(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", timestamp, distance);
    fclose(fp);
    return 0;
}

static void trigger_alert(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1);
    gpioDelay(duration_ms * 1000);
    gpioWrite(gpio_pin, 0);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    float distances[NUM_RANGE_BINS];

    while (running) {
        if (find_magic_word(uart_fd) != 0) {
            if (!running) break;
            fprintf(stderr, "Failed to find magic word\n");
            continue;
        }

        if (decode_range_profile(uart_fd, distances, NUM_RANGE_BINS) != 0) {
            if (!running) break;
            fprintf(stderr, "Failed to decode range profile\n");
            continue;
        }

        if (check_threshold(distances, NUM_RANGE_BINS, THRESHOLD_DISTANCE)) {
            float min_distance = distances[0];
            for (int i = 1; i < NUM_RANGE_BINS; i++) {
                if (distances[i] < min_distance) min_distance = distances[i];
            }

            if (log_intrusion(min_distance) == 0) {
                printf("Intrusion detected at %.2f meters\n", min_distance);
                trigger_alert(GPIO_LED, 2000);
            } else {
                fprintf(stderr, "Failed to log intrusion\n");
            }
        }
    }

    if (uart_fd >= 0) close(uart_fd);
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

