/*
 * Raspberry Pi 4 Model B – TDK Chirp ICU-20201 Ultrasonic ToF Sensor Logger
 *
 * Reads distance every 100 ms over I2C bus 1, logs to distance_log.txt, and
 * asserts GPIO 17 (BCM 17) when distance < 10 cm.
 *
 * Build:  gcc -O2 -Wall -Wextra -o chirp_logger chirp_logger.c -lpigpio -lrt
 * Run:    sudo ./chirp_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x30          /* ICU-20201 default I2C address  */
#define ALERT_GPIO           17            /* BCM 17 – physical pin 17        */
#define DISTANCE_THRESHOLD   10.0f         /* cm                              */
#define LOG_FILE             "distance_log.txt"
#define SAMPLE_PERIOD_US     100000        /* 100 ms                          */

/* Chirp ICU-20201 register addresses (16-bit, big-endian on the bus) */
#define REG_MODEL_ID         0x0000
#define REG_PART_ID          0x0001
#define REG_DISTANCE         0x0002
#define REG_STATUS           0x0003
#define REG_MEAS_CFG         0x0004
#define REG_INT_CFG          0x0005
#define REG_INT_STATUS       0x0006

#define EXPECTED_MODEL_ID    0x0001
#define EXPECTED_PART_ID     0x0001

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_fp    = NULL;

