static int chirp_init(int handle)
{
    uint16_t model_id = 0, part_id = 0;

    if (i2c_read_reg16(handle, REG_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "[ERROR] Failed to read MODEL_ID register.\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "[ERROR] Unexpected MODEL_ID: 0x%04X (expected 0x%04X).\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }

    if (i2c_read_reg16(handle, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "[ERROR] Failed to read PART_ID register.\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "[ERROR] Unexpected PART_ID: 0x%04X (expected 0x%04X).\n",
                part_id, EXPECTED_PART_ID);
        return -1;
    }

    /* Start continuous measurement mode */
    if (i2c_write_reg16(handle, REG_MEAS_CFG, 0x0001) < 0) {
        fprintf(stderr, "[ERROR] Failed to configure measurement mode.\n");
        return -1;
    }

    /* Clear any pending interrupt */
    if (i2c_write_reg16(handle, REG_INT_STATUS, 0x0001) < 0) {
        fprintf(stderr, "[ERROR] Failed to clear interrupt status.\n");
        return -1;
    }

    return 0;
}

/* --------------------------- Read Distance -------------------------------- */
static int chirp_read_distance(int handle, float *distance_cm)
{
    uint16_t raw = 0;

    if (i2c_read_reg16(handle, REG_DISTANCE, &raw) < 0) {
        fprintf(stderr, "[ERROR] Failed to read DISTANCE register.\n");
        return -1;
