    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed.\n");
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[ERROR] strftime failed.\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, distance_cm) < 0) {
        fprintf(stderr, "[ERROR] Failed to write to log file.\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] Failed to flush log file.\n");
        return -1;
    }
    return 0;
}

/* --------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_fp != NULL) {
