#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define LOG_FILE "distance_log.csv"
#define POLL_DELAY_US 100000
#define STOP_DISTANCE 300
#define APPROACH_DISTANCE 600
#define SLOW_DISTANCE 1200

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int vl53l1x_init(int handle) {
    if (i2cWriteByteData(handle, 0x00, 0x01) < 0) return -1;
    if (i2cWriteByteData(handle, 0x01, 0x02) < 0) return -1;
    if (i2cWriteByteData(handle, 0x02, 0x03) < 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(int handle, int *distance) {
    int hi = i2cReadByteData(handle, 0x14);
    if (hi < 0) return -1;
    int lo = i2cReadByteData(handle, 0x15);
    if (lo < 0) return -1;
    *distance = (hi << 8) | lo;
    return 0;
}

static void log_distance(FILE *fp, int distance) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%d\n", ts, distance);
    fflush(fp);
}

static void print_guidance(int distance) {
    if (distance < STOP_DISTANCE) printf("STOP\n");
    else if (distance < APPROACH_DISTANCE) printf("APPROACH\n");
    else if (distance < SLOW_DISTANCE) printf("SLOW\n");
    else printf("CLEAR\n");
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    int file_exists = (access(LOG_FILE, F_OK) == 0);
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }
    if (!file_exists) {
        fprintf(log_file, "timestamp,distance_mm\n");
        fflush(log_file);
    }

    printf("Parking assistance system started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance = 0;
        if (vl53l1x_read_distance(i2c_handle, &distance) != 0) {
            fprintf(stderr, "Error reading distance\n");
        } else {
            log_distance(log_file, distance);
            print_guidance(distance);
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

