/*
 * CH201 ultrasonic ToF sensor reader with LED feedback on Raspberry Pi 4.
 *
 * Wiring:
 *   CH201 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   CH201 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   CH201 VDD -> 3.3 V
 *   CH201 GND -> GND
 *   LED anode -> GPIO 18 (BCM) via 330 ohm resistor -> 3.3 V
 *   LED cathode -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o ch201_led ch201_led.c -lpigpio -lrt
 * Run:    sudo ./ch201_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define CH201_I2C_ADDR       0x50          /* CH201 default 7-bit I2C address */
#define LED_GPIO             18            /* BCM pin for LED anode */
#define SAMPLE_PERIOD_US     100000        /* 100 ms between samples */
#define BLINK_HALF_PERIOD_US 5000          /* 5 ms half-cycle -> 100 Hz max */
#define MAX_RETRIES          3
#define RETRY_DELAY_US       10000         /* 10 ms between retries */

/* CH201 register addresses (16-bit, big-endian on the bus) */
#define CH201_REG_DISTANCE   0x0000
#define CH201_REG_STATUS     0x0001
#define CH201_REG_CONFIG     0x0002

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers --------------------------------- */

/* Write a 16-bit register address followed by a 16-bit value (big-endian). */
static int ch201_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cWriteDevice(handle, buf, 4);
        if (rc == 4)
            return 0;
        fprintf(stderr, "[WARN] i2cWriteDevice(reg=0x%04X) failed (rc=%d), attempt %d/%d\n",
                reg, rc, attempt + 1, MAX_RETRIES);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* Write a 16-bit register address, then read `len` bytes. */
static int ch201_read_reg16(int handle, uint16_t reg, uint8_t *data, uint8_t len)
{
    char addr_buf[2];
    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cWriteDevice(handle, addr_buf, 2);
        if (rc != 2) {
            fprintf(stderr, "[WARN] i2cWriteDevice(addr=0x%04X) failed (rc=%d), attempt %d/%d\n",
                    reg, rc, attempt + 1, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        rc = i2cReadDevice(handle, (char *)data, len);
        if (rc == len)
            return 0;

        fprintf(stderr, "[WARN] i2cReadDevice(reg=0x%04X) failed (rc=%d), attempt %d/%d\n",
                reg, rc, attempt + 1, MAX_RETRIES);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* --------------------------- Sensor logic -------------------------------- */
static int ch201_init(int handle)
{
    /* Probe: try a status-register read to confirm the sensor is present. */
    uint8_t status = 0;
    if (ch201_read_reg16(handle, CH201_REG_STATUS, &status, 1) != 0) {
        fprintf(stderr, "[ERROR] CH201 not responding at 0x%02X on bus %d\n",
                CH201_I2C_ADDR, I2C_BUS);
        return -1;
    }
    printf("[INFO] CH201 detected (status=0x%02X). Initializing...\n", status);

    /* Example configuration: set measurement mode to continuous. */
    if (ch201_write_reg16(handle, CH201_REG_CONFIG, 0x0001) != 0) {
        fprintf(stderr, "[ERROR] Failed to write CH201 config register\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */
    return 0;
}

static int ch201_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t data[2] = {0};
    if (ch201_read_reg16(handle, CH201_REG_DISTANCE, data, 2) != 0)
        return -1;

    *distance_mm = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* --------------------------- LED control --------------------------------- */
static void set_led_state(int gpio, bool on)
{
    if (gpioWrite(gpio, on ? 1 : 0) != 0)
        fprintf(stderr, "[WARN] gpioWrite(%d, %d) failed\n", gpio, on);
}

/* --------------------------- Logging ------------------------------------- */
static void log_data(uint16_t distance_mm, float freq_hz)
{
    time_t rawtime;
    struct tm timeinfo;
    char ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("%s  Distance: %5u mm  LED Freq: %.2f Hz\n", ts, distance_mm, freq_hz);
    fflush(stdout);
}

/* --------------------------- Main loop ----------------------------------- */
