{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, CH201_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, CH201_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialize sensor --- */
    if (ch201_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] CH201 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure LED GPIO --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", LED_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    set_led_state(LED_GPIO, false);

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] CH201 reader started. Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    bool led_on = false;
    uint32_t next_sample_tick = gpioTick();

    while (g_running) {
        uint32_t now = gpioTick();

        /* --- Sample every 100 ms --- */
        if ((int32_t)(now - next_sample_tick) >= 0) {
            uint16_t distance_mm = 0;
            if (ch201_read_distance(g_i2c_handle, &distance_mm) == 0) {
                /* Map distance to LED frequency: 0 mm -> 100 Hz, 200 mm -> 1 Hz */
                float freq = 100.0f - (float)distance_mm / 2.0f;
                if (freq < 1.0f) freq = 1.0f;
                if (freq > 100.0f) freq = 100.0f;

                /* Toggle LED for this sample */
                led_on = !led_on;
                set_led_state(LED_GPIO, led_on);

                log_data(distance_mm, freq);
            } else {
                fprintf(stderr, "[ERROR] Failed to read distance after %d retries\n", MAX_RETRIES);
                /* On read failure, turn LED off for safety */
                set_led_state(LED_GPIO, false);
            }
            next_sample_tick += SAMPLE_PERIOD_US;
        }

        /* --- Sleep until next half-cycle (5 ms) --- */
        gpioDelay(BLINK_HALF_PERIOD_US);
    }

    /* --- Cleanup --- */
    printf("\n[INFO] Shutting down...\n");
    set_led_state(LED_GPIO, false);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("[INFO] Done.\n");
    return EXIT_SUCCESS;
}

