#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x5B
#define TRIGGER_CMD 0x00
#define READ_CMD 0x01
#define MEASUREMENT_DELAY_US 10000
#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES 3
#define LOG_FILE "distance_log.csv"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int trigger_measurement(int handle) {
    char cmd = TRIGGER_CMD;
    int rc = i2cWriteDevice(handle, &cmd, 1);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteDevice (trigger) failed: %d\n", rc);
        return -1;
    }
    return 0;
}

static int read_distance(int handle, uint16_t *distance) {
    char cmd = READ_CMD;
    char buf[2];
    int rc;

    rc = i2cWriteDevice(handle, &cmd, 1);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteDevice (read cmd) failed: %d\n", rc);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    rc = i2cReadDevice(handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadDevice failed: %d\n", rc);
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "Error: Short read: got %d bytes, expected 2\n", rc);
        return -1;
    }

    *distance = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int log_data(const char *filename, uint16_t distance) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance);

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error registering SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error registering SIGTERM handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("MLX75030 distance logger started. Press Ctrl+C to stop.\n");

    while (running) {
        uint16_t distance = 0;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (trigger_measurement(i2c_handle) == 0 &&
                read_distance(i2c_handle, &distance) == 0) {
                success = 1;
                break;
            }
            gpioDelay(10000);
        }

        if (success) {
            if (log_data(LOG_FILE, distance) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: failed to read distance after %d attempts\n", MAX_RETRIES);
        }

        for (int i = 0; i < 10 && running; i++) {
            gpioDelay(SAMPLE_INTERVAL_US / 10);
        }
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

