#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_DELAY_US 50000
#define POLL_DELAY_US 10000
#define LOG_FILE "proximity_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "gmtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s Sensor %d: %s\n", timestamp, sensor_id, event_type) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

static int read_sensor(int gpio_pin) {
    int reading = gpioRead(gpio_pin);
    if (reading < 0) {
        fprintf(stderr, "gpioRead failed on GPIO %d\n", gpio_pin);
        return -1;
    }
    return reading;
}

static int debounce_sensor(int gpio_pin, int *last_state) {
    int current_state = read_sensor(gpio_pin);
    if (current_state < 0) {
        return -1;
    }

    if (current_state != *last_state) {
        gpioDelay(DEBOUNCE_DELAY_US);
        int debounced_state = read_sensor(gpio_pin);
        if (debounced_state < 0) {
            return -1;
        }
        if (debounced_state == current_state) {
            *last_state = current_state;
            return current_state;
        }
    }
    return -1;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int sensor1_last_state = 0;
    int sensor2_last_state = 0;
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor1_state = debounce_sensor(SENSOR_1_GPIO, &sensor1_last_state);
        if (sensor1_state == 0) {
            ret = log_event(1, "DETECTED");
            if (ret != 0) {
                fprintf(stderr, "Error logging event for sensor 1 (DETECTED)\n");
            }
        } else if (sensor1_state == 1) {
            ret = log_event(1, "CLEARED");
            if (ret != 0) {
                fprintf(stderr, "Error logging event for sensor 1 (CLEARED)\n");
            }
        }

        int sensor2_state = debounce_sensor(SENSOR_2_GPIO, &sensor2_last_state);
        if (sensor2_state == 0) {
            ret = log_event(2, "DETECTED");
            if (ret != 0) {
                fprintf(stderr, "Error logging event for sensor 2 (DETECTED)\n");
            }
        } else if (sensor2_state == 1) {
            ret = log_event(2, "CLEARED");
            if (ret != 0) {
                fprintf(stderr, "Error logging event for sensor 2 (CLEARED)\n");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

