/*
 * CH-101 Time-of-Flight distance logger for Raspberry Pi 5.
 *
 * Wiring:
 *   CH-101 SDA  -> GPIO2  (I2C bus 1 SDA, pin 3)
 *   CH-101 SCL  -> GPIO3  (I2C bus 1 SCL, pin 5)
 *   CH-101 VDD  -> 3.3 V
 *   CH-101 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o ch101_log ch101_log.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_ADDR     0x50          /* CH-101 default 7-bit I2C address */

#define REG_MEAS_STATUS 0x00         /* bit 0 = data ready */
#define REG_DISTANCE    0x02         /* 16-bit distance in mm */
#define REG_MODEL_ID    0x00         /* also used to detect sensor presence */

#define SAMPLE_PERIOD_MS 500
#define MEAS_TIMEOUT_MS  50

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write pointer 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read one byte back */
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read from 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: write pointer 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read two bytes (big-endian per TDK convention) */
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16: read from 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Combined write-then-read transaction using a single I2C_RDWR ioctl.
 * This avoids a separate write() and read() which may split across
 * the kernel/user boundary on some systems.
 */
static int i2c_rdwr_reg8(int fd, uint8_t reg, uint8_t *out)
{
    uint8_t tx = reg;
    struct i2c_msg msgs[2] = {
        { .addr = CH101_ADDR, .flags = 0,            .len = 1, .buf = &tx },
        { .addr = CH101_ADDR, .flags = I2C_M_RD,     .len = 1, .buf = out }
    };
    struct i2c_rdwr_ioctl_data data = { .msgs = msgs, .nmsgs = 2 };

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "i2c_rdwr_reg8(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor presence check                                               */
/* ------------------------------------------------------------------ */
static int sensor_present(int fd)
{
    uint8_t id = 0;
    if (i2c_read_reg8(fd, REG_MODEL_ID, &id) != 0)
        return 0;
    /* CH-101 returns 0x01 in the MODEL_ID register */
    if (id != 0x01) {
        fprintf(stderr, "Unexpected MODEL_ID 0x%02X (expected 0x01) — "
                        "wrong sensor or not ready\n", id);
        return 0;
    }
    return 1;
}

/* ------------------------------------------------------------------ */
/* Distance measurement                                                */
/* ------------------------------------------------------------------ */
static int read_distance_mm(int fd, uint16_t *distance_mm)
{
    uint8_t status = 0;
    int waited = 0;

    /* Poll MEAS_STATUS until bit 0 is set (data ready) */
    while (waited < MEAS_TIMEOUT_MS) {
        if (i2c_read_reg8(fd, REG_MEAS_STATUS, &status) != 0)
            return -1;
        if (status & 0x01)
            break;
        usleep(1000);                 /* 1 ms */
        waited++;
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "Timeout waiting for measurement data ready\n");
        return -1;
    }

    /* Read 16-bit distance (big-endian) */
    if (i2c_read_reg16(fd, REG_DISTANCE, distance_mm) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return -1;
    }

    struct tm tm_local;
    if (localtime_r(&now, &tm_local) == NULL) {
        perror("localtime_r");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_local) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u\n", ts, distance_mm) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Set slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                CH101_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Verify sensor is present */
    if (!sensor_present(g_i2c_fd)) {
        fprintf(stderr, "CH-101 sensor not detected at 0x%02X\n", CH101_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV log file */
    g_log_fp = fopen("distance_log.csv", "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(distance_log.csv) failed: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,distance_mm\n");
        fflush(g_log_fp);
    }

    printf("CH-101 distance logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t distance = 0;

        if (read_distance_mm(g_i2c_fd, &distance) == 0) {
            if (log_distance(g_log_fp, distance) != 0)
                fprintf(stderr, "Logging failed for this sample\n");
            else
                printf("Distance: %u mm\n", distance);
        } else {
            fprintf(stderr, "Read failed — skipping sample\n");
        }

        /* Sleep SAMPLE_PERIOD_MS, but wake early on signal */
        for (int ms = 0; ms < SAMPLE_PERIOD_MS && g_running; ms += 10)
            usleep(10000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

