#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L5CX_ADDR 0x52

#define VL53L5CX_REG_SOFT_RESET 0x0003
#define VL53L5CX_REG_SYSTEM_START 0x0000
#define VL53L5CX_REG_RANGE_START 0x0001
#define VL53L5CX_REG_RANGE_STATUS 0x0002
#define VL53L5CX_REG_RANGE_CONFIG 0x0004
#define VL53L5CX_REG_RANGE_DATA 0x001E
#define VL53L5CX_REG_ZONE_CONFIG 0x0005

#define VL53L5CX_RANGE_START 0x01
#define VL53L5CX_RANGE_STOP 0x00
#define VL53L5CX_RANGE_STATUS_READY 0x01

#define NUM_ZONES 64

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint8_t *buf, size_t len) {
    uint8_t reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (write(fd, reg_buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg addr) to 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l5cx_init(int fd) {
    if (i2c_write_reg16(fd, VL53L5CX_REG_SOFT_RESET, 0x00) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg16(fd, VL53L5CX_REG_SOFT_RESET, 0x01) < 0) return -1;
    usleep(10000);

    if (i2c_write_reg16(fd, VL53L5CX_REG_SYSTEM_START, 0x01) < 0) return -1;
    usleep(10000);

    if (i2c_write_reg16(fd, VL53L5CX_REG_ZONE_CONFIG, 0x01) < 0) return -1;
    if (i2c_write_reg16(fd, VL53L5CX_REG_RANGE_CONFIG, 0x01) < 0) return -1;

    return 0;
}

static int vl53l5cx_start_ranging(int fd) {
    return i2c_write_reg16(fd, VL53L5CX_REG_RANGE_START, VL53L5CX_RANGE_START);
}

static int vl53l5cx_stop_ranging(int fd) {
    return i2c_write_reg16(fd, VL53L5CX_REG_RANGE_START, VL53L5CX_RANGE_STOP);
}

static int vl53l5cx_read_data(int fd, uint16_t *distances) {
    uint8_t status;
    int timeout = 100;

    do {
        if (i2c_read_reg16(fd, VL53L5CX_REG_RANGE_STATUS, &status, 1) < 0) return -1;
        if (status & VL53L5CX_RANGE_STATUS_READY) break;
        usleep(1000);
    } while (--timeout > 0);

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for range data ready\n");
        return -1;
    }

    uint8_t buf[NUM_ZONES * 2];
    if (i2c_read_reg16(fd, VL53L5CX_REG_RANGE_DATA, buf, sizeof(buf)) < 0) return -1;

    for (int i = 0; i < NUM_ZONES; i++) {
        distances[i] = (buf[i * 2] << 8) | buf[i * 2 + 1];
    }

    return 0;
}

int main(void) {
    int fd = -1;
    uint16_t distances[NUM_ZONES];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VL53L5CX_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (vl53l5cx_init(fd) < 0) {
        fprintf(stderr, "VL53L5CX initialization failed\n");
        close(fd);
        return 1;
    }

    if (vl53l5cx_start_ranging(fd) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        close(fd);
        return 1;
    }

    printf("VL53L5CX ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        if (vl53l5cx_read_data(fd, distances) == 0) {
            for (int i = 0; i < NUM_ZONES; i++) {
                printf("Zone %2d: %4u mm\n", i, distances[i]);
            }
            printf("\n");
        } else {
            fprintf(stderr, "Failed to read distance data\n");
        }
        usleep(500000);
    }

    vl53l5cx_stop_ranging(fd);
    close(fd);

    printf("\nExiting gracefully.\n");
    return 0;
}

