#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x58
#define REG_DISTANCE 0x00
#define REG_STATUS 0x01
#define REG_CONFIG 0x02
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0;
        }
        fprintf(stderr, "Warning: I2C read failed (reg 0x%02X, attempt %d/%d): %d\n",
                reg, attempt + 1, MAX_RETRIES, result);
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    return -1;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0;
        }
        fprintf(stderr, "Warning: I2C write failed (reg 0x%02X, attempt %d/%d): %d\n",
                reg, attempt + 1, MAX_RETRIES, result);
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    return -1;
}

static int read_distance(int handle, uint16_t *distance) {
    uint8_t high_byte, low_byte;
    if (read_register(handle, REG_DISTANCE, &high_byte) != 0) {
        return -1;
    }
    if (read_register(handle, REG_DISTANCE + 1, &low_byte) != 0) {
        return -1;
    }
    *distance = ((uint16_t)high_byte << 8) | low_byte;
    return 0;
}

static void log_data(uint16_t distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = ts.tv_nsec / 1000000;
    printf("%ld.%03ld, Distance: %u mm\n", (long)ts.tv_sec, milliseconds, distance);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, MLX75030_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (write_register(i2c_handle, REG_CONFIG, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to configure sensor (sensor may be absent or bus error).\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("MLX75030 distance sensor initialized on I2C bus %d, address 0x%02X.\n",
           I2C_BUS, MLX75030_ADDR);
    printf("Sampling every 100 ms. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t distance;
        if (read_distance(i2c_handle, &distance) == 0) {
            log_data(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance after %d retries.\n", MAX_RETRIES);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

