        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, MLX75030_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (write_register(i2c_handle, REG_CONFIG, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to configure sensor (sensor may be absent or bus error).\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("MLX75030 distance sensor initialized on I2C bus %d, address 0x%02X.\n",
           I2C_BUS, MLX75030_ADDR);
    printf("Sampling every 100 ms. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t distance;
        if (read_distance(i2c_handle, &distance) == 0) {
            log_data(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance after %d retries.\n", MAX_RETRIES);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

