#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100
#define POLL_DELAY_US 500000

#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_SYSTEM_MODE 0x0001
#define VL53L1X_REG_RANGE_START 0x0002
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x001E

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg16(uint8_t reg, uint16_t value) {
    char buf[3] = { (char)(reg >> 8), (char)(reg & 0xFF), (char)(value & 0xFF) };
    return i2cWriteDevice(i2c_handle, buf, 3);
}

static int read_reg16(uint8_t reg, uint16_t *value) {
    char buf[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) return -1;
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) return -1;
    *value = (uint16_t)((uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int init_vl53l1x(void) {
    if (write_reg16(VL53L1X_REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write soft reset register.\n");
        return -1;
    }
    gpioDelay(10000);
    if (write_reg16(VL53L1X_REG_SYSTEM_MODE, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write system mode register.\n");
        return -1;
    }
    if (write_reg16(VL53L1X_REG_RANGE_START, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }
    return 0;
}

static int read_distance(uint16_t *distance) {
    uint16_t status;
    if (read_reg16(VL53L1X_REG_RESULT_RANGE_STATUS, &status) != 0) {
        fprintf(stderr, "Error: Failed to read range status.\n");
        return -1;
    }
    if (status & 0x01) {
        if (read_reg16(VL53L1X_REG_RESULT_DISTANCE, distance) != 0) {
            fprintf(stderr, "Error: Failed to read distance.\n");
            return -1;
        }
        return 0;
    }
    return 1;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_vl53l1x() != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    while (running) {
        uint16_t distance;
        int ret = read_distance(&distance);
        if (ret == 0) {
            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(BUZZER_GPIO, 1);
                gpioDelay(100000);
                gpioWrite(BUZZER_GPIO, 0);
            }
        } else if (ret < 0) {
            fprintf(stderr, "Error: I2C read failed, skipping iteration.\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(BUZZER_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

