#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define SERVO_PIN        17

#define SPEED_OF_SOUND   34300.0
#define MIN_DISTANCE_CM  2.0
#define MAX_DISTANCE_CM  400.0
#define MIN_ANGLE        -90
#define MAX_ANGLE        90
#define TIMEOUT_US       50000
#define LOOP_DELAY_US    200000
#define TRIGGER_PULSE_US 10

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static double measure_distance(void) {
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0;
    }
    gpioDelay(2);

    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 1) failed\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0;
    }

    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_start) > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo start timeout\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - timeout_start) > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo end timeout\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    double distance = (double)diff * SPEED_OF_SOUND / 2000000.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: Distance out of range (%.2f cm)\n", distance);
        return -1.0;
    }
    return distance;
}

static int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;

    int pulse_width = 1000 + (angle + 90) * 1000 / 180;
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed\n");
        return -1;
    }
    return 0;
}

static void log_data(double distance) {
    FILE *fp = fopen("sensor_data.log", "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open sensor_data.log\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Distance: %.2f cm\n", timestamp, distance);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(servo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) init failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (g_running) {
        double distance = measure_distance();
        if (distance > 0) {
            int angle = (int)((distance - MIN_DISTANCE_CM) /
                              (MAX_DISTANCE_CM - MIN_DISTANCE_CM) *
                              (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE);
            if (set_servo_angle(angle) != 0) {
                fprintf(stderr, "Error: Failed to set servo angle\n");
            }
            log_data(distance);
        }
        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

