#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define VL53L1X_ADDR   0x29
#define SERVO_PIN      18
#define DISTANCE_THRESHOLD 20
#define SERVO_OPEN_US  1000
#define SERVO_CLOSE_US 1500
#define LOG_FILE       "gate_log.txt"
#define POLL_DELAY_US  100000

#define VL53L1X_REG_SOFT_RESET       0x0003
#define VL53L1X_REG_SYSTEM_MODE      0x0001
#define VL53L1X_REG_RESULT_RANGE     0x0096
#define VL53L1X_REG_RESULT_INT       0x0046
#define VL53L1X_REG_RESULT_STATUS    0x0089
#define VL53L1X_REG_SYSTEM_RANGE     0x0080

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int gate_open = 0;

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fclose(fp);
}

static int i2c_write_reg8(int fd, uint16_t reg, uint8_t val) {
    uint8_t buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, val };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *val) {
    uint8_t wbuf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (write(fd, wbuf, 2) != 2) return -1;
    uint8_t rbuf[2];
    if (read(fd, rbuf, 2) != 2) return -1;
    *val = ((uint16_t)rbuf[0] << 8) | rbuf[1];
    return 0;
}

static int vl53l1x_init(int fd) {
    if (i2c_write_reg8(fd, VL53L1X_REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg8(fd, VL53L1X_REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(10000);
    uint16_t model_id;
    if (i2c_read_reg16(fd, 0x010F, &model_id) < 0) return -1;
    if (model_id != 0xEACC) {
        fprintf(stderr, "VL53L1X not detected (model_id=0x%04X)\n", model_id);
        return -1;
    }
    if (i2c_write_reg8(fd, VL53L1X_REG_SYSTEM_MODE, 0x40) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int vl53l1x_read_distance(int fd, uint16_t *distance) {
    uint16_t status;
    if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_STATUS, &status) < 0) return -1;
    if (status & 0x01) {
        if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_RANGE, distance) < 0) return -1;
        if (i2c_write_reg8(fd, VL53L1X_REG_RESULT_INT, 0x01) < 0) return -1;
        return 0;
    }
    return 1;
}

static void control_servo(int angle) {
    int pulse = SERVO_CLOSE_US + (angle * (SERVO_OPEN_US - SERVO_CLOSE_US) / 180);
    if (gpioServo(SERVO_PIN, pulse) < 0) {
        log_event("ERROR: gpioServo failed");
    }
}

static void open_gate(void) {
    if (!gate_open) {
        control_servo(0);
        gate_open = 1;
        log_event("Gate opened");
    }
}

static void close_gate(void) {
    if (gate_open) {
        control_servo(180);
        gate_open = 0;
        log_event("Gate closed");
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open i2c");
        gpioTerminate();
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_fd) < 0) {
        fprintf(stderr, "VL53L1X init failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    close_gate();

    struct sigaction sa = { .sa_handler = signal_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("System started");

    while (running) {
        uint16_t dist;
        int rc = vl53l1x_read_distance(i2c_fd, &dist);
        if (rc == 0) {
            if (dist < DISTANCE_THRESHOLD) {
                open_gate();
            } else {
                close_gate();
            }
        } else if (rc < 0) {
            log_event("ERROR: I2C read failed");
            gpioDelay(500000);
        }
        gpioDelay(POLL_DELAY_US);
    }

    log_event("System shutting down");
    cleanup();
    return 0;
}

