/*
 * HC-SR04 Ultrasonic Distance Measurement on Raspberry Pi 4 Model B
 *
 * Wiring:
 *   TRIG -> GPIO 23 (physical pin 16, BCM)
 *   ECHO -> GPIO 24 (physical pin 18, BCM)  [5 V -> 3.3 V level shift required]
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:
 *   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24

#define TRIGGER_PULSE_US 10
#define SAMPLE_PERIOD_US 200000   /* 200 ms -> 5 Hz */
#define ECHO_TIMEOUT_US  60000    /* 60 ms max echo wait */
#define MIN_PULSE_US     100      /* reject noise below 100 us */
#define MAX_PULSE_US     30000    /* reject timeout above 30 ms */
#define SOUND_SPEED_CM_S 34300.0  /* cm/s at ~20 C */

static volatile uint32_t g_rising_tick = 0;
static volatile uint32_t g_falling_tick = 0;
static volatile bool     g_echo_seen    = false;
static volatile bool     g_falling_latched = false;

static FILE *g_log_file = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback (rising + falling edge on ECHO)               */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_rising_tick   = tick;
        g_echo_seen     = false;
        g_falling_latched = false;
    } else if (level == 0) {
        g_falling_tick  = tick;
        g_falling_latched = true;
        g_echo_seen     = true;
    }
}

/* ------------------------------------------------------------------ */
/* Trigger a 10 us pulse on TRIG                                       */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 1) failed\n");
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 0) failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* Compute (b - a) with 32-bit tick wraparound                          */
/* ------------------------------------------------------------------ */
static uint32_t tick_diff(uint32_t a, uint32_t b)
{
    return b - a;  /* unsigned subtraction wraps correctly */
}

/* ------------------------------------------------------------------ */
/* Compute distance in cm from pulse width in microseconds             */
/* ------------------------------------------------------------------ */
static float calculate_distance_cm(uint32_t pulse_us)
{
    return (float)pulse_us * SOUND_SPEED_CM_S / 2000000.0f;
}

/* ------------------------------------------------------------------ */
/* Log a reading with an ISO-8601 timestamp                             */
/* ------------------------------------------------------------------ */
static void log_distance(float distance_cm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("%s  Distance: %.2f cm\n", timestamp, distance_cm);
    if (g_log_file) {
        fprintf(g_log_file, "%s,%.2f\n", timestamp, distance_cm);
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure TRIG as output, initially LOW ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIG) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 0) initial failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure ECHO as input with pull-down ---- */
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register alert callback for both edges ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file (append mode) ---- */
    g_log_file = fopen("distance_log.txt", "a");
    if (!g_log_file) {
        perror("Error opening distance_log.txt");
        gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d  ECHO=GPIO%d  (5 V -> 3.3 V level shift required)\n",
           TRIGGER_PIN, ECHO_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        /* Reset state before triggering */
        g_rising_tick   = 0;
        g_falling_tick  = 0;
        g_echo_seen     = false;
        g_falling_latched = false;

        trigger_sensor();

        /* Wait for echo or timeout */
        uint32_t start_tick = gpioTick();
        uint32_t elapsed = 0;
        while (!g_falling_latched && elapsed < ECHO_TIMEOUT_US && g_running) {
            gpioDelay(100);  /* poll every 100 us */
            elapsed = tick_diff(start_tick, gpioTick());
        }

        if (!g_running) {
            break;
        }

        if (!g_echo_seen) {
            fprintf(stderr, "Warning: Echo timeout (no valid pulse within %u us)\n",
                    ECHO_TIMEOUT_US);
        } else {
            uint32_t pulse_us = tick_diff(g_rising_tick, g_falling_tick);
            if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
                fprintf(stderr,
                        "Warning: Pulse out of range (%u us) - noise or no object\n",
                        pulse_us);
            } else {
                float distance = calculate_distance_cm(pulse_us);
                log_distance(distance);
            }
        }

        /* Sleep remainder of the 200 ms sampling period */
        uint32_t sample_elapsed = tick_diff(start_tick, gpioTick());
        if (sample_elapsed < SAMPLE_PERIOD_US) {
            gpioDelay(SAMPLE_PERIOD_US - sample_elapsed);
        }
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioWrite(TRIGGER_PIN, 0);
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

