#define MAX_PULSE_US     30000    /* reject timeout above 30 ms */
#define SOUND_SPEED_CM_S 34300.0  /* cm/s at ~20 C */

static volatile uint32_t g_rising_tick = 0;
static volatile uint32_t g_falling_tick = 0;
static volatile bool     g_echo_seen    = false;
static volatile bool     g_falling_latched = false;

static FILE *g_log_file = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback (rising + falling edge on ECHO)               */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_rising_tick   = tick;
        g_echo_seen     = false;
        g_falling_latched = false;
    } else if (level == 0) {
        g_falling_tick  = tick;
        g_falling_latched = true;
        g_echo_seen     = true;
    }
}

/* ------------------------------------------------------------------ */
/* Trigger a 10 us pulse on TRIG                                       */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 1) failed\n");
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 0) failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* Compute (b - a) with 32-bit tick wraparound                          */
/* ------------------------------------------------------------------ */
static uint32_t tick_diff(uint32_t a, uint32_t b)
{
    return b - a;  /* unsigned subtraction wraps correctly */
}

/* ------------------------------------------------------------------ */
/* Compute distance in cm from pulse width in microseconds             */
/* ------------------------------------------------------------------ */
static float calculate_distance_cm(uint32_t pulse_us)
{
    return (float)pulse_us * SOUND_SPEED_CM_S / 2000000.0f;
}

/* ------------------------------------------------------------------ */
/* Log a reading with an ISO-8601 timestamp                             */
/* ------------------------------------------------------------------ */
static void log_distance(float distance_cm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("%s  Distance: %.2f cm\n", timestamp, distance_cm);
    if (g_log_file) {
        fprintf(g_log_file, "%s,%.2f\n", timestamp, distance_cm);
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure TRIG as output, initially LOW ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIG) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 0) initial failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure ECHO as input with pull-down ---- */
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register alert callback for both edges ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file (append mode) ---- */
    g_log_file = fopen("distance_log.txt", "a");
    if (!g_log_file) {
        perror("Error opening distance_log.txt");
        gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d  ECHO=GPIO%d  (5 V -> 3.3 V level shift required)\n",
           TRIGGER_PIN, ECHO_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        /* Reset state before triggering */
        g_rising_tick   = 0;
        g_falling_tick  = 0;
        g_echo_seen     = false;
        g_falling_latched = false;

        trigger_sensor();

        /* Wait for echo or timeout */
        uint32_t start_tick = gpioTick();
        uint32_t elapsed = 0;
        while (!g_falling_latched && elapsed < ECHO_TIMEOUT_US && g_running) {
            gpioDelay(100);  /* poll every 100 us */
            elapsed = tick_diff(start_tick, gpioTick());
        }

        if (!g_running) {
            break;
        }

        if (!g_echo_seen) {
            fprintf(stderr, "Warning: Echo timeout (no valid pulse within %u us)\n",
                    ECHO_TIMEOUT_US);
        } else {
            uint32_t pulse_us = tick_diff(g_rising_tick, g_falling_tick);
            if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
                fprintf(stderr,
                        "Warning: Pulse out of range (%u us) - noise or no object\n",
                        pulse_us);
            } else {
                float distance = calculate_distance_cm(pulse_us);
                log_distance(distance);
            }
        }

        /* Sleep remainder of the 200 ms sampling period */
        uint32_t sample_elapsed = tick_diff(start_tick, gpioTick());
        if (sample_elapsed < SAMPLE_PERIOD_US) {
            gpioDelay(SAMPLE_PERIOD_US - sample_elapsed);
        }
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioWrite(TRIGGER_PIN, 0);
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

code:
/*
 * Smart Parking Gate — Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - VL53L1X time-of-flight sensor on I2C bus 1 (GPIO2/SDA, GPIO3/SCL)
 *   - VL53L1X shutdown line on GPIO23 (BCM)
 *   - VL53L1X interrupt line on GPIO24 (BCM)
 *   - Servo motor on GPIO18 (BCM) via hardware PWM
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o parking_gate parking_gate.c \
 *       -lpigpio -lrt -lpthread
 * Run:
 *   sudo ./parking_gate
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define SHUTDOWN_PIN         23
#define INTERRUPT_PIN        24
#define SERVO_PIN            18

#define DISTANCE_THRESHOLD_OPEN_CM  50
#define DISTANCE_THRESHOLD_CLOSE_CM 60
#define SERVO_OPEN_US               1000   /* 0 deg   */
#define SERVO_CLOSE_US              2000   /* 180 deg */
#define POLL_DELAY_US               100000 /* 100 ms  */
#define LOG_FILE                    "parking_log.txt"

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_SOFT_RESET      0x000B
#define VL53L1X_REG_MODEL_ID        0x010F
#define VL53L1X_REG_RANGE_CONFIG    0x005E
#define VL53L1X_REG_INTERMEAS_MS    0x006B
#define VL53L1X_REG_SYSTEM_CTRL     0x0080
#define VL53L1X_REG_GPIO_HV_MUX     0x0084
#define VL53L1X_REG_GPIO_TIO_HV     0x0086
#define VL53L1X_REG_SYSTEM_INT_CLR  0x0086
#define VL53L1X_REG_RESULT_INT_STAT 0x0089
#define VL53L1X_REG_RESULT_RANGE    0x0096

#define VL53L1X_MODEL_ID            0xEA
#define VL53L1X_SOFT_RESET_VAL      0x00
#define VL53L1X_SOFT_RESET_RELEASE  0x01

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* --------------------------- Forward declarations ------------------------ */
static int  vl53l1x_write16(int handle, uint16_t reg, uint16_t val);
static int  vl53l1x_read16(int handle, uint16_t reg, uint16_t *val);
static int  vl53l1x_init(int handle);
static int  vl53l1x_read_distance_mm(int handle, uint16_t *distance_mm);
static void set_servo_angle(int angle);
static void log_event(const char *event, int distance_mm);
static void signal_handler(int sig);

/* --------------------------- VL53L1X helpers ----------------------------- */

/* VL53L1X uses 16-bit register addresses.  pigpio's i2cWriteWordData / i2cReadWordData
 * send the 16-bit register address in little-endian order (low byte first),
 * which the VL53L1X expects, so we use i2cWriteWordData for writes and
 * i2cReadWordData for reads. */
static int vl53l1x_write16(int handle, uint16_t reg, uint16_t val)
{
    int rc = i2cWriteWordData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "[VL53L1X] write16 reg=0x%04X val=0x%04X failed: %d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

static int vl53l1x_read16(int handle, uint16_t reg, uint16_t *val)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[VL53L1X] read16 reg=0x%04X failed: %d\n", reg, rc);
        return -1;
    }
    *val = (uint16_t)rc;
    return 0;
}

static int vl53l1x_init(int handle)
{
    uint16_t model_id = 0;

    /* Read and verify model ID */
    if (vl53l1x_read16(handle, VL53L1X_REG_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "[VL53L1X] Cannot read model ID — sensor absent or bus error.\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "[VL53L1X] Unexpected model ID: 0x%04X (expected 0x%04X).\n",
                model_id, VL53L1X_MODEL_ID);
        return -1;
    }
    printf("[VL53L1X] Model ID verified: 0x%04X\n", model_id);

    /* Soft reset */
    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET, VL53L1X_SOFT_RESET_VAL) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */
    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET, VL53L1X_SOFT_RESET_RELEASE) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    /* Configure GPIO 1 as interrupt output (active high) */
    if (vl53l1x_write16(handle, VL53L1X_REG_GPIO_HV_MUX, 0x0010) != 0) /* GPIO1 = INT */
        return -1;
    if (vl53l1x_write16(handle, VL53L1X_REG_GPIO_TIO_HV, 0x0001) != 0)  /* HV = active */
        return -1;

    /* Clear any pending interrupt */
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_INT_CLR, 0x0001) != 0)
        return -1;

    /* Set inter-measurement period to 100 ms (100 * 1 ms) */
    if (vl53l1x_write16(handle, VL53L1X_REG_INTERMEAS_MS, 0x0064) != 0)
        return -1;

    /* Start ranging: bit 0 of SYSTEM_CTRL = 0x01 */
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_CTRL, 0x0001) != 0)
        return -1;

    return 0;
}

static int vl53l1x_read_distance_mm(int handle, uint16_t *distance_mm)
{
    uint16_t status = 0;

    /* Poll the interrupt status register for a new data-ready flag */
    for (int i = 0; i < 50; i++) {
        if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_INT_STAT, &status) != 0)
            return -1;
        if ((status & 0x01) != 0)
            break;
        gpioDelay(2000); /* 2 ms */
    }
    if ((status & 0x01) == 0) {
        fprintf(stderr, "[VL53L1X] Timeout waiting for data-ready.\n");
        return -1;
    }

    /* Read 16-bit range result (mm) */
    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_RANGE, distance_mm) != 0)
        return -1;

    /* Clear the interrupt so the next measurement can signal */
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_INT_CLR, 0x0001) != 0)
        return -1;

    return 0;
}

/* ------------------------------- Servo ----------------------------------- */
static void set_servo_angle(int angle)
{
    if (angle < 0)   angle = 0;
    if (angle > 180) angle = 180;

    int pulse_us = SERVO_OPEN_US +
                   (int)((long)angle * (SERVO_CLOSE_US - SERVO_OPEN_US) / 180);
    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "[Servo] gpioServo failed for angle %d.\n", angle);
    }
}

/* ------------------------------- Logging --------------------------------- */
static void log_event(const char *event, int distance_mm)
{
    if (!g_log_file)
        return;

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[Log] localtime_r failed.\n");
        return;
    }

    fprintf(g_log_file, "%04d-%02d-%02d %02d:%02d:%02d, %s, Distance: %d mm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event, distance_mm);
    fflush(g_log_file);
}

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure shutdown pin as output, keep sensor in shutdown */
    if (gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set shutdown pin mode.\n");
        goto cleanup;
    }
    gpioWrite(SHUTDOWN_PIN, 0);

    /* Configure interrupt pin as input */
    if (gpioSetMode(INTERRUPT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set interrupt pin mode.\n");
        goto cleanup;
    }

    /* Configure servo pin for hardware PWM */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set servo pin mode.\n");
        goto cleanup;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        goto cleanup;
    }

    /* Power up sensor */
    gpioWrite(SHUTDOWN_PIN, 1);
    gpioDelay(100000); /* 100 ms power-up settle */

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed.\n");
        goto cleanup;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        goto cleanup;
    }

    printf("Smart parking gate running.  Ctrl+C to exit.\n");

    bool gate_open = false;

    while (g_running) {
        uint16_t distance_mm = 0;

        if (vl53l1x_read_distance_mm(g_i2c_handle, &distance_mm) != 0) {
            fprintf(stderr, "Distance read failed — retrying.\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        int distance_cm = distance_mm / 10;

        if (!gate_open && distance_cm < DISTANCE_THRESHOLD_OPEN_CM) {
            set_servo_angle(0);
            gate_open = true;
            log_event("Gate Opened", distance_mm);
            printf("Gate opened (distance: %d cm)\n", distance_cm);
        } else if (gate_open && distance_cm > DISTANCE_THRESHOLD_CLOSE_CM) {
            set_servo_angle(180);
            gate_open = false;
            log_event("Gate Closed", distance_mm);
            printf("Gate closed (distance: %d cm)\n", distance_cm);
        }

        gpioDelay(POLL_DELAY_US);
    }

cleanup:
    printf("\nShutting down...\n");

    /* Close gate and power down sensor */
    set_servo_angle(180);
    gpioWrite(SHUTDOWN_PIN, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);

    if (g_log_file) {
        log_event("System Shutdown", -1);
        fclose(g_log_file);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

