static int vl53l1x_read_distance_mm(int handle, uint16_t *distance_mm)
{
    uint16_t status = 0;

    /* Poll the interrupt status register for a new data-ready flag */
    for (int i = 0; i < 50; i++) {
        if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_INT_STAT, &status) != 0)
            return -1;
        if ((status & 0x01) != 0)
            break;
        gpioDelay(2000); /* 2 ms */
    }
    if ((status & 0x01) == 0) {
        fprintf(stderr, "[VL53L1X] Timeout waiting for data-ready.\n");
        return -1;
    }

    /* Read 16-bit range result (mm) */
    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_RANGE, distance_mm) != 0)
        return -1;

    /* Clear the interrupt so the next measurement can signal */
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_INT_CLR, 0x0001) != 0)
        return -1;

    return 0;
}

/* ------------------------------- Servo ----------------------------------- */
static void set_servo_angle(int angle)
{
    if (angle < 0)   angle = 0;
    if (angle > 180) angle = 180;

    int pulse_us = SERVO_OPEN_US +
                   (int)((long)angle * (SERVO_CLOSE_US - SERVO_OPEN_US) / 180);
    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "[Servo] gpioServo failed for angle %d.\n", angle);
    }
}

/* ------------------------------- Logging --------------------------------- */
static void log_event(const char *event, int distance_mm)
{
    if (!g_log_file)
        return;

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[Log] localtime_r failed.\n");
        return;
    }

    fprintf(g_log_file, "%04d-%02d-%02d %02d:%02d:%02d, %s, Distance: %d mm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event, distance_mm);
    fflush(g_log_file);
}

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure shutdown pin as output, keep sensor in shutdown */
    if (gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set shutdown pin mode.\n");
        goto cleanup;
    }
    gpioWrite(SHUTDOWN_PIN, 0);

    /* Configure interrupt pin as input */
    if (gpioSetMode(INTERRUPT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set interrupt pin mode.\n");
        goto cleanup;
    }

    /* Configure servo pin for hardware PWM */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set servo pin mode.\n");
        goto cleanup;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        goto cleanup;
    }

    /* Power up sensor */
    gpioWrite(SHUTDOWN_PIN, 1);
    gpioDelay(100000); /* 100 ms power-up settle */

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed.\n");
        goto cleanup;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        goto cleanup;
    }

    printf("Smart parking gate running.  Ctrl+C to exit.\n");

    bool gate_open = false;

    while (g_running) {
        uint16_t distance_mm = 0;

        if (vl53l1x_read_distance_mm(g_i2c_handle, &distance_mm) != 0) {
            fprintf(stderr, "Distance read failed — retrying.\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        int distance_cm = distance_mm / 10;

        if (!gate_open && distance_cm < DISTANCE_THRESHOLD_OPEN_CM) {
            set_servo_angle(0);
            gate_open = true;
            log_event("Gate Opened", distance_mm);
            printf("Gate opened (distance: %d cm)\n", distance_cm);
        } else if (gate_open && distance_cm > DISTANCE_THRESHOLD_CLOSE_CM) {
            set_servo_angle(180);
            gate_open = false;
            log_event("Gate Closed", distance_mm);
            printf("Gate closed (distance: %d cm)\n", distance_cm);
        }

        gpioDelay(POLL_DELAY_US);
    }

cleanup:
    printf("\nShutting down...\n");

    /* Close gate and power down sensor */
    set_servo_angle(180);
    gpioWrite(SHUTDOWN_PIN, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);

    if (g_log_file) {
        log_event("System Shutdown", -1);
        fclose(g_log_file);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

