#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define MOTOR_FORWARD_PIN 17
#define MOTOR_BACKWARD_PIN 18
#define INTERRUPT_PIN 24

#define DISTANCE_THRESHOLD_LOW 100
#define DISTANCE_THRESHOLD_HIGH 300

#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_SYSTEM_START 0x0001
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x001E

#define VL53L1X_DATA_READY_MASK 0x01

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int motor_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(uint8_t reg, uint8_t value) {
    char buf[3] = { (char)(reg >> 8), (char)(reg & 0xFF), (char)value };
    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "I2C write failed (reg 0x%04X, val 0x%02X): %d\n", reg, value, result);
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(uint8_t reg, uint8_t *buf, uint8_t len) {
    char reg_buf[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    int result = i2cWriteDevice(i2c_handle, reg_buf, 2);
    if (result != 0) {
        fprintf(stderr, "I2C write (reg addr) failed (reg 0x%04X): %d\n", reg, result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, (char *)buf, len);
    if (result != len) {
        fprintf(stderr, "I2C read failed (reg 0x%04X, expected %d): %d\n", reg, len, result);
        return -1;
    }
    return 0;
}

static int vl53l1x_init(void) {
    if (i2c_write_reg16(VL53L1X_REG_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg16(VL53L1X_REG_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg16(VL53L1X_REG_SYSTEM_START, 0x01) != 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(uint16_t *distance) {
    uint8_t status = 0;
    int retries = 0;
    while (retries < 10) {
        if (i2c_read_reg16(VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) != 0) {
            retries++;
            gpioDelay(10000 << retries);
            continue;
        }
        if (status & VL53L1X_DATA_READY_MASK) break;
        gpioDelay(10000);
        retries++;
    }
    if (retries >= 10) {
        fprintf(stderr, "VL53L1X data not ready after 10 retries\n");
        return -1;
    }
    uint8_t buf[2];
    if (i2c_read_reg16(VL53L1X_REG_RESULT_DISTANCE, buf, 2) != 0) return -1;
    *distance = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static void motor_forward(void) {
    if (motor_state != 1) {
        gpioWrite(MOTOR_FORWARD_PIN, 1);
        gpioWrite(MOTOR_BACKWARD_PIN, 0);
        motor_state = 1;
        printf("Motor: FORWARD\n");
    }
}

static void motor_backward(void) {
    if (motor_state != -1) {
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        gpioWrite(MOTOR_BACKWARD_PIN, 1);
        motor_state = -1;
        printf("Motor: BACKWARD\n");
    }
}

static void motor_stop(void) {
    if (motor_state != 0) {
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        gpioWrite(MOTOR_BACKWARD_PIN, 0);
        motor_state = 0;
        printf("Motor: STOP\n");
    }
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    uint16_t distance = 0;
    if (vl53l1x_read_distance(&distance) == 0) {
        printf("Distance: %u mm\n", distance);
        if (distance < DISTANCE_THRESHOLD_LOW) {
            motor_forward();
        } else if (distance > DISTANCE_THRESHOLD_HIGH) {
            motor_backward();
        } else {
            motor_stop();
        }
    } else {
        fprintf(stderr, "Failed to read distance. Stopping motor.\n");
        motor_stop();
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_PIN, PI_PUD_UP);

    if (gpioSetISRFuncEx(INTERRUPT_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Program started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nCleaning up...\n");
    motor_stop();
    gpioSetISRFuncEx(INTERRUPT_PIN, RISING_EDGE, 0, NULL, NULL);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

