/*
 * MPR121 Proximity Art Installation — Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   MPR121 SDA  -> GPIO 2  (I2C bus 1 SDA)
 *   MPR121 SCL  -> GPIO 3  (I2C bus 1 SCL)
 *   MPR121 VDD  -> 3.3 V
 *   MPR121 GND  -> GND
 *   LED bit 0   -> GPIO 17
 *   LED bit 1   -> GPIO 18
 *   LED bit 2   -> GPIO 27
 *   LED bit 3   -> GPIO 22
 *
 * Build:  gcc -O2 -Wall -Wextra -o mpr121_art mpr121_art.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- MPR121 I2C ---- */
#define I2C_BUS        "/dev/i2c-1"
#define MPR121_ADDR    0x5A

/* ---- MPR121 register addresses ---- */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ECR            0x5E
#define MPR121_SOFTRESET      0x80

/* ---- LED GPIOs (BCM numbering) ---- */
#define LED0_PIN 17
#define LED1_PIN 18
#define LED2_PIN 27
#define LED3_PIN 22

#define NUM_ELECTRODES 12
#define POLL_DELAY_MS  50

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* MPR121 driver                                                       */
/* ------------------------------------------------------------------ */

static int mpr121_init(int fd)
{
    /* Soft reset */
    if (i2c_write_reg8(fd, MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    usleep(10000); /* 10 ms settle */

    /* Verify sensor is present by reading back ECR */
    uint8_t ecr = 0;
    if (i2c_read_reg8(fd, MPR121_ECR, &ecr) < 0)
        return -1;
    if (ecr != 0x00) {
        fprintf(stderr, "Warning: ECR readback 0x%02X (expected 0x00)\n", ecr);
    }

    /* Put MPR121 into stop mode (ECR = 0) before configuration */
    if (i2c_write_reg8(fd, MPR121_ECR, 0x00) < 0)
        return -1;

    /* Minimal configuration: enable 12 electrodes, baseline tracking */
    if (i2c_write_reg8(fd, 0x2B, 0x01) < 0) return -1; /* MHDR */
    if (i2c_write_reg8(fd, 0x2C, 0x01) < 0) return -1; /* NHDR */
    if (i2c_write_reg8(fd, 0x2D, 0x0E) < 0) return -1; /* NCLR */
    if (i2c_write_reg8(fd, 0x2E, 0x00) < 0) return -1; /* FDLR */
    if (i2c_write_reg8(fd, 0x2F, 0x01) < 0) return -1; /* MHDF */
    if (i2c_write_reg8(fd, 0x30, 0x01) < 0) return -1; /* NHDF */
    if (i2c_write_reg8(fd, 0x31, 0x0E) < 0) return -1; /* NCLF */
    if (i2c_write_reg8(fd, 0x32, 0x00) < 0) return -1; /* FDLF */
    if (i2c_write_reg8(fd, 0x33, 0x00) < 0) return -1; /* NHDT */
    if (i2c_write_reg8(fd, 0x34, 0x00) < 0) return -1; /* NCLT */
    if (i2c_write_reg8(fd, 0x35, 0x00) < 0) return -1; /* FDLT */

    /* Touch / release thresholds for all 12 electrodes */
    for (int i = 0; i < NUM_ELECTRODES; i++) {
        if (i2c_write_reg8(fd, 0x41 + (i * 2), 0x0F) < 0) return -1; /* TTH */
        if (i2c_write_reg8(fd, 0x42 + (i * 2), 0x0A) < 0) return -1; /* RTH */
    }

    /* Enable 12 electrodes, baseline tracking, no GPIO / proximity */
    if (i2c_write_reg8(fd, MPR121_ECR, 0x8F) < 0)
        return -1;

    return 0;
}

static int mpr121_read_touch(int fd, uint16_t *touch_status)
{
    uint8_t lo = 0, hi = 0;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_L, &lo) < 0)
        return -1;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_H, &hi) < 0)
        return -1;
    *touch_status = ((uint16_t)hi << 8) | lo;
    return 0;
}

/* ------------------------------------------------------------------ */
/* LED control (4-bit via libgpiod)                                    */
/* ------------------------------------------------------------------ */

static int led_pins[4] = { LED0_PIN, LED1_PIN, LED2_PIN, LED3_PIN };

static int led_init(struct gpiod_chip *chip, struct gpiod_line *lines[4])
{
    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, led_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                    led_pins[i], strerror(errno));
            return -1;
        }
        if (gpiod_line_request_output(lines[i], "mpr121_art", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO %d as output: %s\n",
                    led_pins[i], strerror(errno));
            return -1;
        }
    }
    return 0;
}

static void led_set(struct gpiod_line *lines[4], uint8_t pattern)
{
    for (int i = 0; i < 4; i++)
        gpiod_line_set_value(lines[i], (pattern >> i) & 1);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_event(uint16_t touch_status)
{
    time_t rawtime;
    struct tm timeinfo;
    char ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Proximity: 0x%04X (ELE0-ELE11)\n", ts, touch_status);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int i2c_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_lines[4] = { NULL, NULL, NULL, NULL };
    int ret = EXIT_FAILURE;

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open I2C bus */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                MPR121_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Initialize MPR121 */
    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor absent or bus error)\n");
        goto cleanup;
    }

    /* Open GPIO chip and request LED lines */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Cannot open gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }

    if (led_init(chip, led_lines) < 0) {
        fprintf(stderr, "LED GPIO initialization failed\n");
        goto cleanup;
    }

    printf("MPR121 proximity art running. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        uint16_t touch_status = 0;
        if (mpr121_read_touch(i2c_fd, &touch_status) < 0) {
            fprintf(stderr, "I2C read error — continuing\n");
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }

        uint8_t pattern = (uint8_t)(touch_status & 0x0F);
        led_set(led_lines, pattern);

        if (touch_status & 0x0FFF)
            log_event(touch_status);

        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Turn off LEDs */
    if (led_lines[0])
        for (int i = 0; i < 4; i++)
            gpiod_line_set_value(led_lines[i], 0);

    /* Release GPIO lines */
    for (int i = 0; i < 4; i++)
        if (led_lines[i])
            gpiod_line_release(led_lines[i]);

    if (chip)
        gpiod_chip_close(chip);

    if (i2c_fd >= 0)
        close(i2c_fd);

    return ret;
}

