#include <errno.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"

#define SPEED_OF_SOUND_CM_PER_S 34300.0
#define MIN_DISTANCE_CM         2.0
#define MAX_DISTANCE_CM         400.0
#define TRIGGER_PULSE_US        10
#define ECHO_TIMEOUT_US         30000
#define LOOP_DELAY_US           1000000
#define TRIGGER_SETTLE_US       5

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low.\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static double measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low.\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_SETTLE_US);

    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high.\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low after pulse.\n");
        return -1.0;
    }

    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() >= timeout_tick) {
            fprintf(stderr, "Error: echo start timeout (sensor absent or not responding).\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() >= timeout_tick) {
            fprintf(stderr, "Error: echo end timeout (stuck high).\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    double distance = (double)diff * SPEED_OF_SOUND_CM_PER_S / 2000000.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Error: distance %.2f cm out of range [%.0f-%.0f].\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
