    (void)userdata;

    if (level == 1) {
        g_start_tick = tick;
    } else if (level == 0) {
        if (g_start_tick != 0) {
            uint32_t diff = tick - g_start_tick;
            g_pulse_us    = diff;
            g_start_tick  = 0;
