#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29
#define XSHUT_PIN      27
#define POLL_MS        100

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET          0x000B
#define REG_SYSTEM_START        0x0000
#define REG_RESULT_RANGE_STATUS 0x0014
#define REG_RESULT_DISTANCE     0x0096

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address followed by a single byte value */
static int i2c_write_reg8(int fd, uint16_t reg, uint8_t val)
{
    uint8_t buf[3] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF), val };
    if (write(fd, buf, 3) != 3) {
        syslog(LOG_ERR, "I2C write to reg 0x%04X failed: %s", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Write a 16-bit register address, then read `len` bytes */
static int i2c_read_reg(int fd, uint16_t reg, uint8_t *buf, size_t len)
{
    uint8_t addr[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(fd, addr, 2) != 2) {
        syslog(LOG_ERR, "I2C write (addr) for reg 0x%04X failed: %s", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        syslog(LOG_ERR, "I2C read from reg 0x%04X failed: %s", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int fd)
{
    /* Soft reset */
    if (i2c_write_reg8(fd, REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(10000); /* 10 ms */
    if (i2c_write_reg8(fd, REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(10000);

    /* Start ranging */
    if (i2c_write_reg8(fd, REG_SYSTEM_START, 0x01) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int vl53l1x_read_distance(int fd, int *distance_mm)
{
    uint8_t status = 0;
    if (i2c_read_reg(fd, REG_RESULT_RANGE_STATUS, &status, 1) < 0) return -1;

    /* Bit 0 of range status indicates data ready */
    if (!(status & 0x01)) {
        return 1; /* not ready yet */
    }

    uint8_t dist_buf[2] = {0};
    if (i2c_read_reg(fd, REG_RESULT_DISTANCE, dist_buf, 2) < 0) return -1;

    *distance_mm = (dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

int main(void)
{
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install signal handlers: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(XSHUT_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", XSHUT_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Active-low XSHUT: pull high to enable sensor */
    if (gpioWrite(XSHUT_PIN, 1) < 0) {
        syslog(LOG_ERR, "Failed to write GPIO%d", XSHUT_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioDelay(10000); /* 10 ms settle */

    char dev_path[32];
    snprintf(dev_path, sizeof(dev_path), "/dev/i2c-%d", I2C_BUS);
    g_i2c_fd = open(dev_path, O_RDWR);
    if (g_i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", dev_path, strerror(errno));
        gpioWrite(XSHUT_PIN, 0);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioWrite(XSHUT_PIN, 0);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_fd) < 0) {
        syslog(LOG_ERR, "VL53L1X initialization failed");
        close(g_i2c_fd);
        gpioWrite(XSHUT_PIN, 0);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "VL53L1X sensor initialized on I2C bus %d, addr 0x%02X", I2C_BUS, I2C_ADDR);

    while (g_running) {
        int distance = 0;
        int rc = vl53l1x_read_distance(g_i2c_fd, &distance);

        if (rc == 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
            syslog(LOG_INFO, "%s Distance: %d mm", ts, distance);
        } else if (rc < 0) {
            syslog(LOG_ERR, "Failed to read distance from VL53L1X");
        }
        /* rc == 1: data not ready yet, just wait */

        gpioDelay(POLL_MS * 1000);
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    gpioWrite(XSHUT_PIN, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

