#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD_CM 20
#define POLL_INTERVAL_US 100000

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START_STOP 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(log_file);
}

static int i2c_write_reg16(uint8_t reg_hi, uint8_t reg_lo, uint8_t val) {
    char buf[3] = {reg_hi, reg_lo, val};
    return i2cWriteDevice(i2c_handle, buf, 3);
}

static int i2c_read_reg16(uint8_t reg_hi, uint8_t reg_lo, uint8_t *buf, uint32_t len) {
    char reg[2] = {reg_hi, reg_lo};
    if (i2cWriteDevice(i2c_handle, reg, 2) < 0) return -1;
    return i2cReadDevice(i2c_handle, (char *)buf, len);
}

static int vl53l1x_init(void) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(0x01, 0x0F, &model_id, 1) < 0) {
        log_event("Error: Failed to read model ID from VL53L1X");
        return -1;
    }
    if (model_id != 0xEA) {
        char msg[64];
        snprintf(msg, sizeof(msg), "Error: Unexpected model ID 0x%02X (expected 0xEA)", model_id);
        log_event(msg);
        return -1;
    }
    if (i2c_write_reg16(0x00, 0x00, 0x01) < 0) {
        log_event("Error: Failed to start ranging");
        return -1;
    }
    return 0;
}

static int vl53l1x_read_distance_mm(uint16_t *distance_mm) {
    uint8_t status = 0;
    if (i2c_read_reg16(0x00, 0x89, &status, 1) < 0) {
        log_event("Error: Failed to read range status");
        return -1;
    }
    if ((status & 0x01) == 0) {
        return 1; /* not ready yet */
    }
    uint8_t data[2] = {0};
    if (i2c_read_reg16(0x00, 0x96, data, 2) < 0) {
        log_event("Error: Failed to read distance register");
        return -1;
    }
    *distance_mm = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

static void control_gate(int open) {
    gpioWrite(GATE_GPIO, open ? 1 : 0);
    log_event(open ? "Gate opened" : "Gate closed");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X\n", I2C_BUS, VL53L1X_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioWrite(GATE_GPIO, 0);
    log_event("Gate closed (initial state)");

    log_file = fopen("gate_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int gate_state = 0;

    while (running) {
        uint16_t distance_mm = 0;
        int rc = vl53l1x_read_distance_mm(&distance_mm);
        if (rc == 0) {
            int distance_cm = distance_mm / 10;
            char msg[64];
            snprintf(msg, sizeof(msg), "Distance: %d cm", distance_cm);
            log_event(msg);

            if (distance_cm < DISTANCE_THRESHOLD_CM && !gate_state) {
                control_gate(1);
                gate_state = 1;
            } else if (distance_cm >= DISTANCE_THRESHOLD_CM && gate_state) {
                control_gate(0);
                gate_state = 0;
            }
        } else if (rc < 0) {
            log_event("Error: Failed to read distance");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("Shutting down");
    gpioWrite(GATE_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

