#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define SERVO_PIN        18

#define SPEED_OF_SOUND   34300.0
#define MIN_DISTANCE     2.0
#define MAX_DISTANCE     400.0
#define SERVO_MIN_PULSE  500
#define SERVO_MAX_PULSE  2500
#define SERVO_MIN_ANGLE  0
#define SERVO_MAX_ANGLE  180
#define MOVING_AVG_SIZE  5
#define ECHO_TIMEOUT_US  30000
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US    100000
#define SAMPLE_DELAY_US  100000

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_width = 0;
static volatile sig_atomic_t new_pulse = 0;
static FILE *log_file = NULL;

static double distance_buffer[MOVING_AVG_SIZE];
static int    buffer_index = 0;
static int    buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        uint32_t start_tick = tick;
        while (gpioRead(ECHO_PIN) == 1) {
            if ((uint32_t)(gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
                return;
            }
        }
        uint32_t end_tick = gpioTick();
        uint32_t diff = end_tick - start_tick;
        pulse_width = diff;
        new_pulse = 1;
    }
}

static double calculate_distance(uint32_t pw) {
    if (pw == 0) return -1.0;
    double time_s = pw / 1000000.0;
    double dist = (time_s * SPEED_OF_SOUND) / 2.0;
    if (dist < MIN_DISTANCE || dist > MAX_DISTANCE) return -1.0;
    return dist;
}

static double moving_average(double new_distance) {
    distance_buffer[buffer_index] = new_distance;
    buffer_index = (buffer_index + 1) % MOVING_AVG_SIZE;
    if (buffer_count < MOVING_AVG_SIZE) buffer_count++;
    double sum = 0.0;
    for (int i = 0; i < buffer_count; i++) sum += distance_buffer[i];
    return (buffer_count > 0) ? (sum / buffer_count) : new_distance;
}

static int set_servo_angle(int angle) {
    if (angle < SERVO_MIN_ANGLE) angle = SERVO_MIN_ANGLE;
    if (angle > SERVO_MAX_ANGLE) angle = SERVO_MAX_ANGLE;
    int pulse = SERVO_MIN_PULSE + (int)((angle / 180.0) * (SERVO_MAX_PULSE - SERVO_MIN_PULSE));
    if (gpioServo(SERVO_PIN, pulse) != 0) {
        fprintf(stderr, "Error: gpioServo failed for angle %d\n", angle);
        return -1;
    }
    return 0;
}

static void log_data(double distance, int servo_angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%d\n", timestamp, distance, servo_angle);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set servo pin mode\n");
        gpioTerminate();
        return 1;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to set echo alert function\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file\n");
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (deg)\n");
    fflush(log_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }

    for (int i = 0; i < MOVING_AVG_SIZE; i++) distance_buffer[i] = 0.0;

    while (running) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, 0);

        uint32_t start_wait = gpioTick();
        while (!new_pulse && running) {
            if ((uint32_t)(gpioTick() - start_wait) > ECHO_TIMEOUT_US) {
                break;
            }
            gpioDelay(100);
        }

        uint32_t pw = pulse_width;
        new_pulse = 0;

        double raw_distance = calculate_distance(pw);
        double filtered_distance = moving_average(raw_distance);

        int servo_angle;
        if (raw_distance > 0.0) {
            servo_angle = (int)(filtered_distance * 10.0);
            if (servo_angle < SERVO_MIN_ANGLE) servo_angle = SERVO_MIN_ANGLE;
            if (servo_angle > SERVO_MAX_ANGLE) servo_angle = SERVO_MAX_ANGLE;
        } else {
            filtered_distance = -1.0;
            servo_angle = 90;
        }

        if (set_servo_angle(servo_angle) != 0) {
            fprintf(stderr, "Warning: servo set failed\n");
        }

        log_data(filtered_distance, servo_angle);
        gpioDelay(SAMPLE_DELAY_US);
    }

    set_servo_angle(0);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

