#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_LED 17
#define BUFFER_SIZE 10
#define THRESHOLD_MM 200
#define POLL_DELAY_US 50000

#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_I2C_SLAVE_DEVID 0x0001
#define VL53L1X_REG_VHV_CONFIG_TIMEOUT_MACROP_LOOP_BOUND 0x0008
#define VL53L1X_REG_PHASECAL_CONFIG_TIMEOUT_MACROP 0x004B
#define VL53L1X_REG_RANGE_CONFIG_TIMEOUT_MACROP_A 0x005E
#define VL53L1X_REG_RANGE_CONFIG_TIMEOUT_MACROP_B 0x0061
#define VL53L1X_REG_RANGE_CONFIG_SIGMA_THRESH 0x0064
#define VL53L1X_REG_RANGE_CONFIG_MIN_COUNT_RATE_RTN_LIMIT 0x0066
#define VL53L1X_REG_INTERMEASUREMENT_PERIOD 0x006B
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO 0x006A
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0061
#define VL53L1X_REG_SYSTEM_MODE_START 0x0087
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0089
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static int i2c_handle = -1;
static int distance_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(uint8_t reg, uint16_t value) {
    char buf[3] = { (char)(reg >> 8), (char)(reg & 0xFF), (char)(value & 0xFF) };
    if (i2cWriteDevice(i2c_handle, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_write_reg8(uint8_t reg, uint8_t value) {
    char buf[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg16(uint8_t reg, uint16_t *value) {
    char buf[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) return -1;
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) return -1;
    *value = (uint16_t)((uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int i2c_read_reg8(uint8_t reg, uint8_t *value) {
    char buf[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) return -1;
    if (i2cReadDevice(i2c_handle, buf, 1) != 1) return -1;
    *value = (uint8_t)buf[0];
    return 0;
}

static int vl53l1x_init(void) {
    uint16_t dev_id = 0;
    if (i2c_read_reg16(VL53L1X_REG_I2C_SLAVE_DEVID, &dev_id) != 0) {
        fprintf(stderr, "Error: Failed to read device ID.\n");
        return -1;
    }
    if (dev_id != 0xEACC) {
        fprintf(stderr, "Error: Invalid device ID: 0x%04X (expected 0xEACC).\n", dev_id);
        return -1;
    }

    if (i2c_write_reg8(VL53L1X_REG_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg8(VL53L1X_REG_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg16(VL53L1X_REG_VHV_CONFIG_TIMEOUT_MACROP_LOOP_BOUND, 0x09) != 0) return -1;
    if (i2c_write_reg16(VL53L1X_REG_PHASECAL_CONFIG_TIMEOUT_MACROP, 0x78) != 0) return -1;
    if (i2c_write_reg16(VL53L1X_REG_RANGE_CONFIG_TIMEOUT_MACROP_A, 0x001D) != 0) return -1;
    if (i2c_write_reg16(VL53L1X_REG_RANGE_CONFIG_TIMEOUT_MACROP_B, 0x001E) != 0) return -1;
    if (i2c_write_reg16(VL53L1X_REG_RANGE_CONFIG_SIGMA_THRESH, 0x0000) != 0) return -1;
    if (i2c_write_reg16(VL53L1X_REG_RANGE_CONFIG_MIN_COUNT_RATE_RTN_LIMIT, 0x0000) != 0) return -1;
    if (i2c_write_reg16(VL53L1X_REG_INTERMEASUREMENT_PERIOD, 0x0068) != 0) return -1;
    if (i2c_write_reg8(VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO, 0x04) != 0) return -1;

    return 0;
}

static int vl53l1x_start_ranging(void) {
    if (i2c_write_reg8(VL53L1X_REG_SYSTEM_MODE_START, 0x40) != 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(uint16_t *distance) {
    uint8_t status = 0;
    if (i2c_read_reg8(VL53L1X_REG_RESULT_INTERRUPT_STATUS, &status) != 0) return -1;
    if ((status & 0x07) == 0) return 1;

    uint16_t dist = 0;
    if (i2c_read_reg16(VL53L1X_REG_RESULT_DISTANCE, &dist) != 0) return -1;

    if (i2c_write_reg8(VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) return -1;
    *distance = dist;
    return 0;
}

static void add_to_buffer(int distance) {
    distance_buffer[buffer_index] = distance;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void check_threshold(int distance) {
    gpioWrite(GPIO_LED, (distance < THRESHOLD_MM) ? 1 : 0);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2c_write_reg8(VL53L1X_REG_SYSTEM_MODE_START, 0x00);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init() != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        cleanup();
        return 1;
    }

    if (vl53l1x_start_ranging() != 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        cleanup();
        return 1;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("VL53L1X ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t distance = 0;
        int ret = vl53l1x_read_distance(&distance);

        if (ret == 0) {
            add_to_buffer((int)distance);
            check_threshold((int)distance);
            printf("Distance: %u mm\n", distance);
        } else if (ret < 0) {
            fprintf(stderr, "Error: I2C read/write failure.\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

