#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

#define DEFAULT_I2C_BUS 1
#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define PROXIMITY_LOG_FILE "proximity.log"
#define INTERRUPT_GPIO 27

#define SI1102_REG_PART_ID 0x00
#define SI1102_REG_HW_KEY 0x07
#define SI1102_REG_MEAS_RATE0 0x08
#define SI1102_REG_IRQ_ENABLE 0x0F
#define SI1102_REG_IRQ_MODE1 0x10
#define SI1102_REG_IRQ_MODE2 0x11
#define SI1102_REG_IRQ_STATUS 0x12
#define SI1102_REG_ALS_VIS_DATA0 0x22
#define SI1102_REG_ALS_VIS_DATA1 0x23
#define SI1102_REG_PS1_DATA0 0x24
#define SI1102_REG_PS1_DATA1 0x25

static int i2c_address = DEFAULT_I2C_ADDRESS;
static int threshold = DEFAULT_THRESHOLD;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t interrupt_flag = 0;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

static int i2c_read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, pigpio_error(rc));
    }
    return rc;
}

static int init_sensor(int handle) {
    int part_id = i2c_read_reg(handle, SI1102_REG_PART_ID);
    if (part_id < 0) return -1;
    if (part_id != 0x02) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x02)\n", part_id);
        return -1;
    }

    if (i2c_write_reg(handle, SI1102_REG_HW_KEY, 0x17) < 0) return -1;
    if (i2c_write_reg(handle, SI1102_REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (i2c_write_reg(handle, SI1102_REG_IRQ_ENABLE, 0x00) < 0) return -1;
    if (i2c_write_reg(handle, SI1102_REG_IRQ_MODE1, 0x00) < 0) return -1;
    if (i2c_write_reg(handle, SI1102_REG_IRQ_MODE2, 0x00) < 0) return -1;

    if (i2c_write_reg(handle, SI1102_REG_IRQ_ENABLE, 0x01) < 0) return -1;
    if (i2c_write_reg(handle, SI1102_REG_IRQ_MODE1, 0x01) < 0) return -1;
    if (i2c_write_reg(handle, SI1102_REG_IRQ_MODE2, 0x01) < 0) return -1;

    return 0;
}

static int read_proximity(int handle) {
    int low = i2c_read_reg(handle, SI1102_REG_PS1_DATA0);
    if (low < 0) return -1;
    int high = i2c_read_reg(handle, SI1102_REG_PS1_DATA1);
    if (high < 0) return -1;
    return (high << 8) | low;
}

static void log_proximity(int proximity_value, const char *status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    pthread_mutex_lock(&log_mutex);
    if (log_file != NULL) {
        fprintf(log_file, "%s, Proximity: %d, Status: %s\n",
                timestamp, proximity_value, status);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
    pthread_mutex_unlock(&log_mutex);
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
