#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define PWM_PIN          18

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  200.0f
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000
#define PWM_RANGE        1000
#define PWM_DUTY         (PWM_RANGE / 2)
#define TIMEOUT_US       200000
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US    50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static float map_log(float x, float in_min, float in_max,
                     float out_min, float out_max) {
    if (x <= in_min) return out_min;
    if (x >= in_max) return out_max;
    float log_x = log10f(x / in_min);
    float log_max = log10f(in_max / in_min);
    return out_min * powf(10.0f, (log_x / log_max) * (log10f(out_max / out_min)));
}

static float read_distance(void) {
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0f;
    }
    gpioDelay(2);

    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0f;
    }

    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo start\n");
            return -1.0f;
        }
    }
    uint32_t echo_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo end\n");
            return -1.0f;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t diff = echo_end - echo_start;
    float distance = (float)diff / 58.0f;
    return distance;
}

static void set_frequency(int frequency) {
    if (frequency < 0) return;
    if (gpioSetPWMfrequency(PWM_PIN, frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", frequency);
        return;
    }
    if (gpioPWM(PWM_PIN, PWM_DUTY) < 0) {
        fprintf(stderr, "Error: gpioPWM(%d) failed\n", PWM_DUTY);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(PWM_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_frequency = MIN_FREQUENCY_HZ;
    set_frequency(last_frequency);

    while (g_running) {
        float distance = read_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Warning: sensor read failed, preserving last frequency\n");
        } else if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            fprintf(stderr, "Warning: distance %.2f cm out of range, preserving last frequency\n", distance);
        } else {
            float frequency = map_log(distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM,
                                      MIN_FREQUENCY_HZ, MAX_FREQUENCY_HZ);
            set_frequency((int)frequency);
            last_frequency = (int)frequency;
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

