#define MIN_FREQUENCY   200
#define MAX_FREQUENCY   2000
#define ECHO_TIMEOUT_US 100000
#define LOOP_DELAY_US   10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode.\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin mode.\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode.\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set echo pin pull-down.\n");
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low.\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(BUZZER_PIN, 1000) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on buzzer pin.\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static double measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set trigger low.\n");
        return -1.0;
    }
    gpioDelay(2);

    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set trigger high.\n");
        return -1.0;
    }
    gpioDelay(10);
