        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    double last_valid_distance = -1.0;

    while (running) {
        double distance = measure_distance();

        if (distance < 0) {
            fprintf(stderr, "Warning: sensor read failed, using last valid distance.\n");
            if (last_valid_distance > 0) {
                distance = last_valid_distance;
