    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ICU-20201 distance logger started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t distance;
        if (read_distance(&distance) == 0) {
            log_data(distance);
        } else {
            fprintf(stderr, "Error: failed to read distance after retries\n");
        }
        gpioDelay(READ_DELAY);
    }

    cleanup();
    printf("Program terminated gracefully.\n");
