 * Build:  gcc -O2 -Wall -Wextra -o si1175_logger si1175_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1175_ADDR    0x60          /* Si1175 default 7-bit I2C address */
#define LOG_FILE       "proximity_log.csv"
#define SAMPLE_PERIOD  5             /* seconds between samples */

/* Si1175 register addresses (from the Si1175 datasheet / reference manual) */
#define SI1175_REG_PART_ID       0x00
#define SI1175_REG_HW_KEY        0x07
#define SI1175_REG_ALS_VIS_DATA0 0x22
#define SI1175_REG_ALS_VIS_DATA1 0x23
#define SI1175_REG_COMMAND       0x30

/* Si1175 command codes */
#define SI1175_CMD_RESET         0x01
#define SI1175_CMD_ALS_FORCE     0x06

/* Expected PART_ID for the Si1175 (0x45 for Si1175, 0x46 for Si1175-EVB) */
#define SI1175_PART_ID_EXPECTED  0x45

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * Write a single byte to a Si1175 register.
 * Returns 0 on success, -1 on error.
 */
static int si1175_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "write_reg(0x%02X, 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, value, strerror(errno), n);
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from a Si1175 register.
 * Returns 0 on success and stores the value in *out, -1 on error.
 */
static int si1175_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "write(reg=0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "read(reg=0x%02X) failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit little-endian sample from two consecutive registers.
 * Returns 0 on success and stores the value in *out, -1 on error.
 */
static int si1175_read_als(int fd, uint8_t reg_lo, uint16_t *out)
{
    uint8_t lo, hi;
    if (si1175_read_reg(fd, reg_lo, &lo) == -1)
        return -1;
    if (si1175_read_reg(fd, reg_lo + 1, &hi) == -1)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/*
 * Initialise the Si1175: reset, verify PART_ID, and issue a forced ALS
 * measurement so the first sample is valid.
 * Returns 0 on success, -1 on error.
 */
static int si1175_init(int fd)
{
    uint8_t part_id;

    /* Issue a software reset */
    if (si1175_write_reg(fd, SI1175_REG_COMMAND, SI1175_CMD_RESET) == -1)
        return -1;
    usleep(10000);  /* allow reset to complete */

    /* Read and verify PART_ID */
    if (si1175_read_reg(fd, SI1175_REG_PART_ID, &part_id) == -1)
        return -1;
    if (part_id != SI1175_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x%02X). "
                        "Wrong sensor or not present.\n",
                part_id, SI1175_PART_ID_EXPECTED);
        return -1;
    }

    /* Write HW_KEY to enable the device */
    if (si1175_write_reg(fd, SI1175_REG_HW_KEY, 0x17) == -1)
        return -1;

    /* Trigger a forced ALS measurement */
    if (si1175_write_reg(fd, SI1175_REG_COMMAND, SI1175_CMD_ALS_FORCE) == -1)
        return -1;
    usleep(10000);  /* allow first conversion to complete */

    return 0;
}

/*
 * Append a timestamped ALS reading to the CSV log file.
 * Returns 0 on success, -1 on error.
 */
static int log_als_reading(FILE *fp, uint16_t als_value)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u\n", timestamp, als_value) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) == EOF) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() == -1)
        goto cleanup;

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    /* Acquire the Si1175 device */
    if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) == -1) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI1175_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Initialise the sensor */
    if (si1175_init(fd) == -1) {
        fprintf(stderr, "Si1175 initialisation failed.\n");
        goto cleanup;
    }

    /* Open the log file in append mode */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* Write a CSV header if the file is empty */
    if (ftell(fp) == 0) {
        if (fprintf(fp, "timestamp,als_visible\n") < 0) {
            fprintf(stderr, "fprintf header failed: %s\n", strerror(errno));
            goto cleanup;
        }
        fflush(fp);
    }

    printf("Si1175 logger started. Logging to %s every %d seconds. "
           "Press Ctrl+C to stop.\n", LOG_FILE, SAMPLE_PERIOD);

    while (g_running) {
        uint16_t als_value;

        /* Trigger a forced ALS measurement */
        if (si1175_write_reg(fd, SI1175_REG_COMMAND, SI1175_CMD_ALS_FORCE) == -1) {
            fprintf(stderr, "Failed to trigger ALS measurement.\n");
            goto cleanup;
        }
        usleep(10000);  /* allow conversion to complete */

        /* Read the 16-bit ALS_VISIBLE value */
        if (si1175_read_als(fd, SI1175_REG_ALS_VIS_DATA0, &als_value) == -1) {
            fprintf(stderr, "Failed to read ALS_VISIBLE.\n");
            goto cleanup;
        }

        if (log_als_reading(fp, als_value) == -1) {
            fprintf(stderr, "Failed to log ALS reading.\n");
            goto cleanup;
        }

        printf("ALS_VISIBLE: %u\n", als_value);

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fp != NULL)
        fclose(fp);
    if (fd != -1)
        close(fd);
    return rc;
}

