#define SI1120_PART_ID_EXPECTED 0x20

/* Expected HW_KEY value (documented) */
#define SI1120_HW_KEY_EXPECTED  0x17

/* Sampling interval in microseconds (500 ms) */
#define SAMPLE_INTERVAL_US 500000

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Retry parameters */
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

/* Global resources for signal-safe cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers with retry                                    */
/* ------------------------------------------------------------------ */
static int i2c_read_byte_retry(int handle, uint8_t reg, uint8_t *value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0;
        }
        fprintf(stderr, "Warning: I2C read reg 0x%02X failed (attempt %d/%d, rc=%d)\n",
                reg, attempt + 1, MAX_RETRIES, result);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_write_byte_retry(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int result = i2cWriteByteData(handle, reg, value);
        if (result == 0)
            return 0;
        fprintf(stderr, "Warning: I2C write reg 0x%02X val 0x%02X failed (attempt %d/%d, rc=%d)\n",
                reg, value, attempt + 1, MAX_RETRIES, result);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Si1120 initialization                                               */
/* ------------------------------------------------------------------ */
static int si1120_init(int handle)
{
    uint8_t part_id = 0;

    /* 1. Software reset via command register */
    if (i2c_write_byte_retry(handle, SI1120_REG_COMMAND, SI1120_CMD_RESET) != 0) {
        fprintf(stderr, "Error: Failed to reset Si1120\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle after reset */

    /* 2. Verify part ID */
    if (i2c_read_byte_retry(handle, SI1120_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error: Failed to read Si1120 part ID\n");
        return -1;
    }
    if (part_id != SI1120_PART_ID_EXPECTED) {
        fprintf(stderr, "Error: Unexpected Si1120 part ID 0x%02X (expected 0x%02X)\n",
                part_id, SI1120_PART_ID_EXPECTED);
        return -1;
    }
    printf("Si1120 part ID verified: 0x%02X\n", part_id);

    /* 3. Write HW_KEY (documented mandatory init step) */
    if (i2c_write_byte_retry(handle, SI1120_REG_HW_KEY, SI1120_HW_KEY_EXPECTED) != 0) {
        fprintf(stderr, "Error: Failed to write Si1120 HW_KEY\n");
        return -1;
    }

    /* 4. Set measurement rate to 0 (manual / forced mode) */
    if (i2c_write_byte_retry(handle, SI1120_REG_MEAS_RATE0, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to set Si1120 measurement rate\n");
        return -1;
    }

    return 0;
}

