#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE    "/dev/i2c-1"
#define SI1182_ADDR   0x60
#define LOG_FILE      "biometric_log.txt"
#define SAMPLE_MS     100

/* Si1182 register addresses (from datasheet) */
#define SI1182_REG_PART_ID        0x00
#define SI1182_REG_REV_ID         0x01
#define SI1182_REG_SEQ_ID         0x02
#define SI1182_REG_INT_CFG        0x03
#define SI1182_REG_IRQ_ENABLE     0x04
#define SI1182_REG_IRQ_MODE1      0x05
#define SI1182_REG_IRQ_MODE2      0x06
#define SI1182_REG_HW_KEY         0x07
#define SI1182_REG_MEAS_RATE0     0x08
#define SI1182_REG_MEAS_RATE1     0x09
#define SI1182_REG_ALS_RATE       0x0A
#define SI1182_REG_PS_RATE        0x0B
#define SI1182_REG_PS_LED21       0x0C
#define SI1182_REG_PS_LED3        0x0D
#define SI1182_REG_PARAM_WR       0x17
#define SI1182_REG_COMMAND        0x18
#define SI1182_REG_RESPONSE       0x20
#define SI1182_REG_ALS_VIS_DATA0  0x22
#define SI1182_REG_ALS_VIS_DATA1  0x23
#define SI1182_REG_PS1_DATA0      0x24
#define SI1182_REG_PS1_DATA1      0x25

#define SI1182_PART_ID_EXPECTED   0x82
#define SI1182_CMD_RESET          0x01
#define SI1182_CMD_ALS_FORCE      0x06
#define SI1182_CMD_PS_FORCE       0x07
#define SI1182_CMD_ALS_PS_FORCE   0x0F

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int si1182_reset(int fd)
{
    if (i2c_write_reg8(fd, SI1182_REG_COMMAND, SI1182_CMD_RESET) < 0)
        return -1;
    usleep(10000); /* 10 ms settle */
    return 0;
}

static int si1182_init(int fd)
{
    uint8_t part_id = 0;

    if (si1182_reset(fd) < 0) {
        fprintf(stderr, "Si1182 reset failed\n");
        return -1;
    }

    if (i2c_read_reg8(fd, SI1182_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read Si1182 part ID — sensor may be absent\n");
        return -1;
    }
    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr, "Si1182 part ID mismatch: got 0x%02X, expected 0x%02X\n",
                part_id, SI1182_PART_ID_EXPECTED);
        return -1;
    }
    printf("Si1182 detected (part ID 0x%02X)\n", part_id);

    /* Measurement rate: 0x000F = 15 ms ALS + PS cycle */
    if (i2c_write_reg8(fd, SI1182_REG_MEAS_RATE0, 0x0F) < 0) return -1;
    if (i2c_write_reg8(fd, SI1182_REG_MEAS_RATE1, 0x00) < 0) return -1;

    /* ALS rate: 0x00 = 1x ALS per measurement cycle */
    if (i2c_write_reg8(fd, SI1182_REG_ALS_RATE, 0x00) < 0) return -1;

    /* PS rate: 0x00 = 1x PS per measurement cycle */
    if (i2c_write_reg8(fd, SI1182_REG_PS_RATE, 0x00) < 0) return -1;

    /* LED current for PS1 (LED1): 0x0F = 22.4 mA */
    if (i2c_write_reg8(fd, SI1182_REG_PS_LED21, 0x0F) < 0) return -1;

    /* Enable ALS and PS interrupts (optional) */
    if (i2c_write_reg8(fd, SI1182_REG_INT_CFG, 0x03) < 0) return -1;
    if (i2c_write_reg8(fd, SI1182_REG_IRQ_ENABLE, 0x03) < 0) return -1;

    return 0;
}

static int si1182_read_als(int fd, uint16_t *lux_raw)
{
    if (i2c_write_reg8(fd, SI1182_REG_COMMAND, SI1182_CMD_ALS_FORCE) < 0)
        return -1;
    usleep(5000);
    return i2c_read_reg16(fd, SI1182_REG_ALS_VIS_DATA0, lux_raw);
}

static int si1182_read_ps(int fd, uint16_t *prox)
{
    if (i2c_write_reg8(fd, SI1182_REG_COMMAND, SI1182_CMD_PS_FORCE) < 0)
        return -1;
    usleep(5000);
    return i2c_read_reg16(fd, SI1182_REG_PS1_DATA0, prox);
}

static void log_data(FILE *fp, uint16_t lux, uint16_t prox)
{
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%03ld", ts.tv_nsec / 1000000);

    fprintf(fp, "%s,%u,%u\n", timestamp, lux, prox);
    fflush(fp);
    printf("%s,%u,%u\n", timestamp, lux, prox);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SI1182_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (si1182_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("Logging Si1182 ALS and proximity data to %s (Ctrl+C to stop)\n", LOG_FILE);

    while (g_running) {
        uint16_t lux = 0, prox = 0;

        if (si1182_read_als(g_i2c_fd, &lux) < 0) {
            fprintf(stderr, "ALS read error — continuing\n");
        } else if (si1182_read_ps(g_i2c_fd, &prox) < 0) {
            fprintf(stderr, "Proximity read error — continuing\n");
        } else {
            log_data(g_log_fp, lux, prox);
        }

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (g_log_fp)  fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

