#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1145_ADDR 0x60

#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_PS_LED21_SELECT 0x0F
#define SI1145_REG_PS1_DATA0 0x10
#define SI1145_REG_PS1_DATA1 0x11
#define SI1145_REG_COMMAND 0x18

#define SI1145_CMD_PS_FORCE 0x05
#define SI1145_CMD_RESET 0x01

#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int read_proximity(int handle, uint16_t *proximity) {
    uint8_t data0, data1;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (write_register(handle, SI1145_REG_COMMAND, SI1145_CMD_PS_FORCE) < 0) {
            retries++;
            gpioDelay(10000);
            continue;
        }

        gpioDelay(10000);

        if (read_register(handle, SI1145_REG_PS1_DATA0, &data0) < 0) {
            retries++;
            gpioDelay(10000);
            continue;
        }

        if (read_register(handle, SI1145_REG_PS1_DATA1, &data1) < 0) {
            retries++;
            gpioDelay(10000);
            continue;
        }

        *proximity = ((uint16_t)data1 << 8) | data0;
        return 0;
    }

    fprintf(stderr, "Failed to read proximity after %d retries.\n", MAX_RETRIES);
    return -1;
}

static int log_data(FILE *fp, uint16_t proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, %u\n", timestamp, proximity) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static int log_error(FILE *fp, const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, ERROR: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error writing error to log file.\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static int init_si1145(int handle) {
    uint8_t part_id;

    if (write_register(handle, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) {
        fprintf(stderr, "Error resetting Si1145.\n");
        return -1;
    }
    gpioDelay(10000);

    if (read_register(handle, SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error reading Part ID.\n");
        return -1;
    }

    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x45).\n", part_id);
        return -1;
    }

    if (write_register(handle, SI1145_REG_HW_KEY, 0x17) < 0) return -1;
    if (write_register(handle, SI1145_REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (write_register(handle, SI1145_REG_PS_LED21_SELECT, 0x03) < 0) return -1;

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_si1145(i2c_handle) < 0) {
        fprintf(stderr, "Si1145 initialisation failed.\n");
        cleanup();
        return 1;
    }

    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers.\n");
        cleanup();
        return 1;
    }

    printf("Si1145 proximity logger started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t proximity;

        if (read_proximity(i2c_handle, &proximity) == 0) {
            if (log_data(log_file, proximity) < 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            log_error(log_file, "Failed to read proximity data.");
        }

        gpioDelay(100000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

