        if (!g_running) {
            break;
        }

        if (g_echo_state != 2) {
            fprintf(stderr, "Warning: echo timeout (no valid pulse received).\n");
            gpioWrite(BUZZER_PIN, 0);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        uint32_t pulse_us = g_end_tick - g_start_tick;
        double distance = calculate_distance_cm(pulse_us);

        printf("Distance: %7.2f cm  |  Buzzer: %s\n",
               distance, (distance < DISTANCE_THRESHOLD_CM) ? "ON" : "OFF");

        if (gpioWrite(BUZZER_PIN, (distance < DISTANCE_THRESHOLD_CM) ? 1 : 0) != 0) {
            fprintf(stderr, "Error: failed to write BUZZER_PIN %d.\n", BUZZER_PIN);
            break;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioTerminate();

    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

