#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN    17
#define SERVO_PIN   18

#define MAX_DISTANCE_CM 200.0
#define MIN_DISTANCE_CM 20.0
#define MAX_PULSE_US    2500
#define MIN_PULSE_US    500
#define ECHO_TIMEOUT_US 30000
#define SAMPLE_PERIOD_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static float measure_distance(void) {
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1.0;
    gpioDelay(2);
    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -1.0;
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1.0;

    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - timeout_start > ECHO_TIMEOUT_US) return -1.0;
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > ECHO_TIMEOUT_US) return -1.0;
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    return (float)diff / 58.0;
}

static int set_servo_angle(float distance) {
    if (distance < 0.0) return -1;
    float angle = 0.0;
    if (distance >= MAX_DISTANCE_CM) angle = 0.0;
    else if (distance <= MIN_DISTANCE_CM) angle = 180.0;
    else {
        angle = (MAX_DISTANCE_CM - distance) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM) * 180.0;
    }
    int pulse = (int)(MIN_PULSE_US + (angle / 180.0) * (MAX_PULSE_US - MIN_PULSE_US));
    if (gpioServo(SERVO_PIN, pulse) < 0) return -1;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ECHO_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        float distance = measure_distance();
        if (distance < 0.0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        printf("Distance: %.2f cm\n", distance);
        if (set_servo_angle(distance) < 0) {
            fprintf(stderr, "Servo set error\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

