    char reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    char data[2];

    if (i2cWriteDevice(handle, reg_buf, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;
    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/*  VL53L1X driver                                                     */
/* ------------------------------------------------------------------ */

static int vl53l1x_init(int handle)
{
    uint16_t model_id = 0;

    /* Soft reset */
    if (i2c_write16(handle, VL53L1X_REG_SOFT_RESET, 0x0001) < 0) {
        fprintf(stderr, "VL53L1X: soft-reset write failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Verify model ID */
    if (i2c_read16(handle, VL53L1X_REG_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "VL53L1X: failed to read model ID\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID_EXPECTED) {
        fprintf(stderr, "VL53L1X: unexpected model ID 0x%04X (expected 0x%04X)\n",
                model_id, VL53L1X_MODEL_ID_EXPECTED);
        return -1;
    }

    /* Timing budget ~33 ms (0x006B = 0x0000) */
    if (i2c_write16(handle, VL53L1X_REG_SYSTEM_INTERMEASUREMENT, 0x0000) < 0)
        return -1;
    if (i2c_write16(handle, VL53L1X_REG_RANGE_CONFIG_A, 0x0000) < 0)
        return -1;
    if (i2c_write16(handle, VL53L1X_REG_RANGE_CONFIG_B, 0x0000) < 0)
        return -1;

    /* Clear any pending interrupt */
    if (i2c_write16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x0001) < 0)
        return -1;

    /* Enable new sample ready interrupt */
    if (i2c_write16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG, 0x0040) < 0)
        return -1;

    return 0;
}

static int vl53l1x_start_ranging(int handle)
{
    return i2c_write16(handle, VL53L1X_REG_SYSTEM_RANGE_START, 0x0001);
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint16_t status = 0;

    /* Poll the interrupt status register for a new sample */
    for (int i = 0; i < 100; i++) {
        if (i2c_read16(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, &status) < 0)
            return -1;
        if (status & 0x0001)
            break;
        gpioDelay(1000); /* 1 ms */
    }
    if (!(status & 0x0001))
        return -1; /* timeout */

    if (i2c_read16(handle, VL53L1X_REG_RESULT_DISTANCE, distance_mm) < 0)
        return -1;

    /* Clear the interrupt so the next sample can be flagged */
    if (i2c_write16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x0001) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/*  Gate control                                                       */
/* ------------------------------------------------------------------ */

static void set_gate_pulse(int gpio, int pulse_us)
{
    if (gpioPWM(gpio, pulse_us) < 0)
        fprintf(stderr, "Warning: gpioPWM failed on GPIO %d\n", gpio);
}

static void log_event(const char *event)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[64];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file);
    }
    printf("%s: %s\n", timestamp, event);
}

/* ------------------------------------------------------------------ */
/*  Signal handling & cleanup                                          */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioPWM(GATE_GPIO, 0);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/*  Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    int gate_state = 0;          /* 0 = closed, 1 = open */
    int pulse_target = GATE_CLOSED_US;
    int pulse_current = GATE_CLOSED_US;
    int transition_step = 0;
    int step_delay_us = (GATE_TRANSITION * 1000) / 10; /* 10 steps */

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (vl53l1x_start_ranging(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X start ranging failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("gate_log.txt", "a");
    if (!log_file)
        fprintf(stderr, "Warning: could not open gate_log.txt; logging to console only\n");

    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    set_gate_pulse(GATE_GPIO, pulse_current);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Gate control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t distance = 0;

        if (vl53l1x_read_distance(i2c_handle, &distance) < 0) {
            fprintf(stderr, "I2C read error; retrying...\n");
            gpioDelay(100000); /* 100 ms back-off */
            continue;
        }

        printf("Distance: %u mm\n", distance);

        if (distance < DISTANCE_CLOSE_MM && gate_state == 0) {
            gate_state = 1;
            pulse_target = GATE_OPEN_US;
            log_event("Gate opened");
        } else if (distance > DISTANCE_FAR_MM && gate_state == 1) {
            gate_state = 0;
            pulse_target = GATE_CLOSED_US;
            log_event("Gate closed");
        }

        /* Smoothly transition the PWM pulse width */
        if (pulse_current != pulse_target) {
            if (transition_step == 0) {
                transition_step = 1;
                step_delay_us = (GATE_TRANSITION * 1000) / 10;
            }
            if (pulse_current < pulse_target) {
                pulse_current += (pulse_target - pulse_current) / 10;
                if (pulse_current > pulse_target)
                    pulse_current = pulse_target;
            } else {
                pulse_current -= (pulse_current - pulse_target) / 10;
                if (pulse_current < pulse_target)
                    pulse_current = pulse_target;
            }
            set_gate_pulse(GATE_GPIO, pulse_current);
        }

        gpioDelay(50000); /* 50 ms poll interval */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

