#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define MIN_ANGLE       0
#define MAX_ANGLE       180
#define MIN_PULSE_US    500
#define MAX_PULSE_US    2500

#define TIMEOUT_US 50000
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static double measure_distance(void) {
    uint32_t start_tick, end_tick;

    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0;
    }

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - start_tick) > TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    double distance = (double)diff / 58.0;
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range\n", distance);
        return -1.0;
    }
    return distance;
}

static int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: angle %d out of range [%d, %d]\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    int pulse = MIN_PULSE_US + (angle * (MAX_PULSE_US - MIN_PULSE_US) / MAX_ANGLE);
    if (gpioServo(SERVO_PIN, pulse) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse %d\n", pulse);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set servo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Ultrasonic distance measurement and servo control started.\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance();
        if (distance < 0.0) {
            fprintf(stderr, "Error: distance measurement failed\n");
        } else {
            int angle;
            if (distance < 20.0) {
                angle = MIN_ANGLE;
            } else if (distance > 200.0) {
                angle = MAX_ANGLE;
            } else {
                angle = (int)((distance - 20.0) * (MAX_ANGLE - MIN_ANGLE) / (200.0 - 20.0));
            }
            if (set_servo_angle(angle) < 0) {
                fprintf(stderr, "Error: failed to set servo angle\n");
            } else {
                printf("Distance: %.2f cm, Angle: %d\n", distance, angle);
            }
        }
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    set_servo_angle(0);
    gpioDelay(500000);
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

