        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, SI7005_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI7005_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int init_sensor(int fd)
{
    if (i2c_write_byte(fd, SI7005_RESET, 0x00) < 0)
        return -1;
    usleep(15000);
    if (i2c_write_byte(fd, SI7005_CONFIG, 0x00) < 0)
        return -1;
    usleep(10000);
    return 0;
}

static int read_sensor(int fd, float *temperature, float *humidity)
{
    uint8_t buf[2];

    if (i2c_write_byte(fd, SI7005_CONFIG, 0x00) < 0)
        return -1;
    usleep(10000);

    if (i2c_write_byte(fd, SI7005_TEMP, 0x00) < 0)
        return -1;
    usleep(10000);

    if (i2c_read_bytes(fd, SI7005_TEMP, buf, 2) < 0)
        return -1;
    uint16_t raw_temp = ((uint16_t)buf[0] << 8) | buf[1];
    *temperature = (165.0f * (float)raw_temp / 65536.0f) - 40.0f;

    if (i2c_write_byte(fd, SI7005_CONFIG, 0x00) < 0)
        return -1;
    usleep(10000);

    if (i2c_write_byte(fd, SI7005_HUMID, 0x00) < 0)
        return -1;
    usleep(10000);

    if (i2c_read_bytes(fd, SI7005_HUMID, buf, 2) < 0)
        return -1;
    uint16_t raw_humid = ((uint16_t)buf[0] << 8) | buf[1];
    *humidity = (100.0f * (float)raw_humid / 65536.0f);

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    g_fd = open_i2c();
    if (g_fd < 0)
        return 1;

    if (init_sensor(g_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(g_fd);
        g_fd = -1;
        return 1;
    }

    while (g_running) {
        float temperature, humidity;

        if (read_sensor(g_fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Read failed, re-initializing I2C bus.\n");
            close(g_fd);
            g_fd = -1;
            usleep(500000);
            g_fd = open_i2c();
            if (g_fd < 0) {
                fprintf(stderr, "Failed to re-open I2C bus.\n");
                break;
            }
            if (init_sensor(g_fd) < 0) {
                fprintf(stderr, "Sensor re-initialization failed.\n");
                close(g_fd);
                g_fd = -1;
                break;
            }
        }

        for (int i = 0; i < 10 && g_running; i++)
            usleep(200000);
    }

    if (g_fd >= 0) {
        close(g_fd);
        g_fd = -1;
    }
    printf("\nExiting gracefully.\n");
    return 0;
}

