#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 register addresses */
#define MPU6050_WHO_AM_I   0x75
#define MPU6050_WHO_AM_I_VAL 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_SMPLRT_DIV 0x19
#define MPU6050_CONFIG     0x1A
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_XOUT_H 0x3B

/* Expected sample rate: 1 kHz / (1 + 7) = 125 Hz */
#define SAMPLE_RATE_DIVISOR 7
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int mpu6050_init(int handle)
{
    /* Wake up the device (clear SLEEP bit) */
    if (i2cWriteByteData(handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle */

    /* Sample rate divider: 1 kHz / (1 + 7) = 125 Hz */
    if (i2cWriteByteData(handle, MPU6050_SMPLRT_DIV, SAMPLE_RATE_DIVISOR) < 0) {
        fprintf(stderr, "Error: failed to write SMPLRT_DIV\n");
        return -1;
    }

    /* DLPF config: 1 kHz internal, 44 Hz bandwidth, 42 Hz delay */
    if (i2cWriteByteData(handle, MPU6050_CONFIG, 0x03) < 0) {
        fprintf(stderr, "Error: failed to write CONFIG\n");
        return -1;
    }

    /* Gyro full scale ±250 °/s (FS_SEL = 0) */
    if (i2cWriteByteData(handle, MPU6050_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write GYRO_CONFIG\n");
        return -1;
    }

    /* Accel full scale ±2 g (AFS_SEL = 0) */
    if (i2cWriteByteData(handle, MPU6050_ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write ACCEL_CONFIG\n");
        return -1;
    }

    return 0;
}

static int mpu6050_read_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                             int16_t *gx, int16_t *gy, int16_t *gz, int16_t *temp)
{
    char buf[14];

    /* Burst read 14 bytes starting at ACCEL_XOUT_H (0x3B) */
    if (i2cReadI2CBlockData(handle, MPU6050_ACCEL_XOUT_H, buf, 14) != 14) {
        fprintf(stderr, "Error: failed to read 14-byte data block\n");
        return -1;
    }

    /* Accelerometer: big-endian, registers 0x3B–0x40 */
    *ax = (int16_t)((buf[0]  << 8) | (uint8_t)buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | (uint8_t)buf[3]);
    *az = (int16_t)((buf[4]  << 8) | (uint8_t)buf[5]);

    /* Temperature: big-endian, registers 0x41–0x42 */
    *temp = (int16_t)((buf[6]  << 8) | (uint8_t)buf[7]);

    /* Gyroscope: big-endian, registers 0x43–0x48 */
    *gx = (int16_t)((buf[8]  << 8) | (uint8_t)buf[9]);
    *gy = (int16_t)((buf[10] << 8) | (uint8_t)buf[11]);
    *gz = (int16_t)((buf[12] << 8) | (uint8_t)buf[13]);

    return 0;
}

int main(void)
{
    int16_t ax, ay, az, gx, gy, gz, temp;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the MPU-6050 address */
    g_i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device at 0x%02X (err=%d)\n",
                MPU6050_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor identity */
    int who = i2cReadByteData(g_i2c_handle, MPU6050_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register\n");
        goto cleanup_fail;
    }
    if (who != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, MPU6050_WHO_AM_I_VAL);
        goto cleanup_fail;
    }

    /* Initialize sensor */
    if (mpu6050_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialization failed\n");
        goto cleanup_fail;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPU-6050 initialized. Logging data every 100 ms (Ctrl+C to stop)...\n");
    fflush(stdout);

    while (g_running) {
        if (mpu6050_read_data(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz, &temp) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  Gyro: X=%6d Y=%6d Z=%6d  Temp=%6d\n",
                   ax, ay, az, gx, gy, gz, temp);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: read error, continuing...\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;

cleanup_fail:
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_FAILURE;
}

