code:
/*
 * SHT40 temperature & humidity logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SHT40 VDD  -> Pi 3V3  (pin 1)
 *   SHT40 GND  -> Pi GND  (pin 9)
 *   SHT40 SDA  -> Pi GPIO2 / I2C1 SDA (pin 3)
 *   SHT40 SCL  -> Pi GPIO3 / I2C1 SCL (pin 5)
 *
 * Build:  gcc -O2 -Wall -Wextra -o sht40_logger sht40_logger.c -lpigpio -lrt
 * Run:    sudo ./sht40_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- SHT40 constants (per datasheet) ---- */
#define SHT40_ADDR             0x2A   /* default I2C address */
#define SHT40_CMD_MEASURE_HP   0xFD   /* high-repeatability, clock stretching */
#define SHT40_MEASURE_DELAY_US 10000  /* 10 ms worst-case conversion time */
#define SHT40_DATA_LEN         6      /* T_MSB T_LSB T_CRC RH_MSB RH_LSB RH_CRC */
#define SHT40_CRC_POLY         0x31   /* x^8 + x^5 + x^4 + 1 */
#define SHT40_CRC_INIT         0xFF

/* ---- Globals for signal-driven cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 as used by Sensirion / SHT40: poly 0x31, init 0xFF, no final XOR */
static uint8_t sht40_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = SHT40_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ SHT40_CRC_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Open (or reopen) the I2C bus to the SHT40. Returns 0 on success.     */
static int open_i2c(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    g_i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (pigpio code %d)\n",
                g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one high-repeatability sample from the SHT40.                  */
/* Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.          */
static int read_sht40(float *temperature, float *humidity)
{
    uint8_t cmd = SHT40_CMD_MEASURE_HP;
    uint8_t buf[SHT40_DATA_LEN];

    /* Send the measurement command (single-byte write). */
    if (i2cWriteDevice(g_i2c_handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (cmd 0x%02X) failed\n", cmd);
        return -1;
    }

    /* Wait for the conversion to complete. */
    gpioDelay(SHT40_MEASURE_DELAY_US);

    /* Read the 6-byte result: T_MSB T_LSB T_CRC RH_MSB RH_LSB RH_CRC */
    if (i2cReadDevice(g_i2c_handle, (char *)buf, SHT40_DATA_LEN) != SHT40_DATA_LEN) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed\n");
        return -1;
    }

    /* Validate CRCs. */
    if (sht40_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] temperature CRC mismatch (calc=0x%02X got=0x%02X)\n",
                sht40_crc8(&buf[0], 2), buf[2]);
        return -2;
    }
    if (sht40_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] humidity CRC mismatch (calc=0x%02X got=0x%02X)\n",
                sht40_crc8(&buf[3], 2), buf[5]);
        return -2;
    }

    /* Convert raw values to physical units. */
    uint16_t t_raw = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t rh_raw = (uint16_t)((buf[3] << 8) | buf[4]);

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)rh_raw / 65535.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus to the SHT40. */
    if (open_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SHT40 logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature, humidity;

        int rc = read_sht40(&temperature, &humidity);
        if (rc == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed (code %d); re-opening I2C.\n",
                    rc);
            if (open_i2c() != 0) {
                fprintf(stderr, "[WARN] Re-open failed; will retry next cycle.\n");
            }
        }

        /* Sleep 5 s, but wake early on signal. */
        for (int i = 0; i < 50 && g_running; i++)
            gpioDelay(100000); /* 100 ms */
    }

    /* ---- Cleanup ---- */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

