#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define ERROR_TEMP -273.15f
#define LOG_FILE "temperature_log.csv"
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, float *out_temp) {
    uint8_t buf[3];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 3) != 3) return -1;
    int16_t raw = (int16_t)((buf[1] << 8) | buf[0]);
    *out_temp = (float)raw * 0.02f - 273.15f;
    return 0;
}

static int log_temperature(float ambient, float object) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    if (fprintf(log_fp, "%s,%.2f,%.2f\n", ts, ambient, object) < 0) return -1;
    fflush(log_fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float ambient = ERROR_TEMP, object = ERROR_TEMP;
        int err = 0;

        if (i2c_read_reg16(i2c_fd, AMBIENT_TEMP_REG, &ambient) != 0) {
            fprintf(stderr, "Error reading ambient temperature\n");
            err = 1;
        }
        if (i2c_read_reg16(i2c_fd, OBJECT_TEMP_REG, &object) != 0) {
            fprintf(stderr, "Error reading object temperature\n");
            err = 1;
        }

        if (ambient <= -273.0f || object <= -273.0f) {
            fprintf(stderr, "Invalid temperature reading (ambient=%.2f, object=%.2f)\n", ambient, object);
            err = 1;
        }

        if (!err) {
            if (log_temperature(ambient, object) != 0) {
                fprintf(stderr, "Error writing to log file\n");
            }
        }

        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

