/*
 * STS30-DIS temperature logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   STS30-DIS VDD  -> Pi 3V3  (pin 1)
 *   STS30-DIS GND  -> Pi GND  (pin 9)
 *   STS30-DIS SDA  -> Pi GPIO2 / I2C1 SDA (pin 3)
 *   STS30-DIS SCL  -> Pi GPIO3 / I2C1 SCL (pin 5)
 *
 * Build:  gcc -O2 -Wall -Wextra -o sts30_logger sts30_logger.c -lpigpio -lrt
 * Run:    sudo ./sts30_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- STS30-DIS constants (Sensirion datasheet) ---- */
#define STS30_I2C_ADDR          0x4A
#define STS30_CMD_MEAS_HIGHREP  0x2400  /* single-shot, clock stretching, T+RH */
#define STS30_CMD_MEAS_HIGHREP_T 0x2403 /* single-shot, clock stretching, T only */
#define STS30_CMD_READ_MEAS     0x0000  /* read measurement result */
#define STS30_CMD_RESET         0x30A2
#define STS30_CMD_GET_ID        0x3001
#define STS30_MEAS_DELAY_US     20000   /* 20 ms for high-repeatability T-only */
#define STS30_RESET_DELAY_US    15000   /* 15 ms after reset */

/* ---- Application constants ---- */
#define I2C_BUS                 1
#define LOG_FILE                "enclosure_temp_log.txt"
#define ERROR_LOG_FILE          "error_log.txt"
#define SAMPLE_INTERVAL_S       5
#define MAX_RETRIES             3

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit command to the STS30 (big-endian on the wire).       */
/* ------------------------------------------------------------------ */
static int sts30_write_cmd(int handle, uint16_t cmd)
{
    char buf[2] = { (char)(cmd >> 8), (char)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read `len` bytes from the STS30.                                    */
/* ------------------------------------------------------------------ */
static int sts30_read(int handle, char *buf, int len)
{
    if (i2cReadDevice(handle, buf, len) != len) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Reset the sensor to a known state.                                  */
/* ------------------------------------------------------------------ */
static int sts30_reset(int handle)
{
    if (sts30_write_cmd(handle, STS30_CMD_RESET) != 0) {
        return -1;
    }
    gpioDelay(STS30_RESET_DELAY_US);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the 9-byte device ID (optional; used for presence check).      */
/* ------------------------------------------------------------------ */
static int sts30_check_present(int handle)
{
    if (sts30_write_cmd(handle, STS30_CMD_GET_ID) != 0) {
        return -1;
    }
    gpioDelay(10000); /* 10 ms for ID measurement */
    char id[9];
    if (sts30_read(handle, id, sizeof(id)) != 0) {
        return -1;
    }
    /* STS30-DIS device ID bytes: 0x00 0x13 0x30 0x01 0x00 0x00 0x00 0x00 0x00 */
    if ((uint8_t)id[0] != 0x00 || (uint8_t)id[1] != 0x13 || (uint8_t)id[2] != 0x30) {
        return -1; /* not an STS30-DIS */
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a single-shot T-only measurement and read back the result.  */
/* Returns 0 on success and stores temperature in *temp_c.             */
/* ------------------------------------------------------------------ */
static int sts30_read_temperature(int handle, float *temp_c)
{
    if (sts30_write_cmd(handle, STS30_CMD_MEAS_HIGHREP_T) != 0) {
        return -1;
    }

    gpioDelay(STS30_MEAS_DELAY_US);

    /* Read 3 bytes: T_MSB, T_LSB, T_CRC */
    char data[3];
    if (sts30_read(handle, data, sizeof(data)) != 0) {
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    *temp_c = -45.0f + (175.0f * (float)raw / 65535.0f);
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("fopen(error_log.txt)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
static void log_temperature(float temp_c)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(enclosure_temp_log.txt)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] Temperature: %.2f C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp_c);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, STS30_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (addr 0x%02X): %d\n", STS30_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Presence check */
    if (sts30_check_present(g_i2c_handle) != 0) {
        fprintf(stderr, "STS30-DIS not detected at 0x%02X\n", STS30_I2C_ADDR);
        log_error("Sensor not detected (no ACK or wrong ID)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Reset to a known state */
    if (sts30_reset(g_i2c_handle) != 0) {
        fprintf(stderr, "Warning: sensor reset failed\n");
        log_error("Sensor reset failed");
    }

    printf("STS30-DIS logger started. Logging to %s every %d s. Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);

    while (g_running) {
        float temp_c = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (sts30_read_temperature(g_i2c_handle, &temp_c) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(100000); /* 100 ms backoff before retry */
        }

        if (ok) {
            log_temperature(temp_c);
            printf("Temperature: %.2f C\n", temp_c);
        } else {
            log_error("Failed to read temperature after retries");
            fprintf(stderr, "Temperature read failed after %d attempts\n", MAX_RETRIES);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

