    /* Read 3 bytes: T_MSB, T_LSB, T_CRC */
    char data[3];
    if (sts30_read(handle, data, sizeof(data)) != 0) {
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    *temp_c = -45.0f + (175.0f * (float)raw / 65535.0f);
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("fopen(error_log.txt)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
static void log_temperature(float temp_c)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(enclosure_temp_log.txt)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] Temperature: %.2f C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp_c);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, STS30_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (addr 0x%02X): %d\n", STS30_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Presence check */
    if (sts30_check_present(g_i2c_handle) != 0) {
        fprintf(stderr, "STS30-DIS not detected at 0x%02X\n", STS30_I2C_ADDR);
        log_error("Sensor not detected (no ACK or wrong ID)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Reset to a known state */
    if (sts30_reset(g_i2c_handle) != 0) {
        fprintf(stderr, "Warning: sensor reset failed\n");
        log_error("Sensor reset failed");
    }

    printf("STS30-DIS logger started. Logging to %s every %d s. Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);

    while (g_running) {
        float temp_c = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (sts30_read_temperature(g_i2c_handle, &temp_c) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(100000); /* 100 ms backoff before retry */
        }

        if (ok) {
            log_temperature(temp_c);
            printf("Temperature: %.2f C\n", temp_c);
        } else {
            log_error("Failed to read temperature after retries");
            fprintf(stderr, "Temperature read failed after %d attempts\n", MAX_RETRIES);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

