/*
 * SDP810-125Pa differential pressure sensor logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP810 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810_logger sdp810_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS            1
#define SDP810_ADDR        0x25          /* documented I2C address */
#define LOG_FILE           "pressure_log.csv"
#define SAMPLE_PERIOD_US   1000000       /* 1 second */
#define MEAS_DELAY_US      2000          /* 2 ms measurement wait */
#define MAX_RETRIES        3

/* SDP810 continuous measurement command (no averaging, no clock stretching) */
static const uint8_t CMD_CONT_MEAS[2] = {0x36, 0x2F};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)               */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read one 9-byte measurement frame from the SDP810                  */
/* ------------------------------------------------------------------ */
static int read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t buf[9];

    /* Send continuous measurement command */
    if (i2cWriteDevice(handle, (char *)CMD_CONT_MEAS, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed\n");
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(MEAS_DELAY_US);

    /* Read 9 bytes: pressure(2)+crc, temperature(2)+crc, scale(2)+crc */
    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed (sensor absent or bus error)\n");
        return -1;
    }

    /* Validate CRCs */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[ERROR] scale factor CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_factor = (int16_t)((buf[6] << 8) | buf[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "[ERROR] invalid scale factor (0)\n");
        return -1;
    }

    /* Convert raw values using the scale factor */
    *pressure    = (float)raw_pressure    / (float)scale_factor;
    *temperature = (float)raw_temp        / (float)scale_factor;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a CSV row; create header if file is new                     */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, float pressure, float temperature)
{
    FILE *fp = fopen(filename, "a+");
    if (!fp) {
        perror("[ERROR] fopen");
        return -1;
    }

    /* Check if file is empty -> write header */
    if (fseek(fp, 0, SEEK_END) != 0) {
        perror("[ERROR] fseek");
        fclose(fp);
        return -1;
    }
    long fsize = ftell(fp);
    if (fsize < 0) {
        perror("[ERROR] ftell");
        fclose(fp);
        return -1;
    }
    if (fsize == 0) {
        fprintf(fp, "timestamp,pressure_pa,temperature_c\n");
    }

    /* Seek back to end for append */
    if (fseek(fp, 0, SEEK_END) != 0) {
        perror("[ERROR] fseek");
        fclose(fp);
        return -1;
    }

    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);

    if (fclose(fp) != 0) {
        perror("[ERROR] fclose");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C device */
    int handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (handle=%d) — sensor may be absent\n", handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SDP810 logger started. Logging to %s every 1 s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    int consecutive_errors = 0;

    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;

        if (read_sdp810(handle, &pressure, &temperature) == 0) {
            consecutive_errors = 0;
            if (log_data(LOG_FILE, pressure, temperature) != 0) {
                fprintf(stderr, "[WARN] logging failed\n");
            } else {
                printf("%s  P=%.2f Pa  T=%.2f °C\n",
                       __TIME__, pressure, temperature);
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "[WARN] read failed (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "[ERROR] %d consecutive failures — aborting\n",
                        consecutive_errors);
                break;
            }
        }

        /* Sleep 1 s in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    /* Clean shutdown */
    if (i2cClose(handle) != 0) {
        fprintf(stderr, "[WARN] i2cClose failed\n");
    }
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

