#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHT40_ADDR     0x2A
#define MEASURE_CMD    0xFD
#define LOG_FILE       "sht40_log.txt"
#define SAMPLE_PERIOD  5

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Sensirion CRC-8: polynomial 0x31, init 0xFF, no final XOR */
static uint8_t sht40_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static int sht40_read(int fd, float *temp, float *hum)
{
    uint8_t cmd = MEASURE_CMD;
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        perror("write measurement command");
        return -1;
    }

    usleep(10000); /* SHT40 high-repeatability measurement: max 8.5 ms */

    uint8_t buf[6];
    ssize_t r = read(fd, buf, sizeof(buf));
    if (r != (ssize_t)sizeof(buf)) {
        perror("read measurement data");
        return -1;
    }

    if (sht40_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (sht40_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *hum  = 100.0f * (float)h_raw / 65535.0f;
    return 0;
}

static void log_data(FILE *fp, float temp, float hum)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", ts, temp, hum);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen " LOG_FILE);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("SHT40 logging started on %s (addr 0x%02X). Press Ctrl+C to stop.\n",
           I2C_BUS, SHT40_ADDR);

    while (g_running) {
        float temp, hum;
        if (sht40_read(g_i2c_fd, &temp, &hum) == 0) {
            log_data(g_log_fp, temp, hum);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }
        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly.\n");
    if (g_log_fp)  fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return EXIT_SUCCESS;
}

