        rc = i2cWriteByte(handle, cmd);
        if (rc == 0) break;
        fprintf(stderr, "Warning: i2cWriteByte(0x%02X) failed (attempt %d/%d): %s\n",
                cmd, retries + 1, MAX_RETRIES, strerror(errno));
        gpioDelay(10000);
