        fprintf(stderr, "Error: failed to write measurement command 0x%02X after %d retries.\n", cmd, MAX_RETRIES);
        return -1;
    }

    gpioDelay(MEASUREMENT_TIMEOUT_MS * 1000);

    for (retries = 0; retries < MAX_RETRIES; retries++) {
        rc = i2cReadDevice(handle, buf, 2);
        if (rc == 2) break;
        fprintf(stderr, "Warning: i2cReadDevice returned %d (attempt %d/%d): %s\n",
                rc, retries + 1, MAX_RETRIES, strerror(errno));
        gpioDelay(10000);
