    printf("Logging to %s every %d seconds. Press Ctrl+C to exit.\n", LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (g_running) {
        float temp, hum;

        if (read_measurement(g_i2c_handle, CMD_MEASURE_TEMP_NOHOLD, &temp, convert_temperature) != 0) {
            fprintf(stderr, "Error: temperature read failed; continuing.\n");
        } else if (read_measurement(g_i2c_handle, CMD_MEASURE_HUM_NOHOLD, &hum, convert_humidity) != 0) {
            fprintf(stderr, "Error: humidity read failed; continuing.\n");
        } else {
            log_data(temp, hum);
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

