        return 1;
    }

    err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!err_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", ERROR_LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("STS30 temperature logger started. Press Ctrl+C to stop.\n");

