#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define FAN_GPIO       18
#define TEMP_THRESHOLD_HIGH 28.0f
#define TEMP_THRESHOLD_LOW  27.0f
#define BUFFER_SIZE    60
#define RETRY_COUNT    3
#define RETRY_DELAY_US 10000
#define READ_DELAY_US  10000
#define SAMPLE_PERIOD_S 2

#define CMD_MEASURE_TEMP_HOLD  0xE3
#define CMD_RESET              0xFE
#define CMD_READ_ID_1          0xFA
#define CMD_READ_ID_2          0x0F
#define CMD_READ_ID_3          0x00

typedef struct {
    float temperature;
    time_t timestamp;
} Reading;

static Reading buffer[BUFFER_SIZE];
static int    buffer_index = 0;
static int    buffer_count = 0;
static int    i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int handle, uint8_t cmd) {
    char buf[1] = { (char)cmd };
    return i2cWriteDevice(handle, buf, 1);
}

static int i2c_read_bytes(int handle, uint8_t *buf, uint32_t len) {
    return i2cReadDevice(handle, (char *)buf, len);
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }

    if (i2c_write_cmd(i2c_handle, CMD_RESET) < 0) {
        fprintf(stderr, "Warning: Si7021 reset failed (sensor may be absent)\n");
    }
    gpioDelay(15000);

    uint8_t id[8];
    if (i2c_write_cmd(i2c_handle, CMD_READ_ID_1) < 0) {
        fprintf(stderr, "Warning: Si7021 ID read failed\n");
        return 0;
    }
    if (i2c_write_cmd(i2c_handle, CMD_READ_ID_2) < 0) {
        fprintf(stderr, "Warning: Si7021 ID read failed\n");
        return 0;
    }
    if (i2c_read_bytes(i2c_handle, id, 8) != 8) {
        fprintf(stderr, "Warning: Si7021 ID read failed\n");
        return 0;
    }
    printf("Si7021 detected (ID bytes: 0x%02X 0x%02X 0x%02X 0x%02X 0x%02X 0x%02X 0x%02X 0x%02X)\n",
           id[0], id[1], id[2], id[3], id[4], id[5], id[6], id[7]);
    return 0;
}

static int read_temperature(float *temperature) {
    uint8_t data[3];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2c_write_cmd(i2c_handle, CMD_MEASURE_TEMP_HOLD) < 0) {
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        gpioDelay(20000);

        int bytes = i2c_read_bytes(i2c_handle, data, 3);
        if (bytes == 3) {
            uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
            *temperature = (175.72f * raw / 65536.0f) - 46.85f;
            return 0;
        }
        retries--;
        gpioDelay(RETRY_DELAY_US);
    }
    fprintf(stderr, "Error reading temperature after %d retries\n", RETRY_COUNT);
    return -1;
}

static void add_reading(float temperature) {
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].timestamp   = time(NULL);
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void control_fan(float temperature) {
    static bool fan_on = false;
    if (temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1);
        fan_on = true;
        printf("Fan ON  (T=%.2f C)\n", temperature);
    } else if (temperature < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0);
        fan_on = false;
        printf("Fan OFF (T=%.2f C)\n", temperature);
    }
}

static void cleanup(void) {
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Si7021 fan controller started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("[%s] Temperature: %.2f C\n", ts, temperature);
            add_reading(temperature);
            control_fan(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Continuing...\n");
        }
        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

