#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define POLL_INTERVAL_SEC 5
#define FIRST_READ_DELAY_SEC 1

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int send_command(uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error sending command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

static int start_periodic_measurement(void) {
    return send_command(0x21B1);
}

static int stop_periodic_measurement(void) {
    return send_command(0x3F06);
}

static int read_data_ready_flag(int *data_ready) {
    if (send_command(0xE4B8) != 0) {
        return -1;
    }
    gpioDelay(10000);
    uint8_t buf[3];
    int result = i2cReadDevice(i2c_handle, (char *)buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading data ready flag: %d\n", result);
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on data ready flag\n");
        return -1;
    }
    uint16_t flag = ((uint16_t)buf[0] << 8) | buf[1];
    *data_ready = (flag & 0x07FF) != 0;
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    if (send_command(0xEC05) != 0) {
        return -1;
    }
    gpioDelay(10000);
    uint8_t buf[9];
    int result = i2cReadDevice(i2c_handle, (char *)buf, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on CO2 word\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch on temperature word\n");
        return -1;
    }
    if (crc8(buf + 6, 2) != buf[8]) {
        fprintf(stderr, "CRC mismatch on humidity word\n");
        return -1;
    }
    data->co2 = ((uint16_t)buf[0] << 8) | buf[1];
    data->temperature = ((uint16_t)buf[3] << 8) | buf[4];
    data->humidity = ((uint16_t)buf[6] << 8) | buf[7];
    return 0;
}

static void log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%u,%.2f,%.2f\n",
            timestamp,
            data->co2,
            (float)data->temperature / 100.0,
            (float)data->humidity / 1000.0);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        stop_periodic_measurement();
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, SCD40_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up SIGINT handler\n");
        cleanup();
        return 1;
    }
    if (start_periodic_measurement() != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        cleanup();
        return 1;
    }
    sleep(FIRST_READ_DELAY_SEC);
    while (!terminate) {
        int data_ready = 0;
        if (read_data_ready_flag(&data_ready) != 0) {
            fprintf(stderr, "Error reading data ready flag, retrying...\n");
            sleep(POLL_INTERVAL_SEC);
            continue;
        }
        if (data_ready) {
            sensor_data_t sensor_data;
            if (read_sensor_data(&sensor_data) == 0) {
                log_data(&sensor_data);
            } else {
                fprintf(stderr, "Error reading sensor data\n");
            }
        }
        sleep(POLL_INTERVAL_SEC);
    }
    cleanup();
    return 0;
}

