/*
 * SCD40 CO2 monitor for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   SCD40 SDA  -> GPIO2  (I2C bus 1 SDA, physical pin 3)
 *   SCD40 SCL  -> GPIO3  (I2C bus 1 SCL, physical pin 5)
 *   SCD40 VDD  -> 3.3 V
 *   SCD40 GND  -> GND
 *   LED anode  -> GPIO17 (BCM 17, physical pin 11) through 330 Ω resistor
 *   LED cathode-> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o scd40_monitor scd40_monitor.c -lpigpio -lrt
 * Run:    sudo ./scd40_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

/* ---- SCD40 constants (Sensirion SCD4x datasheet) ---- */
#define SCD40_I2C_ADDR          0x62
#define SCD40_CMD_START_PERIODIC 0x21B1
#define SCD40_CMD_READ_MEASUREMENT 0xEC05
#define SCD40_CMD_STOP_PERIODIC  0x3F06
#define SCD40_CMD_GET_DATA_READY 0xE4B8
#define SCD40_CMD_SOFT_RESET     0x3001

#define CO2_THRESHOLD_PPM       1000
#define LED_GPIO                17
#define BUFFER_SIZE             20
#define SAMPLE_INTERVAL_SEC     5
#define I2C_BUS                 1

/* ---- Data structure ---- */
typedef struct {
    time_t timestamp;
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
} sensor_data_t;

/* ---- Globals ---- */
static sensor_data_t circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ---- Prototypes ---- */
static uint8_t crc8(const uint8_t *data, int len);
static int  scd40_write_command(uint16_t cmd);
static int  scd40_read_measurement(uint16_t *co2, uint16_t *temp, uint16_t *rh);
static void add_to_buffer(uint16_t co2, uint16_t temp, uint16_t rh);
static void check_co2_threshold(uint16_t co2);
static void signal_handler(int sig);
static void cleanup(void);

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ---- Write a 16-bit command to the SCD40 ---- */
static int scd40_write_command(uint16_t cmd) {
    uint8_t buf[2];
    buf[0] = (uint8_t)(cmd >> 8);
    buf[1] = (uint8_t)(cmd & 0xFF);
    int rc = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "[SCD40] write command 0x%04X failed (rc=%d)\n", cmd, rc);
        return -1;
    }
    return 0;
}

/* ---- Read measurement: 9 bytes = 3 words + 3 CRCs ---- */
static int scd40_read_measurement(uint16_t *co2, uint16_t *temp, uint16_t *rh) {
    uint8_t buf[9];
    int rc = i2cReadDevice(i2c_handle, (char *)buf, 9);
    if (rc != 9) {
        fprintf(stderr, "[SCD40] read measurement failed (rc=%d)\n", rc);
        return -1;
    }

    /* Validate CRC for each 2-byte word */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[SCD40] CRC mismatch on CO2 word\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[SCD40] CRC mismatch on temperature word\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[SCD40] CRC mismatch on humidity word\n");
        return -1;
    }

    *co2  = (uint16_t)((buf[0] << 8) | buf[1]);
    *temp = (uint16_t)((buf[3] << 8) | buf[4]);
    *rh   = (uint16_t)((buf[6] << 8) | buf[7]);
    return 0;
}

/* ---- Circular buffer ---- */
static void add_to_buffer(uint16_t co2, uint16_t temp, uint16_t rh) {
    circular_buffer[buffer_index].timestamp  = time(NULL);
    circular_buffer[buffer_index].co2        = co2;
    circular_buffer[buffer_index].temperature = temp;
    circular_buffer[buffer_index].humidity   = rh;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

/* ---- CO2 threshold check ---- */
static void check_co2_threshold(uint16_t co2) {
    if (co2 > CO2_THRESHOLD_PPM) {
        gpioWrite(LED_GPIO, 1);
        printf("[ALERT] CO2 > %d ppm (%u ppm) — LED ON\n", CO2_THRESHOLD_PPM, co2);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* ---- Cleanup ---- */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        scd40_write_command(SCD40_CMD_STOP_PERIODIC);
        gpioDelay(500000); /* 500 ms */
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ---- Main ---- */
int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at SCD40 address */
    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X (rc=%d)\n",
                I2C_BUS, SCD40_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Soft reset */
    if (scd40_write_command(SCD40_CMD_SOFT_RESET) != 0) {
        fprintf(stderr, "Soft reset failed — sensor may be absent\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(20000); /* 20 ms */

    /* Start periodic measurement */
    if (scd40_write_command(SCD40_CMD_START_PERIODIC) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(10000); /* 10 ms */

    /* Configure LED GPIO */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SCD40 CO2 monitor started. Sampling every %d s. Ctrl+C to exit.\n",
           SAMPLE_INTERVAL_SEC);

    /* Main loop */
    while (!terminate) {
        uint16_t co2, temp, rh;

        if (scd40_read_measurement(&co2, &temp, &rh) == 0) {
            add_to_buffer(co2, temp, rh);
            printf("CO2: %u ppm | Temp: %.2f °C | RH: %.2f %%\n",
                   co2,
                   (double)temp / 100.0,
                   (double)rh / 1000.0);
            check_co2_threshold(co2);
        } else {
            fprintf(stderr, "Read failed — will retry next cycle\n");
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && !terminate; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

