#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define EDGE_TIMEOUT_US 50000
#define MAX_CONSECUTIVE_ERRORS 3
#define MIN_TEMP_C -40.0f
#define MAX_TEMP_C 150.0f

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int log_message(const char *msg) {
    if (!g_log_fp) return -1;
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) return -1;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(g_log_fp, "%s %s\n", ts, msg);
    fflush(g_log_fp);
    return 0;
}

static int wait_for_level(int level, uint32_t *out_us) {
    uint32_t start = gpioTick();
    while (gpioRead(GPIO_PIN) != level) {
        if (!g_running) return -1;
        if ((int)(gpioTick() - start) > EDGE_TIMEOUT_US) return -2;
    }
    *out_us = gpioTick();
    return 0;
}

static float read_temperature(void) {
    uint32_t t_rise, t_fall, t_rise2;
    int rc;

    rc = wait_for_level(0, &t_rise);
    if (rc != 0) return -1000.0f;

    rc = wait_for_level(1, &t_fall);
    if (rc != 0) return -1000.0f;

    rc = wait_for_level(0, &t_rise2);
    if (rc != 0) return -1000.0f;

    uint32_t cycle_us = t_rise2 - t_rise;
    uint32_t high_us  = t_fall - t_rise;

    if (cycle_us == 0) return -1000.0f;

    float duty = (float)high_us / (float)cycle_us;
    float temp = (duty - 0.5f) * 100.0f;
    return temp;
}

static void log_temperature(float temp) {
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) return;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(g_log_fp, "%s Temperature: %.2f C\n", ts, temp);
    fflush(g_log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int consecutive_errors = 0;

    while (g_running) {
        float temp = read_temperature();

        if (temp > -999.0f) {
            consecutive_errors = 0;
            if (temp >= MIN_TEMP_C && temp <= MAX_TEMP_C) {
                log_temperature(temp);
            } else {
                char msg[128];
                snprintf(msg, sizeof(msg), "Temperature out of range: %.2f C", temp);
                log_message(msg);
            }
        } else {
            consecutive_errors++;
            log_message("Error reading temperature");
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_message("SENSOR MALFUNCTION");
                consecutive_errors = 0;
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

