/*
 * SDP810-125Pa differential pressure sensor reader for Raspberry Pi 3 B+.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP810 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow airflow.c
 *
 * The SDP810 uses the I2C address 0x25 (7-bit) and the continuous-read
 * command 0x36 0x2F.  A 9-byte response is returned:
 *   [p_msb p_lsb p_crc  t_msb t_lsb t_crc  s_msb s_lsb s_crc]
 * where p = pressure (Pa), t = temperature (°C), s = scale factor.
 * CRC-8: polynomial 0x31, initial value 0xFF, no final XOR.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x25
#define CSV_FILE       "airflow.csv"
#define SAMPLE_PERIOD  1           /* seconds between samples */
#define CONV_TIME_MS   45          /* max conversion time per datasheet */

/* Continuous measurement command (MSB, LSB) */
static const uint8_t CMD_CONT_MEAS[2] = { 0x36, 0x2F };

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)               */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int sdp810_read(int fd, float *pressure, float *temperature)
{
    uint8_t buf[9];

    if (i2c_write_cmd(fd, CMD_CONT_MEAS, sizeof(CMD_CONT_MEAS)) != 0)
        return -1;

    /* Wait for conversion to complete (max ~45 ms per datasheet) */
    usleep(CONV_TIME_MS * 1000);

    if (i2c_read_block(fd, buf, sizeof(buf)) != 0)
        return -1;

    /* Validate CRCs for each 2-byte data word */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on pressure word\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch on temperature word\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC mismatch on scale-factor word\n");
        return -1;
    }

    int16_t raw_p = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_t = (int16_t)((buf[3] << 8) | buf[4]);

    /* SDP810 conversion formulas (datasheet) */
    *pressure    = (float)raw_p / 240.0f;          /* Pa */
    *temperature = (float)raw_t / 200.0f;          /* °C */

    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_csv(const char *filename, float pressure, float temperature)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            pressure, temperature);

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s): %s\n", filename, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    g_i2c_fd = i2c_open(I2C_BUS, SDP810_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    printf("SDP810 airflow monitor started.  Logging to %s every %d s.\n",
           CSV_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float pressure, temperature;

        if (sdp810_read(g_i2c_fd, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa  |  Temperature: %.2f °C\n",
                   pressure, temperature);
            if (log_csv(CSV_FILE, pressure, temperature) != 0)
                fprintf(stderr, "Warning: CSV logging failed.\n");
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            usleep(100 * 1000);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        if (close(g_i2c_fd) != 0)
            perror("close(i2c_fd)");
        g_i2c_fd = -1;
    }
    printf("Done.\n");
    return EXIT_SUCCESS;
}

