code:
/*
 * SHT35-DIS-B temperature & humidity logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SHT35 VDD  -> Pi 3V3  (pin 1)
 *   SHT35 GND  -> Pi GND  (pin 9)
 *   SHT35 SDA  -> Pi GPIO2 / I2C1 SDA (pin 3)
 *   SHT35 SCL  -> Pi GPIO3 / I2C1 SCL (pin 5)
 *
 * Build:  gcc -O2 -Wall -Wextra -o sht35_logger sht35_logger.c -lpigpio -lrt
 * Run:    sudo ./sht35_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x44          /* SHT35-DIS-B default I2C address */
#define CSV_FILENAME   "environment.csv"
#define SAMPLE_PERIOD  5             /* seconds between samples */
#define MEAS_DELAY_US  15000         /* 15 ms measurement wait (datasheet: typ 12.5 ms) */

/* SHT35 single-shot, high repeatability, clock-stretching disabled */
#define SHT35_CMD_MSB  0x2C
#define SHT35_CMD_LSB  0x06

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)               */
/* ------------------------------------------------------------------ */
static uint8_t sht35_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int sht35_read(int handle, float *temperature, float *humidity)
{
    uint8_t cmd[2] = { SHT35_CMD_MSB, SHT35_CMD_LSB };
    uint8_t buf[6];

    /* Send measurement command */
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed\n");
        return -1;
    }

    /* Wait for conversion (datasheet: typ 12.5 ms, max 15 ms) */
    gpioDelay(MEAS_DELAY_US);

    /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed (sensor may be absent)\n");
        return -1;
    }

    /* Validate CRCs */
    if (sht35_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }
    if (sht35_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t h_raw = (uint16_t)((buf[3] << 8) | buf[4]);

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, float temperature, float humidity)
{
    /* Check if file exists / is empty to decide on header */
    int need_header = 0;
    FILE *probe = fopen(filename, "r");
    if (probe == NULL) {
        need_header = 1;                 /* file does not exist yet */
    } else {
        fseek(probe, 0, SEEK_END);
        if (ftell(probe) == 0)
            need_header = 1;             /* empty file */
        fclose(probe);
    }

    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("[ERROR] fopen CSV");
        return -1;
    }

    if (need_header)
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);

    if (fclose(fp) != 0) {
        perror("[ERROR] fclose CSV");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SHT35-DIS-B logger started.  Bus %d, addr 0x%02X, CSV: %s\n",
           I2C_BUS, I2C_ADDR, CSV_FILENAME);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature, humidity;

        if (sht35_read(g_i2c_handle, &temperature, &humidity) == 0) {
            printf("T=%.2f C  RH=%.2f %%\n", temperature, humidity);
            if (log_data(CSV_FILENAME, temperature, humidity) != 0) {
                fprintf(stderr, "[WARN] Logging failed (continuing)\n");
            }
        } else {
            fprintf(stderr, "[WARN] Sensor read failed (continuing)\n");
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

