/*
 * Greenhouse monitor — Si7021 on Raspberry Pi Zero W (I2C bus 1, GPIO 2/3)
 * Build:  gcc -O2 -Wall -Wextra -o greenhouse greenhouse.c
 * Run:    ./greenhouse   (Ctrl-C to stop)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define POLL_TIMEOUT_MS 100
#define SAMPLE_PERIOD_S 5

/* Si7021 commands (16-bit, big-endian on the wire) */
#define CMD_MEASURE_TEMP_HOLD   0xE3
#define CMD_MEASURE_HUM_HOLD    0xE5
#define CMD_RESET              0xFE

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Write a 16-bit command (big-endian) to the Si7021.
 * Returns 0 on success, -1 on error.
 */
static int si7021_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "write(cmd 0x%04X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read `len` bytes from the Si7021.
 * Returns 0 on success, -1 on error.
 */
static int si7021_read(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "read: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "read: short read (%zd of %zu bytes)\n", n, len);
        return -1;
    }
    return 0;
}

/*
 * CRC-8 used by Si7021, polynomial 0x31, init 0x00.
 * Covers the two data bytes only (not the command byte).
 */
static uint8_t si7021_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/*
 * Trigger a measurement and poll until data is ready or timeout.
 * Returns 0 on success, -1 on I2C error, -2 on timeout.
 */
static int si7021_measure(int fd, uint16_t cmd, uint16_t *raw)
{
    if (si7021_write_cmd(fd, cmd) < 0)
        return -1;

    /* Si7021 conversion time: ~12 ms for temp, ~12 ms for humidity.
     * Poll every 5 ms up to POLL_TIMEOUT_MS. */
    for (int waited = 0; waited < POLL_TIMEOUT_MS; waited += 5) {
        usleep(5000);
        uint8_t buf[3];
        if (si7021_read(fd, buf, 3) < 0)
            return -1;
        if (si7021_crc8(buf, 2) == buf[2]) {
            *raw = (uint16_t)((buf[0] << 8) | buf[1]);
            return 0;
        }
        /* CRC mismatch — keep polling (sensor may still be ready). */
    }
    return -2;
}

static float raw_to_celsius(uint16_t raw)
{
    return (175.72f * (float)raw / 65536.0f) - 46.85f;
}

static float raw_to_humidity(uint16_t raw)
{
    return (125.0f * (float)raw / 65536.0f) - 6.0f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_line(const char *ts, const char *temp, const char *hum)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }
    fprintf(fp, "%s,%s,%s\n", ts, temp, hum);
    fclose(fp);
}

static void log_error(const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    if (localtime_r(&t, &tm))
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    log_line(ts, "ERROR", "ERROR");
    fprintf(stderr, "%s  %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() < 0)
        return EXIT_FAILURE;

    g_i2c_fd = i2c_open(I2C_BUS, SI7021_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    /* Write CSV header if file is new/empty. */
    {
        FILE *fp = fopen(LOG_FILE, "r");
        int need_header = 1;
        if (fp) {
            if (fseek(fp, 0, SEEK_END) == 0) {
                long sz = ftell(fp);
                if (sz > 0)
                    need_header = 0;
            }
            fclose(fp);
        }
        if (need_header) {
            fp = fopen(LOG_FILE, "w");
            if (fp) {
                fprintf(fp, "timestamp,temperature_C,humidity_percent\n");
                fclose(fp);
            } else {
                fprintf(stderr, "fopen(%s, w): %s\n", LOG_FILE, strerror(errno));
            }
        }
    }

    while (g_running) {
        time_t t = time(NULL);
        struct tm tm;
        char ts[32];
        if (localtime_r(&t, &tm))
            strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        else
            snprintf(ts, sizeof(ts), "UNKNOWN");

        uint16_t raw_t = 0, raw_h = 0;
        int rc_t = si7021_measure(g_i2c_fd, CMD_MEASURE_TEMP_HOLD, &raw_t);
        if (rc_t == 0) {
            int rc_h = si7021_measure(g_i2c_fd, CMD_MEASURE_HUM_HOLD, &raw_h);
            if (rc_h == 0) {
                float temp = raw_to_celsius(raw_t);
                float hum  = raw_to_humidity(raw_h);
                char tbuf[16], hbuf[16];
                snprintf(tbuf, sizeof(tbuf), "%.2f", temp);
                snprintf(hbuf, sizeof(hbuf), "%.2f", hum);
                log_line(ts, tbuf, hbuf);
            } else {
                log_error("humidity read failed (timeout or I2C error)");
            }
        } else {
            log_error("temperature read failed (timeout or I2C error)");
        }

        /* Reset sensor on any read failure so the next cycle starts fresh. */
        if (rc_t != 0 || si7021_write_cmd(g_i2c_fd, CMD_RESET) < 0) {
            fprintf(stderr, "Resetting Si7021...\n");
            if (si7021_write_cmd(g_i2c_fd, CMD_RESET) < 0)
                fprintf(stderr, "Warning: reset write failed: %s\n", strerror(errno));
            usleep(15000); /* reset takes ~15 ms */
        }

        /* Sleep SAMPLE_PERIOD_S, but wake early on signal. */
        for (int s = 0; s < SAMPLE_PERIOD_S && g_running; s++)
            sleep(1);
    }

    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    return EXIT_SUCCESS;
}

