#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define CONVERSION_TIME_US 45000
#define LOG_FILE "airflow.dat"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d (code %d)\n",
                SDP810_ADDR, I2C_BUS, i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    uint8_t cmd[2] = { (MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF };
    uint8_t buf[9];
    int16_t raw_pressure, raw_temperature;
    int32_t scale_factor;

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to write measurement command to I2C device\n");
        return -1;
    }

    gpioDelay(CONVERSION_TIME_US);

    if (i2cReadDevice(i2c_handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "Error: Failed to read 9 bytes from I2C device\n");
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }

    raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    scale_factor = (int32_t)((buf[6] << 16) | (buf[7] << 8) | buf[8]);

    if (scale_factor == 0) {
        fprintf(stderr, "Error: Invalid scale factor (0) from sensor\n");
        return -1;
    }

    data->pressure = (float)raw_pressure / (float)scale_factor;
    data->temperature = (float)raw_temperature / 200.0f;

    return 0;
}

static int log_data(const sensor_data_t *data) {
    if (fwrite(data, sizeof(sensor_data_t), 1, log_file) != 1) {
        fprintf(stderr, "Error: Failed to write data to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: Failed to set up signal handlers");
        return 1;
    }

    if (init_i2c() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "wb");
    if (log_file == NULL) {
        perror("Error: Failed to open log file");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;
    int consecutive_errors = 0;

    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            consecutive_errors = 0;
            if (log_data(&sensor_data) != 0) {
                fprintf(stderr, "Error: Logging failed, continuing...\n");
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error: Sensor read failed (consecutive: %d)\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Error: Too many consecutive failures, aborting\n");
                break;
            }
        }
        gpioDelay(1000000);
    }

    cleanup();
    return 0;
}

