#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define PWM_RANGE 1000
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_US 100000

#define PRESSURE_MIN -100.0f
#define PRESSURE_MAX 100.0f
#define FLOW_RATE_MIN 0.0f
#define FLOW_RATE_MAX 100.0f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_pressure(float *pressure) {
    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *pressure = (float)raw * (PRESSURE_MAX - PRESSURE_MIN) / 65535.0f + PRESSURE_MIN;
    return 0;
}

static float calculate_flow_rate(float pressure) {
    return (pressure - PRESSURE_MIN) * (FLOW_RATE_MAX - FLOW_RATE_MIN) / (PRESSURE_MAX - PRESSURE_MIN) + FLOW_RATE_MIN;
}

static void set_fan_speed(float flow_rate) {
    int duty_cycle = (int)((flow_rate / FLOW_RATE_MAX) * PWM_RANGE);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
    }
}

static void log_data(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Warning: could not set exact PWM frequency\n");
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Warning: could not set exact PWM range\n");
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float pressure;
        if (read_pressure(&pressure) == 0) {
            float flow_rate = calculate_flow_rate(pressure);
            set_fan_speed(flow_rate);
            log_data(pressure);
        } else {
            fprintf(stderr, "Error reading pressure, skipping sample\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioPWM(FAN_GPIO, 0);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

