    uint8_t xl, l, h;
    if (read_register(handle, PRESS_OUT_XL, &xl) < 0) return -1;
    if (read_register(handle, PRESS_OUT_XL + 1, &l) < 0) return -1;
    if (read_register(handle, PRESS_OUT_XL + 2, &h) < 0) return -1;
    int32_t raw = ((int32_t)h << 16) | ((int32_t)l << 8) | (int32_t)xl;
