#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define LED_GPIO       17
#define BUFFER_SIZE    10
#define TEMP_THRESHOLD 28.0f
#define SAMPLE_PERIOD  1.0

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value)
{
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float cb_average(const CircularBuffer *cb)
{
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / (float)cb->count;
}

static int read_temperature(int handle, float *out_temp)
{
    char reg = 0x00;
    char data[2];

    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: failed to select temperature register\n");
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: failed to read 2 bytes from temperature register\n");
        return -1;
    }

    int16_t raw = ((int16_t)(data[0] << 8)) | (uint8_t)data[1];
    raw >>= 5;
    if (raw & 0x0400) raw |= 0xF800;
    *out_temp = (float)raw * 0.125f;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d)\n", handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO%d\n", LED_GPIO);
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    CircularBuffer temp_buffer;
    cb_init(&temp_buffer);

    while (g_running) {
        float temperature;
        if (read_temperature(handle, &temperature) == 0) {
            printf("Temperature: %.2f C\n", temperature);
            cb_add(&temp_buffer, temperature);
            float avg = cb_average(&temp_buffer);
            printf("Average Temperature: %.2f C\n", avg);

            if (avg > TEMP_THRESHOLD) {
                gpioWrite(LED_GPIO, 1);
                printf("Average temperature exceeds threshold. LED ON\n");
            } else {
                gpioWrite(LED_GPIO, 0);
                printf("Average temperature below threshold. LED OFF\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature. Skipping this iteration.\n");
        }

        time_sleep(SAMPLE_PERIOD);
    }

    gpioWrite(LED_GPIO, 0);
    i2cClose(handle);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

