#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD30_I2C_ADDR 0x61
#define LOG_FILE "air_quality.log"
#define SAMPLE_INTERVAL_SEC 5
#define CO2_LOW_THRESHOLD 800
#define CO2_HIGH_THRESHOLD 1200

#define CMD_START_PERIODIC_MEASUREMENT 0x0010
#define CMD_STOP_PERIODIC_MEASUREMENT 0x0104
#define CMD_GET_DATA_READY 0x0202
#define CMD_READ_MEASUREMENT 0x0300

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int write_command(int handle, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    return i2cWriteDevice(handle, (char *)buf, 2);
}

static int write_command_with_arg(int handle, uint16_t cmd, uint16_t arg) {
    uint8_t buf[5];
    buf[0] = (uint8_t)(cmd >> 8);
    buf[1] = (uint8_t)(cmd & 0xFF);
    buf[2] = (uint8_t)(arg >> 8);
    buf[3] = (uint8_t)(arg & 0xFF);
    buf[4] = crc8(&buf[2], 2);
    return i2cWriteDevice(handle, (char *)buf, 5);
}

static int read_words(int handle, uint16_t cmd, uint16_t *data, int count) {
    if (write_command(handle, cmd) < 0) return -1;
    gpioDelay(3000);
    uint8_t buf[9];
    int n = i2cReadDevice(handle, (char *)buf, count * 3);
    if (n != count * 3) return -1;
    for (int i = 0; i < count; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) return -2;
        data[i] = (buf[i * 3] << 8) | buf[i * 3 + 1];
    }
    return 0;
}

static int scd30_start_periodic(int handle) {
    return write_command_with_arg(handle, CMD_START_PERIODIC_MEASUREMENT, 0x0000);
}

static int scd30_stop_periodic(int handle) {
    return write_command(handle, CMD_STOP_PERIODIC_MEASUREMENT);
}

static int scd30_data_ready(int handle, int *ready) {
    uint16_t val;
    int r = read_words(handle, CMD_GET_DATA_READY, &val, 1);
    if (r == 0) { *ready = (val == 1); return 0; }
    return r;
}

static int scd30_read_measurement(int handle, uint16_t *co2, float *temp, float *hum) {
    uint16_t w[9];
    int r = read_words(handle, CMD_READ_MEASUREMENT, w, 9);
    if (r == 0) {
