        return 1;
    }

    g_i2c_handle = i2cOpen(1, SCD30_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X (handle=%d)\n", SCD30_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return 0;
    }

