        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (scd30_start_periodic(g_i2c_handle) < 0) {
        log_error(g_log_file, "Failed to start periodic measurement");
        fprintf(stderr, "Sensor not responding or bus error\n");
        i2cClose(g_i2c_handle);
        fclose(g_log_file);
        gpioTerminate();
        return 0;
    }

    printf("SCD30 monitoring started. Logging to %s every %d s. Press Ctrl+C to stop.\n", LOG_FILE, SAMPLE_INTERVAL_SEC);

