            rc = scd30_read_measurement(g_i2c_handle, &co2, &temp, &hum);
            if (rc == 0) {
                log_data(g_log_file, co2, temp, hum);
                printf("CO2: %u ppm | Temp: %.2f C | Hum: %.2f %% | Vent: %s\n", co2, temp, hum, ventilation_state(co2));
            } else if (rc == -2) {
                log_error(g_log_file, "CRC mismatch on measurement data");
            } else {
