/*
 * SDP32 differential pressure reader for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   SDP32 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP32 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP32 VDD  -> 3.3 V
 *   SDP32 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o sdp32_reader sdp32_reader.c
 *
 * Run:
 *   ./sdp32_reader [sampling_ms]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SDP32_I2C_ADDR      0x21
#define SDP32_MEAS_CMD_MSB  0x36
#define SDP32_MEAS_CMD_LSB  0x2F
#define SDP32_MEAS_DELAY_MS 45
#define DEFAULT_INTERVAL_MS 1000
#define I2C_BUS             "/dev/i2c-1"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* Sensirion CRC-8 polynomial 0x31, init 0xFF */
static bool crc8_ok(const uint8_t *data, size_t len, uint8_t expected)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc == expected;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        if (!g_running)
            return;
    }
}

static int i2c_write_cmd(int fd, uint8_t msb, uint8_t lsb)
{
    uint8_t cmd[2] = { msb, lsb };
    ssize_t n = write(fd, cmd, sizeof(cmd));
    if (n != (ssize_t)sizeof(cmd)) {
        if (n < 0)
            fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        else
            fprintf(stderr, "I2C write short: %zd of %zu bytes\n", n, sizeof(cmd));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) {
                if (!g_running)
                    return -1;
                continue;
            }
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int read_sdp32(int fd, float *pressure, float *temperature)
{
    if (i2c_write_cmd(fd, SDP32_MEAS_CMD_MSB, SDP32_MEAS_CMD_LSB) != 0)
        return -1;

    sleep_ms(SDP32_MEAS_DELAY_MS);

    uint8_t data[9];
    if (i2c_read_bytes(fd, data, sizeof(data)) != 0)
        return -1;

    if (!crc8_ok(&data[0], 2, data[2])) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (!crc8_ok(&data[3], 2, data[5])) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (!crc8_ok(&data[6], 2, data[8])) {
        fprintf(stderr, "Scale-factor CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure    = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temperature = (int16_t)((data[3] << 8) | data[4]);
    int16_t scale_factor    = (int16_t)((data[6] << 8) | data[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0) from sensor\n");
        return -1;
    }

    *pressure    = (float)raw_pressure    / (float)scale_factor;
    *temperature = (float)raw_temperature / (float)scale_factor;

    return 0;
}

int main(int argc, char *argv[])
{
    int interval_ms = DEFAULT_INTERVAL_MS;

    if (argc > 1) {
        char *endptr = NULL;
        long val = strtol(argv[1], &endptr, 10);
        if (endptr == argv[1] || *endptr != '\0' || val <= 0 || val > 1000000) {
            fprintf(stderr, "Invalid interval '%s'. Using default %d ms.\n",
                    argv[1], DEFAULT_INTERVAL_MS);
        } else {
            interval_ms = (int)val;
        }
    }

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP32_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SDP32_I2C_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Probe: try a zero-length write to detect sensor presence */
    if (write(fd, NULL, 0) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X: %s\n",
                SDP32_I2C_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("SDP32 reader started. Interval: %d ms. Press Ctrl+C to stop.\n",
           interval_ms);

    int rc = EXIT_SUCCESS;

    while (g_running) {
        float pressure, temperature;

        if (read_sdp32(fd, &pressure, &temperature) != 0) {
            fprintf(stderr, "Read failed; continuing after %d ms.\n", interval_ms);
            sleep_ms(interval_ms);
            continue;
        }

        time_t now = time(NULL);
        struct tm tm_info;
        char ts[32];
        if (localtime_r(&now, &tm_info) != NULL) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        } else {
            snprintf(ts, sizeof(ts), "<unknown-time>");
        }

        printf("[%s] Pressure: %.2f Pa, Temperature: %.2f °C\n",
               ts, pressure, temperature);
        fflush(stdout);

        sleep_ms(interval_ms);
    }

    if (close(fd) < 0)
        perror("close");

    printf("\nExiting cleanly.\n");
    return rc;
}

