/*
 * SDP810-125Pa differential pressure sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SDA -> GPIO2 (BCM 2, physical pin 3)
 *   SCL -> GPIO3 (BCM 3, physical pin 5)
 *   VDD -> 3.3 V
 *   GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810 sdp810.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x25
#define TRIGGER_CMD    0x362F
#define READ_DELAY_MS  45
#define SAMPLE_PERIOD  1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Sensirion CRC-8: polynomial 0x31, init 0xFF, no final XOR */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static void sleep_ms(unsigned ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

/*
 * Write a 16-bit command to the SDP810.
 * Returns 0 on success, -1 on error.
 */
static int sdp810_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write failed (cmd 0x%04X): %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read 9 bytes: pressure(2)+crc, temperature(2)+crc, scale_factor(2)+crc.
 * Returns 0 on success, -1 on error, -2 on CRC mismatch.
 */
static int sdp810_read_data(int fd, int16_t *pressure,
                            int16_t *temperature, int16_t *scale_factor)
{
    uint8_t buf[9];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < 3; i++) {
        if (sensirion_crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return -2;
        }
    }

    *pressure      = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature   = (int16_t)((buf[3] << 8) | buf[4]);
    *scale_factor  = (int16_t)((buf[6] << 8) | buf[7]);
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SDP810_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("SDP810-125Pa reader started on %s (addr 0x%02X).\n", I2C_BUS, SDP810_ADDR);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        if (sdp810_write_cmd(fd, TRIGGER_CMD) != 0)
            goto cleanup;

        sleep_ms(READ_DELAY_MS);

        int16_t pressure, temperature, scale_factor;
        int r = sdp810_read_data(fd, &pressure, &temperature, &scale_factor);
        if (r == 0) {
            printf("Pressure: %d Pa, Temperature: %d °C, Scale: %d\n",
                   pressure, temperature, scale_factor);
            fflush(stdout);
        } else if (r == -2) {
            fprintf(stderr, "CRC error — sensor may be absent or wiring faulty.\n");
        } else {
            fprintf(stderr, "I2C read error — continuing.\n");
        }

        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep_ms(1000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    printf("\nExiting.\n");
    return rc;
}

