#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define HDC1000_ADDR   0x40
#define REG_TEMP       0x00
#define REG_HUMID      0x01
#define REG_CONFIG     0x02
#define REG_MAN_ID     0xFE
#define REG_DEV_ID     0xFF
#define CONFIG_14BIT   0x1000  /* bit12 = 1 (14-bit T), bit11 = 1 (14-bit RH) */
#define CONV_DELAY_MS  20      /* 14-bit T+RH conversion ~6.5 ms; use 20 ms */
#define POLL_INTERVAL  5       /* seconds between readings */

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_fd >= 0) {
        close(g_fd);
        g_fd = -1;
    }
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val & 0xFF);
    buf[2] = (uint8_t)((val >> 8) & 0xFF);
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int hdc1000_init(int fd)
{
    uint16_t cfg;
    if (i2c_read_reg16(fd, REG_CONFIG, &cfg) < 0) {
        fprintf(stderr, "Cannot read config register — sensor may be absent\n");
        return -1;
    }
    cfg |= CONFIG_14BIT;
    if (i2c_write_reg16(fd, REG_CONFIG, cfg) < 0)
        return -1;
    return 0;
}

static int hdc1000_read(int fd, float *temp, float *hum)
{
    uint16_t raw_t, raw_h;

    /* Trigger measurement by writing pointer to temperature register */
    uint8_t reg = REG_TEMP;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Trigger write failed: %s\n", strerror(errno));
        return -1;
    }

    usleep(CONV_DELAY_MS * 1000);

    /* Read 4 bytes: temp[0], temp[1], humid[0], humid[1] */
    uint8_t buf[4];
    if (read(fd, buf, 4) != 4) {
        fprintf(stderr, "Data read failed: %s\n", strerror(errno));
        return -1;
    }

    raw_t = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    raw_h = (uint16_t)buf[2] | ((uint16_t)buf[3] << 8);

    *temp = (float)raw_t / 65536.0f * 165.0f - 40.0f;
    *hum  = (float)raw_h / 65536.0f * 100.0f;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                HDC1000_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (hdc1000_init(g_fd) < 0) {
        fprintf(stderr, "HDC1000 init failed — check wiring and address\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HDC1000 initialized on %s (addr 0x%02X). Reading every %d s.\n",
           I2C_BUS, HDC1000_ADDR, POLL_INTERVAL);

    while (g_running) {
        float temp, hum;
        if (hdc1000_read(g_fd, &temp, &hum) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
            fflush(stdout);
        } else {
            fprintf(stderr, "Read failed; continuing.\n");
        }
        sleep(POLL_INTERVAL);
    }

    printf("\nExiting cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

