#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x60
#define CMD_MEASURE    0x20
#define READ_LEN       4
#define POLL_DELAY_US  7000
#define LOOP_DELAY_S   5
#define DEFAULT_TEMP   0x0000
#define DEFAULT_PRESS  0x0000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_sensor(int handle, float *temperature, float *pressure) {
    char cmd = CMD_MEASURE;
    char buf[READ_LEN];

    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write measurement command to I2C device.\n");
        return -1;
    }

    gpioDelay(POLL_DELAY_US);

    int bytes_read = i2cReadDevice(handle, buf, READ_LEN);
    if (bytes_read != READ_LEN) {
        fprintf(stderr, "Error: expected %d bytes, got %d from I2C device.\n", READ_LEN, bytes_read);
        return -1;
    }

    uint16_t raw_temp  = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    uint16_t raw_press = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];

    if (raw_temp == DEFAULT_TEMP && raw_press == DEFAULT_PRESS) {
        fprintf(stderr, "Error: sensor returned default values (0x%04X, 0x%04X) - sensor may be absent or unresponsive.\n",
                raw_temp, raw_press);
        return -1;
    }

    *temperature = (float)raw_temp / 100.0f;
    *pressure    = (float)raw_press * 10.0f;

    return 0;
}

static void log_data(float temperature, float pressure) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
    fflush(stdout);
}

int main(void) {
    float temperature, pressure;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device at bus %d, address 0x%02X (code %d).\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("ICP-10101 sensor reader started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        if (read_sensor(g_i2c_handle, &temperature, &pressure) == 0) {
            log_data(temperature, pressure);
        } else {
            fprintf(stderr, "Warning: sensor read failed, will retry next cycle.\n");
        }

        for (int i = 0; i < LOOP_DELAY_S && g_running; i++) {
            sleep(1);
        }
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

