#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90819_ADDR  0x28
#define MLX90819_REG   0x00
#define SAMPLE_PERIOD  1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];

    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
        printf("[%s] ", buf);
    }
}

int main(void)
{
    int fd = -1;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MLX90819 pressure sensor reader started on %s (addr 0x%02X).\n",
           I2C_BUS, MLX90819_ADDR);
    fflush(stdout);

    while (g_running) {
        uint8_t reg = MLX90819_REG;
        ssize_t w = write(fd, &reg, 1);
        if (w != 1) {
            print_timestamp();
            fprintf(stderr, "Error writing register address: %s\n",
                    w < 0 ? strerror(errno) : "short write");
            fflush(stderr);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        uint8_t buf[3];
        ssize_t r = read(fd, buf, sizeof(buf));
        if (r != (ssize_t)sizeof(buf)) {
            print_timestamp();
            fprintf(stderr, "Error reading pressure data: %s\n",
                    r < 0 ? strerror(errno) : "short read");
            fflush(stderr);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        uint32_t raw = ((uint32_t)buf[0] << 16) |
                       ((uint32_t)buf[1] << 8)  |
                       ((uint32_t)buf[2]);

        print_timestamp();
        printf("Pressure: %u\n", raw);
        fflush(stdout);

        sleep(SAMPLE_PERIOD);
    }

    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

