        ssize_t w = write(fd, &reg, 1);
        if (w != 1) {
            print_timestamp();
            fprintf(stderr, "Error writing register address: %s\n",
                    w < 0 ? strerror(errno) : "short write");
            fflush(stderr);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        uint8_t buf[3];
        ssize_t r = read(fd, buf, sizeof(buf));
        if (r != (ssize_t)sizeof(buf)) {
            print_timestamp();
            fprintf(stderr, "Error reading pressure data: %s\n",
                    r < 0 ? strerror(errno) : "short read");
            fflush(stderr);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        uint32_t raw = ((uint32_t)buf[0] << 16) |
                       ((uint32_t)buf[1] << 8)  |
                       ((uint32_t)buf[2]);

        print_timestamp();
        printf("Pressure: %u\n", raw);
        fflush(stdout);

        sleep(SAMPLE_PERIOD);
    }

    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

