/*
 * SDP800-500Pa differential pressure logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow_logger airflow_logger.c
 * Run:    ./airflow_logger   (user must have read/write access to /dev/i2c-1)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x25
#define LOG_FILE       "airflow_log.csv"
#define READ_INTERVAL  1          /* seconds between readings */
#define MEAS_DELAY_MS  8          /* SDP800 needs >= 8 ms after trigger */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)               */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Trigger a single-shot measurement and read the 3-byte response.
 * Returns 0 on success, -1 on error.
 */
static int sdp800_read(int fd, int16_t *pressure_raw)
{
    uint8_t cmd = 0x36;                 /* continuous read command */
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "I2C write trigger: %s\n",
                w < 0 ? strerror(errno) : "short write");
        return -1;
    }

    usleep(MEAS_DELAY_MS * 1000);       /* >= 8 ms per datasheet */

    uint8_t buf[3];
    ssize_t r = read(fd, buf, sizeof(buf));
    if (r != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read: %s\n",
                r < 0 ? strerror(errno) : "short read");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on pressure data\n");
        return -1;
    }

    *pressure_raw = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(const char *path)
{
    /* If the file already exists, we assume a header is present. */
    int need_header = (access(path, F_OK) != 0);

    FILE *fp = fopen(path, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", path, strerror(errno));
        return -1;
    }

    if (need_header) {
        if (fprintf(fp, "timestamp,pressure_pa\n") < 0) {
            fprintf(stderr, "fprintf header: %s\n", strerror(errno));
            fclose(fp);
            return -1;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "fflush header: %s\n", strerror(errno));
            fclose(fp);
            return -1;
        }
    }
    return fileno(fp);
}

static void log_reading(FILE *fp, int16_t raw)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(fp, "%s,%d\n", ts, raw) < 0) {
        fprintf(stderr, "fprintf data: %s\n", strerror(errno));
        return;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush data: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    int fd = i2c_open(I2C_BUS, SDP800_ADDR);
    if (fd < 0)
        return EXIT_FAILURE;

    int log_fd = log_open(LOG_FILE);
    if (log_fd < 0) {
        close(fd);
        return EXIT_FAILURE;
    }
    FILE *fp = fdopen(log_fd, "a");
    if (!fp) {
        fprintf(stderr, "fdopen: %s\n", strerror(errno));
        close(log_fd);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("SDP800 logger started. Press Ctrl-C to stop.\n");

    while (g_running) {
        int16_t raw;
        if (sdp800_read(fd, &raw) == 0) {
            log_reading(fp, raw);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        sleep(READ_INTERVAL);
    }

    printf("\nShutting down cleanly.\n");
    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

