#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define HIH6130_ADDR   0x27
#define LOG_FILE       "environmental_data.log"
#define LOG_MAX_SIZE   (1024 * 1024)   /* 1 MB */
#define READ_INTERVAL  5               /* seconds */
#define MEASURE_DELAY  40000           /* microseconds (40 ms) */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_roll(const char *path)
{
    FILE *fp = fopen(path, "r");
    if (!fp) {
        if (errno != ENOENT) {
            perror("fopen (roll check)");
        }
        return 0;
    }

    if (fseek(fp, 0, SEEK_END) != 0) {
        perror("fseek");
        fclose(fp);
        return -1;
    }

    long sz = ftell(fp);
    fclose(fp);

    if (sz <= 0) {
        return 0;
    }

    if ((unsigned long)sz < LOG_MAX_SIZE) {
        return 0;
    }

    if (remove(path) != 0 && errno != ENOENT) {
        perror("remove (log roll)");
        return -1;
    }
    return 0;
}

static int log_append(const char *path, const char *msg)
{
    FILE *fp = fopen(path, "a");
    if (!fp) {
        perror("fopen (append)");
        return -1;
    }
    if (fputs(msg, fp) == EOF) {
        perror("fputs");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("open i2c bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return -1;
    }
    return fd;
}

static int read_hih6130(int fd, float *temp, float *hum)
{
    uint8_t buf[4];

    /*
     * The HIH6130 is read-only: write a zero-length message to trigger
     * a measurement, then read 4 bytes.  The first two bytes are the
     * status + humidity, the last two are the temperature.
     */
    if (write(fd, buf, 0) < 0) {
        perror("write (trigger)");
        return -1;
    }

    usleep(MEASURE_DELAY);

    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        if (n < 0) {
            perror("read");
        } else {
            fprintf(stderr, "Short read: %zd bytes\n", n);
        }
        return -1;
    }

    /* Status bits occupy the two MSBs of the first byte */
    uint8_t status = (buf[0] >> 6) & 0x03;
    if (status != 0x00) {
        fprintf(stderr, "Sensor status error: 0x%02x\n", status);
        return -1;
    }

    uint16_t raw_hum = ((uint16_t)(buf[0] & 0x3F) << 8) | buf[1];
    uint16_t raw_temp = ((uint16_t)buf[2] << 8) | buf[3];

    *hum = (float)raw_hum / 16383.0f * 100.0f;
    *temp = (float)raw_temp / 16383.0f * 165.0f - 40.0f;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = i2c_open(I2C_BUS, HIH6130_ADDR);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temp, hum;

        if (read_hih6130(fd, &temp, &hum) == 0) {
            time_t now = time(NULL);
            struct tm tmv;
            char ts[32];
            char line[160];

            if (localtime_r(&now, &tmv) != NULL) {
                strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv);
            } else {
                strncpy(ts, "1970-01-01T00:00:00", sizeof(ts) - 1);
                ts[sizeof(ts) - 1] = '\0';
            }

            snprintf(line, sizeof(line), "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                     ts, temp, hum);

            if (log_roll(LOG_FILE) != 0) {
                fprintf(stderr, "Log roll failed; continuing.\n");
            }
            if (log_append(LOG_FILE, line) != 0) {
                fprintf(stderr, "Failed to write to log file.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < READ_INTERVAL * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    if (close(fd) != 0) {
        perror("close");
    }
    return EXIT_SUCCESS;
}

