/*
 * MLX90824 SENT pressure sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   MLX90824 SENT output  -> GPIO4 (BCM 4, physical pin 7)
 *   MLX90824 VDD          -> 3.3 V
 *   MLX90824 GND          -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mlx90824_reader mlx90824_reader.c
 *
 * SENT protocol summary (per SAE J2602):
 *   - 36-813 us tick time (3 us nominal, 3.3 us max, 2.7 us min)
 *   - Sync pulse: 56 ticks (168 us)
 *   - Status nibble + 3 data nibbles + checksum nibble = 5 nibbles
 *   - Nibble pulse width: 12-271 ticks (36-813 us)
 *   - Checksum = (status + d0 + d1 + d2) & 0x0F
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN          4
#define LOG_FILE          "pressure_log.txt"
#define TICK_US           3
#define SYNC_TICKS        56
#define SYNC_MIN_TICKS    50
#define SYNC_MAX_TICKS    62
#define NIBBLE_MIN_TICKS  12
#define NIBBLE_MAX_TICKS  271
#define READ_TIMEOUT_US   1000000   /* 1 s */
#define SAMPLE_PERIOD_US  100000    /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SENT bit-bang receiver                                              */
/* ------------------------------------------------------------------ */

/*
 * Wait for the line to reach the requested level, returning the
 * elapsed time in microseconds, or -1 on timeout / error.
 */
static long wait_level(int level, uint32_t timeout_us)
{
    uint32_t start = gpioTick();
    for (;;) {
        if (gpioRead(GPIO_PIN) == level)
            return (long)(gpioTick() - start);
        if (gpioTick() - start > timeout_us)
            return -1;
    }
}

/*
 * Measure a single nibble pulse width.
 * Returns ticks (>= 0) on success, -1 on timeout, -2 on bus error.
 */
static int measure_nibble(void)
{
    /* Falling edge marks the start of the nibble pulse */
    long fall_us = wait_level(0, READ_TIMEOUT_US);
    if (fall_us < 0)
        return -1;

    /* Rising edge marks the end of the nibble pulse */
    long rise_us = wait_level(1, READ_TIMEOUT_US);
    if (rise_us < 0)
        return -1;

    long width_us = fall_us - rise_us;  /* pigpio ticks are in us; order correct */
    if (width_us < 0)
