        return -2;

    return ticks;
}

/*
 * Decode a nibble value from its pulse width in ticks.
 * SENT nibble encoding: 12 ticks = 0, 13 ticks = 1, ..., 271 ticks = F.
 */
static int ticks_to_nibble(int ticks)
{
    int nibble = ticks - NIBBLE_MIN_TICKS;
    if (nibble < 0 || nibble > 0x0F)
        return -1;
    return nibble;
}

/*
 * Read one complete SENT frame (5 nibbles) and return the pressure
 * value in Pa, or -1.0 on failure.
 */
static float read_sent_frame(void)
{
    /* Wait for the falling edge of the sync pulse */
    long fall_us = wait_level(0, READ_TIMEOUT_US);
    if (fall_us < 0)
