    /* Wait for the rising edge of the sync pulse */
    long rise_us = wait_level(1, READ_TIMEOUT_US);
    if (rise_us < 0)
        return -1.0f;

    long sync_width_us = fall_us - rise_us;
    if (sync_width_us < 0)
        return -1.0f;

    int sync_ticks = (int)(sync_width_us / TICK_US);
    if (sync_ticks < SYNC_MIN_TICKS || sync_ticks > SYNC_MAX_TICKS) {
        fprintf(stderr, "SENT sync pulse out of range: %d ticks\n", sync_ticks);
        return -1.0f;
    }

    int nibbles[5];
    for (int i = 0; i < 5; i++) {
        int ticks = measure_nibble();
        if (ticks < 0) {
            fprintf(stderr, "SENT nibble %d read failed (code %d)\n", i, ticks);
            return -1.0f;
        }
        nibbles[i] = ticks_to_nibble(ticks);
        if (nibbles[i] < 0) {
            fprintf(stderr, "SENT nibble %d out of range: %d ticks\n", i, ticks);
            return -1.0f;
        }
    }

    /* Checksum: (status + d0 + d1 + d2) & 0x0F */
    int calc = (nibbles[0] + nibbles[1] + nibbles[2] + nibbles[3]) & 0x0F;
    if (calc != nibbles[4]) {
        fprintf(stderr, "SENT checksum mismatch: calc=0x%X recv=0x%X\n",
                calc, nibbles[4]);
        return -1.0f;
    }

    /*
     * MLX90824 pressure output (example conversion).
     * Status nibble 0x0 = normal, 0x1 = warning, 0x2 = error.
     * Data nibbles: d0.d1.d2 (12-bit, big-endian).
     */
    uint16_t raw = ((uint16_t)nibbles[1] << 8) | ((uint16_t)nibbles[2] << 4) | nibbles[3];
    float pressure = (float)raw * 0.1f;   /* 10 Pa per LSB (example) */

    return pressure;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_pressure(float pressure)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
