#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>

/* TMP117 I2C default address (GND tied to GND) */
#define TMP117_ADDR 0x48

/* TMP117 register addresses */
#define TMP117_REG_TEMP 0x00
#define TMP117_REG_CONFIG 0x01
#define TMP117_REG_DEVICE_ID 0x0F

/* TMP117 device ID: 0x0117 (big-endian in registers) */
#define TMP117_DEVICE_ID 0x0117

/* Conversion time for 16-bit resolution (~7.8 ms) */
#define TMP117_CONV_TIME_US 10000

/* Global resources for signal handler cleanup */
static int i2c_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can clean up and exit       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Read the 16-bit device ID and verify it matches the expected value */
/* ------------------------------------------------------------------ */
static int verify_device_id(int handle) {
    char reg = TMP117_REG_DEVICE_ID;
    char buf[2];

    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: failed to select device ID register\n");
        return -1;
    }

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: failed to read device ID\n");
        return -1;
    }

    uint16_t id = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    if (id != TMP117_DEVICE_ID) {
        fprintf(stderr, "Error: device ID mismatch (got 0x%04X, expected 0x%04X)\n",
                id, TMP117_DEVICE_ID);
        return -1;
    }

    printf("TMP117 device ID verified: 0x%04X\n", id);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature in degrees Celsius                                */
/* ------------------------------------------------------------------ */
static int read_temperature(int handle, float *temperature) {
    char reg = TMP117_REG_TEMP;
    char buf[2];

    /* Select the temperature register */
    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: failed to select temperature register\n");
        return -1;
    }

    /* Read 2 bytes (MSB first) */
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: failed to read temperature data\n");
        return -1;
    }

    int16_t raw = ((int16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];

    /* TMP117: 1 LSB = 0.0078125 °C */
    *temperature = (float)raw * 0.0078125f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a little-endian float to the binary log file                */
/* ------------------------------------------------------------------ */
static int log_temperature(FILE *f, float temp) {
    uint32_t raw = (uint32_t)(temp * 100000.0f);  /* scale to integer */
    uint8_t bytes[4] = {
        (uint8_t)(raw & 0xFF),
        (uint8_t)((raw >> 8) & 0xFF),
        (uint8_t)((raw >> 16) & 0xFF),
        (uint8_t)((raw >> 24) & 0xFF)
    };

    if (fwrite(bytes, 1, 4, f) != 4) {
        fprintf(stderr, "Error: failed to write temperature to file: %s\n",
                strerror(errno));
        return -1;
    }
    fflush(f);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                       */
/* ------------------------------------------------------------------ */
static void cleanup(void) {
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 (default for Raspberry Pi Zero W) */
    i2c_handle = i2cOpen(1, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device at address 0x%02X\n",
                TMP117_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor identity */
    if (verify_device_id(i2c_handle) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open binary log file in append mode */
    fp = fopen("greenhouse_temps.dat", "ab");
    if (fp == NULL) {
        fprintf(stderr, "Error: failed to open file for writing: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n",
                strerror(errno));
    }

    printf("Greenhouse temperature monitoring started. Logging to greenhouse_temps.dat\n");
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (running) {
        float temperature;

        if (read_temperature(i2c_handle, &temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);
            if (log_temperature(fp, temperature) != 0) {
                fprintf(stderr, "Warning: failed to log temperature, continuing...\n");
            }
        } else {
            fprintf(stderr, "Warning: temperature read failed, will retry next cycle\n");
        }

        /* Sleep 60 seconds, but wake early if a signal arrives */
        for (int i = 0; i < 60 && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

