#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define SHT40_ADDR             0x2A
#define SHT40_CMD_MEASURE_HIGH  0xFD
#define SHT40_CMD_RESET         0x94
#define SHT40_CMD_READ_ID       0x83
#define SHT40_CMD_WAKEUP        0x35
#define SHT40_CMD_SOFT_RESET    0x80
#define SHT40_CMD_SLEEP         0x20
#define SHT40_CMD_MEASURE_MED   0xF6
#define SHT40_CMD_MEASURE_LOW   0xE0

#define LOG_FILE_NAME "environmental_data.txt"
#define SAMPLE_INTERVAL_SEC 5
#define CONVERSION_DELAY_US 10000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (uint8_t)((crc << 1) ^ 0x31);
            else           crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int sht40_reset(void) {
    uint8_t cmd = SHT40_CMD_SOFT_RESET;
    if (i2cWriteDevice(g_i2c_handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: SHT40 soft reset write failed\n");
        return -1;
    }
    gpioDelay(1000);
    return 0;
}

static int sht40_read_id(uint8_t *id) {
    uint8_t cmd = SHT40_CMD_READ_ID;
    if (i2cWriteDevice(g_i2c_handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: SHT40 read ID write failed\n");
        return -1;
    }
    gpioDelay(1000);
    if (i2cReadDevice(g_i2c_handle, (char *)id, 3) != 3) {
        fprintf(stderr, "Error: SHT40 read ID read failed\n");
        return -1;
    }
    return 0;
}

static int sht40_read(sensor_data_t *data) {
    uint8_t cmd = SHT40_CMD_MEASURE_HIGH;
    uint8_t buf[6];

    if (i2cWriteDevice(g_i2c_handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: SHT40 measure write failed\n");
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    if (i2cReadDevice(g_i2c_handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: SHT40 measure read failed\n");
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t h_raw = (uint16_t)((buf[3] << 8) | buf[4]);

    data->temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    data->humidity    = -6.0f  + 125.0f * (float)h_raw / 65535.0f;

    if (data->humidity < 0.0f)   data->humidity = 0.0f;
    if (data->humidity > 100.0f) data->humidity = 100.0f;

    return 0;
}

static int log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                timestamp, data->temperature, data->humidity) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error: fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (sht40_reset() != 0) {
        fprintf(stderr, "Warning: SHT40 reset failed; continuing anyway\n");
    }

    uint8_t id[3];
    if (sht40_read_id(id) == 0) {
        printf("SHT40 ID: 0x%02X 0x%02X 0x%02X\n", id[0], id[1], id[2]);
    } else {
        fprintf(stderr, "Warning: SHT40 read ID failed\n");
    }

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE_NAME, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Logging to %s every %d seconds. Press Ctrl+C to stop.\n",
           LOG_FILE_NAME, SAMPLE_INTERVAL_SEC);

    while (g_running) {
        sensor_data_t data;
        if (sht40_read(&data) == 0) {
            if (log_data(&data) != 0) {
                fprintf(stderr, "Error: logging failed\n");
            }
        } else {
            fprintf(stderr, "Error: sensor read failed\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return 0;
}

