/*
 * SHTC3 Temperature & Humidity Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   SHTC3 VDD  -> Pi Pin 1 (3.3 V)
 *   SHTC3 VSS  -> Pi Pin 2 (GND)
 *   SHTC3 SDA  -> GPIO2 / Pin 3
 *   SHTC3 SCL  -> GPIO3 / Pin 5
 *
 * Build:  gcc -O2 -Wall -Wextra -o shtc3_logger shtc3_logger.c
 * Run:    ./shtc3_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- SHTC3 constants (datasheet) ---- */
#define SHTC3_ADDR             0x70
#define SHTC3_CMD_MEASURE_T_P  0x2401   /* clock stretching, T first, P second */
#define SHTC3_CMD_WAKEUP       0x3517
#define SHTC3_CMD_SLEEP        0xB098
#define SHTC3_CMD_RESET        0x805D

#define SHTC3_MEAS_DELAY_US    12400    /* 12.4 ms max conversion time */
#define SAMPLE_INTERVAL_S      5

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Prototypes ---- */
static uint8_t shtc3_crc8(const uint8_t *data, size_t len);
static int  shtc3_write_cmd(int handle, uint16_t cmd);
static int  shtc3_read_measurement(int handle, float *temp_c, float *rh);
static int  shtc3_validate(float temp_c, float rh);
static int  shtc3_log_data(float temp_c, float rh);
static void shtc3_cleanup(void);
static void signal_handler(int sig);

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t shtc3_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ---- Write a 16-bit command to the SHTC3 ---- */
static int shtc3_write_cmd(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(0x%04X) failed: %d\n", cmd, rc);
        return -1;
    }
    return 0;
}

/* ---- Read one measurement (T + P) from the SHTC3 ---- */
static int shtc3_read_measurement(int handle, float *temp_c, float *rh)
{
    uint8_t data[6];

    /* Wake up the sensor (no-op if already awake) */
    if (shtc3_write_cmd(handle, SHTC3_CMD_WAKEUP) < 0)
        return -1;
    gpioDelay(1000);  /* 1 ms wake-up */

    /* Issue measurement command */
    if (shtc3_write_cmd(handle, SHTC3_CMD_MEASURE_T_P) < 0)
        return -1;

    /* Wait for conversion */
    gpioDelay(SHTC3_MEAS_DELAY_US);

    /* Read 6 bytes: T_MSB, T_LSB, T_CRC, P_MSB, P_LSB, P_CRC */
    int rc = i2cReadDevice(handle, (char *)data, 6);
    if (rc != 6) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected 6)\n", rc);
        return -1;
    }

    /* Put sensor back to sleep to save power */
    shtc3_write_cmd(handle, SHTC3_CMD_SLEEP);
    gpioDelay(1000);

    /* Validate CRCs */
    if (shtc3_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }
    if (shtc3_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "[ERROR] Humidity CRC mismatch\n");
        return -1;
    }

    /* Convert raw values */
    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t p_raw = ((uint16_t)data[3] << 8) | data[4];

    *temp_c = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *rh     = 100.0f * (float)p_raw / 65535.0f;

    return 0;
}

/* ---- Range validation ---- */
static int shtc3_validate(float temp_c, float rh)
{
    if (temp_c < -40.0f || temp_c > 125.0f) {
        fprintf(stderr, "[WARN] Temperature out of range: %.2f C\n", temp_c);
        return -1;
    }
    if (rh < 0.0f || rh > 100.0f) {
        fprintf(stderr, "[WARN] Humidity out of range: %.2f %%\n", rh);
        return -1;
    }
    return 0;
}

/* ---- Log to file ---- */
static int shtc3_log_data(float temp_c, float rh)
{
    FILE *fp = fopen("shtc3_environment.log", "a");
    if (!fp) {
        perror("[ERROR] fopen shtc3_environment.log");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("[ERROR] localtime_r");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temp_c, rh);

    fclose(fp);
    return 0;
}

/* ---- Cleanup: close I2C, put sensor to sleep ---- */
static void shtc3_cleanup(void)
{
    if (g_i2c_handle >= 0) {
        shtc3_write_cmd(g_i2c_handle, SHTC3_CMD_SLEEP);
        gpioDelay(1000);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 (SDA=GPIO2, SCL=GPIO3 on Pi 4) */
    g_i2c_handle = i2cOpen(1, SHTC3_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

