    if (shtc3_write_cmd(g_i2c_handle, SHTC3_CMD_RESET) < 0) {
        fprintf(stderr, "[FATAL] SHTC3 reset failed\n");
        shtc3_cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(1000);

    /* Wake up sensor */
    if (shtc3_write_cmd(g_i2c_handle, SHTC3_CMD_WAKEUP) < 0) {
        fprintf(stderr, "[FATAL] SHTC3 wakeup failed\n");
        shtc3_cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(1000);

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SHTC3 logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float temp_c, rh;

        if (shtc3_read_measurement(g_i2c_handle, &temp_c, &rh) == 0) {
            if (shtc3_validate(temp_c, rh) == 0) {
                printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp_c, rh);
