#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define SI7202_ADDR 0x39
#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 3

#define SI7202_REG_TEMP 0x00
#define SI7202_REG_MAG 0x01
#define SI7202_REG_CONFIG 0x02

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, SI7202_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_register(uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C read failed for reg 0x%02X (rc=%d): %s\n",
                reg, rc, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(float *temp_c) {
    uint8_t buf[2];
    if (read_register(SI7202_REG_TEMP, buf, 2) != 0) return -1;
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temp_c = (raw / 256.0f) - 40.0f;
    return 0;
}

static int read_magnetometer(float *mag_g) {
    uint8_t buf[2];
    if (read_register(SI7202_REG_MAG, buf, 2) != 0) return -1;
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *mag_g = (raw / 65536.0f) * 100.0f;
    return 0;
}

static int log_data(float speed, float temp) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);

    if (isnan(speed) || isnan(temp)) {
        fprintf(log_file, "%s,NaN,NaN\n", ts);
    } else {
        fprintf(log_file, "%s,%.2f,%.2f\n", ts, speed, temp);
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Speed_rps,Temperature_C\n");
        fflush(log_file);
    }

    float temp = NAN, mag = NAN;
    uint32_t last_tick = gpioTick();

    while (running) {
        int t_ok = 0, m_ok = 0;

        for (int r = 0; r < MAX_RETRIES && running; r++) {
            if (read_temperature(&temp) == 0) { t_ok = 1; break; }
            gpioDelay(10000);
        }
        for (int r = 0; r < MAX_RETRIES && running; r++) {
            if (read_magnetometer(&mag) == 0) { m_ok = 1; break; }
            gpioDelay(10000);
        }

        if (!t_ok || !m_ok) {
            fprintf(stderr, "Sensor read failed (temp=%s, mag=%s); logging NaN\n",
                    t_ok ? "ok" : "fail", m_ok ? "ok" : "fail");
            log_data(NAN, NAN);
        } else {
            uint32_t now = gpioTick();
            float dt = (now - last_tick) / 1000000.0f;
            if (dt <= 0.0f) dt = 1.0f;
            float speed = mag / dt;
            log_data(speed, temp);
            last_tick = now;
        }

        uint32_t remaining = SAMPLE_INTERVAL_US;
        while (remaining > 0 && running) {
            uint32_t step = (remaining > 100000) ? 100000 : remaining;
            gpioDelay(step);
            remaining -= step;
        }
    }

    cleanup();
    return 0;
}

