    if (isnan(speed) || isnan(temp)) {
        fprintf(log_file, "%s,NaN,NaN\n", ts);
    } else {
        fprintf(log_file, "%s,%.2f,%.2f\n", ts, speed, temp);
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Speed_rps,Temperature_C\n");
        fflush(log_file);
    }

    float temp = NAN, mag = NAN;
    uint32_t last_tick = gpioTick();

    while (running) {
        int t_ok = 0, m_ok = 0;

        for (int r = 0; r < MAX_RETRIES && running; r++) {
            if (read_temperature(&temp) == 0) { t_ok = 1; break; }
            gpioDelay(10000);
        }
        for (int r = 0; r < MAX_RETRIES && running; r++) {
            if (read_magnetometer(&mag) == 0) { m_ok = 1; break; }
            gpioDelay(10000);
        }

        if (!t_ok || !m_ok) {
            fprintf(stderr, "Sensor read failed (temp=%s, mag=%s); logging NaN\n",
                    t_ok ? "ok" : "fail", m_ok ? "ok" : "fail");
            log_data(NAN, NAN);
        } else {
            uint32_t now = gpioTick();
            float dt = (now - last_tick) / 1000000.0f;
            if (dt <= 0.0f) dt = 1.0f;
            float speed = mag / dt;
            log_data(speed, temp);
            last_tick = now;
        }

        uint32_t remaining = SAMPLE_INTERVAL_US;
        while (remaining > 0 && running) {
            uint32_t step = (remaining > 100000) ? 100000 : remaining;
            gpioDelay(step);
            remaining -= step;
        }
    }

    cleanup();
    return 0;
}

