static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    char buf[4];
    int bytes_read;

    bytes_read = i2cReadDevice(i2c_handle, buf, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }

    uint16_t raw_flow = ((uint16_t)(buf[0] & 0x3F) << 8) | (uint8_t)buf[1];
    uint16_t raw_temp = ((uint16_t)(buf[2] & 0x0F) << 8) | (uint8_t)buf[3];

    data->flow_rate = (float)raw_flow * 0.001f;
    data->temperature = (float)raw_temp * 0.01f - 40.0f;

    return 0;
}

