    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Flow: %.3f SLPM, Temperature: %.2f C\n",
            timestamp, data->flow_rate, data->temperature);
    fflush(log_file);
}

