        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "--- Flow sensor logging started ---\n");
    fflush(log_file);

    int consecutive_errors = 0;

    while (!terminate) {
        sensor_data_t sensor_data;

        if (read_sensor_data(&sensor_data) == 0) {
            log_data(&sensor_data);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error #%d\n", consecutive_errors);

            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached. Re-initializing I2C.\n");
                if (init_i2c() != 0) {
                    fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                    break;
