#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdint.h>

#define DHT11_PIN 4
#define MAX_RETRIES 5
#define DHT11_TIMEOUT 200
#define DHT11_INTERVAL_SEC 2

/* ---- Library-provided API prototypes (microsecond timing, GPIO control) ---- */
extern int gpio_init(void);
extern void gpio_cleanup(void);
extern int gpio_set_mode(int pin, int mode);
extern int gpio_read(int pin);
extern int gpio_write(int pin, int value);
extern void gpio_delay_us(unsigned int us);

/* GPIO modes */
#define GPIO_MODE_OUTPUT 1
#define GPIO_MODE_INPUT  0

/* Timing constants (microseconds) */
#define START_LOW_US   20000   /* >= 18 ms start signal */
#define START_HIGH_US  30      /* release line */
#define RESP_LOW_US    80
#define RESP_HIGH_US   80
#define BIT_LOW_US     50
#define BIT_HIGH_0_US  26
#define BIT_HIGH_1_US  70
#define SAMPLE_US      20

/* Error codes */
#define DHT11_OK          0
#define DHT11_TIMEOUT     1
#define DHT11_CHECKSUM    2
#define DHT11_SENSOR_ABSENT 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read 40 bits from the DHT11; returns DHT11_OK on success, error code otherwise. */
static int read_dht11(int pin, int *humidity, int *temperature) {
    uint8_t data[5] = {0, 0, 0, 0, 0};
    int i, j;

    /* Send start signal: pull low for >= 18 ms, then release */
    if (gpio_set_mode(pin, GPIO_MODE_OUTPUT) != 0) return DHT11_SENSOR_ABSENT;
    if (gpio_write(pin, 0) != 0) return DHT11_SENSOR_ABSENT;
    gpio_delay_us(START_LOW_US);
    if (gpio_write(pin, 1) != 0) return DHT11_SENSOR_ABSENT;
    gpio_delay_us(START_HIGH_US);

    /* Switch to input; sensor pulls line low */
    if (gpio_set_mode(pin, GPIO_MODE_INPUT) != 0) return DHT11_SENSOR_ABSENT;

    /* Wait for sensor response: ~80 us low then ~80 us high */
    int timeout = DHT11_TIMEOUT;
    while (gpio_read(pin) == 1) {
        if (--timeout <= 0) return DHT11_TIMEOUT;
        gpio_delay_us(1);
    }
    timeout = DHT11_TIMEOUT;
    while (gpio_read(pin) == 0) {
        if (--timeout <= 0) return DHT11_TIMEOUT;
        gpio_delay_us(1);
    }
    timeout = DHT11_TIMEOUT;
    while (gpio_read(pin) == 1) {
        if (--timeout <= 0) return DHT11_TIMEOUT;
        gpio_delay_us(1);
    }

    /* Read 40 data bits */
    for (i = 0; i < 5; i++) {
        for (j = 7; j >= 0; j--) {
            timeout = DHT11_TIMEOUT;
            while (gpio_read(pin) == 0) {
                if (--timeout <= 0) return DHT11_TIMEOUT;
                gpio_delay_us(1);
            }
            gpio_delay_us(BIT_LOW_US);
            int level = gpio_read(pin);
            if (level < 0) return DHT11_SENSOR_ABSENT;
            if (level == 1) {
                data[i] |= (1 << j);
            }
            timeout = DHT11_TIMEOUT;
            while (gpio_read(pin) == 1) {
                if (--timeout <= 0) return DHT11_TIMEOUT;
                gpio_delay_us(1);
            }
        }
    }

    /* Verify checksum */
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) return DHT11_CHECKSUM;

    *humidity = data[0];
    *temperature = data[2];
    return DHT11_OK;
}

static void log_data(int humidity, int temperature) {
    FILE *fp = fopen("dht11_readings.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening dht11_readings.txt: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d, Humidity: %d%%, Temperature: %dC\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, humidity, temperature);
    }
    fclose(fp);
}

static void log_error(int error_code) {
    FILE *fp = fopen("dht11_errors.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening dht11_errors.txt: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d, Error Code: %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, error_code);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpio_init() != 0) {
