/*
 * ADPD105 Dual-Sensor Correlated Color Temperature Logger
 * Board:  Raspberry Pi Zero W
 * Library: pigpio (I2C via /dev/i2c-1)
 *
 * Reads two ADPD105 photometric front-end sensors, computes the
 * correlated color temperature (CCT) from the sensor data, and logs
 * the average CCT once per second to cct_log.csv.
 *
 * Build:  gcc -O2 -Wall -o cct_logger cct_logger.c -lpigpio -lm
 * Run:    sudo ./cct_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- ADPD105 I2C addresses (7-bit) ---- */
#define ADPD105_ADDR_1 0x50
#define ADPD105_ADDR_2 0x51

/* ---- ADPD105 register map (representative subset) ---- */
#define ADPD105_REG_DEVID        0x00
#define ADPD105_REG_MODE         0x01
#define ADPD105_REG_DATA_CH1     0x02
#define ADPD105_REG_DATA_CH2     0x04
#define ADPD105_REG_TEMP         0x06
#define ADPD105_REG_INT_STATUS   0x08
#define ADPD105_REG_INT_ENABLE   0x09
#define ADPD105_REG_FIFO_COUNT   0x0A
#define ADPD105_REG_FIFO_DATA    0x0B

#define ADPD105_DEVID_EXPECTED   0x01

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_h1 = -1;
static int  g_i2c_h2 = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an ADPD105 register; returns 0 on success, -1 on error. */
static int adpd105_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ADPD105] write reg 0x%02X val 0x%02X failed (rc=%d)\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* Read one byte from an ADPD105 register; returns 0 on success, -1 on error. */
static int adpd105_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ADPD105] read reg 0x%02X failed (rc=%d)\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Open an I2C handle to an ADPD105 and verify the device ID. */
static int adpd105_init(int bus, uint8_t addr)
{
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "[ADPD105] i2cOpen(bus=%d, addr=0x%02X) failed (rc=%d)\n",
                bus, addr, handle);
        return -1;
    }

    uint8_t devid = 0;
    if (adpd105_read_reg(handle, ADPD105_REG_DEVID, &devid) != 0) {
        i2cClose(handle);
        return -1;
    }
    if (devid != ADPD105_DEVID_EXPECTED) {
        fprintf(stderr, "[ADPD105] unexpected DEVID 0x%02X (expected 0x%02X) at 0x%02X\n",
                devid, ADPD105_DEVID_EXPECTED, addr);
        i2cClose(handle);
        return -1;
    }

    /* Put sensor in standby so we can configure it. */
    if (adpd105_write_reg(handle, ADPD105_REG_MODE, 0x00) != 0) {
        i2cClose(handle);
        return -1;
    }

    /* Clear any pending interrupts. */
    if (adpd105_write_reg(handle, ADPD105_REG_INT_STATUS, 0x00) != 0) {
        i2cClose(handle);
        return -1;
    }

    /* Enable data-ready interrupt on channel 1. */
    if (adpd105_write_reg(handle, ADPD105_REG_INT_ENABLE, 0x01) != 0) {
        i2cClose(handle);
        return -1;
    }

    /* Start normal operation. */
    if (adpd105_write_reg(handle, ADPD105_REG_MODE, 0x01) != 0) {
        i2cClose(handle);
        return -1;
    }

    return handle;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian sample from a channel register. */
static int adpd105_read_sample(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "[ADPD105] block read reg 0x%02X failed (rc=%d)\n", reg, rc);
        return -1;
    }
    *out = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute correlated color temperature from two-channel ADC counts. */
static double calculate_cct(uint16_t ch1, uint16_t ch2)
{
    if (ch1 == 0 || ch2 == 0)
        return 0.0;

    double r = (double)ch1;
    double g = (double)ch2;

    /* Simplified linear approximation (example). */
    double cct = 4000.0 + (5000.0 - 4000.0) * (1.0 - (r / (r + g)));
    return cct;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_h1 >= 0) { i2cClose(g_i2c_h1); g_i2c_h1 = -1; }
    if (g_i2c_h2 >= 0) { i2cClose(g_i2c_h2); g_i2c_h2 = -1; }
    if (g_log_fp)      { fclose(g_log_fp);   g_log_fp = NULL; }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C handles to both sensors ---- */
    g_i2c_h1 = adpd105_init(1, ADPD105_ADDR_1);
    if (g_i2c_h1 < 0) {
        fprintf(stderr, "Failed to initialise sensor 1 (0x%02X)\n", ADPD105_ADDR_1);
        cleanup();
        return EXIT_FAILURE;
    }

    g_i2c_h2 = adpd105_init(1, ADPD105_ADDR_2);
    if (g_i2c_h2 < 0) {
        fprintf(stderr, "Failed to initialise sensor 2 (0x%02X)\n", ADPD105_ADDR_2);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file (append); write header if empty ---- */
    g_log_fp = fopen("cct_log.csv", "a");
    if (!g_log_fp) {
        perror("fopen(cct_log.csv)");
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0)
        fprintf(g_log_fp, "Timestamp,Average_CCT\n");
    fflush(g_log_fp);

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

