#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX90824_ADDR 0x60
#define LOG_FILE "pressure_log.txt"
#define READ_INTERVAL_SEC 2

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
}

static void log_message(const char *msg) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    if (log_file) {
        fprintf(log_file, "%s,%s\n", ts, msg);
        fflush(log_file);
    }
    fprintf(stderr, "%s,%s\n", ts, msg);
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, MLX90824_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(float *pressure, float *temperature) {
    char cmd[2] = {0x00, 0x00};
    char buf[4];
    int ret;

    ret = i2cWriteDevice(i2c_handle, cmd, 2);
    if (ret != 0) {
        fprintf(stderr, "I2C write error: %d\n", ret);
        return -1;
    }

    gpioDelay(10000); /* 10 ms conversion delay */

    ret = i2cReadDevice(i2c_handle, buf, 4);
    if (ret != 4) {
        fprintf(stderr, "I2C read error: expected 4 bytes, got %d\n", ret);
        return -1;
    }

    int raw_pressure = (buf[0] << 8) | buf[1];
    int raw_temp = (buf[2] << 8) | buf[3];

    *pressure = (float)raw_pressure / 100.0f;
    *temperature = (float)raw_temp / 100.0f;

    return 0;
}

static void log_data(float pressure, float temperature) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(log_file, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(log_file);
}

int main(void) {
    float pressure, temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        log_message("I2C initialization failed");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Program started");

    while (running) {
        if (read_sensor_data(&pressure, &temperature) == 0) {
            log_data(pressure, temperature);
        } else {
            log_message("Sensor read failed");
        }
        sleep(READ_INTERVAL_SEC);
    }

    log_message("Program exiting");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

