#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD_HIGH 28.0f
#define TEMP_THRESHOLD_LOW 26.0f
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO%d to LOW\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X (pigpio error %d)\n",
                I2C_BUS, LM75B_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: I2C read failed (returned %d)\n", result);
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | (buf[1] & 0xFF));
    *temperature = (float)raw / 256.0f;
    return 0;
}

static void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

static float calculate_average(const CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / (float)cb->count;
}

static int control_fan(float average_temp) {
    static bool fan_on = false;
    int rc = 0;

    if (average_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) != 0) {
            fprintf(stderr, "Error: failed to turn fan ON\n");
            rc = -1;
        } else {
            fan_on = true;
            printf("Fan ON (avg %.2f C)\n", average_temp);
        }
    } else if (average_temp < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) != 0) {
            fprintf(stderr, "Error: failed to turn fan OFF\n");
            rc = -1;
        } else {
            fan_on = false;
            printf("Fan OFF (avg %.2f C)\n", average_temp);
        }
    }
    return rc;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    CircularBuffer temp_buffer = {0};
    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            add_to_buffer(&temp_buffer, temperature);
            float avg = calculate_average(&temp_buffer);
            printf("Temperature: %.2f C, Average: %.2f C\n", temperature, avg);
            if (control_fan(avg) != 0) {
                fprintf(stderr, "Warning: fan control reported an error\n");
            }
        } else {
            fprintf(stderr, "Warning: temperature read failed, retrying next cycle\n");
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

