/*
 * SDP810-500Pa differential pressure monitor for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP810 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow airflow.c -lpigpio -lrt
 * Run:    sudo ./airflow
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25          /* SDP810-500Pa default 7-bit address */
#define LOG_FILE       "airflow.log"
#define SAMPLE_PERIOD  1             /* seconds between samples */
#define MEAS_DELAY_US  45000         /* 45 ms first-measurement wait */
#define PRESSURE_WARN  5.0f          /* Pa threshold for warning */

/* SDP810 command: continuous measurement, no averaging, mass flow */
static const uint8_t CMD_MEASURE[2] = {0x36, 0x2F};

static volatile sig_atomic_t g_running = 1;
static int  g_i2c  = -1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void on_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Sensirion CRC-8 (poly 0x31, init 0xFF, no final XOR)                 */
/* ------------------------------------------------------------------ */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void timestamp_str(char *buf, size_t n)
{
    time_t t = time(NULL);
    struct tm tmv;
    localtime_r(&t, &tmv);
    strftime(buf, n, "%Y-%m-%d %H:%M:%S", &tmv);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c >= 0) {
        i2cClose(g_i2c);
        g_i2c = -1;
    }
    if (g_log) {
        fflush(g_log);
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d). "
                        "Sensor may be absent or bus unavailable.\n", g_i2c);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("Error: cannot open log file");
        i2cClose(g_i2c);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP810-500Pa airflow monitor started.  Logging to %s\n", LOG_FILE);
    printf("Press Ctrl-C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        char ts[32];
        timestamp_str(ts, sizeof(ts));

        /* Send continuous-measurement command */
        if (i2cWriteDevice(g_i2c, (char *)CMD_MEASURE, 2) != 0) {
            fprintf(stderr, "%s  WARN: I2C write failed (sensor absent or bus error).\n", ts);
            fprintf(g_log, "%s,ERROR,I2C_WRITE_FAIL\n", ts);
            fflush(g_log);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        /* Wait for first measurement to be ready */
        gpioDelay(MEAS_DELAY_US);

        /* Read 9 bytes: pressure(2)+crc, temp(2)+crc, scale(2)+crc */
        uint8_t raw[9];
        int n = i2cReadDevice(g_i2c, (char *)raw, 9);
        if (n != 9) {
            fprintf(stderr, "%s  WARN: I2C read returned %d bytes (expected 9).\n", ts, n);
            fprintf(g_log, "%s,ERROR,READ_SHORT,%d\n", ts, n);
            fflush(g_log);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        /* CRC validation */
        if (sensirion_crc8(&raw[0], 2) != raw[2] ||
            sensirion_crc8(&raw[3], 2) != raw[5] ||
            sensirion_crc8(&raw[6], 2) != raw[8]) {
            fprintf(stderr, "%s  WARN: CRC mismatch on sensor data.\n", ts);
            fprintf(g_log, "%s,ERROR,CRC_MISMATCH\n", ts);
            fflush(g_log);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        /* Convert raw big-endian signed 16-bit values */
        int16_t dp_raw = (int16_t)((raw[0] << 8) | raw[1]);
        int16_t t_raw  = (int16_t)((raw[3] << 8) | raw[4]);

        /* SDP810-500Pa: pressure in Pa, temperature in °C */
        float pressure = (float)dp_raw / 20.0f;   /* 500 Pa range -> 20 LSB/Pa */
        float temp     = (float)t_raw / 200.0f;   /* 125 °C range -> 200 LSB/°C */

        /* Log CSV */
        fprintf(g_log, "%s,%.2f,%.2f\n", ts, pressure, temp);
        fflush(g_log);

        /* Threshold check */
        if (pressure > PRESSURE_WARN)
            fprintf(stderr, "%s  WARN: Pressure %.2f Pa exceeds threshold %.1f Pa.\n",
                    ts, pressure, PRESSURE_WARN);

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

