#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define STTS2004_ADDR  0x35
#define LED_GPIO       17
#define TEMP_HIGH      28.0f
#define TEMP_LOW       27.0f
#define I2C_RETRIES    3
#define I2C_RETRY_DELAY_MS 10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static bool g_led_state = false;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write reg 0x%02X failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, I2C_RETRIES, strerror(errno));
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }
        if (read(fd, val, 1) != 1) {
            fprintf(stderr, "I2C read reg 0x%02X failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, I2C_RETRIES, strerror(errno));
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }
        return 0;
    }
    return -1;
}

static int read_temperature(int fd, float *temp_c)
{
    uint8_t raw;
    if (i2c_read_reg8(fd, 0x00, &raw) != 0)
        return -1;

    int16_t signed_raw = (int16_t)raw;
    *temp_c = (float)signed_raw * 0.1f;
    return 0;
}

static int set_led(int state)
{
    int val = state ? 1 : 0;
    if (g_led_state == (bool)state)
        return 0;

    if (g_i2c_fd >= 0) {
        uint8_t reg = 0x01;
        uint8_t cmd = state ? 0x01 : 0x00;
        if (write(g_i2c_fd, &reg, 1) != 1) {
            fprintf(stderr, "Failed to write LED control register: %s\n", strerror(errno));
            return -1;
        }
        if (write(g_i2c_fd, &cmd, 1) != 1) {
            fprintf(stderr, "Failed to set LED state: %s\n", strerror(errno));
            return -1;
        }
    }
    g_led_state = state;
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        set_led(false);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                STTS2004_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("STTS2004 temperature monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temp;
        if (read_temperature(g_i2c_fd, &temp) != 0) {
            fprintf(stderr, "Temperature read failed after retries; exiting.\n");
            break;
        }

        printf("Temperature: %.2f C\n", temp);

        if (temp > TEMP_HIGH && !g_led_state) {
            if (set_led(true) != 0)
                fprintf(stderr, "Warning: failed to turn LED on.\n");
        } else if (temp < TEMP_LOW && g_led_state) {
            if (set_led(false) != 0)
                fprintf(stderr, "Warning: failed to turn LED off.\n");
        }

        sleep(1);
    }

    cleanup();
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

