            fprintf(stderr, "Failed to write LED control register: %s\n", strerror(errno));
            return -1;
        }
        if (write(g_i2c_fd, &cmd, 1) != 1) {
            fprintf(stderr, "Failed to set LED state: %s\n", strerror(errno));
            return -1;
        }
    }
    g_led_state = state;
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        set_led(false);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                STTS2004_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("STTS2004 temperature monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temp;
        if (read_temperature(g_i2c_fd, &temp) != 0) {
            fprintf(stderr, "Temperature read failed after retries; exiting.\n");
            break;
        }

        printf("Temperature: %.2f C\n", temp);

        if (temp > TEMP_HIGH && !g_led_state) {
            if (set_led(true) != 0)
                fprintf(stderr, "Warning: failed to turn LED on.\n");
        } else if (temp < TEMP_LOW && g_led_state) {
            if (set_led(false) != 0)
                fprintf(stderr, "Warning: failed to turn LED off.\n");
        }

        sleep(1);
    }

    cleanup();
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

