#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define LOG_FILE       "environment.log"
#define SAMPLE_PERIOD  60          /* seconds between samples */
#define MAX_RETRIES    3
#define MEASURE_RH_NO_HOLD  0xE5
#define MEASURE_TEMP_NO_HOLD 0xF3
#define READ_TEMP_PREV_RH   0xE0
#define CMD_DELAY_US        20000   /* 20 ms — Si7021 no-hold conversion time */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_fp    = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void timestamp_str(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tmv;
    localtime_r(&t, &tmv);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tmv);
}

static void log_error(const char *msg)
{
    char ts[32];
    timestamp_str(ts, sizeof ts);
    fprintf(stderr, "%s ERROR: %s\n", ts, msg);
    if (g_log_fp) {
        fprintf(g_log_fp, "%s,ERROR,%s\n", ts, msg);
        fflush(g_log_fp);
    }
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint8_t cmd)
{
    char buf[1] = { (char)cmd };
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cWriteDevice(handle, buf, 1);
        if (rc == 0) return 0;
        gpioDelay(10000); /* 10 ms back-off */
    }
    return -1;
}

static int i2c_read_bytes(int handle, uint8_t *buf, uint32_t len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cReadDevice(handle, (char *)buf, len);
        if (rc == (int)len) return 0;
        gpioDelay(10000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Sensor presence check                                              */
/* ------------------------------------------------------------------ */
static int sensor_present(int handle)
{
    /* Read the electronic ID (SNB_0 .. SNB_7, 8 bytes) */
    if (i2c_write_cmd(handle, 0xFA) != 0) return 0;
    gpioDelay(10000);
    uint8_t id[8];
    if (i2c_read_bytes(handle, id, 8) != 0) return 0;
    return 1;
}

/* ------------------------------------------------------------------ */
/* Read RH and Temperature (no-hold + read-previous-temperature path)  */
/* ------------------------------------------------------------------ */
static int read_si7021(int handle, float *temp_c, float *rh_pct)
{
    uint8_t rh_raw[2];
    uint8_t t_raw[2];

    /* 1. Measure RH, no-hold */
    if (i2c_write_cmd(handle, MEASURE_RH_NO_HOLD) != 0) {
        log_error("Failed to write RH measurement command");
        return -1;
    }
    gpioDelay(CMD_DELAY_US);

    if (i2c_read_bytes(handle, rh_raw, 2) != 0) {
        log_error("Failed to read RH measurement");
        return -1;
    }

    /* 2. Read temperature from previous RH measurement */
    if (i2c_write_cmd(handle, READ_TEMP_PREV_RH) != 0) {
        log_error("Failed to write read-previous-temperature command");
        return -1;
    }
    gpioDelay(5000); /* 5 ms */

    if (i2c_read_bytes(handle, t_raw, 2) != 0) {
        log_error("Failed to read temperature from previous RH measurement");
        return -1;
    }

    uint16_t rh_u = ((uint16_t)rh_raw[0] << 8) | rh_raw[1];
    uint16_t t_u  = ((uint16_t)t_raw[0]  << 8) | t_raw[1];

    *rh_pct  = (125.0f * rh_u / 65536.0f) - 6.0f;
    if (*rh_pct < 0.0f)   *rh_pct = 0.0f;
    if (*rh_pct > 100.0f) *rh_pct = 100.0f;

    *temp_c = (175.72f * t_u / 65536.0f) - 46.85f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */
static void log_data(float temp_c, float rh_pct)
{
    char ts[32];
    timestamp_str(ts, sizeof ts);
    fprintf(g_log_fp, "%s,%.2f,%.2f\n", ts, temp_c, rh_pct);
    fflush(g_log_fp);
    printf("%s,%.2f,%.2f\n", ts, temp_c, rh_pct);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X\n",
                I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (!sensor_present(g_i2c_handle)) {
        fprintf(stderr, "Si7021 sensor not detected at 0x%02X\n", I2C_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Failed to open log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(g_log_fp, "# Si7021 logging started — bus %d addr 0x%02X\n",
            I2C_BUS, I2C_ADDR);
    fflush(g_log_fp);

    while (g_running) {
        float temp_c, rh_pct;
        if (read_si7021(g_i2c_handle, &temp_c, &rh_pct) == 0) {
            log_data(temp_c, rh_pct);
        } else {
            log_error("Sensor read failed — continuing");
        }
        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; ++i) {
            sleep(1);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

