                I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (!sensor_present(g_i2c_handle)) {
        fprintf(stderr, "Si7021 sensor not detected at 0x%02X\n", I2C_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Failed to open log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(g_log_fp, "# Si7021 logging started — bus %d addr 0x%02X\n",
            I2C_BUS, I2C_ADDR);
    fflush(g_log_fp);

    while (g_running) {
        float temp_c, rh_pct;
        if (read_si7021(g_i2c_handle, &temp_c, &rh_pct) == 0) {
            log_data(temp_c, rh_pct);
        } else {
            log_error("Sensor read failed — continuing");
        }
        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; ++i) {
            sleep(1);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

