#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define BUFFER_SIZE 100
#define LOG_DIR "/var/log/scd40_data"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"
#define CSV_FILE_PREFIX "scd40_data"
#define CSV_FILE_SUFFIX ".csv"
#define CSV_FILE_PATH_LEN 256
#define MAX_RETRIES 3
#define MEASUREMENT_INTERVAL_US 5000000
#define LOGGING_INTERVAL_US 60000000
#define STARTUP_DELAY_US 1000000

#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F06

typedef struct {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
    uint8_t co2_crc;
    uint8_t temp_crc;
    uint8_t hum_crc;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t running = 1;
static pthread_t logging_thread;

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open error log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_command(int handle, uint16_t command) {
    uint8_t buf[2] = { (uint8_t)(command >> 8), (uint8_t)(command & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 2) {
        log_error("I2C write command failed");
        return -1;
    }
    return 0;
}

static int i2c_read_data(int handle, uint8_t *data, int len) {
    if (i2cReadDevice(handle, (char *)data, len) != len) {
        log_error("I2C read data failed");
        return -1;
    }
    return 0;
}

static int init_i2c() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }
    i2c_handle = i2cOpen(1, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int init_circular_buffer(circular_buffer_t *buf) {
    buf->head = 0;
    buf->tail = 0;
    buf->count = 0;
    if (pthread_mutex_init(&buf->mutex, NULL) != 0) {
        log_error("Mutex initialization failed");
        return -1;
    }
    return 0;
}

static void add_to_buffer(circular_buffer_t *buf, sensor_data_t data) {
    pthread_mutex_lock(&buf->mutex);
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count == BUFFER_SIZE) {
        buf->tail = (buf->tail + 1) % BUFFER_SIZE;
    } else {
        buf->count++;
    }
    pthread_mutex_unlock(&buf->mutex);
}

static int read_scd40_data(sensor_data_t *data) {
    uint8_t raw_data[9];
    if (i2c_write_command(i2c_handle, CMD_READ_MEASUREMENT) != 0) {
        return -1;
    }
    gpioDelay(2000);
    if (i2c_read_data(i2c_handle, raw_data, 9) != 0) {
        return -1;
    }
    if (crc8(&raw_data[0], 2) != raw_data[2] ||
        crc8(&raw_data[3], 2) != raw_data[5] ||
        crc8(&raw_data[6], 2) != raw_data[8]) {
        log_error("CRC check failed");
        return -1;
    }
    data->co2 = (raw_data[0] << 8) | raw_data[1];
    data->temperature = (raw_data[3] << 8) | raw_data[4];
    data->humidity = (raw_data[6] << 8) | raw_data[7];
    data->co2_crc = raw_data[2];
    data->temp_crc = raw_data[5];
    data->hum_crc = raw_data[8];
    return 0;
}

static void *logging_thread_func(void *arg) {
    (void)arg;
    while (running) {
        gpioDelay(LOGGING_INTERVAL_US);
        if (!running) break;
        char filename[CSV_FILE_PATH_LEN];
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        snprintf(filename, sizeof(filename), "%s/%s_%d-%02d-%02d_%02d-%02d-%02d%s",
                 LOG_DIR, CSV_FILE_PREFIX,
                 tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                 tm.tm_hour, tm.tm_min, tm.tm_sec, CSV_FILE_SUFFIX);
        FILE *fp = fopen(filename, "w");
        if (!fp) {
            log_error("Failed to open CSV file for writing");
            continue;
        }
        fprintf(fp, "Timestamp,CO2_ppm,Temperature_C,Humidity_RH\n");
        pthread_mutex_lock(&buffer.mutex);
        for (int i = 0; i < buffer.count; i++) {
            int idx = (buffer.tail + i) % BUFFER_SIZE;
            fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%.2f,%.2f\n",
                    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                    tm.tm_hour, tm.tm_min, tm.tm_sec,
                    buffer.data[idx].co2,
                    (float)buffer.data[idx].temperature / 100.0,
                    (float)buffer.data[idx].humidity / 1000.0);
        }
        pthread_mutex_unlock(&buffer.mutex);
        fclose(fp);
        buffer.head = 0;
        buffer.tail = 0;
        buffer.count = 0;
    }
    return NULL;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup() {
    if (i2c_handle >= 0) {
        i2c_write_command(i2c_handle, CMD_STOP_PERIODIC_MEASUREMENT);
        gpioDelay(500000);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    pthread_mutex_destroy(&buffer.mutex);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() != 0) {
        return 1;
    }
    if (init_circular_buffer(&buffer) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (mkdir(LOG_DIR, 0755) == -1) {
        if (errno != EEXIST) {
            log_error("Failed to create log directory");
            cleanup();
            return 1;
        }
    }
    if (i2c_write_command(i2c_handle, CMD_START_PERIODIC_MEASUREMENT) != 0) {
        cleanup();
        return 1;
    }
    gpioDelay(STARTUP_DELAY_US);
    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        log_error("Failed to create logging thread");
        cleanup();
        return 1;
    }
    while (running) {
        sensor_data_t data;
        if (read_scd40_data(&data) == 0) {
            add_to_buffer(&buffer, data);
        }
        gpioDelay(MEASUREMENT_INTERVAL_US);
    }
    pthread_join(logging_thread, NULL);
    cleanup();
    return 0;
}

