#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define TRIGGER_CMD 0x36
#define READ_CMD 0x00
#define SAMPLE_INTERVAL_SEC 5
#define POST_TRIGGER_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int handle, float *pressure, float *temperature) {
    char buf[4];
    int rc;

    rc = i2cWriteByte(handle, TRIGGER_CMD);
    if (rc < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", rc);
        return -1;
    }

    gpioDelay(POST_TRIGGER_DELAY_US);

    rc = i2cWriteByte(handle, READ_CMD);
    if (rc < 0) {
        fprintf(stderr, "Error writing read command: %d\n", rc);
        return -1;
    }

    rc = i2cReadDevice(handle, buf, 4);
    if (rc != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", rc);
        return -1;
    }

    unsigned int raw_p = ((unsigned int)(unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    unsigned int raw_t = ((unsigned int)(unsigned char)buf[2] << 8) | (unsigned char)buf[3];

    *pressure = (float)raw_p / 65535.0f * 100.0f;
    *temperature = (float)raw_t / 65535.0f * 150.0f - 40.0f;

    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, Pressure: %.2f hPa, Temperature: %.2f C\n", timestamp, pressure, temperature);
    fflush(fp);
    printf("%s, Pressure: %.2f hPa, Temperature: %.2f C\n", timestamp, pressure, temperature);
}

int main(void) {
    int handle;
    float pressure, temperature;
    FILE *fp;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fp = fopen("environmental_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing signal handler\n");
        fclose(fp);
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (read_sensor(handle, &pressure, &temperature) == 0) {
            log_data(fp, pressure, temperature);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping sample\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    fclose(fp);
    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

