/*
 * Raspberry Pi 4 Model B – TDK ICP-10125 barometric pressure monitor
 *
 * Reads pressure + temperature from the ICP-10125 over I2C (bus 1,
 * address 0x60), verifies the CRC-8 checksum, and drives a warning
 * LED on GPIO17 (BCM) at 1 Hz when pressure >= 95 000 Pa and at 5 Hz
 * when pressure < 95 000 Pa.
 *
 * Build:  gcc -O2 -Wall -Wextra -o icp10125_monitor icp10125_monitor.c \
 *            -lgpiod -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x60
#define GPIO_CHIP       "gpiochip4"   /* BCM GPIO bank on Pi 4 */
#define GPIO_OFFSET     17            /* BCM 17 */
#define PRESSURE_THRESHOLD 95000.0f   /* Pa */
#define POLL_INTERVAL_S 1             /* seconds between sensor polls */
#define TRIGGER_DELAY_MS 20           /* ms to wait after a read trigger */

/* ICP-10125 commands (16-bit, big-endian on the bus) */
#define CMD_READ_ID     0xEF80
#define CMD_READ_DATA   0x2860

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static struct gpiod_line *g_led_line = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write16(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write16(0x%04X) failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_n(int fd, uint8_t *buf, size_t n)
{
    size_t total = 0;
    while (total < n) {
        ssize_t r = read(fd, buf + total, n - total);
        if (r < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (r == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += (size_t)r;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (poly 0x31, init 0xFF) – matches ICP-10125 datasheet           */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sensor(int fd, float *pressure, float *temperature)
{
    /* Trigger a measurement */
    if (i2c_write16(fd, CMD_READ_DATA) < 0)
        return -1;

    /* Wait for the conversion to complete (>= 20 ms per datasheet) */
    struct timespec ts = { 0, TRIGGER_DELAY_MS * 1000000L };
    nanosleep(&ts, NULL);

    /* Read 6 bytes: P_MSB, P_LSB, T_MSB, T_LSB, CRC_MSB, CRC_LSB */
    uint8_t raw[6];
    if (i2c_read_n(fd, raw, sizeof(raw)) < 0)
        return -1;

    /* Verify CRC (covers all 6 data bytes) */
    uint8_t calc = crc8(raw, 6);
    if (calc != 0x00) {
        fprintf(stderr, "CRC mismatch: calc=0x%02X recv=0x%02X\n",
                calc, raw[5]);
        return -1;
    }

    /* Assemble 24-bit pressure and temperature values */
    uint32_t p_raw = ((uint32_t)raw[0] << 16) |
                     ((uint32_t)raw[1] << 8)  |
                     ((uint32_t)raw[2]);
    uint32_t t_raw = ((uint32_t)raw[3] << 16) |
                     ((uint32_t)raw[4] << 8)  |
                     ((uint32_t)raw[5]);

    /* Scale factors from datasheet (ICP-10125, 24-bit mode) */
    *pressure    = (float)p_raw / 16777216.0f * 120000.0f - 50000.0f;
    *temperature = (float)t_raw / 16777216.0f * 150.0f - 40.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* LED control                                                         */
/* ------------------------------------------------------------------ */
static void set_led(struct gpiod_line *line, bool on)
{
    if (gpiod_line_set_value(line, on ? 1 : 0) < 0)
        fprintf(stderr, "Warning: failed to set LED: %s\n", strerror(errno));
}

static void blink_led(struct gpiod_line *line, bool warn)
{
    unsigned int on_ms  = warn ? 100 : 500;
    unsigned int off_ms = warn ? 100 : 500;

    set_led(line, true);
    usleep(on_ms * 1000);
    set_led(line, false);
    usleep(off_ms * 1000);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_led_line) {
        gpiod_line_set_value(g_led_line, 0);
        gpiod_line_release(g_led_line);
        g_led_line = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor presence (read ID register) ---- */
    if (i2c_write16(g_i2c_fd, CMD_READ_ID) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X\n", I2C_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }
    uint8_t id[2];
    if (i2c_read_n(g_i2c_fd, id, 2) < 0) {
        fprintf(stderr, "Failed to read sensor ID\n");
        cleanup();
        return EXIT_FAILURE;
    }
    uint16_t sensor_id = ((uint16_t)id[0] << 8) | id[1];
    printf("ICP-10125 detected (ID=0x%04X)\n", sensor_id);

    /* ---- Open GPIO chip and request LED line ---- */
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_led_line = gpiod_chip_get_line(chip, GPIO_OFFSET);
    if (!g_led_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                GPIO_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_led_line, "icp10125_monitor", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n",
                GPIO_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Main loop ---- */
    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;

        if (read_sensor(g_i2c_fd, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n",
                   pressure, temperature);
            blink_led(g_led_line, pressure < PRESSURE_THRESHOLD);
        } else {
            fprintf(stderr, "Sensor read failed; retrying next cycle.\n");
            /* Ensure LED is off on error */
            set_led(g_led_line, false);
        }

        /* Sleep for the remainder of the poll interval */
        struct timespec sleep_ts = { POLL_INTERVAL_S, 0 };
        nanosleep(&sleep_ts, NULL);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

