#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0
#define LOG_FILE "temperature_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000
#define SAMPLE_INTERVAL_US 2000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temp_reg(uint8_t reg, float *temp) {
    int raw;
    for (int i = 0; i < MAX_RETRIES; i++) {
        raw = i2cReadWordData(i2c_handle, reg);
        if (raw >= 0) {
            *temp = (float)((raw * 0.02) - 273.15);
            return 0;
        }
        fprintf(stderr, "I2C read error (reg 0x%02X, attempt %d): %d\n", reg, i + 1, raw);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int log_temperature(float ambient, float object) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, Ambient: %.2f C, Object: %.2f C\n", ts, ambient, object);
    }
    fclose(fp);
    return 0;
}

static void control_fan(float object_temp) {
    static int fan_on = 0;
    if (object_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON (Object: %.2f C)\n", object_temp);
        } else {
            fprintf(stderr, "Failed to turn fan ON\n");
        }
    } else if (object_temp < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (Object: %.2f C)\n", object_temp);
        } else {
            fprintf(stderr, "Failed to turn fan OFF\n");
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", MLX90614_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(FAN_GPIO, 0);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float ambient_temp, object_temp;
        int amb_ok = read_temp_reg(AMBIENT_TEMP_REG, &ambient_temp);
        int obj_ok = read_temp_reg(OBJECT_TEMP_REG, &object_temp);

        if (amb_ok == 0 && obj_ok == 0) {
            printf("Ambient: %.2f C, Object: %.2f C\n", ambient_temp, object_temp);
            log_temperature(ambient_temp, object_temp);
            control_fan(object_temp);
        } else {
            fprintf(stderr, "Sensor read failed; skipping log and fan control.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

