/*
 * HDC2010 Temperature & Humidity Sensor Reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   HDC2010 SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   HDC2010 SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   HDC2010 VDD  -> 3.3 V (pin 1)
 *   HDC2010 GND  -> GND  (pin 6)
 *
 * Build:  gcc -O2 -Wall -Wextra -o hdc2010_reader hdc2010_reader.c -lpigpio -lrt
 * Run:    sudo ./hdc2010_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- HDC2010 register map (from TI HDC2010 datasheet) ---- */
#define HDC2010_ADDR            0x40
#define REG_TEMP_LSB            0x00
#define REG_TEMP_MSB            0x01
#define REG_HUM_LSB             0x02
#define REG_HUM_MSB             0x03
#define REG_MEAS_CFG            0x0F
#define REG_INT_CFG             0x0B
#define REG_MANUFACTURER_ID     0xFE
#define REG_DEVICE_ID           0xFF

#define MEAS_CFG_TEMP_EN        0x01
#define MEAS_CFG_HUM_EN         0x02
#define MEAS_CFG_MEAS_TRIG      0x01
#define MEAS_CFG_MODE_CONT      0x00
#define MEAS_CFG_MODE_SINGLE    0x04

#define EXPECTED_MFR_ID         0x5449
#define EXPECTED_DEV_ID         0x1050

#define I2C_BUS                 1
#define POLL_TIMEOUT_MS         500
#define POLL_INTERVAL_US        10000   /* 10 ms between polls */
#define SAMPLE_INTERVAL_S       5
#define MAX_I2C_RETRIES         3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair.                          */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_reg16(int handle, uint8_t lsb_reg, uint16_t *out)
{
    int lsb = i2cReadByteData(handle, lsb_reg);
    if (lsb < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(0x%02X) failed: %d\n",
                lsb_reg, lsb);
        return -1;
    }
    int msb = i2cReadByteData(handle, lsb_reg + 1);
    if (msb < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(0x%02X) failed: %d\n",
                lsb_reg + 1, msb);
        return -1;
    }
    *out = (uint16_t)((msb << 8) | lsb);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a byte to a register with retry.                              */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int write_reg_retry(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < MAX_I2C_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "[WARN] i2cWriteByteData(0x%02X, 0x%02X) attempt %d/%d failed: %d\n",
                reg, value, attempt + 1, MAX_I2C_RETRIES, rc);
        if (attempt < MAX_I2C_RETRIES - 1)
            gpioDelay(10000); /* 10 ms back-off */
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Trigger a single measurement and wait for completion.               */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int trigger_and_wait(int handle)
{
    /* Single-shot mode: clear continuous bit, set trigger bit */
    if (write_reg_retry(handle, REG_MEAS_CFG,
                        MEAS_CFG_TEMP_EN | MEAS_CFG_HUM_EN |
                        MEAS_CFG_MODE_SINGLE | MEAS_CFG_MEAS_TRIG) != 0)
        return -1;

    uint32_t elapsed = 0;
    while (elapsed < POLL_TIMEOUT_MS * 1000) {
        int cfg = i2cReadByteData(handle, REG_MEAS_CFG);
        if (cfg < 0) {
            fprintf(stderr, "[ERROR] Failed to poll MEAS_CFG: %d\n", cfg);
            return -1;
        }
        if ((cfg & MEAS_CFG_MEAS_TRIG) == 0)
            return 0;          /* measurement complete */
        gpioDelay(POLL_INTERVAL_US);
        elapsed += POLL_INTERVAL_US;
    }
    fprintf(stderr, "[ERROR] Measurement timeout (%d ms)\n", POLL_TIMEOUT_MS);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Verify the sensor identity.                                         */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int verify_sensor(int handle)
{
    int mfr = i2cReadWordData(handle, REG_MANUFACTURER_ID);
    if (mfr < 0) {
        fprintf(stderr, "[ERROR] Cannot read MANUFACTURER_ID: %d\n", mfr);
        return -1;
    }
    if ((uint16_t)mfr != EXPECTED_MFR_ID) {
        fprintf(stderr, "[ERROR] Unexpected MFR ID: 0x%04X (expected 0x%04X)\n",
                (uint16_t)mfr, EXPECTED_MFR_ID);
        return -1;
    }

    int dev = i2cReadWordData(handle, REG_DEVICE_ID);
    if (dev < 0) {
        fprintf(stderr, "[ERROR] Cannot read DEVICE_ID: %d\n", dev);
        return -1;
    }
    if ((uint16_t)dev != EXPECTED_DEV_ID) {
        fprintf(stderr, "[ERROR] Unexpected DEV ID: 0x%04X (expected 0x%04X)\n",
                (uint16_t)dev, EXPECTED_DEV_ID);
        return -1;
    }

    printf("[INFO] HDC2010 verified (MFR=0x%04X, DEV=0x%04X)\n",
           (uint16_t)mfr, (uint16_t)dev);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature and humidity.                                      */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_hdc2010(int handle, float *temperature, float *humidity)
{
    if (trigger_and_wait(handle) != 0)
        return -1;

    uint16_t raw_temp, raw_hum;
    if (read_reg16(handle, REG_TEMP_LSB, &raw_temp) != 0)
        return -1;
    if (read_reg16(handle, REG_HUM_LSB, &raw_hum) != 0)
        return -1;

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)raw_hum  / 65536.0f) * 100.0f;

    /* Sanity-range checks */
    if (*temperature < -40.0f || *temperature > 125.0f) {
        fprintf(stderr, "[WARN] Temperature out of range: %.2f C\n", *temperature);
    }
    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "[WARN] Humidity out of range: %.2f %%\n", *humidity);
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at HDC2010 address --- */
    g_i2c_handle = i2cOpen(I2C_BUS, HDC2010_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, HDC2010_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Verify sensor identity --- */
    if (verify_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "[ERROR] HDC2010 not detected at 0x%02X\n", HDC2010_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main sampling loop --- */
    while (g_running) {
        float temperature, humidity;

        if (read_hdc2010(g_i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "[ERROR] Failed to read sensor data\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    /* --- Clean shutdown --- */
    printf("\n[INFO] Shutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

