/*
 * Raspberry Pi 3 Model B+ — Sensirion SDP800-500Pa differential pressure logger
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * I2C address: 0x25 (7-bit)
 * Measurement command: 0x361F (trigger single measurement, no averaging)
 * Conversion time: ~45 ms
 * Data format: [P_msb, P_lsb, P_crc, T_msb, T_lsb, T_crc]
 *   P = (P_msb << 8) | P_lsb   (signed 16-bit, Pa)
 *   T = (T_msb << 8) | T_lsb   (signed 16-bit, °C × 200)
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp800_logger sdp800_logger.c -lpigpio -lrt
 * Run:    sudo ./sdp800_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP800_ADDR    0x25          /* Sensirion SDP800-500Pa 7-bit I2C address */
#define MEASURE_CMD    0x361F        /* single measurement, no averaging */
#define MEASURE_DELAY  45000         /* 45 ms in microseconds */
#define LOOP_DELAY     500000        /* 500 ms in microseconds */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)               */
/* ------------------------------------------------------------------ */
static bool crc8_ok(const uint8_t *data, uint8_t len, uint8_t expected)
{
    uint8_t crc = 0xFF;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc == expected;
}

/* ------------------------------------------------------------------ */
/* Read one measurement from the SDP800                               */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_sdp800(int handle, int16_t *pressure, int16_t *temperature)
{
    uint8_t cmd[2] = {
        (uint8_t)(MEASURE_CMD >> 8),
        (uint8_t)(MEASURE_CMD & 0xFF)
    };
    uint8_t buf[6];

    /* Send measurement command */
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed\n");
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(MEASURE_DELAY);

    /* Read 6 bytes: P_msb, P_lsb, P_crc, T_msb, T_lsb, T_crc */
    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed (sensor absent or bus error)\n");
        return -1;
    }

    /* Validate CRCs */
    if (!crc8_ok(&buf[0], 2, buf[2])) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch\n");
        return -1;
    }
    if (!crc8_ok(&buf[3], 2, buf[5])) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }

    /* Convert raw values */
    *pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[3] << 8) | buf[4]);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d) — check wiring and address\n",
                g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP800-500Pa logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t pressure = 0, temperature = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_sdp800(g_i2c_handle, &pressure, &temperature) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(10000); /* 10 ms back-off before retry */
        }

        if (ok) {
            printf("Pressure: %d Pa, Temperature: %d * 200 °C\n",
                   pressure, temperature);
        } else {
            fprintf(stderr, "[WARN] Measurement failed after %d attempts\n", MAX_RETRIES);
        }

        /* Sleep 500 ms (interruptible by signals) */
        for (int i = 0; i < 50 && g_running; i++)
            gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

