#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 4000000
#define SPI_FLAGS 0
#define RELAY_GPIO 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define MAX_PROFILE_POINTS 100
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 3

typedef struct {
    float kp, ki, kd;
    float integral, prev_error;
} PIDController;

typedef struct {
    float time;
    float temperature;
} ProfilePoint;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;
static ProfilePoint profile[MAX_PROFILE_POINTS];
static int profile_count = 0;
static int current_profile_index = 0;
static float current_target_temp = 0.0f;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max6675(int handle, float *temperature) {
    char tx[2] = {0, 0};
    char rx[2] = {0, 0};
    int ret = spiXfer(handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    if (rx[1] & 0x04) {
        fprintf(stderr, "MAX6675 fault detected\n");
        return -1;
    }
    int raw = ((rx[0] << 8) | rx[1]) >> 3;
    *temperature = raw * 0.25f;
    return 0;
}

static float pid_calculate(PIDController *pid, float setpoint, float actual) {
    float error = setpoint - actual;
    pid->integral += error;
    float derivative = error - pid->prev_error;
    float output = pid->kp * error + pid->ki * pid->integral + pid->kd * derivative;
    pid->prev_error = error;
    if (output < 0.0f) output = 0.0f;
    if (output > 1.0f) output = 1.0f;
    return output;
}

static int load_profile(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Failed to open profile file: %s\n", strerror(errno));
        return -1;
    }
    char line[256];
    int i = 0;
    while (fgets(line, sizeof(line), fp) && i < MAX_PROFILE_POINTS) {
        if (line[0] == '#' || line[0] == '\n' || line[0] == '\0') continue;
        if (sscanf(line, "%f,%f", &profile[i].time, &profile[i].temperature) == 2) {
            i++;
        } else {
            fprintf(stderr, "Invalid line in profile: %s", line);
        }
    }
    fclose(fp);
    profile_count = i;
    if (profile_count == 0) {
        fprintf(stderr, "No valid profile points found\n");
        return -1;
    }
    return 0;
}

static void log_temperature(float temp) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay GPIO mode\n");
        cleanup();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (load_profile(PROFILE_FILE) != 0) {
        cleanup();
        return 1;
    }

    PIDController pid = {0.1f, 0.01f, 0.001f, 0.0f, 0.0f};

    while (running) {
        float temp = NAN;
        int ok = 0;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (read_max6675(spi_handle, &temp) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(100000);
        }
        if (!ok) {
            fprintf(stderr, "Sensor read failed after %d attempts\n", MAX_RETRIES);
            gpioWrite(RELAY_GPIO, 0);
            log_temperature(NAN);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (current_profile_index < profile_count) {
            current_target_temp = profile[current_profile_index].temperature;
            if (temp >= current_target_temp) {
                current_profile_index++;
            }
        }

        float duty = pid_calculate(&pid, current_target_temp, temp);
        gpioPWM(RELAY_GPIO, (int)(duty * 255.0f));
        log_temperature(temp);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

