/*
 * Greenhouse heater controller — Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   DS18B20 1-wire data  -> GPIO4  (physical pin 7)
 *   Relay enable         -> GPIO17 (physical pin 11)
 *   PWM duty control     -> GPIO18 (physical pin 12, hardware PWM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o greenhouse greenhouse.c -lpigpio -lrt
 *   (pigpio must be installed; run as root or with appropriate permissions.)
 *
 * Usage:
 *   ./greenhouse <setpoint_C> <Kp> <Ki> <Kd>
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

#define DS18B20_GPIO          4
#define RELAY_GPIO            17
#define PWM_GPIO              18

#define PWM_RANGE             1000
#define PWM_FREQ              1000   /* Hz — 1 kHz hardware PWM */
#define LOG_INTERVAL_SEC      5
#define SAMPLE_PERIOD_US      200000 /* 200 ms */
#define MAX_SENSORS           8
#define DS18B20_BASE          "/sys/bus/w1/devices/"
#define DS18B20_ID_PREFIX    "28-"
#define DS18B20_ID_LEN        16     /* "28-" + 12 hex chars + NUL */
#define DS18B20_PATH_LEN      64

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* DS18B20 helpers                                                     */
/* ------------------------------------------------------------------ */

/*
 * Scan /sys/bus/w1/devices for DS18B20 sensors (28-xxxx...).
 * Returns the number of sensors found, or -1 on error.
 */
static int find_ds18b20_sensors(char ids[][DS18B20_ID_LEN], int max_sensors)
{
    FILE *fp = NULL;
    char line[256];
    int count = 0;

    fp = fopen("/sys/bus/w1/devices/w1_bus_master1/w1_master_slaves", "r");
    if (fp == NULL) {
        /* Fallback: try the directory listing (older kernel layouts). */
        fp = fopen("/sys/bus/w1/devices/", "r");
        if (fp == NULL) {
            fprintf(stderr, "Error opening 1-wire device directory: %s\n",
                    strerror(errno));
            return -1;
        }
        /* Directory listing path — parse lines to extract IDs. */
        while (fgets(line, sizeof(line), fp) != NULL) {
            char *p = line;
            while (*p == ' ' || *p == '\t') p++;
            if (strncmp(p, DS18B20_ID_PREFIX, 3) == 0) {
                if (count < max_sensors) {
                    strncpy(ids[count], p, DS18B20_ID_LEN - 1);
                    ids[count][DS18B20_ID_LEN - 1] = '\0';
                    count++;
                }
            }
        }
        fclose(fp);
        return count;
    }

    /* w1_master_slaves file path — IDs are already listed. */
    while (fgets(line, sizeof(line), fp) != NULL) {
        char *p = line;
        while (*p == ' ' || *p == '\t') p++;
        if (strncmp(p, DS18B20_ID_PREFIX, 3) == 0) {
            if (count < max_sensors) {
                strncpy(ids[count], p, DS18B20_ID_LEN - 1);
                ids[count][DS18B20_ID_LEN - 1] = '\0';
                count++;
            }
        }
    }
    fclose(fp);
    return count;
}

/*
 * Read temperature from a single DS18B20 sensor.
 * Returns 0 on success and stores the temperature in *temp_c;
 * returns -1 on error or if the sensor is absent.
 */
static int read_ds18b20(const char *sensor_id, float *temp_c)
{
    char path[DS18B20_PATH_LEN];
    FILE *fp = NULL;
    char line[256];
    int crc_ok = 0;
    float temperature = NAN;

    snprintf(path, sizeof(path), "%s%s/w1_slave",
             DS18B20_BASE, sensor_id);

    fp = fopen(path, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    /* Read the two lines produced by the DS18B20 driver. */
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading CRC line from %s\n", path);
        fclose(fp);
        return -1;
    }

    /* The first line ends with YES if the CRC is valid, NO otherwise. */
    if (strstr(line, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for sensor %s\n", sensor_id);
        fclose(fp);
        return -1;
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading temperature line from %s\n", path);
        fclose(fp);
        return -1;
    }

    fclose(fp);

    /* Parse the temperature value (e.g., "t=23456"). */
    char *t_ptr = strstr(line, "t=");
    if (t_ptr == NULL) {
        fprintf(stderr, "Temperature field not found in %s\n", path);
        return -1;
    }

    long raw = strtol(t_ptr + 2, NULL, 10);
    if (raw == 0 && errno == EINVAL) {
        fprintf(stderr, "Invalid temperature value in %s\n", path);
        return -1;
    }

    temperature = (float)raw / 1000.0f;
    *temp_c = temperature;
    return 0;
}

/* ------------------------------------------------------------------ */
/* PID controller                                                      */
/* ------------------------------------------------------------------ */
static float calculate_pid(float setpoint, float actual,
                            float Kp, float Ki, float Kd,
                            float *integral, float *prev_error)
{
    float error = setpoint - actual;
    *integral += error;

    /* Anti-windup clamp */
    if (*integral > 100.0f)  *integral = 100.0f;
    if (*integral < -100.0f) *integral = -100.0f;

    float derivative = error - *prev_error;
    float output = Kp * error + Ki * (*integral) + Kd * derivative;

    *prev_error = error;
    return output;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float avg_temp, float setpoint, float pid_out, int duty)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_fp,
            "%s, Temp: %.2f C, Setpoint: %.2f C, PID: %.2f, PWM: %d\n",
            timestamp, avg_temp, setpoint, pid_out, duty);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure relay is off and PWM is stopped. */
    gpioWrite(RELAY_GPIO, 0);
    gpioPWM(PWM_GPIO, 0);

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    float setpoint, Kp, Ki, Kd;
    char sensor_ids[MAX_SENSORS][DS18B20_ID_LEN];
    int num_sensors;
    float integral = 0.0f;
    float prev_error = 0.0f;
    int duty_cycle = 0;
    int relay_state = 0;

    if (argc != 5) {
        fprintf(stderr,
                "Usage: %s <setpoint_C> <Kp> <Ki> <Kd>\n", argv[0]);
        return EXIT_FAILURE;
    }

    setpoint = strtof(argv[1], NULL);
    Kp = strtof(argv[2], NULL);
    Ki = strtof(argv[3], NULL);
    Kd = strtof(argv[4], NULL);

    if (isnan(setpoint) || isnan(Kp) || isnan(Ki) || isnan(Kd)) {
        fprintf(stderr, "Error: Invalid floating-point input.\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO. */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay GPIO mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    /* Configure PWM GPIO. */
    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set PWM GPIO mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioPWM(PWM_GPIO, 0);

    /* Find DS18B20 sensors. */
    num_sensors = find_ds18b20_sensors(sensor_ids, MAX_SENSORS);
    if (num_sensors <= 0) {
        fprintf(stderr, "No DS18B20 sensors found. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    printf("Found %d DS18B20 sensor(s).\n", num_sensors);

    /* Open log file. */
    g_log_fp = fopen("greenhouse.log", "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    install_signal_handlers();

    time_t last_log_time = time(NULL);

    while (g_running) {
        float sum_temp = 0.0f;
        int valid_readings = 0;

        for (int i = 0; i < num_sensors; i++) {
            float temp;
            if (read_ds18b20(sensor_ids[i], &temp) == 0) {
                sum_temp += temp;
                valid_readings++;
            } else {
                fprintf(stderr, "Error reading sensor %s\n",
                        sensor_ids[i]);
            }
        }

        float avg_temp = NAN;
        if (valid_readings > 0) {
            avg_temp = sum_temp / (float)valid_readings;
        } else {
            fprintf(stderr, "No valid temperature readings. "
                            "Setting output to 0.\n");
            integral = 0.0f;
            prev_error = 0.0f;
            duty_cycle = 0;
            gpioPWM(PWM_GPIO, 0);
            relay_state = 0;
            gpioWrite(RELAY_GPIO, 0);
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float pid_output = calculate_pid(setpoint, avg_temp,
                                          Kp, Ki, Kd,
                                          &integral, &prev_error);

        /* Clamp PID output to [0, 100]. */
        if (pid_output < 0.0f) pid_output = 0.0f;
        if (pid_output > 100.0f) pid_output = 100.0f;

        duty_cycle = (int)(pid_output * (PWM_RANGE / 100.0f));

        /* Set PWM duty cycle. */
        if (gpioPWM(PWM_GPIO, duty_cycle) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
        }

        /* Control relay based on PID output. */
        if (pid_output > 0.0f) {
            if (relay_state == 0) {
                if (gpioWrite(RELAY_GPIO, 1) == 0) {
                    relay_state = 1;
                } else {
                    fprintf(stderr, "Failed to activate relay\n");
                }
            }
        } else {
            if (relay_state == 1) {
                if (gpioWrite(RELAY_GPIO, 0) == 0) {
                    relay_state = 0;
                } else {
                    fprintf(stderr, "Failed to deactivate relay\n");
                }
            }
        }

        /* Log data every LOG_INTERVAL_SEC seconds. */
        time_t current_time = time(NULL);
        if (difftime(current_time, last_log_time) >= LOG_INTERVAL_SEC) {
            log_data(avg_temp, setpoint, pid_output, duty_cycle);
            last_log_time = current_time;
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

