    if (*integral < -100.0f) *integral = -100.0f;

    float derivative = error - *prev_error;
    float output = Kp * error + Ki * (*integral) + Kd * derivative;

    *prev_error = error;
    return output;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float avg_temp, float setpoint, float pid_out, int duty)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_fp,
            "%s, Temp: %.2f C, Setpoint: %.2f C, PID: %.2f, PWM: %d\n",
            timestamp, avg_temp, setpoint, pid_out, duty);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure relay is off and PWM is stopped. */
    gpioWrite(RELAY_GPIO, 0);
    gpioPWM(PWM_GPIO, 0);

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    float setpoint, Kp, Ki, Kd;
    char sensor_ids[MAX_SENSORS][DS18B20_ID_LEN];
    int num_sensors;
    float integral = 0.0f;
    float prev_error = 0.0f;
    int duty_cycle = 0;
    int relay_state = 0;

    if (argc != 5) {
        fprintf(stderr,
                "Usage: %s <setpoint_C> <Kp> <Ki> <Kd>\n", argv[0]);
        return EXIT_FAILURE;
    }

    setpoint = strtof(argv[1], NULL);
    Kp = strtof(argv[2], NULL);
    Ki = strtof(argv[3], NULL);
    Kd = strtof(argv[4], NULL);

    if (isnan(setpoint) || isnan(Kp) || isnan(Ki) || isnan(Kd)) {
        fprintf(stderr, "Error: Invalid floating-point input.\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO. */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay GPIO mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    /* Configure PWM GPIO. */
    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set PWM GPIO mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioPWM(PWM_GPIO, 0);

    /* Find DS18B20 sensors. */
    num_sensors = find_ds18b20_sensors(sensor_ids, MAX_SENSORS);
    if (num_sensors <= 0) {
        fprintf(stderr, "No DS18B20 sensors found. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    printf("Found %d DS18B20 sensor(s).\n", num_sensors);

    /* Open log file. */
    g_log_fp = fopen("greenhouse.log", "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    install_signal_handlers();

    time_t last_log_time = time(NULL);

    while (g_running) {
        float sum_temp = 0.0f;
        int valid_readings = 0;

        for (int i = 0; i < num_sensors; i++) {
            float temp;
            if (read_ds18b20(sensor_ids[i], &temp) == 0) {
                sum_temp += temp;
                valid_readings++;
            } else {
                fprintf(stderr, "Error reading sensor %s\n",
                        sensor_ids[i]);
            }
        }

        float avg_temp = NAN;
        if (valid_readings > 0) {
            avg_temp = sum_temp / (float)valid_readings;
        } else {
            fprintf(stderr, "No valid temperature readings. "
                            "Setting output to 0.\n");
            integral = 0.0f;
            prev_error = 0.0f;
            duty_cycle = 0;
            gpioPWM(PWM_GPIO, 0);
            relay_state = 0;
            gpioWrite(RELAY_GPIO, 0);
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float pid_output = calculate_pid(setpoint, avg_temp,
                                          Kp, Ki, Kd,
                                          &integral, &prev_error);

        /* Clamp PID output to [0, 100]. */
        if (pid_output < 0.0f) pid_output = 0.0f;
        if (pid_output > 100.0f) pid_output = 100.0f;

        duty_cycle = (int)(pid_output * (PWM_RANGE / 100.0f));

        /* Set PWM duty cycle. */
        if (gpioPWM(PWM_GPIO, duty_cycle) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
        }

        /* Control relay based on PID output. */
        if (pid_output > 0.0f) {
            if (relay_state == 0) {
                if (gpioWrite(RELAY_GPIO, 1) == 0) {
                    relay_state = 1;
                } else {
                    fprintf(stderr, "Failed to activate relay\n");
                }
            }
        } else {
            if (relay_state == 1) {
                if (gpioWrite(RELAY_GPIO, 0) == 0) {
                    relay_state = 0;
                } else {
                    fprintf(stderr, "Failed to deactivate relay\n");
                }
            }
        }

        /* Log data every LOG_INTERVAL_SEC seconds. */
        time_t current_time = time(NULL);
        if (difftime(current_time, last_log_time) >= LOG_INTERVAL_SEC) {
            log_data(avg_temp, setpoint, pid_output, duty_cycle);
            last_log_time = current_time;
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

