/*
 * AHT20 humidity monitor with dehumidifier relay control.
 *
 * Board:  Raspberry Pi 5 (BCM GPIO numbering)
 * Sensor: AHT20 on /dev/i2c-1, address 0x38
 * Relay:  active-high on GPIO17
 *
 * Build:  gcc -O2 -Wall -Wextra -o aht20_dehumidifier aht20_dehumidifier.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define AHT20_ADDR     0x38
#define GPIO_CHIP       "gpiochip4"   /* RP1 on Pi 5 */
#define GPIO_LINE       17
#define HUMIDITY_HIGH   60.0f
#define HUMIDITY_LOW    55.0f
#define POLL_INTERVAL   5            /* seconds */
#define MAX_RETRIES     3
#define RETRY_DELAY_MS  10
#define MEASURE_DELAY_MS 80

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/*
 * Trigger a measurement and read the 6-byte result.
 * Returns 0 on success, -1 on failure.
 */
static int aht20_read(int fd, float *humidity)
{
    uint8_t cmd[3] = { 0xAC, 0x33, 0x00 };
    uint8_t data[6];
    int retries = MAX_RETRIES;

    while (retries > 0) {
        if (write(fd, cmd, sizeof(cmd)) != (ssize_t)sizeof(cmd)) {
            fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
            retries--;
            if (retries > 0) sleep_ms(RETRY_DELAY_MS);
            continue;
        }

        sleep_ms(MEASURE_DELAY_MS);

        ssize_t n = read(fd, data, sizeof(data));
        if (n != (ssize_t)sizeof(data)) {
            fprintf(stderr, "I2C read failed: %s (got %zd bytes)\n",
                    n < 0 ? strerror(errno) : "short read", n);
            retries--;
            if (retries > 0) sleep_ms(RETRY_DELAY_MS);
            continue;
        }

        /* Bit 7 of byte 0 indicates busy; bit 3 indicates calibrated. */
        if (data[0] & 0x80) {
            fprintf(stderr, "AHT20 busy after measurement\n");
            retries--;
            if (retries > 0) sleep_ms(RETRY_DELAY_MS);
            continue;
        }
        if (!(data[0] & 0x08)) {
            fprintf(stderr, "AHT20 not calibrated\n");
            retries--;
            if (retries > 0) sleep_ms(RETRY_DELAY_MS);
            continue;
        }

        uint32_t raw = ((uint32_t)data[1] << 12) |
                       ((uint32_t)data[2] << 4)  |
                       ((uint32_t)data[3] >> 4);
        *humidity = ((float)raw / 1048576.0f) * 100.0f;
        return 0;
    }

    return -1;
}

int main(void)
{
    int fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa = { .sa_handler = sig_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        goto cleanup;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                AHT20_ADDR, strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "aht20_dehumidifier", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n",
                GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    printf("AHT20 humidity monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float humidity = 0.0f;

        if (aht20_read(fd, &humidity) == 0) {
            time_t now = time(NULL);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S",
                     localtime(&now));
            printf("[%s] Humidity: %.2f%%\n", ts, humidity);

            if (humidity > HUMIDITY_HIGH) {
                if (gpiod_line_set_value(line, 1) < 0)
                    fprintf(stderr, "Failed to activate relay: %s\n",
                            strerror(errno));
                else
                    printf("Humidity above threshold, dehumidifier ON\n");
            } else if (humidity < HUMIDITY_LOW) {
                if (gpiod_line_set_value(line, 0) < 0)
                    fprintf(stderr, "Failed to deactivate relay: %s\n",
                            strerror(errno));
                else
                    printf("Humidity below threshold, dehumidifier OFF\n");
            }
        } else {
            fprintf(stderr, "Failed to read humidity after %d retries.\n",
                    MAX_RETRIES);
        }

        /* Sleep in 100 ms increments so signals are caught promptly. */
        for (int i = 0; i < POLL_INTERVAL * 10 && g_running; i++)
            sleep_ms(100);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    if (fd >= 0) close(fd);
    return ret;
}

