#include <syslog.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define HTU21D_ADDR    0x40
#define HTU21D_CMD_HUM 0xE5
#define API_ENDPOINT   "http://api.example.com/humidity"
#define SERVER_IP      "192.168.1.100"
#define SERVER_PORT    80
#define POLL_INTERVAL  60

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else           crc <<= 1;
        }
    }
    return crc;
}

static int i2c_read_humidity(int fd, float *humidity) {
    uint8_t cmd = HTU21D_CMD_HUM;
    if (write(fd, &cmd, 1) != 1) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }
    usleep(50000);

    uint8_t buf[3];
    ssize_t n = read(fd, buf, 3);
    if (n != 3) {
        syslog(LOG_ERR, "I2C read failed: expected 3 bytes, got %zd (%s)", n, strerror(errno));
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        syslog(LOG_ERR, "CRC mismatch on humidity data");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    raw &= 0xFFFC;
    *humidity = -6.0f + 125.0f * (float)raw / 65536.0f;
    if (*humidity < 0.0f) *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;
    return 0;
}

static int http_post_data(float humidity) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "socket() failed: %s", strerror(errno));
        return -1;
    }

    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "inet_pton() failed for %s", SERVER_IP);
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "connect() failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    char json[128];
    snprintf(json, sizeof(json), "{\"humidity\": %.2f}", humidity);

    char request[512];
    snprintf(request, sizeof(request),
             "POST %s HTTP/1.1\r\n"
             "Host: %s\r\n"
             "Content-Type: application/json\r\n"
             "Content-Length: %zu\r\n"
             "Connection: close\r\n"
             "\r\n"
             "%s",
             API_ENDPOINT, SERVER_IP, strlen(json), json);

    size_t total = strlen(request);
    size_t sent = 0;
    while (sent < total) {
        ssize_t w = write(sockfd, request + sent, total - sent);
        if (w < 0) {
            if (errno == EINTR) continue;
            syslog(LOG_ERR, "write() failed: %s", strerror(errno));
            close(sockfd);
            return -1;
        }
        sent += w;
    }

    char response[1024];
    ssize_t r = read(sockfd, response, sizeof(response) - 1);
    if (r < 0) {
        syslog(LOG_ERR, "read() failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }
    response[r] = '\0';

    close(sockfd);

    if (strstr(response, "200 OK") == NULL) {
        syslog(LOG_ERR, "HTTP request failed: %s", response);
        return -1;
    }
    return 0;
}

int main(void) {
    openlog("htu21d_humidity", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction() failed: %s", strerror(errno));
        closelog();
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "open(%s) failed: %s", I2C_BUS, strerror(errno));
        closelog();
