}

static int read_bmp280(int handle, double *temperature, double *pressure) {
    uint8_t data[6];
    if (i2c_read_reg(handle, BMP280_PRESS_MSB_REG, data, 6) != 0) return -1;
    int32_t raw_pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    *temperature = compensate_temperature(raw_temperature) / 100.0;
    *pressure = compensate_pressure(raw_pressure) / 256.0 / 100.0;
    return 0;
}

static void log_pressure(double pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Pressure: %.2f hPa\n", s, pressure);
    fclose(fp);
}

static int initialize_bmp280(int handle) {
    uint8_t chip_id;
    if (i2c_read_reg(handle, BMP280_CHIP_ID_REG, &chip_id, 1) != 0) return -1;
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID: 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write_reg(handle, BMP280_RESET_REG, BMP280_RESET_CMD) != 0) return -1;
    gpioDelay(10000);
    if (read_calibration_data(handle) != 0) return -1;
    if (i2c_write_reg(handle, BMP280_CONFIG_REG, 0x00) != 0) return -1;
    if (i2c_write_reg(handle, BMP280_CTRL_MEAS_REG, 0x27) != 0) return -1;
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_bmp280(i2c_handle) != 0) {
        fprintf(stderr, "BMP280 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("BMP280 initialized successfully. Monitoring pressure...\n");

    while (running) {
        double temperature, pressure;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !success) {
            if (read_bmp280(i2c_handle, &temperature, &pressure) == 0) {
                success = 1;
            } else {
                fprintf(stderr, "Error reading BMP280, retrying... (%d/%d)\n", retries + 1, MAX_RETRIES);
                i2cClose(i2c_handle);
                gpioDelay(100000);
                i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
                if (i2c_handle < 0) {
                    fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                    break;
                }
                if (initialize_bmp280(i2c_handle) != 0) {
                    fprintf(stderr, "BMP280 re-initialization failed\n");
                    i2cClose(i2c_handle);
                    i2c_handle = -1;
                    break;
                }
                retries++;
            }
        }

        if (success) {
            printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temperature, pressure);
            if (pressure > PRESSURE_HIGH_THRESHOLD || pressure < PRESSURE_LOW_THRESHOLD) {
                log_pressure(pressure);
            }
        } else {
            fprintf(stderr, "Failed to read BMP280 after %d retries\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

