/*
 * Raspberry Pi 4B — TMP117 temperature, AHT20 humidity, PIR motion logger.
 *
 * Build:  gcc -O2 -Wall -Wextra -o logger logger.c -lgpiod -lrt
 * Run:    sudo ./logger
 *
 * Hardware:
 *   TMP117  I2C 0x48  on /dev/i2c-1
 *   AHT20   I2C 0x38  on /dev/i2c-1
 *   PIR     GPIO17    (gpiochip4 line 17, input)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMP117_ADDR    0x48
#define AHT20_ADDR     0x38
#define PIR_CHIP       "gpiochip4"
#define PIR_LINE       17

#define TMP117_REG_TEMP 0x00
#define TMP117_REG_CONFIG 0x01

#define AHT20_CMD_INIT   0xBE
#define AHT20_CMD_MEAS   0xAC
#define AHT20_CMD_RESET  0xBA

#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_pir = NULL;

static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

static void msleep(unsigned ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static int i2c_write(int fd, uint8_t addr, const uint8_t *buf, size_t len)
{
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        return -1;
    }
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "write(0x%02X, %zu): %s\n", addr, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t addr, uint8_t *buf, size_t len)
{
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "read(0x%02X, %zu): got %zd (%s)\n",
                addr, len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

static int init_i2c(void)
{
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_aht20(void)
{
    uint8_t cmd = AHT20_CMD_RESET;
    if (i2c_write(g_i2c_fd, AHT20_ADDR, &cmd, 1) < 0) return -1;
    msleep(20);

    cmd = AHT20_CMD_INIT;
    if (i2c_write(g_i2c_fd, AHT20_ADDR, &cmd, 1) < 0) return -1;
    msleep(10);
    return 0;
}

static int read_aht20(float *humidity)
{
    uint8_t cmd = AHT20_CMD_MEAS;
    if (i2c_write(g_i2c_fd, AHT20_ADDR, &cmd, 1) < 0) return -1;
    msleep(80);

    uint8_t buf[7];
    if (i2c_read(g_i2c_fd, AHT20_ADDR, buf, 7) < 0) return -1;

    if (buf[0] & 0x80) {
        fprintf(stderr, "AHT20 busy after measurement\n");
        return -1;
    }
    uint32_t raw = ((uint32_t)buf[1] << 12) |
                   ((uint32_t)buf[2] << 4)  |
                   ((uint32_t)buf[3] >> 4);
    *humidity = ((float)raw / 1048576.0f) * 100.0f;
    return 0;
}

static int read_tmp117(float *temperature)
{
    uint8_t buf[2];
    if (i2c_read(g_i2c_fd, TMP117_ADDR, buf, 2) < 0) return -1;
    int16_t raw = (int16_t)((buf[0] << 4) | (buf[1] >> 4));
    *temperature = (float)raw * 0.0078125f;
    return 0;
}

static int read_pir(void)
{
    int val = gpiod_line_get_value(g_pir);
    if (val < 0) {
        fprintf(stderr, "gpiod_line_get_value: %s\n", strerror(errno));
        return 0;
    }
    return val;
}

static int open_log_file(void)
{
    time_t now = time(NULL);
    struct tm tmv;
    localtime_r(&now, &tmv);
    char filename[64];
    strftime(filename, sizeof(filename), "sensor_data_%Y-%m-%d.csv", &tmv);

    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", filename, strerror(errno));
        return -1;
    }

    long pos = ftell(fp);
    if (pos == 0) {
        fprintf(fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
        fflush(fp);
    }
    return 0;
}

static void log_data(float temp, float hum, int motion)
{
    time_t now = time(NULL);
    struct tm tmv;
    localtime_r(&now, &tmv);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
    fprintf(g_log_fp, "%s,%.2f,%.2f,%d\n", ts, temp, hum, motion);
    fflush(g_log_fp);
}

static void cleanup(void)
{
    if (g_log_fp) { fclose(g_log_fp); g_log_fp = NULL; }
    if (g_pir)    { gpiod_line_release(g_pir); g_pir = NULL; }
    if (g_chip)   { gpiod_chip_close(g_chip); g_chip = NULL; }
    if (g_i2c_fd >= 0) { close(g_i2c_fd); g_i2c_fd = -1; }
}

int main(void)
{
    struct sigaction sa = { .sa_handler = handle_signal };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() < 0) { cleanup(); return 1; }

    if (init_aht20() < 0)
        fprintf(stderr, "Warning: AHT20 init failed (sensor may be absent)\n");

    g_chip = gpiod_chip_open_by_name(PIR_CHIP);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s): %s\n", PIR_CHIP, strerror(errno));
        cleanup(); return 1;
    }
    g_pir = gpiod_chip_get_line(g_chip, PIR_LINE);
    if (!g_pir) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", PIR_LINE, strerror(errno));
        cleanup(); return 1;
    }
    if (gpiod_line_request_input(g_pir, "pir_sensor") < 0) {
        fprintf(stderr, "gpiod_line_request_input: %s\n", strerror(errno));
        cleanup(); return 1;
    }

    if (open_log_file() < 0) { cleanup(); return 1; }

    while (g_running) {
        float temp = 0.0f, hum = 0.0f;
        int motion = 0;
        int ok = 1;

        for (int r = 0; r < MAX_RETRIES && ok; r++) {
            if (read_tmp117(&temp) == 0) break;
            if (r < MAX_RETRIES - 1) msleep(RETRY_DELAY_MS);
            else ok = 0;
        }
        if (!ok) { fprintf(stderr, "TMP117 read failed after retries\n"); temp = -99.0f; }

        ok = 1;
        for (int r = 0; r < MAX_RETRIES && ok; r++) {
            if (read_aht20(&hum) == 0) break;
            if (r < MAX_RETRIES - 1) msleep(RETRY_DELAY_MS);
            else ok = 0;
        }
        if (!ok) { fprintf(stderr, "AHT20 read failed after retries\n"); hum = -1.0f; }

        motion = read_pir();

        log_data(temp, hum, motion);
        sleep(1);
    }

    cleanup();
    return 0;
}

