#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define RAIN_SENSOR_PIN  17
#define MOTOR_ENA_PIN    22
#define MOTOR_IN1_PIN    23
#define MOTOR_IN2_PIN    24

#define POLL_INTERVAL_SEC  2
#define MOTOR_RUN_SEC      5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_timestamp(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static int safe_set_value(struct gpiod_line *line, int val, const char *label)
{
    if (gpiod_line_set_value(line, val) < 0) {
        fprintf(stderr, "Error setting %s to %d: %s\n", label, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int motor_stop(struct gpiod_line *ena, struct gpiod_line *in1,
                       struct gpiod_line *in2)
{
    if (safe_set_value(ena, 0, "ENA") < 0) return -1;
    if (safe_set_value(in1, 0, "IN1") < 0) return -1;
    if (safe_set_value(in2, 0, "IN2") < 0) return -1;
    return 0;
}

static int motor_run_forward(struct gpiod_line *ena, struct gpiod_line *in1,
                             struct gpiod_line *in2, int duration_sec)
{
    if (safe_set_value(in1, 1, "IN1") < 0) return -1;
    if (safe_set_value(in2, 0, "IN2") < 0) return -1;
    if (safe_set_value(ena, 1, "ENA") < 0) return -1;

    for (int i = 0; i < duration_sec && g_running; i++)
        sleep(1);

    return motor_stop(ena, in1, in2);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rain_line = NULL;
    struct gpiod_line *ena_line = NULL;
    struct gpiod_line *in1_line = NULL;
    struct gpiod_line *in2_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    rain_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    ena_line  = gpiod_chip_get_line(chip, MOTOR_ENA_PIN);
    in1_line  = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    in2_line  = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);

    if (!rain_line || !ena_line || !in1_line || !in2_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
