#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27
#define SAMPLE_US 500000  /* 500 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read CPU idle + busy jiffies from /proc/stat. */
static int read_cpu_stats(unsigned long long *user, unsigned long long *nice,
                          unsigned long long *system, unsigned long long *idle,
                          unsigned long long *iowait, unsigned long long *irq,
                          unsigned long long *softirq) {
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("fopen(/proc/stat)");
        return -1;
    }
    int rc = fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu",
                    user, nice, system, idle, iowait, irq, softirq);
    fclose(fp);
    if (rc != 7) {
        fprintf(stderr, "fscanf(/proc/stat) failed (rc=%d)\n", rc);
        return -1;
    }
    return 0;
}

/* Map 0..100 CPU load to a common-anode RGB gradient:
 *   0%   -> green  (0, 255, 0)
 *   50%  -> yellow (255, 255, 0)
 *   100% -> red    (255, 0, 0)
 * Common-anode: 0 = full on, 255 = full off. */
static void cpu_to_color(int load, int *r, int *g, int *b) {
    if (load < 0)   load = 0;
    if (load > 100) load = 100;

    if (load < 50) {
        *r = 0;
        *g = 255;
        *b = (int)((50 - load) * 5.1);   /* 255 -> 0 */
    } else {
        *r = (int)((load - 50) * 5.1);   /* 0 -> 255 */
        *g = 255 - (int)((load - 50) * 5.1);
        *b = 0;
    }
}

static void set_led_color(int r, int g, int b) {
    /* Common-anode: invert so 0 = full on, 255 = full off. */
    gpioPWM(RED_PIN,   255 - r);
    gpioPWM(GREEN_PIN, 255 - g);
    gpioPWM(BLUE_PIN,  255 - b);
}

static void led_off(void) {
    /* Common-anode: full off. */
    gpioPWM(RED_PIN,   255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN,  255);
}

int main(void) {
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    if (gpioSetMode(RED_PIN,   PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- PWM range 0..255 for each channel --- */
    gpioSetPWMrange(RED_PIN,   255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN,  255);

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        led_off();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- first sample --- */
    unsigned long long u1, n1, s1, i1, iw1, ir1, si1;
    if (read_cpu_stats(&u1, &n1, &s1, &i1, &iw1, &ir1, &si1) != 0) {
        led_off();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct timespec sleep_ts = {0, SAMPLE_US};

    while (running) {
        nanosleep(&sleep_ts, NULL);
        if (!running) break;

        unsigned long long u2, n2, s2, i2, iw2, ir2, si2;
        if (read_cpu_stats(&u2, &n2, &s2, &i2, &iw2, &ir2, &si2) != 0) {
            led_off();
            gpioTerminate();
            return EXIT_FAILURE;
        }

        unsigned long long prev_idle = i1 + iw1;
        unsigned long long prev_non  = u1 + n1 + s1 + ir1 + si1;
        unsigned long long curr_idle = i2 + iw2;
        unsigned long long curr_non  = u2 + n2 + s2 + ir2 + si2;

        unsigned long long prev_total = prev_idle + prev_non;
        unsigned long long curr_total = curr_idle + curr_non;

        unsigned long long totald = curr_total - prev_total;
        if (totald == 0) {
            /* No change between samples; keep previous color. */
            continue;
        }
        unsigned long long nonidled = curr_non - prev_non;

        int load = (int)(((double)nonidled / (double)totald) * 100.0);
        if (load < 0)   load = 0;
        if (load > 100) load = 100;

        int r, g, b;
        cpu_to_color(load, &r, &g, &b);
        set_led_color(r, g, b);

        u1 = u2; n1 = n2; s1 = s2; i1 = i2; iw1 = iw2; ir1 = ir2; si1 = si2;
    }

    /* --- clean shutdown --- */
    led_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

