#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define UDP_IP "192.168.1.100"
#define UDP_PORT 5000
#define SAMPLE_INTERVAL_SEC 5

#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB_00 0x88

#define BMP280_CHIP_ID 0x58

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static int g_udp_socket = -1;

static uint16_t dig_T1;
static int16_t dig_T2, dig_T3;
static uint16_t dig_P1;
static int16_t dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
static int32_t t_fine;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(handle, reg, val) < 0) return -1;
    return 0;
}

static int read_calibration_data(int handle) {
    uint8_t calib[24];
    if (i2c_read_block(handle, BMP280_REG_CALIB_00, calib, 24) < 0) return -1;
    dig_T1 = (uint16_t)(calib[0] | (calib[1] << 8));
    dig_T2 = (int16_t)(calib[2] | (calib[3] << 8));
    dig_T3 = (int16_t)(calib[4] | (calib[5] << 8));
    dig_P1 = (uint16_t)(calib[6] | (calib[7] << 8));
    dig_P2 = (int16_t)(calib[8] | (calib[9] << 8));
    dig_P3 = (int16_t)(calib[10] | (calib[11] << 8));
    dig_P4 = (int16_t)(calib[12] | (calib[13] << 8));
    dig_P5 = (int16_t)(calib[14] | (calib[15] << 8));
    dig_P6 = (int16_t)(calib[16] | (calib[17] << 8));
    dig_P7 = (int16_t)(calib[18] | (calib[19] << 8));
    dig_P8 = (int16_t)(calib[20] | (calib[21] << 8));
    dig_P9 = (int16_t)(calib[22] | (calib[23] << 8));
    return 0;
}

static int32_t compensate_temperature(int32_t adc_T) {
    int32_t var1, var2;
    var1 = ((((adc_T >> 3) - ((int32_t)dig_T1 << 1))) * ((int32_t)dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)dig_T1)) * ((adc_T >> 4) - ((int32_t)dig_T1))) >> 12) * ((int32_t)dig_T3)) >> 14;
    t_fine = var1 + var2;
    return (t_fine * 5 + 128) >> 8;
}

static uint32_t compensate_pressure(int32_t adc_P) {
    int32_t var1, var2;
    uint32_t p;
    var1 = ((int32_t)t_fine >> 1) - 64000;
    var2 = (((var1 >> 2) * (var1 >> 2)) >> 11) * ((int32_t)dig_P6);
    var2 = var2 + ((var1 * ((int32_t)dig_P5)) << 1);
    var2 = (var2 >> 2) + (((int32_t)dig_P4) << 16);
    var1 = (((((int32_t)dig_P3) * (((var1 >> 2) * (var1 >> 2)) >> 13)) >> 3) + ((((int32_t)dig_P2) * var1) >> 1)) >> 18;
    var1 = ((((32768 + var1)) * ((int32_t)dig_P1)) >> 15);
    if (var1 == 0) return 0;
    p = (((uint32_t)(((1048576) - adc_P) - (var2 >> 12))) * 3125);
    if (p < 0x80000000) p = (p << 1) / ((uint32_t)var1);
    else p = (p / (uint32_t)var1) * 2;
    var1 = (((int32_t)dig_P9) * ((int32_t)(((p >> 3) * (p >> 3)) >> 13))) >> 12;
    var2 = (((int32_t)(p >> 2)) * ((int32_t)dig_P8)) >> 13;
    p = (uint32_t)((int32_t)p + ((var1 + var2 + dig_P7) >> 4));
    return p;
}

static int read_bmp280(int handle, float *temperature, float *pressure) {
    uint8_t data[6];
    if (i2c_read_block(handle, BMP280_REG_PRESS_MSB, data, 6) < 0) return -1;
    int32_t raw_pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    *temperature = compensate_temperature(raw_temperature) / 100.0f;
    *pressure = compensate_pressure(raw_pressure) / 256.0f;
    return 0;
}

static int send_udp_packet(int sock, const char *ip, int port, const char *json_string) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip, &addr.sin_addr) <= 0) return -1;
    if (sendto(sock, json_string, strlen(json_string), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) return -1;
    return 0;
}

int main() {
