#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   500000
#define FAN_GPIO    18
#define PWM_FREQ    1000
#define PWM_RANGE   255
#define BUFFER_SIZE 20
#define SAMPLE_US   1000000

#define MAX31855_FAULT_OPEN_CIRCUIT  0x01
#define MAX31855_FAULT_SHORT_GND     0x02
#define MAX31855_FAULT_SHORT_VCC     0x04

typedef struct {
    time_t timestamp;
    float  temperature;
    int    duty_cycle;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int      buffer_index = 0;
static int      buffer_count = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max31855(int spi_handle, float *temperature) {
    char rx[4] = {0, 0, 0, 0};
    int  ret  = spiRead(spi_handle, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "SPI read failed (ret=%d)\n", ret);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] <<  8) |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        uint8_t fault = (uint8_t)(raw >> 4) & 0x07;
        if (fault & MAX31855_FAULT_OPEN_CIRCUIT)
            fprintf(stderr, "MAX31855 fault: open circuit\n");
        if (fault & MAX31855_FAULT_SHORT_GND)
            fprintf(stderr, "MAX31855 fault: short to GND\n");
        if (fault & MAX31855_FAULT_SHORT_VCC)
            fprintf(stderr, "MAX31855 fault: short to VCC\n");
        return -2;
    }

    int16_t thermocouple = (int16_t)(raw >> 18);
    *temperature = thermocouple * 0.25f;
    return 0;
}

static int calculate_duty_cycle(float temperature) {
    if (temperature < 25.0f) return 0;
    if (temperature < 40.0f) return (int)((temperature - 25.0f) / 15.0f * 127.5f);
    if (temperature < 60.0f) return (int)((temperature - 40.0f) / 20.0f * 152.5f) + 128;
    return 255;
}

static void log_data(float temperature, int duty_cycle) {
    log_buffer[buffer_index].timestamp  = time(NULL);
    log_buffer[buffer_index].temperature = temperature;
    log_buffer[buffer_index].duty_cycle  = duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_log_buffer(void) {
    printf("\n--- Log Buffer (%d entries) ---\n", buffer_count);
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S",
                 localtime(&log_buffer[idx].timestamp));
        printf("[%s] Temp: %.2f C, Duty: %d/255\n",
               ts, log_buffer[idx].temperature, log_buffer[idx].duty_cycle);
    }
    printf("--- End of Log Buffer ---\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioPWM(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioPWM(FAN_GPIO, 0);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Temperature-controlled fan started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        int   rc = read_max31855(spi_handle, &temperature);

        if (rc == 0) {
            int duty = calculate_duty_cycle(temperature);
            if (gpioPWM(FAN_GPIO, duty) < 0) {
                fprintf(stderr, "gpioPWM failed for duty %d\n", duty);
            } else {
                log_data(temperature, duty);
                printf("Temp: %.2f C, Duty: %d/255\n", temperature, duty);
            }
        } else if (rc == -2) {
            fprintf(stderr, "MAX31855 fault detected, skipping fan update\n");
        }

        gpioDelay(SAMPLE_US);
    }

    gpioPWM(FAN_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();

    print_log_buffer();
    return EXIT_SUCCESS;
}

