#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define LOG_FILE "rtd_log.csv"
#define RTD_NOMINAL_RESISTANCE 100.0
#define RTD_A 0.0039083
#define RTD_B -0.0000005775
#define RTD_C -0.000000000004183
#define R0 100.0
#define R_REF 4300.0
#define FAULT_THRESHOLD 0.05

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return 0;
}

static int read_register(int fd, uint8_t reg, uint8_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };
    if (spi_transfer(fd, tx, rx, 2) < 0) {
        return -1;
    }
    *value = rx[1];
    return 0;
}

static int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), value };
    uint8_t rx[2] = { 0 };
    return spi_transfer(fd, tx, rx, 2);
}

static int read_temperature(int fd, float *temperature) {
    uint8_t rtd_lsb = 0, rtd_msb = 0, fault = 0;
    if (read_register(fd, 0x01, &rtd_lsb) < 0) {
        return -1;
    }
    if (read_register(fd, 0x00, &rtd_msb) < 0) {
        return -1;
    }
    if (read_register(fd, 0x02, &fault) < 0) {
        return -1;
    }
    if (fault & 0x01) {
        fprintf(stderr, "Error: Fault detected (D16). Clearing...\n");
        if (write_register(fd, 0x02, 0x01) < 0) {
            return -1;
        }
        return -2;
    }
    uint16_t rtd_raw = ((uint16_t)rtd_msb << 8) | rtd_lsb;
    rtd_raw >>= 1;
    float rtd_resistance = R_REF * (float)rtd_raw / 32768.0;
    if (rtd_resistance < 0.0) {
        return -3;
    }
    float temp = (RTD_A + sqrt(RTD_A * RTD_A - 4 * RTD_B * (1.0 - rtd_resistance / RTD_NOMINAL_RESISTANCE))) / (2 * RTD_B);
    if (temp < -200.0 || temp > 1350.0) {
        return -4;
    }
    *temperature = temp;
    return 0;
}

static void log_data(FILE *fp, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", timestamp, temperature);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return 1;
    }
    uint8_t mode = SPI_MODE_1;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl WR_MODE");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl WR_BITS_PER_WORD");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl WR_MAX_SPEED_HZ");
        close(spi_fd);
        return 1;
    }
    if (write_register(spi_fd, 0x01, 0x80) < 0) {
        fprintf(stderr, "Error: Failed to configure MAX31865.\n");
        close(spi_fd);
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen log file");
        close(spi_fd);
        return 1;
    }
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C)\n");
        fflush(log_file);
    }
    printf("Starting temperature logging. Press Ctrl+C to exit.\n");
    while (running) {
        float temperature = 0.0;
        int ret = read_temperature(spi_fd, &temperature);
        if (ret == 0) {
            log_data(log_file, temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else if (ret == -2) {
            fprintf(stderr, "Warning: Sensor fault cleared, continuing.\n");
        } else if (ret == -3) {
            fprintf(stderr, "Error: Invalid RTD resistance value.\n");
        } else if (ret == -4) {
            fprintf(stderr, "Error: Temperature out of range.\n");
        } else {
            fprintf(stderr, "Error: SPI communication failure.\n");
        }
        sleep(5);
    }
    printf("\nShutting down gracefully.\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return 0;
}

