        return -2;
    }
    uint16_t rtd_raw = ((uint16_t)rtd_msb << 8) | rtd_lsb;
    rtd_raw >>= 1;
    float rtd_resistance = R_REF * (float)rtd_raw / 32768.0;
    if (rtd_resistance < 0.0) {
        return -3;
    }
    float temp = (RTD_A + sqrt(RTD_A * RTD_A - 4 * RTD_B * (1.0 - rtd_resistance / RTD_NOMINAL_RESISTANCE))) / (2 * RTD_B);
    if (temp < -200.0 || temp > 1350.0) {
        return -4;
    }
    *temperature = temp;
    return 0;
}

static void log_data(FILE *fp, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", timestamp, temperature);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return 1;
    }
    uint8_t mode = SPI_MODE_1;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl WR_MODE");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl WR_BITS_PER_WORD");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl WR_MAX_SPEED_HZ");
        close(spi_fd);
        return 1;
    }
    if (write_register(spi_fd, 0x01, 0x80) < 0) {
        fprintf(stderr, "Error: Failed to configure MAX31865.\n");
        close(spi_fd);
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen log file");
        close(spi_fd);
        return 1;
    }
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C)\n");
        fflush(log_file);
    }
    printf("Starting temperature logging. Press Ctrl+C to exit.\n");
    while (running) {
        float temperature = 0.0;
        int ret = read_temperature(spi_fd, &temperature);
        if (ret == 0) {
            log_data(log_file, temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else if (ret == -2) {
            fprintf(stderr, "Warning: Sensor fault cleared, continuing.\n");
        } else if (ret == -3) {
            fprintf(stderr, "Error: Invalid RTD resistance value.\n");
        } else if (ret == -4) {
            fprintf(stderr, "Error: Temperature out of range.\n");
        } else {
            fprintf(stderr, "Error: SPI communication failure.\n");
        }
        sleep(5);
    }
    printf("\nShutting down gracefully.\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return 0;
}

