/*
 * BME280 I2C reader for Raspberry Pi Zero W
 * Bus: /dev/i2c-1  (GPIO2 = SDA, GPIO3 = SCL)
 * Address: 0x76 (SDO tied to GND) or 0x77 (SDO tied to VDDIO)
 *
 * Build:  gcc -O2 -Wall -Wextra -o bme280_log bme280_log.c
 * Run:    ./bme280_log   (Ctrl-C to stop)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- BME280 constants (datasheet rev 1.26) ---- */
#define BME280_I2C_ADDR_0x76 0x76
#define BME280_I2C_ADDR_0x77 0x77
#define BME280_CHIP_ID_REG   0xD0
#define BME280_CHIP_ID       0x60
#define BME280_RESET_REG     0xE0
#define BME280_RESET_CMD     0xB6
#define BME280_CTRL_HUM_REG  0xF2
#define BME280_CTRL_MEAS_REG 0xF4
#define BME280_CONFIG_REG    0xF5
#define BME280_DATA_REG      0xF7
#define BME280_CALIB_00_REG  0x88
#define BME280_CALIB_26_REG  0xE1

#define LOG_FILE "bme280_log.csv"
#define I2C_BUS "/dev/i2c-1"
#define SAMPLE_INTERVAL_SEC 5

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Calibration coefficients ---- */
typedef struct {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
    uint8_t  dig_H1;
    int16_t  dig_H2;
    uint8_t  dig_H3;
    int16_t  dig_H4;
    int16_t  dig_H5;
    int8_t   dig_H6;
} bme280_calib_t;

static bme280_calib_t g_cal;
static int32_t g_t_fine;

/* ---- Signal handler ---- */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C burst write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- BME280 init ---- */
static int bme280_init(int fd)
{
    uint8_t chip_id;
    if (i2c_read_reg(fd, BME280_CHIP_ID_REG, &chip_id) < 0)
        return -1;
    if (chip_id != BME280_CHIP_ID) {
        fprintf(stderr, "Chip ID mismatch: got 0x%02X, expected 0x%02X\n", chip_id, BME280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg(fd, BME280_RESET_REG, BME280_RESET_CMD) < 0)
        return -1;
    usleep(2000); /* 2 ms reset wait */

    /* Read calibration block 0x88..0xA1 (26 bytes) */
    uint8_t cal0[26];
    if (i2c_read_burst(fd, BME280_CALIB_00_REG, cal0, sizeof(cal0)) < 0)
        return -1;
    g_cal.dig_T1 = (uint16_t)(cal0[0]  | (cal0[1]  << 8));
    g_cal.dig_T2 = (int16_t)(cal0[2]  | (cal0[3]  << 8));
    g_cal.dig_T3 = (int16_t)(cal0[4]  | (cal0[5]  << 8));
    g_cal.dig_P1 = (uint16_t)(cal0[6]  | (cal0[7]  << 8));
    g_cal.dig_P2 = (int16_t)(cal0[8]  | (cal0[9]  << 8));
    g_cal.dig_P3 = (int16_t)(cal0[10] | (cal0[11] << 8));
    g_cal.dig_P4 = (int16_t)(cal0[12] | (cal0[13] << 8));
    g_cal.dig_P5 = (int16_t)(cal0[14] | (cal0[15] << 8));
    g_cal.dig_P6 = (int16_t)(cal0[16] | (cal0[17] << 8));
    g_cal.dig_P7 = (int16_t)(cal0[18] | (cal0[19] << 8));
    g_cal.dig_P8 = (int16_t)(cal0[20] | (cal0[21] << 8));
    g_cal.dig_P9 = (int16_t)(cal0[22] | (cal0[23] << 8));
    g_cal.dig_H1 = cal0[25];

    /* Read calibration block 0xE1..0xE7 (7 bytes) */
    uint8_t cal1[7];
    if (i2c_read_burst(fd, BME280_CALIB_26_REG, cal1, sizeof(cal1)) < 0)
        return -1;
    g_cal.dig_H2 = (int16_t)(cal1[0] | (cal1[1] << 8));
    g_cal.dig_H3 = cal1[2];
    g_cal.dig_H4 = (int16_t)(((int8_t)cal1[3] << 4) | (cal1[4] & 0x0F));
    g_cal.dig_H5 = (int16_t)(((int8_t)cal1[5] << 4) | (cal1[4] >> 4));
    g_cal.dig_H6 = (int8_t)cal1[6];

    /* ctrl_hum = 0x01 -> 1x oversampling */
    if (i2c_write_reg(fd, BME280_CTRL_HUM_REG, 0x01) < 0)
        return -1;

    /* config: t_sb=0.5ms, filter=4, spi3w_en=0 */
    if (i2c_write_reg(fd, BME280_CONFIG_REG, 0x08) < 0)
        return -1;

    /* ctrl_meas: osrs_t=1x, osrs_p=1x, mode=sleep (yet) */
    if (i2c_write_reg(fd, BME280_CTRL_MEAS_REG, 0x24) < 0)
        return -1;

    /* ctrl_meas: osrs_t=1x, osrs_p=1x, mode=forced (0x01) */
    if (i2c_write_reg(fd, BME280_CTRL_MEAS_REG, 0x25) < 0)
        return -1;

    return 0;
}

/* ---- Read & compensate ---- */
static int bme280_read(int fd, float *temp, float *hum, float *press)
{
    /* Trigger forced mode */
    if (i2c_write_reg(fd, BME280_CTRL_MEAS_REG, 0x25) < 0)
        return -1;

    /* Wait for measurement to complete (~5.5 ms max for 1x/1x/forced) */
    usleep(6000);

    uint8_t data[8];
    if (i2c_read_burst(fd, BME280_DATA_REG, data, sizeof(data)) < 0)
        return -1;

    int32_t raw_p = (int32_t)((data[0] << 12) | (data[1] << 4) | (data[2] >> 4));
    int32_t raw_t = (int32_t)((data[3] << 12) | (data[4] << 4) | (data[5] >> 4));
    int32_t raw_h = (int32_t)((data[6] << 8) | data[7]);

    /* Temperature compensation (datasheet formula) */
    double v1 = ((double)raw_t / 16384.0 - (double)g_cal.dig_T1 / 1024.0) * (double)g_cal.dig_T2;
    double v2 = ((double)raw_t / 131072.0 - (double)g_cal.dig_T1 / 8192.0);
    v2 = v2 * v2 * (double)g_cal.dig_T3;
    g_t_fine = (int32_t)(v1 + v2);
    *temp = (float)((v1 + v2) / 5120.0);

    /* Pressure compensation */
    double v3 = ((double)g_t_fine / 2.0) - 64000.0;
    double v4 = v3 * v3 * (double)g_cal.dig_P6 / 32768.0;
    v4 = v4 + v3 * (double)g_cal.dig_P5 * 2.0;
    v4 = (v4 / 4.0) + ((double)g_cal.dig_P4 * 65536.0);
    v3 = ((double)g_cal.dig_P3 * v3 * v3 / 524288.0 + (double)g_cal.dig_P2 * v3) / 524288.0;
    v3 = (1.0 + v3 / 32768.0) * (double)g_cal.dig_P1;
    double p = 1048576.0 - (double)raw_p;
    p = (p - (v4 / 4096.0)) * 6250.0 / v3;
    v3 = (double)g_cal.dig_P9 * p * p / 2147483648.0;
    v4 = p * (double)g_cal.dig_P8 / 32768.0;
    p = p + (v3 + v4 + (double)g_cal.dig_P7) / 16.0;
    *press = (float)(p / 100.0); /* Pa -> hPa */

    /* Humidity compensation */
    double h = (double)g_t_fine - 76800.0;
    h = (raw_h - ((double)g_cal.dig_H4 * 64.0 + (double)g_cal.dig_H5 / 16384.0 * h)) *
        (double)g_cal.dig_H2 / (65536.0 * (1.0 + (double)g_cal.dig_H6 / 67108864.0 * h *
        (1.0 + (double)g_cal.dig_H3 / 67108864.0 * h)));
    h = h * (1.0 - (double)g_cal.dig_H1 * h / 524288.0);
    if (h > 100.0) h = 100.0;
    if (h < 0.0)   h = 0.0;
    *hum = (float)h;

    return 0;
}

/* ---- Logging ---- */
static int log_data(FILE *fp, float temp, float hum, float press)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[20];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, temp, hum, press) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Try 0x76 first, then 0x77 */
    uint8_t addr = BME280_I2C_ADDR_0x76;
    if (ioctl(g_i2c_fd, I2C_SLAVE, addr) < 0) {
        addr = BME280_I2C_ADDR_0x77;
        if (ioctl(g_i2c_fd, I2C_SLAVE, addr) < 0) {
            fprintf(stderr, "ioctl(I2C_SLAVE, 0x76 or 0x77) failed: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* Initialize sensor */
    if (bme280_init(g_i2c_fd) < 0) {
        fprintf(stderr, "BME280 initialization failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,temperature_c,humidity_pct,pressure_hpa\n");
        fflush(g_log_fp);
    }

    printf("BME280 logging started -> %s (Ctrl-C to stop)\n", LOG_FILE);

    /* Main loop */
    while (g_running) {
        float temp, hum, press;
        if (bme280_read(g_i2c_fd, &temp, &hum, &press) < 0) {
            fprintf(stderr, "Sensor read failed; continuing\n");
        } else {
            if (log_data(g_log_fp, temp, hum, press) < 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

