#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define BMP180_ADDR             0x77
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_MSB          0xF6
#define BMP180_REG_LSB          0xF7
#define BMP180_REG_XLSB         0xF8
#define BMP180_REG_CAL_AC1      0xAA
#define BMP180_REG_CAL_AC2      0xAC
#define BMP180_REG_CAL_AC3      0xAE
#define BMP180_REG_CAL_AC4      0xB0
#define BMP180_REG_CAL_AC5      0xB2
#define BMP180_REG_CAL_AC6      0xB4
#define BMP180_REG_CAL_B1       0xB6
#define BMP180_REG_CAL_B2       0xB8
#define BMP180_REG_CAL_MB       0xBA
#define BMP180_REG_CAL_MC       0xBC
#define BMP180_REG_CAL_MD       0xBE

#define ALERT_GPIO              24
#define BUFFER_SIZE             1200
#define PRESSURE_THRESHOLD      5.0
#define SAMPLE_INTERVAL_US      50000
#define I2C_BUS                 1

static volatile sig_atomic_t running = 1;

typedef struct {
    time_t timestamp;
    float  pressure;
} PressureData;

static PressureData pressure_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    return (i2cWriteDevice(handle, buf, 2) == 2) ? 0 : -1;
}

static int read_calibration_data(int handle) {
    uint8_t buf[22];
    if (i2c_read_reg(handle, BMP180_REG_CAL_AC1, buf, 22) < 0) return -1;
    ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1  = (int16_t)((buf[12] << 8) | buf[13]);
    b2  = (int16_t)((buf[14] << 8) | buf[15]);
    mb  = (int16_t)((buf[16] << 8) | buf[17]);
    mc  = (int16_t)((buf[18] << 8) | buf[19]);
    md  = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temperature(int handle, int32_t *raw_temp) {
    if (i2c_write_reg(handle, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    gpioDelay(5000);
    uint8_t buf[2];
    if (i2c_read_reg(handle, BMP180_REG_MSB, buf, 2) < 0) return -1;
    *raw_temp = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int handle, int32_t *raw_pressure) {
    if (i2c_write_reg(handle, BMP180_REG_CONTROL, 0x34) < 0) return -1;
    gpioDelay(5000);
    uint8_t buf[3];
    if (i2c_read_reg(handle, BMP180_REG_MSB, buf, 3) < 0) return -1;
    *raw_pressure = ((int32_t)(buf[0] << 16) | (buf[1] << 8) | buf[2]) >> 8;
    return 0;
}

static float calculate_pressure(int32_t raw_temp, int32_t raw_pressure) {
    int32_t x1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1 * 4 + x3) << 0) + 2) / 4);
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)raw_pressure - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (float)p / 100.0f;
}

static void add_to_buffer(float pressure) {
    pressure_buffer[buffer_index].timestamp = time(NULL);
    pressure_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static float calculate_rolling_average(void) {
    if (buffer_count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++) sum += pressure_buffer[i].pressure;
    return sum / (float)buffer_count;
}

static void check_pressure_deviation(float current_pressure, float rolling_average) {
    if (buffer_count < 20) return;
    float deviation = fabsf(current_pressure - rolling_average);
    if (deviation > PRESSURE_THRESHOLD) {
        fprintf(stderr, "ALERT: Pressure deviation %.2f hPa exceeds threshold %.1f hPa\n", deviation, PRESSURE_THRESHOLD);
        gpioWrite(ALERT_GPIO, 1);
        gpioDelay(1000000);
        gpioWrite(ALERT_GPIO, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0);

    int i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, BMP180_ADDR);
        gpioTerminate();
        return 1;
    }

    if (read_calibration_data(i2c_handle) < 0) {
        fprintf(stderr, "Error: Failed to read BMP180 calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        int32_t raw_temp, raw_pressure;
        if (read_raw_temperature(i2c_handle, &raw_temp) < 0) {
            fprintf(stderr, "Error: Failed to read raw temperature\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        if (read_raw_pressure(i2c_handle, &raw_pressure) < 0) {
            fprintf(stderr, "Error: Failed to read raw pressure\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        float pressure = calculate_pressure(raw_temp, raw_pressure);
        add_to_buffer(pressure);
        float rolling_average = calculate_rolling_average();
        check_pressure_deviation(pressure, rolling_average);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cClose(i2c_handle);
    gpioWrite(ALERT_GPIO, 0);
    gpioTerminate();
    return 0;
}

