        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    while (running) {
        int32_t ut, up;
        if (read_raw_temperature(i2c_fd, &ut) < 0) {
            fprintf(stderr, "Error reading raw temperature: %s\n", strerror(errno));
            break;
        }
        if (read_raw_pressure(i2c_fd, &up) < 0) {
            fprintf(stderr, "Error reading raw pressure: %s\n", strerror(errno));
            break;
        }
        double temperature = calculate_temperature(ut);
        double pressure = calculate_pressure(up, ut);
        log_data(temperature, pressure);
        usleep(500000);
    }

    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
