/*
 * BMP280 weather logger for Raspberry Pi 4 Model B
 * I2C bus 1 (/dev/i2c-1), SDA=GPIO2 (pin 3), SCL=GPIO3 (pin 5)
 * Default address 0x76 (SDO->GND) or 0x77 (SDO->VDDIO)
 * Logs "YYYY-MM-DD HH:MM:SS, Temperature: XX.XX °C, Pressure: YYYY.YY hPa"
 * to weather_data.txt every 5 seconds until SIGINT/SIGTERM.
 *
 * Build:  gcc -O2 -Wall -Wextra -o bmp280_logger bmp280_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BMP280_ADDR_DEFAULT 0x76
#define BMP280_ADDR_ALT     0x77

#define BMP280_REG_ID       0xD0
#define BMP280_REG_RESET    0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG   0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB  0xFA
#define BMP280_REG_CALIB    0x88

#define BMP280_CHIP_ID      0x58
#define LOG_FILE            "weather_data.txt"
#define SAMPLE_INTERVAL_S   5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1)
        return -1;
    ssize_t n = read(fd, buf, len);
    return (n == (ssize_t)len) ? 0 : -1;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t msg[2] = { reg, val };
    if (write(fd, msg, 2) != 2)
        return -1;
    return 0;
}

/* ---- BMP280 calibration ---- */

typedef struct {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
} bmp280_calib_t;

static int bmp280_read_calib(int fd, bmp280_calib_t *c)
{
    uint8_t d[24];
    if (i2c_read_reg(fd, BMP280_REG_CALIB, d, sizeof(d)) != 0)
        return -1;

    c->dig_T1 = (uint16_t)(d[0]  | (d[1]  << 8));
    c->dig_T2 = (int16_t) (d[2]  | (d[3]  << 8));
    c->dig_T3 = (int16_t) (d[4]  | (d[5]  << 8));
    c->dig_P1 = (uint16_t)(d[6]  | (d[7]  << 8));
    c->dig_P2 = (int16_t) (d[8]  | (d[9]  << 8));
    c->dig_P3 = (int16_t) (d[10] | (d[11] << 8));
    c->dig_P4 = (int16_t) (d[12] | (d[13] << 8));
    c->dig_P5 = (int16_t) (d[14] | (d[15] << 8));
    c->dig_P6 = (int16_t) (d[16] | (d[17] << 8));
    c->dig_P7 = (int16_t) (d[18] | (d[19] << 8));
    c->dig_P8 = (int16_t) (d[20] | (d[21] << 8));
    c->dig_P9 = (int16_t) (d[22] | (d[23] << 8));
    return 0;
}

/* ---- Bosch 64-bit compensation (datasheet rev 1.26) ---- */

static int32_t g_t_fine;

static int32_t compensate_temp(int32_t adc_T, const bmp280_calib_t *c)
{
    int32_t var1, var2;
    var1 = ((((adc_T >> 3) - ((int32_t)c->dig_T1 << 1))) * ((int32_t)c->dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)c->dig_T1)) * ((adc_T >> 4) - ((int32_t)c->dig_T1))) >> 12) *
            ((int32_t)c->dig_T3)) >> 14;
    g_t_fine = var1 + var2;
    return (g_t_fine * 5 + 128) >> 8;  /* centi-degrees C */
}

static uint32_t compensate_press(int32_t adc_P, const bmp280_calib_t *c)
{
    int32_t var1, var2;
    uint32_t p;
    var1 = ((int32_t)g_t_fine >> 1) - 64000;
    var2 = (((var1 >> 2) * (var1 >> 2)) >> 11) * ((int32_t)c->dig_P6);
    var2 = var2 + ((var1 * ((int32_t)c->dig_P5)) << 1);
    var2 = (var2 >> 2) + (((int32_t)c->dig_P4) << 16);
    var1 = (((((int32_t)c->dig_P3) * (((var1 >> 2) * (var1 >> 2)) >> 13)) >> 3) +
            ((((int32_t)c->dig_P2) * var1) >> 1)) >> 18;
    var1 = ((((32768 + var1)) * ((int32_t)c->dig_P1)) >> 15);
    if (var1 == 0)
        return 0;  /* avoid divide-by-zero */
    p = (((uint32_t)(((1 << 31) - adc_P) - (var2 >> 12))) * 6250U) / (uint32_t)var1;
    var1 = (((int32_t)c->dig_P9) * ((int32_t)(((p >> 3) * (p >> 3)) >> 13))) >> 12;
    var2 = (((int32_t)(p >> 2)) * ((int32_t)c->dig_P8)) >> 13;
    p = (uint32_t)((int32_t)p + ((var1 + var2 + ((int32_t)c->dig_P7)) >> 4));
    return p;  /* Pa */
}

/* ---- Sensor read ---- */

static int bmp280_read(int fd, const bmp280_calib_t *c,
                       float *temp_c, float *press_hpa)
{
    uint8_t d[6];
    if (i2c_read_reg(fd, BMP280_REG_PRESS_MSB, d, 6) != 0)
        return -1;

    int32_t adc_P = (int32_t)((uint32_t)d[0] << 12 | (uint32_t)d[1] << 4 | (uint32_t)d[2] >> 4);
    int32_t adc_T = (int32_t)((uint32_t)d[3] << 12 | (uint32_t)d[4] << 4 | (uint32_t)d[5] >> 4);

    int32_t t = compensate_temp(adc_T, c);
    uint32_t p = compensate_press(adc_P, c);

    *temp_c  = t / 100.0f;
    *press_hpa = p / 100.0f;
    return 0;
}

/* ---- Main ---- */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    /* Probe default address, then alternate */
    uint8_t addr = BMP280_ADDR_DEFAULT;
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        addr = BMP280_ADDR_ALT;
        if (ioctl(fd, I2C_SLAVE, addr) < 0) {
            perror("ioctl I2C_SLAVE");
            close(fd);
            return EXIT_FAILURE;
        }
    }

    uint8_t id;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id, 1) != 0) {
        fprintf(stderr, "Failed to read BMP280 chip ID: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Unexpected chip ID 0x%02X (expected 0x%02X)\n", id, BMP280_CHIP_ID);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Soft reset */
    if (i2c_write_reg(fd, BMP280_REG_RESET, 0xB6) != 0) {
        perror("reset write");
        close(fd);
        return EXIT_FAILURE;
    }
    usleep(2000);

    /* config: t_sb=500us(000), filter=4(010), spi3w_en=0 */
    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x08) != 0) {
        perror("config write");
        close(fd);
        return EXIT_FAILURE;
    }

    bmp280_calib_t cal;
    if (bmp280_read_calib(fd, &cal) != 0) {
        fprintf(stderr, "Failed to read calibration data: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("BMP280 detected at 0x%02X. Logging to %s every %d s. Ctrl+C to stop.\n",
           addr, LOG_FILE, SAMPLE_INTERVAL_S);

    while (g_running) {
        /* ctrl_meas: osrs_t=x1(001), osrs_p=x1(001), mode=forced(01) -> 0x25 */
        if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x25) != 0) {
            fprintf(stderr, "ctrl_meas write failed: %s\n", strerror(errno));
            sleep(1);
            continue;
        }

        /* Wait for measurement to complete (max ~5.5 ms at x1/x1) */
        usleep(6000);

        float temp_c, press_hpa;
        if (bmp280_read(fd, &cal, &temp_c, &press_hpa) != 0) {
            fprintf(stderr, "Sensor read failed: %s\n", strerror(errno));
            sleep(1);
            continue;
        }

        time_t now = time(NULL);
        struct tm tmv;
        if (localtime_r(&now, &tmv) == NULL) {
            fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
            sleep(1);
            continue;
        }

        char ts[32];
        if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv) == 0) {
            fprintf(stderr, "strftime failed\n");
            sleep(1);
            continue;
        }

        char line[128];
        snprintf(line, sizeof(line), "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n",
                 ts, temp_c, press_hpa);

        FILE *fp = fopen(LOG_FILE, "a");
        if (!fp) {
            fprintf(stderr, "fopen %s: %s\n", LOG_FILE, strerror(errno));
            sleep(1);
            continue;
        }
        if (fputs(line, fp) == EOF) {
            fprintf(stderr, "fputs: %s\n", strerror(errno));
        }
        if (fclose(fp) != 0) {
            fprintf(stderr, "fclose: %s\n", strerror(errno));
        }

        printf("%s", line);

        /* Sleep but wake early on signal */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    printf("\nExiting gracefully.\n");
    close(fd);
    return EXIT_SUCCESS;
}

