        perror("reset write");
        close(fd);
        return EXIT_FAILURE;
    }
    usleep(2000);

    /* config: t_sb=500us(000), filter=4(010), spi3w_en=0 */
    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x08) != 0) {
        perror("config write");
        close(fd);
        return EXIT_FAILURE;
    }

    bmp280_calib_t cal;
    if (bmp280_read_calib(fd, &cal) != 0) {
        fprintf(stderr, "Failed to read calibration data: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("BMP280 detected at 0x%02X. Logging to %s every %d s. Ctrl+C to stop.\n",
           addr, LOG_FILE, SAMPLE_INTERVAL_S);

    while (g_running) {
        /* ctrl_meas: osrs_t=x1(001), osrs_p=x1(001), mode=forced(01) -> 0x25 */
        if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x25) != 0) {
            fprintf(stderr, "ctrl_meas write failed: %s\n", strerror(errno));
            sleep(1);
            continue;
        }

        /* Wait for measurement to complete (max ~5.5 ms at x1/x1) */
        usleep(6000);

        float temp_c, press_hpa;
        if (bmp280_read(fd, &cal, &temp_c, &press_hpa) != 0) {
            fprintf(stderr, "Sensor read failed: %s\n", strerror(errno));
            sleep(1);
            continue;
        }

        time_t now = time(NULL);
        struct tm tmv;
        if (localtime_r(&now, &tmv) == NULL) {
            fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
            sleep(1);
            continue;
        }

        char ts[32];
        if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv) == 0) {
            fprintf(stderr, "strftime failed\n");
            sleep(1);
            continue;
        }

        char line[128];
        snprintf(line, sizeof(line), "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n",
                 ts, temp_c, press_hpa);

        FILE *fp = fopen(LOG_FILE, "a");
        if (!fp) {
            fprintf(stderr, "fopen %s: %s\n", LOG_FILE, strerror(errno));
            sleep(1);
            continue;
        }
        if (fputs(line, fp) == EOF) {
            fprintf(stderr, "fputs: %s\n", strerror(errno));
        }
        if (fclose(fp) != 0) {
            fprintf(stderr, "fclose: %s\n", strerror(errno));
        }

        printf("%s", line);

        /* Sleep but wake early on signal */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    printf("\nExiting gracefully.\n");
    close(fd);
    return EXIT_SUCCESS;
}

