/*
 * Raspberry Pi 4 Model B – LM75 temperature monitor with alert LED.
 *
 * Hardware:
 *   - LM75 temperature sensor on I2C bus 1, address 0x48.
 *   - Alert LED on GPIO18 (BCM), active-high.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o lm75_monitor lm75_monitor.c -lpigpio -lpthread
 *
 * Run:
 *   sudo ./lm75_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define LM75_ADDR            0x48
#define ALERT_GPIO           18
#define BUFFER_SIZE          60
#define TEMP_THRESHOLD       28.0f
#define SAMPLE_PERIOD_US     1000000   /* 1 second */
#define ALERT_CHECK_PERIOD   100000    /* 100 ms  */
#define MAX_REINIT_ATTEMPTS  3

/* LM75 registers */
#define LM75_REG_TEMP        0x00
#define LM75_REG_CONFIG      0x01
#define LM75_REG_THYST       0x02
#define LM75_REG_TOS         0x03

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static pthread_mutex_t g_buffer_mutex;

/* Circular buffer */
typedef struct {
    float  data[BUFFER_SIZE];
    size_t head;
    size_t count;
} CircularBuffer;

static CircularBuffer g_temp_buffer;

/* ----------------------------- Prototypes -------------------------------- */
static int  init_hardware(void);
static void cleanup_hardware(void);
static int  read_temperature(float *out_temp);
static void buffer_add(float temp);
static float buffer_average(void);
static void *alert_thread(void *arg);
static void signal_handler(int sig);

/* ----------------------------- Implementation ----------------------------- */

static int init_hardware(void)
{
    /* --- I2C --- */
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }

    g_i2c_fd = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, LM75_ADDR, strerror(errno));
        return -1;
    }

    /*
     * LM75 configuration register (0x01):
     *   Bit 7 = 0  -> continuous conversion mode
     *   Bit 6 = 0  -> 0.5 Hz conversion rate
     *   Bit 5 = 0  -> active-high alert polarity
     *   Bit 4 = 0  -> alert pin is active until cleared by software
     *   Bit 3 = 0  -> interrupt mode (not comparator)
     *   Bits 2:0  -> fault queue = 1
     * Value = 0x00.
     */
    if (i2cWriteByteData(g_i2c_fd, LM75_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "[ERROR] Failed to write LM75 config register: %s\n",
                strerror(errno));
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    /* --- GPIO --- */
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d, PI_OUTPUT) failed\n", ALERT_GPIO);
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    if (gpioWrite(ALERT_GPIO, 0) < 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%d, 0) failed\n", ALERT_GPIO);
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    return 0;
}

static void cleanup_hardware(void)
{
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    /* Best-effort LED off */
    gpioWrite(ALERT_GPIO, 0);
}

/*
 * Read temperature from LM75.
 * Returns 0 on success, -1 on I2C error.
 */
static int read_temperature(float *out_temp)
{
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[ERROR] I2C not initialized\n");
        return -1;
    }

    /*
     * LM75 temperature register (0x00) is 16-bit, left-justified.
     * Resolution: 0.5 °C per LSB.
     * Bits [15:7] = temperature, bits [6:0] = 0.
     */
    int raw = i2cReadWordData(g_i2c_fd, LM75_REG_TEMP);
    if (raw < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData(0x%02X) failed: %s\n",
                LM75_REG_TEMP, strerror(errno));
        return -1;
    }

    /* pigpio returns the raw byte-swapped word; swap to get host order. */
    uint16_t swapped = (uint16_t)((raw >> 8) | (raw << 8));
    int16_t  signed_val = (int16_t)(swapped >> 5);   /* right-justify */
    *out_temp = (float)signed_val * 0.5f;

    return 0;
}

static void buffer_add(float temp)
{
    pthread_mutex_lock(&g_buffer_mutex);
    g_temp_buffer.data[g_temp_buffer.head] = temp;
    g_temp_buffer.head = (g_temp_buffer.head + 1) % BUFFER_SIZE;
    if (g_temp_buffer.count < BUFFER_SIZE) {
        g_temp_buffer.count++;
    }
    pthread_mutex_unlock(&g_buffer_mutex);
}

static float buffer_average(void)
{
    float sum = 0.0f;
    size_t count = 0;

    pthread_mutex_lock(&g_buffer_mutex);
    for (size_t i = 0; i < g_temp_buffer.count; i++) {
        sum += g_temp_buffer.data[i];
    }
    count = g_temp_buffer.count;
    pthread_mutex_unlock(&g_buffer_mutex);

    return (count > 0) ? (sum / (float)count) : 0.0f;
}

/*
 * Background thread: polls the in-memory buffer and drives the alert LED.
 */
static void *alert_thread(void *arg)
{
    (void)arg;
    while (g_running) {
        float avg = buffer_average();
        int level = (avg > TEMP_THRESHOLD) ? 1 : 0;

        if (gpioWrite(ALERT_GPIO, level) < 0) {
            fprintf(stderr, "[ERROR] gpioWrite(%d, %d) failed\n",
                    ALERT_GPIO, level);
        }

        usleep(ALERT_CHECK_PERIOD);
    }
    return NULL;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize mutex */
    if (pthread_mutex_init(&g_buffer_mutex, NULL) != 0) {
        fprintf(stderr, "[FATAL] pthread_mutex_init() failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize hardware */
    if (init_hardware() != 0) {
        fprintf(stderr, "[FATAL] Hardware initialization failed\n");
        pthread_mutex_destroy(&g_buffer_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize circular buffer */
    memset(&g_temp_buffer, 0, sizeof(g_temp_buffer));

    /* Start alert thread */
    pthread_t alert_tid;
    if (pthread_create(&alert_tid, NULL, alert_thread, NULL) != 0) {
        fprintf(stderr, "[FATAL] pthread_create() failed: %s\n", strerror(errno));
        cleanup_hardware();
        pthread_mutex_destroy(&g_buffer_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("LM75 temperature monitor started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        float temp;
        if (read_temperature(&temp) == 0) {
            buffer_add(temp);
            float avg = buffer_average();
            printf("Temperature: %.2f C | Average: %.2f C\n", temp, avg);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; attempting re-init...\n");
            int reinit_ok = 0;
            for (int attempt = 0; attempt < MAX_REINIT_ATTEMPTS && g_running; attempt++) {
                if (init_hardware() == 0) {
                    reinit_ok = 1;
                    break;
                }
                fprintf(stderr, "[WARN] Re-init attempt %d/%d failed\n",
                        attempt + 1, MAX_REINIT_ATTEMPTS);
                usleep(500000);
            }
            if (!reinit_ok) {
                fprintf(stderr, "[FATAL] All re-init attempts exhausted.\n");
                g_running = 0;
            }
        }

        usleep(SAMPLE_PERIOD_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    g_running = 0;
    pthread_join(alert_tid, NULL);
    cleanup_hardware();
    pthread_mutex_destroy(&g_buffer_mutex);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

