#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <jansson.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_FLAGS 0
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define CONFIG_FILE "config.json"
#define DEFAULT_TARGET_TEMP 25.0
#define DEFAULT_KP 1.0
#define DEFAULT_KI 0.1
#define DEFAULT_KD 0.01
#define MAX_TEMP 80.0
#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x07
#define RTD_NOMINAL_RESISTANCE 100.0
#define RTD_REF_RESISTANCE 430.0
#define RTD_A 3.9083e-3
#define RTD_B -5.775e-7

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename, double *target_temp, double *kp, double *ki, double *kd) {
    json_error_t error;
    json_t *root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error loading config file: %s\n", error.text);
        return -1;
    }
    json_t *val;
    *target_temp = DEFAULT_TARGET_TEMP;
    *kp = DEFAULT_KP;
    *ki = DEFAULT_KI;
    *kd = DEFAULT_KD;
    val = json_object_get(root, "target_temperature");
    if (json_is_real(val)) *target_temp = json_real_value(val);
    val = json_object_get(root, "kp");
    if (json_is_real(val)) *kp = json_real_value(val);
    val = json_object_get(root, "ki");
    if (json_is_real(val)) *ki = json_real_value(val);
    val = json_object_get(root, "kd");
    if (json_is_real(val)) *kd = json_real_value(val);
    json_decref(root);
    return 0;
}

static int read_max31865_rtd(double *temperature) {
    char tx[2] = {MAX31865_RTD_MSB_REG, 0x00};
    char rx[2] = {0, 0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) return -1;
