    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC5, (int16_t *)ac5) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC6, (int16_t *)ac6) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_B1, b1) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_B2, b2) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MB, mb) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MC, mc) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MD, md) < 0) return -1;
    return 0;
}

static int read_raw_temperature(int fd, int32_t *ut) {
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, BMP180_TEMP_CMD) < 0) return -1;
    usleep(5000);
    int32_t raw;
    if (i2c_read_reg16(fd, BMP180_REG_MSB, (int16_t *)&raw) < 0) return -1;
    *ut = raw;
    return 0;
}

static int read_raw_pressure(int fd, int32_t *up) {
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, BMP180_PRESSURE_CMD | (BMP180_OSS << 6)) < 0) return -1;
    usleep(5000 + (3000 << BMP180_OSS));
    int32_t raw;
    if (i2c_read_reg24(fd, BMP180_REG_MSB, &raw) < 0) return -1;
    *up = (raw >> (8 - BMP180_OSS));
    return 0;
}

static int32_t compute_b5(int32_t ut, int16_t ac6, int16_t ac5, int16_t mc, int16_t md) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    return x1 + x2;
}

static int32_t compute_temperature(int32_t ut, int16_t ac6, int16_t ac5, int16_t mc, int16_t md) {
    int32_t b5 = compute_b5(ut, ac6, ac5, mc, md);
    return (b5 + 8) >> 4;
}

static int32_t compute_pressure(int32_t up, int32_t ut, int16_t ac1, int16_t ac2, int16_t ac3,
                                uint16_t ac4, uint16_t ac5, uint16_t ac6,
                                int16_t b1, int16_t b2, int16_t mb, int16_t mc, int16_t md) {
    int32_t b5 = compute_b5(ut, ac6, ac5, mc, md);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static int log_breach(float temperature, float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s - Temperature: %.2f C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BMP180_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;

    if (read_calibration_data(fd, &ac1, &ac2, &ac3, &ac4, &ac5, &ac6, &b1, &b2, &mb, &mc, &md) < 0) {
        fprintf(stderr, "Error reading BMP180 calibration data: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    printf("BMP180 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int32_t ut = 0, up = 0;
        int temp_ok = 0, press_ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_raw_temperature(fd, &ut) == 0) {
                temp_ok = 1;
                break;
            }
            fprintf(stderr, "Error reading temperature (attempt %d/%d): %s\n", attempt + 1, MAX_RETRIES, strerror(errno));
            usleep(100000);
        }

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_raw_pressure(fd, &up) == 0) {
                press_ok = 1;
                break;
            }
            fprintf(stderr, "Error reading pressure (attempt %d/%d): %s\n", attempt + 1, MAX_RETRIES, strerror(errno));
            usleep(100000);
        }

        if (!temp_ok || !press_ok) {
            fprintf(stderr, "Sensor read failed after %d retries. Continuing...\n", MAX_RETRIES);
            sleep(1);
            continue;
        }

        int32_t temp_raw = compute_temperature(ut, ac6, ac5, mc, md);
        int32_t press_raw = compute_pressure(up, ut, ac1, ac2, ac3, ac4, ac5, ac6, b1, b2, mb, mc, md);

        float temperature = temp_raw / 10.0f;
        float pressure = press_raw / 100.0f;

        printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temperature, pressure);

        if (temperature > TEMP_THRESHOLD || pressure < PRESSURE_THRESHOLD) {
            if (log_breach(temperature, pressure) == 0) {
                printf("Breach logged to %s\n", LOG_FILE);
            } else {
                fprintf(stderr, "Error logging breach.\n");
            }
        }

        sleep(1);
    }

    printf("\nExiting gracefully...\n");
    close(fd);
    return 0;
}

