#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR             0x77
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_MSB          0xF6
#define BMP180_REG_CALIB_START  0xAA
#define BMP180_CALIB_LEN        22
#define BMP180_CMD_TEMP         0x2E
#define BMP180_CMD_PRESSURE     0x34
#define FAN_GPIO                18
#define TEMP_THRESHOLD          30.0f
#define BUFFER_SIZE             60
#define SAMPLE_PERIOD_US        500000

typedef struct {
    time_t timestamp;
    float  temperature;
    float  pressure;
} sensor_data_t;

static sensor_data_t circular_buffer[BUFFER_SIZE];
static int           buffer_index = 0;
static int           buffer_count = 0;
static volatile sig_atomic_t running = 1;
static int           i2c_handle = -1;
static int16_t       ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t      ac4, ac5, ac6;
static volatile sig_atomic_t fan_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    int n = i2cReadDevice(handle, (char *)buf, len);
    return (n == (int)len) ? 0 : -1;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val) {
    char buf[2] = {(char)reg, (char)val};
    return (i2cWriteDevice(handle, buf, 2) == 2) ? 0 : -1;
}

static int read_calibration_data(void) {
    uint8_t data[BMP180_CALIB_LEN];
    if (i2c_read_block(i2c_handle, BMP180_REG_CALIB_START, data, BMP180_CALIB_LEN) != 0) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    ac1 = (int16_t)((data[0]  << 8) | data[1]);
    ac2 = (int16_t)((data[2]  << 8) | data[3]);
    ac3 = (int16_t)((data[4]  << 8) | data[5]);
    ac4 = (uint16_t)((data[6]  << 8) | data[7]);
    ac5 = (uint16_t)((data[8]  << 8) | data[9]);
    ac6 = (uint16_t)((data[10] << 8) | data[11]);
    b1  = (int16_t)((data[12] << 8) | data[13]);
    b2  = (int16_t)((data[14] << 8) | data[15]);
    mb  = (int16_t)((data[16] << 8) | data[17]);
    mc  = (int16_t)((data[18] << 8) | data[19]);
    md  = (int16_t)((data[20] << 8) | data[21]);
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    if (i2c_write_byte(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) != 0) return -1;
    gpioDelay(5000);
    uint8_t data[2];
    if (i2c_read_block(i2c_handle, BMP180_REG_MSB, data, 2) != 0) return -1;
    *ut = (int32_t)((data[0] << 8) | data[1]);
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    if (i2c_write_byte(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE) != 0) return -1;
    gpioDelay(5000);
    uint8_t data[3];
    if (i2c_read_block(i2c_handle, BMP180_REG_MSB, data, 3) != 0) return -1;
    *up = ((int32_t)(data[0] << 16) | (int32_t)(data[1] << 8) | data[2]) >> (8 - 0);
    return 0;
}

static float calculate_temperature(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    return ((b5 + 8) >> 4) / 10.0f;
}

static float calculate_pressure(int32_t up, int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    int32_t x3 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x4 = ((int32_t)ac2 * b6) >> 11;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << 0) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x4 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else                 p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    return (float)(p + ((x1 + x2 + 3791) >> 4));
}

static void add_to_buffer(float temperature, float pressure) {
    circular_buffer[buffer_index].timestamp  = time(NULL);
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].pressure    = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void control_fan(float temperature) {
    if (temperature > TEMP_THRESHOLD && !fan_state) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_state = 1;
            printf("Fan ON\n");
        }
    } else if (temperature <= TEMP_THRESHOLD && fan_state) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_state = 0;
            printf("Fan OFF\n");
        }
    }
}

static void timer_callback(void *user_data) {
    (void)user_data;
    int32_t ut, up;
    if (read_raw_temperature(&ut) != 0) {
        fprintf(stderr, "Error: Failed to read raw temperature\n");
        return;
    }
    if (read_raw_pressure(&up) != 0) {
        fprintf(stderr, "Error: Failed to read raw pressure\n");
        return;
    }
    float temperature = calculate_temperature(ut);
    float pressure    = calculate_pressure(up, ut);
    add_to_buffer(temperature, pressure);
    printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
    control_fan(temperature);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(FAN_GPIO, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (gpioSetTimerFuncEx(0, SAMPLE_PERIOD_US, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set timer\n");
        gpioWrite(FAN_GPIO, 0);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("BMP180 monitoring started. Press Ctrl+C to exit.\n");
    while (running) {
        gpioDelay(100000);
    }
    gpioSetTimerFuncEx(0, SAMPLE_PERIOD_US, NULL, NULL);
    gpioWrite(FAN_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

