#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define BMP180_ADDR             0x77
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_MSB          0xF6
#define BMP180_REG_LSB          0xF7
#define BMP180_REG_XLSB         0xF8
#define BMP180_REG_CAL_AC1      0xAA
#define BMP180_REG_CAL_AC2      0xAC
#define BMP180_REG_CAL_AC3      0xAE
#define BMP180_REG_CAL_AC4      0xB0
#define BMP180_REG_CAL_AC5      0xB2
#define BMP180_REG_CAL_AC6      0xB4
#define BMP180_REG_CAL_B1       0xB6
#define BMP180_REG_CAL_B2       0xB8
#define BMP180_REG_CAL_MB       0xBA
#define BMP180_REG_CAL_MC       0xBC
#define BMP180_REG_CAL_MD       0xBE

#define BMP180_OSS              3
#define BMP180_CMD_TEMP         0x2E
#define BMP180_CMD_PRESSURE     0x34

#define GPIO_INTERRUPT_PIN      27
#define DEBOUNCE_DELAY_US       200000
#define LOG_INTERVAL_US         2000000
#define LOG_FILE_NAME           "pressure_log.txt"

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_logging_enabled = 0;
static volatile uint32_t     g_last_interrupt_tick = 0;

typedef struct {
    int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)userdata;
    if (tick - g_last_interrupt_tick > DEBOUNCE_DELAY_US) {
        g_logging_enabled = !g_logging_enabled;
        printf("Data logging %s\n", g_logging_enabled ? "enabled" : "disabled");
        g_last_interrupt_tick = tick;
    }
}

static int i2c_read_reg16(int handle, uint8_t reg, int16_t *out) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_read_reg16u(int handle, uint8_t reg, uint16_t *out) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_calibration(int handle, bmp180_cal_t *cal) {
    if (i2c_read_reg16(handle, BMP180_REG_CAL_AC1, &cal->ac1) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_AC2, &cal->ac2) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_AC3, &cal->ac3) < 0) return -1;
    if (i2c_read_reg16u(handle, BMP180_REG_CAL_AC4, &cal->ac4) < 0) return -1;
    if (i2c_read_reg16u(handle, BMP180_REG_CAL_AC5, &cal->ac5) < 0) return -1;
    if (i2c_read_reg16u(handle, BMP180_REG_CAL_AC6, &cal->ac6) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_B1,  &cal->b1)  < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_B2,  &cal->b2)  < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_MB,  &cal->mb)  < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_MC,  &cal->mc)  < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_MD,  &cal->md)  < 0) return -1;
    return 0;
}

static int read_raw_temperature(int handle, int32_t *ut) {
    char cmd = BMP180_CMD_TEMP;
    if (i2cWriteDevice(handle, &cmd, 1) < 0) return -1;
    gpioDelay(5000);
    char buf[2];
    if (i2cWriteByte(handle, BMP180_REG_MSB) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int handle, int32_t *up) {
    char cmd = BMP180_CMD_PRESSURE + (BMP180_OSS << 6);
    if (i2cWriteDevice(handle, &cmd, 1) < 0) return -1;
    gpioDelay(2000 + (3000 << BMP180_OSS));
    char buf[3];
    if (i2cWriteByte(handle, BMP180_REG_MSB) < 0) return -1;
    if (i2cReadDevice(handle, buf, 3) != 3) return -1;
    *up = ((int32_t)(buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut, const bmp180_cal_t *cal) {
    int32_t x1 = ((ut - (int32_t)cal->ac6) * (int32_t)cal->ac5) >> 15;
    int32_t x2 = ((int32_t)cal->mc << 11) / (x1 + (int32_t)cal->md);
    return x1 + x2;
}

static double compute_pressure(int32_t up, int32_t ut, const bmp180_cal_t *cal) {
    int32_t b5 = compute_b5(ut, cal);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)cal->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)cal->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)cal->ac1 * 4 + x3) << BMP180_OSS) + 2) >> 2);
    x1 = ((int32_t)cal->ac3 * b6) >> 13;
    x2 = ((int32_t)cal->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)cal->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000UL) p = (b7 * 2) / b4;
    else                   p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    return (double)(p + ((x1 + x2 + 3791) >> 4));
}

static void log_pressure(double pressure) {
    FILE *fp = fopen(LOG_FILE_NAME, "a");
    if (!fp) { perror("fopen"); return; }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f Pa\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, pressure);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int handle = i2cOpen(1, BMP180_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed (addr 0x%02X): %s\n", BMP180_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    bmp180_cal_t cal;
    if (read_calibration(handle, &cal) < 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_INTERRUPT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(GPIO_INTERRUPT_PIN, PI_PUD_UP);

    if (gpioSetISRFuncEx(GPIO_INTERRUPT_PIN, FALLING_EDGE, 0, interrupt_handler, NULL) < 0) {
        fprintf(stderr, "gpioSetISRFuncEx failed\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    printf("BMP180 initialized. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (g_logging_enabled) {
            int32_t ut, up;
            if (read_raw_temperature(handle, &ut) < 0) {
                fprintf(stderr, "I2C error reading temperature\n");
            } else if (read_raw_pressure(handle, &up) < 0) {
                fprintf(stderr, "I2C error reading pressure\n");
            } else {
                double pressure = compute_pressure(up, ut, &cal);
                log_pressure(pressure);
                printf("Pressure: %.2f Pa\n", pressure);
            }
        }
        gpioDelay(LOG_INTERVAL_US);
    }

    gpioSetISRFuncEx(GPIO_INTERRUPT_PIN, FALLING_EDGE, 0, NULL, NULL);
    i2cClose(handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

