#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define HEATER_GPIO 17
#define MAX_DUTY_CYCLE 0.8
#define LOG_FILE "heater_log.csv"
#define SAMPLE_INTERVAL_US 1000000

#define MAX31855_FAULT_OPEN 0x01
#define MAX31855_FAULT_GND 0x02
#define MAX31855_FAULT_VCC 0x04

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max31855(int handle, float *temp) {
    unsigned char rx[4] = {0};
    int ret = spiRead(handle, (char *)rx, 4);
    if (ret != 4) {
        fprintf(stderr, "SPI read failed (ret=%d)\n", ret);
        return -1;
    }
    if (rx[3] & 0x01) {
        fprintf(stderr, "MAX31855 fault: ");
        if (rx[1] & MAX31855_FAULT_OPEN) fprintf(stderr, "open circuit ");
        if (rx[1] & MAX31855_FAULT_GND) fprintf(stderr, "short to GND ");
        if (rx[1] & MAX31855_FAULT_VCC) fprintf(stderr, "short to VCC ");
        fprintf(stderr, "\n");
        return -2;
    }
    int16_t raw = (int16_t)((rx[0] << 8) | rx[1]);
    *temp = raw * 0.25f;
    return 0;
}

static float pi_control(float setpoint, float actual, float *integral, float dt) {
    float error = setpoint - actual;
    *integral += error * dt;
    if (*integral > MAX_DUTY_CYCLE) *integral = MAX_DUTY_CYCLE;
    if (*integral < 0.0f) *integral = 0.0f;
    float output = 2.0f * error + 0.1f * (*integral);
    if (output > MAX_DUTY_CYCLE) output = MAX_DUTY_CYCLE;
    if (output < 0.0f) output = 0.0f;
    return output;
}

static void log_data(FILE *f, float temp, float duty, const char *status) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(f, "%s,%.2f,%.2f,%s\n", ts, temp, duty, status);
    fflush(f);
}

int main(void) {
    float setpoint = 25.0f;
    float integral = 0.0f;
    float last_temp = 0.0f;
    float duty = 0.0f;
    int consecutive_errors = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioPWM(HEATER_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Cannot open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "Timestamp,Temperature(DegC),DutyCycle,Status\n");

    while (running) {
        float temp;
        int rc = read_max31855(spi_handle, &temp);
        if (rc == 0) {
            consecutive_errors = 0;
            last_temp = temp;
            float dt = 1.0f;
            duty = pi_control(setpoint, temp, &integral, dt);
            gpioPWM(HEATER_GPIO, (int)(duty * 1000000.0f));
            log_data(log_file, temp, duty, "OK");
        } else if (rc == -2) {
            consecutive_errors++;
            if (consecutive_errors > 3) {
                fprintf(stderr, "Too many MAX31855 faults, aborting\n");
                break;
            }
            gpioPWM(HEATER_GPIO, 0);
            log_data(log_file, last_temp, 0.0f, "FAULT");
        } else {
            consecutive_errors++;
            if (consecutive_errors > 3) {
                fprintf(stderr, "Too many SPI errors, aborting\n");
                break;
            }
            gpioPWM(HEATER_GPIO, 0);
            log_data(log_file, last_temp, 0.0f, "SPI_ERROR");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioPWM(HEATER_GPIO, 0);
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

