#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define POLL_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm(int pin, int duty) {
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d (duty=%d)\n", pin, duty);
        return -1;
    }
    return 0;
}

static void turn_off_led(void) {
    set_pwm(RED_PIN, 255);
    set_pwm(GREEN_PIN, 255);
    set_pwm(BLUE_PIN, 255);
}

static void set_led_color(int r, int g, int b) {
    set_pwm(RED_PIN,   255 - r);
    set_pwm(GREEN_PIN, 255 - g);
    set_pwm(BLUE_PIN,  255 - b);
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    char buffer[16];
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        if (ferror(fp)) {
            perror("Error reading temperature file");
        } else {
            fprintf(stderr, "Error: unexpected EOF reading temperature file\n");
        }
        fclose(fp);
        return -1;
    }

    fclose(fp);

    char *endptr;
    long temp = strtol(buffer, &endptr, 10);
    if (endptr == buffer) {
        fprintf(stderr, "Error: temperature file does not contain a valid number\n");
        return -1;
    }

    return (int)temp;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: sigaction failed");
        turn_off_led();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    turn_off_led();

    while (running) {
        int temp = read_cpu_temp();
        if (temp < 0) {
            fprintf(stderr, "Warning: temperature read failed, skipping update\n");
        } else {
            int r, g, b;
            if (temp < 40000) {
                r = 0; g = 0; b = 255;
            } else if (temp < 60000) {
                r = 0; g = 255; b = 0;
            } else {
                r = 255; g = 0; b = 0;
            }

            set_led_color(r, g, b);
            printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temp, r, g, b);
            fflush(stdout);
        }

        usleep(POLL_INTERVAL_US);
    }

    turn_off_led();
    gpioTerminate();
    return EXIT_SUCCESS;
}

