#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define SERVER_IP "yourserver.com"
#define SERVER_PORT 80
#define API_ENDPOINT "/api/humidity"
#define MAX_RETRIES 3
#define DHT22_TIMEOUT 255

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

int read_dht22(float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = PI_HIGH;
    int bit_count = 0;
    int i;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, PI_LOW);
    gpioDelay(2000);
    gpioWrite(DHT22_GPIO, PI_HIGH);
    gpioDelay(30);
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    uint32_t start = gpioTick();
    while (gpioRead(DHT22_GPIO) == PI_HIGH) {
        if (gpioTick() - start > DHT22_TIMEOUT) return -1;
    }
    start = gpioTick();
    while (gpioRead(DHT22_GPIO) == PI_LOW) {
        if (gpioTick() - start > DHT22_TIMEOUT) return -1;
    }
    start = gpioTick();
    while (gpioRead(DHT22_GPIO) == PI_HIGH) {
        if (gpioTick() - start > DHT22_TIMEOUT) return -1;
    }

    for (i = 0; i < 40; i++) {
        start = gpioTick();
        while (gpioRead(DHT22_GPIO) == PI_LOW) {
            if (gpioTick() - start > DHT22_TIMEOUT) return -1;
        }
        uint32_t pulse_start = gpioTick();
        while (gpioRead(DHT22_GPIO) == PI_HIGH) {
            if (gpioTick() - pulse_start > DHT22_TIMEOUT) return -1;
        }
        uint32_t pulse_length = gpioTick() - pulse_start;
        data[i / 8] <<= 1;
        if (pulse_length > 50) {
            data[i / 8] |= 1;
        }
        bit_count++;
    }

    if (bit_count != 40) return -1;

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -1;

    *humidity = (float)(((unsigned int)data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((unsigned int)(data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) *temperature = -*temperature;

    return 0;
}

int post_data(float temperature, float humidity) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        perror("inet_pton");
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("connect");
        close(sockfd);
        return -1;
    }

    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    char json_string[256];
    snprintf(json_string, sizeof(json_string),
             "{\"timestamp\":\"%s\",\"temperature\":%.1f,\"humidity\":%.1f}",
             timestamp, temperature, humidity);

    char request[512];
    snprintf(request, sizeof(request),
             "POST %s HTTP/1.1\r\nHost: %s\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n%s",
             API_ENDPOINT, SERVER_IP, strlen(json_string), json_string);

    if (write(sockfd, request, strlen(request)) < 0) {
        perror("write");
        close(sockfd);
        return -1;
    }

    char response[1024];
    int bytes_received = read(sockfd, response, sizeof(response) - 1);
    if (bytes_received < 0) {
        perror("read");
        close(sockfd);
        return -1;
    }
    response[bytes_received] = '\0';

    close(sockfd);

    if (strstr(response, "HTTP/1.1 200 OK") == NULL) {
        fprintf(stderr, "Error: Server returned: %s\n", response);
        return -1;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;
    int retries = 0;

    while (!terminate) {
        if (read_dht22(&temperature, &humidity) == 0) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
            if (post_data(temperature, humidity) != 0) {
                fprintf(stderr, "Error posting data, retrying...\n");
                retries++;
                if (retries >= MAX_RETRIES) {
                    fprintf(stderr, "Max retries reached, exiting.\n");
                    break;
                }
                sleep(5);
                continue;
            }
            retries = 0;
        } else {
            fprintf(stderr, "Error reading DHT22 sensor, retrying...\n");
            retries++;
            if (retries >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, exiting.\n");
                break;
            }
            sleep(5);
            continue;
        }
        sleep(60);
    }

    gpioTerminate();
    return 0;
}

