#define BMP180_CMD_TEMP         0x2E
#define BMP180_CMD_PRESSURE     (0x34 + (BMP180_OSS << 6))
#define BMP180_CONV_DELAY_US    26000
#define BMP180_TEMP_DELAY_US    5000

#define BUTTON_GPIO             4
#define DEBOUNCE_US             200000
#define LOG_INTERVAL_S          2

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_logging_enabled = 0;
static volatile uint32_t     g_last_interrupt_tick = 0;

static int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void button_interrupt_handler(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)userdata;
    uint32_t elapsed = tick - g_last_interrupt_tick;
    if (elapsed > DEBOUNCE_US) {
        g_logging_enabled = !g_logging_enabled;
        printf("Data logging %s\n", g_logging_enabled ? "enabled" : "disabled");
        fflush(stdout);
        g_last_interrupt_tick = tick;
    }
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    return 0;
}

static int read_calibration_data(int handle) {
    uint8_t buf[22];
    if (i2c_read_reg(handle, BMP180_REG_CAL_AC1, buf, sizeof(buf)) < 0) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        return -1;
    }
    ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1  = (int16_t)((buf[12] << 8) | buf[13]);
    b2  = (int16_t)((buf[14] << 8) | buf[15]);
    mb  = (int16_t)((buf[16] << 8) | buf[17]);
    mc  = (int16_t)((buf[18] << 8) | buf[19]);
    md  = (int16_t)((buf[20] << 8) | buf[21]);
    if (ac1 == 0 && ac2 == 0 && ac3 == 0) {
        fprintf(stderr, "Invalid calibration data (all zeros) - sensor not present?\n");
        return -1;
    }
    return 0;
}

static int read_raw_temperature(int handle, int32_t *raw_temp) {
    if (i2c_write_reg(handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    gpioDelay(BMP180_TEMP_DELAY_US);
    uint8_t buf[2];
    if (i2c_read_reg(handle, BMP180_REG_MSB, buf, 2) < 0) return -1;
    *raw_temp = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int handle, int32_t *raw_pressure) {
    if (i2c_write_reg(handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE) < 0) return -1;
    gpioDelay(BMP180_CONV_DELAY_US);
    uint8_t buf[3];
    if (i2c_read_reg(handle, BMP180_REG_MSB, buf, 3) < 0) return -1;
    *raw_pressure = ((int32_t)(buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

static int32_t compute_b5(int32_t raw_temp) {
    int32_t x1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    return x1 + x2;
}

static double calculate_pressure(int32_t raw_pressure, int32_t b5) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1 * 4 + x3) << BMP180_OSS) + 2) >> 2);
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)raw_pressure - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000UL) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return (double)p / 100.0;
}

static void log_pressure(double pressure) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f hPa\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, pressure);
    }
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %s\n", BMP180_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (read_calibration_data(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);
    if (gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, button_interrupt_handler, NULL) < 0) {
        fprintf(stderr, "Error setting up button interrupt: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up SIGINT handler: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("BMP180 pressure logger started. Press button on GPIO %d to toggle logging.\n", BUTTON_GPIO);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        if (g_logging_enabled) {
            int32_t raw_temp, raw_pressure;
            if (read_raw_temperature(i2c_handle, &raw_temp) < 0) {
                fprintf(stderr, "Error reading raw temperature: %s\n", strerror(errno));
            } else if (read_raw_pressure(i2c_handle, &raw_pressure) < 0) {
                fprintf(stderr, "Error reading raw pressure: %s\n", strerror(errno));
            } else {
                int32_t b5 = compute_b5(raw_temp);
                double pressure = calculate_pressure(raw_pressure, b5);
                log_pressure(pressure);
                printf("Pressure: %.2f hPa\n", pressure);
                fflush(stdout);
            }
        } else {
            printf("Logging disabled. Press button to enable.\n");
            fflush(stdout);
        }
        gpioDelay(LOG_INTERVAL_S * 1000000);
    }

    printf("\nShutting down...\n");
    gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, NULL, NULL);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

