#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <getopt.h>
#include <errno.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define POST_INTERVAL 10
#define DHT22_TIMEOUT 255
#define DHT22_START_LOW_US 1000
#define DHT22_START_HIGH_US 30
#define DHT22_BIT_THRESHOLD_US 50

static volatile sig_atomic_t running = 1;
static char *api_url = "http://your-the-librarys-API-call.com/api/humidity";

typedef struct {
    float humidity;
    float temperature;
    int error;
} DHT22Data;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(int gpio, float *humidity, float *temperature) {
    int data[5] = {0, 0, 0, 0, 0};
    int last_state = PI_HIGH;
    int bit_count = 0;
    int i;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, PI_LOW);
    gpioDelay(DHT22_START_LOW_US);
    gpioWrite(gpio, PI_HIGH);
    gpioDelay(DHT22_START_HIGH_US);
    gpioSetMode(gpio, PI_INPUT);

    uint32_t start = gpioTick();
    while (gpioRead(gpio) == PI_HIGH) {
        if (gpioTick() - start > DHT22_TIMEOUT) return -1;
    }
    start = gpioTick();
    while (gpioRead(gpio) == PI_LOW) {
        if (gpioTick() - start > DHT22_TIMEOUT) return -1;
    }
    start = gpioTick();
    while (gpioRead(gpio) == PI_HIGH) {
        if (gpioTick() - start > DHT22_TIMEOUT) return -1;
    }

    for (i = 0; i < 40; i++) {
        start = gpioTick();
        while (gpioRead(gpio) == PI_LOW) {
            if (gpioTick() - start > DHT22_TIMEOUT) return -1;
        }
        uint32_t pulse_start = gpioTick();
        while (gpioRead(gpio) == PI_HIGH) {
            if (gpioTick() - pulse_start > DHT22_TIMEOUT) return -1;
        }
        uint32_t pulse_length = gpioTick() - pulse_start;
        if (pulse_length > DHT22_BIT_THRESHOLD_US) {
            data[bit_count / 8] |= (1 << (7 - (bit_count % 8)));
        }
        bit_count++;
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        return -1;
    }

    *humidity = (float)(((unsigned int)data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((unsigned int)(data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) *temperature = -*temperature;

    return 0;
}

static char *format_json(float humidity, float temperature) {
    char *json_string = malloc(256);
    if (!json_string) return NULL;
    snprintf(json_string, 256, "{\"humidity\": %.1f, \"temperature\": %.1f}", humidity, temperature);
    return json_string;
}

static int post_data(const char *url, const char *json_data) {
    CURL *curl = curl_easy_init();
    if (!curl) return -1;

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) { curl_easy_cleanup(curl); return -1; }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    int ret = -1;
    if (res == CURLE_OK) {
        long http_code = 0;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
        if (http_code >= 200 && http_code < 300) ret = 0;
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return ret;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                api_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s api_url]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("dht22_sensor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting DHT22 sensor monitoring on GPIO %d", DHT22_GPIO);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) {
        syslog(LOG_ERR, "curl_global_init failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        DHT22Data dht22_data;
        dht22_data.error = 0;
        dht22_data.humidity = 0.0;
        dht22_data.temperature = 0.0;

        int retries = 0;
        while (retries < MAX_RETRIES && running) {
            if (read_dht22(DHT22_GPIO, &dht22_data.humidity, &dht22_data.temperature) == 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                syslog(LOG_WARNING, "DHT22 read failed, retrying (%d/%d)", retries, MAX_RETRIES);
                sleep(2);
            }
        }

        if (dht22_data.error == 0) {
