                        syslog(LOG_INFO, "Data posted successfully: %s", json_data);
                        break;
                    }
                    post_retries++;
                    if (post_retries < MAX_RETRIES) {
                        syslog(LOG_WARNING, "POST failed, retrying (%d/%d)", post_retries, MAX_RETRIES);
                        sleep(2);
                    }
                }
                free(json_data);
            } else {
                syslog(LOG_ERR, "Failed to allocate memory for JSON");
            }
        } else {
            syslog(LOG_ERR, "Failed to read DHT22 sensor after %d retries", MAX_RETRIES);
        }

        for (int i = 0; i < POST_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    curl_global_cleanup();
    gpioTerminate();
    syslog(LOG_INFO, "Exiting DHT22 sensor monitoring");
    closelog();
    return EXIT_SUCCESS;
}

