/*
 * Raspberry Pi 5 Active Cooler – Temperature-controlled fan daemon.
 *
 * Reads  /sys/class/thermal/thermal_zone0/temp  (CPU temperature in milli-Celsius)
 * Reads  /sys/class/thermal/cooling_device0/cur_state  (current fan state)
 * Writes /sys/class/thermal/cooling_device0/cur_state  (new fan state)
 * Logs  /var/log/fan_control.log
 *
 * Build:  gcc -O2 -Wall -Wextra -o fan_control fan_control.c
 * Run:    sudo ./fan_control   (needs write access to cooling_device0)
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>

#define TEMP_FILE        "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE   "/sys/class/thermal/cooling_device0/cur_state"
#define MAX_STATE_FILE   "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE         "/var/log/fan_control.log"
#define POLL_INTERVAL_S  5

#define TEMP_THRESHOLD_0 45000   /* 45 °C  – fan off */
#define TEMP_THRESHOLD_1 55000   /* 55 °C  – low speed */
#define TEMP_THRESHOLD_2 65000   /* 65 °C  – medium speed */
#define TEMP_THRESHOLD_3 65000   /* 65 °C+ – max speed */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_message(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, message);
    } else {
        fprintf(fp, "(unknown time): %s\n", message);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Sysfs helpers                                                       */
/* ------------------------------------------------------------------ */
static int read_sysfs_int(const char *path, int *out)
{
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }

    char buf[32];
    ssize_t n = read(fd, buf, sizeof(buf) - 1);
    if (n == -1) {
        fprintf(stderr, "read(%s): %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);

    buf[n] = '\0';
    char *end = NULL;
    errno = 0;
    long val = strtol(buf, &end, 10);
    if (errno != 0 || end == buf || *end != '\n' && *end != '\0') {
        fprintf(stderr, "parse(%s): invalid integer\n", path);
        return -1;
    }

    *out = (int)val;
    return 0;
}

static int write_sysfs_int(const char *path, int value)
{
    int fd = open(path, O_WRONLY);
    if (fd == -1) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }

    char buf[32];
    int len = snprintf(buf, sizeof(buf), "%d\n", value);
    if (len < 0 || (size_t)len >= sizeof(buf)) {
        fprintf(stderr, "snprintf failed for %s\n", path);
        close(fd);
        return -1;
    }

    ssize_t written = write(fd, buf, (size_t)len);
    if (written == -1) {
        fprintf(stderr, "write(%s): %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    if (written != len) {
        fprintf(stderr, "write(%s): partial write (%zd/%d)\n",
                path, written, len);
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Fan control logic                                                   */
/* ------------------------------------------------------------------ */
static int determine_fan_speed(int temperature)
{
    if (temperature < TEMP_THRESHOLD_0) return 0;
    if (temperature < TEMP_THRESHOLD_1) return 1;
    if (temperature < TEMP_THRESHOLD_2) return 2;
    return 3;
}

static int set_fan_speed(int speed)
{
    int current;
    if (read_sysfs_int(FAN_STATE_FILE, &current) == -1) {
        fprintf(stderr, "Cannot read current fan state; aborting.\n");
        return -1;
    }

    if (current == speed)
        return 0;                       /* no change needed */

    if (write_sysfs_int(FAN_STATE_FILE, speed) == -1) {
        fprintf(stderr, "Failed to set fan speed to %d\n", speed);
        return -1;
    }

    char msg[128];
    snprintf(msg, sizeof(msg), "Fan speed set to %d", speed);
    log_message(msg);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    int max_state;
    if (read_sysfs_int(MAX_STATE_FILE, &max_state) == -1) {
        fprintf(stderr, "Cannot read cooling_device max_state; aborting.\n");
        return EXIT_FAILURE;
    }
    if (max_state < 0 || max_state > 3) {
        fprintf(stderr, "Unexpected max_state %d; aborting.\n", max_state);
        return EXIT_FAILURE;
    }

    log_message("Fan control daemon started.");

    while (g_running) {
        int temperature;
        if (read_sysfs_int(TEMP_FILE, &temperature) == -1) {
            fprintf(stderr, "Failed to read temperature; retrying in %d s.\n",
                    POLL_INTERVAL_S);
            sleep(POLL_INTERVAL_S);
            continue;
        }

        int desired = determine_fan_speed(temperature);

        if (desired > max_state)
            desired = max_state;

        if (set_fan_speed(desired) == -1) {
            fprintf(stderr, "Fan control failed; retrying in %d s.\n",
                    POLL_INTERVAL_S);
        }

        sleep(POLL_INTERVAL_S);
    }

    /* Graceful shutdown */
    if (set_fan_speed(0) == -1) {
        fprintf(stderr, "Warning: failed to turn off fan on exit.\n");
    }
    log_message("Fan control daemon shutting down.");
    return EXIT_SUCCESS;
}

