#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define MIN_TEMP 40.0
#define MAX_TEMP 70.0
#define MIN_DUTY 0
#define MAX_DUTY 100
#define LOG_FILE "cooling_log.csv"
#define POLL_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static float read_cpu_temp(void) {
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!fp) {
        perror("Error opening temperature file");
        return -1.0f;
    }
    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1.0f;
    }
    fclose(fp);
    return (float)temp_milli / 1000.0f;
}

static int set_fan_speed(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Invalid duty cycle: %d\n", duty_cycle);
        return -1;
    }
    int range = gpioGetPWMrange(FAN_GPIO);
    if (range < 0) {
        fprintf(stderr, "Failed to get PWM range\n");
        return -1;
    }
    int pwm_value = (duty_cycle * range) / 100;
    if (gpioPWM(FAN_GPIO, pwm_value) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
        return -1;
    }
    return 0;
}

static int log_data(float temperature, int duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set up signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency to %d Hz\n", PWM_FREQUENCY);
        gpioTerminate();
        return 1;
    }

    if (set_fan_speed(0) != 0) {
        fprintf(stderr, "Failed to initialize fan to 0%%\n");
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (!fp) {
            perror("Error creating log file");
            gpioTerminate();
            return 1;
        }
        fprintf(fp, "Timestamp,Temperature (C),Duty Cycle (%%)\n");
        fclose(fp);
    } else {
        fclose(fp);
    }

    while (running) {
        float temperature = read_cpu_temp();
        if (temperature < 0.0f) {
            fprintf(stderr, "Failed to read CPU temperature, retrying in %d seconds...\n", POLL_INTERVAL);
            sleep(POLL_INTERVAL);
            continue;
        }

        int duty_cycle;
        if (temperature <= MIN_TEMP) {
            duty_cycle = MIN_DUTY;
        } else if (temperature >= MAX_TEMP) {
            duty_cycle = MAX_DUTY;
        } else {
            duty_cycle = (int)(((temperature - MIN_TEMP) / (MAX_TEMP - MIN_TEMP)) * (MAX_DUTY - MIN_DUTY) + MIN_DUTY);
        }

        if (set_fan_speed(duty_cycle) != 0) {
            fprintf(stderr, "Failed to set fan speed\n");
        }

        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        sleep(POLL_INTERVAL);
    }

    set_fan_speed(0);
    gpioTerminate();
    return 0;
}

