#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_A 17
#define GPIO_B 18
#define PULSES_PER_REVOLUTION 360
#define LOG_FILE "encoder_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_position(float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Angle: %.2f\n", timestamp, angle) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    int last_state = -1;
    int current_state;
    int pulse_count = 0;
    float angle;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_A, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", GPIO_A);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_B, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", GPIO_B);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_A, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up on GPIO %d\n", GPIO_A);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(GPIO_B, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up on GPIO %d\n", GPIO_B);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        current_state = (gpioRead(GPIO_A) << 1) | gpioRead(GPIO_B);

        if (current_state != last_state) {
            if (last_state != -1) {
                if ((last_state == 0 && current_state == 1) ||
                    (last_state == 1 && current_state == 3) ||
                    (last_state == 3 && current_state == 2) ||
                    (last_state == 2 && current_state == 0)) {
                    pulse_count++;
                } else if ((last_state == 0 && current_state == 2) ||
                           (last_state == 2 && current_state == 3) ||
                           (last_state == 3 && current_state == 1) ||
                           (last_state == 1 && current_state == 0)) {
                    pulse_count--;
                }
            }

            angle = (float)(pulse_count % PULSES_PER_REVOLUTION) / PULSES_PER_REVOLUTION * 360.0f;

            if (log_position(angle) != 0) {
                fprintf(stderr, "Error logging position, continuing...\n");
            }

            last_state = current_state;
        }

        gpioDelay(1000);
    }

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

