/*
 * ADPD144RI Red/IR Photometric Sensor Logger with GPIO Threshold Indicator
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: ADPD144RI (I2C address 0x50)
 * LED:    GPIO17 (active-high)
 *
 * Build:  gcc -O2 -Wall -o adpd144ri_logger adpd144ri_logger.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- ADPD144RI I2C address ---- */
#define ADPD144RI_ADDR 0x50

/* ---- Register map (from ADPD144RI datasheet) ---- */
#define REG_DEVID       0x00
#define REG_MODE        0x01
#define REG_DATA_RED_L  0x08
#define REG_DATA_RED_H  0x09
#define REG_DATA_IR_L   0x0A
#define REG_DATA_IR_H   0x0B

#define EXPECTED_DEVID  0x44

/* ---- GPIO ---- */
#define GPIO_CHIP       "gpiochip0"
#define GPIO_LED        17

/* ---- Threshold ---- */
#define IR_THRESHOLD    2000

/* ---- Sampling ---- */
#define SAMPLE_PERIOD_MS 100

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;
static struct gpiod_line *g_led_line = NULL;
static struct gpiod_chip *g_chip = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_led_line) {
        gpiod_line_set_value(g_led_line, 0);
        gpiod_line_release(g_led_line);
        g_led_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int fd, uint8_t reg_l, uint16_t *val)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg_l, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, reg_l + 1, &hi) < 0) return -1;
    *val = ((uint16_t)hi << 8) | lo;
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_sensor(int fd)
{
    uint8_t devid = 0;
    if (i2c_read_reg8(fd, REG_DEVID, &devid) < 0) {
        fprintf(stderr, "Cannot read DEVID — sensor absent or bus error.\n");
        return -1;
    }
    if (devid != EXPECTED_DEVID) {
        fprintf(stderr, "Unexpected DEVID: 0x%02X (expected 0x%02X).\n",
                devid, EXPECTED_DEVID);
        return -1;
    }

    /* Put sensor in standby before configuration */
    if (i2c_write_reg8(fd, REG_MODE, 0x00) < 0) return -1;
    usleep(10000);

    /* Configure mode register (example: 0x01 = normal operation) */
    if (i2c_write_reg8(fd, REG_MODE, 0x01) < 0) return -1;
    usleep(10000);

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_sensor(int fd, uint16_t *red, uint16_t *ir)
{
    if (i2c_read_reg16(fd, REG_DATA_RED_L, red) < 0) return -1;
    if (i2c_read_reg16(fd, REG_DATA_IR_L, ir) < 0)   return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t red, uint16_t ir)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) return;
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%u,%u\n", ts, red, ir);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (init_sensor(g_i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen("adpd144ri_log.txt", "a");
    if (!g_log_fp) {
        perror("fopen adpd144ri_log.txt");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip and request LED line ---- */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        perror("gpiod_chip_open_by_name");
        cleanup();
        return EXIT_FAILURE;
    }

    g_led_line = gpiod_chip_get_line(g_chip, GPIO_LED);
    if (!g_led_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_led_line, "adpd144ri_led", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADPD144RI logger started. Press Ctrl+C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        uint16_t red, ir;

        if (read_sensor(g_i2c_fd, &red, &ir) < 0) {
            fprintf(stderr, "Read error — continuing.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        log_data(g_log_fp, red, ir);

        int led_state = (ir > IR_THRESHOLD) ? 1 : 0;
        if (gpiod_line_set_value(g_led_line, led_state) < 0) {
            perror("gpiod_line_set_value");
        }

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

