        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int fd, uint8_t reg_l, uint16_t *val)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg_l, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, reg_l + 1, &hi) < 0) return -1;
    *val = ((uint16_t)hi << 8) | lo;
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_sensor(int fd)
{
    uint8_t devid = 0;
    if (i2c_read_reg8(fd, REG_DEVID, &devid) < 0) {
        fprintf(stderr, "Cannot read DEVID — sensor absent or bus error.\n");
        return -1;
    }
    if (devid != EXPECTED_DEVID) {
        fprintf(stderr, "Unexpected DEVID: 0x%02X (expected 0x%02X).\n",
                devid, EXPECTED_DEVID);
        return -1;
    }

    /* Put sensor in standby before configuration */
    if (i2c_write_reg8(fd, REG_MODE, 0x00) < 0) return -1;
    usleep(10000);

    /* Configure mode register (example: 0x01 = normal operation) */
    if (i2c_write_reg8(fd, REG_MODE, 0x01) < 0) return -1;
    usleep(10000);

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_sensor(int fd, uint16_t *red, uint16_t *ir)
{
    if (i2c_read_reg16(fd, REG_DATA_RED_L, red) < 0) return -1;
    if (i2c_read_reg16(fd, REG_DATA_IR_L, ir) < 0)   return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t red, uint16_t ir)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) return;
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%u,%u\n", ts, red, ir);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (init_sensor(g_i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen("adpd144ri_log.txt", "a");
    if (!g_log_fp) {
        perror("fopen adpd144ri_log.txt");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip and request LED line ---- */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        perror("gpiod_chip_open_by_name");
        cleanup();
        return EXIT_FAILURE;
    }

    g_led_line = gpiod_chip_get_line(g_chip, GPIO_LED);
    if (!g_led_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_led_line, "adpd144ri_led", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADPD144RI logger started. Press Ctrl+C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        uint16_t red, ir;

        if (read_sensor(g_i2c_fd, &red, &ir) < 0) {
            fprintf(stderr, "Read error — continuing.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        log_data(g_log_fp, red, ir);

        int led_state = (ir > IR_THRESHOLD) ? 1 : 0;
        if (gpiod_line_set_value(g_led_line, led_state) < 0) {
            perror("gpiod_line_set_value");
        }

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

