/*
 * ADPD144RI Red/IR Photometric Sensor Logger
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    /dev/i2c-1 (GPIO2=SDA, GPIO3=SCL)
 * LED:    GPIO17 (active-high)
 *
 * Build:  gcc -O2 -Wall -Wextra -o adpd144ri_logger adpd144ri_logger.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- ADPD144RI I2C address (7-bit) ---- */
#define ADPD144RI_ADDR 0x58

/* ---- Register map (from ADPD144RI datasheet) ---- */
#define REG_DEVID       0x00
#define REG_MODE        0x01
#define REG_DATA_RED    0x02
#define REG_DATA_IR     0x04
#define REG_THRESHOLD   0x06
#define REG_INT_STATUS  0x08

#define EXPECTED_DEVID  0x44

/* ---- GPIO ---- */
#define GPIO_CHIP       "gpiochip0"
#define GPIO_LED        17

/* ---- Threshold ---- */
#define IR_THRESHOLD    2000

/* ---- Sampling ---- */
#define SAMPLE_PERIOD_MS 100

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_led  = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_led) {
        gpiod_line_set_value(g_led, 0);
        gpiod_line_release(g_led);
        g_led = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit register. Returns 0 on success, -1 on error. */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an 8-bit register. Returns 0 on success, -1 on error. */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t red, uint16_t ir)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, red, ir);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(/dev/i2c-1) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                ADPD144RI_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor presence via DEVID ---- */
    uint8_t devid = 0;
    if (i2c_read_reg8(g_i2c_fd, REG_DEVID, &devid) != 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X (I2C error or absent)\n",
                ADPD144RI_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }
    if (devid != EXPECTED_DEVID) {
        fprintf(stderr, "Unexpected DEVID: 0x%02X (expected 0x%02X)\n",
                devid, EXPECTED_DEVID);
        cleanup();
        return EXIT_FAILURE;
    }
    printf("ADPD144RI detected (DEVID=0x%02X)\n", devid);

    /* ---- Open GPIO chip and request LED line ---- */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                GPIO_CHIP, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_led = gpiod_chip_get_line(g_chip, GPIO_LED);
    if (!g_led) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                GPIO_LED, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_led, "adpd144ri_logger", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen("adpd144ri_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(adpd144ri_log.txt) failed: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,red,ir\n");
        fflush(g_log_fp);
    }

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint16_t red = 0, ir = 0;

        if (i2c_read_reg16(g_i2c_fd, REG_DATA_RED, &red) != 0 ||
            i2c_read_reg16(g_i2c_fd, REG_DATA_IR, &ir) != 0) {
            fprintf(stderr, "I2C read error; continuing\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        log_data(g_log_fp, red, ir);

        if (ir > IR_THRESHOLD) {
            if (gpiod_line_set_value(g_led, 1) < 0) {
                fprintf(stderr, "gpiod_line_set_value(1) failed: %s\n",
                        strerror(errno));
            }
        } else {
            if (gpiod_line_set_value(g_led, 0) < 0) {
                fprintf(stderr, "gpiod_line_set_value(0) failed: %s\n",
                        strerror(errno));
            }
        }

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

