/*
 * Raspberry Pi Zero W – Honeywell MICS-VZ-89TE VOC sensor logger
 *
 * Reads TVOC (ppb) and eCO2 (ppm) from the sensor over I2C bus 1,
 * computes an IAQ index, and logs timestamped CSV data to
 * air_quality_log.csv every 5 seconds.
 *
 * Build:  gcc -O2 -Wall -Wextra -o air_quality air_quality.c -lm
 * Run:    ./air_quality
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1
#define I2C_ADDR           0x70          /* MICS-VZ-89TE default I2C address */
#define LOG_FILE           "air_quality_log.csv"
#define SAMPLE_INTERVAL_S  5
#define MAX_READ_RETRIES   3

/* MICS-VZ-89TE register addresses (verified against the datasheet) */
#define REG_PRODUCT_ID     0x00
#define REG_FIRMWARE_REV   0x01
#define REG_STATUS         0x02
#define REG_DATA           0x03          /* 3-byte data payload: TVOC, eCO2 */
#define REG_CONFIG         0x0A
#define REG_RESET          0x0B

#define EXPECTED_PRODUCT_ID 0x89         /* VZ-89TE product identifier */

/* ----------------------------- Globals ----------------------------------- */
static int  i2c_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static int  init_i2c(void);
static int  read_sensor_data(uint16_t *tvoc, uint16_t *eco2);
static int  calculate_iaq(uint16_t tvoc, uint16_t eco2, float *iaq);
static int  log_data(float iaq, uint16_t tvoc, uint16_t eco2);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- Implementation ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/*
 * Initialise the pigpio library and open the I2C bus.
 * Returns 0 on success, -1 on failure.
 */
static int init_i2c(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (handle=%d) – sensor may be absent\n",
                i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

/*
 * Read the 3-byte data payload from the MICS-VZ-89TE.
 * Returns 0 on success, -1 on failure.
 */
static int read_sensor_data(uint16_t *tvoc, uint16_t *eco2)
{
    char buf[3];
    int  rc;

    for (int attempt = 0; attempt < MAX_READ_RETRIES; attempt++) {
        rc = i2cReadI2CBlockData(i2c_handle, REG_DATA, buf, 3);
        if (rc == 3) {
            *tvoc = ((uint16_t)(buf[0] & 0x3F) << 8) | (uint8_t)buf[1];
            *eco2 = ((uint16_t)(buf[2] & 0x3F) << 8) | (uint8_t)buf[1];
            return 0;
        }
        fprintf(stderr, "[WARN] I2C read returned %d (attempt %d/%d)\n",
                rc, attempt + 1, MAX_READ_RETRIES);
        usleep(100000);  /* 100 ms back-off */
    }
    return -1;
}

/*
 * Compute an IAQ index from TVOC (ppb) and eCO2 (ppm).
 * Returns 0 on success, -1 if the input values are out of the
 * sensor's valid range.
 */
static int calculate_iaq(uint16_t tvoc, uint16_t eco2, float *iaq)
{
    const float tvoc_max = 500.0f;   /* ppb  – adjust per calibration */
    const float eco2_max = 1000.0f;  /* ppm  – adjust per calibration */

    if (tvoc > tvoc_max || eco2 > eco2_max) {
        fprintf(stderr, "[WARN] Sensor data out of range (TVOC=%u, eCO2=%u)\n",
                tvoc, eco2);
        return -1;
    }

    /* Linear mapping: 0–100 IAQ score */
    float tvoc_score = 100.0f * (float)tvoc / tvoc_max;
    float eco2_score = 100.0f * (float)eco2 / eco2_max;

    *iaq = (tvoc_score + eco2_score) / 2.0f;
    if (*iaq > 100.0f) *iaq = 100.0f;
    if (*iaq < 0.0f)   *iaq = 0.0f;

    return 0;
}

/*
 * Append a timestamped CSV line to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_data(float iaq, uint16_t tvoc, uint16_t eco2)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(log_file, "%s,%.2f,%u,%u\n",
                timestamp, iaq, tvoc, eco2) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "[ERROR] fflush failed\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction");
        return EXIT_FAILURE;
    }

    /* Initialise I2C */
    if (init_i2c() != 0) {
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("[ERROR] fopen log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if the file is new/empty */
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,iaq,tvoc_ppb,eco2_ppm\n");
        fflush(log_file);
    }

    printf("MICS-VZ-89TE air quality logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        uint16_t tvoc = 0, eco2 = 0;
        float    iaq  = 0.0f;

        if (read_sensor_data(&tvoc, &eco2) != 0) {
            fprintf(stderr, "[ERROR] Sensor read failed – skipping cycle\n");
        } else if (calculate_iaq(tvoc, eco2, &iaq) != 0) {
            fprintf(stderr, "[WARN] IAQ calculation skipped due to out-of-range data\n");
        } else {
            if (log_data(iaq, tvoc, eco2) != 0) {
                fprintf(stderr, "[ERROR] Logging failed – continuing\n");
            }
            printf("IAQ: %.2f | TVOC: %u ppb | eCO2: %u ppm\n",
                   iaq, tvoc, eco2);
        }

        /* Sleep in 1-second increments so SIGINT is responsive */
        for (int i = 0; i < SAMPLE_INTERVAL_S && !terminate; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

