#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip4"
#define GPIO_LINE_OFFSET 17
#define CONSUMER_LABEL   "ttp223_tamper"
#define POLL_INTERVAL_MS 100
#define INTRUSION_THRESHOLD_S 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static long long monotonic_ms(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    return (long long)ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line, CONSUMER_LABEL) != 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring TTP223B touch sensor on GPIO %d (BCM). Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);
    fflush(stdout);

    long long touch_start_ms = 0;
    int alert_printed = 0;

    while (g_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Failed to read line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
            goto cleanup;
        }

        long long now_ms = monotonic_ms();
        if (now_ms < 0) {
            goto cleanup;
        }

        if (val == 1) {
            if (touch_start_ms == 0) {
                touch_start_ms = now_ms;
                alert_printed = 0;
            } else if (!alert_printed && (now_ms - touch_start_ms) >= (INTRUSION_THRESHOLD_S * 1000LL)) {
                printf("Intrusion detected! TTP223B touched for more than %d seconds.\n", INTRUSION_THRESHOLD_S);
                fflush(stdout);
                alert_printed = 1;
            }
        } else {
            touch_start_ms = 0;
            alert_printed = 0;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

