/*
 * INMP441 I2S MEMS Microphone Sampler for Raspberry Pi 4 Model B
 *
 * Uses the Linux ALSA subsystem to capture 16-bit PCM audio from the
 * INMP441 over the I2S bus, and writes the raw samples to a file.
 *
 * Wiring:
 *   INMP441 SCK  -> GPIO 18 (BCM)  [I2S BCLK]
 *   INMP441 WS   -> GPIO 17 (BCM)  [I2S LRCLK / channel select]
 *   INMP441 SD   -> GPIO 19 (BCM)  [I2S DATA]
 *   INMP441 VDD  -> 3.3 V
 *   INMP441 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o audio_capture audio_capture.c -lpigpio -lrt
 * Run:    sudo ./audio_capture
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/soundcard.h>

#include <pigpio.h>

#define I2S_DEVICE        "/dev/snd/pcmC0D0c"
#define OUTPUT_FILE       "audio_capture.pcm"
#define SAMPLE_RATE       16000
#define CHANNELS          1
#define BITS_PER_SAMPLE   16
#define FRAMES_PER_BUFFER 1024
#define GPIO_LRCLK        17

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int init_i2s(void)
{
    int fd = open(I2S_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2S_DEVICE, strerror(errno));
        return -1;
    }

    int format = AFMT_S16_LE;
    if (ioctl(fd, SNDCTL_DSP_SETFMT, &format) < 0) {
        fprintf(stderr, "Error setting audio format: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (format != AFMT_S16_LE) {
        fprintf(stderr, "Error: 16-bit little-endian format not supported.\n");
        close(fd);
        return -1;
    }

    int channels = CHANNELS;
    if (ioctl(fd, SNDCTL_DSP_CHANNELS, &channels) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (channels != CHANNELS) {
        fprintf(stderr, "Error: requested %d channels, got %d.\n", CHANNELS, channels);
        close(fd);
        return -1;
    }

    int rate = SAMPLE_RATE;
    if (ioctl(fd, SNDCTL_DSP_SPEED, &rate) < 0) {
        fprintf(stderr, "Error setting sample rate: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (rate != SAMPLE_RATE) {
        fprintf(stderr, "Warning: requested %d Hz, got %d Hz.\n", SAMPLE_RATE, rate);
    }

    return fd;
}

static int write_pcm_data(int fd, const char *data, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = write(fd, data + total, len - total);
        if (n < 0) {
            if (errno == EINTR) {
                if (!g_running) {
                    return -1;
                }
                continue;
            }
            fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LRCLK, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output.\n", GPIO_LRCLK);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LRCLK, 0);

    int i2s_fd = init_i2s();
    if (i2s_fd < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *out = fopen(OUTPUT_FILE, "wb");
    if (out == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", OUTPUT_FILE, strerror(errno));
        close(i2s_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    size_t frame_size = (size_t)CHANNELS * (BITS_PER_SAMPLE / 8);
    size_t buffer_size = FRAMES_PER_BUFFER * frame_size;
    char *buffer = malloc(buffer_size);
    if (buffer == NULL) {
        fprintf(stderr, "Error allocating %zu bytes: %s\n", buffer_size, strerror(errno));
        fclose(out);
        close(i2s_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Capturing audio from %s... Press Ctrl+C to stop.\n", I2S_DEVICE);

    while (g_running) {
        ssize_t bytes_read = read(i2s_fd, buffer, buffer_size);
        if (bytes_read < 0) {
            if (errno == EINTR) {
                if (!g_running) {
                    break;
                }
                continue;
            }
            fprintf(stderr, "Error reading from I2S device: %s\n", strerror(errno));
            break;
        }
        if (bytes_read == 0) {
            fprintf(stderr, "End of stream reached.\n");
            break;
        }

        if (write_pcm_data(fileno(out), buffer, (size_t)bytes_read) != 0) {
            break;
        }
    }

    free(buffer);
    fclose(out);
    close(i2s_fd);
    gpioTerminate();

    printf("\nAudio capture stopped.\n");
    return EXIT_SUCCESS;
}

