#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18
#define PWM_FREQUENCY 100
#define DEBOUNCE_DELAY_US 50000
#define POLL_DELAY_US 50000
#define SENSOR_TIMEOUT_S 5
#define LOG_FILE "flame_log.txt"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];
    if (t) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    } else {
        strncpy(timestamp, "UNKNOWN", sizeof(timestamp));
    }
    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set flame sensor pin mode.\n");
        return -1;
    }
    if (gpioSetMode(FAN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set fan pin mode.\n");
        return -1;
    }
    if (gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        return -1;
    }
    if (gpioPWM(FAN_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize PWM duty cycle.\n");
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    gpioPWM(FAN_PIN, 0);
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_INPUT);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        fclose(log_file);
        return EXIT_FAILURE;
    }

    log_event("System started");

    int last_flame_state = 0;
    time_t last_valid_reading = time(NULL);
    int sensor_absent = 0;

    while (program_running) {
        int sensor_value = gpioRead(FLAME_SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Error: failed to read flame sensor pin.\n");
            break;
        }
        last_valid_reading = time(NULL);
        sensor_absent = 0;

        if (sensor_value == 0 && last_flame_state == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);
            sensor_value = gpioRead(FLAME_SENSOR_PIN);
            if (sensor_value == 0) {
                if (gpioPWM(FAN_PIN, 255) != 0) {
                    fprintf(stderr, "Error: failed to start PWM.\n");
                    break;
                }
                log_event("Flame detected");
                last_flame_state = 1;
            }
        } else if (sensor_value == 1 && last_flame_state == 1) {
            gpioDelay(DEBOUNCE_DELAY_US);
            sensor_value = gpioRead(FLAME_SENSOR_PIN);
            if (sensor_value == 1) {
                if (gpioPWM(FAN_PIN, 0) != 0) {
                    fprintf(stderr, "Error: failed to stop PWM.\n");
                    break;
                }
                log_event("Flame ended");
                last_flame_state = 0;
            }
        }

        if (time(NULL) - last_valid_reading > SENSOR_TIMEOUT_S) {
            if (!sensor_absent) {
                fprintf(stderr, "Warning: no valid sensor reading for %d seconds. Sensor may be absent.\n", SENSOR_TIMEOUT_S);
                log_event("Warning: sensor timeout");
                sensor_absent = 1;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    log_event("System shutting down");
    cleanup_gpio();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    return EXIT_SUCCESS;
}

