#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define TRIGGER_PIN     23
#define READY_PIN       24
#define LOG_FILE        "radar_data.log"
#define FRAME_SIZE      32768
#define FRAME_PERIOD_US 100000

#define LOG_MAGIC       0x4144

typedef struct {
    uint32_t start_freq;
    uint32_t end_freq;
    uint16_t num_chirps;
    uint16_t num_samples;
} RadarConfig;

typedef struct {
    uint64_t timestamp;
    uint32_t frame_number;
    uint8_t  data[FRAME_SIZE];
} RadarFrame;

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return -1;
    }

    return fd;
}

static int gpio_init(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(TRIGGER_PIN) failed\n");
        return -1;
    }
    if (gpioSetMode(READY_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(READY_PIN) failed\n");
        return -1;
    }
    if (gpioSetPullUpDown(READY_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(READY_PIN) failed\n");
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(TRIGGER_PIN, 0) failed\n");
        return -1;
    }

    return 0;
}

static int log_init(void) {
    g_log_fp = fopen(LOG_FILE, "wb");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    uint32_t magic = LOG_MAGIC;
    if (fwrite(&magic, sizeof(magic), 1, g_log_fp) != 1) {
        perror("fwrite(magic)");
        fclose(g_log_fp);
        g_log_fp = NULL;
        return -1;
