/*
 * OPT3001 Ambient Light Sensor Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   OPT3001 SDA -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   OPT3001 SCL -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   OPT3001 VDD -> 3.3 V
 *   OPT3001 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o light_logger light_logger.c -lpigpio -lrt
 * Run:    sudo ./light_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- OPT3001 constants (from TI datasheet) ---- */
#define OPT3001_ADDR          0x44    /* default I2C address (ADDR pin tied to GND) */
#define REG_RESULT            0x00    /* Result register (read-only) */
#define REG_CONFIG            0x01    /* Configuration register (read/write) */
#define REG_MANUFACTURER_ID   0x7E    /* Manufacturer ID register (0x5449) */
#define REG_DEVICE_ID         0x7F    /* Device ID register (0x3001) */

#define EXPECTED_MFR_ID       0x5449
#define EXPECTED_DEV_ID       0x3001

/*
 * Configuration register value:
 *   Bits 15:12 RN[3:0] = 1100  -> Automatic full-scale range
 *   Bits 11:9  CTN[2:0] = 000  -> Continuous conversion mode
 *   Bit  8     M[1:0]   = 00   -> 100 ms conversion time
 *   Bit  7     FC       = 0    -> No fault count
 *   Bit  6     FL       = 0    -> No fault latch
 *   Bit  5     L        = 0    -> No latch
 *   Bit  4     POL      = 0    -> Active low polarity
 *   Bit  3     ME       = 0    -> No interrupt
 *   Bit  2     OVF      = 0    -> No overflow
 *   Bit  1     CR       = 0    -> No interrupt
 *   Bit  0     RN[0]    = 0    -> (part of RN field)
 *
 * Binary: 1100 0000 0000 0000
 * Hex:    0xC000
 */
#define CONFIG_CONTINUOUS     0xC000

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit big-endian value to an OPT3001 register.             */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int opt3001_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian value from an OPT3001 register.            */
/* Returns 0 on success and stores the value in *out; -1 on failure.  */
/* ------------------------------------------------------------------ */
static int opt3001_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data[2];

    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (reg select 0x%02X) failed\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice from reg 0x%02X failed\n", reg);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Verify the sensor is present by reading the manufacturer and       */
/* device ID registers. Returns 0 on success, -1 on failure.          */
/* ------------------------------------------------------------------ */
static int opt3001_verify(int handle)
{
    uint16_t mfr_id = 0, dev_id = 0;

    if (opt3001_read_reg(handle, REG_MANUFACTURER_ID, &mfr_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read manufacturer ID (sensor absent or bus error)\n");
        return -1;
    }
    if (mfr_id != EXPECTED_MFR_ID) {
        fprintf(stderr, "[ERROR] Unexpected manufacturer ID: 0x%04X (expected 0x%04X)\n",
                mfr_id, EXPECTED_MFR_ID);
        return -1;
    }

    if (opt3001_read_reg(handle, REG_DEVICE_ID, &dev_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read device ID\n");
        return -1;
    }
    if (dev_id != EXPECTED_DEV_ID) {
        fprintf(stderr, "[ERROR] Unexpected device ID: 0x%04X (expected 0x%04X)\n",
                dev_id, EXPECTED_DEV_ID);
        return -1;
    }

    printf("[INFO] OPT3001 verified: MFR=0x%04X, DEV=0x%04X\n", mfr_id, dev_id);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert the 16-bit result register to lux.                         */
/* Returns 0 on success and stores lux in *out; -1 on invalid data.   */
/* ------------------------------------------------------------------ */
static int opt3001_to_lux(uint16_t raw, float *out)
{
    /*
     * Result register format (16-bit):
     *   Bits 15:12  -> Exponent (4 bits)
     *   Bits 11:0   -> Mantissa (12 bits)
     *
     * Lux = mantissa * 0.01 * (2 ^ exponent)
     */
    uint32_t exponent = (raw >> 12) & 0x0F;
    uint32_t mantissa = raw & 0x0FFF;

    if (exponent > 15) {
        fprintf(stderr, "[ERROR] Invalid exponent 0x%X in raw 0x%04X\n", exponent, raw);
        return -1;
    }

    *out = (float)mantissa * 0.01f * (float)(1u << exponent);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped lux reading to the log file.                  */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int log_lux(FILE *fp, float lux)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "[ERROR] time() failed\n");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", ts, lux) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[WARN] fflush failed on log file\n");
        return -1;
    }

    return 0;
}

