    if (opt3001_verify(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] OPT3001 not detected or not responding.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure continuous conversion mode ---- */
    if (opt3001_write_reg(g_i2c_handle, REG_CONFIG, CONFIG_CONTINUOUS) != 0) {
        fprintf(stderr, "[FATAL] Failed to configure OPT3001.\n");
        cleanup();
        return EXIT_FAILURE;
