 *   Bit  8     M[1:0]   = 00   -> 100 ms conversion time
 *   Bit  7     FC       = 0    -> No fault count
 *   Bit  6     FL       = 0    -> No fault latch
 *   Bit  5     L        = 0    -> No latch
 *   Bit  4     POL      = 0    -> Active low polarity
 *   Bit  3     ME       = 0    -> No interrupt
 *   Bit  2     OVF      = 0    -> No overflow
 *   Bit  1     CR       = 0    -> No interrupt
 *   Bit  0     RN[0]    = 0    -> (part of RN field)
