    if (mfr_id != EXPECTED_MFR_ID) {
        fprintf(stderr, "[ERROR] Unexpected manufacturer ID: 0x%04X (expected 0x%04X)\n",
                mfr_id, EXPECTED_MFR_ID);
        return -1;
    }

    if (opt3001_read_reg(handle, REG_DEVICE_ID, &dev_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read device ID\n");
        return -1;
    }
    if (dev_id != EXPECTED_DEV_ID) {
        fprintf(stderr, "[ERROR] Unexpected device ID: 0x%04X (expected 0x%04X)\n",
                dev_id, EXPECTED_DEV_ID);
        return -1;
    }

    printf("[INFO] OPT3001 verified: MFR=0x%04X, DEV=0x%04X\n", mfr_id, dev_id);
    return 0;
}

