/*
 * SainSmart IR Flame Detection Sensor Module reader (GPIO DOUT line)
 * Board: Raspberry Pi 3 Model B+
 * Wiring: VCC -> 3.3 V, GND -> GND, DOUT -> GPIO17 (BCM 17)
 * Sensor DOUT is active-low: 0 = flame detected, 1 = no flame.
 *
 * Build: gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define FLAME_GPIO_LINE	17		/* BCM pin number */
#define POLL_INTERVAL_S	1		/* seconds between readings */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl+C)                      */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read the flame sensor and print a timestamped status line.         */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int read_and_log_flame(struct gpiod_line *line)
{
    int value;
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line %d: %s\n",
                FLAME_GPIO_LINE, strerror(errno));
        return -1;
    }

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    /* DOUT is active-low: 0 => flame detected, 1 => no flame */
    if (value == 0) {
        printf("%s Flame Detected: YES\n", timestamp);
    } else {
        printf("%s Flame Detected: NO\n", timestamp);
    }
    fflush(stdout);

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct gpiod_line_request *request = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for graceful shutdown */
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the gpiochip that exposes BCM GPIO lines on the Pi */
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error opening /dev/gpiochip0: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the line object for BCM pin 17 */
    line = gpiod_chip_get_line(chip, FLAME_GPIO_LINE);
    if (line == NULL) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n",
                FLAME_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    /* Configure the line as input with internal pull-up */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "Error allocating line settings: %s\n",
                strerror(errno));
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_UP);

    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "Error allocating line config: %s\n",
                strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_config_add_line_settings(line_cfg, &FLAME_GPIO_LINE, 1,
                                             settings) != 0) {
        fprintf(stderr, "Error configuring line %d: %s\n",
                FLAME_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    /* Request the line from the kernel */
    request = gpiod_chip_request_lines(chip, NULL, line_cfg);
    if (request == NULL) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n",
                FLAME_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    /* Main polling loop */
    while (g_running) {
        if (read_and_log_flame(line) != 0) {
            fprintf(stderr, "Error reading flame sensor; continuing.\n");
        }
        sleep(POLL_INTERVAL_S);
    }

    printf("\nShutting down gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release resources in reverse order of acquisition */
    if (request != NULL)
        gpiod_line_request_release(request);
    if (line_cfg != NULL)
        gpiod_line_config_free(line_cfg);
    if (settings != NULL)
        gpiod_line_settings_free(settings);
    if (line != NULL)
        gpiod_line_release(line);
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

