    /* Configure the line as input with internal pull-up */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "Error allocating line settings: %s\n",
                strerror(errno));
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_UP);

    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "Error allocating line config: %s\n",
                strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_config_add_line_settings(line_cfg, &FLAME_GPIO_LINE, 1,
                                             settings) != 0) {
        fprintf(stderr, "Error configuring line %d: %s\n",
                FLAME_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    /* Request the line from the kernel */
    request = gpiod_chip_request_lines(chip, NULL, line_cfg);
    if (request == NULL) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n",
                FLAME_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    /* Main polling loop */
    while (g_running) {
        if (read_and_log_flame(line) != 0) {
            fprintf(stderr, "Error reading flame sensor; continuing.\n");
        }
        sleep(POLL_INTERVAL_S);
    }

    printf("\nShutting down gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release resources in reverse order of acquisition */
    if (request != NULL)
        gpiod_line_request_release(request);
    if (line_cfg != NULL)
        gpiod_line_config_free(line_cfg);
    if (settings != NULL)
        gpiod_line_settings_free(settings);
    if (line != NULL)
        gpiod_line_release(line);
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

