#include <pigpio.h>

#define NUM_CHANNELS 8
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

/* TTP226 OUT1..OUT8 -> BCM GPIO 2..9 */
static const int sensor_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_sensor_data(int *data)
{
    int rc = ttp226_read_data(data);
    if (rc != 0) {
        fprintf(stderr, "Error: ttp226_read_data failed (rc=%d)\n", rc);
        return -1;
    }
    return 0;
}

static void print_sensor_data(const int *data)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    long ms = (ts.tv_sec * 1000L) + (ts.tv_nsec / 1000000L);

    printf("[%ld ms] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
           ms,
           data[0], data[1], data[2], data[3],
           data[4], data[5], data[6], data[7]);
    fflush(stdout);
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs with pull-down resistors */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for BCM %d\n", sensor_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed for BCM %d\n", sensor_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Initialize TTP226 driver */
    if (ttp226_init() != 0) {
        fprintf(stderr, "Error: TTP226 initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int sensor_data[NUM_CHANNELS];

    while (g_running) {
        if (read_sensor_data(sensor_data) != 0) {
            break;
        }
        print_sensor_data(sensor_data);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown: ensure API is invoked at least once on exit */
    (void)ttp226_read_data(sensor_data);
    gpioTerminate();
    return EXIT_SUCCESS;
}

