/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring (BCM numbering):
 *   Sensor CH1 -> GPIO2  (physical pin 3)
 *   Sensor CH2 -> GPIO3  (physical pin 5)
 *   Sensor CH3 -> GPIO4  (physical pin 7)
 *   Sensor CH4 -> GPIO17 (physical pin 11)
 *   Sensor CH5 -> GPIO27 (physical pin 13)
 *   Sensor CH6 -> GPIO22 (physical pin 15)
 *   Sensor CH7 -> GPIO10 (physical pin 19)
 *   Sensor CH8 -> GPIO9  (physical pin 21)
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp226_reader ttp226_reader.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static const unsigned int sensor_pins[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buf[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", &timeinfo);
        printf("%s", buf);
    } else {
        printf("1970-01-01T00:00:00");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int i;
    int ret = EXIT_FAILURE;

    for (i = 0; i < NUM_CHANNELS; i++)
        lines[i] = NULL;

    /* Open the default gpiochip (gpiochip0 on Pi 4). */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire each line as an input with bias disabled. */
    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error getting GPIO line %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "ttp226-reader") < 0) {
            fprintf(stderr, "Error requesting GPIO line %u as input: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Install SIGINT handler for graceful shutdown. */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }

    printf("TTP226 8-channel touch sensor reader started. Press Ctrl-C to exit.\n");

    while (program_running) {
        int values[NUM_CHANNELS];
        int read_ok = 1;

        for (i = 0; i < NUM_CHANNELS; i++) {
            int v = gpiod_line_get_value(lines[i]);
            if (v < 0) {
                fprintf(stderr, "Error reading GPIO line %u: %s\n",
                        sensor_pins[i], strerror(errno));
                read_ok = 0;
                break;
            }
            values[i] = v;
        }

        if (!read_ok)
            continue;

        print_timestamp();
        printf(",%d,%d,%d,%d,%d,%d,%d,%d\n",
               values[0], values[1], values[2], values[3],
               values[4], values[5], values[6], values[7]);
        fflush(stdout);

        /* Sleep 50 ms using nanosleep for signal-aware delay. */
        struct timespec ts = {0, POLL_INTERVAL_MS * 1000000L};
        while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
            if (!program_running)
                break;
        }
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release each line individually. */
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL)
            gpiod_line_release(lines[i]);
    }

    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

