    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_si1145(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error: Failed to read PART_ID register.\n");
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Error: Invalid PART_ID (0x%02X). Expected 0x45.\n", part_id);
        return -1;
    }

    if (i2c_write_reg8(fd, SI1145_REG_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error: Failed to write HW_KEY.\n");
        return -1;
    }

    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE0, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write MEAS_RATE0.\n");
        return -1;
    }

    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write MEAS_RATE1.\n");
        return -1;
    }

    return 0;
}

static int read_uv_index(int fd, float *uv_index) {
    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, SI1145_CMD_UV_FORCE) < 0) {
        fprintf(stderr, "Error: Failed to trigger UV measurement.\n");
        return -1;
    }
    usleep(10000);

    uint16_t raw_uv;
    if (i2c_read_reg16(fd, SI1145_REG_UVINDEX_DATA0, &raw_uv) < 0) {
        fprintf(stderr, "Error: Failed to read UV index data.\n");
        return -1;
    }

    *uv_index = (float)raw_uv / 100.0f;
    return 0;
}

static int read_als_visible(int fd, uint16_t *als_visible) {
    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) {
        fprintf(stderr, "Error: Failed to trigger ALS measurement.\n");
        return -1;
    }
    usleep(10000);

    if (i2c_read_reg16(fd, SI1145_REG_ALS_VIS_DATA0, als_visible) < 0) {
        fprintf(stderr, "Error: Failed to read ALS visible data.\n");
        return -1;
    }
    return 0;
}

static void log_data(FILE *fp, float uv_index, uint16_t als_visible) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%u\n", timestamp, uv_index, als_visible);
    fflush(fp);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Failed to open /dev/i2c-1");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Error: Failed to acquire I2C bus access");
        close(i2c_fd);
        return 1;
    }

    if (init_si1145(i2c_fd) < 0) {
        fprintf(stderr, "Error: Si1145 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        perror("Error: Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
        fflush(log_file);
    }

    printf("Si1145 sensor initialized. Logging to uv_als_log.csv\n");

    while (running) {
        float uv_index;
        uint16_t als_visible;

        if (read_uv_index(i2c_fd, &uv_index) == 0 && read_als_visible(i2c_fd, &als_visible) == 0) {
            printf("UV Index: %.2f, ALS Visible: %u\n", uv_index, als_visible);
            log_data(log_file, uv_index, als_visible);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }

        sleep(1);
    }

    printf("\nExiting gracefully...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return 0;
}

