/*
 * Raspberry Pi 5 – Dual SLF3S-0600F Liquid Flow Sensor Monitor
 *
 * Reads flow rates from two Sensirion SLF3S-0600F sensors on I2C bus 1,
 * computes the average, logs it to flow_log.txt every second, and drives
 * an alarm on GPIO17 (BCM) when the average falls below 0.5 ml/min.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flow_monitor flow_monitor.c -lgpiod
 * Run:    sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <gpiod.h>

/* ----------------------------- Constants ------------------------------- */

#define I2C_BUS            "/dev/i2c-1"
#define SENSOR1_ADDR       0x40
#define SENSOR2_ADDR       0x41
#define ALARM_GPIO_LINE    17          /* BCM 17 */
#define ALARM_CONSUMER     "flow_alarm"
#define FLOW_THRESHOLD     0.5f        /* ml/min */
#define LOG_FILE           "flow_log.txt"
#define SAMPLE_PERIOD_S    1           /* seconds between samples */
#define STARTUP_DELAY_MS   100         /* ms to wait after start command */

/* SLF3S-0600F commands (16-bit, big-endian on the bus) */
#define CMD_START_CONTINUOUS  0x3608
#define CMD_READ_FLOW         0x0000     /* read the 16-bit flow register */

/* Sensirion CRC-8: polynomial 0x31, init 0xFF */
#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

/* --------------------------- Global state ------------------------------ */

static volatile sig_atomic_t g_running = 1;

static int               g_i2c_fd   = -1;
static FILE             *g_log_fp   = NULL;
static struct gpiod_chip *g_chip     = NULL;
static struct gpiod_line *g_alarm    = NULL;

/* ------------------------- Signal handling ----------------------------- */

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* --------------------------- I2C helpers -------------------------------- */

static int i2c_write_cmd(int fd, uint8_t addr, uint16_t cmd)
{
    uint8_t buf[3];
    buf[0] = (uint8_t)(cmd >> 8);
    buf[1] = (uint8_t)(cmd & 0xFF);

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        return -1;
    }
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "write(0x%02X, cmd 0x%04X): %s\n",
                addr, cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t addr, uint16_t reg,
                          uint16_t *out)
{
    uint8_t cmd[2];
    cmd[0] = (uint8_t)(reg >> 8);
    cmd[1] = (uint8_t)(reg & 0xFF);

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        return -1;
    }
    if (write(fd, cmd, 2) != 2) {
        fprintf(stderr, "write(0x%02X, reg 0x%04X): %s\n",
                addr, reg, strerror(errno));
        return -1;
    }

    /* Small delay so the sensor can clock out the response */
    usleep(2000);

    uint8_t data[2];
    ssize_t n = read(fd, data, 2);
    if (n != 2) {
        fprintf(stderr, "read(0x%02X, reg 0x%04X): got %zd bytes (%s)\n",
                addr, reg, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* --------------------------- CRC-8 (Sensirion) -------------------------- */

static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* --------------------------- Sensor read -------------------------------- */

/*
 * Read a 16-bit flow value from an SLF3S-0600F.
 * Returns 0 on success and stores the flow in *flow_raw.
 * Returns -1 on I2C or CRC error.
 */
static int read_flow_raw(int fd, uint8_t addr, uint16_t *flow_raw)
{
    uint16_t raw;
    if (i2c_read_reg16(fd, addr, CMD_READ_FLOW, &raw) < 0)
        return -1;

    /* Sensirion 16-bit flow data: [MSB, LSB, CRC] */
    uint8_t bytes[3];
    bytes[0] = (uint8_t)(raw >> 8);
    bytes[1] = (uint8_t)(raw & 0xFF);
    bytes[2] = sensirion_crc8(bytes, 2);

    if (bytes[2] != (uint8_t)(raw & 0xFF)) {
        fprintf(stderr, "CRC mismatch on 0x%02X (calc=0x%02X got=0x%02X)\n",
                addr, bytes[2], (uint8_t)(raw & 0xFF));
        return -1;
    }

    *flow_raw = raw;
    return 0;
}

/*
 * Convert raw 16-bit flow to ml/min.
 * SLF3S-0600F: 1 LSB = 0.01 ml/min (signed 16-bit).
 */
static float raw_to_ml_min(uint16_t raw)
{
    int16_t signed_raw = (int16_t)raw;
    return (float)signed_raw * 0.01f;
}

/* --------------------------- Logging ------------------------------------ */

static void log_flow(float avg_flow)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_fp, "%s, Average Flow Rate: %.2f ml/min\n", ts, avg_flow);
    fflush(g_log_fp);
}

/* --------------------------- Cleanup ------------------------------------ */

static void cleanup(void)
{
    if (g_alarm) {
        gpiod_line_set_value(g_alarm, 0);
        gpiod_line_release(g_alarm);
        g_alarm = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* --------------------------- Main --------------------------------------- */

int main(void)
{
    /* --- I2C --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- GPIO (alarm) --- */
    g_chip = gpiod_chip_open_by_name("gpiochip4"); /* RP1 on Pi 5 */
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    g_alarm = gpiod_chip_get_line(g_chip, ALARM_GPIO_LINE);
    if (!g_alarm) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                ALARM_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(g_alarm, ALARM_CONSUMER, 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    if (install_signal_handlers() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Start continuous measurement on both sensors --- */
    if (i2c_write_cmd(g_i2c_fd, SENSOR1_ADDR, CMD_START_CONTINUOUS) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2c_write_cmd(g_i2c_fd, SENSOR2_ADDR, CMD_START_CONTINUOUS) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Wait for the first conversion to complete */
    usleep(STARTUP_DELAY_MS * 1000);

    printf("Monitoring flow rates. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        uint16_t raw1 = 0, raw2 = 0;
        int ok1 = 0, ok2 = 0;

        if (read_flow_raw(g_i2c_fd, SENSOR1_ADDR, &raw1) == 0) {
            ok1 = 1;
        } else {
            fprintf(stderr, "Sensor 1 read failed; skipping cycle.\n");
        }

        if (read_flow_raw(g_i2c_fd, SENSOR2_ADDR, &raw2) == 0) {
            ok2 = 1;
        } else {
            fprintf(stderr, "Sensor 2 read failed; skipping cycle.\n");
        }

        if (!ok1 && !ok2) {
            /* No valid readings this cycle – keep alarm off and log 0 */
            gpiod_line_set_value(g_alarm, 0);
            log_flow(0.0f);
        } else if (!ok1 || !ok2) {
            /* One sensor failed – log the valid reading */
            float flow = raw_to_ml_min(ok1 ? raw1 : raw2);
            int below = (flow < FLOW_THRESHOLD) ? 1 : 0;
            gpiod_line_set_value(g_alarm, below);
            log_flow(flow);
        } else {
            /* Both sensors OK */
            float f1 = raw_to_ml_min(raw1);
            float f2 = raw_to_ml_min(raw2);
            float avg = (f1 + f2) / 2.0f;
            int below = (avg < FLOW_THRESHOLD) ? 1 : 0;
            gpiod_line_set_value(g_alarm, below);
            log_flow(avg);
        }

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

