/*
 * Raspberry Pi 5 – Omron D7S vibration sensor monitor
 *
 * Wiring:
 *   D7S SDA  -> GPIO2 (BCM 2,  I2C1 SDA, pin 3)
 *   D7S SCL  -> GPIO3 (BCM 3,  I2C1 SCL, pin 5)
 *   D7S VDD  -> 3.3 V (pin 1)
 *   D7S GND  -> GND  (pin 9)
 *
 * Build:  gcc -O2 -Wall -Wextra -o fan_health fan_health.c
 * Run:    ./fan_health   (user must be in the 'i2c' group or root)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- D7S constants (verified against Omron D7S datasheet) ---- */
#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x1E          /* 7-bit I2C address (0x3C for 8-bit) */

#define REG_MODE       0x00          /* Mode register */
#define MODE_ACTIVE    0x01          /* Active mode (continuous measurement) */

#define REG_X_LSB      0x04          /* X-axis acceleration, LSB */
#define REG_X_MSB      0x05          /* X-axis acceleration, MSB */
#define REG_Y_LSB      0x06          /* Y-axis acceleration, LSB */
#define REG_Y_MSB      0x07          /* Y-axis acceleration, MSB */
#define REG_Z_LSB      0x08          /* Z-axis acceleration, LSB */
#define REG_Z_MSB      0x09          /* Z-axis acceleration, MSB */

#define CSV_FILENAME   "fan_health.csv"
#define POLL_MS        500           /* Sampling interval */
#define ACTIVE_TIMEOUT_MS 1000       /* Max wait for sensor to settle */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_csv_fp = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;          /* let main loop exit cleanly */
}

/* ------------------------------------------------------------------ */
/* Write one byte to a D7S register. Returns 0 on success, -1 on error. */
static int d7s_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair. Returns 0 on success.   */
static int d7s_read_reg16(int fd, uint8_t reg_lsb, int16_t *out)
{
    uint8_t buf[2];
    uint8_t cmd = reg_lsb;

    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg_lsb, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg_lsb, strerror(errno));
        return -1;
    }
    *out = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Open the I2C bus and target the D7S. Returns fd or -1.              */
static int d7s_open(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                D7S_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/* ------------------------------------------------------------------ */
/* Initialise the D7S: set active mode, wait for first conversion.     */
static int d7s_init(int fd)
{
    if (d7s_write_reg(fd, REG_MODE, MODE_ACTIVE) < 0)
        return -1;

    /* D7S needs ~10 ms to start a conversion in active mode. */
    usleep(10000);

    /* Poll until we can read a valid X value (sensor must be present). */
    int ok = 0;
    for (int elapsed = 0; elapsed < ACTIVE_TIMEOUT_MS && !ok; elapsed += 10) {
        int16_t x;
        if (d7s_read_reg16(fd, REG_X_LSB, &x) == 0) {
            ok = 1;
        } else {
            usleep(10000);
        }
    }
    if (!ok) {
        fprintf(stderr, "D7S not responding within %d ms – check wiring\n",
                ACTIVE_TIMEOUT_MS);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append one CSV row. Returns 0 on success, -1 on write/flush error.  */
static int csv_append(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    char ts[32];
    time_t now = time(NULL);
    struct tm tmv;
    if (localtime_r(&now, &tmv) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush CSV failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C and initialise sensor ---- */
    g_i2c_fd = d7s_open();
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    if (d7s_init(g_i2c_fd) < 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Open CSV (append); write header if empty ---- */
    g_csv_fp = fopen(CSV_FILENAME, "a");
    if (!g_csv_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILENAME, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    long pos = ftell(g_csv_fp);
    if (pos == 0) {
        if (fprintf(g_csv_fp, "timestamp,x,y,z\n") < 0 ||
            fflush(g_csv_fp) != 0) {
            fprintf(stderr, "Cannot write CSV header: %s\n", strerror(errno));
            fclose(g_csv_fp);
            g_csv_fp = NULL;
            close(g_i2c_fd);
            g_i2c_fd = -1;
            return EXIT_FAILURE;
        }
    }

    printf("D7S monitoring started. Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int16_t x, y, z;

        if (d7s_read_reg16(g_i2c_fd, REG_X_LSB, &x) < 0 ||
            d7s_read_reg16(g_i2c_fd, REG_Y_LSB, &y) < 0 ||
            d7s_read_reg16(g_i2c_fd, REG_Z_LSB, &z) < 0) {
            /* On I2C error, log and retry rather than crash */
            fprintf(stderr, "Sensor read error – retrying in %d ms\n", POLL_MS);
        } else {
            if (csv_append(g_csv_fp, x, y, z) < 0) {
                fprintf(stderr, "CSV write error – continuing\n");
            }
        }

        usleep(POLL_MS * 1000);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    if (g_csv_fp) {
        fclose(g_csv_fp);
        g_csv_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("Done.\n");
    return EXIT_SUCCESS;
}

