    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C and initialise sensor ---- */
    g_i2c_fd = d7s_open();
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    if (d7s_init(g_i2c_fd) < 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Open CSV (append); write header if empty ---- */
    g_csv_fp = fopen(CSV_FILENAME, "a");
    if (!g_csv_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILENAME, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    long pos = ftell(g_csv_fp);
    if (pos == 0) {
        if (fprintf(g_csv_fp, "timestamp,x,y,z\n") < 0 ||
            fflush(g_csv_fp) != 0) {
            fprintf(stderr, "Cannot write CSV header: %s\n", strerror(errno));
            fclose(g_csv_fp);
            g_csv_fp = NULL;
            close(g_i2c_fd);
            g_i2c_fd = -1;
            return EXIT_FAILURE;
        }
    }

    printf("D7S monitoring started. Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int16_t x, y, z;

        if (d7s_read_reg16(g_i2c_fd, REG_X_LSB, &x) < 0 ||
            d7s_read_reg16(g_i2c_fd, REG_Y_LSB, &y) < 0 ||
            d7s_read_reg16(g_i2c_fd, REG_Z_LSB, &z) < 0) {
            /* On I2C error, log and retry rather than crash */
            fprintf(stderr, "Sensor read error – retrying in %d ms\n", POLL_MS);
        } else {
            if (csv_append(g_csv_fp, x, y, z) < 0) {
                fprintf(stderr, "CSV write error – continuing\n");
            }
        }

        usleep(POLL_MS * 1000);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    if (g_csv_fp) {
        fclose(g_csv_fp);
        g_csv_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("Done.\n");
    return EXIT_SUCCESS;
}

