#include <unistd.h>
#include <pigpio.h>

/* TMAG5170 I2C address (A0 tied to GND) */
#define TMAG5170_ADDR 0x48

/* TMAG5170 register addresses */
#define TMAG5170_REG_DEVICE_CONFIG 0x00
#define TMAG5170_REG_SENSOR_CONFIG 0x01
#define TMAG5170_REG_X_MSB        0x02
#define TMAG5170_REG_X_LSB        0x03
#define TMAG5170_REG_Y_MSB        0x04
#define TMAG5170_REG_Y_LSB        0x05
#define TMAG5170_REG_Z_MSB        0x06
#define TMAG5170_REG_Z_LSB        0x07

/* Device config: continuous mode, 50 mT range, all axes enabled */
#define TMAG5170_DEV_CFG 0x00
/* Sensor config: continuous mode, 50 mT range, all axes enabled */
#define TMAG5170_SENS_CFG 0x00

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n", reg, val, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int init_sensor(void) {
    if (write_reg(TMAG5170_REG_DEVICE_CONFIG, TMAG5170_DEV_CFG) < 0) return -1;
    if (write_reg(TMAG5170_REG_SENSOR_CONFIG, TMAG5170_SENS_CFG) < 0) return -1;
    return 0;
}

static int read_magnetic_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_msb, x_lsb, y_msb, y_lsb, z_msb, z_lsb;

    if (read_reg(TMAG5170_REG_X_MSB, &x_msb) < 0) return -1;
    if (read_reg(TMAG5170_REG_X_LSB, &x_lsb) < 0) return -1;
    if (read_reg(TMAG5170_REG_Y_MSB, &y_msb) < 0) return -1;
    if (read_reg(TMAG5170_REG_Y_LSB, &y_lsb) < 0) return -1;
    if (read_reg(TMAG5170_REG_Z_MSB, &z_msb) < 0) return -1;
    if (read_reg(TMAG5170_REG_Z_LSB, &z_lsb) < 0) return -1;

    *x = (int16_t)((x_msb << 8) | x_lsb);
    *y = (int16_t)((y_msb << 8) | y_lsb);
    *z = (int16_t)((z_msb << 8) | z_lsb);
    return 0;
}

static void log_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file);
}

int main(void) {
    int16_t x, y, z;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x%02X: %d\n", TMAG5170_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed (sensor may be absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open magnetic_log.csv for appending\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
        fflush(log_file);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        if (read_magnetic_data(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Failed to read magnetic data\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

