#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <stdatomic.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_US 1000000  /* 1 second */

static atomic_int g_pulse_count = 0;
static FILE *g_log_file = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can clean up and exit.      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — fires on every edge of GPIO_PIN.            */
/* ------------------------------------------------------------------ */
static void pulse_counter(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    (void)tick;

    if (level == 1) {                 /* rising edge => one revolution */
        atomic_fetch_add(&g_pulse_count, 1);
    }
}

/* ------------------------------------------------------------------ */
/* Compute RPM from pulses counted in the last SAMPLE_INTERVAL_US.    */
/* ------------------------------------------------------------------ */
static double calculate_rpm(int pulses)
{
    return (double)pulses * 60.0 / (double)(SAMPLE_INTERVAL_US / 1000000);
}

/* ------------------------------------------------------------------ */
/* Log one RPM sample to both stdout and the log file.                 */
/* ------------------------------------------------------------------ */
static void log_rpm(double rpm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("%s %.2f\n", timestamp, rpm);
    fflush(stdout);

    if (g_log_file != NULL) {
        fprintf(g_log_file, "%s %.2f\n", timestamp, rpm);
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup — disable timer, unregister callback, close file, release   */
/* pigpio resources.                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    gpioSetTimerFuncEx(0, 0, NULL);   /* disable 1 Hz timer */
    gpioSetAlertFuncEx(GPIO_PIN, NULL); /* unregister alert  */

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- configure GPIO pin ---- */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d.\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- register alert callback ---- */
    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_counter) != 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx failed for GPIO %d.\n", GPIO_PIN);
        fclose(g_log_file);
        g_log_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: sigaction(SIGINT) failed");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: sigaction(SIGTERM) failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    /* ---- main sampling loop ---- */
    while (g_running) {
        int pulses = atomic_exchange(&g_pulse_count, 0);
        double rpm = calculate_rpm(pulses);
        log_rpm(rpm);

        /* sleep 1 s; pigpio's gpioDelay is a busy-wait, but acceptable here */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

