#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27
#define LOG_FILE "rotation_log.txt"

/* Quadrature state machine: each bit = pin level (A=bit0, B=bit1) */
#define STATE_MASK 0x03

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t event_cond = PTHREAD_COND_INITIALIZER;

/* Quadrature state: previous state of the two pins */
static volatile int last_state = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
    pthread_mutex_lock(&log_mutex);
    pthread_cond_signal(&event_cond);
    pthread_mutex_unlock(&log_mutex);
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — runs in pigpio's callback thread            */
/* ------------------------------------------------------------------ */
static void sensor_alert_cb(int gpio, int level, uint32_t tick)
{
    (void)tick;

    int a = (gpio == SENSOR_A_PIN) ? level : gpioRead(SENSOR_A_PIN);
    int b = (gpio == SENSOR_B_PIN) ? level : gpioRead(SENSOR_B_PIN);
    if (a < 0 || b < 0)
        return;                       /* pigpio read error — skip */

    int current = (a & 0x01) | ((b & 0x01) << 1);

    pthread_mutex_lock(&log_mutex);

    /* Quadrature direction inference: a state change of 2 steps
       (0->2 or 2->0) is CW, a change of 1 step (0->1 or 1->0) is CCW. */
    int delta = current - last_state;
    if (delta == 2 || delta == -2) {
        fprintf(log_file, "Clockwise\n");
    } else if (delta == 1 || delta == -1) {
        fprintf(log_file, "Counter-Clockwise\n");
    }
    fflush(log_file);
    last_state = current;

    pthread_mutex_unlock(&log_mutex);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    /* ---- initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        fclose(log_file);
        log_file = NULL;
        return EXIT_FAILURE;
    }

    /* ---- configure pins ---- */
    if (gpioSetMode(SENSOR_A_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(A) failed\n");
        goto cleanup_gpio;
    }
    if (gpioSetMode(SENSOR_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(B) failed\n");
        goto cleanup_gpio;
    }
    /* Enable internal pull-ups so the pins read HIGH when idle. */
    if (gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(A) failed\n");
        goto cleanup_gpio;
    }
    if (gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(B) failed\n");
        goto cleanup_gpio;
    }

    /* ---- read initial state ---- */
    int a0 = gpioRead(SENSOR_A_PIN);
    int b0 = gpioRead(SENSOR_B_PIN);
    if (a0 < 0 || b0 < 0) {
        fprintf(stderr, "gpioRead initial failed\n");
        goto cleanup_gpio;
    }
