/*
 * TTP223B touch sensor -> LED on Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   TTP223B SIG  -> GPIO23 (physical pin 16, BCM 23)
 *   TTP223B VCC  -> 3.3 V (physical pin 1)
 *   TTP223B GND  -> GND  (physical pin 9)
 *   LED anode    -> GPIO18 (physical pin 12, BCM 18) via ~330 ohm resistor
 *   LED cathode  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_led touch_led.c -lgpiod
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <time.h>
#include <unistd.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define TOUCH_SENSOR_PIN 23   /* BCM 23, physical pin 16 */
#define LED_PIN          18   /* BCM 18, physical pin 12 */
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void sleep_ms(unsigned int ms)
{
    struct timespec ts;
    ts.tv_sec  = ms / 1000;
    ts.tv_nsec = (long)(ms % 1000) * 1000000L;
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    if (install_signal_handlers() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Starting TTP223B touch sensor -> LED control");

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        syslog(LOG_ERR, "Failed to open %s: %s", GPIO_CHIP_NAME, strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (touch_line == NULL) {
        syslog(LOG_ERR, "Failed to get line %d: %s", TOUCH_SENSOR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        syslog(LOG_ERR, "Failed to get line %d: %s", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(touch_line, "touch_led_touch") < 0) {
        syslog(LOG_ERR, "Failed to request touch line as input: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "touch_led_led", 0) < 0) {
        syslog(LOG_ERR, "Failed to request LED line as output: %s", strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "GPIO initialized: touch=BCM%d, led=BCM%d", TOUCH_SENSOR_PIN, LED_PIN);

    bool led_on = false;

    while (g_running) {
        int val = gpiod_line_get_value(touch_line);
        if (val < 0) {
            syslog(LOG_ERR, "Failed to read touch sensor: %s", strerror(errno));
            sleep_ms(POLL_INTERVAL_MS);
            continue;
        }

        bool touched = (val == 1);

        if (touched && !led_on) {
            if (gpiod_line_set_value(led_line, 1) < 0) {
                syslog(LOG_ERR, "Failed to turn LED on: %s", strerror(errno));
            } else {
                led_on = true;
                syslog(LOG_INFO, "Touch detected -> LED ON");
            }
        } else if (!touched && led_on) {
            if (gpiod_line_set_value(led_line, 0) < 0) {
                syslog(LOG_ERR, "Failed to turn LED off: %s", strerror(errno));
            } else {
                led_on = false;
                syslog(LOG_INFO, "Touch released -> LED OFF");
            }
        }

        sleep_ms(POLL_INTERVAL_MS);
    }

    /* ------------------------------------------------------------------ */
    /* Graceful shutdown                                                   */
    /* ------------------------------------------------------------------ */
    syslog(LOG_INFO, "Shutting down");

    if (gpiod_line_set_value(led_line, 0) < 0) {
        syslog(LOG_ERR, "Failed to turn LED off during shutdown: %s", strerror(errno));
    }

    gpiod_line_release(touch_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    syslog(LOG_INFO, "Resources released");
    closelog();
    return EXIT_SUCCESS;
}

