/*
 * Raspberry Pi 3 Model B+ — TTP223B touch sensor toggles an LED.
 *
 * Wiring:
 *   TTP223B OUT  -> GPIO17 (physical pin 11)
 *   LED anode    -> GPIO18 (physical pin 12) via 330 Ω resistor
 *   LED cathode  -> GND
 *   TTP223B VCC  -> 3.3 V
 *   TTP223B GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_led touch_led.c -lgpiod
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define TOUCH_GPIO  17
#define LED_GPIO    18
#define DEBOUNCE_MS 50

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    while (nanosleep(&ts, &ts) != 0) {
        if (errno != EINTR) {
            perror("nanosleep");
            break;
        }
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        goto cleanup;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_GPIO);
    if (touch_line == NULL) {
        perror("gpiod_chip_get_line(touch)");
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (led_line == NULL) {
        perror("gpiod_chip_get_line(led)");
        goto cleanup;
    }

    /* Request LED as output, initial value LOW. */
    if (gpiod_line_request_output(led_line, "ttp223b-led", 0) != 0) {
        perror("gpiod_line_request_output(led)");
        goto cleanup;
    }

    /* Request touch line for rising-edge events. */
    if (gpiod_line_request_rising_edge_events(touch_line, "ttp223b-touch") != 0) {
        perror("gpiod_line_request_rising_edge_events(touch)");
        goto cleanup;
    }

    printf("Touch sensor ready. Touch GPIO%d to toggle LED on GPIO%d.\n",
           TOUCH_GPIO, LED_GPIO);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    bool led_state = false;

    while (g_running) {
        /* Block up to 1 s waiting for a rising edge. */
        int ev = gpiod_line_event_wait(touch_line, &(struct timespec){1, 0});
        if (ev < 0) {
            if (errno == EINTR)
                continue;
            perror("gpiod_line_event_wait");
            goto cleanup;
        }
        if (ev == 0)
            continue; /* timeout, loop and check g_running */

        /* Drain any queued events so a brief touch produces one toggle. */
        while (gpiod_line_event_wait(touch_line, &(struct timespec){0, 0}) > 0)
            ;

        led_state = !led_state;
        if (gpiod_line_set_value(led_line, led_state ? 1 : 0) != 0) {
            perror("gpiod_line_set_value(led)");
            goto cleanup;
        }

        printf("Touch detected — LED %s\n", led_state ? "ON" : "OFF");
        fflush(stdout);

        sleep_ms(DEBOUNCE_MS);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line != NULL)
        gpiod_line_release(led_line);
    if (touch_line != NULL)
        gpiod_line_release(touch_line);
    if (chip != NULL)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");
    return ret;
}

