#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN    27
#define LED_2_PIN    22

#define LOG_BUFFER_SIZE 100
#define POLL_DELAY_US   50000  /* 50 ms */

typedef struct {
    int      pin;
    time_t   timestamp;
    int      state;
} LogEntry;

static LogEntry log_buffer[LOG_BUFFER_SIZE];
static int      log_index   = 0;
static int      log_overflow = 0;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set SENSOR_1_PIN (GPIO%d) as input.\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set SENSOR_2_PIN (GPIO%d) as input.\n", SENSOR_2_PIN);
        return -1;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set LED_1_PIN (GPIO%d) as output.\n", LED_1_PIN);
        return -1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set LED_2_PIN (GPIO%d) as output.\n", LED_2_PIN);
        return -1;
    }

    /* Ensure LEDs are off at startup */
    if (gpioWrite(LED_1_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise LED_1_PIN (GPIO%d) low.\n", LED_1_PIN);
        return -1;
    }
    if (gpioWrite(LED_2_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise LED_2_PIN (GPIO%d) low.\n", LED_2_PIN);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Best-effort LED turn-off before terminating pigpio */
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioTerminate();
}

static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d.\n", pin);
        return -1;
    }
    return v;
}

static int write_led(int pin, int state)
{
    if (gpioWrite(pin, state) < 0) {
        fprintf(stderr, "Error: gpioWrite failed on pin %d (state %d).\n", pin, state);
        return -1;
    }
    return 0;
}

static void log_event(int pin, int state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Warning: time() failed; logging without timestamp.\n");
        now = 0;
    }

    log_buffer[log_index].pin       = pin;
    log_buffer[log_index].timestamp = now;
    log_buffer[log_index].state     = state;

    log_index++;
    if (log_index >= LOG_BUFFER_SIZE) {
        log_index = 0;
        log_overflow++;
    }
}

static void print_log_buffer(void)
{
    printf("\n--- Log Buffer Contents ---\n");
    printf("Overflow count: %d\n", log_overflow);

    int start = log_overflow > 0 ? log_index : 0;
    int count = log_overflow > 0 ? LOG_BUFFER_SIZE : log_index;

    for (int i = 0; i < count; i++) {
        int idx = (start + i) % LOG_BUFFER_SIZE;
        printf("Entry %3d: Pin=%d, Timestamp=%ld, State=%d\n",
               i, log_buffer[idx].pin, (long)log_buffer[idx].timestamp, log_buffer[idx].state);
    }
    printf("--- End of Log Buffer ---\n");
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            /* Sensor read failure: turn off LEDs for safety and continue */
            write_led(LED_1_PIN, 0);
            write_led(LED_2_PIN, 0);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        write_led(LED_1_PIN, s1);
        write_led(LED_2_PIN, s2);

        if (s1 == 1) {
            log_event(SENSOR_1_PIN, 1);
        }
        if (s2 == 1) {
            log_event(SENSOR_2_PIN, 1);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    print_log_buffer();
    cleanup_gpio();
    printf("Cleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

