#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53
#define LOG_FILE "biometric_log.txt"
#define READ_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_sensor_data(int handle, int *heart_rate, int *spo2) {
    char buf[2];

    if (i2cWriteByte(handle, 0x00) < 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    *heart_rate = (int)(unsigned char)buf[0];
    *spo2 = (int)(unsigned char)buf[1];
    return 0;
}

static void log_data(FILE *fp, int heart_rate, int spo2) {
    time_t t = time(NULL);
    struct tm tm_info;
    char timestamp[64];

    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return;
    }

    if (fprintf(fp, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
}

int main(void) {
    int heart_rate, spo2;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        fclose(g_log_file);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting data acquisition. Press Ctrl+C to stop.\n");

    while (g_running) {
        if (read_sensor_data(g_i2c_handle, &heart_rate, &spo2) == 0) {
            log_data(g_log_file, heart_rate, spo2);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        sleep(READ_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");

    if (g_log_file != NULL) {
        fclose(g_log_file);
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

