#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN    27

#define TILT_THRESHOLD_SEC 2
#define POLL_INTERVAL_US   100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write an ISO-8601 timestamped event line to the log file            */
/* ------------------------------------------------------------------ */
static void log_event(const char *event)
{
    if (g_log_file == NULL)
        return;

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s - %s\n", ts, event) < 0)
        fprintf(stderr, "fprintf to log failed\n");

    if (fflush(g_log_file) != 0)
        fprintf(stderr, "fflush failed\n");
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin; returns 0 or 1, or -1 on error                   */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead(%d) failed\n", pin);
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Set alarm pin; returns 0 on success, -1 on error                    */
/* ------------------------------------------------------------------ */
static int set_alarm(int state)
{
    if (gpioWrite(ALARM_PIN, state) < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", ALARM_PIN, state);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- configure pins ---- */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(SENSOR_1_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(SENSOR_2_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ALARM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(ALARM_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* internal pull-down so sensors read LOW when idle */
    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(SENSOR_1_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(SENSOR_2_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ensure alarm is off at start */
    if (set_alarm(0) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_file = fopen("bridge_integrity.log", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file: bridge_integrity.log\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("System started");

    /* ---- state machine ---- */
    int alarm_active = 0;
    int tilt1_active = 0;
    int tilt2_active = 0;
    uint32_t tilt1_start = 0;
    uint32_t tilt2_start = 0;

    while (g_running) {
        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            /* sensor read error — log and keep running */
            log_event("Sensor read error");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        uint32_t now = gpioTick();  /* microseconds since boot */

        /* ---- Sensor 1 ---- */
        if (s1 == 1) {
            if (!tilt1_active) {
                tilt1_active = 1;
                tilt1_start = now;
                log_event("Tilt detected on Sensor 1");
            } else if (!alarm_active &&
                       (now - tilt1_start) >= (TILT_THRESHOLD_SEC * 1000000)) {
                alarm_active = 1;
                if (set_alarm(1) == 0)
                    log_event("Alarm activated (Sensor 1 threshold exceeded)");
                else
                    log_event("Alarm activation failed");
            }
        } else {
            if (tilt1_active) {
                tilt1_active = 0;
                log_event("Tilt ended on Sensor 1");
            }
            if (alarm_active && !tilt2_active) {
                alarm_active = 0;
                if (set_alarm(0) == 0)
                    log_event("Alarm deactivated");
                else
                    log_event("Alarm deactivation failed");
            }
        }

        /* ---- Sensor 2 ---- */
        if (s2 == 1) {
            if (!tilt2_active) {
                tilt2_active = 1;
                tilt2_start = now;
                log_event("Tilt detected on Sensor 2");
            } else if (!alarm_active &&
                       (now - tilt2_start) >= (TILT_THRESHOLD_SEC * 1000000)) {
                alarm_active = 1;
                if (set_alarm(1) == 0)
                    log_event("Alarm activated (Sensor 2 threshold exceeded)");
                else
                    log_event("Alarm activation failed");
            }
        } else {
            if (tilt2_active) {
                tilt2_active = 0;
                log_event("Tilt ended on Sensor 2");
            }
            if (alarm_active && !tilt1_active) {
                alarm_active = 0;
                if (set_alarm(0) == 0)
                    log_event("Alarm deactivated");
                else
                    log_event("Alarm deactivation failed");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* ---- graceful shutdown ---- */
    log_event("System shutting down");
    set_alarm(0);
    cleanup();
    return EXIT_SUCCESS;
}

