        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("System started");

    /* ---- state machine ---- */
    int alarm_active = 0;
    int tilt1_active = 0;
    int tilt2_active = 0;
    uint32_t tilt1_start = 0;
    uint32_t tilt2_start = 0;

    while (g_running) {
        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            /* sensor read error — log and keep running */
            log_event("Sensor read error");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        uint32_t now = gpioTick();  /* microseconds since boot */

        /* ---- Sensor 1 ---- */
        if (s1 == 1) {
            if (!tilt1_active) {
                tilt1_active = 1;
                tilt1_start = now;
                log_event("Tilt detected on Sensor 1");
            } else if (!alarm_active &&
                       (now - tilt1_start) >= (TILT_THRESHOLD_SEC * 1000000)) {
                alarm_active = 1;
                if (set_alarm(1) == 0)
                    log_event("Alarm activated (Sensor 1 threshold exceeded)");
                else
                    log_event("Alarm activation failed");
            }
        } else {
            if (tilt1_active) {
                tilt1_active = 0;
                log_event("Tilt ended on Sensor 1");
            }
            if (alarm_active && !tilt2_active) {
                alarm_active = 0;
                if (set_alarm(0) == 0)
                    log_event("Alarm deactivated");
                else
                    log_event("Alarm deactivation failed");
            }
        }

        /* ---- Sensor 2 ---- */
        if (s2 == 1) {
            if (!tilt2_active) {
                tilt2_active = 1;
                tilt2_start = now;
                log_event("Tilt detected on Sensor 2");
            } else if (!alarm_active &&
                       (now - tilt2_start) >= (TILT_THRESHOLD_SEC * 1000000)) {
                alarm_active = 1;
                if (set_alarm(1) == 0)
                    log_event("Alarm activated (Sensor 2 threshold exceeded)");
                else
                    log_event("Alarm activation failed");
            }
        } else {
            if (tilt2_active) {
                tilt2_active = 0;
                log_event("Tilt ended on Sensor 2");
            }
            if (alarm_active && !tilt1_active) {
                alarm_active = 0;
                if (set_alarm(0) == 0)
                    log_event("Alarm deactivated");
                else
                    log_event("Alarm deactivation failed");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* ---- graceful shutdown ---- */
    log_event("System shutting down");
    set_alarm(0);
    cleanup();
    return EXIT_SUCCESS;
}

