#define REG_CTRL224        0xFF

/* CTRL1: bit 0 = power-down (0 = active, 1 = power-down) */
#define CTRL1_POWER_DOWN   0x01

/* ----------------------------- Globals ----------------------------------- */
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;
static volatile sig_atomic_t g_running = 1;

/* ----------------------------- Prototypes -------------------------------- */
static int  init_sensor(void);
static int  read_sensor_data(float *x, float *y, float *z);
static float calculate_magnitude(float x, float y, float z);
static void trigger_alert(void);
static void log_event(float magnitude);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- Implementation ----------------------------- */

/*
 * Initialise the D7S-A0011.
 *   1. Verify the sensor is present by reading CTRL1.
 *   2. Clear the power-down bit so the sensor is active.
 */
static int init_sensor(void)
{
    int rc;
    int ctrl1;

    /* Probe: read CTRL1 to confirm the device is responding */
    rc = i2cReadByteData(g_i2c_handle, REG_CTRL1);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] Sensor not responding on 0x%02X (rc=%d).\n",
                I2C_ADDR, rc);
        return -1;
    }
    ctrl1 = rc;

    /* Clear power-down bit so the sensor is active */
    rc = i2cWriteByteData(g_i2c_handle, REG_CTRL1, ctrl1 & ~CTRL1_POWER_DOWN);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] Failed to clear power-down bit (rc=%d).\n", rc);
        return -1;
    }

    /* Allow the sensor to settle after power-up */
    gpioDelay(10000); /* 10 ms */
    return 0;
}

/*
 * Read X/Y/Z vibration data from the D7S-A0011.
 * Returns 0 on success, -1 on failure.
 */
static int read_sensor_data(float *x, float *y, float *z)
{
    char buf[6];
    int  rc;
    int  attempt;

    for (attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cReadI2CBlockData(g_i2c_handle, 0x00, buf, 6);
        if (rc == 6) {
            /* D7S-A0011 outputs 16-bit big-endian two's-complement values */
            int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
            int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
            int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

            /* Convert to physical units (placeholder scaling) */
            *x = (float)raw_x / 100.0f;
            *y = (float)raw_y / 100.0f;
            *z = (float)raw_z / 100.0f;
            return 0;
        }

        fprintf(stderr, "[WARN] I2C block read failed (rc=%d), attempt %d/%d.\n",
                rc, attempt + 1, MAX_RETRIES);
        gpioDelay(10000); /* 10 ms back-off */
    }

    fprintf(stderr, "[ERROR] Failed to read sensor data after %d retries.\n",
            MAX_RETRIES);
    return -1;
}

/* Euclidean magnitude of the vibration vector */
static float calculate_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* Pulse the alert LED for 1 s */
static void trigger_alert(void)
{
    gpioWrite(ALERT_LED_PIN, 1);
    gpioDelay(ALERT_DURATION_US);
    gpioWrite(ALERT_LED_PIN, 0);
}

/* Log a threshold-exceeding event with an ISO-8601 timestamp */
static void log_event(float magnitude)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s, Magnitude: %.2f\n", timestamp, magnitude);
    fflush(g_log_file);
}

/* Release all resources */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /* Put sensor back into power-down mode */
        (void)i2cWriteByteData(g_i2c_handle, REG_CTRL1, CTRL1_POWER_DOWN);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* SIGINT / SIGTERM handler */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    float x, y, z, magnitude;

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (rc=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor init --- */
    if (init_sensor() != 0) {
        fprintf(stderr, "[FATAL] Sensor initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Alert LED --- */
    gpioSetMode(ALERT_LED_PIN, PI_OUTPUT);
    gpioWrite(ALERT_LED_PIN, 0);

    /* --- Log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open %s for appending.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic monitoring started.  Threshold=%.1f  Log=%s\n",
           VIBRATION_THRESHOLD, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        if (read_sensor_data(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);
            if (magnitude > VIBRATION_THRESHOLD) {
                printf("[ALERT] Magnitude %.2f exceeds threshold %.1f\n",
                       magnitude, VIBRATION_THRESHOLD);
                log_event(magnitude);
                trigger_alert();
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

