/*
 * obstacle_led.c — Raspberry Pi 5
 *
 * Reads four Keywish KY-032 IR obstacle-avoidance sensors (active-low)
 * on GPIO4, GPIO17, GPIO27, GPIO22 and drives an LED on GPIO18.
 * The LED is ON when any sensor reports an object.
 *
 * Build:  gcc -O2 -Wall -Wextra -o obstacle_led obstacle_led.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define NUM_SENSORS   4
#define LED_PIN       18
#define POLL_MS       50

static const unsigned int sensor_pins[NUM_SENSORS] = {4, 17, 27, 22};

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_lines[NUM_SENSORS];
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_SENSORS; i++)
        sensor_lines[i] = NULL;

    if (install_signal_handlers() != 0)
        goto cleanup;

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (sensor_lines[i] == NULL) {
            fprintf(stderr, "Failed to get sensor line %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(sensor_lines[i], "ky032-sensor") < 0) {
            fprintf(stderr, "Failed to request sensor line %u as input: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        fprintf(stderr, "Failed to get LED line %u: %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(led_line, "ky032-led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line %u as output: %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Obstacle detection running. Press Ctrl+C to exit.\n");

    while (g_running) {
        bool object_detected = false;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(sensor_lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading sensor line %u: %s\n",
                        sensor_pins[i], strerror(errno));
                goto cleanup;
            }
            /* KY-032 is active-low: 0 => object detected */
            if (val == 0) {
                object_detected = true;
                break;
            }
        }

        if (gpiod_line_set_value(led_line, object_detected ? 1 : 0) < 0) {
            fprintf(stderr, "Error writing LED line %u: %s\n",
                    LED_PIN, strerror(errno));
            goto cleanup;
        }

        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line != NULL)
        gpiod_line_release(led_line);
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (sensor_lines[i] != NULL)
            gpiod_line_release(sensor_lines[i]);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");
    return ret;
}

