/*
 * flame_monitor.c — Raspberry Pi 3 Model B+ flame sensor monitor
 *
 * Five Keyes KY-026 flame sensors (digital OUT) on BCM GPIO 2, 3, 4, 17, 27.
 * Logs HIGH->LOW transitions to /var/log/flame_events.log with ISO-8601 UTC
 * timestamps and uses syslog for lifecycle events and per-sensor errors.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor   (needs write access to /var/log)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/file.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS      5
#define LOG_FILE         "/var/log/flame_events.log"
#define DEBOUNCE_DELAY_US 50000   /* 50 ms */
#define POLL_INTERVAL_US  1000000 /* 1 s  */
#define TIMESTAMP_LEN     32

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};

static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static int get_iso8601_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_info;

    if (time(&rawtime) == (time_t)-1)
        return -1;

    if (gmtime_r(&rawtime, &tm_info) == NULL)
        return -1;

    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_info) == 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *message)
{
    char ts[TIMESTAMP_LEN];
    if (get_iso8601_timestamp(ts, sizeof(ts)) == 0) {
        FILE *fp = fopen(LOG_FILE, "a");
        if (fp) {
            if (flock(fileno(fp), LOCK_EX) == 0) {
                if (fprintf(fp, "%s - %s\n", ts, message) < 0)
                    syslog(LOG_ERR, "fprintf to log failed: %s", strerror(errno));
                if (fflush(fp) != 0)
                    syslog(LOG_ERR, "fflush failed: %s", strerror(errno));
                flock(fileno(fp), LOCK_UN);
            } else {
                syslog(LOG_ERR, "flock failed: %s", strerror(errno));
            }
            fclose(fp);
        } else {
            syslog(LOG_ERR, "fopen(%s) failed: %s", LOG_FILE, strerror(errno));
        }
    } else {
        syslog(LOG_ERR, "Failed to generate timestamp: %s", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    int prev_state[NUM_SENSORS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = NULL;
        prev_state[i] = 1; /* assume HIGH (flame present) at startup */
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- open syslog ---- */
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Flame sensor monitoring started (GPIO 2,3,4,17,27)");

    /* ---- open gpiochip0 ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name failed: %s", strerror(errno));
        goto cleanup;
    }

    /* ---- acquire and request each line ---- */
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "gpiod_chip_get_line(%u) failed: %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(%u) failed: %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* ---- main polling loop ---- */
    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                syslog(LOG_ERR, "gpiod_line_get_value(%u) failed: %s",
                       sensor_pins[i], strerror(errno));
                continue;
            }

            /* Detect HIGH -> LOW transition (flame extinguished) */
            if (prev_state[i] == 1 && val == 0) {
                /* Debounce: re-read after 50 ms */
                usleep(DEBOUNCE_DELAY_US);
                int confirm = gpiod_line_get_value(lines[i]);
                if (confirm < 0) {
                    syslog(LOG_ERR, "debounce read(%u) failed: %s",
                           sensor_pins[i], strerror(errno));
                    continue;
                }
                if (confirm == 0) {
                    char msg[128];
                    snprintf(msg, sizeof(msg),
                             "Sensor ID: %d (GPIO %u) - Flame Detected",
                             i + 1, sensor_pins[i]);
                    log_event(msg);
                    syslog(LOG_INFO, "%s", msg);
                }
            }
            prev_state[i] = val;
        }
        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* ---- release lines ---- */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }

    /* ---- close chip ---- */
    if (chip)
        gpiod_chip_close(chip);

    /* ---- syslog ---- */
    syslog(LOG_INFO, "Flame sensor monitoring stopped");
    closelog();

    return ret;
}

