/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 3 Model B+.
 *
 * Wiring (TTP226 OUT0..OUT7 -> BCM GPIO):
 *   OUT0 -> GPIO5   OUT1 -> GPIO6   OUT2 -> GPIO13  OUT3 -> GPIO19
 *   OUT4 -> GPIO26  OUT5 -> GPIO12  OUT6 -> GPIO16  OUT7 -> GPIO20
 *
 * Build:  gcc -Wall -Wextra -O2 -o ttp226_reader ttp226_reader.c -lgpiod
 * Run:    ./ttp226_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 50000  /* 50 ms */

static const unsigned int touch_pins[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];

    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", &tm_info) > 0) {
        printf("[%s] ", buf);
    } else {
        printf("[unknown-time] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk bulk;
    struct gpiod_line *lines[NUM_CHANNELS];
    int prev_states[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Resolve each GPIO line and store pointers */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error: Failed to get GPIO line %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Request all eight lines as inputs in a single bulk request */
    gpiod_line_bulk_init(&bulk);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_bulk_add(&bulk, lines[i]);
    }

    if (gpiod_line_request_bulk_input(&bulk, "ttp226-touch") < 0) {
        fprintf(stderr, "Error: Failed to request GPIO lines as inputs: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Read initial states */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int val = gpiod_line_get_value(lines[i]);
        if (val < 0) {
            fprintf(stderr, "Error: Failed to read initial value from GPIO %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
        prev_states[i] = val;
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main polling loop */
    while (program_running) {
        int values[NUM_CHANNELS];
        int read_ok = 1;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error: Failed to read GPIO %u: %s\n",
                        touch_pins[i], strerror(errno));
                read_ok = 0;
                break;
            }
            values[i] = val;
        }

        if (!read_ok) {
            /* Brief pause before retrying to avoid log flooding */
            usleep(POLL_INTERVAL_US);
            continue;
        }

        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (values[i] != prev_states[i]) {
                print_timestamp();
                printf("Sensor %d (GPIO %u): %s\n",
                       i, touch_pins[i],
                       values[i] ? "Touched" : "Released");
                fflush(stdout);
                prev_states[i] = values[i];
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release the bulk request (lines are released automatically) */
    gpiod_line_release_bulk(&bulk);
    gpiod_chip_close(chip);
    return ret;
}

