#define VEML7700_CONFIG_DEFAULT 0x0000
#define VEML7700_CONFIG_SD 0x0001

#define ERR_NONE 0
#define ERR_I2C_OPEN 1
#define ERR_I2C_WRITE 2
#define ERR_I2C_READ 3
#define ERR_PWM_INIT 4
#define ERR_LOG_OPEN 5
#define ERR_LOG_WRITE 6

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int veml7700_init(int handle) {
    if (i2cWriteWordData(handle, VEML7700_REG_CONFIG, VEML7700_CONFIG_DEFAULT) < 0) {
        fprintf(stderr, "Error: Failed to write VEML7700 config register.\n");
        return -1;
    }
    return 0;
}

static int veml7700_read_lux(int handle, float *lux) {
    int raw = i2cReadWordData(handle, VEML7700_REG_ALS);
    if (raw < 0) {
        fprintf(stderr, "Error: Failed to read VEML7700 ALS register.\n");
        return -1;
    }
    *lux = (float)raw;
    return 0;
}

static int set_led_brightness(int gpio, int brightness) {
    if (gpioPWM(gpio, brightness) < 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle on GPIO %d.\n", gpio);
        return -1;
    }
    return 0;
}

static int log_data(FILE *fp, float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    if (fprintf(fp, "%s, Lux: %.2f, Brightness: %d, Error: %d\n", timestamp, lux, brightness, error_code) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: Failed to flush log file.\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: Failed to set up signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, VEML7700_ADDR);
        gpioTerminate();
        return 1;
    }

    if (veml7700_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VEML7700 initialization failed.\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", LED_GPIO);
        cleanup();
        return 1;
    }

    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d.\n", LED_GPIO);
        cleanup();
        return 1;
    }

    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO %d.\n", LED_GPIO);
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s.\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Adaptive grow light system started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux = 0.0f;
        int brightness = 0;
        int error_code = ERR_NONE;

        if (veml7700_read_lux(i2c_handle, &lux) < 0) {
            error_code = ERR_I2C_READ;
            lux = 0.0f;
        }

        if (error_code == ERR_NONE) {
            if (lux < 100.0f) {
                brightness = 100;
            } else if (lux < 500.0f) {
                brightness = 75;
            } else if (lux < 1000.0f) {
                brightness = 50;
            } else {
                brightness = 25;
            }
        }

        if (set_led_brightness(LED_GPIO, brightness) < 0) {
            error_code = ERR_PWM_INIT;
        }

        if (log_data(log_file, lux, brightness, error_code) < 0) {
            error_code = ERR_LOG_WRITE;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    set_led_brightness(LED_GPIO, 0);
    cleanup();
    return 0;
}

