#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define OPT3001_I2C_ADDR 0x44
#define REG_RESULT       0x00
#define REG_CONFIG       0x01
#define REG_MANUFACTURER 0x7E
#define REG_DEVICE_ID    0x7F

#define OPT3001_MANUFACTURER_ID 0x5449
#define OPT3001_DEVICE_ID      0x3001

#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "light_data.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_word(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c_write_word: write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "i2c_read_word: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "i2c_read_word: read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

static int opt3001_init(int fd)
{
    uint16_t manuf, dev_id;

    if (i2c_read_word(fd, REG_MANUFACTURER, &manuf) < 0)
        return -1;
    if (manuf != OPT3001_MANUFACTURER_ID) {
        fprintf(stderr, "OPT3001: manufacturer ID mismatch (0x%04X, expected 0x%04X)\n",
                manuf, OPT3001_MANUFACTURER_ID);
        return -1;
    }

    if (i2c_read_word(fd, REG_DEVICE_ID, &dev_id) < 0)
        return -1;
    if (dev_id != OPT3001_DEVICE_ID) {
        fprintf(stderr, "OPT3001: device ID mismatch (0x%04X, expected 0x%04X)\n",
                dev_id, OPT3001_DEVICE_ID);
        return -1;
    }

    /* Config: RN=1100 (auto-range), CT=100 (100 ms), M=1 (continuous), FC=00, OVF=0, CR=11 (512 ms) */
    uint16_t config = 0xC410;
    if (i2c_write_word(fd, REG_CONFIG, config) < 0)
        return -1;

    return 0;
}

static int opt3001_read_lux(int fd, float *lux_out)
{
    uint16_t raw;
    if (i2c_read_word(fd, REG_RESULT, &raw) < 0)
        return -1;

    /* OPT3001 result register: bits[15:12] = exponent, bits[11:0] = mantissa */
    uint32_t exponent = (raw >> 12) & 0x0F;
    uint32_t mantissa = raw & 0x0FFF;
    *lux_out = (float)mantissa * (0.01f * (float)(1 << exponent));
    return 0;
}

static void log_data(FILE *fp, float lux)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, lux);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, OPT3001_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                OPT3001_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    if (opt3001_init(g_i2c_fd) < 0) {
        fprintf(stderr, "OPT3001 initialization failed\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("OPT3001 light sensor logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float lux;
        if (opt3001_read_lux(g_i2c_fd, &lux) < 0) {
            fprintf(stderr, "Failed to read lux value; skipping iteration.\n");
        } else {
            log_data(g_log_fp, lux);
            printf("Lux: %.2f\n", lux);
        }
        sleep(1);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

