#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_PIN 4
#define ALERT_PIN 17
#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL_US 500000
#define ALERT_DURATION_US 1000000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n", FLAME_SENSOR_PIN, pigpio_error(value));
        return -1;
    }
    return value;
}

static int set_alert(int state) {
    int rc = gpioWrite(ALERT_PIN, state);
    if (rc < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed: %s\n", ALERT_PIN, state, pigpio_error(rc));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", ALERT_PIN);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (log_event("Program started") != 0) {
        fprintf(stderr, "Failed to log program start event\n");
        cleanup();
        return 1;
    }

    while (running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            if (log_event("Error reading flame sensor") != 0) {
                fprintf(stderr, "Failed to log sensor read error\n");
            }
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (sensor_value == 0) {
            if (log_event("Flame detected!") != 0) {
                fprintf(stderr, "Failed to log flame event\n");
            }
            if (set_alert(1) != 0) {
                fprintf(stderr, "Failed to set alert pin HIGH\n");
            }
            gpioDelay(ALERT_DURATION_US);
            if (set_alert(0) != 0) {
                fprintf(stderr, "Failed to set alert pin LOW\n");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    if (log_event("Program terminated") != 0) {
        fprintf(stderr, "Failed to log program termination event\n");
    }
    cleanup();
    return 0;
}

