#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS        "/dev/i2c-1"
#define SLF3S_ADDR     0x40
#define MEASURE_CMD    0x3608
#define FLOW_MIN       0.0f
#define FLOW_MAX       100.0f
#define LOG_FILE       "cooling_log.csv"
#define SAMPLE_US      1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
