#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdbool.h>
#include <gpiod.h>

#define LEFT_SENSOR_PIN   17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN  22
#define LOG_FILE          "path_log.csv"
#define SAMPLE_INTERVAL_US 50000  /* 50 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int get_iso8601_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL)
        return -1;

    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &timeinfo) == 0)
        return -1;

    return 0;
}

static int log_data(FILE *fp, const char *timestamp,
                    int left, int middle, int right)
{
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0)
        return -1;
    if (fflush(fp) != 0)
        return -1;
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    const unsigned int pins[3] = {LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN};
    const char *names[3] = {"left", "middle", "right"};
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "gpiod_chip_get_line failed for %s (pin %u): %s\n",
                    names[i], pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "ky033-obstacle") < 0) {
            fprintf(stderr, "gpiod_line_request_input failed for %s (pin %u): %s\n",
                    names[i], pins[i], strerror(errno));
            goto cleanup;
        }
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen");
        goto cleanup;
    }

    while (program_running) {
        int values[3];
        char timestamp[32];

        for (int i = 0; i < 3; i++) {
            int v = gpiod_line_get_value(lines[i]);
            if (v < 0) {
                fprintf(stderr, "gpiod_line_get_value failed for %s (pin %u): %s\n",
                        names[i], pins[i], strerror(errno));
                goto cleanup;
            }
            values[i] = v;
        }

        if (get_iso8601_timestamp(timestamp, sizeof(timestamp)) != 0) {
            fprintf(stderr, "Failed to generate timestamp\n");
            goto cleanup;
        }

        if (log_data(fp, timestamp, values[0], values[1], values[2]) != 0) {
            perror("log_data");
            goto cleanup;
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fflush(fp);
        fclose(fp);
    }
    for (int i = 0; i < 3; i++) {
        if (lines[i] != NULL)
            gpiod_line_release(lines[i]);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

