/*
 * touch_lamp.c — Raspberry Pi 5 touch-activated lamp simulator
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_lamp touch_lamp.c -lgpiod
 * Run:    ./touch_lamp
 *
 * Hardware:
 *   TTP223 capacitive touch sensor  -> GPIO23 (BCM 23, /dev/gpiochip4)
 *   LED + 330 Ω resistor            -> GPIO24 (BCM 24, /dev/gpiochip4)
 *
 * The TTP223 output is active-high; a rising edge on GPIO23 toggles
 * the LED and logs the event with an ISO-8601 timestamp.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip4"
#define TOUCH_PIN        23          /* BCM 23 — TTP223 OUT */
#define LED_PIN          24          /* BCM 24 — LED      */
#define LOG_FILE         "touch_log.txt"
#define POLL_TIMEOUT_MS  1000

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_event(FILE *log, int led_state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_local;
    if (localtime_r(&now, &tm_local) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", &tm_local) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(log, "%s Touch detected, LED state: %d\n", ts, led_state) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(log) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    FILE *log = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Open log file -------------------------------------------- */
    log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        fprintf(stderr, "Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* ---- Open GPIO chip ------------------------------------------- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    /* ---- Get lines ------------------------------------------------- */
    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (touch_line == NULL) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                TOUCH_PIN, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }

    /* ---- Request lines -------------------------------------------- */
    if (gpiod_line_request_rising_edge_events(touch_line, "touch_lamp") < 0) {
        fprintf(stderr, "gpiod_line_request_rising_edge_events(%d) failed: %s\n",
                TOUCH_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "touch_lamp", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output(%d) failed: %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Touch lamp running. Touch GPIO%d to toggle GPIO%d. Ctrl+C to exit.\n",
           TOUCH_PIN, LED_PIN);

    /* ---- Main loop ------------------------------------------------- */
    while (g_running) {
        int ev = gpiod_line_event_wait(touch_line,
                                       &(struct timespec){0, POLL_TIMEOUT_MS * 1000000L});
        if (ev < 0) {
            if (errno == EINTR) {
                continue;            /* signal interrupted — check g_running */
            }
            fprintf(stderr, "gpiod_line_event_wait() failed: %s\n",
                    strerror(errno));
            goto cleanup;
        }
        if (ev == 0) {
            continue;                /* timeout, no event */
        }

        /* Consume the event so the line is re-armed */
        struct gpiod_line_event event;
        if (gpiod_line_event_read(touch_line, &event) < 0) {
            fprintf(stderr, "gpiod_line_event_read() failed: %s\n",
                    strerror(errno));
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
            continue;
        }

        /* ---- Toggle LED ------------------------------------------- */
        int val = gpiod_line_get_value(led_line);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value(%d) failed: %s\n",
                    LED_PIN, strerror(errno));
            continue;
        }

        val = !val;
        if (gpiod_line_set_value(led_line, val) < 0) {
            fprintf(stderr, "gpiod_line_set_value(%d, %d) failed: %s\n",
                    LED_PIN, val, strerror(errno));
            continue;
        }

        log_event(log, val);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* ---- Release resources in reverse order ----------------------- */
    if (led_line != NULL) {
        gpiod_line_release(led_line);
    }
    if (touch_line != NULL) {
        gpiod_line_release(touch_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log != NULL) {
        if (fclose(log) != 0) {
            fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
        }
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting gracefully.\n");
    }
    return ret;
}

