/*
 * Flame detection safety system — Raspberry Pi 3 Model B+
 * Sensor : Keyes KY-026 flame sensor (digital output, active-low)
 * Wiring : DO  -> GPIO17 (BCM, physical pin 11)
 *          BUZ -> GPIO18 (BCM, physical pin 12)
 * Build  : gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define FLAME_SENSOR_PIN  17
#define BUZZER_PIN        18
#define LOG_FILE          "alert_log.txt"
#define POLL_INTERVAL_MS  500
#define BUZZER_DURATION_MS 2000
#define POLL_SLICE_MS     100
#define BUZZER_SLICE_MS   100

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_event(const char *message)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "[%s] %s\n", timestamp, message) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(g_log_fp) == EOF) {
        perror("fflush");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Buzzer control                                                      */
/* ------------------------------------------------------------------ */
static int buzzer_on(struct gpiod_line *buzzer)
{
    if (gpiod_line_set_value(buzzer, 1) < 0) {
        perror("gpiod_line_set_value(buzzer ON)");
        return -1;
    }
    return 0;
}

static int buzzer_off(struct gpiod_line *buzzer)
{
    if (gpiod_line_set_value(buzzer, 0) < 0) {
        perror("gpiod_line_set_value(buzzer OFF)");
        return -1;
    }
    return 0;
}

static int activate_buzzer(struct gpiod_line *buzzer, int duration_ms)
{
    int remaining = duration_ms;
    while (remaining > 0 && g_running) {
        int slice = (remaining > BUZZER_SLICE_MS) ? BUZZER_SLICE_MS : remaining;
        if (buzzer_on(buzzer) < 0)
            return -1;
        usleep(slice * 1000);
        if (buzzer_off(buzzer) < 0)
            return -1;
        remaining -= slice;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    int               ret = EXIT_FAILURE;

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    if (install_signal_handlers() < 0)
        goto cleanup;

    /* Open GPIO chip 0 (gpiochip0 on RPi 3 B+) */
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number(0)");
        goto cleanup;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        perror("gpiod_chip_get_line(flame)");
        goto cleanup;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("gpiod_chip_get_line(buzzer)");
        goto cleanup;
    }

    /* Request flame sensor line as input */
    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        perror("gpiod_line_request_input(flame)");
        goto cleanup;
    }

    /* Request buzzer line as output, initial value LOW */
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("gpiod_line_request_output(buzzer)");
        goto cleanup;
    }

    /* Ensure buzzer is off at startup */
    if (buzzer_off(buzzer_line) < 0)
        goto cleanup;

    /* Log system start */
    if (log_event("System started") < 0)
        goto cleanup;

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    int last_state = gpiod_line_get_value(flame_line);
    if (last_state < 0) {
        perror("gpiod_line_get_value(initial)");
        goto cleanup;
    }

    /* Main polling loop */
    while (g_running) {
        int current_state = gpiod_line_get_value(flame_line);
        if (current_state < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        /* Detect HIGH -> LOW transition (flame newly detected) */
        if (last_state == 1 && current_state == 0) {
            printf("Flame detected!\n");
            if (log_event("FLAME DETECTED") < 0)
                goto cleanup;
            if (activate_buzzer(buzzer_line, BUZZER_DURATION_MS) < 0)
                goto cleanup;
        }

        last_state = current_state;

        /* Sleep in 100 ms slices so signals are caught promptly */
        int remaining = POLL_INTERVAL_MS;
        while (remaining > 0 && g_running) {
            int slice = (remaining > POLL_SLICE_MS) ? POLL_SLICE_MS : remaining;
            usleep(slice * 1000);
            remaining -= slice;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Turn buzzer off and release lines */
    if (buzzer_line) {
        (void)buzzer_off(buzzer_line);
        gpiod_line_release(buzzer_line);
    }
    if (flame_line)
        gpiod_line_release(flame_line);
    if (chip)
        gpiod_chip_close(chip);

    if (g_log_fp) {
        if (log_event("System stopped") < 0)
            fprintf(stderr, "Failed to log shutdown event\n");
        if (fclose(g_log_fp) == EOF)
            perror("fclose");
        g_log_fp = NULL;
    }

    if (ret == EXIT_SUCCESS)
        printf("Flame detection system stopped.\n");

    return ret;
}

