/*
 * TMAG5110A1 Hall-Effect latch sensor monitor for Raspberry Pi 4 Model B.
 *
 * Three sensors are polled on the GPIO bus:
 *   Sensor 1 OUT -> GPIO4  (BCM)
 *   Sensor 2 OUT -> GPIO17 (BCM)
 *   Sensor 3 OUT -> GPIO27 (BCM)
 *
 * The TMAG5110A1 output is open-drain: the line is pulled low when a
 * south-pole magnet is present (magnet-present = logic low) and released
 * high when the magnet is removed (magnet-removed = logic high).
 *
 * Build:  gcc -O2 -Wall -Wextra -o magnet_monitor magnet_monitor.c -lpigpio -lrt
 * Run:    sudo ./magnet_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17
#define SENSOR_3_GPIO 27

#define NUM_SENSORS 3
#define LOG_FILE    "magnet_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

/* Sensor descriptor */
typedef struct {
    int gpio_pin;
    int sensor_id;
    int last_state;   /* 0 = magnet present (low), 1 = magnet removed (high) */
} sensor_t;

static sensor_t sensors[NUM_SENSORS] = {
    { SENSOR_1_GPIO, 1, -1 },
    { SENSOR_2_GPIO, 2, -1 },
    { SENSOR_3_GPIO, 3, -1 }
};

static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can clean up and exit.      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write an ISO-8601 timestamped entry to the log file.                */
/* ------------------------------------------------------------------ */
static void log_event(int sensor_id, int state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s - Sensor %d: Magnet %s\n",
                timestamp, sensor_id,
                (state == 0) ? "PRESENT" : "REMOVED");
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin; returns 0 or 1 on success, -1 on error.         */
/* ------------------------------------------------------------------ */
static int read_sensor(int gpio_pin)
{
    int level = gpioRead(gpio_pin);
    if (level < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n",
                gpio_pin, pigpio_error(level));
        return -1;
    }
    return level;
}

/* ------------------------------------------------------------------ */
/* Configure a GPIO pin as input with internal pull-up.               */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int initialize_sensor(int gpio_pin)
{
    if (gpioSetMode(gpio_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", gpio_pin);
        return -1;
    }
    if (gpioSetPullUpDown(gpio_pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up on GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — close log file and terminate pigpio.              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int i;

    /* --- Initialize pigpio library --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor GPIO pins --- */
    for (i = 0; i < NUM_SENSORS; i++) {
        if (initialize_sensor(sensors[i].gpio_pin) != 0) {
            fprintf(stderr, "Failed to initialize sensor %d (GPIO %d)\n",
                    sensors[i].sensor_id, sensors[i].gpio_pin);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* --- Open log file for appending --- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring TMAG5110A1 sensors on GPIO %d, %d, %d.\n",
           SENSOR_1_GPIO, SENSOR_2_GPIO, SENSOR_3_GPIO);
    printf("Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    /* --- Main polling loop --- */
    while (program_running) {
        for (i = 0; i < NUM_SENSORS; i++) {
            int state = read_sensor(sensors[i].gpio_pin);
            if (state < 0) {
                /* Read error — log to stderr and continue. */
                continue;
            }

            if (sensors[i].last_state == -1) {
                /* First read: record initial state without logging a
                   transition (avoids a false event at startup). */
                sensors[i].last_state = state;
            } else if (sensors[i].last_state != state) {
                log_event(sensors[i].sensor_id, state);
                sensors[i].last_state = state;
            }
        }
        usleep(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

