#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x60

#define REG_PART_ID 0x00
#define REG_HW_REV 0x01
#define REG_HR_DATA 0x25
#define REG_COMMAND 0x30

#define CMD_RESET 0x01
#define CMD_START 0x02

#define EXPECTED_PART_ID 0x82
#define EXPECTED_HW_REV 0x01

#define MOVING_AVG_SIZE 5
#define MIN_BPM 30
#define MAX_BPM 220

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static int heart_rate_history[MOVING_AVG_SIZE] = {0};
static int history_index = 0;
static int history_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int initialize_sensor(int handle) {
    uint8_t part_id, hw_rev;

    if (read_register(handle, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Sensor absent or bus error: cannot read PART_ID.\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X).\n", part_id, EXPECTED_PART_ID);
        return -1;
    }

    if (read_register(handle, REG_HW_REV, &hw_rev) != 0) {
        fprintf(stderr, "Sensor absent or bus error: cannot read HW_REV.\n");
        return -1;
    }
    if (hw_rev != EXPECTED_HW_REV) {
        fprintf(stderr, "Unexpected HW_REV: 0x%02X (expected 0x%02X).\n", hw_rev, EXPECTED_HW_REV);
        return -1;
    }

    if (write_register(handle, REG_COMMAND, CMD_RESET) != 0) {
        fprintf(stderr, "Failed to reset sensor.\n");
        return -1;
    }
    gpioDelay(10000);

    if (write_register(handle, REG_COMMAND, CMD_START) != 0) {
        fprintf(stderr, "Failed to start sensor.\n");
        return -1;
    }
    gpioDelay(10000);

    return 0;
}

static int read_heart_rate(int handle) {
    int result = i2cReadByteData(handle, REG_HR_DATA);
    if (result < 0) {
        fprintf(stderr, "Error reading heart rate data: %d\n", result);
        return -1;
    }
    return result;
}

static int moving_average(int new_value) {
    heart_rate_history[history_index] = new_value;
    history_index = (history_index + 1) % MOVING_AVG_SIZE;
    if (history_count < MOVING_AVG_SIZE) {
        history_count++;
    }

    int sum = 0;
    for (int i = 0; i < history_count; i++) {
        sum += heart_rate_history[i];
    }
    return sum / history_count;
}

static int validate_heart_rate(int heart_rate) {
    if (heart_rate < MIN_BPM || heart_rate > MAX_BPM) {
        fprintf(stderr, "Invalid heart rate: %d (out of range [%d, %d])\n", heart_rate, MIN_BPM, MAX_BPM);
        return -1;
    }
    return 0;
}

static int log_heart_rate(int heart_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time.\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%d\n", timestamp, heart_rate) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file.\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, SI1182_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        cleanup();
        return 1;
    }

    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    printf("Starting heart rate monitoring. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int heart_rate = read_heart_rate(i2c_handle);
        if (heart_rate >= 0) {
            int filtered_heart_rate = moving_average(heart_rate);
            if (validate_heart_rate(filtered_heart_rate) == 0) {
                if (log_heart_rate(filtered_heart_rate) != 0) {
                    fprintf(stderr, "Error logging heart rate.\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading heart rate, retrying...\n");
        }
        gpioDelay(1000000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

