}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_lines[NUM_CHANNELS];
    struct gpiod_line *counter_lines[NUM_CHANNELS];
    FILE *log_fp = NULL;
    int counter = 0;
    int prev_state[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    memset(touch_lines, 0, sizeof(touch_lines));
    memset(counter_lines, 0, sizeof(counter_lines));
    memset(prev_state, 0, sizeof(prev_state));

