#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdbool.h>
#include <gpiod.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22
#define LOG_FILE "tracking_log.csv"
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int write_header_if_new(FILE *fp) {
    long pos = ftell(fp);
    if (pos < 0) {
        perror("ftell");
        return -1;
    }
    if (pos == 0) {
        if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n") < 0) {
            perror("fprintf header");
            return -1;
        }
        if (fflush(fp) != 0) {
            perror("fflush header");
            return -1;
        }
    }
    return 0;
}

static int log_sensor_data(FILE *fp, int s1, int s2, int s3, int s4) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, s1, s2, s3, s4) < 0) {
        perror("fprintf data");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush data");
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[4] = {NULL, NULL, NULL, NULL};
    const unsigned int pins[4] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN, SENSOR4_PIN};
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %u: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "ky033-tracker") < 0) {
            fprintf(stderr, "gpiod_line_request_input failed for pin %u: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen");
        goto cleanup;
    }

    if (write_header_if_new(fp) < 0) {
        goto cleanup;
    }

    while (program_running) {
        int s1 = gpiod_line_get_value(lines[0]);
        int s2 = gpiod_line_get_value(lines[1]);
        int s3 = gpiod_line_get_value(lines[2]);
        int s4 = gpiod_line_get_value(lines[3]);

        if (s1 < 0 || s2 < 0 || s3 < 0 || s4 < 0) {
            fprintf(stderr, "Error reading sensor values: %s\n", strerror(errno));
        } else {
            if (log_sensor_data(fp, s1, s2, s3, s4) < 0) {
                fprintf(stderr, "Error logging sensor data\n");
            }
        }

        struct timespec ts = {0, POLL_INTERVAL_MS * 1000000L};
        nanosleep(&ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        if (fclose(fp) != 0) {
            perror("fclose");
        }
    }
    for (int i = 0; i < 4; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

