        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    pigpio_ready = 1;

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(SENSOR_1_PIN) failed\n");
        goto cleanup;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(SENSOR_2_PIN) failed\n");
        goto cleanup;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(LED_PIN) failed\n");
        goto cleanup;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(LED_PIN, 0) failed\n");
        goto cleanup;
    }

