        goto cleanup;
    }

    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "gpioRead failed (s1=%d s2=%d)\n", s1, s2);
            break;
        }

        /* TCRT5000 modules are active-low: 0 => obstacle detected */
        int obstacle_both = (s1 == 0 && s2 == 0) ? 1 : 0;

        if (led_state != obstacle_both) {
            if (gpioWrite(LED_PIN, obstacle_both) != 0) {
                fprintf(stderr, "gpioWrite(LED_PIN) failed\n");
                break;
            }
            led_state = obstacle_both;
        }

        if (log_data(g_log_fp, s1, s2, led_state) != 0) {
            break;
        }

        gpioDelay(POLL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (pigpio_ready) {
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    return ret;
}

