#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MIC_PIN 4
#define LED_PIN 17
#define SAMPLE_PERIOD_US 125
#define LED_ON_DURATION_US 100000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(MIC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set MIC_PIN %d as input.\n", MIC_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LED_PIN %d as output.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED_PIN %d to LOW.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

static void log_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char time_buf[32];
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);

    long milliseconds = ts.tv_nsec / 1000000L;
    printf("%s.%03ld\n", time_buf, milliseconds);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Sampling ICS-40180 on GPIO%d, LED on GPIO%d. Press Ctrl+C to exit.\n",
           MIC_PIN, LED_PIN);
    fflush(stdout);

    while (g_running) {
        int mic_value = gpioRead(MIC_PIN);
        if (mic_value < 0) {
            fprintf(stderr, "Error: gpioRead failed on MIC_PIN %d.\n", MIC_PIN);
            break;
        }

        if (mic_value == 1) {
            log_timestamp();

            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Error: failed to turn LED on.\n");
                break;
            }

            gpioDelay(LED_ON_DURATION_US);

            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to turn LED off.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup_gpio();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

