    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char time_buf[32];
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);

    long milliseconds = ts.tv_nsec / 1000000L;
    printf("%s.%03ld\n", time_buf, milliseconds);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Sampling ICS-40180 on GPIO%d, LED on GPIO%d. Press Ctrl+C to exit.\n",
           MIC_PIN, LED_PIN);
    fflush(stdout);

    while (g_running) {
        int mic_value = gpioRead(MIC_PIN);
        if (mic_value < 0) {
            fprintf(stderr, "Error: gpioRead failed on MIC_PIN %d.\n", MIC_PIN);
            break;
        }

        if (mic_value == 1) {
            log_timestamp();

            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Error: failed to turn LED on.\n");
                break;
            }

            gpioDelay(LED_ON_DURATION_US);

            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to turn LED off.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup_gpio();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

