#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define LEFT_SENSOR_PIN   17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN  22
#define POLL_INTERVAL_MS  100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left_line = NULL;
    struct gpiod_line *center_line = NULL;
    struct gpiod_line *right_line = NULL;
    int ret = EXIT_FAILURE;

    /* Register signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 4) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO lines for each sensor */
    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    if (left_line == NULL) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", LEFT_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    if (center_line == NULL) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", CENTER_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    if (right_line == NULL) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", RIGHT_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request each line as input with pull-up enabled (active-low sensors) */
    if (gpiod_line_request_input_flags(left_line, "ir_sensor_left", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", LEFT_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(center_line, "ir_sensor_center", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", CENTER_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(right_line, "ir_sensor_right", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", RIGHT_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    printf("IR Sensor Reading Program Started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (program_running) {
        int left_val = gpiod_line_get_value(left_line);
        int center_val = gpiod_line_get_value(center_line);
        int right_val = gpiod_line_get_value(right_line);

        if (left_val < 0 || center_val < 0 || right_val < 0) {
            fprintf(stderr, "Error reading sensor values: %s\n", strerror(errno));
            break;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left_val, center_val, right_val);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (left_line != NULL) {
        gpiod_line_release(left_line);
    }
    if (center_line != NULL) {
        gpiod_line_release(center_line);
    }
    if (right_line != NULL) {
        gpiod_line_release(right_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("Program terminated.\n");
    return ret;
}

