/*
 * Si1175 ALS reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   Si1175 SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   Si1175 SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   Si1175 VDD  -> 3.3 V (pin 1)
 *   Si1175 GND  -> GND  (pin 6)
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1175_als si1175_als.c -lpigpio -lrt
 * Run:    sudo ./si1175_als
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si1175 I2C constants ---- */
#define SI1175_I2C_BUS        1
#define SI1175_I2C_ADDR       0x60          /* 7-bit default address */

/* ---- Si1175 register addresses ---- */
#define SI1175_REG_PART_ID    0x00
#define SI1175_REG_ALS_DATA0  0x22          /* ALS LSB */
#define SI1175_REG_ALS_DATA1  0x23          /* ALS MSB */

/* ---- Expected PART_ID value ---- */
#define SI1175_PART_ID        0x75

/* ---- Sampling ---- */
#define SAMPLE_PERIOD_US      100000        /* 100 ms */
#define MAX_CONSECUTIVE_ERRORS 10

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;            /* let main loop exit cleanly            */
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a Si1175 register. Returns 0 on success,    */
/* -1 on I2C error, -2 if the sensor is absent (NACK).                 */
/* ------------------------------------------------------------------ */
static int si1175_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        if (rc == PI_I2C_READ_FAILED)   /* NACK / device not present   */
            return -2;
        return -1;                      /* genuine I2C bus error       */
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the 16-bit ALS sample (LSB first). Returns 0 on success,       */
/* -1 on I2C error, -2 if the sensor is absent.                        */
/* ------------------------------------------------------------------ */
static int si1175_read_als(int handle, uint16_t *als_out)
{
    uint8_t lsb = 0, msb = 0;

    if (si1175_read_reg(handle, SI1175_REG_ALS_DATA0, &lsb) != 0)
        return -1;
    if (si1175_read_reg(handle, SI1175_REG_ALS_DATA1, &msb) != 0)
        return -1;

    *als_out = ((uint16_t)msb << 8) | lsb;
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers for clean shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus to Si1175 ---- */
    g_i2c_handle = i2cOpen(SI1175_I2C_BUS, SI1175_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor presence via PART_ID ---- */
    uint8_t part_id = 0;
    if (si1175_read_reg(g_i2c_handle, SI1175_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error: Si1175 not responding at 0x%02X "
                        "(sensor absent or bus error).\n", SI1175_I2C_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (part_id != SI1175_PART_ID) {
        fprintf(stderr, "Error: Unexpected PART_ID 0x%02X (expected 0x%02X). "
                        "Wrong sensor or incorrect address?\n",
                        part_id, SI1175_PART_ID);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si1175 detected (PART_ID=0x%02X). Reading ALS every 100 ms...\n",
           part_id);

    /* ---- Main sampling loop ---- */
    int consecutive_errors = 0;

    while (g_running) {
        uint16_t als = 0;
        int rc = si1175_read_als(g_i2c_handle, &als);

        if (rc == 0) {
            printf("ALS: %u\n", als);
            consecutive_errors = 0;
        } else if (rc == -2) {
            fprintf(stderr, "Error: Si1175 disappeared from bus (NACK).\n");
            break;                       /* sensor went away — exit       */
        } else {
            fprintf(stderr, "Error: I2C read failure (rc=%d).\n", rc);
            if (++consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Error: %d consecutive I2C failures — aborting.\n",
                        consecutive_errors);
                break;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);     /* 100 ms (microseconds)         */
    }

    /* ---- Clean shutdown ---- */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

