/*
 * TTP226 8-channel capacitive touch sensor poller for Raspberry Pi 3 Model B+.
 *
 * Wiring (TTP226 breakout to Raspberry Pi 3 Model B+):
 *   TP1 -> GPIO5  (BCM 5)
 *   TP2 -> GPIO6  (BCM 6)
 *   TP3 -> GPIO13 (BCM 13)
 *   TP4 -> GPIO19 (BCM 19)
 *   TP5 -> GPIO26 (BCM 26)
 *   TP6 -> GPIO12 (BCM 12)
 *   TP7 -> GPIO16 (BCM 16)
 *   TP8 -> GPIO20 (BCM 20)
 *   VCC -> 3.3 V
 *   GND -> GND
 *
 * Compile:
 *   gcc -o touch_poll touch_poll.c -lrt
 *
 * Run:
 *   ./touch_poll
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200

static const unsigned int channel_pins[NUM_CHANNELS] = {
    5,  6,  13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int values[NUM_CHANNELS];
    struct timespec ts;
    double elapsed;
    int ret;
    int exit_code = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire each GPIO line as input */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, channel_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }

        ret = gpiod_line_request_input(lines[i], "ttp226-poll");
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Main polling loop */
    while (g_running) {
        /* Read all 8 channels */
        for (int i = 0; i < NUM_CHANNELS; i++) {
            ret = gpiod_line_get_value(lines[i]);
            if (ret < 0) {
                fprintf(stderr, "Failed to read GPIO line %u: %s\n",
                        channel_pins[i], strerror(errno));
                goto cleanup;
            }
            values[i] = ret;
        }

        /* Get monotonic timestamp */
        if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            goto cleanup;
        }
        elapsed = (double)ts.tv_sec + (double)ts.tv_nsec / 1.0e9;

        /* Print one line: [12.345s] CH1=0 CH2=1 ... CH8=0 */
        printf("[%6.3fs] ", elapsed);
        for (int i = 0; i < NUM_CHANNELS; i++) {
            printf("CH%d=%d", i + 1, values[i]);
            if (i < NUM_CHANNELS - 1)
                putchar(' ');
        }
        putchar('\n');
        fflush(stdout);

        /* Sleep 200 ms (interruptible by signals) */
        struct timespec sleep_ts = { 0, POLL_INTERVAL_MS * 1000000L };
        while (nanosleep(&sleep_ts, &sleep_ts) == -1 && errno == EINTR) {
            if (!g_running)
                break;
        }
    }

    exit_code = EXIT_SUCCESS;

cleanup:
    /* Release all acquired lines */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL)
            gpiod_line_release(lines[i]);
    }

    if (chip != NULL)
        gpiod_chip_close(chip);

    return exit_code;
}

