#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255
#define FADE_STEPS    50
#define FADE_DELAY_US (5000000 / FADE_STEPS)
#define HUE_CHANGE_MS 5000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set RED_PIN mode");
        return -1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GREEN_PIN mode");
        return -1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set BLUE_PIN mode");
        return -1;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set RED_PIN PWM frequency");
        return -1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set GREEN_PIN PWM frequency");
        return -1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set BLUE_PIN PWM frequency");
        return -1;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "Failed to set RED_PIN PWM range");
        return -1;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "Failed to set GREEN_PIN PWM range");
        return -1;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "Failed to set BLUE_PIN PWM range");
        return -1;
    }

    return 0;
}

static void set_led_color(int red, int green, int blue) {
    if (red   < 0) red   = 0; if (red   > 255) red   = 255;
    if (green < 0) green = 0; if (green > 255) green = 255;
    if (blue  < 0) blue  = 0; if (blue  > 255) blue  = 255;

    gpioPWM(RED_PIN,   red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN,  blue);
}

static void fade_to_color(int red, int green, int blue) {
    static int current_red   = 0;
    static int current_green = 0;
    static int current_blue  = 0;

    int red_diff   = red   - current_red;
    int green_diff = green - current_green;
    int blue_diff  = blue  - current_blue;

    for (int i = 1; i <= FADE_STEPS; i++) {
        current_red   += red_diff   / FADE_STEPS;
        current_green += green_diff / FADE_STEPS;
        current_blue  += blue_diff  / FADE_STEPS;

        if (i < FADE_STEPS) {
            int r = current_red, g = current_green, b = current_blue;
            if (red_diff   % FADE_STEPS > 0 && i == FADE_STEPS) r = red;
            if (green_diff % FADE_STEPS > 0 && i == FADE_STEPS) g = green;
            if (blue_diff  % FADE_STEPS > 0 && i == FADE_STEPS) b = blue;
            set_led_color(r, g, b);
        } else {
            set_led_color(red, green, blue);
        }
        usleep(FADE_DELAY_US);
    }

    current_red   = red;
    current_green = green;
    current_blue  = blue;
}

static void cleanup(void) {
    set_led_color(0, 0, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("rgb_fader", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGINT handler");
        closelog();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler");
        closelog();
        return 1;
    }

    if (init_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    unsigned char seed[4];
    FILE *fp = fopen("/dev/urandom", "rb");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open /dev/urandom, using time as seed");
        srand((unsigned int)time(NULL));
    } else {
        if (fread(seed, 1, sizeof(seed), fp) != sizeof(seed)) {
            syslog(LOG_ERR, "Failed to read from /dev/urandom, using time as seed");
            srand((unsigned int)time(NULL));
        } else {
            srand((unsigned int)((seed[0] << 24) | (seed[1] << 16) | (seed[2] << 8) | seed[3]));
        }
        fclose(fp);
    }

    syslog(LOG_INFO, "RGB LED fader started");

    while (g_running) {
        int red   = rand() % 256;
        int green = rand() % 256;
        int blue  = rand() % 256;

        fade_to_color(red, green, blue);

        for (int i = 0; i < HUE_CHANGE_MS / 100 && g_running; i++) {
            usleep(100000);
        }
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return 0;
}

