#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TCS34725_ADDR  0x29

#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE      0x00
#define TCS34725_ATIME       0x01
#define TCS34725_ID          0x12
#define TCS34725_CDATAL      0x14
#define TCS34725_RDATAL      0x16
#define TCS34725_GDATAL      0x18
#define TCS34725_BDATAL      0x1A

#define TCS34725_ENABLE_PON  0x01
#define TCS34725_ENABLE_AEN  0x02

#define LED_GPIO_LINE 17
#define RED_THRESHOLD 200
#define POLL_DELAY_MS 200

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { (uint8_t)(TCS34725_COMMAND_BIT | reg), value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n", reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    uint8_t cmd = (uint8_t)(TCS34725_COMMAND_BIT | reg);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 write(0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t cmd = (uint8_t)(TCS34725_COMMAND_BIT | reg);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16 write(0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16 read(0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id = 0;
    if (i2c_read_reg8(fd, TCS34725_ID, &id) < 0) {
        return -1;
    }
    if (id != 0x44 && id != 0x10) {
        fprintf(stderr, "Unexpected TCS34725 ID: 0x%02X (expected 0x44 or 0x10)\n", id);
        return -1;
    }

    if (i2c_write_reg8(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) {
        return -1;
    }
    usleep(3000);

    if (i2c_write_reg8(fd, TCS34725_ATIME, 0xDB) < 0) {
        return -1;
    }

    if (i2c_write_reg8(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        return -1;
    }
    usleep(3000);
    return 0;
}

static int tcs34725_read_calibrated(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    uint16_t raw_c, raw_r, raw_g, raw_b;
    if (i2c_read_reg16(fd, TCS34725_CDATAL, &raw_c) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_RDATAL, &raw_r) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_GDATAL, &raw_g) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_BDATAL, &raw_b) < 0) return -1;

    *c = raw_c;
    *r = raw_r;
    *g = raw_g;
    *b = raw_b;
    return 0;
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "tcs34725_led", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(fd);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("TCS34725 initialized. Reading color values...\n");

    while (g_running) {
        uint16_t r, g, b, c;
        if (tcs34725_read_calibrated(fd, &r, &g, &b, &c) < 0) {
            fprintf(stderr, "Read failed, re-initializing sensor...\n");
            if (tcs34725_init(fd) < 0) {
                fprintf(stderr, "Re-initialization failed, exiting.\n");
                break;
            }
            continue;
        }

        printf("R: %u, G: %u, B: %u, C: %u\n", r, g, b, c);

        int led_val = (r > RED_THRESHOLD) ? 1 : 0;
        if (gpiod_line_set_value(led_line, led_val) < 0) {
            perror("gpiod_line_set_value");
        }

        sleep_ms(POLL_DELAY_MS);
    }

    i2c_write_reg8(fd, TCS34725_ENABLE, 0x00);
    close(fd);
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

