code:
/*
 * Raspberry Pi 4 Model B – BH1750 ambient light sensor reading and
 * logarithmic brightness control of a WS2812B LED strip.
 *
 * Hardware:
 *   - BH1750 on I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL), address 0x23.
 *   - WS2812B data line on GPIO18 (BCM 18, PCM_CLK).
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_led light_led.c -lm
 *
 * Run:
 *   sudo ./light_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define BH1750_CMD_CONT 0x10   /* Continuous H-Resolution Mode */
#define BH1750_CONV_MS 180     /* Conversion time ~120 ms; 180 ms margin */

#define LED_COUNT      10
#define LED_PIN        18       /* BCM 18 = PCM_CLK */

#define PWM_PERIOD_US  1000     /* 1 µs resolution for WS2812B timing */
#define PWM_RANGE      255

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    /* BH1750 sends MSB first */
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out)
{
    if (i2c_write_cmd(fd, BH1750_CMD_CONT) < 0)
        return -1;

    usleep(BH1750_CONV_MS * 1000);

    uint16_t raw;
    if (i2c_read16(fd, &raw) < 0)
        return -1;

    *lux_out = (float)raw / 1.2f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* WS2812B via hardware PWM / wave                                     */
/* ------------------------------------------------------------------ */

static int pwm_init(int pin)
{
    int fd = open("/dev/pwmchip0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open /dev/pwmchip0: %s\n", strerror(errno));
        return -1;
    }

    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/export");
    FILE *f = fopen(path, "w");
    if (!f) {
        /* May already be exported */
        fprintf(stderr, "export: %s\n", strerror(errno));
    } else {
        fprintf(f, "0");
        fclose(f);
    }

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/period");
    f = fopen(path, "w");
    if (!f) { fprintf(stderr, "period: %s\n", strerror(errno)); return -1; }
    fprintf(f, "%d", 1000000); /* 1 ms period */
    fclose(f);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
    f = fopen(path, "w");
    if (!f) { fprintf(stderr, "duty_cycle: %s\n", strerror(errno)); return -1; }
    fprintf(f, "0");
    fclose(f);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/enable");
    f = fopen(path, "w");
    if (!f) { fprintf(stderr, "enable: %s\n", strerror(errno)); return -1; }
    fprintf(f, "1");
    fclose(f);

    return fd;
}

static void pwm_set_duty(int fd, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > 1000000) duty = 1000000;

    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
    FILE *f = fopen(path, "w");
    if (!f) {
        fprintf(stderr, "duty_cycle write: %s\n", strerror(errno));
        return;
    }
    fprintf(f, "%d", duty);
    fclose(f);
}

static void pwm_disable(int fd)
{
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/enable");
    FILE *f = fopen(path, "w");
    if (f) {
        fprintf(f, "0");
        fclose(f);
    }
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/unexport");
    f = fopen(path, "w");
    if (f) {
        fprintf(f, "0");
        fclose(f);
    }
    close(fd);
}

/* ------------------------------------------------------------------ */
/* WS2812B bit-bang via wave (hardware PWM)                            */
/* ------------------------------------------------------------------ */

static void ws2812_set_led(int pwm_fd, uint8_t r, uint8_t g, uint8_t b)
{
    /* WS2812B expects GRB order */
    uint32_t grb = ((uint32_t)g << 16) | ((uint32_t)r << 8) | b;

    for (int i = 23; i >= 0; i--) {
        int bit = (grb >> i) & 1;
        int duty = bit ? 700 : 350; /* ~70% / 35% of 1 ms period */
        pwm_set_duty(pwm_fd, duty);
        usleep(1);
    }
}

static void ws2812_update(int pwm_fd, const uint8_t *buf)
{
    for (int i = 0; i < LED_COUNT; i++) {
        uint8_t r = buf[i * 3 + 0];
        uint8_t g = buf[i * 3 + 1];
        uint8_t b = buf[i * 3 + 2];
        ws2812_set_led(pwm_fd, r, g, b);
    }
}

/* ------------------------------------------------------------------ */
/* Logarithmic mapping                                                 */
/* ------------------------------------------------------------------ */

static void map_lux_to_leds(float lux, uint8_t *buf)
{
    float log_lux = log10f(lux + 1.0f);
    float norm = log_lux / 5.0f; /* 5 log-units -> full brightness */
