/* Logarithmic mapping                                                 */
/* ------------------------------------------------------------------ */

static void map_lux_to_leds(float lux, uint8_t *buf)
{
    float log_lux = log10f(lux + 1.0f);
    float norm = log_lux / 5.0f; /* 5 log-units -> full brightness */
    if (norm < 0.0f) norm = 0.0f;
    if (norm > 1.0f) norm = 1.0f;

    uint8_t val = (uint8_t)(norm * 255.0f);
    for (int i = 0; i < LED_COUNT; i++) {
        buf[i * 3 + 0] = 0;          /* G */
        buf[i * 3 + 1] = val;        /* R */
        buf[i * 3 + 2] = 0;          /* B */
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    int pwm_fd = pwm_init(LED_PIN);
    if (pwm_fd < 0) {
        fprintf(stderr, "PWM init failed\n");
        close(i2c_fd);
        return 1;
    }

    uint8_t led_buf[LED_COUNT * 3];
    memset(led_buf, 0, sizeof(led_buf));

    while (g_running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error; retrying...\n");
            usleep(500000);
            continue;
        }

        map_lux_to_leds(lux, led_buf);
        ws2812_update(pwm_fd, led_buf);

        printf("Lux: %.2f  ->  ", lux);
        for (int i = 0; i < LED_COUNT; i++)
            printf("%02X ", led_buf[i * 3 + 1]);
        printf("\n");

        usleep(100000);
    }

    /* Graceful shutdown */
    pwm_set_duty(pwm_fd, 0);
    pwm_disable(pwm_fd);
    close(i2c_fd);

    printf("\nExiting cleanly.\n");
    return 0;
