/*
 * Raspberry Pi Zero W – BH1750 ambient light sensor controlling an
 * APA102 LED strip via I2C and SPI.
 *
 * Build:  gcc -O2 -Wall -Wextra -o light_led light_led.c
 *
 * Wiring:
 *   BH1750  SDA -> GPIO2 (pin 3), SCL -> GPIO3 (pin 5), VCC 3V3, GND
 *   APA102  SCLK -> GPIO11 (pin 23, SPI0 SCLK), MOSI -> GPIO10 (pin 19, SPI0 MOSI)
 *           VCC 5V, GND
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define SPI_BUS        "/dev/spidev0.0"
#define NUM_LEDS       10
#define SPI_SPEED_HZ   1000000
#define CONV_DELAY_MS  120

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_ms(unsigned ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

/* ---------- I2C helpers ---------- */

static int i2c_write(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n", byte, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read failed: expected 2 bytes, got %zd (%s)\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    /* BH1750 sends MSB first */
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Read ambient light in lux from the BH1750.
 * Returns 0 on success, -1 on error.
 */
static int bh1750_read(int fd, uint16_t *lux)
{
    /* One-Time High-Resolution Mode (0x20) */
    if (i2c_write(fd, 0x20) < 0)
        return -1;

    sleep_ms(CONV_DELAY_MS);

    return i2c_read16(fd, lux);
}

/* ---------- SPI helpers ---------- */

static int spi_xfer(int fd, const uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = 8;
    tr.delay_usecs   = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Build an APA102 frame and transmit it.
 *   start_frame: 4 bytes of 0x00
 *   led_frame:   4 bytes per LED (0xE0 | global, B, G, R)
 *   end_frame:   4 bytes of 0xFF
 */
static int apa102_update(int fd, uint8_t brightness, uint8_t r, uint8_t g, uint8_t b)
{
    size_t frame_len = 4 + (size_t)NUM_LEDS * 4 + 4;
    uint8_t *frame = malloc(frame_len);
    if (!frame) {
        fprintf(stderr, "malloc failed: %s\n", strerror(errno));
        return -1;
    }

    size_t idx = 0;
    memset(&frame[idx], 0x00, 4); idx += 4;                 /* start frame */
    for (int i = 0; i < NUM_LEDS; i++) {
        frame[idx++] = 0xE0 | (brightness & 0x1F);
        frame[idx++] = b;
        frame[idx++] = g;
        frame[idx++] = r;
    }
    memset(&frame[idx], 0xFF, 4); idx += 4;                 /* end frame */

    uint8_t *rx = calloc(1, frame_len);
    if (!rx) {
        fprintf(stderr, "calloc failed: %s\n", strerror(errno));
        free(frame);
        return -1;
    }

    int rc = spi_xfer(fd, frame, rx, frame_len);
    free(rx);
    free(frame);
    return rc;
}

static int apa102_off(int fd)
{
    return apa102_update(fd, 0, 0, 0, 0);
}

/* ---------- Main ---------- */

int main(void)
{
    int i2c_fd = -1, spi_fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- I2C --- */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                BH1750_ADDR, strerror(errno));
        goto cleanup;
    }

    /* --- SPI --- */
    spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", SPI_BUS, strerror(errno));
        goto cleanup;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Main loop --- */
    while (g_running) {
        uint16_t lux = 0;
        if (bh1750_read(i2c_fd, &lux) < 0) {
            fprintf(stderr, "BH1750 read error – continuing\n");
            sleep_ms(500);
            continue;
        }

        /* Scale lux to a 5-bit brightness (0–31) */
        uint8_t brightness = (uint8_t)(lux / 1000);
        if (brightness > 31)
            brightness = 31;

        /* Map brightness to RGB (white) */
        uint8_t r = brightness, g = brightness, b = brightness;

        if (apa102_update(spi_fd, brightness, r, g, b) < 0) {
            fprintf(stderr, "APA102 update failed – continuing\n");
        }

        printf("Lux: %5u  Brightness: %u\n", lux, brightness);
        sleep_ms(100);
    }

    /* --- Graceful shutdown --- */
    if (apa102_off(spi_fd) < 0)
        fprintf(stderr, "Warning: failed to turn off LEDs on exit\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (spi_fd >= 0)
        close(spi_fd);
    if (i2c_fd >= 0)
        close(i2c_fd);
    return rc;
}

