    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                BH1750_ADDR, strerror(errno));
        goto cleanup;
    }

    /* --- SPI --- */
    spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", SPI_BUS, strerror(errno));
        goto cleanup;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Main loop --- */
    while (g_running) {
        uint16_t lux = 0;
        if (bh1750_read(i2c_fd, &lux) < 0) {
            fprintf(stderr, "BH1750 read error – continuing\n");
            sleep_ms(500);
            continue;
        }

        /* Scale lux to a 5-bit brightness (0–31) */
        uint8_t brightness = (uint8_t)(lux / 1000);
        if (brightness > 31)
            brightness = 31;

        /* Map brightness to RGB (white) */
        uint8_t r = brightness, g = brightness, b = brightness;

        if (apa102_update(spi_fd, brightness, r, g, b) < 0) {
            fprintf(stderr, "APA102 update failed – continuing\n");
        }

        printf("Lux: %5u  Brightness: %u\n", lux, brightness);
        sleep_ms(100);
    }

    /* --- Graceful shutdown --- */
    if (apa102_off(spi_fd) < 0)
        fprintf(stderr, "Warning: failed to turn off LEDs on exit\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (spi_fd >= 0)
        close(spi_fd);
    if (i2c_fd >= 0)
        close(i2c_fd);
    return rc;
}

