#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR_LOW  0x23
#define BH1750_ADDR_HIGH 0x5C
#define BH1750_CONT_HRES 0x10
#define NUM_SENSORS 3
#define SPI_BAUD 1000000
#define SPI_FLAGS 0
#define NUM_LEDS 10
#define FADE_STEPS 50
#define FADE_DELAY_US 10000
#define LOOP_DELAY_US 100000
#define CONV_DELAY_US 180000

static volatile sig_atomic_t running = 1;
static int i2c_handles[NUM_SENSORS];
static int spi_handle = -1;
static uint8_t led_buffer[(NUM_LEDS + 1) * 4];

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int handle) {
    if (i2cWriteByte(handle, BH1750_CONT_HRES) < 0) return -1;
    gpioDelay(CONV_DELAY_US);
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    return (buf[0] << 8) | buf[1];
}

static void set_led_brightness(uint8_t brightness) {
    for (int i = 0; i < NUM_LEDS; i++) {
        led_buffer[i * 4 + 1] = brightness;
        led_buffer[i * 4 + 2] = brightness;
        led_buffer[i * 4 + 3] = brightness;
    }
    led_buffer[NUM_LEDS * 4] = 0xFF;
    led_buffer[NUM_LEDS * 4 + 1] = 0xFF;
    led_buffer[NUM_LEDS * 4 + 2] = 0xFF;
    led_buffer[NUM_LEDS * 4 + 3] = 0xFF;
    if (spiWrite(spi_handle, (char *)led_buffer, sizeof(led_buffer)) < 0) {
        fprintf(stderr, "SPI write failed: %s\n", strerror(errno));
    }
}

static void fade_leds(uint8_t target_brightness) {
    uint8_t current_brightness = led_buffer[1];
    int step = (target_brightness > current_brightness) ? 1 : -1;
    int diff = target_brightness - current_brightness;
    for (int i = 0; i < FADE_STEPS && running; i++) {
        current_brightness += step;
        if (step > 0 && current_brightness > target_brightness) current_brightness = target_brightness;
        if (step < 0 && current_brightness < target_brightness) current_brightness = target_brightness;
        set_led_brightness(current_brightness);
        gpioDelay(FADE_DELAY_US);
    }
    set_led_brightness(target_brightness);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) i2c_handles[i] = -1;

    i2c_handles[0] = i2cOpen(I2C_BUS, BH1750_ADDR_LOW, 0);
    if (i2c_handles[0] < 0) {
        fprintf(stderr, "Warning: Could not open BH1750 at 0x23: %s\n", strerror(errno));
    } else {
        fprintf(stderr, "BH1750 at 0x23 opened successfully.\n");
    }

    i2c_handles[1] = i2cOpen(I2C_BUS, BH1750_ADDR_HIGH, 0);
    if (i2c_handles[1] < 0) {
        fprintf(stderr, "Warning: Could not open BH1750 at 0x5C: %s\n", strerror(errno));
    } else {
        fprintf(stderr, "BH1750 at 0x5C opened successfully.\n");
    }

    spi_handle = spiOpen(0, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_handles[i] >= 0) i2cClose(i2c_handles[i]);
        }
        gpioTerminate();
        return 1;
    }

    memset(led_buffer, 0, sizeof(led_buffer));
    led_buffer[NUM_LEDS * 4] = 0xFF;
    led_buffer[NUM_LEDS * 4 + 1] = 0xFF;
    led_buffer[NUM_LEDS * 4 + 2] = 0xFF;
    led_buffer[NUM_LEDS * 4 + 3] = 0xFF;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        int sum = 0;
        int valid = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_handles[i] >= 0) {
                int val = read_bh1750(i2c_handles[i]);
                if (val >= 0) {
                    sum += val;
                    valid++;
                } else {
                    fprintf(stderr, "Warning: Read failed from sensor %d: %s\n", i, strerror(errno));
                }
            }
        }
        uint8_t target = 0;
        if (valid > 0) {
            int avg = sum / valid;
            target = (uint8_t)(avg / 100);
            if (target > 255) target = 255;
        }
        fade_leds(target);
        gpioDelay(LOOP_DELAY_US);
    }

    set_led_brightness(0);
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) i2cClose(i2c_handles[i]);
    }
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

