    if (i2c_write_reg8(fd, REG_ALS_CONF, 0x00) < 0) {
        return -1;
    }
    sleep_ms(10);
    return 0;
}

static int veml7700_read_lux(int fd, float *lux_out) {
    uint16_t raw;
    if (i2c_read_reg16(fd, REG_ALS_DATA, &raw) < 0) {
        return -1;
    }
    /* VEML7700 default resolution: 0.2304 lux/count */
    *lux_out = (float)raw * 0.2304f;
    return 0;
}

static uint8_t gamma_correct(uint8_t brightness) {
    float gamma = 2.8f;
    float linear = (float)brightness / 255.0f;
    float corrected = powf(linear, gamma);
    return (uint8_t)(corrected * 255.0f);
}

static void ws2812b_send_byte(uint8_t byte) {
    for (int i = 7; i >= 0; i--) {
        if (byte & (1 << i)) {
            /* Bit '1': ~700ns high, ~600ns low */
            if (ioctl(g_gpio_fd, GPIO_SET_VALUE, 1) < 0) {
                perror("GPIO_SET_VALUE high");
                return;
            }
            sleep_us(1);
            if (ioctl(g_gpio_fd, GPIO_SET_VALUE, 0) < 0) {
                perror("GPIO_SET_VALUE low");
                return;
            }
            sleep_us(1);
        } else {
            /* Bit '0': ~350ns high, ~900ns low */
            if (ioctl(g_gpio_fd, GPIO_SET_VALUE, 1) < 0) {
                perror("GPIO_SET_VALUE high");
                return;
            }
            sleep_us(1);
            if (ioctl(g_gpio_fd, GPIO_SET_VALUE, 0) < 0) {
                perror("GPIO_SET_VALUE low");
                return;
            }
            sleep_us(3);
        }
    }
}

static void ws2812b_set_color(uint8_t r, uint8_t g, uint8_t b) {
    uint8_t gr = gamma_correct(g);
    uint8_t rr = gamma_correct(r);
    uint8_t br = gamma_correct(b);

    for (int i = 0; i < NUM_LEDS; i++) {
        ws2812b_send_byte(gr);
        ws2812b_send_byte(rr);
        ws2812b_send_byte(br);
    }
    /* Latch: hold data line low for >50us */
    if (ioctl(g_gpio_fd, GPIO_SET_VALUE, 0) < 0) {
        perror("GPIO_SET_VALUE latch");
    }
    sleep_us(60);
}

static void ws2812b_off(void) {
    ws2812b_set_color(0, 0, 0);
}

int main(void) {
    struct sigaction sa = { .sa_handler = signal_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (veml7700_init(g_i2c_fd) < 0) {
        fprintf(stderr, "VEML7700 init failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open GPIO character device for bit-banging */
    g_gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (g_gpio_fd < 0) {
        perror("open GPIO chip");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiohandle_request req = {0};
    req.lineoffsets[0] = GPIO_PIN;
    req.flags = GPIOHANDLE_REQUEST_OUTPUT;
    req.default_values[0] = 0;
    req.consumer_label = "ws2812b";

    struct gpiohandle_data data = {0};

    if (ioctl(g_gpio_fd, GPIO_GET_LINEHANDLE_IOCTL, &req) < 0) {
        perror("GPIO_GET_LINEHANDLE_IOCTL");
        close(g_gpio_fd);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("VEML7700 light sensor and WS2812B LED strip ready.\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float lux = 0.0f;
        int retries = I2C_RETRIES;
        bool success = false;

        while (retries > 0 && g_running) {
            if (veml7700_read_lux(g_i2c_fd, &lux) == 0) {
                success = true;
                break;
            }
            fprintf(stderr, "I2C read error (attempt %d/%d): %s\n",
                    I2C_RETRIES - retries + 1, I2C_RETRIES, strerror(errno));
            retries--;
            if (retries > 0) {
                sleep_ms(I2C_RETRY_DELAY_MS);
            }
        }

        if (!success) {
            fprintf(stderr, "Failed to read lux after %d retries. Continuing.\n", I2C_RETRIES);
            lux = 0.0f;
        }

        uint8_t brightness = (uint8_t)(lux / 1000.0f * 255.0f);
        if (brightness > 255) brightness = 255;
        if (brightness < 0)   brightness = 0;

        printf("Lux: %.2f, Brightness: %u\n", lux, brightness);

        /* Drive LED strip with gamma correction */
        ws2812b_set_color(brightness, brightness, brightness);

        sleep_ms(LOOP_DELAY_MS);
    }

    /* Cleanup */
    ws2812b_off();
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    if (g_gpio_fd >= 0) close(g_gpio_fd);

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

