#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN       17
#define LED_PIN          18

#define POLL_INTERVAL_US  50000
#define SELF_TEST_SAMPLES 5
#define SELF_TEST_DELAY_US 100000
#define SELF_TEST_LED_ON_US  500000
#define SELF_TEST_LED_OFF_US 500000
#define SELF_TEST_ERR_ON_US  100000
#define SELF_TEST_ERR_OFF_US 100000
#define SELF_TEST_ERR_CYCLES 5
#define BUZZER_SHORT_US  200000
#define BUZZER_LONG_US   600000
#define BUZZER_REPEATS   3

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    }
    printf("[%s] %s\n", ts, event);
    fflush(stdout);
}

static int set_line_value(struct gpiod_line *line, int value, const char *label) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting %s value to %d: %s\n", label, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int self_test(struct gpiod_line *flame_line, struct gpiod_line *led_line) {
    log_event("Starting self-test...");

    for (int i = 0; i < 2; i++) {
        if (set_line_value(led_line, 1, "LED") < 0) return -1;
        usleep(SELF_TEST_LED_ON_US);
        if (set_line_value(led_line, 0, "LED") < 0) return -1;
        usleep(SELF_TEST_LED_OFF_US);
    }

    int flame_detected = 1;
    for (int i = 0; i < SELF_TEST_SAMPLES; i++) {
        int val = gpiod_line_get_value(flame_line);
        if (val < 0) {
            fprintf(stderr, "Error reading flame sensor during self-test: %s\n", strerror(errno));
            return -1;
        }
        if (val != 0) {
            flame_detected = 0;
            break;
        }
        usleep(SELF_TEST_DELAY_US);
    }

    if (flame_detected) {
        log_event("Self-test failed: Flame sensor stuck LOW.");
        for (int i = 0; i < SELF_TEST_ERR_CYCLES; i++) {
            if (set_line_value(led_line, 1, "LED") < 0) return -1;
            usleep(SELF_TEST_ERR_ON_US);
            if (set_line_value(led_line, 0, "LED") < 0) return -1;
            usleep(SELF_TEST_ERR_OFF_US);
        }
        return -1;
    }

    log_event("Self-test passed.");
    return 0;
}

static void play_buzzer(struct gpiod_line *buzzer_line) {
    for (int r = 0; r < BUZZER_REPEATS; r++) {
        if (set_line_value(buzzer_line, 1, "Buzzer") < 0) return;
        usleep(BUZZER_SHORT_US);
        if (set_line_value(buzzer_line, 0, "Buzzer") < 0) return;
        usleep(BUZZER_SHORT_US);
        if (set_line_value(buzzer_line, 1, "Buzzer") < 0) return;
        usleep(BUZZER_LONG_US);
        if (set_line_value(buzzer_line, 0, "Buzzer") < 0) return;
        usleep(BUZZER_SHORT_US);
        if (set_line_value(buzzer_line, 1, "Buzzer") < 0) return;
        usleep(BUZZER_SHORT_US);
        if (set_line_value(buzzer_line, 0, "Buzzer") < 0) return;
        usleep(BUZZER_SHORT_US);
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        return 1;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!flame_line || !buzzer_line || !led_line) {
        fprintf(stderr, "Error getting GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        fprintf(stderr, "Error requesting flame sensor line as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Error requesting buzzer line as output: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Error requesting LED line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (self_test(flame_line, led_line) < 0) {
        log_event("Self-test failed. Exiting.");
        goto cleanup;
    }

    log_event("Entering main loop.");

    while (program_running) {
        int val = gpiod_line_get_value(flame_line);
        if (val < 0) {
            fprintf(stderr, "Error reading flame sensor: %s\n", strerror(errno));
            log_event("Error reading flame sensor.");
            break;
        }

        if (val == 0) {
            if (set_line_value(buzzer_line, 1, "Buzzer") < 0) break;
            if (set_line_value(led_line, 1, "LED") < 0) break;
            log_event("Flame detected!");
            play_buzzer(buzzer_line);
            while (program_running) {
                int v = gpiod_line_get_value(flame_line);
                if (v < 0) {
                    fprintf(stderr, "Error reading flame sensor: %s\n", strerror(errno));
                    log_event("Error reading flame sensor.");
                    break;
                }
                if (v != 0) break;
                usleep(POLL_INTERVAL_US);
            }
            if (set_line_value(buzzer_line, 0, "Buzzer") < 0) break;
            if (set_line_value(led_line, 0, "LED") < 0) break;
            log_event("Flame cleared.");
        }
        usleep(POLL_INTERVAL_US);
    }

    ret = 0;

cleanup:
    if (led_line) gpiod_line_release(led_line);
    if (buzzer_line) gpiod_line_release(buzzer_line);
    if (flame_line) gpiod_line_release(flame_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

