#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define LED_GPIO       17
#define BUFFER_SIZE    60
#define MIN_FREQ_HZ    0.5
#define MAX_FREQ_HZ    5.0
#define MAX_LUX        1000.0
#define CONV_TIME_MS   180

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, 0x10) < 0) return -1;
    usleep(CONV_TIME_MS * 1000);
    return 0;
}

static int bh1750_read_lux(int fd, float *lux) {
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static void gpio_export(int pin) {
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) { perror("export open"); return; }
    char str[4];
    snprintf(str, sizeof(str), "%d", pin);
    if (write(fd, str, strlen(str)) < 0 && errno != EBUSY)
        perror("export write");
    close(fd);
}

static void gpio_unexport(int pin) {
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) { perror("unexport open"); return; }
    char str[4];
    snprintf(str, sizeof(str), "%d", pin);
    if (write(fd, str, strlen(str)) < 0)
        perror("unexport write");
    close(fd);
}

static void gpio_set_dir(int pin, const char *dir) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) { perror("dir open"); return; }
    if (write(fd, dir, strlen(dir)) < 0)
        perror("dir write");
    close(fd);
}

static void gpio_write(int pin, int val) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) { perror("value open"); return; }
    if (write(fd, val ? "1" : "0", 1) < 0)
        perror("value write");
    close(fd);
}

static void gpio_cleanup(void) {
    gpio_unexport(LED_GPIO);
}

static void add_reading(float lux, float buffer[], int *idx, int size) {
    buffer[*idx] = lux;
    *idx = (*idx + 1) % size;
}

static float calc_avg(const float buffer[], int size) {
    float sum = 0.0f;
    for (int i = 0; i < size; i++)
        sum += buffer[i];
    return sum / (float)size;
}

