static void gpio_export(int pin) {
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) { perror("export open"); return; }
    char str[4];
    snprintf(str, sizeof(str), "%d", pin);
    if (write(fd, str, strlen(str)) < 0 && errno != EBUSY)
        perror("export write");
    close(fd);
}

static void gpio_unexport(int pin) {
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) { perror("unexport open"); return; }
    char str[4];
    snprintf(str, sizeof(str), "%d", pin);
    if (write(fd, str, strlen(str)) < 0)
