#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define DATA_PIN  17
#define CLOCK_PIN 18
#define LATCH_PIN 27

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int shift_out(int data, int clock, int latch, unsigned char data_byte) {
    if (gpioWrite(latch, 0) < 0) return -1;
    for (int i = 7; i >= 0; i--) {
        int bit = (data_byte >> i) & 1;
        if (gpioWrite(data, bit) < 0) return -1;
        if (gpioWrite(clock, 1) < 0) return -1;
        gpioDelay(1);
        if (gpioWrite(clock, 0) < 0) return -1;
        gpioDelay(1);
    }
    if (gpioWrite(latch, 1) < 0) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(DATA_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(CLOCK_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(LATCH_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LATCH_PIN, 0) < 0 || gpioWrite(CLOCK_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise control lines\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Digit '5' on a common-cathode seven-segment display:
     * segments a,b,c,d,e,f ON; g,dp OFF
     * 74HC595 output order: Q0=dp, Q1=g, Q2=f, Q3=e, Q4=d, Q5=c, Q6=b, Q7=a
     * bit pattern = 0b01111101 (MSB first) */
    unsigned char digit5 = 0x7D;

    while (running) {
        if (shift_out(DATA_PIN, CLOCK_PIN, LATCH_PIN, digit5) < 0) {
            fprintf(stderr, "Shift-out failed\n");
            break;
        }
        gpioDelay(500000);
        if (!running) break;
        if (shift_out(DATA_PIN, CLOCK_PIN, LATCH_PIN, 0x00) < 0) {
            fprintf(stderr, "Shift-out (clear) failed\n");
            break;
        }
        gpioDelay(500000);
    }

    /* Clear display and release lines */
    shift_out(DATA_PIN, CLOCK_PIN, LATCH_PIN, 0x00);
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

