/*
 * blink_button.c — Blink an LED on GPIO17 (1 s on, 1 s off) while waiting
 * for a falling-edge event on GPIO18 (pull-up, active-low button).
 *
 * Build:  gcc -O2 -Wall -Wextra -o blink_button blink_button.c -lgpiod
 * Run:    ./blink_button
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define LED_PIN    17
#define BUTTON_PIN 18
#define CHIP_NAME  "gpiochip0"
#define PERIOD_MS  2000
#define TIMEOUT_MS 1000

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_sigint_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        /* Retry on interruption by a signal. */
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led  = NULL;
    struct gpiod_line *btn  = NULL;
    int ret = EXIT_FAILURE;

    if (install_sigint_handler() == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "Failed to get LED line %d: %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }

    btn = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!btn) {
        fprintf(stderr, "Failed to get button line %d: %s\n", BUTTON_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led, "blink_button", 0) < 0) {
        fprintf(stderr, "Failed to request LED line %d as output: %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_falling_edge_events_flags(btn, "blink_button",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request falling-edge events on button line %d: %s\n",
                BUTTON_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Blinking LED on GPIO%d (2 s period) while waiting for falling edge on GPIO%d.\n",
           LED_PIN, BUTTON_PIN);
    printf("Press Ctrl-C to exit.\n");
    fflush(stdout);

    bool led_on = false;
    int  rc;

    while (g_running) {
        if (led_on) {
            if (gpiod_line_set_value(led, 0) < 0) {
                fprintf(stderr, "Failed to set LED low: %s\n", strerror(errno));
                goto cleanup;
            }
            led_on = false;
        } else {
            if (gpiod_line_set_value(led, 1) < 0) {
                fprintf(stderr, "Failed to set LED high: %s\n", strerror(errno));
                goto cleanup;
            }
            led_on = true;
        }

        /* Sleep for half the period, checking for events every 100 ms. */
        for (int i = 0; i < (PERIOD_MS / 100) && g_running; i++) {
            rc = gpiod_line_event_wait(btn, &(struct timespec){ .tv_sec = 0, .tv_nsec = 100000000L });
            if (rc < 0) {
                if (errno == EINTR) {
                    continue;  /* Signal interrupted; re-check g_running. */
                }
                fprintf(stderr, "Event wait failed: %s\n", strerror(errno));
                goto cleanup;
            }
            if (rc > 0) {
                struct gpiod_line_event ev;
                if (gpiod_line_event_read(btn, &ev) < 0) {
                    fprintf(stderr, "Event read failed: %s\n", strerror(errno));
                    goto cleanup;
                }
                if (ev.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                    printf("Button pressed! Stopping blink and exiting.\n");
                    fflush(stdout);
                    goto cleanup;
                }
            }
            sleep_ms(100);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led) {
        gpiod_line_set_value(led, 0);   /* Ensure LED is off. */
        gpiod_line_release(led);
    }
    if (btn) {
        gpiod_line_release(btn);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

