    int  rc;

    while (g_running) {
        if (led_on) {
            if (gpiod_line_set_value(led, 0) < 0) {
                fprintf(stderr, "Failed to set LED low: %s\n", strerror(errno));
                goto cleanup;
            }
            led_on = false;
        } else {
            if (gpiod_line_set_value(led, 1) < 0) {
                fprintf(stderr, "Failed to set LED high: %s\n", strerror(errno));
                goto cleanup;
            }
            led_on = true;
        }

        /* Sleep for half the period, checking for events every 100 ms. */
        for (int i = 0; i < (PERIOD_MS / 100) && g_running; i++) {
            rc = gpiod_line_event_wait(btn, &(struct timespec){ .tv_sec = 0, .tv_nsec = 100000000L });
            if (rc < 0) {
                if (errno == EINTR) {
                    continue;  /* Signal interrupted; re-check g_running. */
                }
                fprintf(stderr, "Event wait failed: %s\n", strerror(errno));
                goto cleanup;
            }
            if (rc > 0) {
                struct gpiod_line_event ev;
                if (gpiod_line_event_read(btn, &ev) < 0) {
                    fprintf(stderr, "Event read failed: %s\n", strerror(errno));
                    goto cleanup;
                }
                if (ev.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                    printf("Button pressed! Stopping blink and exiting.\n");
                    fflush(stdout);
                    goto cleanup;
                }
            }
            sleep_ms(100);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led) {
        gpiod_line_set_value(led, 0);   /* Ensure LED is off. */
        gpiod_line_release(led);
    }
    if (btn) {
        gpiod_line_release(btn);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

