        if (gpioWrite(LED_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to write LOW to GPIO%d.\n", LED_PIN);
            break;
        }
        printf("LED OFF\n");
        fflush(stdout);
        time_sleep(DELAY_MS / 1000.0);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

