/*
 * blink_button.c — LED blink while button is held, using libgpiod.
 *
 * Wiring (Raspberry Pi 40-pin header, BCM numbering):
 *   GPIO24 (pin 18) — LED anode via 330 ohm resistor to GND
 *   GPIO22 (pin 15) — button to 3V3, 10 kohm pull-down to GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o blink_button blink_button.c -lgpiod
 * Run:    sudo ./blink_button   (or ensure user is in the 'gpio' group)
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define LED_PIN    24
#define BUTTON_PIN 22
#define CHIP_NAME  "gpiochip4"   /* main GPIO controller on Pi 5; use "gpiochip0" on Pi 3/4 */

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    while (nanosleep(&ts, &ts) != 0) {
        if (errno != EINTR) {
            perror("nanosleep");
            break;
        }
        /* retry on EINTR so signals are handled promptly */
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led  = NULL;
    struct gpiod_line *btn  = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    led = gpiod_chip_get_line(chip, LED_PIN);
    if (led == NULL) {
        fprintf(stderr, "Failed to get LED line (GPIO%d): %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }

    btn = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (btn == NULL) {
        fprintf(stderr, "Failed to get button line (GPIO%d): %s\n",
                BUTTON_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led, "blink_button", 0) != 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n",
                strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(btn, "blink_button",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) != 0) {
        fprintf(stderr, "Failed to request button line as input with pull-down: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("Press the button (GPIO%d) to blink the LED (GPIO%d).\n",
           BUTTON_PIN, LED_PIN);
    printf("Press Ctrl-C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int val = gpiod_line_get_value(btn);
        if (val < 0) {
            fprintf(stderr, "Failed to read button: %s\n", strerror(errno));
            goto cleanup;
        }

        if (val == 1) {
            /* Button held — blink 500 ms on / 500 ms off */
            if (gpiod_line_set_value(led, 1) != 0) {
                fprintf(stderr, "Failed to turn LED on: %s\n", strerror(errno));
                goto cleanup;
            }
            sleep_ms(500);
            if (!g_running)
                break;
            if (gpiod_line_set_value(led, 0) != 0) {
                fprintf(stderr, "Failed to turn LED off: %s\n", strerror(errno));
                goto cleanup;
            }
            sleep_ms(500);
        } else {
            /* Button released — ensure LED is off */
            if (gpiod_line_set_value(led, 0) != 0) {
                fprintf(stderr, "Failed to turn LED off: %s\n", strerror(errno));
                goto cleanup;
            }
            sleep_ms(50);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led != NULL)
        gpiod_line_release(led);
    if (btn != NULL)
        gpiod_line_release(btn);
    if (chip != NULL)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");
    return ret;
}

