#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

#define PWM_PERIOD_US  10000   /* 10 ms  -> 100 Hz */
#define PWM_STEPS      100     /* 0..99  -> 100 steps */
#define STEP_US        (PWM_PERIOD_US / PWM_STEPS)

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm(int pin, int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;

    int on_us  = (duty_percent * PWM_PERIOD_US) / 100;
    int off_us = PWM_PERIOD_US - on_us;

    if (gpioWrite(pin, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(pin=%d, HIGH) failed\n", pin);
        return -1;
    }
    if (on_us > 0) {
        struct timespec ts = {0, on_us * 1000L};
        clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL);
    }

    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(pin=%d, LOW) failed\n", pin);
        return -1;
    }
    if (off_us > 0) {
        struct timespec ts = {0, off_us * 1000L};
        clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL);
    }
    return 0;
}

static void generate_random_color(int *r, int *g, int *b) {
    *r = rand() % 101;
    *g = rand() % 101;
    *b = rand() % 101;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[3] = {RED_PIN, GREEN_PIN, BLUE_PIN};
    for (int i = 0; i < 3; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode(pin=%d, OUTPUT) failed\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    int red, green, blue;
    generate_random_color(&red, &green, &blue);

    while (running) {
        if (set_pwm(RED_PIN, red) < 0)   break;
        if (set_pwm(GREEN_PIN, green) < 0) break;
        if (set_pwm(BLUE_PIN, blue) < 0)  break;

        generate_random_color(&red, &green, &blue);

        struct timespec ts = {0, 100 * 1000 * 1000L}; /* 100 ms */
        clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL);
    }

    /* Turn off all LEDs and release GPIO lines */
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

