#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* LSM303DLHC I2C addresses */
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

/* LSM303DLHC accelerometer registers */
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A   0x28
#define OUT_X_H_A   0x29
#define OUT_Y_L_A   0x2A
#define OUT_Y_H_A   0x2B
#define OUT_Z_L_A   0x2C
#define OUT_Z_H_A   0x2D

/* GPIO pin for impact interrupt (BCM numbering) */
#define IMPACT_GPIO 17

/* Default impact threshold in G */
#define DEFAULT_THRESHOLD 2.0f

/* Polling interval in microseconds (100 ms = 10 Hz) */
#define POLL_INTERVAL_US 100000

/* Impact pulse duration in microseconds */
#define IMPACT_PULSE_US 50000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_gpio_initialized = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an I2C register; returns 0 on success, -1 on error */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a single byte from an I2C register; returns 0 on success, -1 on error */
static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Initialize the LSM303DLHC accelerometer */
static int init_accelerometer(int fd) {
    /* Enable accelerometer: 50 Hz data rate, normal mode, all axes enabled */
    if (i2c_write_reg(fd, CTRL_REG1_A, 0x27) != 0) {
        return -1;
    }
    /* Set full-scale range to +/- 2g (0x00) and enable high-resolution mode */
    if (i2c_write_reg(fd, CTRL_REG4_A, 0x08) != 0) {
        return -1;
    }
    return 0;
}

/* Read accelerometer data; returns 0 on success, -1 on error */
static int read_accelerometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t xl, xh, yl, yh, zl, zh;

