    if (i2c_read_reg(fd, OUT_X_H_A, &xh) != 0) return -1;
    if (i2c_read_reg(fd, OUT_Y_L_A, &yl) != 0) return -1;
    if (i2c_read_reg(fd, OUT_Y_H_A, &yh) != 0) return -1;
    if (i2c_read_reg(fd, OUT_Z_L_A, &zl) != 0) return -1;
