#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define ADPD188BI_ADDR 0x58
#define LED_GPIO 18
#define PWM_RANGE 1024
#define SAMPLE_INTERVAL_US 500000
#define RETRY_DELAY_US 100000

#define ALS_LSB_REG 0x0A
#define ALS_MSB_REG 0x0B
#define RED_LSB_REG 0x0C
#define RED_MSB_REG 0x0D
#define GREEN_LSB_REG 0x0E
#define GREEN_MSB_REG 0x0F
#define BLUE_LSB_REG 0x10
#define BLUE_MSB_REG 0x11

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(uint8_t reg, uint8_t *value) {
    if (i2cWriteByte(i2c_handle, reg) < 0) return -1;
    int b = i2cReadByte(i2c_handle);
    if (b < 0) return -1;
    *value = (uint8_t)b;
    return 0;
}

static int read_als(uint16_t *als) {
    uint8_t lsb, msb;
    if (read_register(ALS_LSB_REG, &lsb) < 0) return -1;
    if (read_register(ALS_MSB_REG, &msb) < 0) return -1;
    *als = ((uint16_t)msb << 8) | lsb;
    return 0;
}

static int read_color(uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t r_lsb, r_msb, g_lsb, g_msb, b_lsb, b_msb;
    if (read_register(RED_LSB_REG, &r_lsb) < 0) return -1;
    if (read_register(RED_MSB_REG, &r_msb) < 0) return -1;
    if (read_register(GREEN_LSB_REG, &g_lsb) < 0) return -1;
    if (read_register(GREEN_MSB_REG, &g_msb) < 0) return -1;
    if (read_register(BLUE_LSB_REG, &b_lsb) < 0) return -1;
    if (read_register(BLUE_MSB_REG, &b_msb) < 0) return -1;
    *red = ((uint16_t)r_msb << 8) | r_lsb;
    *green = ((uint16_t)g_msb << 8) | g_lsb;
    *blue = ((uint16_t)b_msb << 8) | b_lsb;
    return 0;
}

static void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(log_file);
}

static void control_led(uint16_t als) {
    int duty = (int)((als / 65535.0) * PWM_RANGE);
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (duty < 0) duty = 0;
    gpioPWM(LED_GPIO, duty);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioPWM(LED_GPIO, 0);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", ADPD188BI_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);
    gpioPWM(LED_GPIO, 0);

    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "timestamp,als,red,green,blue\n");
    fflush(log_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting ADPD188BI color sensor logging...\n");

    while (!terminate) {
        uint16_t als, red, green, blue;
        if (read_als(&als) == 0 && read_color(&red, &green, &blue) == 0) {
            log_data(als, red, green, blue);
            control_led(als);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("Shutting down...\n");
    cleanup();
    return 0;
}

