    int duty = (int)((als / 65535.0) * PWM_RANGE);
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (duty < 0) duty = 0;
    gpioPWM(LED_GPIO, duty);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioPWM(LED_GPIO, 0);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", ADPD188BI_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);
    gpioPWM(LED_GPIO, 0);

    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "timestamp,als,red,green,blue\n");
    fflush(log_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting ADPD188BI color sensor logging...\n");

    while (!terminate) {
        uint16_t als, red, green, blue;
        if (read_als(&als) == 0 && read_color(&red, &green, &blue) == 0) {
            log_data(als, red, green, blue);
            control_led(als);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("Shutting down...\n");
    cleanup();
    return 0;
}

