#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- FXOS8700CQ constants (datasheet) ---- */
#define FXOS8700_I2C_ADDR  0x20
#define FXOS8700_WHO_AM_I  0x0D
#define FXOS8700_WHO_AM_I_VAL 0xC7
#define FXOS8700_CTRL_REG1  0x2A
#define FXOS8700_CTRL_REG2  0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB  0x01

/* ±2 g range, 14-bit resolution, 200 Hz ODR */
#define FXOS8700_CTRL_REG1_CFG 0x00  /* ACTIVE = 0, standby */
#define FXOS8700_CTRL_REG2_CFG 0x02  /* ±2 g, 14-bit */
#define FXOS8700_M_CTRL_REG1_CFG 0x1F /* OS=1, HYS=0, MODE=1 (hybrid) */
#define FXOS8700_M_CTRL_REG2_CFG 0x20 /* auto-reset, auto-increment */

#define IMPACT_THRESHOLD  2.5f   /* g */
#define SAMPLE_PERIOD_US  50000  /* 50 ms */
#define LOG_FILE          "impact_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int fxos_write(uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, val, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
static int fxos_read_block(uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(g_i2c_handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X, len=%u) failed: %d\n",
                reg, len, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
static int fxos_init(void)
{
    /* Verify device identity */
    int who = i2cReadByteData(g_i2c_handle, FXOS8700_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "[ERROR] Cannot read WHO_AM_I register: %d\n", who);
        return -1;
    }
    if (who != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "[ERROR] WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Put device in standby so configuration changes take effect */
    if (fxos_write(FXOS8700_CTRL_REG1, 0x00) < 0) return -1;
    gpioDelay(1000); /* 1 ms settle */

    /* Configure magnetometer: hybrid mode, auto-reset, auto-increment */
    if (fxos_write(FXOS8700_M_CTRL_REG1, FXOS8700_M_CTRL_REG1_CFG) < 0) return -1;
    if (fxos_write(FXOS8700_M_CTRL_REG2, FXOS8700_M_CTRL_REG2_CFG) < 0) return -1;

    /* Accelerometer range ±2 g, 14-bit */
    if (fxos_write(FXOS8700_CTRL_REG2, FXOS8700_CTRL_REG2_CFG) < 0) return -1;

    /* Activate: ACTIVE = 1, ODR = 001 (200 Hz) */
    if (fxos_write(FXOS8700_CTRL_REG1, 0x01) < 0) return -1;
    gpioDelay(1000); /* 1 ms settle */

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_accel(int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (fxos_read_block(FXOS8700_OUT_X_MSB, buf, sizeof(buf)) != (int)sizeof(buf))
        return -1;

    /* 14-bit left-justified: shift right 2 to get signed 16-bit value */
    *x = (int16_t)((buf[0] << 8) | buf[1]) >> 2;
    *y = (int16_t)((buf[2] << 8) | buf[3]) >> 2;
    *z = (int16_t)((buf[4] << 8) | buf[5]) >> 2;
    return 0;
}

/* ------------------------------------------------------------------ */
static float accel_magnitude(int16_t x, int16_t y, int16_t z)
{
    /* ±2 g range => 1 g = 4096 counts (14-bit, 2 g / 2^14) */
    const float scale = 1.0f / 4096.0f;
    float ax = (float)x * scale;
    float ay = (float)y * scale;
    float az = (float)z * scale;
    return sqrtf(ax * ax + ay * ay + az * az);
}

/* ------------------------------------------------------------------ */
static void log_impact(int16_t x, int16_t y, int16_t z, float mag)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%d,%d,%d,%.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                x, y, z, mag);
    } else {
        fprintf(fp, "1970-01-01 00:00:00,%d,%d,%d,%.3f\n", x, y, z, mag);
    }

    if (fclose(fp) != 0)
        perror("[WARN] fclose(" LOG_FILE ")");
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the FXOS8700CQ address */
    g_i2c_handle = i2cOpen(1, FXOS8700_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                FXOS8700_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (fxos_init() != 0) {
        fprintf(stderr, "[ERROR] FXOS8700CQ initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("FXOS8700CQ initialized. Logging impacts (threshold %.2f g) to %s\n",
           IMPACT_THRESHOLD, LOG_FILE);
    printf("Press Ctrl-C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t x, y, z;

        if (read_accel(&x, &y, &z) == 0) {
            float mag = accel_magnitude(x, y, z);
            if (mag > IMPACT_THRESHOLD) {
                log_impact(x, y, z, mag);
                printf("[IMPACT] mag=%.3f g  (x=%d, y=%d, z=%d)\n", mag, x, y, z);
            }
        } else {
            fprintf(stderr, "[WARN] Accelerometer read failed; continuing.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

