#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define GYRO_ADDR      0x69
#define WHO_AM_I       0x0F
#define WHO_AM_I_VAL   0xD3
#define CTRL_REG1      0x20
#define CTRL_REG4      0x23
#define OUT_X_L        0x28
#define OUT_X_H        0x29
#define OUT_Y_L        0x2A
#define OUT_Y_H        0x2B
#define OUT_Z_L        0x2C
#define OUT_Z_H        0x2D
#define NUM_CAL_SAMPLES 100
#define CALIBRATION_DELAY_MS 100
#define SAMPLE_PERIOD_US 50000
#define ALERT_THRESHOLD 50.0f
#define LOG_FILE "gyro_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (burst reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_gyro(void) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(i2c_fd, WHO_AM_I, &who_am_i) < 0) return -1;
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg8(i2c_fd, CTRL_REG1, 0x0F) < 0) return -1;
    if (i2c_write_reg8(i2c_fd, CTRL_REG4, 0x80) < 0) return -1;
    return 0;
}

static int read_gyro_raw(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(i2c_fd, OUT_X_L | 0x80, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void calibrate_gyro(float *x_off, float *y_off, float *z_off) {
    int16_t x, y, z;
    long sx = 0, sy = 0, sz = 0;
    printf("Calibrating gyroscope (keep sensor stationary)...\n");
    for (int i = 0; i < NUM_CAL_SAMPLES; i++) {
        if (read_gyro_raw(&x, &y, &z) < 0) {
            fprintf(stderr, "Calibration read failed at sample %d\n", i);
            *x_off = *y_off = *z_off = 0.0f;
            return;
        }
        sx += x; sy += y; sz += z;
        usleep(CALIBRATION_DELAY_MS * 1000);
    }
    *x_off = (float)sx / NUM_CAL_SAMPLES;
    *y_off = (float)sy / NUM_CAL_SAMPLES;
    *z_off = (float)sz / NUM_CAL_SAMPLES;
    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n", *x_off, *y_off, *z_off);
}

