#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADXL345 I2C address (SDO tied to GND) */
#define ADXL345_ADDR 0x53

/* ADXL345 registers */
#define ADXL345_DEVID       0x00
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0      0x32
#define ADXL345_DEVID_VAL   0xE5

/* GPIO pin for LED (BCM numbering) */
#define LED_PIN 17

/* Acceleration threshold in g */
#define ACCEL_THRESHOLD 2.0f

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Full-resolution sensitivity: 4 mg/LSB at ±2 g */
#define SCALE_FACTOR 0.004f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value)
{
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z)
{
    char data[6];
    int result = i2cReadI2CBlockData(handle, ADXL345_DATAX0, data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading acceleration data: %d\n", result);
        return -1;
    }

    int16_t raw_x = (int16_t)(((uint8_t)data[1] << 8) | (uint8_t)data[0]);
    int16_t raw_y = (int16_t)(((uint8_t)data[3] << 8) | (uint8_t)data[2]);
    int16_t raw_z = (int16_t)(((uint8_t)data[5] << 8) | (uint8_t)data[4]);

    *x = (float)raw_x * SCALE_FACTOR;
    *y = (float)raw_y * SCALE_FACTOR;
    *z = (float)raw_z * SCALE_FACTOR;

    return 0;
}

static void log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(fp);
}

static void control_led(float x, float y, float z)
{
    int threshold_exceeded = (fabsf(x) > ACCEL_THRESHOLD ||
                              fabsf(y) > ACCEL_THRESHOLD ||
                              fabsf(z) > ACCEL_THRESHOLD);

    if (gpioWrite(LED_PIN, threshold_exceeded) < 0) {
        fprintf(stderr, "Error writing to LED pin %d\n", LED_PIN);
    }
}

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %d\n",
                ADXL345_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t devid = 0;
    if (read_register(i2c_handle, ADXL345_DEVID, &devid) != 0) {
        fprintf(stderr, "Cannot read DEVID — sensor may be absent\n");
        cleanup();
        return 1;
    }
    if (devid != ADXL345_DEVID_VAL) {
        fprintf(stderr, "Unexpected DEVID: 0x%02X (expected 0x%02X)\n",
                devid, ADXL345_DEVID_VAL);
        cleanup();
        return 1;
    }

    /* Standby mode before configuration */
    if (write_register(i2c_handle, ADXL345_POWER_CTL, 0x00) != 0) {
        cleanup();
        return 1;
    }

    /* Full resolution, ±2 g range, right-justified */
    if (write_register(i2c_handle, ADXL345_DATA_FORMAT, 0x0B) != 0) {
        cleanup();
        return 1;
    }

    /* Measurement mode */
    if (write_register(i2c_handle, ADXL345_POWER_CTL, 0x08) != 0) {
        cleanup();
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting LED pin %d as output\n", LED_PIN);
        cleanup();
        return 1;
    }
    gpioWrite(LED_PIN, 0);

    log_file = fopen("accel_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("ADXL345 logging started. Press Ctrl+C to stop.\n");

    while (running) {
        float x, y, z;

        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
            control_led(x, y, z);
        } else {
            fprintf(stderr, "Read error — skipping sample\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    cleanup();
    return 0;
}

