#define ACCEL_SENSITIVITY 0.000061f
#define MAG_SENSITIVITY   0.0001f

static volatile sig_atomic_t running = 1;
static int i2c_handle_accel = -1;
static int i2c_handle_mag   = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
