        fprintf(stderr, "Error writing to magnetometer MR_REG_M\n");
        goto cleanup;
    }

    FILE *fp = fopen("compass_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        goto cleanup;
    }
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y,Mag_Z\n");
    }

    while (running) {
        float ax, ay, az, mx, my, mz;
        if (read_accelerometer(i2c_handle_accel, &ax, &ay, &az) == 0 &&
            read_magnetometer(i2c_handle_mag, &mx, &my, &mz) == 0) {
            float heading = calculate_heading(ax, ay, az, mx, my, mz);
            log_data(fp, heading, ax, ay, az, mx, my, mz);
