#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x1A
#define SENSOR2_ADDR 0x1B
#define SAMPLE_INTERVAL_US 10000
#define LOG_FILE "audio_log.dat"

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int handle, int16_t *out) {
    char buf[2];
    int bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "I2C read failed (handle %d): %s\n", handle, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static double calculate_tdoa(struct timespec ts1, struct timespec ts2) {
    return (double)(ts1.tv_sec - ts2.tv_sec) + (double)(ts1.tv_nsec - ts2.tv_nsec) / 1e9;
}

static int log_data(FILE *fp, struct timespec ts1, struct timespec ts2, int16_t s1, int16_t s2, double tdoa) {
    if (fprintf(fp, "%ld,%09ld,%d,%d,%.9f\n", (long)ts1.tv_sec, ts1.tv_nsec, s1, s2, tdoa) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
        i2c_handle2 = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n", SENSOR1_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n", SENSOR2_ADDR, strerror(errno));
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
        i2cClose(i2c_handle2);
        i2c_handle2 = -1;
        gpioTerminate();
        return 1;
    }

    while (running) {
        struct timespec ts1, ts2;
        int16_t sensor1_data, sensor2_data;

        if (clock_gettime(CLOCK_REALTIME, &ts1) != 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            break;
        }

        if (read_sensor_data(i2c_handle1, &sensor1_data) != 0) {
            fprintf(stderr, "Sensor 1 read error, skipping sample\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        if (clock_gettime(CLOCK_REALTIME, &ts2) != 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            break;
        }

        if (read_sensor_data(i2c_handle2, &sensor2_data) != 0) {
            fprintf(stderr, "Sensor 2 read error, skipping sample\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        double tdoa = calculate_tdoa(ts1, ts2);

        if (log_data(log_file, ts1, ts2, sensor1_data, sensor2_data, tdoa) != 0) {
            fprintf(stderr, "Logging failed, exiting\n");
            break;
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

