#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16488A Register Addresses */
#define ADIS16488A_XGYRO_OUT  0x04
#define ADIS16488A_YGYRO_OUT  0x06
#define ADIS16488A_ZGYRO_OUT  0x08
#define ADIS16488A_XACCEL_OUT 0x0A
#define ADIS16488A_YACCEL_OUT 0x0C
#define ADIS16488A_ZACCEL_OUT 0x0E

/* Sensitivity values */
#define GYRO_SENSITIVITY    0.005f   /* deg/sec/LSB */
#define ACCEL_SENSITIVITY   0.00025f /* g/LSB */

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 /* 1 MHz */
#define SPI_MODE    3       /* CPOL=1, CPHA=1 */

/* Timing */
#define STALL_TIME_US  40   /* Stall time between read request and data transfer */
#define SAMPLE_DELAY_US 100000 /* 100 ms */

/* Global variables */
static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t running = 1;

/* Structure to hold IMU data */
typedef struct {
    float gyro_x, gyro_y, gyro_z;
    float accel_x, accel_y, accel_z;
} imu_data_t;

/* Function prototypes */
static int read_register(uint8_t reg, int16_t *value);
static int read_imu_data(imu_data_t *data);
static void log_data(imu_data_t data);
static void cleanup(void);
static void signal_handler(int signal);
static void delay_us_nonblocking(uint32_t us);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Non-blocking delay that checks the running flag every 10 ms */
static void delay_us_nonblocking(uint32_t us) {
    uint32_t elapsed = 0;
    while (elapsed < us && running) {
