#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8

#define ADIS16448_GX    0x04
#define ADIS16448_GY    0x06
#define ADIS16448_GZ    0x08
#define ADIS16448_AX    0x0A
#define ADIS16448_AY    0x0C
#define ADIS16448_AZ    0x0E

