    if (read_register(ADIS16448_GY, &raw_gy) < 0) return -1;
    if (read_register(ADIS16448_GZ, &raw_gz) < 0) return -1;
    if (read_register(ADIS16448_AX, &raw_ax) < 0) return -1;
    if (read_register(ADIS16448_AY, &raw_ay) < 0) return -1;
