        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return 1;
    }

    printf("ADIS16448 IMU Reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float gx, gy, gz, ax, ay, az;

        if (read_imu_data(&gx, &gy, &gz, &ax, &ay, &az) == 0) {
            printf("Gyro X: %.2f dps, Gyro Y: %.2f dps, Gyro Z: %.2f dps, "
