    gpioDelay(40);

    /* Second transfer: send dummy to clock out data */
    tx_buf[0] = 0x00;
    tx_buf[1] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error: SPI transfer failed for register 0x%02X (data read).\n", reg_addr);
        return -1;
