    if (read_register(ADIS16448_GYOUT, &raw_gyro_y) != 0) return -1;
    if (read_register(ADIS16448_GZOUT, &raw_gyro_z) != 0) return -1;
    if (read_register(ADIS16448_XACCL, &raw_accel_x) != 0) return -1;
    if (read_register(ADIS16448_YACCL, &raw_accel_y) != 0) return -1;
    if (read_register(ADIS16448_ZACCL, &raw_accel_z) != 0) return -1;

    *gyro_x  = (float)raw_gyro_x  * GYRO_SCALE;
    *gyro_y  = (float)raw_gyro_y  * GYRO_SCALE;
    *gyro_z  = (float)raw_gyro_z  * GYRO_SCALE;
    *accel_x = (float)raw_accel_x * ACCEL_SCALE;
    *accel_y = (float)raw_accel_y * ACCEL_SCALE;
    *accel_z = (float)raw_accel_z * ACCEL_SCALE;

    return 0;
}

int main() {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d).\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    /* Main loop */
    while (!terminate) {
        if (read_imu_data(&gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z) == 0) {
            printf("Gyro X: %.2f deg/s, Gyro Y: %.2f deg/s, Gyro Z: %.2f deg/s\n",
                   gyro_x, gyro_y, gyro_z);
            printf("Accel X: %.4f g, Accel Y: %.4f g, Accel Z: %.4f g\n",
                   accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Error: Failed to read IMU data.\n");
        }

        gpioDelay(100000); /* 100 ms delay */
    }

    /* Clean up */
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

