/*
 * MPU-6886 6-axis IMU reader for Raspberry Pi 4 Model B
 * Bus: I2C-1 (GPIO2=SDA, GPIO3=SCL), address 0x68
 * Reads accel (X/Y/Z) and gyro (X/Y/Z) every 50 ms and prints raw 16-bit values.
 * Retries transient I2C errors up to 3 times; closes the bus on SIGINT/SIGTERM.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mpu6886_reader mpu6886_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6886_ADDR   0x68

/* MPU-6886 register map (verified against the datasheet) */
#define REG_SMPLRT_DIV  0x19
#define REG_CONFIG      0x1A
#define REG_GYRO_CFG    0x1B
#define REG_ACCEL_CFG   0x1C
#define REG_ACCEL_CFG2  0x1D
#define REG_INT_PIN_CFG 0x37
#define REG_ACCEL_XOUT_H 0x3B
#define REG_GYRO_XOUT_H  0x43

#define SAMPLE_PERIOD_US 50000   /* 50 ms */
#define MAX_RETRIES      3

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit register; returns 0 on success, -1 on error. */
static int reg_write8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "reg_write8(0x%02X): write returned %zd: %s\n",
                reg, n, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read `len` bytes starting at `reg` using a combined SMBus-style transfer. */
static int reg_read_burst(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    if (len == 0 || len > 64)
        return -1;

    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "reg_read_burst(0x%02X): write pointer failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* Read the data bytes */
    ssize_t n = read(fd, dst, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "reg_read_burst(0x%02X): read returned %zd (expected %zu): %s\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int mpu6886_init(int fd)
{
    /*
     * Sample rate = 1 kHz / (1 + SMPLRT_DIV).
     * 0x07 -> 1 kHz / 8 = 125 Hz.
     */
    if (reg_write8(fd, REG_SMPLRT_DIV, 0x07) == -1)
        return -1;

    /* DLPF_CFG = 0x01 (21 Hz gyro bandwidth, 1.25 kHz gyro output) */
    if (reg_write8(fd, REG_CONFIG, 0x01) == -1)
        return -1;

    /* Gyro full-scale range: ±250 °/s (FS_SEL=0) */
    if (reg_write8(fd, REG_GYRO_CFG, 0x00) == -1)
        return -1;

    /* Accel full-scale range: ±2 g (AFS_SEL=0) */
    if (reg_write8(fd, REG_ACCEL_CFG, 0x00) == -1)
        return -1;

    /* Accel DLPF: ODR=1 kHz, DLPF_CFG=0x00 (460 Hz bandwidth) */
    if (reg_write8(fd, REG_ACCEL_CFG2, 0x00) == -1)
        return -1;

    /* INT_PIN_CFG: LATCH_INT_EN=0, INT_ANYRD_2CLEAR=0, ACTL=0, open-drain=0 */
    if (reg_write8(fd, REG_INT_PIN_CFG, 0x00) == -1)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_sensor_data(int fd, int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *gx, int16_t *gy, int16_t *gz)
{
    uint8_t buf[14];

    /*
     * Burst read 14 bytes starting at ACCEL_XOUT_H:
     *   [0..5]  accel X/Y/Z (6)
     *   [6..7]  temperature (2)  -- skipped
     *   [8..13] gyro  X/Y/Z (6)
     */
    if (reg_read_burst(fd, REG_ACCEL_XOUT_H, buf, sizeof(buf)) == -1)
        return -1;

    *ax = (int16_t)((buf[0]  << 8) | buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | buf[3]);
    *az = (int16_t)((buf[4]  << 8) | buf[5]);
    *gx = (int16_t)((buf[8]  << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = (int16_t)((buf[12] << 8) | buf[13]);
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t ax, ay, az, gx, gy, gz;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() == -1)
        return EXIT_FAILURE;

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                MPU6886_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Probe: try reading the WHO_AM_I register (0x75) */
    uint8_t whoami = 0;
    if (reg_read_burst(g_fd, 0x75, &whoami, 1) == -1) {
        fprintf(stderr, "Sensor not responding at 0x%02X on %s\n",
                MPU6886_ADDR, I2C_BUS);
        goto cleanup;
    }
    if (whoami != 0x70) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x70\n", whoami);
        goto cleanup;
    }

    if (mpu6886_init(g_fd) == -1) {
        fprintf(stderr, "MPU-6886 initialization failed\n");
        goto cleanup;
    }

    printf("MPU-6886 ready at 0x%02X on %s. Sampling every %d ms. Ctrl-C to stop.\n",
           MPU6886_ADDR, I2C_BUS, SAMPLE_PERIOD_US / 1000);

    while (g_running) {
        int ok = 0;
        for (int attempt = 1; attempt <= MAX_RETRIES && g_running; ++attempt) {
            if (read_sensor_data(g_fd, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES)
                usleep(1000);
        }

        if (ok) {
            printf("Accel: X=%6d Y=%6d Z=%6d  |  Gyro: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Sensor read failed after %d attempts; continuing.\n",
                    MAX_RETRIES);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nExiting cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (g_fd >= 0) {
        close(g_fd);
        g_fd = -1;
    }
    return rc;
}

