    *gz = (int16_t)((buf[12] << 8) | buf[13]);
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t ax, ay, az, gx, gy, gz;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() == -1)
        return EXIT_FAILURE;

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                MPU6886_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Probe: try reading the WHO_AM_I register (0x75) */
    uint8_t whoami = 0;
    if (reg_read_burst(g_fd, 0x75, &whoami, 1) == -1) {
        fprintf(stderr, "Sensor not responding at 0x%02X on %s\n",
                MPU6886_ADDR, I2C_BUS);
        goto cleanup;
    }
    if (whoami != 0x70) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x70\n", whoami);
        goto cleanup;
    }

    if (mpu6886_init(g_fd) == -1) {
        fprintf(stderr, "MPU-6886 initialization failed\n");
        goto cleanup;
    }

    printf("MPU-6886 ready at 0x%02X on %s. Sampling every %d ms. Ctrl-C to stop.\n",
           MPU6886_ADDR, I2C_BUS, SAMPLE_PERIOD_US / 1000);

    while (g_running) {
        int ok = 0;
        for (int attempt = 1; attempt <= MAX_RETRIES && g_running; ++attempt) {
            if (read_sensor_data(g_fd, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES)
                usleep(1000);
        }

        if (ok) {
            printf("Accel: X=%6d Y=%6d Z=%6d  |  Gyro: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Sensor read failed after %d attempts; continuing.\n",
                    MAX_RETRIES);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nExiting cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (g_fd >= 0) {
        close(g_fd);
        g_fd = -1;
    }
    return rc;
}

