#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADXL345 constants (datasheet) ---- */
#define ADXL345_ADDR          0x53
#define ADXL345_REG_DEVID     0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATA_FMT  0x31
#define ADXL345_REG_DATAX0    0x32
#define ADXL345_DEVID_EXPECTED 0xE5

#define I2C_BUS              1
#define LED_GPIO             17
#define THRESHOLD_G          2.5f
#define SCALE_FACTOR         256.0f   /* LSB per g in full-resolution, +/-2g */
#define POLL_INTERVAL_US     10000    /* 10 ms */
#define LED_ON_DURATION_US   500000   /* 500 ms */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure LED is off before terminating pigpio */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
static int adxl345_init(int handle)
{
    /* Standby -> set data format to full resolution, +/-2g (0x08) */
    if (i2cWriteByteData(handle, ADXL345_REG_DATA_FMT, 0x08) < 0) {
        fprintf(stderr, "Error: failed to set DATA_FMT register\n");
        return -1;
    }
    /* Clear sleep bit, set measure bit -> standby -> measure */
    if (i2cWriteByteData(handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: failed to set POWER_CTL register\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_acceleration(int handle, float *x, float *y, float *z)
{
    char raw[6];

    if (i2cReadI2CBlockData(handle, ADXL345_REG_DATAX0, raw, 6) != 6) {
        fprintf(stderr, "Error: failed to read 6-byte acceleration block\n");
        return -1;
    }

    int16_t x_raw = (int16_t)(((uint8_t)raw[1] << 8) | (uint8_t)raw[0]);
    int16_t y_raw = (int16_t)(((uint8_t)raw[3] << 8) | (uint8_t)raw[2]);
    int16_t z_raw = (int16_t)(((uint8_t)raw[5] << 8) | (uint8_t)raw[4]);

    *x = (float)x_raw / SCALE_FACTOR;
    *y = (float)y_raw / SCALE_FACTOR;
    *z = (float)z_raw / SCALE_FACTOR;
    return 0;
}

/* ------------------------------------------------------------------ */
static float calculate_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ------------------------------------------------------------------ */
static void log_impact(float x, float y, float z, float magnitude)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[80];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file,
            "%s - Impact detected: X=%.3f g, Y=%.3f g, Z=%.3f g, Magnitude=%.3f g\n",
            timestamp, x, y, z, magnitude);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    float x, y, z, magnitude;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- LED GPIO setup ---- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at addr 0x%02X\n",
                I2C_BUS, ADXL345_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Verify device identity ---- */
    int devid = i2cReadByteData(g_i2c_handle, ADXL345_REG_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error: failed to read DEVID register\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr,
                "Error: device ID mismatch (got 0x%02X, expected 0x%02X) - "
                "sensor absent or wrong device\n",
                devid, ADXL345_DEVID_EXPECTED);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (adxl345_init(g_i2c_handle) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log_file = fopen("impact_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: failed to open impact_log.txt for appending\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL345 impact monitor running. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        if (read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);
            if (magnitude > THRESHOLD_G) {
                gpioWrite(LED_GPIO, 1);
                log_impact(x, y, z, magnitude);
                gpioDelay(LED_ON_DURATION_US);
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            /* Bus error: back off briefly to avoid log flooding */
            gpioDelay(100000);
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

