    if (i2cWriteByteData(i2c_handle, REG_ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing ACCEL_CONFIG\n");
        return -1;
    }
    return 0;
}

static int read_imu_data(imu_data_t *data) {
    char buf[14];

    /* Burst read 14 bytes starting at ACCEL_XOUT_H (0x2D):
     * AXH, AXL, AYH, AYL, AZH, AZL, TEMP_H, TEMP_L, GXH, GXL, GYH, GYL, GZH, GZL */
    if (i2cReadI2CBlockData(i2c_handle, REG_ACCEL_XOUT_H, buf, 14) != 14) {
        fprintf(stderr, "Error reading IMU data block\n");
        return -1;
    }

    int16_t ax = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    int16_t ay = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    int16_t az = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);
    int16_t gx = (int16_t)((buf[8]  << 8) | (uint8_t)buf[9]);
    int16_t gy = (int16_t)((buf[10] << 8) | (uint8_t)buf[11]);
    int16_t gz = (int16_t)((buf[12] << 8) | (uint8_t)buf[13]);

    data->accel_x = (float)ax / ACCEL_SENSITIVITY;
    data->accel_y = (float)ay / ACCEL_SENSITIVITY;
    data->accel_z = (float)az / ACCEL_SENSITIVITY;
    data->gyro_x  = (float)gx / GYRO_SENSITIVITY;
    data->gyro_y  = (float)gy / GYRO_SENSITIVITY;
    data->gyro_z  = (float)gz / GYRO_SENSITIVITY;

    return 0;
}

static void log_data(const imu_data_t *data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
    fprintf(log_file, "%.6f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, data->accel_x, data->accel_y, data->accel_z,
            data->gyro_x, data->gyro_y, data->gyro_z);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_imu() != 0) {
        fprintf(stderr, "IMU initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,accel_x,accel_y,accel_z,gyro_x,gyro_y,gyro_z\n");
    }

    imu_data_t imu_data;
    while (!terminate) {
        if (read_imu_data(&imu_data) == 0) {
            log_data(&imu_data);
        } else {
            fprintf(stderr, "Failed to read IMU data\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

