#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS        1
#define I2C_ADDR       0x1D          /* GY-45 default (SA0 tied high) */
#define CTRL_REG1      0x2A
#define OUT_X_MSB      0x01
#define WHO_AM_I       0x0D
#define WHO_AM_I_VAL   0x2A          /* MMA8451Q device ID */
#define LED_GPIO       17            /* BCM 17 */
#define G_THRESHOLD    2.0f          /* g */
#define G_PER_COUNT    (1.0f / 1024.0f) /* ±2 g range */
#define POLL_MS        100
#define LED_ON_MS      500

/* ---- Globals for cleanup ---- */
static int  i2c_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg(uint8_t reg, uint8_t val)
{
    char buf[2] = { (char)reg, (char)val };
    return i2cWriteDevice(i2c_handle, buf, 2);
}

static int i2c_read_reg(uint8_t reg, uint8_t *val)
{
    char wbuf[1] = { (char)reg };
    if (i2cWriteDevice(i2c_handle, wbuf, 1) != 0)
        return -1;
    char rbuf[1];
    if (i2cReadDevice(i2c_handle, rbuf, 1) != 1)
        return -1;
    *val = (uint8_t)rbuf[0];
    return 0;
}

/* ---- Accelerometer ---- */
static int init_accelerometer(void)
{
    uint8_t who;
    if (i2c_read_reg(WHO_AM_I, &who) != 0) {
        fprintf(stderr, "Error: cannot read WHO_AM_I register\n");
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode to allow configuration */
    if (i2c_write_reg(CTRL_REG1, 0x00) != 0) {
        fprintf(stderr, "Error: cannot set standby mode\n");
        return -1;
    }
    gpioDelay(2000); /* 2 ms */

    /* Active mode, 800 Hz ODR, no sleep */
    if (i2c_write_reg(CTRL_REG1, 0x01) != 0) {
        fprintf(stderr, "Error: cannot set active mode\n");
        return -1;
    }
    gpioDelay(2000);

    return 0;
}

static int read_acceleration(float *x, float *y, float *z)
{
    uint8_t x_msb, x_lsb, y_msb, y_lsb, z_msb, z_lsb;

    if (i2c_read_reg(OUT_X_MSB, &x_msb) != 0) return -1;
    if (i2c_read_reg(OUT_X_MSB + 1, &x_lsb) != 0) return -1;
    if (i2c_read_reg(OUT_X_MSB + 2, &y_msb) != 0) return -1;
    if (i2c_read_reg(OUT_X_MSB + 3, &y_lsb) != 0) return -1;
    if (i2c_read_reg(OUT_X_MSB + 4, &z_msb) != 0) return -1;
    if (i2c_read_reg(OUT_X_MSB + 5, &z_lsb) != 0) return -1;

    int16_t raw_x = (int16_t)((x_msb << 8) | x_lsb);
    int16_t raw_y = (int16_t)((y_msb << 8) | y_lsb);
    int16_t raw_z = (int16_t)((z_msb << 8) | z_lsb);

    *x = (float)raw_x * G_PER_COUNT;
    *y = (float)raw_y * G_PER_COUNT;
    *z = (float)raw_z * G_PER_COUNT;
    return 0;
}

static bool threshold_exceeded(float x, float y, float z)
{
    return fabsf(x) > G_THRESHOLD || fabsf(y) > G_THRESHOLD || fabsf(z) > G_THRESHOLD;
}

/* ---- Logging ---- */
static void log_impact(float x, float y, float z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g\n", timestamp, x, y, z);
    fflush(log_file);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    float x, y, z;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_accelerometer() != 0) {
        fprintf(stderr, "Error: accelerometer init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set GPIO%d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open impact_log.txt\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring acceleration (threshold %.1f g)... Press Ctrl+C to exit.\n",
           G_THRESHOLD);

    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            if (threshold_exceeded(x, y, z)) {
                gpioWrite(LED_GPIO, 1);
                log_impact(x, y, z);
                gpioDelay(LED_ON_MS * 1000);
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Warning: I2C read error\n");
        }
        gpioDelay(POLL_MS * 1000);
    }

    printf("\nExiting cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

