#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMAG5273_ADDR  0x48
#define CSV_FILENAME   "magnetic_field_log.csv"
#define SAMPLE_PERIOD  1

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_sensor_data(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    if (i2c_read_reg16(fd, 0x01, x) < 0) return -1;
    if (i2c_read_reg16(fd, 0x02, y) < 0) return -1;
    if (i2c_read_reg16(fd, 0x03, z) < 0) return -1;
    return 0;
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z);
    fflush(fp);
}

static int file_exists(const char *path)
{
    return access(path, F_OK) == 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                TMAG5273_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    if (!file_exists(CSV_FILENAME)) {
        g_csv_fp = fopen(CSV_FILENAME, "w");
        if (!g_csv_fp) {
            fprintf(stderr, "fopen(%s, w) failed: %s\n",
                    CSV_FILENAME, strerror(errno));
            close(g_i2c_fd);
            g_i2c_fd = -1;
            return EXIT_FAILURE;
        }
        fprintf(g_csv_fp, "timestamp,x,y,z\n");
        fflush(g_csv_fp);
    } else {
        g_csv_fp = fopen(CSV_FILENAME, "a");
        if (!g_csv_fp) {
            fprintf(stderr, "fopen(%s, a) failed: %s\n",
                    CSV_FILENAME, strerror(errno));
            close(g_i2c_fd);
            g_i2c_fd = -1;
            return EXIT_FAILURE;
        }
    }

    printf("TMAG5273 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t x, y, z;
        if (read_sensor_data(g_i2c_fd, &x, &y, &z) == 0) {
            log_data(g_csv_fp, x, y, z);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly...\n");
    if (g_csv_fp) {
        fclose(g_csv_fp);
        g_csv_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

