/*
 * ADXL345 Free-Fall Detector for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADXL345 SDA  -> GPIO2  (physical pin 3,  I2C bus 1)
 *   ADXL345 SCL  -> GPIO3  (physical pin 5,  I2C bus 1)
 *   ADXL345 INT1 -> GPIO17 (physical pin 11, BCM 17)
 *   ADXL345 VCC  -> 3.3 V
 *   ADXL345 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o freefall freefall.c -lgpiod
 *
 * Run:
 *   sudo ./freefall
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- ADXL345 register definitions ---- */
#define ADXL345_ADDR          0x53
#define ADXL345_DEVID         0x00
#define ADXL345_DEVID_VAL     0xE5
#define ADXL345_POWER_CTL     0x2D
#define ADXL345_DATA_FORMAT   0x31
#define ADXL345_DATAX0        0x32
#define ADXL345_INT_ENABLE    0x2E
#define ADXL345_INT_MAP       0x2F
#define ADXL345_INT_SOURCE    0x30
#define ADXL345_THRESH_FF     0x28
#define ADXL345_TIME_FF       0x29

/* ---- Configuration ---- */
#define I2C_BUS               "/dev/i2c-1"
#define GPIO_CHIP             "gpiochip4"   /* BCM GPIO controller on Pi 4 */
#define GPIO_LINE             17            /* BCM 17 = physical pin 11 */
#define LOG_FILE              "freefall_log.csv"
#define POLL_TIMEOUT_MS       1000

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static FILE    *g_log_fp   = NULL;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_line = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (burst reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int adxl345_init(int fd)
{
    uint8_t devid = 0;

    /* --- Verify device identity --- */
    if (i2c_read_reg8(fd, ADXL345_DEVID, &devid) < 0)
        return -1;
    if (devid != ADXL345_DEVID_VAL) {
        fprintf(stderr, "ADXL345 not detected (DEVID=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID_VAL);
        return -1;
    }

    /* --- Standby mode (clear measure bit) before configuring --- */
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x00) < 0)
        return -1;

    /* --- Data format: 4-wire SPI off, full resolution, +/-2g, right-justified --- */
    if (i2c_write_reg8(fd, ADXL345_DATA_FORMAT, 0x08) < 0)
        return -1;

    /* --- Free-fall threshold: 64 mg (0x04 * 16 mg/LSB) --- */
    if (i2c_write_reg8(fd, ADXL345_THRESH_FF, 0x04) < 0)
        return -1;

    /* --- Free-fall time: 10 ms (0x0A * 5 ms/LSB) --- */
    if (i2c_write_reg8(fd, ADXL345_TIME_FF, 0x0A) < 0)
        return -1;

    /* --- Map free-fall interrupt to INT1 --- */
    if (i2c_write_reg8(fd, ADXL345_INT_MAP, 0x00) < 0)
        return -1;

    /* --- Enable free-fall interrupt --- */
    if (i2c_write_reg8(fd, ADXL345_INT_ENABLE, 0x04) < 0)
        return -1;

    /* --- Enter measurement mode --- */
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x08) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, ADXL345_DATAX0, buf, 6) < 0)
        return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_sample(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    struct timespec ts;
    struct tm tm_info;
    char tbuf[32];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld,%d,%d,%d\n", tbuf, ts.tv_nsec / 1000000L, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Disable interrupts and enter standby */
        (void)i2c_write_reg8(g_i2c_fd, ADXL345_INT_ENABLE, 0x00);
        (void)i2c_write_reg8(g_i2c_fd, ADXL345_POWER_CTL, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_line) {
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    struct gpiod_line_event event;
    struct timespec ts = { 0, POLL_TIMEOUT_MS * 1000000L };
    int16_t x, y, z;

    /* --- Signal handling --- */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Initialize sensor --- */
    if (adxl345_init(g_i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip and request INT1 line --- */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        perror("gpiod_chip_open_by_name");
        cleanup();
        return EXIT_FAILURE;
    }

    g_line = gpiod_chip_get_line(g_chip, GPIO_LINE);
    if (!g_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_rising_edge_events(g_line, "adxl345-int1") < 0) {
        perror("gpiod_line_request_rising_edge_events");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen " LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(g_log_fp, "timestamp,x,y,z\n");
    fflush(g_log_fp);

    printf("Free-fall detection started. INT1 on GPIO17. Ctrl+C to exit.\n");

    /* --- Main event loop --- */
    while (g_running) {
        int ret = gpiod_line_event_wait(g_line, &ts);
        if (ret < 0) {
            if (errno == EINTR)
                continue;
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret == 0)
            continue; /* timeout, no event */

        /* Drain all pending events */
        while (gpiod_line_event_read(g_line, &event) == 0) {
            /* Read and log acceleration on each free-fall event */
            if (read_accel(g_i2c_fd, &x, &y, &z) == 0)
                log_sample(g_log_fp, x, y, z);
            else
                fprintf(stderr, "Failed to read acceleration data.\n");
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

