        int ret = gpiod_line_event_wait(g_line, &ts);
        if (ret < 0) {
            if (errno == EINTR)
                continue;
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret == 0)
            continue; /* timeout, no event */

        /* Drain all pending events */
        while (gpiod_line_event_read(g_line, &event) == 0) {
            /* Read and log acceleration on each free-fall event */
            if (read_accel(g_i2c_fd, &x, &y, &z) == 0)
                log_sample(g_log_fp, x, y, z);
            else
                fprintf(stderr, "Failed to read acceleration data.\n");
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

