#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LSM6DSR_ADDR 0x6A
#define WHO_AM_I 0x0F
#define WHO_AM_I_VAL 0x6A
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

#define ACCEL_SENSITIVITY 0.061f
#define GYRO_SENSITIVITY 4.375f
#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f
#define DETECTION_WINDOW 1.0f
#define SAMPLE_PERIOD_US 9615

typedef struct {
    float x, y, z;
} sensor_data_t;

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) return -1;
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val) {
    return i2cWriteByteData(handle, reg, val);
}

static int i2c_read_burst(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) return -1;
    return 0;
}

static int init_lsm6dsr(int handle) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg(handle, WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (0x%02X, expected 0x%02X). Sensor absent or wrong device.\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg(handle, CTRL1_XL, 0x80) < 0) {
        fprintf(stderr, "Error: Failed to configure accelerometer (ODR=104Hz, FS=2g).\n");
        return -1;
    }
    if (i2c_write_reg(handle, CTRL2_G, 0x80) < 0) {
        fprintf(stderr, "Error: Failed to configure gyroscope (ODR=104Hz, FS=250dps).\n");
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, sensor_data_t *data) {
    uint8_t buf[6];
    if (i2c_read_burst(handle, OUTX_L_G, buf, 6) < 0) {
        fprintf(stderr, "Error: Failed to read gyroscope data.\n");
        return -1;
    }
    int16_t gx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t gy = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t gz = (int16_t)((buf[5] << 8) | buf[4]);
    data->x = (float)gx / GYRO_SENSITIVITY;
    data->y = (float)gy / GYRO_SENSITIVITY;
    data->z = (float)gz / GYRO_SENSITIVITY;
    if (i2c_read_burst(handle, OUTX_L_XL, buf, 6) < 0) {
        fprintf(stderr, "Error: Failed to read accelerometer data.\n");
        return -1;
    }
    int16_t ax = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t ay = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t az = (int16_t)((buf[5] << 8) | buf[4]);
    data->x = (float)ax / ACCEL_SENSITIVITY;
    data->y = (float)ay / ACCEL_SENSITIVITY;
    data->z = (float)az / ACCEL_SENSITIVITY;
    return 0;
}

static float calculate_magnitude(sensor_data_t data) {
    return sqrtf(data.x * data.x + data.y * data.y + data.z * data.z);
}

static void log_data(FILE *fp, sensor_data_t accel, sensor_data_t gyro, float magnitude) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
    fprintf(fp, "%.6f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n", timestamp, accel.x, accel.y, accel.z, gyro.x, gyro.y, gyro.z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    int i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X.\n", LSM6DSR_ADDR);
        gpioTerminate();
        return 1;
    }

    if (init_lsm6dsr(i2c_handle) < 0) {
        fprintf(stderr, "Error: LSM6DSR initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open motion_log.txt for writing.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");
    }

    int fall_state = 0;
    struct timespec fall_start_time;
    clock_gettime(CLOCK_REALTIME, &fall_start_time);

    while (running) {
        sensor_data_t accel_data, gyro_data;
        if (read_sensor_data(i2c_handle, &accel_data) < 0) {
            fprintf(stderr, "Error: Sensor read failed, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        float magnitude = calculate_magnitude(accel_data);
        log_data(log_file, accel_data, gyro_data, magnitude);

        if (magnitude < FREEFALL_THRESHOLD) {
            if (fall_state == 0) {
                fall_state = 1;
                clock_gettime(CLOCK_REALTIME, &fall_start_time);
            }
        } else if (magnitude > IMPACT_THRESHOLD) {
            if (fall_state == 1) {
                struct timespec current_time;
                clock_gettime(CLOCK_REALTIME, &current_time);
                double time_diff = (current_time.tv_sec - fall_start_time.tv_sec) + (current_time.tv_nsec - fall_start_time.tv_nsec) / 1e9;
                if (time_diff <= DETECTION_WINDOW) {
                    printf("Impact detected!\n");
                }
                fall_state = 0;
            }
        } else {
            fall_state = 0;
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nCleaning up...\n");
    if (log_file) fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

