#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16266 Register Addresses */
#define ADIS16266_REG_XGYRO_OUT 0x04
#define ADIS16266_REG_YGYRO_OUT 0x06
#define ADIS16266_REG_ZGYRO_OUT 0x08
#define ADIS16266_REG_SMPL_PRD  0x36
#define ADIS16266_REG_SENSIT    0x38
#define ADIS16266_REG_AVG_CNT   0x3A
#define ADIS16266_REG_GLOB_CMD  0x6E
#define ADIS16266_REG_MSC_CTRL  0x68
#define ADIS16266_REG_SMPL_STAT 0x72
#define ADIS16266_REG_DIAG_STAT 0x74
#define ADIS16266_REG_XGYRO_OFF 0x76
#define ADIS16266_REG_YGYRO_OFF 0x78
#define ADIS16266_REG_ZGYRO_OFF 0x7A
#define ADIS16266_REG_ALM_MAG   0x7C
#define ADIS16266_REG_ALM_SMPL  0x7E
#define ADIS16266_REG_ALM_CTRL  0x80
#define ADIS16266_REG_ALM_STAT  0x82
#define ADIS16266_REG_ALM_REG  0x84
#define ADIS16266_REG_ALM_DATA  0x86
#define ADIS16266_REG_XGYRO_OFF 0x76
#define ADIS16266_REG_YGYRO_OFF 0x78
#define ADIS16266_REG_ZGYRO_OFF 0x7A
#define ADIS16266_REG_ALM_MAG   0x7C
#define ADIS16266_REG_ALM_SMPL  0x7E
#define ADIS16266_REG_ALM_CTRL  0x80
#define ADIS16266_REG_ALM_STAT  0x82
#define ADIS16266_REG_ALM_REG  0x84
#define ADIS16266_REG_ALM_DATA  0x86
#define ADIS16266_REG_WHO_AM_I  0x02

#define ADIS16266_WHO_AM_I_VAL  0x4053

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 /* 1 MHz */
#define SPI_FLAGS   0x00000003 /* mode 3: CPOL=1, CPHA=1 */

/* Gyroscope Scale Factor (deg/sec/LSB) */
#define GYRO_SCALE_FACTOR 0.0305f

/* Global variables */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int spi_read_register(uint8_t reg_addr, uint16_t *data);
static int spi_write_register(uint8_t reg_addr, uint16_t data);
static int initialize_adis16266(void);
static int read_gyro_data(float *x, float *y, float *z);
static void log_data(float x, float y, float z);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* Read a 16-bit register from the ADIS16266 */
static int spi_read_register(uint8_t reg_addr, uint16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = (char)(reg_addr | 0x80); /* Set MSB for read */
    tx_buf[1] = 0x00;                    /* Dummy byte */

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error: SPI read transfer failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    *data = ((uint16_t)(uint8_t)rx_buf[0] << 8) | (uint8_t)rx_buf[1];
    return 0;
}

/* Write a 16-bit value to an ADIS16266 register */
static int spi_write_register(uint8_t reg_addr, uint16_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = (char)(reg_addr & 0x7F); /* Clear MSB for write */
    tx_buf[1] = (char)(data & 0xFF);     /* Low byte */

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error: SPI write transfer failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    return 0;
}

/* Initialize the ADIS16266 */
static int initialize_adis16266(void) {
    uint16_t who_am_i = 0;

    /* Verify device identity */
    if (spi_read_register(ADIS16266_REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != ADIS16266_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (expected 0x%04X, got 0x%04X)\n",
                ADIS16266_WHO_AM_I_VAL, who_am_i);
        return -1;
    }

    /* Reset the device */
    if (spi_write_register(ADIS16266_REG_GLOB_CMD, 0x0004) != 0) {
        fprintf(stderr, "Error: Failed to reset device\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms delay for reset */

    /* Configure sample period (0x000A = 10 ms) */
    if (spi_write_register(ADIS16266_REG_SMPL_PRD, 0x000A) != 0) {
        fprintf(stderr, "Error: Failed to set sample period\n");
        return -1;
    }

    /* Configure sensitivity (0x0000 = default) */
    if (spi_write_register(ADIS16266_REG_SENSIT, 0x0000) != 0) {
        fprintf(stderr, "Error: Failed to set sensitivity\n");
        return -1;
    }

    /* Configure averaging count (0x0001 = 1 sample) */
    if (spi_write_register(ADIS16266_REG_AVG_CNT, 0x0001) != 0) {
        fprintf(stderr, "Error: Failed to set averaging count\n");
        return -1;
    }

    return 0;
}

/* Read gyroscope data and convert to degrees per second */
static int read_gyro_data(float *x, float *y, float *z) {
    uint16_t x_raw, y_raw, z_raw;

    if (spi_read_register(ADIS16266_REG_XGYRO_OUT, &x_raw) != 0) return -1;
    if (spi_read_register(ADIS16266_REG_YGYRO_OUT, &y_raw) != 0) return -1;
    if (spi_read_register(ADIS16266_REG_ZGYRO_OUT, &z_raw) != 0) return -1;

    *x = (float)((int16_t)x_raw) * GYRO_SCALE_FACTOR;
    *y = (float)((int16_t)y_raw) * GYRO_SCALE_FACTOR;
    *z = (float)((int16_t)z_raw) * GYRO_SCALE_FACTOR;

    return 0;
}

/* Log data to CSV file */
static void log_data(float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    fprintf(log_file, "%.6f,%.6f,%.6f,%.6f\n", timestamp, x, y, z);
    fflush(log_file);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize ADIS16266 */
    if (initialize_adis16266() != 0) {
        fprintf(stderr, "Error: ADIS16266 initialisation failed\n");
        cleanup();
        return 1;
    }

    /* Open log file once */
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        cleanup();
        return 1;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
        fflush(log_file);
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    float x, y, z;

    /* Main loop */
    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Error: Failed to read gyro data\n");
        }
        gpioDelay(10000); /* 10 ms delay */
    }

    /* Cleanup */
    cleanup();
    return 0;
}

