#define L3G4200D_OUT_X_L    0x28
#define L3G4200D_OUT_X_H    0x29
#define L3G4200D_OUT_Y_L    0x2A
#define L3G4200D_OUT_Y_H    0x2B
#define L3G4200D_OUT_Z_L    0x2C
#define L3G4200D_OUT_Z_H    0x2D

#define L3G4200D_WHO_AM_I_VAL 0xD3
#define L3G4200D_SENSITIVITY  114.285714286  /* mdps/LSB at FS=250 dps */

#define I2C_BUS 1
#define I2C_ADDR 0x69
#define SAMPLE_PERIOD_US 10000  /* 10 ms */
#define MAX_INIT_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_retry(int handle, uint8_t reg, uint8_t val) {
    for (int attempt = 0; attempt < MAX_INIT_RETRIES; attempt++) {
        if (i2cWriteByteData(handle, reg, val) == 0) return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_INIT_RETRIES, strerror(errno));
        gpioDelay(100000); /* 100 ms backoff */
    }
    return -1;
}

static int init_gyroscope(void) {
    int who = i2cReadByteData(i2c_handle, L3G4200D_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I: %s\n", strerror(errno));
        return -1;
    }
    if (who != L3G4200D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, L3G4200D_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: 0x0F -> 100 Hz ODR, all axes enabled, normal mode */
    if (i2c_write_retry(i2c_handle, L3G4200D_CTRL_REG1, 0x0F) != 0) return -1;
    /* CTRL_REG4: 0x80 -> FS = 250 dps, block data update */
    if (i2c_write_retry(i2c_handle, L3G4200D_CTRL_REG4, 0x80) != 0) return -1;

    return 0;
}

static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, L3G4200D_OUT_X_L | 0x80, buf, 6) != 6) {
        fprintf(stderr, "I2C block read failed: %s\n", strerror(errno));
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | (uint8_t)buf[0]);
    *y = (int16_t)((buf[3] << 8) | (uint8_t)buf[2]);
    *z = (int16_t)((buf[5] << 8) | (uint8_t)buf[4]);
    return 0;
}

static void log_data(FILE *fp, double x, double y, double z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(fp, "%ld.%09ld,%.6f,%.6f,%.6f\n",
            (long)ts.tv_sec, ts.tv_nsec, x, y, z);
    fflush(fp);
}

