    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_gyroscope() != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open gyro_log.csv: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int16_t raw_x, raw_y, raw_z;
    while (!terminate) {
        if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
            double x = (double)raw_x / L3G4200D_SENSITIVITY;
            double y = (double)raw_y / L3G4200D_SENSITIVITY;
            double z = (double)raw_z / L3G4200D_SENSITIVITY;
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Read error, continuing...\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

