#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME     "flame_events.log"
#define POLL_INTERVAL_US  500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped line to the log file and flush immediately      */
/* ------------------------------------------------------------------ */
static void log_event(const char *message)
{
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: log file is not open.\n");
        return;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed.\n");
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime() failed.\n");
        return;
    }

    if (fprintf(g_log_file, "%s – %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Read the flame sensor; returns 1 if flame detected (LOW),          */
/* 0 if no flame (HIGH), -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_flame_sensor(void)
{
    int level = gpioRead(FLAME_SENSOR_GPIO);
    if (level == PI_BAD_GPIO) {
        fprintf(stderr, "Error: gpioRead failed for GPIO %d.\n", FLAME_SENSOR_GPIO);
        return -1;
    }
    return (level == 0) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — close log file and terminate pigpio               */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        if (fclose(g_log_file) != 0) {
            fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
        }
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install SIGINT handler for clean Ctrl-C exit ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

