#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x28
#define REG_X_AXIS     0x00
#define REG_Y_AXIS     0x02
#define REG_Z_AXIS     0x04
#define SAMPLE_PERIOD  100000   /* microseconds (100 ms) */
#define LOG_FILE       "vibration_log.csv"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read a 16-bit big-endian axis value from the D7S-0001.
 * Returns 0 on success, -1 on error. */
static int read_axis(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "write(reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "read(reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_sensor(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    if (read_axis(fd, REG_X_AXIS, x) != 0) return -1;
    if (read_axis(fd, REG_Y_AXIS, y) != 0) return -1;
    if (read_axis(fd, REG_Z_AXIS, z) != 0) return -1;
    return 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                D7S_ADDR, strerror(errno));
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* Write header only if file is empty */
    long pos = ftell(fp);
    if (pos == 0) {
        fprintf(fp, "Timestamp,X,Y,Z\n");
        fflush(fp);
    }

    printf("Logging vibration data to %s (Ctrl+C to stop)...\n", LOG_FILE);

    while (g_running) {
        int16_t x, y, z;
        char ts[32];

        if (read_sensor(fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Sensor read failed; skipping sample.\n");
        } else {
            get_timestamp(ts, sizeof(ts));
            fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z);
            fflush(fp);
        }

        usleep(SAMPLE_PERIOD);
    }

    printf("\nExiting cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    if (fd >= 0) close(fd);
    return rc;
}

