#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define HALL_SENSOR_1_GPIO 17
#define HALL_SENSOR_2_GPIO 27
#define LOG_FILE "conveyor_log.txt"
#define POLL_INTERVAL_US 50000  /* 50 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int log_sensor_data(FILE *fp, int gpio1, int gpio2)
{
    struct timespec ts;
    char timestamp[40];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t len = strlen(timestamp);
    snprintf(timestamp + len, sizeof(timestamp) - len, ".%03ld", ts.tv_nsec / 1000000);

    if (fprintf(fp, "%s, GPIO%d: %d, GPIO%d: %d\n",
                timestamp, HALL_SENSOR_1_GPIO, gpio1,
                HALL_SENSOR_2_GPIO, gpio2) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(HALL_SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", HALL_SENSOR_1_GPIO);
        goto cleanup_gpio;
    }
    if (gpioSetMode(HALL_SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", HALL_SENSOR_2_GPIO);
        goto cleanup_gpio;
    }

    /* Enable internal pull-ups so the line reads HIGH when no magnet is present */
    if (gpioSetPullUpDown(HALL_SENSOR_1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", HALL_SENSOR_1_GPIO);
        goto cleanup_gpio;
    }
    if (gpioSetPullUpDown(HALL_SENSOR_2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", HALL_SENSOR_2_GPIO);
        goto cleanup_gpio;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup_gpio;
    }

    printf("Monitoring Hall sensors on GPIO%d and GPIO%d. Press Ctrl+C to exit.\n",
           HALL_SENSOR_1_GPIO, HALL_SENSOR_2_GPIO);

    while (program_running) {
        int gpio1 = gpioRead(HALL_SENSOR_1_GPIO);
        int gpio2 = gpioRead(HALL_SENSOR_2_GPIO);

        if (gpio1 < 0 || gpio2 < 0) {
            fprintf(stderr, "Error reading GPIO pins (GPIO17=%d, GPIO27=%d)\n",
                    gpio1, gpio2);
            break;
        }

        if (log_sensor_data(fp, gpio1, gpio2) != 0) {
            break;
        }

        if (gpio1 == 1 && gpio2 == 1) {
            printf("Conveyor Halt: Both sensors HIGH\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

    if (fp != NULL) {
        if (fclose(fp) != 0) {
            fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        }
    }

cleanup_gpio:
    gpioTerminate();
    return ret;
}

