#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* MMA8452Q I2C address (SA0 tied to GND) */
#define MMA8452Q_ADDR 0x1D

/* MMA8452Q register addresses */
#define MMA8452Q_STATUS   0x00
#define MMA8452Q_OUT_X_MSB 0x01
#define MMA8452Q_OUT_X_LSB 0x02
#define MMA8452Q_OUT_Y_MSB 0x03
#define MMA8452Q_OUT_Y_LSB 0x04
#define MMA8452Q_OUT_Z_MSB 0x05
#define MMA8452Q_OUT_Z_LSB 0x06
#define MMA8452Q_WHO_AM_I  0x0D
#define MMA8452Q_XYZ_DATA_CFG 0x0E
#define MMA8452Q_CTRL_REG1   0x2A

/* Expected device ID */
#define MMA8452Q_ID 0x2A

/* Tilt threshold in degrees */
#define TILT_THRESHOLD 45.0

/* I2C bus device path */
#define I2C_BUS "/dev/i2c-1"

/* Log file path */
#define LOG_FILE "fall_log.txt"

/* Global file descriptors for cleanup */
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    exit(0);
}

/* Write a single byte to an 8-bit register */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a single byte from an 8-bit register */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read multiple bytes starting from an 8-bit register */
static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "Error reading burst from reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Initialize the MMA8452Q accelerometer */
static int init_accelerometer(int fd) {
    uint8_t who_am_i = 0;

    /* Verify device identity */
    if (i2c_read_reg8(fd, MMA8452Q_WHO_AM_I, &who_am_i) < 0) {
        return -1;
    }
    if (who_am_i != MMA8452Q_ID) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who_am_i, MMA8452Q_ID);
        return -1;
    }

    /* Place device in standby mode to allow configuration */
    if (i2c_write_reg8(fd, MMA8452Q_CTRL_REG1, 0x00) < 0) {
        return -1;
    }
    usleep(1000);

    /* Set data rate to 100 Hz (ODR[3:0] = 0x08) */
    if (i2c_write_reg8(fd, MMA8452Q_CTRL_REG1, 0x08) < 0) {
        return -1;
    }

    /* Enable active mode (CTRL_REG1 bit ASLPRATE=0, ACTIVE=1) */
    if (i2c_write_reg8(fd, MMA8452Q_CTRL_REG1, 0x01) < 0) {
        return -1;
    }

    usleep(10000); /* Allow sensor to stabilize */
    return 0;
}

/* Read accelerometer data and return signed 12-bit values */
static int read_accelerometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];

    if (i2c_read_burst(fd, MMA8452Q_OUT_X_MSB, buf, 6) < 0) {
        return -1;
    }

    /* Combine MSB and LSB, then right-shift by 4 to get 12-bit signed value */
    *x = (int16_t)((buf[0] << 8) | buf[1]) >> 4;
    *y = (int16_t)((buf[2] << 8) | buf[3]) >> 4;
    *z = (int16_t)((buf[4] << 8) | buf[5]) >> 4;

    return 0;
}

/* Calculate tilt angle in degrees from accelerometer data */
static double calculate_tilt(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / 4096.0;
    double y_g = (double)y / 4096.0;
    double z_g = (double)z / 4096.0;

    double tilt_x = atan2(x_g, sqrt(y_g * y_g + z_g * z_g)) * 180.0 / M_PI;
    double tilt_y = atan2(y_g, sqrt(x_g * x_g + z_g * z_g)) * 180.0 / M_PI;

    return fmax(fabs(tilt_x), fabs(tilt_y));
}

/* Log a fall event to the log file */
static void log_fall_event(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(g_log_fp, "%s - X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(g_log_fp);
}

int main(void) {
    int16_t x, y, z;
    double tilt;

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    /* Set I2C slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                MMA8452Q_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    /* Initialize accelerometer */
    if (init_accelerometer(g_i2c_fd) < 0) {
        fprintf(stderr, "Error initializing accelerometer\n");
        close(g_i2c_fd);
        return 1;
    }

    /* Open log file once in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("Fall detection started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (1) {
        if (read_accelerometer(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error reading accelerometer data, skipping iteration\n");
            usleep(10000);
            continue;
        }

        tilt = calculate_tilt(x, y, z);

        if (tilt > TILT_THRESHOLD) {
            log_fall_event(x, y, z);
            printf("Fall detected! Tilt: %.2f degrees\n", tilt);
        }

        usleep(10000); /* 10 ms delay (~100 Hz polling) */
    }

    /* Cleanup (unreachable in normal operation, but kept for completeness) */
    fclose(g_log_fp);
    close(g_i2c_fd);
    return 0;
}

