#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* LIS3MDL register addresses */
#define LIS3MDL_WHO_AM_I   0x0F
#define LIS3MDL_CTRL_REG1  0x20
#define LIS3MDL_CTRL_REG2  0x21
#define LIS3MDL_CTRL_REG3  0x22
#define LIS3MDL_CTRL_REG4  0x23
#define LIS3MDL_OUT_X_L    0x28
#define LIS3MDL_OUT_X_H    0x29
#define LIS3MDL_OUT_Y_L    0x2A
#define LIS3MDL_OUT_Y_H    0x2B
#define LIS3MDL_OUT_Z_L    0x2C
#define LIS3MDL_OUT_Z_H    0x2D

#define LIS3MDL_WHO_AM_I_VAL 0x3D

/* ±4 gauss sensitivity: 14.6 mG/LSB = 0.0146 G/LSB */
#define LIS3MDL_SENSITIVITY 0.0146f

/* Metal detection threshold: 800 mG */
#define METAL_THRESHOLD 800.0f

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS "/dev/i2c-1"

/* LIS3MDL I2C address (SA1 tied to GND) */
#define LIS3MDL_ADDR 0x1E

/* Calibration constants (replace with your calibrated values) */
static const float X_OFFSET = 0.0f;
static const float Y_OFFSET = 0.0f;
static const float Z_OFFSET = 0.0f;
static const float X_SCALE  = 1.0f;
static const float Y_SCALE  = 1.0f;
static const float Z_SCALE  = 1.0f;

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_reg8: write");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg8: write");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("i2c_read_reg8: read");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_lis3mdl(int fd)
{
    uint8_t who_am_i = 0;

    if (i2c_read_reg8(fd, LIS3MDL_WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "init_lis3mdl: failed to read WHO_AM_I\n");
        return -1;
    }
    if (who_am_i != LIS3MDL_WHO_AM_I_VAL) {
        fprintf(stderr, "init_lis3mdl: WHO_AM_I mismatch (0x%02X, expected 0x%02X)\n",
                who_am_i, LIS3MDL_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: temp enable | OM ultra-high | data rate 10 Hz */
    if (i2c_write_reg8(fd, LIS3MDL_CTRL_REG1, 0x70) < 0) return -1;
    /* CTRL_REG2: full-scale ±4 gauss */
    if (i2c_write_reg8(fd, LIS3MDL_CTRL_REG2, 0x00) < 0) return -1;
    /* CTRL_REG3: continuous-conversion mode */
    if (i2c_write_reg8(fd, LIS3MDL_CTRL_REG3, 0x00) < 0) return -1;
    /* CTRL_REG4: Z-axis high performance mode */
    if (i2c_write_reg8(fd, LIS3MDL_CTRL_REG4, 0x0C) < 0) return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_magnetometer(int fd, float *x, float *y, float *z)
{
    uint8_t xl, xh, yl, yh, zl, zh;
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_reg8(fd, LIS3MDL_OUT_X_L, &xl) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_OUT_X_H, &xh) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_OUT_Y_L, &yl) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_OUT_Y_H, &yh) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_OUT_Z_L, &zl) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_OUT_Z_H, &zh) < 0) return -1;

    raw_x = (int16_t)((xh << 8) | xl);
    raw_y = (int16_t)((yh << 8) | yl);
    raw_z = (int16_t)((zh << 8) | zl);

    *x = ((float)raw_x - X_OFFSET) * X_SCALE * LIS3MDL_SENSITIVITY;
    *y = ((float)raw_y - Y_OFFSET) * Y_SCALE * LIS3MDL_SENSITIVITY;
    *z = ((float)raw_z - Z_OFFSET) * Z_SCALE * LIS3MDL_SENSITIVITY;

    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x, float y, float z)
{
    fprintf(fp, "%.2f,%.2f,%.2f\n", x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void check_metal_detection(float x, float y, float z)
{
    float magnitude = sqrtf(x * x + y * y + z * z);
    if (magnitude > METAL_THRESHOLD) {
        fprintf(stderr, "METAL DETECTED! Magnitude: %.2f mG\n", magnitude);
    }
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    int init_attempts = 0;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        cleanup();
        return EXIT_FAILURE;
    }

    while (init_attempts < 3) {
        if (init_lis3mdl(g_i2c_fd) == 0) {
            break;
        }
        init_attempts++;
        if (init_attempts < 3) {
            fprintf(stderr, "init_lis3mdl failed, retrying (%d/3)...\n", init_attempts);
            sleep(1);
        }
    }

    if (init_attempts >= 3) {
        fprintf(stderr, "Failed to initialize LIS3MDL after 3 attempts.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen("magnetic_log.txt", "a");
    if (g_log_fp == NULL) {
        perror("fopen(magnetic_log.txt)");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(stderr, "LIS3MDL initialized. Logging to magnetic_log.txt at 10 Hz.\n");

    while (g_running) {
        float x, y, z;

        if (read_magnetometer(g_i2c_fd, &x, &y, &z) == 0) {
            log_data(g_log_fp, x, y, z);
            check_metal_detection(x, y, z);
        } else {
            fprintf(stderr, "Error reading magnetometer data.\n");
        }

        usleep(100000); /* 100 ms -> 10 Hz */
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

