#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADXL354B Register Addresses */
#define ADXL354B_REG_DEVID_AD   0x00
#define ADXL354B_REG_PARTID     0x02
#define ADXL354B_REG_STATUS     0x04
#define ADXL354B_REG_XDATA_H    0x08
#define ADXL354B_REG_XDATA_L    0x09
#define ADXL354B_REG_XDATA_XL   0x0A
#define ADXL354B_REG_YDATA_H    0x0B
#define ADXL354B_REG_YDATA_L    0x0C
#define ADXL354B_REG_YDATA_XL   0x0D
#define ADXL354B_REG_ZDATA_H    0x0E
#define ADXL354B_REG_ZDATA_L    0x0F
#define ADXL354B_REG_ZDATA_XL   0x10
#define ADXL354B_REG_POWER_CTL  0x2D
#define ADXL354B_REG_RESET      0x1F

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 /* 1 MHz */
#define SPI_MODE    0

/* ADXL354B Constants */
#define ADXL354B_PARTID        0xAD
#define ADXL354B_RESET_CMD     0x52
#define ADXL354B_RUN_BIT       0x01
#define ADXL354B_STABLE_BIT    0x01

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int32_t x;
    int32_t y;
    int32_t z;
} accelerometer_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0 };
    int result = spiXfer(spi_handle, tx, rx, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read error on reg 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    char rx[2] = { 0 };
    int result = spiXfer(spi_handle, tx, rx, 2);
    if (result != 2) {
        fprintf(stderr, "SPI write error on reg 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int spi_read_multi(uint8_t reg, uint8_t *buf, int len) {
    char tx[32];
    char rx[32];
    if (len > (int)sizeof(tx) - 1) return -1;
    tx[0] = (char)(reg | 0x80 | 0x40);
    memset(&tx[1], 0, len);
    int result = spiXfer(spi_handle, tx, rx, len + 1);
    if (result != len + 1) {
        fprintf(stderr, "SPI multi-read error on reg 0x%02X: %d\n", reg, result);
        return -1;
    }
    memcpy(buf, &rx[1], len);
    return 0;
}

static int adxl354b_reset(void) {
    if (spi_write_register(ADXL354B_REG_RESET, ADXL354B_RESET_CMD) != 0) return -1;
    gpioDelay(1000); /* 1 ms */
    return 0;
}

static int adxl354b_init(void) {
    uint8_t partid = 0;
    uint8_t status = 0;
    int retries = 0;

    if (adxl354b_reset() != 0) {
        fprintf(stderr, "ADXL354B reset failed.\n");
        return -1;
    }

    /* Clear RUN bit to enter standby */
    if (spi_write_register(ADXL354B_REG_POWER_CTL, 0x00) != 0) return -1;
    gpioDelay(1000);

    /* Wait for STABLE bit to be set */
    do {
        if (spi_read_register(ADXL354B_REG_STATUS, &status) != 0) return -1;
        gpioDelay(1000);
        if (++retries > 10) {
            fprintf(stderr, "ADXL354B not stable after reset.\n");
            return -1;
        }
    } while ((status & ADXL354B_STABLE_BIT) == 0);

    /* Read PARTID to verify sensor presence */
    if (spi_read_register(ADXL354B_REG_PARTID, &partid) != 0) return -1;
    if (partid != ADXL354B_PARTID) {
        fprintf(stderr, "ADXL354B PARTID mismatch: 0x%02X (expected 0x%02X)\n", partid, ADXL354B_PARTID);
        return -1;
    }

    /* Set RUN bit to start measurement */
    if (spi_write_register(ADXL354B_REG_POWER_CTL, ADXL354B_RUN_BIT) != 0) return -1;
    gpioDelay(1000);

    return 0;
}

static int read_accelerometer_data(accelerometer_data_t *data) {
    uint8_t buf[6];
    if (spi_read_multi(ADXL354B_REG_XDATA_H, buf, 6) != 0) return -1;

    int32_t x = ((int32_t)buf[0] << 8) | buf[1];
    int32_t y = ((int32_t)buf[2] << 8) | buf[3];
    int32_t z = ((int32_t)buf[4] << 8) | buf[5];

    /* Sign-extend 16-bit to 20-bit (2's complement) */
    if (x & 0x8000) x |= 0xFFFF0000;
    if (y & 0x8000) y |= 0xFFFF0000;
    if (z & 0x8000) z |= 0xFFFF0000;

    data->x = x;
    data->y = y;
    data->z = z;
    return 0;
}

static void log_data(accelerometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, data.x, data.y, data.z);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (adxl354b_init() != 0) {
        fprintf(stderr, "ADXL354B initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    accelerometer_data_t data;
    int retry_count = 0;

    while (!terminate) {
        if (read_accelerometer_data(&data) == 0) {
            log_data(data);
            retry_count = 0;
        } else {
            fprintf(stderr, "Error reading accelerometer data. Retry %d\n", retry_count + 1);
            retry_count++;
            if (retry_count > 5) {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                break;
            }
            gpioDelay(10000); /* 10 ms backoff */
            continue;
        }
        gpioDelay(100000); /* 100 ms */
    }

    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

