    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    accelerometer_data_t data;
    int retry_count = 0;

    while (!terminate) {
        if (read_accelerometer_data(&data) == 0) {
            log_data(data);
            retry_count = 0;
        } else {
            fprintf(stderr, "Error reading accelerometer data. Retry %d\n", retry_count + 1);
            retry_count++;
            if (retry_count > 5) {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                break;
            }
            gpioDelay(10000); /* 10 ms backoff */
            continue;
        }
        gpioDelay(100000); /* 100 ms */
    }

    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

