#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ADIS16362 Register Addresses */
#define ADIS16362_REG_XGYRO_OUT  0x04
#define ADIS16362_REG_YGYRO_OUT  0x06
#define ADIS16362_REG_ZGYRO_OUT  0x08
#define ADIS16362_REG_XACCEL_OUT 0x0A
#define ADIS16362_REG_YACCEL_OUT 0x0C
#define ADIS16362_REG_ZACCEL_OUT 0x0E

/* Scaling factors */
#define GYRO_SCALE  0.05f   /* deg/sec per LSB */
#define ACCEL_SCALE 0.0025f /* g per LSB */

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_BAUD    1000000 /* 1 MHz */
#define SPI_FLAGS   0x00000003 /* Mode 3: active-high clock, sampled on trailing edge */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x_gyro;
    float y_gyro;
    float z_gyro;
    float x_accel;
    float y_accel;
    float z_accel;
} imu_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/*
 * Read a 16-bit register from the ADIS16362.
 * The ADIS16362 SPI protocol requires a 16-bit transfer for each read:
 *   Transfer 1: send (reg | 0x80) then dummy byte; receive dummy.
 *   Transfer 2: send dummy then dummy; receive data.
 * The two transfers are back-to-back with no intervening CS release.
 */
static int read_register(uint8_t reg, int16_t *out) {
    char tx1[2] = { (char)(reg | 0x80), 0x00 };
    char rx1[2] = { 0, 0 };
    char tx2[2] = { 0x00, 0x00 };
    char rx2[2] = { 0, 0 };

    if (spiXfer(spi_handle, tx1, rx1, 2) != 2) {
        fprintf(stderr, "SPI transfer 1 failed for reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (spiXfer(spi_handle, tx2, rx2, 2) != 2) {
        fprintf(stderr, "SPI transfer 2 failed for reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)(((uint8_t)rx2[0] << 8) | (uint8_t)rx2[1]);
    return 0;
}

static int read_imu_data(imu_data_t *data) {
    int16_t raw;

    if (read_register(ADIS16362_REG_XGYRO_OUT, &raw) != 0) return -1;
    data->x_gyro = (float)raw * GYRO_SCALE;

    if (read_register(ADIS16362_REG_YGYRO_OUT, &raw) != 0) return -1;
    data->y_gyro = (float)raw * GYRO_SCALE;

    if (read_register(ADIS16362_REG_ZGYRO_OUT, &raw) != 0) return -1;
    data->z_gyro = (float)raw * GYRO_SCALE;

    if (read_register(ADIS16362_REG_XACCEL_OUT, &raw) != 0) return -1;
    data->x_accel = (float)raw * ACCEL_SCALE;

    if (read_register(ADIS16362_REG_YACCEL_OUT, &raw) != 0) return -1;
    data->y_accel = (float)raw * ACCEL_SCALE;

    if (read_register(ADIS16362_REG_ZACCEL_OUT, &raw) != 0) return -1;
    data->z_accel = (float)raw * ACCEL_SCALE;

    return 0;
}

static int log_data(const imu_data_t *data) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }
    if (fprintf(log_file, "%ld.%09ld,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
                (long)ts.tv_sec, ts.tv_nsec,
                data->x_gyro, data->y_gyro, data->z_gyro,
                data->x_accel, data->y_accel, data->z_accel) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open imu_log.csv: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    if (fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n") < 0) {
        fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Failed to flush CSV header: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    imu_data_t imu_data;
    int consecutive_errors = 0;

    while (!terminate) {
        if (read_imu_data(&imu_data) == 0) {
            consecutive_errors = 0;
            if (log_data(&imu_data) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "IMU read failed (consecutive: %d)\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive errors; aborting.\n");
                break;
            }
        }
        gpioDelay(10000); /* 10 ms delay (~100 Hz) */
    }

    cleanup();
    return EXIT_SUCCESS;
}

