#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip4"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_SEC 1
#define PARKING_DURATION_SEC 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_timestamped(const char *msg)
{
    time_t rawtime;
    struct tm timeinfo;
    char ts[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &timeinfo);
        printf("[%s] %s\n", ts, msg);
    } else {
        printf("[unknown] %s\n", msg);
    }
    fflush(stdout);
}

static void simulate_parking(void)
{
    log_timestamped("Self-parking sequence started");
    sleep(PARKING_DURATION_SEC);
    log_timestamped("Self-parking sequence completed");
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line, "e18-d80nk-obstacle") < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    log_timestamped("Obstacle detection system started");

    while (g_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Failed to read line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
            goto cleanup;
        }

        if (val == 0) {
            simulate_parking();
        }

        sleep(POLL_INTERVAL_SEC);
    }

    log_timestamped("Obstacle detection system stopped");
    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

