/*
 * KY-032 IR obstacle-avoidance sensor poller for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   Sensor 1  -> GPIO17 (physical pin 11)
 *   Sensor 2  -> GPIO27 (physical pin 13)
 *   VCC       -> 3.3 V
 *   GND       -> GND
 *
 * The KY-032 output is active-low: 0 = obstacle detected, 1 = path clear.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o ky032_poll ky032_poll.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_PIN_1      17
#define GPIO_PIN_2      27
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r");
        return;
    }
    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    printf("[%s] ", buf);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (line1 == NULL) {
        perror("gpiod_chip_get_line(GPIO_PIN_1)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (line2 == NULL) {
        perror("gpiod_chip_get_line(GPIO_PIN_2)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line1, "ky032_poll") < 0) {
        perror("gpiod_line_request_input(line1)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line2, "ky032_poll") < 0) {
        perror("gpiod_line_request_input(line2)");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("KY-032 obstacle-avoidance sensor poller started.\n");
