    if (line2 == NULL) {
        perror("gpiod_chip_get_line(GPIO_PIN_2)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line1, "ky032_poll") < 0) {
        perror("gpiod_line_request_input(line1)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line2, "ky032_poll") < 0) {
        perror("gpiod_line_request_input(line2)");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("KY-032 obstacle-avoidance sensor poller started.\n");
    printf("  Sensor 1: GPIO%d\n  Sensor 2: GPIO%d\n  Poll interval: %d ms\n",
           GPIO_PIN_1, GPIO_PIN_2, POLL_INTERVAL_MS);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    int ret_code = EXIT_SUCCESS;

    while (g_running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);

        if (val1 < 0 || val2 < 0) {
            print_timestamp();
            fprintf(stderr, "Error reading GPIO lines (val1=%d, val2=%d): %s\n",
                    val1, val2, strerror(errno));
            ret_code = EXIT_FAILURE;
            break;
        }

        print_timestamp();
        printf("Sensor 1 (GPIO%d): %s | Sensor 2 (GPIO%d): %s\n",
               GPIO_PIN_1,
               (val1 == 0) ? "OBSTACLE DETECTED" : "Path clear",
               GPIO_PIN_2,
               (val2 == 0) ? "OBSTACLE DETECTED" : "Path clear");
        fflush(stdout);

        struct timespec ts = { 0, POLL_INTERVAL_MS * 1000000L };
        nanosleep(&ts, NULL);
    }

    printf("\nShutting down...\n");
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return ret_code;
}

