/*
 * ADIS16266 Gyroscope Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16266 CS  -> GPIO8  (SPI0 CE0, /dev/spidev0.0)
 *   ADIS16266 SCLK-> GPIO11 (SPI0 SCLK)
 *   ADIS16266 DOUT-> GPIO9  (SPI0 MISO)
 *   ADIS16266 DIN -> GPIO10 (SPI0 MOSI)
 *   ADIS16266 VIO -> 3.3 V
 *   ADIS16266 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o adis16266_gyro adis16266_gyro.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8
#define SPI_DELAY_US    0

#define GYRO_SCALE      0.02f      /* deg/sec per LSB */
#define SAMPLE_PERIOD_MS 100

/* ADIS16266 Register Addresses (8-bit, MSB-first) */
#define REG_XGYRO_OUT   0x04
#define REG_YGYRO_OUT   0x06
#define REG_ZGYRO_OUT   0x08
#define REG_STATUS      0x02

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int spi_xfer(int fd, const uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = SPI_DELAY_US;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16266.
 * Protocol: send (reg | 0x80) then read 2 bytes in a second transfer. */
static int read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0, 0 };

    if (spi_xfer(fd, tx, rx, sizeof(tx)) < 0)
        return -1;

    *out = (int16_t)((rx[0] << 8) | rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_spi(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/* ------------------------------------------------------------------ */
static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000U,
        .tv_nsec = (long)(ms % 1000U) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_spi_fd = init_spi();
    if (g_spi_fd < 0)
        return EXIT_FAILURE;

    printf("ADIS16266 Gyroscope Reader started on %s\n", SPI_DEVICE);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t x_raw = 0, y_raw = 0, z_raw = 0;

        if (read_reg16(g_spi_fd, REG_XGYRO_OUT, &x_raw) < 0 ||
            read_reg16(g_spi_fd, REG_YGYRO_OUT, &y_raw) < 0 ||
            read_reg16(g_spi_fd, REG_ZGYRO_OUT, &z_raw) < 0) {
            fprintf(stderr, "SPI read error — continuing.\n");
            sleep_ms(SAMPLE_PERIOD_MS);
            continue;
        }

        float x_rate = (float)x_raw * GYRO_SCALE;
        float y_rate = (float)y_raw * GYRO_SCALE;
        float z_rate = (float)z_raw * GYRO_SCALE;

        printf("X: %+.2f deg/s  Y: %+.2f deg/s  Z: %+.2f deg/s\n",
               x_rate, y_rate, z_rate);

        sleep_ms(SAMPLE_PERIOD_MS);
    }

    printf("\nShutting down...\n");
    if (g_spi_fd >= 0)
        close(g_spi_fd);
    return EXIT_SUCCESS;
}

