#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C address (SA0 tied to GND) */
#define LSM6DSR_ADDR 0x6A

/* LSM6DSR register addresses */
#define LSM6DSR_WHO_AM_I   0x0F
#define LSM6DSR_CTRL1_XL   0x10
#define LSM6DSR_CTRL2_G    0x11
#define LSM6DSR_OUTX_L_G   0x22
#define LSM6DSR_OUTX_L_XL  0x28

/* Expected chip ID */
#define LSM6DSR_WHO_AM_I_VAL 0x6A

/* Scaling factors for default ranges */
#define ACCEL_SCALE 0.000061f  /* 2g range, 0.061 mg/LSB */
#define GYRO_SCALE  0.000070f  /* 245 dps range, 0.070 dps/LSB */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read failed at reg 0x%02X (rc=%d, expected %u)\n",
                reg, rc, len);
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed at reg 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    return 0;
}

static int16_t combine_le(const uint8_t *p)
{
    return (int16_t)((uint16_t)p[0] | ((uint16_t)p[1] << 8));
}

static int init_lsm6dsr(int handle)
{
    uint8_t who_am_i = 0;

    if (i2c_read_block(handle, LSM6DSR_WHO_AM_I, &who_am_i, 1) != 0)
        return -1;

    if (who_am_i != LSM6DSR_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, LSM6DSR_WHO_AM_I_VAL);
        return -1;
    }

    /* Accelerometer: 12.5 Hz, 2g range, anti-aliasing 408 Hz */
    if (i2c_write_byte(handle, LSM6DSR_CTRL1_XL, 0x40) != 0)
        return -1;

    /* Gyroscope: 12.5 Hz, 245 dps range */
    if (i2c_write_byte(handle, LSM6DSR_CTRL2_G, 0x40) != 0)
        return -1;

    return 0;
}

static int read_accel(int handle, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_block(handle, LSM6DSR_OUTX_L_XL, buf, 6) != 0)
        return -1;
    *x = combine_le(&buf[0]) * ACCEL_SCALE;
    *y = combine_le(&buf[2]) * ACCEL_SCALE;
    *z = combine_le(&buf[4]) * ACCEL_SCALE;
    return 0;
}

static int read_gyro(int handle, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_block(handle, LSM6DSR_OUTX_L_G, buf, 6) != 0)
        return -1;
    *x = combine_le(&buf[0]) * GYRO_SCALE;
    *y = combine_le(&buf[2]) * GYRO_SCALE;
    *z = combine_le(&buf[4]) * GYRO_SCALE;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (rc=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lsm6dsr(g_i2c_handle) != 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float ax, ay, az, gx, gy, gz;

        if (read_accel(g_i2c_handle, &ax, &ay, &az) != 0 ||
            read_gyro(g_i2c_handle, &gx, &gy, &gz) != 0) {
            fprintf(stderr, "Sensor read error\n");
            break;
        }

        printf("Accel: X=%.3f g, Y=%.3f g, Z=%.3f g, "
               "Gyro: X=%.3f dps, Y=%.3f dps, Z=%.3f dps\n",
               ax, ay, az, gx, gy, gz);
        fflush(stdout);

        /* 100 ms delay; gpioDelay returns the elapsed microseconds */
        gpioDelay(100000);
    }

    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

