/*
 * Raspberry Pi 4 Model B – FXOS8700 I2C reader
 *
 * Wiring:
 *   FXOS8700 SDA  -> GPIO2 (BCM 2,  I2C bus 1 SDA)
 *   FXOS8700 SCL  -> GPIO3 (BCM 3,  I2C bus 1 SCL)
 *   FXOS8700 VDD  -> 3.3 V
 *   FXOS8700 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o fxos8700 fxos8700.c -lpigpio -lrt
 * Run:    sudo ./fxos8700
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- FXOS8700 register map (verified against NXP datasheet) ---- */
#define FXOS8700_I2C_ADDR      0x28    /* SA0 tied to GND on Adafruit breakout */
#define FXOS8700_REG_STATUS    0x00
#define FXOS8700_REG_OUT_X_MSB 0x01    /* accel X MSB through 0x05, mag 0x06-0x0B */
#define FXOS8700_REG_M_CTRL    0x0B
#define FXOS8700_REG_XYZ_DATA_CFG 0x0E
#define FXOS8700_REG_CTRL_REG1 0x2A
#define FXOS8700_REG_WHO_AM_I  0x0D

#define FXOS8700_WHO_AM_I_VAL  0xC7
#define FXOS8700_CTRL_REG1_RST 0x80
#define FXOS8700_CTRL_REG1_MODE 0x01   /* bit 0: ACTIVE = 1, STANDBY = 0 */

#define I2C_BUS              1
#define SAMPLE_PERIOD_US     100000   /* 100 ms */
#define MAX_RETRIES          3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
static int i2c_read_block_retry(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
        if (rc == (int)len)
            return 0;
        fprintf(stderr, "I2C block read failed (reg 0x%02X, attempt %d/%d): rc=%d\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        gpioDelay(10000); /* 10 ms back-off */
    }
    return -1;
}

/* ------------------------------------------------------------------ */
static int fxos8700_init(int handle)
{
    /* --- Reset --- */
    if (i2cWriteByteData(handle, FXOS8700_REG_CTRL_REG1,
                         FXOS8700_CTRL_REG1_RST) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG1 (reset)\n");
        return -1;
    }
    gpioDelay(2000); /* 2 ms settle after reset */

    /* --- Verify device identity --- */
    int who = i2cReadByteData(handle, FXOS8700_REG_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* --- Configure accelerometer range: +/-2g (0x00) --- */
    if (i2cWriteByteData(handle, FXOS8700_REG_XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Failed to write XYZ_DATA_CFG\n");
        return -1;
    }

    /* --- Magnetometer: hybrid auto-increment mode (0x00) --- */
    if (i2cWriteByteData(handle, FXOS8700_REG_M_CTRL, 0x00) < 0) {
        fprintf(stderr, "Failed to write M_CTRL\n");
        return -1;
    }

    /* --- Standby -> Active --- */
    if (i2cWriteByteData(handle, FXOS8700_REG_CTRL_REG1,
                         FXOS8700_CTRL_REG1_MODE) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG1 (active)\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int fxos8700_read(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                         int16_t *mx, int16_t *my, int16_t *mz)
{
    uint8_t buf[12];

    if (i2c_read_block_retry(handle, FXOS8700_REG_OUT_X_MSB, buf, sizeof(buf)) < 0)
        return -1;

    /* Accelerometer: 14-bit left-aligned, 14-bit left-aligned */
    *ax = (int16_t)(((buf[0] << 8) | buf[1]) >> 2);
    *ay = (int16_t)(((buf[2] << 8) | buf[3]) >> 2);
    *az = (int16_t)(((buf[4] << 8) | buf[5]) >> 2);

    /* Magnetometer: 16-bit */
    *mx = (int16_t)((buf[6]  << 8) | buf[7]);
    *my = (int16_t)((buf[8]  << 8) | buf[9]);
    *mz = (int16_t)((buf[10] << 8) | buf[11]);

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, FXOS8700_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed on bus %d addr 0x%02X: %d\n",
                I2C_BUS, FXOS8700_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fxos8700_init(g_i2c_handle) < 0) {
        fprintf(stderr, "FXOS8700 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("FXOS8700 ready. Sampling every 100 ms (Ctrl-C to stop).\n");

    while (g_running) {
        int16_t ax, ay, az, mx, my, mz;

        if (fxos8700_read(g_i2c_handle, &ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  Mag: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

