#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define ADXL345_I2C_ADDR 0x53
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_DATA_FORMAT 0x31
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

int adxl345_init(int fd) {
    if (i2c_write_byte(fd, ADXL345_REG_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error: Could not reset ADXL345 (standby).\n");
        return -1;
    }
    if (i2c_write_byte(fd, ADXL345_REG_BW_RATE, 0x0A) < 0) {
        fprintf(stderr, "Error: Could not set ADXL345 data rate.\n");
        return -1;
    }
    if (i2c_write_byte(fd, ADXL345_REG_DATA_FORMAT, 0x08) < 0) {
        fprintf(stderr, "Error: Could not set ADXL345 data format.\n");
        return -1;
    }
    if (i2c_write_byte(fd, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Could not set ADXL345 to measure mode.\n");
        return -1;
    }
    return 0;
}

int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, ADXL345_REG_DATAX0, buf, 6) < 0) {
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / 256.0;
    double y_g = (double)y / 256.0;
    double z_g = (double)z / 256.0;
    double tilt = atan2(y_g, sqrt(x_g * x_g + z_g * z_g)) * 180.0 / M_PI;
    return tilt;
}

void log_tilt_event(double tilt_angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Tilt angle: %.2f degrees\n", s, tilt_angle);
    fclose(fp);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C bus %s\n", I2C_BUS);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_I2C_ADDR) < 0) {
        fprintf(stderr, "Error: Could not acquire I2C bus access/talk to slave 0x%02X\n", ADXL345_I2C_ADDR);
        close(i2c_fd);
        return 1;
    }

    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "Error: ADXL345 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("Tilt monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t x, y, z;
        if (read_acceleration(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error: Failed to read acceleration data.\n");
            usleep(100000);
            continue;
        }

        double tilt_angle = calculate_tilt_angle(x, y, z);

        if (fabs(tilt_angle) > TILT_THRESHOLD) {
            log_tilt_event(tilt_angle);
        }

        usleep(100000);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_fd >= 0) {
        i2c_write_byte(i2c_fd, ADXL345_REG_POWER_CTL, 0x00);
        close(i2c_fd);
    }
    return 0;
}

