#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SOUND_SENSOR_GPIO 17
#define SAMPLE_INTERVAL_US 1000
#define WINDOW_DURATION_S 5
#define PAUSE_BETWEEN_WINDOWS_S 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int parse_threshold(const char *arg, int *out) {
    char *endptr = NULL;
    errno = 0;
    long val = strtol(arg, &endptr, 10);
    if (errno != 0 || endptr == arg || *endptr != '\0' || val <= 0 || val > 1000000) {
        return -1;
    }
    *out = (int)val;
    return 0;
}

static void print_timestamp(void) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "[time-error] ");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "[localtime-error] ");
        return;
    }
    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[strftime-error] ");
        return;
    }
    printf("[%s] ", buf);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold_high_readings>\n", argv[0]);
        fprintf(stderr, "  threshold must be a positive integer\n");
        return EXIT_FAILURE;
    }

    int threshold = 0;
    if (parse_threshold(argv[1], &threshold) != 0) {
        fprintf(stderr, "Error: threshold must be a positive integer (1-1000000)\n");
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO%d\n", SOUND_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring KY-038 sound sensor on GPIO%d (threshold=%d)\n", SOUND_SENSOR_GPIO, threshold);
    printf("Sampling every %d ms over %d s windows, pausing %d s between windows.\n",
           SAMPLE_INTERVAL_US / 1000, WINDOW_DURATION_S, PAUSE_BETWEEN_WINDOWS_S);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int high_count = 0;
        time_t window_start = time(NULL);
        if (window_start == (time_t)-1) {
            fprintf(stderr, "Warning: time() failed; starting window without timestamp\n");
        }

        while (g_running) {
            time_t now = time(NULL);
            if (now == (time_t)-1) {
                fprintf(stderr, "Warning: time() failed; aborting window\n");
                break;
            }
            if (now - window_start >= WINDOW_DURATION_S) {
                break;
            }

            int level = gpioRead(SOUND_SENSOR_GPIO);
            if (level < 0) {
                fprintf(stderr, "Error: gpioRead failed on GPIO%d\n", SOUND_SENSOR_GPIO);
                break;
            }
            if (level == 1) {
                high_count++;
            }

            gpioDelay(SAMPLE_INTERVAL_US);
        }

        if (!g_running) {
            break;
        }

        print_timestamp();
        if (high_count > threshold) {
            printf("ALERT: %d high readings (threshold=%d)\n", high_count, threshold);
        } else {
            printf("Status: %d high readings (threshold=%d)\n", high_count, threshold);
        }
        fflush(stdout);

        if (g_running) {
            sleep(PAUSE_BETWEEN_WINDOWS_S);
        }
    }

    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

