                CODE_MIN, CODE_MAX);
        return -1;
    }

    return code;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_access(int code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time");
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%06d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, code);

    if (fclose(fp) != 0) {
        perror("fclose(" LOG_FILE ")");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Door control                                                        */
/* ------------------------------------------------------------------ */
static int unlock_door(struct gpiod_line *line, const char *label)
{
    printf("Unlocking %s...\n", label);

    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value(HIGH)");
        return -1;
    }

    /* Sleep in 1 s increments so we can exit promptly on signal */
    for (int i = 0; i < UNLOCK_DURATION && g_running; i++) {
        sleep(1);
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value(LOW)");
        return -1;
    }

    printf("%s locked.\n", label);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(struct gpiod_chip *chip,
                    struct gpiod_line *line_a,
                    struct gpiod_line *line_b)
{
    /* Ensure doors are locked before releasing resources */
    if (line_a) gpiod_line_set_value(line_a, 0);
    if (line_b) gpiod_line_set_value(line_b, 0);

    if (line_a) gpiod_line_release(line_a);
    if (line_b) gpiod_line_release(line_b);
    if (chip)   gpiod_chip_close(chip);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_a = NULL;
    struct gpiod_line *line_b = NULL;
    int ret = EXIT_FAILURE;

    srand((unsigned int)time(NULL));

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(gpiochip4)");
        return EXIT_FAILURE;
    }

    line_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (line_a == NULL) {
        perror("gpiod_chip_get_line(DOOR_A_PIN)");
        goto cleanup;
    }

    line_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (line_b == NULL) {
        perror("gpiod_chip_get_line(DOOR_B_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line_a, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(line_a)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line_b, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(line_b)");
        goto cleanup;
    }

    printf("Door access control system started.\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int generated_code = generate_code();
        printf("Generated code: %06d\n", generated_code);

        int user_code = get_user_input();
        if (user_code == -1) {
            if (!g_running) break;
            continue;
        }

        if (user_code == generated_code) {
            printf("Access granted!\n");

            if (unlock_door(line_a, "Door A") != 0) {
                fprintf(stderr, "Failed to unlock Door A.\n");
            }
            if (unlock_door(line_b, "Door B") != 0) {
                fprintf(stderr, "Failed to unlock Door B.\n");
            }

            if (log_access(generated_code) != 0) {
                fprintf(stderr, "Failed to log access.\n");
            }
        } else {
            printf("Access denied.\n");
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    cleanup(chip, line_a, line_b);
    printf("Exiting.\n");
    return ret;
}

