#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <netinet/in.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPR121_ADDR    0x5A
#define PWM_PIN        18
#define PORT           12345
#define LOG_FILE       "frequency_log.txt"
#define SAMPLE_US      20000
#define PLAYBACK_SEC   5
#define SECRET         "MySecretKey"

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR           0x5E
#define MPR121_CONFIG1       0x5B
#define MPR121_CONFIG2       0x5C
#define MPR121_MHDR          0x2B
#define MPR121_NHDR          0x2C
#define MPR121_NCLR          0x2D
#define MPR121_FDLR          0x2E
#define MPR121_MHDF          0x2F
#define MPR121_NHDF          0x30
#define MPR121_NCLF          0x31
#define MPR121_FDLF          0x32
#define MPR121_NHDT          0x33
#define MPR121_NCLT          0x34
#define MPR121_FDLT          0x35

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int server_fd = -1;
static int client_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    if (i2c_write_reg(MPR121_ECR, 0x00) < 0) return -1;
    gpioDelay(1000);

    if (i2c_write_reg(MPR121_MHDR, 0x01) < 0) return -1;
    if (i2c_write_reg(MPR121_NHDR, 0x01) < 0) return -1;
    if (i2c_write_reg(MPR121_NCLR, 0x0E) < 0) return -1;
    if (i2c_write_reg(MPR121_FDLR, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_MHDF, 0x01) < 0) return -1;
    if (i2c_write_reg(MPR121_NHDF, 0x05) < 0) return -1;
    if (i2c_write_reg(MPR121_NCLF, 0x01) < 0) return -1;
    if (i2c_write_reg(MPR121_FDLF, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_NHDT, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_NCLT, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_FDLT, 0x00) < 0) return -1;

    if (i2c_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (i2c_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;

    if (i2c_write_reg(MPR121_ECR, 0x8F) < 0) return -1;
    gpioDelay(1000);
    return 0;
}

static int mpr121_read_touch(uint16_t *touch) {
    uint8_t lo, hi;
    if (i2c_read_reg(MPR121_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (i2c_read_reg(MPR121_TOUCHSTATUS_H, &hi) < 0) return -1;
    *touch = ((uint16_t)hi << 8) | lo;
    return 0;
}

static int calculate_frequency(uint16_t touch_data) {
    int num_touches = 0;
    for (int i = 0; i < 12; i++) {
        if (touch_data & (1 << i)) num_touches++;
    }
    if (num_touches == 0) return 0;
    return (int)(440.0 * pow(2.0, (num_touches - 1.0) / 12.0));
}

static void play_tone(int frequency) {
    if (frequency > 0) {
        if (gpioHardwarePWM(PWM_PIN, frequency, 500000) < 0) {
            fprintf(stderr, "Failed to start PWM on GPIO%d: %s\n", PWM_PIN, pigpio_error(gpioGetMode(PWM_PIN)));
            return;
        }
    }
    gpioDelay(PLAYBACK_SEC * 1000000);
    gpioHardwarePWM(PWM_PIN, 0, 0);
}

static void log_frequency(int frequency) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Frequency: %d Hz\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, frequency);
    fclose(fp);
}

static int authenticate_message(const char *message) {
    if (strncmp(message, "MOTION_DETECTED:", 16) != 0) return 0;
    const char *key_start = strstr(message, SECRET);
    if (!key_start) return 0;
    if (key_start != message + 16) return 0;
    return 1;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        i2c_write_reg(MPR121_ECR, 0x00);
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    gpioHardwarePWM(PWM_PIN, 0, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access to 0x%02X: %s\n", MPR121_ADDR, strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        fprintf(stderr, "Socket creation failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        fprintf(stderr, "setsockopt failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        fprintf(stderr, "Bind failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        fprintf(stderr, "Listen failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Accept failed: %s\n", strerror(errno));
            break;
        }

        char buffer[1024] = {0};
        ssize_t bytes = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes > 0) {
            buffer[bytes] = '\0';
            printf("Received: %s\n", buffer);

            if (authenticate_message(buffer)) {
                uint16_t touch_data;
                if (mpr121_read_touch(&touch_data) == 0) {
                    int frequency = calculate_frequency(touch_data);
                    printf("Playing frequency: %d Hz\n", frequency);
                    play_tone(frequency);
                    log_frequency(frequency);
                } else {
                    fprintf(stderr, "Failed to read touch data\n");
                }
            } else {
                fprintf(stderr, "Authentication failed\n");
            }
        } else if (bytes < 0) {
            fprintf(stderr, "Receive failed: %s\n", strerror(errno));
        }

        close(client_fd);
        client_fd = -1;
    }

    cleanup();
    return 0;
}

