#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* LSM303DLHC I2C addresses */
#define LSM303_ADDRESS_MAG  0x1E

/* Magnetometer register addresses */
#define LSM303_REGISTER_MAG_MR_REG_M  0x02
#define LSM303_REGISTER_MAG_OUT_X_H_M 0x08

/* GPIO pin for LED (BCM numbering) */
#define LED_PIN 17

/* I2C bus device path on Raspberry Pi Zero W */
#define I2C_BUS_DEVICE "/dev/i2c-1"

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an 8-bit register                            */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read N bytes starting at an 8-bit register                          */
/* ------------------------------------------------------------------ */
static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the LSM303DLHC magnetometer                              */
/* ------------------------------------------------------------------ */
static int init_magnetometer(int fd)
{
    /* Continuous-conversion mode, temperature sensor enabled */
    if (i2c_write_reg8(fd, LSM303_REGISTER_MAG_MR_REG_M, 0x00) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read magnetometer data and return Z-axis magnitude                  */
/* ------------------------------------------------------------------ */
static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];

    if (i2c_read_block(fd, LSM303_REGISTER_MAG_OUT_X_H_M, buf, 6) != 0)
        return -1;

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Map a signed 16-bit value to a 0–255 brightness level               */
/* ------------------------------------------------------------------ */
static int map_to_brightness(int16_t value)
{
    int abs_val = abs(value);
    if (abs_val > 32767) abs_val = 32767;

    /* Scale 0–32767 to 0–255 */
    int brightness = (abs_val * 255) / 32767;
    if (brightness < 0)   brightness = 0;
    if (brightness > 255) brightness = 255;
    return brightness;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — stops PWM, closes I2C, closes log file             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* gpioTerminate is safe to call even if gpioInitialise failed */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio initialisation ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen("magnetometer_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Warning: could not open log file: %s\n",
                strerror(errno));
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS_DEVICE, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n",
                I2C_BUS_DEVICE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Set slave address ---- */
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_ADDRESS_MAG) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                LSM303_ADDRESS_MAG, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialise magnetometer ---- */
    if (init_magnetometer(g_i2c_fd) != 0) {
        fprintf(stderr, "Magnetometer initialisation failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure LED pin for hardware PWM ---- */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioPWM(LED_PIN, 0);  /* start with LED off */

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fprintf(stderr, "Magnetometer sampling started. Press Ctrl+C to exit.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int16_t x, y, z;

        if (read_magnetometer(g_i2c_fd, &x, &y, &z) == 0) {
            int brightness = map_to_brightness(z);

            if (gpioPWM(LED_PIN, brightness) != 0) {
                fprintf(stderr, "gpioPWM failed on GPIO%d\n", LED_PIN);
            }

            if (g_log_file != NULL) {
                fprintf(g_log_file, "X=%d, Y=%d, Z=%d, Brightness=%d\n",
                        x, y, z, brightness);
                fflush(g_log_file);
            }
        } else {
            fprintf(stderr, "Magnetometer read error — skipping sample\n");
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    /* ---- Graceful shutdown ---- */
    fprintf(stderr, "\nShutting down...\n");
    gpioPWM(LED_PIN, 0);  /* turn LED off */
    cleanup();
    return EXIT_SUCCESS;
}

