#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HMC5883L_ADDR        0x1E
#define HMC5883L_CONFIG_A    0x00
#define HMC5883L_CONFIG_B    0x01
#define HMC5883L_MODE        0x02
#define HMC5883L_DATA_X_MSB  0x03
#define HMC5883L_DATA_Z_MSB  0x05
#define HMC5883L_DATA_Y_MSB  0x07

#define SAMPLE_COUNT         100
#define SAMPLE_DELAY_US      500000  /* 500 ms */

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} MagnetometerData;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                reg, pigpio_error(rc));
    }
    return rc;
}

static int initialize_hmc5883l(int handle) {
    if (i2c_write_byte(handle, HMC5883L_CONFIG_A, 0x70) < 0) return -1;
    if (i2c_write_byte(handle, HMC5883L_CONFIG_B, 0x20) < 0) return -1;
    if (i2c_write_byte(handle, HMC5883L_MODE, 0x00) < 0) return -1;
    return 0;
}

static int read_magnetometer_data(int handle, MagnetometerData *data) {
    uint8_t buffer[6];
    if (i2c_read_block(handle, HMC5883L_DATA_X_MSB, buffer, 6) < 0) {
        data->x = data->y = data->z = 0;
        return -1;
    }
    data->x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data->y = (int16_t)((buffer[4] << 8) | buffer[5]);
    return 0;
}

static void calculate_hard_iron_offsets(int16_t *x, int16_t *y, int16_t *z,
                                         const int16_t *x_buf,
                                         const int16_t *y_buf,
                                         const int16_t *z_buf,
                                         int count) {
    long x_sum = 0, y_sum = 0, z_sum = 0;
    for (int i = 0; i < count; i++) {
        x_sum += x_buf[i];
        y_sum += y_buf[i];
        z_sum += z_buf[i];
    }
    *x = (int16_t)(x_sum / count);
    *y = (int16_t)(y_sum / count);
    *z = (int16_t)(z_sum / count);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %s\n",
                HMC5883L_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_hmc5883l(g_i2c_handle) < 0) {
        fprintf(stderr, "Failed to initialize HMC5883L\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int16_t x_buffer[SAMPLE_COUNT];
    int16_t y_buffer[SAMPLE_COUNT];
    int16_t z_buffer[SAMPLE_COUNT];
    int buffer_index = 0;
    int samples_filled = 0;

    int16_t hard_iron_x = 0, hard_iron_y = 0, hard_iron_z = 0;

    while (g_running) {
        MagnetometerData raw_data;
        if (read_magnetometer_data(g_i2c_handle, &raw_data) < 0) {
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        x_buffer[buffer_index] = raw_data.x;
        y_buffer[buffer_index] = raw_data.y;
        z_buffer[buffer_index] = raw_data.z;
        buffer_index = (buffer_index + 1) % SAMPLE_COUNT;
        if (samples_filled < SAMPLE_COUNT) samples_filled++;

        if (samples_filled == SAMPLE_COUNT) {
            calculate_hard_iron_offsets(&hard_iron_x, &hard_iron_y, &hard_iron_z,
                                        x_buffer, y_buffer, z_buffer,
                                        SAMPLE_COUNT);
            printf("Hard iron offsets: X=%d, Y=%d, Z=%d\n",
                   hard_iron_x, hard_iron_y, hard_iron_z);
        }

        int16_t corrected_x = raw_data.x - hard_iron_x;
        int16_t corrected_y = raw_data.y - hard_iron_y;
        int16_t corrected_z = raw_data.z - hard_iron_z;

        printf("X=%d, Y=%d, Z=%d\n", corrected_x, corrected_y, corrected_z);
        fflush(stdout);

        gpioDelay(SAMPLE_DELAY_US);
    }

    if (g_i2c_handle >= 0) {
