static int g_buf_count = 0;  /* valid entries */

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C burst write (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, dst, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Accelerometer init ---- */
static int init_accelerometer(void)
{
    uint8_t who;

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                LSM303D_ADDR, strerror(errno));
        return -1;
    }

    /* Verify device identity */
    if (i2c_read_reg8(g_i2c_fd, LSM303D_WHO_AM_I, &who) < 0)
        return -1;
    if (who != LSM303D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LSM303D_WHO_AM_I_VAL);
        return -1;
    }

    /*
     * CTRL_REG1_A: 0x57 -> ODR = 100 Hz, all axes enabled, normal mode.
     * CTRL_REG2_A: 0x00 -> no high-pass filter.
     * CTRL_REG3_A: 0x00 -> no interrupt, default.
     * CTRL_REG4_A: 0x00 -> +/-2 g full scale, continuous update.
     * CTRL_REG5_A: 0x00 -> no FIFO, default.
     * CTRL_REG6_A: 0x00 -> no decimation, default.
     * CTRL_REG7_A: 0x00 -> no filtering, default.
     */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG1_A, 0x57) < 0) return -1;
    if (i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG2_A, 0x00) < 0) return -1;
    if (i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG3_A, 0x00) < 0) return -1;
    if (i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG4_A, 0x00) < 0) return -1;
    if (i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG5_A, 0x00) < 0) return -1;
    if (i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG6_A, 0x00) < 0) return -1;
    if (i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG7_A, 0x00) < 0) return -1;

    /* Configure INT1 for 6D detection (bit 6 = 1) with OR combination */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_INT1_CFG_A, 0x40) < 0) return -1;

    /* Threshold: 2000 mg / 0.061 mg/LSB ≈ 32768 -> 0x8000, but 8-bit reg.
     * Use 0xFF for maximum sensitivity threshold. */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_INT1_THS_A, 0xFF) < 0) return -1;

    /* Duration: 0 -> interrupt triggered immediately on threshold breach */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_INT1_DURATION_A, 0x00) < 0) return -1;

    return 0;
}

/* ---- Read one sample ---- */
static int read_acceleration(float *x, float *y, float *z)
{
    uint8_t raw[6];
    int16_t rx, ry, rz;

    if (i2c_read_burst(g_i2c_fd, LSM303D_OUT_X_L_A | 0x80, raw, 6) < 0)
        return -1;

    rx = (int16_t)((raw[1] << 8) | raw[0]);
    ry = (int16_t)((raw[3] << 8) | raw[2]);
    rz = (int16_t)((raw[5] << 8) | raw[4]);

    *x = rx * LSM303D_SENSITIVITY;
    *y = ry * LSM303D_SENSITIVITY;
    *z = rz * LSM303D_SENSITIVITY;
    return 0;
}

/* ---- Circular buffer ---- */
static void buffer_push(const accel_sample_t *s)
{
    g_buffer[g_buf_head] = *s;
    g_buf_head = (g_buf_head + 1) % BUFFER_SIZE;
    if (g_buf_count < BUFFER_SIZE)
        g_buf_count++;
}

static void buffer_dump_last_n(int n)
{
    if (n > g_buf_count)
        n = g_buf_count;
    if (n <= 0)
        return;

    int start = (g_buf_head - n + BUFFER_SIZE) % BUFFER_SIZE;
    printf("--- Last %d samples ---\n", n);
    for (int i = 0; i < n; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        localtime_r(&g_buffer[idx].ts.tv_sec, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s.%03ld] X: %7.2f mg  Y: %7.2f mg  Z: %7.2f mg\n",
               ts, g_buffer[idx].ts.tv_nsec / 1000000L,
               g_buffer[idx].x, g_buffer[idx].y, g_buffer[idx].z);
    }
    printf("-----------------------\n");
    fflush(stdout);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Put accelerometer in standby mode */
        (void)i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG1_A, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_int1_line) {
        gpiod_line_release(g_int1_line);
        g_int1_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_accelerometer() < 0) {
        fprintf(stderr, "Accelerometer initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_int1_line = gpiod_chip_get_line(g_chip, LSM303D_INT1_PIN);
    if (!g_int1_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                LSM303D_INT1_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_rising_edge_events(g_int1_line, "lsm303d_mon") < 0) {
        fprintf(stderr, "gpiod_line_request_rising_edge_events failed: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LSM303D monitor running. Press Ctrl-C to exit.\n");
    fflush(stdout);

    while (g_running) {
        accel_sample_t sample;
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        sample.ts = ts;

        if (read_acceleration(&sample.x, &sample.y, &sample.z) == 0) {
            buffer_push(&sample);
        } else {
            /* Failed read: skip this sample, keep buffer integrity */
            continue;
        }

        /* Poll INT1 line for rising edge (non-blocking) */
        struct timespec zero_ts = { 0, 0 };
        int ev = gpiod_line_event_wait(g_int1_line, &zero_ts);
        if (ev < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "gpiod_line_event_wait error: %s\n",
                    strerror(errno));
            break;
        }
        if (ev > 0) {
            struct gpiod_line_event event;
            if (gpiod_line_event_read(g_int1_line, &event) == 0) {
                if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                    buffer_dump_last_n(10);
                }
            }
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

