#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DELAY_MS       500

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static void sleep_ms(unsigned ms)
{
    struct timespec ts;
    ts.tv_sec  = ms / 1000;
    ts.tv_nsec = (long)(ms % 1000) * 1000000L;
    while (nanosleep(&ts, &ts) == -1) {
        /* Retry on EINTR so SIGINT can break the delay */
        if (g_running)
            continue;
        break;
    }
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure both pins as outputs and ensure they start LOW */
    if (safe_set_mode(SOLENOID_1_PIN, PI_OUTPUT) != 0 ||
        safe_set_mode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_write(SOLENOID_1_PIN, 0) != 0 ||
        safe_write(SOLENOID_2_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int active = 0;  /* 0 = solenoid 1, 1 = solenoid 2 */

    while (g_running) {
        int other = !active;
        if (safe_write(SOLENOID_1_PIN, active ? 0 : 1) != 0 ||
            safe_write(SOLENOID_2_PIN, active ? 1 : 0) != 0) {
            break;
        }
        active = other;
        sleep_ms(DELAY_MS);
    }

    /* Clean shutdown: both solenoids OFF, then release pigpio */
    safe_write(SOLENOID_1_PIN, 0);
    safe_write(SOLENOID_2_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

