#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <ctype.h>
#include <pigpio.h>

#define LOCK1_GPIO      17
#define LOCK2_GPIO      27
#define UART1_DEVICE    "/dev/serial0"
#define UART2_DEVICE    "/dev/serial1"
#define BAUD_RATE       9600
#define CODE_LENGTH     6
#define EXPECTED_CODE   "123456"
#define LOCK_DURATION_S 2
#define READ_TIMEOUT_S  5
#define POLL_DELAY_US   100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Constant-time comparison to avoid timing side-channels. */
static int codes_match(const char *a, const char *b)
{
    int diff = 0;
    for (int i = 0; i < CODE_LENGTH; i++)
        diff |= (unsigned char)a[i] ^ (unsigned char)b[i];
    return diff == 0;
}

/*
 * Read exactly CODE_LENGTH digits from the given UART handle.
 * Returns 0 on success, -1 on timeout, -2 on read error, -3 on signal.
 */
static int read_code(int uart_handle, char *code)
{
    char ch;
    int  idx = 0;
    time_t start = time(NULL);

    while (g_running) {
        if (time(NULL) - start >= READ_TIMEOUT_S) {
            fprintf(stderr, "[UART%02d] Timeout (%d s) waiting for code.\n",
                    uart_handle, READ_TIMEOUT_S);
            return -1;
        }

        int bytes = serRead(uart_handle, &ch, 1);
        if (bytes < 0) {
            fprintf(stderr, "[UART%02d] serRead error: %s\n",
                    uart_handle, strerror(errno));
            return -2;
        }
        if (bytes == 0) {
            usleep(POLL_DELAY_US);
            continue;
        }

        if (isdigit((unsigned char)ch)) {
            if (idx < CODE_LENGTH) {
                code[idx++] = ch;
                if (idx == CODE_LENGTH) {
                    code[idx] = '\0';
                    return 0;
                }
            }
        } else {
            /* Non-digit resets the buffer. */
            idx = 0;
            start = time(NULL);
        }
    }
    return -3;
}

static int unlock_door(void)
{
    if (gpioWrite(LOCK1_GPIO, 1) < 0) {
        fprintf(stderr, "Failed to set LOCK1_GPIO HIGH: %s\n", strerror(errno));
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 1) < 0) {
        fprintf(stderr, "Failed to set LOCK2_GPIO HIGH: %s\n", strerror(errno));
        gpioWrite(LOCK1_GPIO, 0);
        return -1;
    }

    printf("Door unlocked for %d seconds.\n", LOCK_DURATION_S);
    fflush(stdout);

    /* Sleep in 100 ms slices so we can exit promptly on signal. */
    for (int i = 0; i < LOCK_DURATION_S * 10 && g_running; i++)
        usleep(100000);

    if (gpioWrite(LOCK1_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to set LOCK1_GPIO LOW: %s\n", strerror(errno));
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to set LOCK2_GPIO LOW: %s\n", strerror(errno));
        return -1;
    }

    printf("Door locked.\n");
    fflush(stdout);
    return 0;
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure relay GPIOs as outputs, initially LOW (locked) --- */
    if (gpioSetMode(LOCK1_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LOCK1_GPIO mode: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LOCK2_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LOCK2_GPIO mode: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LOCK1_GPIO, 0) < 0 || gpioWrite(LOCK2_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to initialise relay GPIOs LOW: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open UART ports via pigpio --- */
    int uart1 = serOpen(UART1_DEVICE, BAUD_RATE, 0);
    if (uart1 < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", UART1_DEVICE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int uart2 = serOpen(UART2_DEVICE, BAUD_RATE, 0);
    if (uart2 < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", UART2_DEVICE, strerror(errno));
        serClose(uart1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        serClose(uart1);
        serClose(uart2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Dual-factor door lock system started.\n");
    printf("  UART1: %s | UART2: %s | Baud: %d\n", UART1_DEVICE, UART2_DEVICE, BAUD_RATE);
    printf("  Lock1 relay: GPIO%d | Lock2 relay: GPIO%d\n", LOCK1_GPIO, LOCK2_GPIO);
    printf("  Expected code: %s | Unlock duration: %d s\n", EXPECTED_CODE, LOCK_DURATION_S);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    char code1[CODE_LENGTH + 1] = {0};
    char code2[CODE_LENGTH + 1] = {0};
    int  have1 = 0, have2 = 0;

    /* --- Main loop --- */
    while (g_running) {
        int rc;

        if (!have1) {
            rc = read_code(uart1, code1);
            if (rc == 0) {
                have1 = 1;
                printf("[UART1] Code received: %s\n", code1);
                fflush(stdout);
            } else if (rc < 0 && rc != -3) {
                /* Timeout or error — keep trying. */
            }
        }

        if (!have2) {
            rc = read_code(uart2, code2);
            if (rc == 0) {
                have2 = 1;
                printf("[UART2] Code received: %s\n", code2);
                fflush(stdout);
            } else if (rc < 0 && rc != -3) {
                /* Timeout or error — keep trying. */
            }
        }

        if (have1 && have2) {
            if (codes_match(code1, code2) && codes_match(code1, EXPECTED_CODE)) {
                printf("Codes match expected value. Unlocking door.\n");
                fflush(stdout);
                if (unlock_door() < 0) {
                    fprintf(stderr, "Unlock failed; aborting.\n");
                    break;
                }
            } else {
                printf("Codes do not match expected value. Lock remains locked.\n");
                fflush(stdout);
            }
            have1 = have2 = 0;
            memset(code1, 0, sizeof(code1));
            memset(code2, 0, sizeof(code2));
        }

        usleep(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    fprintf(stderr, "\nShutting down...\n");
    fflush(stderr);

    /* Ensure both locks are locked (LOW) before releasing resources. */
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);

    serClose(uart1);
    serClose(uart2);
    gpioTerminate();

    fprintf(stderr, "Cleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

