/*
 * Raspberry Pi 4 Model B — PIR Door-Strike Controller
 *
 * Monitors an HC-SR501 PIR sensor on GPIO4 (physical pin 7) and energises
 * a door-strike relay on GPIO17 (physical pin 11) for 1 s on each motion
 * event.  If the PIR stays HIGH for more than 10 s a failsafe de-energises
 * the relay and logs a warning.
 *
 * Build:  gcc -O2 -Wall -Wextra -o pir_door pir_door.c -lgpiod
 * Run:    sudo ./pir_door
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <time.h>
#include <unistd.h>

#define PIR_PIN        4    /* GPIO4  — HC-SR501 OUT */
#define RELAY_PIN      17   /* GPIO17 — relay control */
#define POLL_MS        50   /* PIR poll interval (ms) */
#define RELAY_MS       1000 /* Relay energise duration (ms) */
#define FAILSAFE_S     10   /* Fail-safe threshold (s) */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT): %s", strerror(errno));
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM): %s", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging helpers                                                     */
/* ------------------------------------------------------------------ */
static void log_msg(int priority, const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    vsyslog(priority, fmt, ap);
    va_end(ap);
}

static void log_err(const char *msg)
{
    log_msg(LOG_ERR, "%s: %s", msg, strerror(errno));
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int set_line_value(struct gpiod_line *line, int value)
{
    if (gpiod_line_set_value(line, value) < 0) {
        log_err("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Fail-safe                                                           */
/* ------------------------------------------------------------------ */
static void fail_safe(struct gpiod_line *relay)
{
    log_msg(LOG_WARNING,
            "PIR HIGH for >%d s — potential malfunction. "
            "Failsafe: de-energising relay.", FAILSAFE_S);

    if (set_line_value(relay, 0) < 0)
        log_msg(LOG_ERR, "Fail-safe: failed to de-energise relay");
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("pir_door", LOG_PID | LOG_CONS, LOG_USER);

    if (install_signal_handlers() < 0) {
        closelog();
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip4 on Pi 4 with 6.2+ kernel) */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        /* Fallback: let libgpiod find the first usable chip */
        chip = gpiod_chip_open_by_number(0);
    }
    if (!chip) {
        log_err("gpiod_chip_open");
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *pir   = gpiod_chip_get_line(chip, PIR_PIN);
    struct gpiod_line *relay = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!pir || !relay) {
        log_err("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    /* Request PIR as input */
    if (gpiod_line_request_input(pir, "pir_door") < 0) {
        log_err("gpiod_line_request_input(PIR)");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    /* Request relay as output, initial value LOW (de-energised) */
    if (gpiod_line_request_output(relay, "pir_door", 0) < 0) {
        log_err("gpiod_line_request_output(relay)");
        gpiod_line_release(pir);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    log_msg(LOG_INFO, "PIR Door-Strike Controller started (PIR=GPIO%d, Relay=GPIO%d)",
            PIR_PIN, RELAY_PIN);

    time_t last_motion = 0;
    bool relay_on = false;

    while (g_running) {
        int pir_val = gpiod_line_get_value(pir);
        if (pir_val < 0) {
            log_err("gpiod_line_get_value(PIR)");
            usleep(POLL_MS * 1000);
            continue;
        }

        if (pir_val == 1) {
            time_t now = time(NULL);
            if (now == (time_t)-1) {
                log_err("time");
                usleep(POLL_MS * 1000);
                continue;
            }

            if (last_motion == 0) {
                last_motion = now;
                log_msg(LOG_INFO, "Motion detected (PIR HIGH)");
            } else if (difftime(now, last_motion) > FAILSAFE_S) {
                fail_safe(relay);
                last_motion = now; /* reset so we don't spam the log */
            }

            /* Energise relay if not already on */
            if (!relay_on) {
                if (set_line_value(relay, 1) == 0) {
                    relay_on = true;
                    log_msg(LOG_INFO, "Relay energised (GPIO%d HIGH)", RELAY_PIN);
                }
            }
        } else {
            /* PIR LOW — reset timer */
            last_motion = 0;
            if (relay_on) {
                if (set_line_value(relay, 0) == 0) {
                    relay_on = false;
                    log_msg(LOG_INFO, "Relay de-energised (GPIO%d LOW)", RELAY_PIN);
                }
            }
        }

        usleep(POLL_MS * 1000);
    }

    /* ---- Clean shutdown ---- */
    log_msg(LOG_INFO, "Shutting down — de-energising relay and releasing lines.");

    /* Ensure relay is LOW before releasing */
    if (relay_on)
        set_line_value(relay, 0);

    gpiod_line_release(pir);
    gpiod_line_release(relay);
    gpiod_chip_close(chip);
    closelog();

    return EXIT_SUCCESS;
}

