#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define RELAY_ON 0
#define RELAY_OFF 1

#define TIMER_ID 0
#define TIMER_INTERVAL_MS 60000
#define RELAY_ON_DURATION_S 300
#define RELAY_OFF_DURATION_S 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(priority, "%s: %s", timestamp, message);
}

static int set_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Failed to set GPIO %d to %d", pin, state);
        log_message(LOG_ERR, msg);
        return -1;
    }
    return 0;
}

static void timer_callback(void *user_data) {
    (void)user_data;
    static int current_relay = 1;
    char msg[128];

    snprintf(msg, sizeof(msg), "Timer callback triggered, current relay: %d", current_relay);
    log_message(LOG_INFO, msg);

    if (current_relay == 1) {
        if (set_relay(RELAY1_PIN, RELAY_ON) == 0) {
            snprintf(msg, sizeof(msg), "Relay 1 activated");
            log_message(LOG_INFO, msg);
        }
        current_relay = 2;
    } else if (current_relay == 2) {
        if (set_relay(RELAY2_PIN, RELAY_ON) == 0) {
            snprintf(msg, sizeof(msg), "Relay 2 activated");
            log_message(LOG_INFO, msg);
        }
        current_relay = 3;
    } else if (current_relay == 3) {
        if (set_relay(RELAY3_PIN, RELAY_ON) == 0) {
            snprintf(msg, sizeof(msg), "Relay 3 activated");
            log_message(LOG_INFO, msg);
        }
        current_relay = 4;
    } else if (current_relay == 4) {
        if (set_relay(RELAY4_PIN, RELAY_ON) == 0) {
            snprintf(msg, sizeof(msg), "Relay 4 activated");
            log_message(LOG_INFO, msg);
        }
        current_relay = 1;
    }
}

static void cleanup(void) {
    log_message(LOG_INFO, "Cleaning up GPIO and exiting.");
    set_relay(RELAY1_PIN, RELAY_OFF);
    set_relay(RELAY2_PIN, RELAY_OFF);
    set_relay(RELAY3_PIN, RELAY_OFF);
    set_relay(RELAY4_PIN, RELAY_OFF);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Failed to set GPIO %d as output", pins[i]);
            log_message(LOG_ERR, msg);
            cleanup();
            return EXIT_FAILURE;
        }
        if (set_relay(pins[i], RELAY_OFF) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }

