/*
 * MPU6050 100 Hz accelerometer sampler for Raspberry Pi 4 Model B.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mpu6050_sampler mpu6050_sampler.c
 * Run:    ./mpu6050_sampler
 *
 * The most recent sample is made available via the driver library
 * interface /sys/kernel/mpu6050_accel/latest.
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MPU6050 constants ---- */
#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define PWR_MGMT_1     0x6B
#define ACCEL_XOUT_H   0x3B
#define ACCEL_CONFIG   0x1C
#define ACCEL_SCALE    16384.0f   /* +/- 2 g range */

/* ---- Sampler constants ---- */
#define SAMPLE_HZ      100
#define SAMPLE_NS      (1000000000L / SAMPLE_HZ)
#define BUFFER_SIZE    100
#define DRIVER_PATH    "/sys/kernel/mpu6050_accel/latest"

/* ---- Data structures ---- */
typedef struct {
    float x, y, z;
} accel_sample_t;

typedef struct {
    accel_sample_t buf[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static int      g_timer_fd = -1;
static FILE    *g_driver_fp = NULL;
static circular_buffer_t *g_cb = NULL;

/* ---- Signal handler ---- */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, dst, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read burst from 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- MPU6050 init ---- */
static int mpu6050_init(int fd)
{
    /* Wake the device (clear SLEEP bit) */
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0)
        return -1;
    /* Allow oscillator to stabilise */
    struct timespec ts = { .tv_sec = 0, .tv_nsec = 100000000 };
    nanosleep(&ts, NULL);

    /* Set accelerometer range to +/- 2 g (AFS_SEL = 0) */
    if (i2c_write_byte(fd, ACCEL_CONFIG, 0x00) < 0)
        return -1;

    return 0;
}

/* ---- Read one sample ---- */
static int read_accel_sample(int fd, accel_sample_t *out)
{
    uint8_t raw[6];
    if (i2c_read_burst(fd, ACCEL_XOUT_H, raw, sizeof(raw)) < 0)
        return -1;

    int16_t x = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t y = (int16_t)((raw[2] << 8) | raw[3]);
    int16_t z = (int16_t)((raw[4] << 8) | raw[5]);

    out->x = (float)x / ACCEL_SCALE;
    out->y = (float)y / ACCEL_SCALE;
    out->z = (float)z / ACCEL_SCALE;
    return 0;
}

/* ---- Circular buffer ---- */
static void cb_init(circular_buffer_t *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void cb_push(circular_buffer_t *cb, accel_sample_t s)
{
    cb->buf[cb->head] = s;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static accel_sample_t cb_latest(const circular_buffer_t *cb)
{
    if (cb->count == 0) {
        static accel_sample_t zero = {0, 0, 0};
        return zero;
    }
    int idx = (cb->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    return cb->buf[idx];
}

/* ---- Driver library file ---- */
static int driver_write(const accel_sample_t *s)
{
    if (g_driver_fp == NULL)
        return -1;
    if (fprintf(g_driver_fp, "%.3f,%.3f,%.3f\n", s->x, s->y, s->z) < 0) {
        fprintf(stderr, "Driver file write failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(g_driver_fp);
    return 0;
}

/* ---- Timer callback (SIGEV_SIGNAL) ---- */
static void timer_handler(int sig, siginfo_t *si, void *uc)
{
    (void)sig; (void)uc;
    if (si->si_signo != SIGRTMIN)
        return;

    accel_sample_t sample;
    if (read_accel_sample(g_i2c_fd, &sample) == 0) {
        cb_push(g_cb, sample);
        driver_write(&sample);
    } else {
        fprintf(stderr, "Sensor read error — skipping sample.\n");
    }
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_timer_fd >= 0) {
        timer_delete(g_timer_fd);
        g_timer_fd = -1;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_driver_fp) {
        fclose(g_driver_fp);
        g_driver_fp = NULL;
    }
    free(g_cb);
    g_cb = NULL;
}

/* ---- Main ---- */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Probe: try a register read to confirm the sensor is present */
    uint8_t probe;
    if (i2c_read_burst(g_i2c_fd, PWR_MGMT_1, &probe, 1) < 0) {
        fprintf(stderr, "MPU6050 not responding at 0x%02X on %s\n",
                MPU6050_ADDR, I2C_BUS);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (mpu6050_init(g_i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Allocate circular buffer */
    g_cb = calloc(1, sizeof(*g_cb));
    if (!g_cb) {
        perror("calloc");
        cleanup();
        return EXIT_FAILURE;
    }
    cb_init(g_cb);

    /* Open driver library file */
    g_driver_fp = fopen(DRIVER_PATH, "w");
    if (!g_driver_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", DRIVER_PATH, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Create POSIX per-process timer */
    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo  = SIGRTMIN;
    sev.sigev_value.sival_ptr = NULL;

    struct sigaction tsig;
    memset(&tsig, 0, sizeof(tsig));
    tsig.sa_sigaction = timer_handler;
    tsig.sa_flags     = SA_SIGINFO;
    sigemptyset(&tsig.sa_mask);
    if (sigaction(SIGRTMIN, &tsig, NULL) < 0) {
        perror("sigaction(SIGRTMIN)");
        cleanup();
        return EXIT_FAILURE;
    }

    timer_t timerid;
    if (timer_create(CLOCK_MONOTONIC, &sev, &timerid) < 0) {
        perror("timer_create");
        cleanup();
        return EXIT_FAILURE;
    }
    g_timer_fd = (int)timerid;

    /* Arm the timer */
    struct itimerspec its;
    its.it_interval.tv_sec  = 0;
    its.it_interval.tv_nsec = SAMPLE_NS;
    its.it_value.tv_sec     = 0;
    its.it_value.tv_nsec    = SAMPLE_NS;
    if (timer_settime(timerid, 0, &its, NULL) < 0) {
        perror("timer_settime");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPU6050 sampling at %d Hz.  Driver output: %s\n", SAMPLE_HZ, DRIVER_PATH);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop — sleep until signal */
    while (g_running)
        pause();

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

