    its.it_interval.tv_sec  = 0;
    its.it_interval.tv_nsec = SAMPLE_NS;
    its.it_value.tv_sec     = 0;
    its.it_value.tv_nsec    = SAMPLE_NS;
    if (timer_settime(timerid, 0, &its, NULL) < 0) {
        perror("timer_settime");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPU6050 sampling at %d Hz.  Driver output: %s\n", SAMPLE_HZ, DRIVER_PATH);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop — sleep until signal */
    while (g_running)
        pause();

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

