#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define CONSUMER "relay-toggle"

static const unsigned int relay_pins[NUM_RELAYS] = {18, 23, 24, 25};
static const int intervals[NUM_RELAYS] = {2, 3, 5, 7};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static double elapsed_seconds(const struct timespec *start, const struct timespec *end) {
    return (double)(end->tv_sec - start->tv_sec) +
           (double)(end->tv_nsec - start->tv_nsec) / 1.0e9;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int lines_requested = 0;
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }
        lines_requested++;
    }

    struct timespec next_times[NUM_RELAYS];
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    for (int i = 0; i < NUM_RELAYS; i++) {
        next_times[i] = now;
    }

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &now);

        for (int i = 0; i < NUM_RELAYS; i++) {
            if (elapsed_seconds(&next_times[i], &now) >= (double)intervals[i]) {
                int val = gpiod_line_get_value(lines[i]);
                if (val < 0) {
                    fprintf(stderr, "Failed to read GPIO line %u: %s\n", relay_pins[i], strerror(errno));
                    goto cleanup;
                }
                if (gpiod_line_set_value(lines[i], !val) < 0) {
                    fprintf(stderr, "Failed to write GPIO line %u: %s\n", relay_pins[i], strerror(errno));
                    goto cleanup;
                }
                next_times[i] = now;
                next_times[i].tv_sec += intervals[i];
            }
        }

        struct timespec sleep_ts = {0, 100 * 1000 * 1000}; /* 100 ms */
        nanosleep(&sleep_ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < lines_requested; i++) {
        if (lines[i] != NULL) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

