#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SOUND_SENSOR_GPIO 17
#define RELAY_GPIO 27
#define RELAY_ACTIVATION_TIME 3
#define POLL_INTERVAL_US 100000
#define LOG_FILE "alarm_log.txt"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int log_timestamp(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int activate_relay(int gpio, int duration_seconds) {
    if (gpioWrite(gpio, 1) != 0) {
        fprintf(stderr, "Error activating relay on GPIO %d\n", gpio);
        return -1;
    }

    time_sleep(duration_seconds);

    if (gpioWrite(gpio, 0) != 0) {
        fprintf(stderr, "Error deactivating relay on GPIO %d\n", gpio);
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", SOUND_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing relay to OFF state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sound_detected = gpioRead(SOUND_SENSOR_GPIO);
        if (sound_detected < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", SOUND_SENSOR_GPIO);
            break;
        }

        if (sound_detected == 1) {
            printf("Sound detected!\n");

            if (log_timestamp(LOG_FILE) != 0) {
                fprintf(stderr, "Error logging timestamp\n");
            }

            if (activate_relay(RELAY_GPIO, RELAY_ACTIVATION_TIME) != 0) {
                fprintf(stderr, "Error activating relay\n");
            }

            while (program_running && gpioRead(SOUND_SENSOR_GPIO) == 1) {
                gpioDelay(POLL_INTERVAL_US);
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error turning off relay during shutdown\n");
    }

    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

