/*
 * MPU-6050 Gyroscope Reader with Circular Buffer and Threshold Callback
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C1 (SDA=GPIO2, SCL=GPIO3, BCM)
 * Sensor: MPU-6050 (I2C address 0x68)
 *
 * Build:  gcc -O2 -Wall -o gyro_monitor gyro_monitor.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- Configuration ---- */
#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68

#define PWR_MGMT_1     0x6B
#define GYRO_XOUT_H    0x43
#define GYRO_CONFIG    0x1B

#define GYRO_SCALE     131.0f   /* LSB per deg/s at ±250 deg/s */
#define THRESHOLD      50.0f    /* deg/s */
#define BUFFER_SIZE    100
#define SAMPLE_DELAY   10000   /* 10 ms in microseconds */

/* ---- Data Structures ---- */
typedef struct {
    int16_t x, y, z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ---- Signal Handler ---- */
static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- I2C Helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Sensor Init ---- */
static int init_mpu6050(int fd) {
    /* Wake up: clear SLEEP bit in PWR_MGMT_1 */
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000); /* 100 ms stabilization */

    /* Set gyro full-scale range to ±250 deg/s (FS_SEL=0) */
    if (i2c_write_reg8(fd, GYRO_CONFIG, 0x00) < 0) return -1;

    return 0;
}

/* ---- Read Gyro ---- */
static int read_gyro_data(int fd, gyro_data_t *out) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, GYRO_XOUT_H, buf, 6) < 0) return -1;

    out->x = (int16_t)((buf[0] << 8) | buf[1]);
    out->y = (int16_t)((buf[2] << 8) | buf[3]);
    out->z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* ---- Circular Buffer ---- */
static void buffer_init(circular_buffer_t *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void buffer_add(circular_buffer_t *cb, gyro_data_t d) {
    cb->data[cb->head] = d;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

/* ---- Threshold Check ---- */
static bool threshold_exceeded(gyro_data_t d) {
    float x = (float)d.x / GYRO_SCALE;
    float y = (float)d.y / GYRO_SCALE;
    float z = (float)d.z / GYRO_SCALE;
    float mag = sqrtf(x * x + y * y + z * z);
    return mag > THRESHOLD;
}

/* ---- Callback ---- */
static void on_threshold_exceeded(gyro_data_t d) {
    float x = (float)d.x / GYRO_SCALE;
    float y = (float)d.y / GYRO_SCALE;
    float z = (float)d.z / GYRO_SCALE;
    float mag = sqrtf(x * x + y * y + z * z);

    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);

    printf("[%s] THRESHOLD EXCEEDED | X:%7.2f Y:%7.2f Z:%7.2f deg/s | mag: %7.2f deg/s\n",
           ts, x, y, z, mag);
}

/* ---- Main ---- */
int main(void) {
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Select MPU-6050 */
    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_mpu6050(g_i2c_fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed (sensor absent or bus error).\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 ready on %s (addr 0x%02X). Sampling at 100 Hz. Press Ctrl+C to exit.\n",
           I2C_BUS, MPU6050_ADDR);

    circular_buffer_t gyro_buffer;
    buffer_init(&gyro_buffer);

    while (g_running) {
        gyro_data_t sample;
        if (read_gyro_data(g_i2c_fd, &sample) < 0) {
            fprintf(stderr, "Read error — continuing.\n");
            usleep(SAMPLE_DELAY);
            continue;
        }

        buffer_add(&gyro_buffer, sample);

        if (threshold_exceeded(sample)) {
            on_threshold_exceeded(sample);
        }

        usleep(SAMPLE_DELAY);
    }

    /* Cleanup */
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

