#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/time.h>
#include <the_driver.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define SAMPLE_INTERVAL_SEC 5
#define RESPONSE_TIMEOUT_SEC 1
#define RESPONSE_LEN 9
#define CMD_LEN 9

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;
static FILE *g_log_fp = NULL;
static FILE *g_err_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_error(const char *msg) {
    struct timeval tv;
    struct tm tm_info;
    char ts[32];
    gettimeofday(&tv, NULL);
    localtime_r(&tv.tv_sec, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    if (g_err_fp) {
        fprintf(g_err_fp, "%s.%06ld: %s\n", ts, tv.tv_usec, msg);
        fflush(g_err_fp);
    }
    fprintf(stderr, "%s.%06ld: %s\n", ts, tv.tv_usec, msg);
}

static int read_response(int fd, unsigned char *buf, size_t len) {
    size_t total = 0;
    struct timeval start, now;
    gettimeofday(&start, NULL);
    while (total < len) {
        gettimeofday(&now, NULL);
        long elapsed = (now.tv_sec - start.tv_sec) * 1000000L + (now.tv_usec - start.tv_usec);
        if (elapsed > RESPONSE_TIMEOUT_SEC * 1000000L) {
            return -1;
        }
        ssize_t n = uart_read(fd, (char *)(buf + total), len - total);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) continue;
            return -1;
        }
        if (n == 0) {
            usleep(10000);
            continue;
        }
        total += (size_t)n;
    }
    return 0;
}

static int read_co2(int fd, int *ppm) {
    unsigned char cmd[CMD_LEN] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};
    unsigned char resp[RESPONSE_LEN];

    if (uart_write(fd, (char *)cmd, CMD_LEN) != CMD_LEN) {
        log_error("Failed to write command to UART");
        return -1;
    }

    if (read_response(fd, resp, RESPONSE_LEN) != 0) {
        log_error("Timeout waiting for MH-Z19B response");
        return -1;
    }

    if (resp[0] != 0xFF || resp[1] != 0x86) {
        log_error("Invalid response header from MH-Z19B");
        return -1;
    }

    int checksum = 0;
    for (int i = 1; i < RESPONSE_LEN - 1; i++) {
        checksum += resp[i];
    }
    checksum = 255 - checksum;
    checksum++;

    if (checksum != resp[RESPONSE_LEN - 1]) {
        log_error("Checksum mismatch on MH-Z19B response");
        return -1;
    }

    *ppm = (resp[2] << 8) | resp[3];
    return 0;
}

static void log_data(FILE *fp, int ppm, int error_flag) {
    struct timeval tv;
    struct tm tm_info;
    char ts[32];
    gettimeofday(&tv, NULL);
    localtime_r(&tv.tv_sec, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "{\"timestamp\": \"%s.%06ld\", \"co2_ppm\": %d, \"error\": %d}\n",
            ts, tv.tv_usec, ppm, error_flag);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    g_uart_fd = uart_open(UART_DEVICE, BAUD_RATE);
    if (g_uart_fd < 0) {
        fprintf(stderr, "Failed to open UART %s: %s\n", UART_DEVICE, strerror(errno));
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log");
        uart_close(g_uart_fd);
        return 1;
    }

    g_err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!g_err_fp) {
        perror("fopen error log");
        fclose(g_log_fp);
        uart_close(g_uart_fd);
        return 1;
    }

    printf("CO2 monitoring started. Logging to %s, errors to %s\n", LOG_FILE, ERROR_LOG_FILE);

    while (g_running) {
        int ppm = 0;
        int error_flag = 0;

        if (read_co2(g_uart_fd, &ppm) != 0) {
            error_flag = 1;
        }

        log_data(g_log_fp, ppm, error_flag);
        if (error_flag) {
            fprintf(stderr, "Error reading CO2: %d\n", ppm);
        } else {
            printf("CO2: %d ppm\n", ppm);
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (g_log_fp) fclose(g_log_fp);
    if (g_err_fp) fclose(g_err_fp);
    if (g_uart_fd >= 0) uart_close(g_uart_fd);
    return 0;
}

