#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* HMC5883L I2C address (0x1E or 0x1E | 0x0C depending on SA0) */
#define HMC5883L_ADDR 0x1E

/* HMC5883L register addresses */
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE     0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Y_MSB 0x07

/* GPIO pin for alert (BCM numbering) */
#define ALERT_PIN 17

/* Target heading in degrees */
#define TARGET_HEADING 90.0

/* Heading deviation threshold in degrees */
#define HEADING_THRESHOLD 10.0

/* Circular buffer size */
#define BUFFER_SIZE 100

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Hard-iron compensation offsets */
#define HARD_IRON_X 100
#define HARD_IRON_Y -50

/* Global state */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Circular buffer */
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static CircularBuffer heading_buffer;

/* Function prototypes */
static int init_hmc5883l(void);
static int read_magnetometer(int16_t *x, int16_t *y, int16_t *z);
static float calculate_heading(int16_t x, int16_t y);
static void add_to_buffer(CircularBuffer *cb, float heading);
static float get_average_heading(const CircularBuffer *cb);
static void signal_handler(int sig);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Initialize the HMC5883L magnetometer */
static int init_hmc5883l(void) {
    /* Configuration register A: 8-average, 15 Hz, normal measurement */
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }

    /* Configuration register B: 1.3 Ga full scale, gain = 1090 */
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    /* Mode register: continuous measurement */
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

/* Read magnetometer data from the HMC5883L */
static int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    /* Read 6 bytes starting from the X MSB register */
    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    /* HMC5883L data order: X, Z, Y (MSB first) */
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

/* Calculate heading in degrees from raw X and Y values */
static float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2f((float)y, (float)x) * 180.0f / M_PI;

    /* Apply hard-iron compensation */
    heading -= atan2f((float)HARD_IRON_Y, (float)HARD_IRON_X) * 180.0f / M_PI;

    /* Normalize heading to [0, 360) */
    if (heading < 0.0f) {
        heading += 360.0f;
    }

    return heading;
}

/* Add a heading to the circular buffer */
static void add_to_buffer(CircularBuffer *cb, float heading) {
    cb->buffer[cb->head] = heading;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

/* Get the average heading from the circular buffer */
static float get_average_heading(const CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0f;
    }

    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / (float)cb->count;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set ALERT_PIN as output and initialize to LOW */
    gpioSetMode(ALERT_PIN, PI_OUTPUT);
    gpioWrite(ALERT_PIN, 0);

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize HMC5883L */
    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize circular buffer */
    heading_buffer.head = 0;
    heading_buffer.count = 0;

    /* Set up signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("HMC5883L magnetometer reading started. Press Ctrl+C to exit.\n");

    int16_t x, y, z;
    float heading, average_heading;

    while (!terminate) {
        /* Read magnetometer data */
        if (read_magnetometer(&x, &y, &z) == 0) {
            /* Calculate heading */
            heading = calculate_heading(x, y);

            /* Add heading to circular buffer */
            add_to_buffer(&heading_buffer, heading);

            /* Get average heading */
            average_heading = get_average_heading(&heading_buffer);

            /* Check if heading is within the threshold */
            if (fabsf(average_heading - TARGET_HEADING) > HEADING_THRESHOLD) {
                gpioWrite(ALERT_PIN, 1);
            } else {
                gpioWrite(ALERT_PIN, 0);
            }

            printf("Heading: %.2f, Average Heading: %.2f\n", heading, average_heading);
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    cleanup();
    printf("Program terminated.\n");

    return EXIT_SUCCESS;
}

