/*
 * Raspberry Pi 5 – BH1750 ambient light logger with RGB relay control
 *
 * Hardware:
 *   - BH1750FVI on I2C bus 1, address 0x23 (ADDR pin to GND)
 *   - 3x 5 V relays on GPIO 17 (RED), GPIO 27 (GREEN), GPIO 22 (BLUE)
 *
 * Build:  gcc -O2 -Wall -Wextra -o lighting lighting.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ----------------------------- Constants ------------------------------- */
#define I2C_BUS            "/dev/i2c-1"
#define BH1750_ADDR        0x23          /* ADDR pin -> GND */
#define BH1750_PWR_ON      0x01
#define BH1750_CONT_HRES   0x10          /* continuous high-res mode */
#define BH1750_CONV_MS     120           /* conversion time (ms) */

#define RED_PIN    17
#define GREEN_PIN  27
#define BLUE_PIN   22

#define LUX_THRESHOLD_LOW    50
#define LUX_THRESHOLD_MED    150
#define LUX_THRESHOLD_HIGH   300

#define LOG_FILE "lighting_log.txt"

/* --------------------------- Global state ------------------------------ */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static FILE    *g_log_fp   = NULL;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_red  = NULL;
static struct gpiod_line  *g_green = NULL;
static struct gpiod_line  *g_blue = NULL;

/* ------------------------- Forward declarations ------------------------ */
static void cleanup(void);
static void signal_handler(int sig);
static int  bh1750_init(void);
static int  bh1750_read_lux(uint16_t *lux_out);
static void control_lamps(uint16_t lux);
static void log_data(uint16_t lux, int r, int g, int b);

/* ------------------------------- Main ---------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Open log file -------------------------------------------------- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --------------------------------------------------- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open(" I2C_BUS ")");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Initialise BH1750 --------------------------------------------- */
    if (bh1750_init() != 0) {
        fprintf(stderr, "BH1750 init failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip and request relay lines ------------------------ */
    g_chip = gpiod_chip_open_by_name("gpiochip4");   /* RP1 on Pi 5 */
    if (!g_chip) {
        perror("gpiod_chip_open_by_name");
        cleanup();
        return EXIT_FAILURE;
    }

    g_red   = gpiod_chip_get_line(g_chip, RED_PIN);
    g_green = gpiod_chip_get_line(g_chip, GREEN_PIN);
    g_blue  = gpiod_chip_get_line(g_chip, BLUE_PIN);
    if (!g_red || !g_green || !g_blue) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_red,   "lighting-red",   0) < 0 ||
        gpiod_line_request_output(g_green, "lighting-green", 0) < 0 ||
        gpiod_line_request_output(g_blue,  "lighting-blue",  0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Main loop ------------------------------------------------------ */
    while (g_running) {
        uint16_t lux = 0;
        if (bh1750_read_lux(&lux) != 0) {
            fprintf(stderr, "BH1750 read error; continuing\n");
        } else {
            control_lamps(lux);
            int r = gpiod_line_get_value(g_red);
            int g = gpiod_line_get_value(g_green);
            int b = gpiod_line_get_value(g_blue);
            log_data(lux, r, g, b);
        }
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* --------------------------- BH1750 helpers ----------------------------- */
static int bh1750_init(void)
{
    uint8_t cmd = BH1750_PWR_ON;
    if (write(g_i2c_fd, &cmd, 1) != 1) {
        perror("BH1750 power-on");
        return -1;
    }
    cmd = BH1750_CONT_HRES;
    if (write(g_i2c_fd, &cmd, 1) != 1) {
        perror("BH1750 set mode");
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(uint16_t *lux_out)
{
    uint8_t buf[2];
    ssize_t n = read(g_i2c_fd, buf, 2);
    if (n != 2) {
        if (n < 0)
            perror("BH1750 read");
        else
            fprintf(stderr, "BH1750 short read: %zd bytes\n", n);
        return -1;
    }
    *lux_out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* --------------------------- Lamp control ------------------------------ */
static void control_lamps(uint16_t lux)
{
    int r = 0, g = 0, b = 0;

    if (lux < LUX_THRESHOLD_LOW) {
        r = 1;
    } else if (lux < LUX_THRESHOLD_MED) {
        g = 1;
    } else if (lux < LUX_THRESHOLD_HIGH) {
        b = 1;
    } else {
        r = g = b = 1;
    }

    if (gpiod_line_set_value(g_red,   r) < 0 ||
        gpiod_line_set_value(g_green, g) < 0 ||
        gpiod_line_set_value(g_blue,  b) < 0) {
        perror("gpiod_line_set_value");
    }
}

/* ----------------------------- Logging --------------------------------- */
static void log_data(uint16_t lux, int r, int g, int b)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(g_log_fp, "%s, Lux: %u, RED: %d, GREEN: %d, BLUE: %d\n",
                ts, lux, r, g, b) < 0) {
        perror("fprintf");
    } else {
        fflush(g_log_fp);
    }
}

/* --------------------------- Cleanup / signals -------------------------- */
static void cleanup(void)
{
    if (g_red)   gpiod_line_set_value(g_red,   0);
    if (g_green) gpiod_line_set_value(g_green, 0);
    if (g_blue)  gpiod_line_set_value(g_blue,  0);

    if (g_red)   gpiod_line_release(g_red);
    if (g_green) gpiod_line_release(g_green);
    if (g_blue)  gpiod_line_release(g_blue);
    if (g_chip)  gpiod_chip_close(g_chip);

    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

