    if (g_red)   gpiod_line_release(g_red);
    if (g_green) gpiod_line_release(g_green);
    if (g_blue)  gpiod_line_release(g_blue);
    if (g_chip)  gpiod_chip_close(g_chip);

    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

