#define PWM_RANGE 255
#define LOOP_DELAY_US 100000
#define DISTANCE_THRESHOLD 50.0

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", MOTOR_A_IN1);
        return -1;
    }
    if (gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", MOTOR_A_IN2);
        return -1;
    }
    if (gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", MOTOR_B_IN3);
        return -1;
    }
    if (gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", MOTOR_B_IN4);
        return -1;
    }

    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", MOTOR_A_IN2);
        return -1;
    }
    if (gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", MOTOR_B_IN4);
        return -1;
    }

    if (gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", MOTOR_A_IN2);
        return -1;
    }
    if (gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", MOTOR_B_IN4);
        return -1;
    }

    return 0;
}

static void stop_motors(void) {
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
