    gpioWrite(MOTOR_B_IN4, 0);
    gpioPWM(MOTOR_A_IN2, 0);
    gpioPWM(MOTOR_B_IN4, 0);
}

static void cleanup(void) {
    stop_motors();
    gpioTerminate();
}

static int set_motor_speed(int in1, int in2, int in3, int in4, float distance) {
    int duty_cycle = (int)(distance * 2.55f);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    if (distance < DISTANCE_THRESHOLD) {
        if (gpioWrite(in1, 1) != 0) return -1;
        if (gpioWrite(in3, 1) != 0) return -1;
        if (gpioPWM(in2, duty_cycle) != 0) return -1;
        if (gpioPWM(in4, duty_cycle) != 0) return -1;
    } else {
        if (gpioWrite(in1, 0) != 0) return -1;
        if (gpioWrite(in3, 0) != 0) return -1;
        if (gpioPWM(in2, duty_cycle) != 0) return -1;
        if (gpioPWM(in4, duty_cycle) != 0) return -1;
    }
    return 0;
}

