    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_a> <distance_b>\n", argv[0]);
        fprintf(stderr, "  distance_a, distance_b: float values in cm (10.0-100.0)\n");
        return EXIT_FAILURE;
    }

    float distance_a = (float)atof(argv[1]);
    float distance_b = (float)atof(argv[2]);

    if (distance_a < 10.0f || distance_a > 100.0f) {
        fprintf(stderr, "Error: distance_a (%.2f) must be between 10.0 and 100.0.\n", distance_a);
        return EXIT_FAILURE;
    }
    if (distance_b < 10.0f || distance_b > 100.0f) {
        fprintf(stderr, "Error: distance_b (%.2f) must be between 10.0 and 100.0.\n", distance_b);
        return EXIT_FAILURE;
    }

