#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define FADE_DURATION 1800
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define SCHEDULE_FILE "lighting_schedule.txt"

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int parse_time(const char *str, int *hour, int *minute, int *second) {
    if (sscanf(str, "%d:%d:%d", hour, minute, second) != 3) return -1;
    if (*hour < 0 || *hour > 23 || *minute < 0 || *minute > 59 || *second < 0 || *second > 59) return -1;
    return 0;
}

static int parse_schedule(const char *filename, int *hour, int *minute, int *second, int *relay, int *state) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening schedule file");
        return -1;
    }
    char line[256];
    int found = 0;
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    if (!tm_info) {
        fclose(fp);
        return -1;
    }
    int current_hour = tm_info->tm_hour;
    int current_minute = tm_info->tm_min;
    int current_second = tm_info->tm_sec;

    while (fgets(line, sizeof(line), fp)) {
        int h, m, s, r, st;
        char time_str[16], relay_str[4], state_str[4];
        if (sscanf(line, "%15[^,],%3[^,],%3s", time_str, relay_str, state_str) == 3) {
            if (parse_time(time_str, &h, &m, &s) == 0) {
                if (sscanf(relay_str, "%d", &r) == 1 && r >= 1 && r <= NUM_RELAYS) {
                    if (strcmp(state_str, "on") == 0) st = 1;
                    else if (strcmp(state_str, "off") == 0) st = 0;
                    else continue;
                    if (h > current_hour || (h == current_hour && m > current_minute) || (h == current_hour && m == current_minute && s > current_second)) {
                        *hour = h; *minute = m; *second = s; *relay = r; *state = st;
                        found = 1;
                        break;
                    }
                }
            }
        }
    }
    fclose(fp);
    return found ? 0 : -1;
}

static void set_relay(int relay, int state) {
    if (relay >= 1 && relay <= NUM_RELAYS) {
        gpioWrite(relay_pins[relay - 1], state);
    }
}

static void fade_lamp(int relay, int target_state) {
    int current_state = gpioRead(relay_pins[relay - 1]);
    if (current_state == target_state) return;
    int step_delay = 1000000 / PWM_FREQUENCY;
    int steps = FADE_DURATION * PWM_FREQUENCY;
    int step = 1;
    while (running && step <= steps) {
        int duty = (target_state == 1) ? (PWM_RANGE * step / steps) : (PWM_RANGE - PWM_RANGE * step / steps);
        if (duty < 0) duty = 0;
        if (duty > PWM_RANGE) duty = PWM_RANGE;
        gpioPWM(relay_pins[relay - 1], duty);
        gpioDelay(step_delay);
        step++;
    }
    gpioPWM(relay_pins[relay - 1], target_state ? PWM_RANGE : 0);
    gpioWrite(relay_pins[relay - 1], target_state);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioSetMode(relay_pins[i], PI_OUTPUT);
        gpioWrite(relay_pins[i], 0);
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    int hour, minute, second, relay, state;
    while (running) {
        if (parse_schedule(SCHEDULE_FILE, &hour, &minute, &second, &relay, &state) == 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            if (!tm_info) continue;
            int current_hour = tm_info->tm_hour;
            int current_minute = tm_info->tm_min;
            int current_second = tm_info->tm_sec;
            if (hour == current_hour && minute == current_minute && second == current_second) {
                fade_lamp(relay, state);
            }
        }
        gpioDelay(1000000);
    }
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 0);
    }
    gpioTerminate();
    return 0;
}

