/*
 * rudimentary_theremin.c — Raspberry Pi Zero W
 *
 * Reads distance from an HC-SR04 ultrasonic sensor (trigger on GPIO23, echo on
 * GPIO24) and maps it to a PWM frequency on GPIO18.  The program runs at ~50 Hz
 * and enforces a 60 ms minimum between measurements to stay within the
 * HC-SR04's 60 ms / 5 cm / 38 kHz bandwidth limit.
 *
 * Build:  gcc -O2 -Wall -Wextra -o rudimentary_theremin rudimentary_theremin.c -lpigpio -lrt
 * Run:    sudo ./rudimentary_theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define TRIGGER_PIN  23
#define ECHO_PIN     24
#define BUZZER_PIN   18

/* ---- Physical constants ---- */
#define SPEED_OF_SOUND_CM_PER_US  0.0343   /* cm/µs at 20 °C */
#define MIN_DISTANCE_CM           2.0      /* HC-SR04 minimum range */
#define MAX_DISTANCE_CM           400.0    /* HC-SR04 maximum range */

/* ---- Theremin mapping ---- */
#define MIN_FREQUENCY_HZ          200
#define MAX_FREQUENCY_HZ          1000

/* ---- Timing ---- */
#define TRIGGER_PULSE_US          10       /* HC-SR04 requires >= 10 µs */
#define ECHO_TIMEOUT_US           30000    /* 30 ms — covers ~5 m round trip */
#define LOOP_PERIOD_US            20000    /* 50 Hz main-loop cadence */
#define MEASUREMENT_GAP_US        60000    /* 60 ms between HC-SR04 reads */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_pigpio_ready = 0;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Returns distance in cm, or -1.0 on timeout / error.                 */
static float read_distance(void)
{
    /* Issue a 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout if sensor absent or stuck) */
    uint32_t start_wait = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_wait) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return -1.0f;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1.0f;
        }
