    uint32_t echo_end = gpioTick();

    uint32_t pulse_us = echo_end - echo_start;
    float distance = (float)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of HC-SR04 range\n",
                distance);
        return -1.0f;
    }
    return distance;
}

/* ------------------------------------------------------------------ */
static int map_distance_to_frequency(float distance)
{
    if (distance < 0.0f)
        return MIN_FREQUENCY_HZ;

    float freq = MIN_FREQUENCY_HZ +
                 (distance / MAX_DISTANCE_CM) *
                 (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ);

    if (freq < MIN_FREQUENCY_HZ)
        freq = MIN_FREQUENCY_HZ;
    if (freq > MAX_FREQUENCY_HZ)
        freq = MAX_FREQUENCY_HZ;

