#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_FREQ 1000
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_led_color(float red, float green, float blue) {
    if (red < 0.0f || red > 1.0f || green < 0.0f || green > 1.0f || blue < 0.0f || blue > 1.0f) {
        fprintf(stderr, "Error: Color values must be between 0.0 and 1.0\n");
        return -1;
    }

    int r = (int)(red   * PWM_RANGE);
    int g = (int)(green * PWM_RANGE);
    int b = (int)(blue  * PWM_RANGE);

    if (gpioPWM(RED_PIN,   r) < 0) return -1;
    if (gpioPWM(GREEN_PIN, g) < 0) return -1;
    if (gpioPWM(BLUE_PIN,  b) < 0) return -1;

    return 0;
}

static void turn_off_led(void) {
    gpioPWM(RED_PIN,   0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN,  0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN,   PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency\n");
        turn_off_led();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) < 0) {
        fprintf(stderr, "Error: Failed to set PWM range\n");
        turn_off_led();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        turn_off_led();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("RGB LED color transition started. Press Ctrl+C to exit.\n");

    while (running) {
        double time = (double)clock() / (double)CLOCKS_PER_SEC;
        float proximity = (float)(sin(time) * 0.5 + 0.5);

        float red   = proximity;
        float green = 1.0f - proximity;
        float blue  = 0.0f;

        if (set_led_color(red, green, blue) < 0) {
            fprintf(stderr, "Error: Failed to set LED color\n");
            break;
        }

        usleep(50000);
    }

    turn_off_led();
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

