#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define DEBOUNCE_US 50000
#define PWM_FREQ 1000
#define PWM_RANGE 1000
#define PWM_DUTY 500

typedef struct {
    int frequency;
    int duration;
} Note;

static const Note melody[] = {
    {262, 500}, {294, 500}, {330, 500}, {349, 500},
    {392, 500}, {440, 500}, {494, 500}, {523, 500}
};
static const int melody_length = sizeof(melody) / sizeof(melody[0]);

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t button_pressed = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)tick; (void)userdata;
    if (level == 0) {
        static uint32_t last_tick = 0;
        if (tick - last_tick > DEBOUNCE_US) {
            button_pressed = 1;
            last_tick = tick;
        }
    }
}

static int play_tone(int frequency, int duration_ms) {
    if (frequency <= 0) {
        gpioPWM(BUZZER_PIN, 0);
        gpioDelay(duration_ms * 1000);
        return 0;
    }
    if (gpioSetPWMfrequency(BUZZER_PIN, frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for %d Hz\n", frequency);
        return -1;
    }
    if (gpioPWM(BUZZER_PIN, PWM_DUTY) < 0) {
        fprintf(stderr, "Error: gpioPWM start failed for %d Hz\n", frequency);
        return -1;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioPWM(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM stop failed for %d Hz\n", frequency);
        return -1;
    }
    return 0;
}

static int play_melody(void) {
    for (int i = 0; i < melody_length; i++) {
        if (!running) return 0;
        if (play_tone(melody[i].frequency, melody[i].duration) < 0) {
            gpioPWM(BUZZER_PIN, 0);
            return -1;
        }
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for button pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for button pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for buzzer pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(BUZZER_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for buzzer pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(BUZZER_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for buzzer pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM initial stop failed for buzzer pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed for button pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Doorbell ready. Press the button (GPIO17) to play the melody. Ctrl+C to exit.\n");

    while (running) {
        if (button_pressed) {
            button_pressed = 0;
            printf("Button pressed! Playing melody...\n");
            if (play_melody() < 0) {
                fprintf(stderr, "Error: melody playback failed\n");
            }
            if (!running) break;
            printf("Melody finished.\n");
        }
        gpioDelay(10000);
    }

    gpioPWM(BUZZER_PIN, 0);
    gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, NULL, NULL);
    gpioTerminate();
    printf("Doorbell shut down cleanly.\n");
    return EXIT_SUCCESS;
}

