#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5
#define THRESHOLD 3
#define LOG_FILE "vibration_events.log"
#define DEFAULT_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int log_event(int value) {
    char ts[32];
    if (get_timestamp(ts, sizeof(ts)) != 0) {
        fprintf(stderr, "Error: failed to generate timestamp for log entry.\n");
        return -1;
    }
    if (fprintf(log_file, "%s,%d\n", ts, value) < 0) {
        fprintf(stderr, "Error: failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file: %s\n", strerror(errno));
    }
    return 0;
}

static void check_threshold(const int *window, int count) {
    int high_count = 0;
    for (int i = 0; i < count; i++) {
        if (window[i] == 1) {
            high_count++;
        }
    }
    if (high_count >= THRESHOLD) {
        char ts[32];
        if (get_timestamp(ts, sizeof(ts)) == 0) {
            printf("EARTHQUAKE ALERT! Timestamp: %s\n", ts);
            fflush(stdout);
        } else {
            fprintf(stderr, "Error: failed to generate timestamp for alert.\n");
        }
    }
}

int main(int argc, char *argv[]) {
    int timeout_ms = DEFAULT_TIMEOUT_MS;

    if (argc > 1) {
        char *endptr;
        long val = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || val <= 0 || val > 10000) {
            fprintf(stderr, "Error: timeout must be a positive integer (1-10000 ms).\n");
            return EXIT_FAILURE;
        }
        timeout_ms = (int)val;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO%d.\n", GPIO_PIN);
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n", strerror(errno));
    }

    int window[WINDOW_SIZE];
    int window_index = 0;
    int window_count = 0;

    printf("Monitoring SW-420 vibration sensor on GPIO%d (timeout=%d ms). Press Ctrl+C to exit.\n",
           GPIO_PIN, timeout_ms);
    fflush(stdout);

    while (program_running) {
        int event = gpioRead(GPIO_PIN);
        if (event < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", GPIO_PIN);
            break;
        }

        window[window_index] = event;
        window_index = (window_index + 1) % WINDOW_SIZE;
        if (window_count < WINDOW_SIZE) {
            window_count++;
        }

        if (log_event(event) != 0) {
            fprintf(stderr, "Warning: logging failed for this event.\n");
        }

        check_threshold(window, window_count);

        if (gpioDelay(timeout_ms * 1000) < 0) {
            fprintf(stderr, "Warning: gpioDelay interrupted.\n");
        }
    }

    printf("\nShutting down...\n");
    fflush(stdout);

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Warning: error closing log file: %s\n", strerror(errno));
        }
        log_file = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

