    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO%d.\n", GPIO_PIN);
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n", strerror(errno));
    }

    int window[WINDOW_SIZE];
    int window_index = 0;
    int window_count = 0;

    printf("Monitoring SW-420 vibration sensor on GPIO%d (timeout=%d ms). Press Ctrl+C to exit.\n",
           GPIO_PIN, timeout_ms);
    fflush(stdout);

    while (program_running) {
        int event = gpioRead(GPIO_PIN);
        if (event < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", GPIO_PIN);
            break;
        }

        window[window_index] = event;
        window_index = (window_index + 1) % WINDOW_SIZE;
        if (window_count < WINDOW_SIZE) {
            window_count++;
        }

        if (log_event(event) != 0) {
            fprintf(stderr, "Warning: logging failed for this event.\n");
        }

        check_threshold(window, window_count);

        if (gpioDelay(timeout_ms * 1000) < 0) {
            fprintf(stderr, "Warning: gpioDelay interrupted.\n");
        }
    }

    printf("\nShutting down...\n");
    fflush(stdout);

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Warning: error closing log file: %s\n", strerror(errno));
        }
        log_file = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

