#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* LSM303DLHC Magnetometer I2C address (7-bit, SA1 tied to GND) */
#define LSM303_MAG_ADDR 0x1E

/* LSM303DLHC Magnetometer register addresses */
#define LSM303_MAG_MR_REG 0x02
#define LSM303_MAG_OUT_X_H 0x03
#define LSM303_MAG_OUT_X_L 0x04
#define LSM303_MAG_OUT_Y_H 0x05
#define LSM303_MAG_OUT_Y_L 0x06
#define LSM303_MAG_OUT_Z_H 0x07
#define LSM303_MAG_OUT_Z_L 0x08

/* Hard-iron calibration offsets (replace with your calibrated values) */
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

/* Global variables for signal handling */
static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

/* Function prototypes */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z);
static void calibrate_data(int16_t x, int16_t y, int16_t z, int16_t *cx, int16_t *cy, int16_t *cz);
static float calculate_heading(int16_t x, int16_t y);
static const char *determine_compass_direction(float heading);
static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z, float heading);
static void signal_handler(int sig);
static void cleanup(void);

/* Write a single byte to an I2C register */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a single byte from an I2C register */
static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read raw magnetometer data from the LSM303DLHC */
static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_h, x_l, y_h, y_l, z_h, z_l;

    if (i2c_read_reg(fd, LSM303_MAG_OUT_X_H, &x_h) < 0) return -1;
    if (i2c_read_reg(fd, LSM303_MAG_OUT_X_L, &x_l) < 0) return -1;
    if (i2c_read_reg(fd, LSM303_MAG_OUT_Y_H, &y_h) < 0) return -1;
    if (i2c_read_reg(fd, LSM303_MAG_OUT_Y_L, &y_l) < 0) return -1;
    if (i2c_read_reg(fd, LSM303_MAG_OUT_Z_H, &z_h) < 0) return -1;
    if (i2c_read_reg(fd, LSM303_MAG_OUT_Z_L, &z_l) < 0) return -1;

    *x = (int16_t)((x_h << 8) | x_l);
    *y = (int16_t)((y_h << 8) | y_l);
    *z = (int16_t)((z_h << 8) | z_l);

    return 0;
}

/* Apply hard-iron calibration offsets */
static void calibrate_data(int16_t x, int16_t y, int16_t z, int16_t *cx, int16_t *cy, int16_t *cz) {
    *cx = x - X_OFFSET;
    *cy = y - Y_OFFSET;
    *cz = z - Z_OFFSET;
}

/* Calculate heading in degrees from calibrated X and Y values */
static float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2f((float)y, (float)x) * 180.0f / M_PI;
    if (heading < 0) {
        heading += 360.0f;
    }
    return heading;
}

/* Determine compass direction from heading */
static const char *determine_compass_direction(float heading) {
    if (heading < 22.5f || heading >= 337.5f) return "N";
    if (heading < 67.5f) return "NE";
    if (heading < 112.5f) return "E";
    if (heading < 157.5f) return "SE";
    if (heading < 202.5f) return "S";
    if (heading < 247.5f) return "SW";
    if (heading < 292.5f) return "W";
    return "NW";
}

/* Log data to CSV file */
static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z, float heading) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, %d, %d, %d, %.2f\n", timestamp, x, y, z, heading) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    /* Open I2C bus */
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    /* Set I2C slave address */
    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", LSM303_MAG_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    /* Initialize magnetometer: continuous conversion mode */
    if (i2c_write_reg(i2c_fd, LSM303_MAG_MR_REG, 0x00) < 0) {
        fprintf(stderr, "Error initializing magnetometer\n");
        cleanup();
        return 1;
    }

    /* Open log file in append mode */
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    /* Write header if the file is newly created */
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n");
        fflush(log_file);
    }

    printf("Magnetometer data logging started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        int16_t raw_x, raw_y, raw_z;
        int16_t cal_x, cal_y, cal_z;
        float heading;
        const char *direction;

        if (read_magnetometer(i2c_fd, &raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "Error reading magnetometer data, skipping sample.\n");
        } else {
            calibrate_data(raw_x, raw_y, raw_z, &cal_x, &cal_y, &cal_z);
            heading = calculate_heading(cal_x, cal_y);
            direction = determine_compass_direction(heading);

            if (log_data(log_file, cal_x, cal_y, cal_z, heading) < 0) {
                fprintf(stderr, "Error logging data.\n");
            }

            printf("Direction: %s, Heading: %.2f degrees\n", direction, heading);
        }

        sleep(1);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

