#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 200000  /* 200 ms in microseconds */

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t relay_state = 0;  /* 0 = OFF, 1 = ON */
static volatile uint32_t last_touch_tick = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown on Ctrl+C / SIGINT              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Append a JSON state-change entry to relay_log.json                 */
/* ------------------------------------------------------------------ */
static int log_relay_state(int state)
{
    FILE *fp;
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    fp = fopen("relay_log.json", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening relay_log.json: %s\n",
                strerror(errno));
        return -1;
    }

    if (fprintf(fp, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n",
                timestamp, state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "Error writing to relay_log.json: %s\n",
                strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing relay_log.json: %s\n",
                strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — runs in a pigpio thread                      */
/* ------------------------------------------------------------------ */
static void touch_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    /* Only act on rising edge (touch detected) */
    if (level != 1) {
        return;
    }

    /* Debounce: ignore touches that arrive too soon after the last one */
    uint32_t elapsed = tick - last_touch_tick;
    if (elapsed < DEBOUNCE_DELAY_US) {
        return;
    }
    last_touch_tick = tick;

    /* Toggle relay state */
    relay_state = !relay_state;

    /* Drive the relay pin */
    if (gpioWrite(RELAY_PIN, relay_state) < 0) {
        fprintf(stderr, "gpioWrite failed on relay pin %d\n", RELAY_PIN);
        return;
    }

    /* Log the state change */
    if (log_relay_state(relay_state) < 0) {
        fprintf(stderr, "Failed to log relay state change\n");
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure relay pin as output and force it OFF --- */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed on relay pin %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite failed on relay pin %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    relay_state = 0;

    /* --- Configure touch sensor pin as input with pull-down --- */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed on touch pin %d\n",
                TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed on touch pin %d\n",
                TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Register alert callback for rising-edge touch detection --- */
    if (gpioSetAlertFunc(TOUCH_SENSOR_PIN, touch_callback) < 0) {
        fprintf(stderr, "gpioSetAlertFunc failed on touch pin %d\n",
                TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handler for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch-controlled relay running. Press Ctrl+C to exit.\n");

    /* --- Main loop: sleep until signal received --- */
    while (running) {
        gpioDelay(100000);  /* 100 ms */
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");

    /* Force relay OFF */
    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to turn relay OFF during shutdown\n");
    }
    relay_state = 0;

    /* Log the final OFF state */
    if (log_relay_state(relay_state) < 0) {
        fprintf(stderr, "Warning: failed to log final relay state\n");
    }

    /* Clean up pigpio resources */
    gpioTerminate();

    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

