#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

#define MOISTURE_THRESHOLD 30
#define IRRIGATION_DURATION 5
#define RELAY_GAP 1
#define POLL_INTERVAL 10

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static const int relay_pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
static const int num_relays = 4;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    for (int i = 0; i < num_relays; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO%d as output\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(relay_pins[i], 1) != 0) {
            fprintf(stderr, "Failed to initialise GPIO%d high\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void deactivate_all_relays(void) {
    for (int i = 0; i < num_relays; i++) {
        gpioWrite(relay_pins[i], 1);
    }
}

static void cleanup(void) {
    deactivate_all_relays();
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int simulate_moisture(void) {
    return rand() % 101;
}

static void log_irrigation(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s - Relay %d - Moisture Level: %d\n", timestamp, relay_number, moisture_level) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

static void irrigate(int relay_number, int moisture_level) {
    if (gpioWrite(relay_pins[relay_number - 1], 0) != 0) {
        fprintf(stderr, "Failed to activate relay %d\n", relay_number);
        return;
    }
    log_irrigation(relay_number, moisture_level);
    gpioDelay(IRRIGATION_DURATION * 1000000);
    if (gpioWrite(relay_pins[relay_number - 1], 1) != 0) {
        fprintf(stderr, "Failed to deactivate relay %d\n", relay_number);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    log_file = fopen("irrigation_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open irrigation_log.txt: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    srand((unsigned int)time(NULL));

    while (running) {
        int moisture_level = simulate_moisture();
        printf("Simulated Moisture Level: %d\n", moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD) {
            for (int i = 0; i < num_relays && running; i++) {
                irrigate(i + 1, moisture_level);
                if (i < num_relays - 1 && running) {
                    gpioDelay(RELAY_GAP * 1000000);
                }
            }
        }

        if (running) {
            gpioDelay(POLL_INTERVAL * 1000000);
        }
    }

    cleanup();
    return 0;
}

