/*
 * Automated Plant Watering System — Raspberry Pi Zero W
 *
 * Hardware:
 *   - Two SG90 servo motors (5V, 90° range, 500–2500 µs pulse)
 *   - Valve servo  -> GPIO17 (BCM 17, physical pin 11)
 *   - Nozzle servo -> GPIO18 (BCM 18, physical pin 12)
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o watering watering.c -lthe_driver_library -lrt
 *
 * The library API is assumed to be:
 *   int servo_set_pulse(int gpio, int pulse_us);  // returns 0 on success
 *   void servo_cleanup(void);
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

#define VALVE_GPIO        17
#define NOZZLE_GPIO       18

#define VALVE_OPEN_US     1500   /* 90°  */
#define VALVE_CLOSE_US    500    /* 0°   */
#define NOZZLE_MIN_US     500    /* 0°   */
#define NOZZLE_MAX_US     2500   /* 180° */
#define NOZZLE_STEP_US    500    /* 45°  */

#define MOISTURE_THRESHOLD 50
#define SPRAY_DURATION_S   5
#define CYCLE_DELAY_S      5
#define NOZZLE_HOLD_S      2
#define MAX_RETRIES        3
#define RETRY_DELAY_MS     100

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

static void sleep_s(unsigned int s)
{
    sleep_ms(s * 1000);
}

static int set_servo_retry(int gpio, int pulse_us)
{
    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        if (servo_set_pulse(gpio, pulse_us) == 0)
            return 0;
        fprintf(stderr,
                "Warning: servo_set_pulse(gpio=%d, %d us) failed (attempt %d/%d)\n",
                gpio, pulse_us, attempt, MAX_RETRIES);
        sleep_ms(RETRY_DELAY_MS);
    }
    fprintf(stderr,
            "Error: servo_set_pulse(gpio=%d, %d us) failed after %d retries\n",
            gpio, pulse_us, MAX_RETRIES);
    return -1;
}

static void stop_servos(void)
{
    /* Library API: servo_set_pulse with 0 pulse width stops the servo. */
    (void)servo_set_pulse(VALVE_GPIO, 0);
    (void)servo_set_pulse(NOZZLE_GPIO, 0);
}

static void cleanup_and_exit(int exit_code)
{
    stop_servos();
    servo_cleanup();
    exit(exit_code);
}

/* ------------------------------------------------------------------ */
/* Watering cycle                                                      */
/* ------------------------------------------------------------------ */

static void water_plant(int moisture)
{
    printf("Moisture level: %d%% (threshold %d%%)\n",
           moisture, MOISTURE_THRESHOLD);

    if (moisture >= MOISTURE_THRESHOLD) {
        printf("Moisture sufficient; skipping watering cycle.\n");
        return;
    }

    printf("Watering cycle started.\n");

    /* ---- Open valve ---- */
    if (set_servo_retry(VALVE_GPIO, VALVE_OPEN_US) != 0) {
        fprintf(stderr, "Critical: failed to open valve. Aborting cycle.\n");
        return;
    }
    printf("Valve opened (90°).\n");

    /* ---- Nozzle sweep: 0°, 45°, 90°, 135°, 180° ---- */
    const int nozzle_positions_us[] = {
        NOZZLE_MIN_US,
        NOZZLE_MIN_US + NOZZLE_STEP_US,
        NOZZLE_MIN_US + 2 * NOZZLE_STEP_US,
        NOZZLE_MIN_US + 3 * NOZZLE_STEP_US,
        NOZZLE_MAX_US
    };
    const int num_positions =
        sizeof(nozzle_positions_us) / sizeof(nozzle_positions_us[0]);

    for (int i = 0; i < num_positions && g_running; ++i) {
        int pos = nozzle_positions_us[i];

        if (set_servo_retry(NOZZLE_GPIO, pos) != 0) {
            fprintf(stderr,
                    "Warning: nozzle set to %d us failed; continuing.\n",
                    pos);
            continue;
        }

        printf("Nozzle at %d us (%d°).\n", pos, pos / 500);

        /* Hold spray for NOZZLE_HOLD_S seconds */
        for (int s = 0; s < NOZZLE_HOLD_S && g_running; ++s)
            sleep_s(1);
    }

    /* ---- Spray duration ---- */
    for (int s = 0; s < SPRAY_DURATION_S && g_running; ++s)
        sleep_s(1);

    /* ---- Close valve ---- */
    if (set_servo_retry(VALVE_GPIO, VALVE_CLOSE_US) != 0)
        fprintf(stderr, "Warning: failed to close valve.\n");
    else
        printf("Valve closed (0°).\n");

    printf("Watering cycle complete.\n");
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    install_signal_handlers();

    /* Initialize library */
    if (servo_set_pulse(VALVE_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize valve GPIO %d.\n",
                VALVE_GPIO);
        return EXIT_FAILURE;
    }
    if (servo_set_pulse(NOZZLE_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize nozzle GPIO %d.\n",
                NOZZLE_GPIO);
        servo_cleanup();
        return EXIT_FAILURE;
    }

    printf("Plant watering system started.\n");
    printf("Valve  : GPIO%d (initial pulse 0)\n", VALVE_GPIO);
    printf("Nozzle : GPIO%d (initial pulse 0)\n", NOZZLE_GPIO);
    printf("Threshold: %d%%\n", MOISTURE_THRESHOLD);
    printf("Press Ctrl+C to exit.\n\n");

    /* Simulated moisture sequence: 20, 40, 60, 80, 100 */
    const int moisture_levels[] = {20, 40, 60, 80, 100};
    const int num_levels =
        sizeof(moisture_levels) / sizeof(moisture_levels[0]);
    int level_idx = 0;

    while (g_running) {
        int moisture = moisture_levels[level_idx];
        printf("--- Cycle %d ---\n", level_idx + 1);
        water_plant(moisture);

        /* Wait CYCLE_DELAY_S seconds between cycles */
        for (int s = 0; s < CYCLE_DELAY_S && g_running; ++s)
            sleep_s(1);

        level_idx = (level_idx + 1) % num_levels;
    }

    printf("\nShutting down...\n");
    cleanup_and_exit(EXIT_SUCCESS);
    return EXIT_SUCCESS; /* unreachable */
}

