/*
 * MPU-6050 Gyroscope Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MPU-6050 VCC  -> Pi 3V3  (Pin 1)
 *   MPU-6050 GND  -> Pi GND  (Pin 9)
 *   MPU-6050 SCL  -> Pi GPIO3 / I2C1 SCL (Pin 5)
 *   MPU-6050 SDA  -> Pi GPIO2 / I2C1 SDA (Pin 3)
 *
 * Build:  gcc -O2 -Wall -Wextra -o gyro_log gyro_log.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MPU-6050 constants (datasheet) ---- */
#define MPU6050_ADDR        0x68
#define MPU6050_SMPLRT_DIV  0x19
#define MPU6050_CONFIG      0x1A
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_PWR_MGMT_1  0x6B

#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "gyro_log.txt"
#define SAMPLE_HZ 10
#define SAMPLE_US (1000000 / SAMPLE_HZ)

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_burst(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg ptr 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read len bytes back */
    ssize_t n = read(fd, dst, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int mpu6050_init(int fd)
{
    /* Wake up: clear SLEEP bit in PWR_MGMT_1 */
    if (i2c_write_byte(fd, MPU6050_PWR_MGMT_1, 0x00) != 0)
        return -1;
    usleep(100000); /* allow oscillator to stabilize */

    /* Sample rate divider = 7  ->  1 kHz / (1 + 7) = 125 Hz internal */
    if (i2c_write_byte(fd, MPU6050_SMPLRT_DIV, 0x07) != 0)
        return -1;

    /* DLPF_CFG = 3  ->  44 Hz bandwidth, 1 kHz internal */
    if (i2c_write_byte(fd, MPU6050_CONFIG, 0x03) != 0)
        return -1;

    /* FS_SEL = 3  ->  +/- 250 deg/s full scale */
    if (i2c_write_byte(fd, MPU6050_GYRO_CONFIG, 0x00) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int mpu6050_read_gyro(int fd, float *gx, float *gy, float *gz)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, MPU6050_GYRO_XOUT_H, buf, sizeof(buf)) != 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    /* FS_SEL = 0  ->  131 LSB per deg/s */
    *gx = (float)raw_x / 131.0f;
    *gy = (float)raw_y / 131.0f;
    *gz = (float)raw_z / 131.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float gx, float gy, float gz)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            gx, gy, gz);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Quick presence check: try reading PWR_MGMT_1 */
    uint8_t who = 0;
    if (i2c_read_burst(g_i2c_fd, MPU6050_PWR_MGMT_1, &who, 1) != 0) {
        fprintf(stderr, "MPU-6050 not responding at 0x%02X on %s\n",
                MPU6050_ADDR, I2C_BUS);
        cleanup();
        return EXIT_FAILURE;
    }

    if (mpu6050_init(g_i2c_fd) != 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_fp, "# MPU-6050 gyro log started\n");
    fprintf(g_log_fp, "# timestamp,x_dps,y_dps,z_dps\n");
    fflush(g_log_fp);

    printf("Logging MPU-6050 data to %s at %d Hz. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_HZ);

    while (g_running) {
        float gx, gy, gz;
        if (mpu6050_read_gyro(g_i2c_fd, &gx, &gy, &gz) != 0) {
            fprintf(stderr, "Read error — continuing.\n");
        } else {
            log_data(g_log_fp, gx, gy, gz);
        }
        usleep(SAMPLE_US);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

