#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

/* L293D input pins (BCM numbering) */
#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22

/* Button pins (BCM numbering) */
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

/* Motor parameters */
#define STEPS_PER_ROTATION 512
#define STEP_DELAY_US 3000  /* 3 ms between steps */

/* Debounce window in microseconds */
#define DEBOUNCE_US 200000

/* Global flag for graceful shutdown */
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Helper: de-energize all coils (reduce power consumption / heating) */
/* ------------------------------------------------------------------ */
static void motor_off(void) {
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
}

/* ------------------------------------------------------------------ */
/* Helper: perform a single full-step (single-coil) excitation        */
/* ------------------------------------------------------------------ */
static int step_motor(int in1, int in2, int in3, int in4) {
    if (gpioWrite(IN1, in1) < 0) return -1;
    if (gpioWrite(IN2, in2) < 0) return -1;
    if (gpioWrite(IN3, in3) < 0) return -1;
    if (gpioWrite(IN4, in4) < 0) return -1;
    gpioDelay(STEP_DELAY_US);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Rotate the motor: +ve steps = clockwise, -ve steps = counter-clockwise */
/* ------------------------------------------------------------------ */
static int rotate_motor(int steps) {
    int i;
    int abs_steps = abs(steps);

    for (i = 0; i < abs_steps && running; i++) {
        if (steps > 0) {
            /* Clockwise: full-step sequence */
            if (step_motor(1, 0, 0, 0) < 0) return -1;
            if (step_motor(0, 1, 0, 0) < 0) return -1;
            if (step_motor(0, 0, 1, 0) < 0) return -1;
            if (step_motor(0, 0, 0, 1) < 0) return -1;
        } else {
            /* Counter-clockwise: reverse full-step sequence */
            if (step_motor(0, 0, 0, 1) < 0) return -1;
            if (step_motor(0, 0, 1, 0) < 0) return -1;
            if (step_motor(0, 1, 0, 0) < 0) return -1;
            if (step_motor(1, 0, 0, 0) < 0) return -1;
        }
    }

    /* De-energize coils after rotation */
    motor_off();
    return 0;
}

/* ------------------------------------------------------------------ */
/* Lock the door (clockwise)                                           */
/* ------------------------------------------------------------------ */
static int lock_door(void) {
