#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29
#define RELAY_PIN      18
#define DISTANCE_THRESHOLD_CM 50
#define POLL_DELAY_US  100000  /* 100 ms */

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET              0x0003
#define REG_SYSTEM_MODE_START_STOP  0x0000
#define REG_RESULT_RANGE_STATUS     0x0089
#define REG_RESULT_DISTANCE         0x0096

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit value to a 16-bit register address (big-endian on bus). */
static int vl53l1x_write16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* Read a 16-bit value from a 16-bit register address. */
static int vl53l1x_read16(int handle, uint16_t reg, uint16_t *out)
{
    char reg_buf[2];
    char data_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) < 0)
        return -1;

    if (i2cReadDevice(handle, data_buf, 2) != 2)
        return -1;

    *out = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* Read a 32-bit value from a 16-bit register address. */
static int vl53l1x_read32(int handle, uint16_t reg, uint32_t *out)
{
    char reg_buf[2];
    char data_buf[4];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) < 0)
        return -1;

    if (i2cReadDevice(handle, data_buf, 4) != 4)
        return -1;

    *out = ((uint32_t)(uint8_t)data_buf[0] << 24) |
           ((uint32_t)(uint8_t)data_buf[1] << 16) |
           ((uint32_t)(uint8_t)data_buf[2] << 8)  |
           (uint32_t)(uint8_t)data_buf[3];
    return 0;
}

static int init_vl53l1x(int handle)
{
    /* Soft reset */
    if (vl53l1x_write16(handle, REG_SOFT_RESET, 0x0001) < 0) {
        fprintf(stderr, "Error: failed to write soft reset register.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Start ranging (mode = 0x40: back-to-back ranging) */
    if (vl53l1x_write16(handle, REG_SYSTEM_MODE_START_STOP, 0x0040) < 0) {
        fprintf(stderr, "Error: failed to start ranging.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */
    return 0;
}

static int read_distance_cm(int handle, uint16_t *distance_cm)
{
    uint16_t status;
    uint32_t raw;

    if (vl53l1x_read16(handle, REG_RESULT_RANGE_STATUS, &status) < 0) {
        fprintf(stderr, "Error: failed to read range status.\n");
        return -1;
    }

    /* Bit 0 of the status register indicates data ready */
    if ((status & 0x0001) == 0) {
        return 1; /* not ready yet */
    }

