        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X.\n",
                I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_vl53l1x(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance_cm;
        int rc = read_distance_cm(g_i2c_handle, &distance_cm);

        if (rc == 0) {
            printf("Distance: %u cm\n", distance_cm);
            gpioWrite(RELAY_PIN, (distance_cm <= DISTANCE_THRESHOLD_CM) ? 1 : 0);
        } else if (rc < 0) {
            /* I2C error: ensure relay is off for safety */
            gpioWrite(RELAY_PIN, 0);
        }
        /* rc == 1: data not ready yet, just skip this cycle */

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(RELAY_PIN, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
