/*
 * MPU-6050 Gyroscope Reader for Raspberry Pi 3 Model B+
 * Bus: /dev/i2c-1  Address: 0x68 (AD0 tied to GND)
 * Wiring: SDA -> GPIO2 (BCM), SCL -> GPIO3 (BCM), VDD -> 3V3, GND -> GND
 * Build: gcc -O2 -Wall -o mpu6050_gyro mpu6050_gyro.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68

#define REG_SMPLRT_DIV 0x19
#define REG_CONFIG     0x1A
#define REG_GYRO_CFG   0x1B
#define REG_GYRO_XOUT_H 0x43
#define REG_PWR_MGMT_1 0x6B

#define GYRO_SCALE_250  131.0f
#define GYRO_SCALE_500  65.5f
#define GYRO_SCALE_1000 32.8f
#define GYRO_SCALE_2000 16.4f

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, dst, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read burst from 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd)
{
    /* Wake the device (SLEEP bit = 0) */
    if (i2c_write_reg8(fd, REG_PWR_MGMT_1, 0x00) < 0)
        return -1;
    usleep(100000); /* allow oscillator to stabilize */

    /* Sample rate divider = 7 -> 1 kHz / (1 + 7) = 125 Hz */
    if (i2c_write_reg8(fd, REG_SMPLRT_DIV, 0x07) < 0)
        return -1;

    /* DLPF_CFG = 3 -> 44 Hz bandwidth, 1 kHz internal sample */
    if (i2c_write_reg8(fd, REG_CONFIG, 0x03) < 0)
        return -1;

    /* FS_SEL = 3 -> +/- 2000 dps */
    if (i2c_write_reg8(fd, REG_GYRO_CFG, 0x18) < 0)
        return -1;

    return 0;
}

static int mpu6050_read_gyro(int fd, float *gx, float *gy, float *gz)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, REG_GYRO_XOUT_H, buf, sizeof(buf)) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    *gx = (float)raw_x / GYRO_SCALE_2000f;
    *gy = (float)raw_y / GYRO_SCALE_2000f;
    *gz = (float)raw_z / GYRO_SCALE_2000f;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Quick presence check: read PWR_MGMT_1 */
    uint8_t who = 0;
    if (i2c_read_burst(fd, REG_PWR_MGMT_1, &who, 1) < 0) {
        fprintf(stderr, "MPU-6050 not responding at 0x%02X\n", MPU6050_ADDR);
        close(fd);
        return EXIT_FAILURE;
    }

    if (mpu6050_init(fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialized at 0x%02X on %s. Logging 125 Hz gyro data (Ctrl+C to stop).\n",
           MPU6050_ADDR, I2C_BUS);

    while (g_running) {
        float gx, gy, gz;
        if (mpu6050_read_gyro(fd, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "Gyro read error; continuing.\n");
            usleep(10000);
            continue;
        }
        printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s\n", gx, gy, gz);
        usleep(8000); /* ~125 Hz */
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

