/*
 * Automated Plant Watering System — Raspberry Pi 4 Model B
 *
 * Four 5 V relay modules on BCM GPIO17, GPIO18, GPIO27, GPIO22.
 * Active-low relay: HIGH = inactive, LOW = active.
 *
 * Build:  gcc -O2 -Wall -Wextra -o watering watering.c -lgpiod
 * Run:    sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS      4
#define WATERING_TIME   5          /* seconds per relay */
#define CYCLE_PERIOD    86400      /* 24 hours in seconds */
#define POLL_INTERVAL   60         /* seconds between relay activations */
#define LOG_FILE        "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_cycle_start(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s\n", ts);
    } else {
        fprintf(fp, "<timestamp-error>\n");
    }

    if (fclose(fp) != 0)
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
}

/* ------------------------------------------------------------------ */
static int set_all_relays(struct gpiod_line_bulk *bulk, int value)
{
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_set_value(bulk->lines[i], value) < 0) {
            fprintf(stderr, "Failed to set GPIO%u to %d: %s\n",
                    relay_pins[i], value, strerror(errno));
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void deactivate_all(struct gpiod_line_bulk *bulk)
{
    (void)set_all_relays(bulk, 1);   /* HIGH = inactive */
}

/* ------------------------------------------------------------------ */
static int activate_relay(struct gpiod_line *line, int idx)
{
    printf("Activating relay on GPIO%u (BCM %u)...\n",
           relay_pins[idx], relay_pins[idx]);

    if (gpiod_line_set_value(line, 0) < 0) {   /* LOW = active */
        fprintf(stderr, "Failed to activate relay on GPIO%u: %s\n",
                relay_pins[idx], strerror(errno));
        return -1;
    }

    /* Sleep in 1-second increments so we can exit promptly on signal */
    for (int s = 0; s < WATERING_TIME && g_running; s++)
        sleep(1);

    if (gpiod_line_set_value(line, 1) < 0) {   /* HIGH = inactive */
        fprintf(stderr, "Failed to deactivate relay on GPIO%u: %s\n",
                relay_pins[idx], strerror(errno));
        return -1;
    }

    printf("Deactivated relay on GPIO%u.\n", relay_pins[idx]);
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk relay_bulk;
    struct gpiod_line *lines[NUM_RELAYS];
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip4");
