#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define LOG_FILE "smart_lighting.log"
#define NUM_RELAYS 4
#define PWM_FREQUENCY 1000
#define SUNRISE_DURATION 1800
#define STEP_DELAY 1

static const int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};
static volatile sig_atomic_t running = 1;

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMfrequency(relay_pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioPWM(relay_pins[i], 0) != 0) {
            fprintf(stderr, "Failed to initialize PWM on GPIO %d\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void set_relay_duty_cycle(int relay_index, int duty_cycle) {
    if (relay_index < 0 || relay_index >= NUM_RELAYS) {
        fprintf(stderr, "Invalid relay index: %d\n", relay_index);
        return;
    }
    if (duty_cycle < 0 || duty_cycle > 255) {
        fprintf(stderr, "Invalid duty cycle: %d\n", duty_cycle);
        return;
    }
    if (gpioPWM(relay_pins[relay_index], duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", relay_pins[relay_index]);
    }
}

static void cleanup(void) {
    log_message("Cleaning up GPIO and terminating pigpio...");
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioPWM(relay_pins[i], 0);
    }
    gpioTerminate();
    log_message("Cleanup complete.");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (initialize_gpio() != 0) {
        log_message("GPIO initialization failed. Exiting.");
        return 1;
    }
    log_message("GPIO initialized successfully.");

    int total_steps = SUNRISE_DURATION / STEP_DELAY;
    for (int step = 0; step <= total_steps && running; step++) {
        int duty_cycle = (int)(((float)step / total_steps) * 255.0f);
        if (duty_cycle > 255) duty_cycle = 255;

        for (int i = 0; i < NUM_RELAYS; i++) {
            set_relay_duty_cycle(i, duty_cycle);
        }

        char log_buffer[256];
        snprintf(log_buffer, sizeof(log_buffer),
                 "Step %d/%d, Duty Cycle: %d", step, total_steps, duty_cycle);
        log_message(log_buffer);

        if (step < total_steps) {
            gpioDelay(STEP_DELAY * 1000000);
        }
    }

    if (!running) {
        log_message("Sunrise interrupted by signal.");
    } else {
        log_message("Sunrise effect completed.");
    }

    cleanup();
    return 0;
}

