/* Circular buffer size */
#define BUFFER_SIZE 100

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Sampling period (microseconds) for 20 Hz */
#define SAMPLE_PERIOD_US 50000

/* Maximum re-initialization attempts on read failure */
#define MAX_REINIT_ATTEMPTS 3

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* Structure to hold gyroscope data */
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

/* Circular buffer */
static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;

/* Function prototypes */
static int initialize_i2c(void);
static int read_gyro_data(float *x, float *y, float *z);
static void add_to_buffer(float x, float y, float z);
static void check_threshold(float x, float y, float z);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* Initializes the I2C connection and configures the MPU-6050 */
static int initialize_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    /* Set sample rate divider to 7 (1 kHz / (1 + 7) = 125 Hz) */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_SMPLRT_DIV, 7) < 0) {
        fprintf(stderr, "Error writing to SMPLRT_DIV register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    /* Set DLPF configuration to 2 (44 Hz bandwidth, 42 Hz delay) */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_CONFIG, 2) < 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    /* Set gyro full scale range to +/- 250 deg/s (FS_SEL = 0) */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

/* Reads raw gyroscope data from the MPU-6050 and converts to deg/s */
static int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(i2c_handle, MPU6050_REG_GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    /* Convert to degrees/second (FS_SEL = 0 -> +/- 250 deg/s, 32768 counts) */
    *x = (float)raw_x / 32768.0f * 250.0f;
    *y = (float)raw_y / 32768.0f * 250.0f;
    *z = (float)raw_z / 32768.0f * 250.0f;

    return 0;
}

/* Adds data to the circular buffer */
static void add_to_buffer(float x, float y, float z) {
    gyro_buffer[buffer_index].timestamp = clock_gettime(CLOCK_REALTIME);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

/* Checks if any axis exceeds the threshold and controls the LED */
static void check_threshold(float x, float y, float z) {
    if (fabsf(x) > ANGULAR_VELOCITY_THRESHOLD ||
        fabsf(y) > ANGULAR_VELOCITY_THRESHOLD ||
        fabsf(z) > ANGULAR_VELOCITY_THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set LED pin as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Initialize I2C */
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        gpioTerminate();
        return 1;
    }

    /* Set up signal handling */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;
    int reinit_attempts = 0;

    /* Main loop */
    while (program_running) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);
            check_threshold(x, y, z);
            reinit_attempts = 0;
        } else {
            reinit_attempts++;
            fprintf(stderr, "Failed to read gyro data (attempt %d/%d)\n",
                    reinit_attempts, MAX_REINIT_ATTEMPTS);
            if (reinit_attempts >= MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max re-initialization attempts reached. Exiting.\n");
                break;
            }
            if (initialize_i2c() != 0) {
                fprintf(stderr, "I2C re-initialization failed. Exiting.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Cleanup */
    cleanup();
    return 0;
}

