#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS_PER_WORD 8
#define SPI_MODE 0
#define GPIO_CHIP "/dev/gpiochip0"
#define CS_LINE_OFFSET 8
#define LOG_FILE "gyro_log.txt"
#define SAMPLE_INTERVAL_US 10000
#define MAX_RETRIES 3

#define GYRO_XOUT_H 0x1D
#define GYRO_YOUT_H 0x1F
#define GYRO_ZOUT_H 0x21

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_line *cs_line = NULL;
static struct gpiod_chip *gpio_chip = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return 0;
}

static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx[7] = {0};
    uint8_t rx[7] = {0};
    int retries = 0;

    while (retries < MAX_RETRIES) {
        tx[0] = GYRO_XOUT_H | 0x80;
        if (gpiod_line_set_value(cs_line, 0) < 0) {
            fprintf(stderr, "Failed to assert CS: %s\n", strerror(errno));
            retries++;
            usleep(1000);
            continue;
        }
        if (spi_transfer(tx, rx, 7) == 0) {
            gpiod_line_set_value(cs_line, 1);
            *x = (int16_t)((rx[1] << 8) | rx[2]);
            *y = (int16_t)((rx[3] << 8) | rx[4]);
            *z = (int16_t)((rx[5] << 8) | rx[6]);
            return 0;
        }
        gpiod_line_set_value(cs_line, 1);
        retries++;
        usleep(1000);
    }
    return -1;
}

static int log_data(FILE *fp, const struct timespec *ts, int16_t x, int16_t y, int16_t z) {
    if (fprintf(fp, "%ld.%09ld,%d,%d,%d\n", ts->tv_sec, ts->tv_nsec, x, y, z) < 0) {
        return -1;
    }
    if (fflush(fp) != 0) {
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (cs_line != NULL) {
        gpiod_line_set_value(cs_line, 1);
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open(SPI_DEVICE)");
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        cleanup();
        return 1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        cleanup();
        return 1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        cleanup();
        return 1;
    }

    gpio_chip = gpiod_chip_open(GPIO_CHIP);
    if (gpio_chip == NULL) {
        perror("gpiod_chip_open");
        cleanup();
        return 1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, CS_LINE_OFFSET);
    if (cs_line == NULL) {
        perror("gpiod_chip_get_line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "mpu9250_spi_cs", 1) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen(LOG_FILE)");
        cleanup();
        return 1;
    }

    while (running) {
        int16_t x, y, z;
        struct timespec ts;

        if (read_gyro_data(&x, &y, &z) == 0) {
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                if (log_data(log_file, &ts, x, y, z) != 0) {
                    fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
                }
            } else {
                fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            }
        } else {
            fprintf(stderr, "Failed to read gyro data after %d retries\n", MAX_RETRIES);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

