#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 register addresses */
#define MPU6050_REG_SMPLRT_DIV   0x19
#define MPU6050_REG_CONFIG       0x1A
#define MPU6050_REG_GYRO_CONFIG  0x1B
#define MPU6050_REG_ACCEL_CONFIG 0x1C
#define MPU6050_REG_ACCEL_XOUT_H 0x3B
#define MPU6050_REG_PWR_MGMT_1   0x6B

/* LED GPIO pin (BCM numbering) */
#define LED_PIN 21

/* Roll and pitch threshold in degrees */
#define TILT_THRESHOLD 45.0f

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Global variables for cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* Signal handler for Ctrl+C */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Function to initialize the MPU-6050 */
static int init_mpu6050(int handle) {
    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(handle, MPU6050_REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms delay for oscillator to stabilize */

    /* Set sample rate divider to 7 (1 kHz / (1 + 7) = 125 Hz) */
    if (i2cWriteByteData(handle, MPU6050_REG_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: Could not set sample rate divider\n");
        return -1;
    }

    /* Set DLPF configuration to 2 (44 Hz bandwidth, 1 kHz internal sample rate) */
    if (i2cWriteByteData(handle, MPU6050_REG_CONFIG, 0x02) < 0) {
        fprintf(stderr, "Error: Could not set DLPF configuration\n");
        return -1;
    }

    /* Set gyro full scale range to +/- 250 degrees/sec (FS_SEL = 0) */
    if (i2cWriteByteData(handle, MPU6050_REG_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set gyro full scale range\n");
        return -1;
    }

    /* Set accelerometer full scale range to +/- 2g (AFS_SEL = 0) */
    if (i2cWriteByteData(handle, MPU6050_REG_ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set accelerometer full scale range\n");
        return -1;
    }

    return 0;
}

/* Function to read raw accelerometer data from the MPU-6050 */
static int read_raw_accel_data(int handle, int16_t *ax, int16_t *ay, int16_t *az) {
    char buf[6];

    if (i2cReadI2CBlockData(handle, MPU6050_REG_ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read accelerometer data\n");
        return -1;
    }

    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

/* Function to calculate roll and pitch angles from accelerometer data */
static void calculate_roll_pitch(int16_t ax, int16_t ay, int16_t az, float *roll, float *pitch) {
    float ax_f = (float)ax;
    float ay_f = (float)ay;
    float az_f = (float)az;

    *roll  = atan2f(ay_f, az_f) * 180.0f / M_PI;
    *pitch = atan2f(-ax_f, sqrtf(ay_f * ay_f + az_f * az_f)) * 180.0f / M_PI;
}

/* Function to log tilt data to a file */
static void log_tilt_data(float roll, float pitch) {
    FILE *fp = fopen("tilt_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open tilt_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fclose(fp);
}

/* Function to control the LED based on tilt thresholds */
static void control_led(float roll, float pitch) {
    if (fabsf(roll) > TILT_THRESHOLD || fabsf(pitch) > TILT_THRESHOLD) {
        gpioWrite(LED_PIN, 1); /* Turn LED on */
    } else {
        gpioWrite(LED_PIN, 0); /* Turn LED off */
    }
}

int main() {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C connection */
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C connection (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Set LED pin as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); /* Ensure LED is initially off */

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int16_t ax, ay, az;
    float roll, pitch;

    /* Main loop */
    while (program_running) {
        /* Read raw accelerometer data */
        if (read_raw_accel_data(i2c_handle, &ax, &ay, &az) == 0) {
            /* Calculate roll and pitch */
            calculate_roll_pitch(ax, ay, az, &roll, &pitch);

            /* Log tilt data */
            log_tilt_data(roll, pitch);

            /* Control LED */
            control_led(roll, pitch);

            /* Print roll and pitch to console */
            printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);
        } else {
            fprintf(stderr, "Warning: Failed to read sensor data, retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US); /* Delay for 100ms */
    }

    /* Cleanup */
    gpioWrite(LED_PIN, 0); /* Turn LED off */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("\nExiting gracefully...\n");
    return 0;
}

