#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1145_ADDR    0x60
#define LED_PIN        17
#define LOG_FILE       "biometric_log.txt"
#define POLL_MS        100
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000

#define REG_PART_ID     0x00
#define REG_HW_KEY      0x07
#define REG_MEAS_RATE   0x08
#define REG_ALS_VIS_DATA0 0x22
#define REG_PS1_DATA0   0x24

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int init_si1145(int fd) {
    uint8_t part_id;
    if (i2c_read_reg(fd, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error: cannot read PART_ID: %s\n", strerror(errno));
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Error: unexpected PART_ID 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }
    if (i2c_write_reg(fd, REG_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error: cannot write HW_KEY: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg(fd, REG_MEAS_RATE, 0x08) < 0) {
        fprintf(stderr, "Error: cannot set MEAS_RATE: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor(int fd, int *ambient, int *proximity) {
    uint8_t als_lo, als_hi, ps_lo, ps_hi;
    if (i2c_read_reg(fd, REG_ALS_VIS_DATA0, &als_lo) < 0) return -1;
    if (i2c_read_reg(fd, REG_ALS_VIS_DATA0 + 1, &als_hi) < 0) return -1;
    if (i2c_read_reg(fd, REG_PS1_DATA0, &ps_lo) < 0) return -1;
    if (i2c_read_reg(fd, REG_PS1_DATA0 + 1, &ps_hi) < 0) return -1;
    *ambient = (als_hi << 8) | als_lo;
    *proximity = (ps_hi << 8) | ps_lo;
    return 0;
}

static void log_data(FILE *f, int ambient, int proximity) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(f, "%04d-%02d-%02d %02d:%02d:%02d,AmbientLight:%d,Proximity:%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, ambient, proximity);
    fflush(f);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        fprintf(stderr, "Error: cannot set I2C slave 0x%02X: %s\n", SI1145_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (init_si1145(g_i2c_fd) < 0) {
        fprintf(stderr, "Error: Si1145 initialisation failed\n");
        close(g_i2c_fd);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (g_running) {
        int ambient = 0, proximity = 0;
        int ok = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_sensor(g_i2c_fd, &ambient, &proximity) == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1) usleep(RETRY_DELAY_US);
        }
        if (ok) {
            log_data(g_log, ambient, proximity);
            gpioWrite(LED_PIN, (proximity > 100) ? 1 : 0);
        } else {
            fprintf(stderr, "Error: sensor read failed after %d attempts\n", MAX_RETRIES);
        }
        usleep(POLL_MS * 1000);
    }

    gpioWrite(LED_PIN, 0);
    if (g_log) fclose(g_log);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    gpioTerminate();
    return 0;
}

