#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

/* ADXRS290 register addresses */
#define ADXRS290_REG_XGYRO_OUT 0x04
#define ADXRS290_REG_YGYRO_OUT 0x06

/* SPI parameters */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* mode 0, CE0 active low */

/* Retry parameters */
#define MAX_RETRIES 3

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 10000

/* Global resources for signal handler */
static int  spi_handle = -1;
static FILE *fp       = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can clean up and exit       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Initialise SPI via pigpio                                          */
/* ------------------------------------------------------------------ */
static int init_spi(void)
{
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %s\n",
                SPI_CHANNEL, pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADXRS290                            */
/*   reg  : register address (OR with 0x80 for read)                   */
/*   rate : output signed 16-bit value                                */
/* Returns 0 on success, -1 on error                                  */
/* ------------------------------------------------------------------ */
static int read_gyro_axis(uint8_t reg, int16_t *rate)
{
    char tx[2];
    char rx[2];

    /* ADXRS290 read: MSB of register address = 1 */
    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;  /* dummy byte to clock out data */

    int ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X: %s\n",
                reg, pigpio_error(ret));
        return -1;
    }

    /* Data is returned in the second byte of the transfer */
    *rate = (int16_t)(uint8_t)rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample to the CSV file                                      */
/* ------------------------------------------------------------------ */
static int log_data(FILE *f, double timestamp, int16_t x_rate, int16_t y_rate)
{
    if (fprintf(f, "%.6f,%d,%d\n", timestamp, x_rate, y_rate) < 0) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(f) != 0) {
        fprintf(stderr, "Error flushing CSV file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — closes SPI, file, and terminates pigpio           */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Initialise SPI */
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    /* Open CSV file for appending */
    fp = fopen("gyro_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening gyro_data.csv: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    /* Write CSV header if file is empty */
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,x_rate,y_rate\n");
        fflush(fp);
    }

    int retry_count = 0;

    while (!terminate) {
        int16_t x_rate = 0;
        int16_t y_rate = 0;

        if (read_gyro_axis(ADXRS290_REG_XGYRO_OUT, &x_rate) != 0 ||
            read_gyro_axis(ADXRS290_REG_YGYRO_OUT, &y_rate) != 0) {
            retry_count++;
            fprintf(stderr, "Gyro read error (attempt %d/%d)\n",
                    retry_count, MAX_RETRIES);
            if (retry_count >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                break;
            }
            /* Attempt to re-initialise SPI */
            spiClose(spi_handle);
            spi_handle = -1;
            if (init_spi() != 0) {
                fprintf(stderr, "SPI re-initialisation failed. Exiting.\n");
                break;
            }
            continue;
        }

        retry_count = 0;  /* reset on success */

        /* Build timestamp with microsecond precision */
        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            break;
        }
        double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;

        if (log_data(fp, timestamp, x_rate, y_rate) != 0) {
            fprintf(stderr, "Logging failed. Exiting.\n");
            break;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

