#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17
#define SEISMIC_THRESHOLD_MS 500
#define ALERT_DURATION_MS 2000
#define LOG_FILE "seismic_events.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];
    if (t) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    } else {
        strncpy(timestamp, "UNKNOWN", sizeof(timestamp));
        timestamp[sizeof(timestamp) - 1] = '\0';
    }
    fprintf(log_file, "%s - %s\n", timestamp, message);
    fflush(log_file);
}

static void trigger_alert(void) {
    if (gpioWrite(ALERT_PIN, 1) < 0) {
        log_event("ERROR: Failed to set alert pin HIGH");
        return;
    }
    gpioDelay(ALERT_DURATION_MS * 1000);
    if (gpioWrite(ALERT_PIN, 0) < 0) {
        log_event("ERROR: Failed to set alert pin LOW");
    }
}

static void sensor_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)tick;
    (void)userdata;
    static uint32_t s1_start = 0;
    static uint32_t s2_start = 0;
    static int s1_active = 0;
    static int s2_active = 0;

    if (gpio == SENSOR_1_PIN) {
        if (level == 1) {
            s1_start = gpioTick();
            s1_active = 1;
        } else if (level == 0 && s1_active) {
            uint32_t duration = gpioTick() - s1_start;
            s1_active = 0;
            if (s2_active && duration >= SEISMIC_THRESHOLD_MS * 1000) {
                log_event("Seismic event detected!");
                trigger_alert();
            }
        }
    } else if (gpio == SENSOR_2_PIN) {
        if (level == 1) {
            s2_start = gpioTick();
            s2_active = 1;
        } else if (level == 0 && s2_active) {
            uint32_t duration = gpioTick() - s2_start;
            s2_active = 0;
            if (s1_active && duration >= SEISMIC_THRESHOLD_MS * 1000) {
                log_event("Seismic event detected!");
                trigger_alert();
            }
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting alert pin mode\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_PIN, 0);

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0 || gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting sensor pin modes\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) < 0 || gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error setting pull-down resistors\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(SENSOR_1_PIN, sensor_callback, NULL) < 0 ||
        gpioSetAlertFuncEx(SENSOR_2_PIN, sensor_callback, NULL) < 0) {
        fprintf(stderr, "Error registering alert callbacks\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing signal handlers: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");
    log_event("Monitoring started");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    log_event("Monitoring stopped");
    gpioWrite(ALERT_PIN, 0);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

