                log_event("Seismic event detected!");
                trigger_alert();
            }
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting alert pin mode\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_PIN, 0);

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0 || gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting sensor pin modes\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) < 0 || gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error setting pull-down resistors\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(SENSOR_1_PIN, sensor_callback, NULL) < 0 ||
        gpioSetAlertFuncEx(SENSOR_2_PIN, sensor_callback, NULL) < 0) {
        fprintf(stderr, "Error registering alert callbacks\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing signal handlers: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");
    log_event("Monitoring started");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    log_event("Monitoring stopped");
    gpioWrite(ALERT_PIN, 0);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

