#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* mode 0, active-low CE */

#define GYRO_X_REG     0x00       /* X-axis rate register */
#define GYRO_READ_BIT  0x80       /* MSB = 1 for read */
#define GYRO_DATA_LEN  2          /* 2 data bytes + 1 status byte */

#define THRESHOLD      20.0f      /* deg/s */
#define LED_PIN        17
#define BUFFER_SIZE    100

/* ------------------------------- Globals --------------------------------- */
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    struct timespec timestamp;
    float rate;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_head = 0;
static int buffer_count = 0;

/* --------------------------- Function prototypes ------------------------- */
static int  spi_read_register(uint8_t reg, uint8_t *data, int len);
static int  read_gyro_x(float *rate);
static void add_to_buffer(struct timespec ts, float rate);
static void check_threshold(float rate);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- SPI read -------------------------------- */
static int spi_read_register(uint8_t reg, uint8_t *data, int len)
{
    if (len < 0 || len > 255) {
        fprintf(stderr, "spi_read_register: invalid length %d\n", len);
        return -1;
    }

    char tx[1 + GYRO_DATA_LEN];
    char rx[1 + GYRO_DATA_LEN];

    tx[0] = (char)(reg | GYRO_READ_BIT);
    memset(&tx[1], 0, sizeof(tx) - 1);

    int ret = spiXfer(spi_handle, tx, rx, sizeof(tx));
    if (ret != (int)sizeof(tx)) {
        fprintf(stderr, "spiXfer failed: returned %d (expected %zu)\n",
                ret, sizeof(tx));
        return -1;
    }

    memcpy(data, &rx[1], len);
    return 0;
}

/* --------------------------- Read X-axis rate ---------------------------- */
static int read_gyro_x(float *rate)
{
    uint8_t data[GYRO_DATA_LEN];
    if (spi_read_register(GYRO_X_REG, data, GYRO_DATA_LEN) != 0) {
        return -1;
    }

    /* ADXRS290: 16-bit two's-complement, LSB = 0.02 deg/s */
    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *rate = (float)raw * 0.02f;
    return 0;
}

/* ------------------------- Circular buffer ------------------------------- */
static void add_to_buffer(struct timespec ts, float rate)
{
    pthread_mutex_lock(&buffer_mutex);
    gyro_buffer[buffer_head].timestamp = ts;
    gyro_buffer[buffer_head].rate      = rate;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
    pthread_mutex_unlock(&buffer_mutex);
}

/* --------------------------- Threshold check ----------------------------- */
static void check_threshold(float rate)
{
    gpioWrite(LED_PIN, (rate > THRESHOLD) ? 1 : 0);
}

/* --------------------------- Signal handler ------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    pthread_mutex_destroy(&buffer_mutex);
}

/* --------------------------------- main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXRS290 X-axis monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float rate;
        if (read_gyro_x(&rate) == 0) {
            struct timespec ts;
            clock_gettime(CLOCK_MONOTONIC, &ts);
            add_to_buffer(ts, rate);
            check_threshold(rate);
            printf("X-axis rate: %.2f deg/s\n", rate);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    cleanup();
    return EXIT_SUCCESS;
}

