/*
 * Smart Sunset Simulator — Raspberry Pi Zero W
 * Three relay-controlled dimmable lamps on GPIO17, GPIO18, GPIO27 (BCM).
 * Fades each lamp sequentially from 100% to 0% over a user-defined duration.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sunset sunset.c -lpigpio -lrt
 * Run:    sudo ./sunset <seconds>
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_PIN 17
#define LAMP2_PIN 18
#define LAMP3_PIN 27

#define PWM_FREQUENCY 100          /* Hz  */
#define PWM_RANGE     255          /* 0-255 duty steps */
#define FADE_STEPS    100          /* granularity per lamp fade */
#define STEP_DELAY_US 10000        /* 10 ms per step (100 steps = 1 s) */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    /* Turn off all lamps and terminate pigpio */
    gpioPWM(LAMP1_PIN, 0);
    gpioPWM(LAMP2_PIN, 0);
    gpioPWM(LAMP3_PIN, 0);
    gpioTerminate();
}

static int parse_duration(const char *arg, int *out)
{
    char *end = NULL;
    long val = strtol(arg, &end, 10);
    if (end == arg || *end != '\0') {
        fprintf(stderr, "Error: duration must be an integer.\n");
        return -1;
    }
    if (val < 1 || val > 3600) {
        fprintf(stderr, "Error: duration must be 1-3600 seconds.\n");
        return -1;
    }
    *out = (int)val;
    return 0;
}

static void fade_lamp(int pin, int duration_s)
{
    int steps_per_s = 1000000 / STEP_DELAY_US; /* 100 */
    int total_steps = duration_s * steps_per_s;
    int step_delay_us = (total_steps > 0) ? (1000000 / total_steps) : 10000;

    for (int i = PWM_RANGE; i >= 0 && g_running; i--) {
        if (gpioPWM(pin, i) < 0) {
            fprintf(stderr, "Warning: gpioPWM failed on pin %d\n", pin);
        }
        gpioDelay(step_delay_us);
    }
    if (g_running) {
        gpioPWM(pin, 0);
    }
}

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_seconds>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int duration = 0;
    if (parse_duration(argv[1], &duration) != 0) {
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure PWM on each lamp pin */
    if (gpioSetMode(LAMP1_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(LAMP2_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(LAMP3_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO mode.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(LAMP1_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(LAMP2_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(LAMP3_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(LAMP1_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(LAMP2_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(LAMP3_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure lamps start at full brightness */
    gpioPWM(LAMP1_PIN, PWM_RANGE);
    gpioPWM(LAMP2_PIN, PWM_RANGE);
    gpioPWM(LAMP3_PIN, PWM_RANGE);

    printf("Sunset simulator started. Fading %d lamps over %d seconds.\n",
           3, duration);
    printf("Press Ctrl+C to stop.\n");
    fflush(stdout);

    fade_lamp(LAMP1_PIN, duration);
    if (!g_running) goto shutdown;

    fade_lamp(LAMP2_PIN, duration);
    if (!g_running) goto shutdown;

    fade_lamp(LAMP3_PIN, duration);

shutdown:
    cleanup();
    if (g_running) {
        printf("Sunset simulation complete.\n");
    } else {
        printf("\nSunset simulation interrupted. Lamps turned off.\n");
    }
    return EXIT_SUCCESS;
}

