#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RED_PIN    17
#define YELLOW_PIN 22
#define GREEN_PIN  23
#define BLUE_PIN   24

#define RED_DURATION    10
#define RED_YELLOW_DURATION 2
#define GREEN_DURATION  10
#define YELLOW_DURATION 3

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static int set_all(struct gpiod_line *r, struct gpiod_line *y,
                    struct gpiod_line *g, struct gpiod_line *b, int val) {
    if (gpiod_line_set_value(r, val) < 0) return -1;
    if (gpiod_line_set_value(y, val) < 0) return -1;
    if (gpiod_line_set_value(g, val) < 0) return -1;
    if (gpiod_line_set_value(b, val) < 0) return -1;
    return 0;
}

static int off_all(struct gpiod_line *r, struct gpiod_line *y,
                    struct gpiod_line *g, struct gpiod_line *b) {
    return set_all(r, y, g, b, 1);
}

static int on_all(struct gpiod_line *r, struct gpiod_line *y,
                   struct gpiod_line *g, struct gpiod_line *b) {
    return set_all(r, y, g, b, 0);
}

static void sleep_ms(unsigned int ms) {
    while (ms > 0 && running) {
        unsigned int chunk = (ms > 100) ? 100 : ms;
        usleep(chunk * 1000);
        ms -= chunk;
    }
