#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 100
#define POLL_INTERVAL_US 10000

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECONFIG0 0x5E
#define MPR121_ELECONFIG1 0x5F
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void log_error(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d", reg, value, rc);
        log_error(msg);
    }
    return rc;
}

static int mpr121_init(void) {
    if (mpr121_write_reg(MPR121_ECR, 0x00) < 0) return -1;
    gpioDelay(1000);
    if (mpr121_write_reg(MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLR, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDF, 0x05) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDT, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLT, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLT, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;
    if (mpr121_write_reg(MPR121_E0TTH, 0x0F) < 0) return -1;
    if (mpr121_write_reg(MPR121_E0RTH, 0x0A) < 0) return -1;
    if (mpr121_write_reg(MPR121_ECR, 0x8F) < 0) return -1;
    gpioDelay(1000);
    return 0;
}

static int read_touch_status(uint16_t *status) {
    char buf[2];
    int rc = i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2);
    if (rc != 2) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C read failed: rc=%d", rc);
        log_error(msg);
        return -1;
    }
    *status = ((uint16_t)(buf[1] & 0x0F) << 8) | (uint8_t)buf[0];
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioSetMode(RELAY_GPIO, PI_INPUT);
    if (log_file) {
        log_error("Cleanup complete.");
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    log_file = fopen("touch_relay.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Failed to open I2C bus %d at addr 0x%02X: %d", I2C_BUS, MPR121_ADDR, i2c_handle);
        log_error(msg);
        cleanup();
        return 1;
    }

    if (mpr121_init() < 0) {
        log_error("MPR121 initialization failed");
        cleanup();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        log_error("Failed to set relay GPIO mode");
        cleanup();
        return 1;
    }
    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        log_error("Failed to set relay GPIO initial state");
        cleanup();
        return 1;
    }

    uint32_t last_touch_time = 0;
    int relay_state = 0;

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) < 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (touch_status & 0x0001) {
            uint32_t now = gpioTick();
            if (now - last_touch_time > DEBOUNCE_DELAY_MS * 1000) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_GPIO, relay_state) < 0) {
                    log_error("Failed to write relay GPIO");
                } else {
                    char msg[128];
                    snprintf(msg, sizeof(msg), "Relay toggled to %d", relay_state);
                    log_error(msg);
                }
                last_touch_time = now;
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return 0;
}

