#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DISPENSE_INTERVAL_MS 1000
#define DISPENSE_HALF_MS (DISPENSE_INTERVAL_MS / 2)
#define DISPENSE_DELAY_MS 5000
#define LOG_FILE "dispense_log.txt"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int log_dispense_event(int pin1, int pin2, int duration_ms) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s - Dispensed: Solenoid 1 (GPIO%d), Solenoid 2 (GPIO%d), Duration: %d ms\n",
            timestamp, pin1, pin2, duration_ms);
    fclose(fp);
    return 0;
}

static int dispense_solenoid(int pin, int duration_ms) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error activating solenoid on GPIO %d\n", pin);
        return -1;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error deactivating solenoid on GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static int dispense_sequence(void) {
    if (dispense_solenoid(SOLENOID_1_PIN, DISPENSE_HALF_MS) != 0) {
        return -1;
    }
    if (dispense_solenoid(SOLENOID_2_PIN, DISPENSE_HALF_MS) != 0) {
        return -1;
    }
    return 0;
}

