            fprintf(stderr, "Dispense sequence failed\n");
            gpioTerminate();
            return 1;
        }
        if (log_dispense_event(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_INTERVAL_MS) != 0) {
            fprintf(stderr, "Logging failed\n");
            gpioTerminate();
            return 1;
        }
        gpioDelay(DISPENSE_DELAY_MS * 1000);
    }

    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
    gpioTerminate();
    return 0;
}

