    if (speed > MAX_SPEED) speed = MAX_SPEED;
    if (speed < -MAX_SPEED) speed = -MAX_SPEED;

    int forward_pin, backward_pin;
    if (motor == 'A') {
        forward_pin = MOTOR_A_FORWARD;
        backward_pin = MOTOR_A_BACKWARD;
    } else if (motor == 'B') {
        forward_pin = MOTOR_B_FORWARD;
        backward_pin = MOTOR_B_BACKWARD;
    } else {
        fprintf(stderr, "Invalid motor character: %c\n", motor);
        return;
    }

    if (speed > 0) {
        if (GPIO_setMode(forward_pin, GPIO_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set forward pin mode for motor %c\n", motor);
            return;
        }
        if (GPIO_write(forward_pin, 1) != 0) {
            fprintf(stderr, "Failed to write forward pin for motor %c\n", motor);
            return;
        }
        if (GPIO_setMode(backward_pin, GPIO_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set backward pin mode for motor %c\n", motor);
            return;
        }
        if (GPIO_write(backward_pin, 0) != 0) {
            fprintf(stderr, "Failed to write backward pin for motor %c\n", motor);
            return;
        }
        if (PWM_setDutyCycle(forward_pin, speed) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle for motor %c\n", motor);
        }
    } else if (speed < 0) {
        if (GPIO_setMode(forward_pin, GPIO_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set forward pin mode for motor %c\n", motor);
            return;
        }
        if (GPIO_write(forward_pin, 0) != 0) {
            fprintf(stderr, "Failed to write forward pin for motor %c\n", motor);
            return;
        }
        if (GPIO_setMode(backward_pin, GPIO_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set backward pin mode for motor %c\n", motor);
            return;
        }
        if (GPIO_write(backward_pin, 1) != 0) {
            fprintf(stderr, "Failed to write backward pin for motor %c\n", motor);
            return;
        }
        if (PWM_setDutyCycle(backward_pin, -speed) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle for motor %c\n", motor);
        }
    } else {
        if (GPIO_setMode(forward_pin, GPIO_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set forward pin mode for motor %c\n", motor);
            return;
        }
        if (GPIO_write(forward_pin, 0) != 0) {
            fprintf(stderr, "Failed to write forward pin for motor %c\n", motor);
            return;
        }
        if (GPIO_setMode(backward_pin, GPIO_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set backward pin mode for motor %c\n", motor);
            return;
        }
        if (GPIO_write(backward_pin, 0) != 0) {
            fprintf(stderr, "Failed to write backward pin for motor %c\n", motor);
            return;
        }
        if (PWM_setDutyCycle(forward_pin, 0) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle for motor %c\n", motor);
        }
    }
}

static void stop_motors(void) {
    set_motor_speed('A', 0);
    set_motor_speed('B', 0);
}

static void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
}

int main(void) {
    float tilt_error, distance;
    int motor_a_speed, motor_b_speed;
    float integral = 0.0f;
    float previous_error = 0.0f;

    srand((unsigned int)time(NULL));

    if (GPIO_init() != 0) {
        fprintf(stderr, "Failed to initialize GPIO library.\n");
        return 1;
    }

    if (PWM_init() != 0) {
        fprintf(stderr, "Failed to initialize PWM library.\n");
        GPIO_terminate();
        return 1;
    }

    if (GPIO_setMode(ENA, GPIO_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set ENA mode.\n");
        PWM_terminate();
        GPIO_terminate();
        return 1;
    }
    if (GPIO_write(ENA, 1) != 0) {
        fprintf(stderr, "Failed to write ENA.\n");
        PWM_terminate();
        GPIO_terminate();
        return 1;
    }

    if (GPIO_setMode(ENB, GPIO_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set ENB mode.\n");
        PWM_terminate();
        GPIO_terminate();
        return 1;
    }
    if (GPIO_write(ENB, 1) != 0) {
        fprintf(stderr, "Failed to write ENB.\n");
        PWM_terminate();
        GPIO_terminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        PWM_terminate();
        GPIO_terminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        PWM_terminate();
        GPIO_terminate();
        return 1;
    }

    while (running) {
        tilt_error = simulate_tilt_error();
        distance = simulate_distance();

        float derivative = tilt_error - previous_error;
        integral += tilt_error;
        motor_a_speed = (int)(KP * tilt_error + KI * integral + KD * derivative);
        motor_b_speed = (int)(KP * tilt_error + KI * integral + KD * derivative);

        if (distance < OBSTACLE_THRESHOLD) {
            motor_a_speed = -REVERSE_SPEED;
            motor_b_speed = -REVERSE_SPEED;
        }

        set_motor_speed('A', motor_a_speed);
        set_motor_speed('B', motor_b_speed);

        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        previous_error = tilt_error;
        usleep(LOOP_DELAY_US);
    }

    stop_motors();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    PWM_terminate();
    GPIO_terminate();

    return 0;
}

