#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set touch sensor pin %d as input.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set relay pin %d as output.\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure relay starts in the OFF state (active-high relay: LOW = de-energized) */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize relay pin %d to LOW.\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    /* De-energize relay before terminating */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to de-energize relay during cleanup.\n");
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    int relay_state = 0;

    while (running) {
        int sensor_value = gpioRead(TOUCH_SENSOR_PIN);

        if (sensor_value < 0) {
            fprintf(stderr, "Error: failed to read touch sensor pin %d.\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (sensor_value == 1) {
            relay_state = !relay_state;

            if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                fprintf(stderr, "Error: failed to write relay pin %d.\n", RELAY_PIN);
                break;
            }

            printf("Touch detected! Relay toggled to %s.\n", relay_state ? "ON" : "OFF");

            /* Debounce delay */
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        gpioDelay(10000); /* 10 ms polling interval */
    }

    cleanup_gpio();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

