/*
 * mood_light.c — Audio-reactive RGB mood light for Raspberry Pi 3 Model B+
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mood_light mood_light.c -lpigpio -lasound -lm
 *
 * Wiring (common-cathode RGB LED with current-limiting resistors):
 *   Red   -> GPIO17 (BCM 17, physical pin 11)
 *   Green -> GPIO18 (BCM 18, physical pin 12)
 *   Blue  -> GPIO27 (BCM 27, physical pin 13)
 *
 * The program computes the RMS amplitude of each 1024-frame ALSA buffer,
 * maps it non-linearly to RGB, and drives the LED with software PWM via
 * pigpio.  When ALSA is unavailable (e.g. no microphone), a simulated
 * sine-wave amplitude is used so the mood light still cycles.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define ALSA_AVAILABLE 1

#if ALSA_AVAILABLE
#include <alsa/asoundlib.h>
#endif

/* ---- Hardware / audio constants ---- */
#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define SAMPLE_RATE     8000
#define PERIOD_SIZE     1024
#define NUM_CHANNELS    1
#define FRAME_BYTES     2          /* 16-bit little-endian */
#define BUFFER_BYTES    (PERIOD_SIZE * FRAME_BYTES)

#define PWM_RANGE       255
#define PWM_FREQ        1000       /* Hz — pigpio default is 800, but 1000 is fine */

#define SENSITIVITY     1.0f       /* default scaling factor */
#define SLEEP_US        10000      /* 10 ms per cycle */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;

#if ALSA_AVAILABLE
static snd_pcm_t *g_pcm = NULL;
static snd_pcm_hw_params_t *g_hw_params = NULL;
static int16_t *g_audio_buffer = NULL;
#endif

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static void cleanup(void);
static void set_led_color(int r, int g, int b);
static void map_amplitude_to_color(float amp, int *r, int *g, int *b);
static float calculate_rms(const int16_t *data, int num_samples);
#if ALSA_AVAILABLE
static int  init_alsa(void);
static int  read_audio_data(int16_t *buffer, int num_frames);
static void handle_alsa_error(int err, const char *context);
#else
static float simulate_audio_amplitude(void);
#endif

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    /* Turn off LED */
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);

    /* Release pigpio resources */
    gpioTerminate();

#if ALSA_AVAILABLE
    if (g_audio_buffer) {
        free(g_audio_buffer);
        g_audio_buffer = NULL;
    }
    if (g_pcm) {
        snd_pcm_drain(g_pcm);
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
    }
    if (g_hw_params) {
        snd_pcm_hw_params_free(g_hw_params);
        g_hw_params = NULL;
    }
#endif
}

/* ------------------------------------------------------------------ */
/* LED control                                                         */
/* ------------------------------------------------------------------ */
static void set_led_color(int r, int g, int b)
{
    gpioPWM(RED_PIN,   r);
    gpioPWM(GREEN_PIN, g);
    gpioPWM(BLUE_PIN,  b);
}

static void map_amplitude_to_color(float amp, int *r, int *g, int *b)
{
    /* Non-linear mapping: low amplitudes -> blue, high -> red */
    float scaled = powf(amp, 0.5f);
    if (scaled > 1.0f) scaled = 1.0f;

    int v = (int)(scaled * PWM_RANGE);
    if (v > PWM_RANGE) v = PWM_RANGE;
    if (v < 0)        v = 0;

    *r = v;
    *g = 0;
    *b = PWM_RANGE - v;
}

/* ------------------------------------------------------------------ */
/* Audio processing                                                    */
/* ------------------------------------------------------------------ */
static float calculate_rms(const int16_t *data, int num_samples)
{
    double sum_sq = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double s = (double)data[i];
        sum_sq += s * s;
    }
    return (float)sqrt(sum_sq / (double)num_samples);
}

#if ALSA_AVAILABLE
/* ------------------------------------------------------------------ */
/* ALSA helpers                                                        */
/* ------------------------------------------------------------------ */
static int init_alsa(void)
{
    int err;

    err = snd_pcm_open(&g_pcm, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "Error opening PCM device 'default': %s\n",
                snd_strerror(err));
        return -1;
    }

    g_hw_params = snd_pcm_hw_params_malloc();
    if (!g_hw_params) {
        fprintf(stderr, "Error allocating HW params\n");
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
        return -1;
    }

    err = snd_pcm_hw_params_any(g_pcm, g_hw_params);
    if (err < 0) {
        handle_alsa_error(err, "snd_pcm_hw_params_any");
        goto fail;
    }

    err = snd_pcm_hw_params_set_access(g_pcm, g_hw_params,
                                       SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) {
        handle_alsa_error(err, "snd_pcm_hw_params_set_access");
        goto fail;
    }

    err = snd_pcm_hw_params_set_format(g_pcm, g_hw_params,
                                       SND_PCM_FORMAT_S16_LE);
    if (err < 0) {
        handle_alsa_error(err, "snd_pcm_hw_params_set_format");
        goto fail;
    }

    err = snd_pcm_hw_params_set_rate_near(g_pcm, g_hw_params,
                                          &SAMPLE_RATE, NULL);
    if (err < 0) {
        handle_alsa_error(err, "snd_pcm_hw_params_set_rate_near");
        goto fail;
    }

    err = snd_pcm_hw_params_set_channels(g_pcm, g_hw_params, NUM_CHANNELS);
    if (err < 0) {
        handle_alsa_error(err, "snd_pcm_hw_params_set_channels");
        goto fail;
    }

    err = snd_pcm_hw_params_set_period_size_near(g_pcm, g_hw_params,
                                                  &PERIOD_SIZE, NULL);
    if (err < 0) {
        handle_alsa_error(err, "snd_pcm_hw_params_set_period_size_near");
        goto fail;
    }

    err = snd_pcm_hw_params(g_pcm, g_hw_params);
    if (err < 0) {
        handle_alsa_error(err, "snd_pcm_hw_params");
        goto fail;
    }

    err = snd_pcm_prepare(g_pcm);
    if (err < 0) {
        handle_alsa_error(err, "snd_pcm_prepare");
        goto fail;
    }

    g_audio_buffer = (int16_t *)malloc(BUFFER_BYTES);
    if (!g_audio_buffer) {
        fprintf(stderr, "Error allocating audio buffer\n");
        goto fail;
    }

    return 0;

fail:
    if (g_audio_buffer) { free(g_audio_buffer); g_audio_buffer = NULL; }
    if (g_hw_params)    { snd_pcm_hw_params_free(g_hw_params); g_hw_params = NULL; }
    if (g_pcm)          { snd_pcm_close(g_pcm); g_pcm = NULL; }
    return -1;
}

static int read_audio_data(int16_t *buffer, int num_frames)
{
    int err = snd_pcm_readi(g_pcm, buffer, num_frames);
    if (err == -EPIPE) {
        fprintf(stderr, "ALSA buffer overrun — recovering\n");
        snd_pcm_prepare(g_pcm);
        return -1;
    }
    if (err == -ESTRPIPE) {
        fprintf(stderr, "ALSA device suspended — recovering\n");
        if (snd_pcm_resume(g_pcm) < 0) {
            fprintf(stderr, "Resume failed; re-opening\n");
            snd_pcm_prepare(g_pcm);
        }
        return -1;
    }
    if (err < 0) {
        fprintf(stderr, "ALSA read error: %s\n", snd_strerror(err));
        return -1;
    }
    if (err != num_frames) {
        fprintf(stderr, "Short read: got %d of %d frames\n", err, num_frames);
        return -1;
    }
    return 0;
}

static void handle_alsa_error(int err, const char *context)
{
    fprintf(stderr, "ALSA error in %s: %s\n", context, snd_strerror(err));
}
#endif

/* ------------------------------------------------------------------ */
/* Simulation (when ALSA is unavailable)                               */
/* ------------------------------------------------------------------ */
#if !ALSA_AVAILABLE
static float simulate_audio_amplitude(void)
{
    static double phase = 0.0;
    phase += 0.01;
    if (phase > 2.0 * M_PI) phase -= 2.0 * M_PI;
    float amp = (float)(sin(phase) * 0.5 + 0.5);
    return amp;
}
#endif

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    float sensitivity = SENSITIVITY;

    if (argc > 1) {
        sensitivity = (float)atof(argv[1]);
        if (sensitivity <= 0.0f) {
            fprintf(stderr, "Invalid sensitivity '%s' — using default %.2f\n",
                    argv[1], SENSITIVITY);
            sensitivity = SENSITIVITY;
        }
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    gpioSetPWMrange(RED_PIN,   PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN,  PWM_RANGE);

    gpioSetPWMfrequency(RED_PIN,   PWM_FREQ);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ);
    gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ);

    /* ---- ALSA init ---- */
#if ALSA_AVAILABLE
    if (init_alsa() < 0) {
        fprintf(stderr, "ALSA initialization failed — "
                        "falling back to simulation mode\n");
    }
#endif

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Mood light running.  Sensitivity: %.2f  (Ctrl+C to exit)\n",
           sensitivity);

    /* ---- Main loop ---- */
    while (g_running) {
#if ALSA_AVAILABLE
        if (g_pcm && g_audio_buffer) {
            if (read_audio_data(g_audio_buffer, PERIOD_SIZE) < 0) {
                usleep(SLEEP_US);
                continue;
            }
            float amp = calculate_rms(g_audio_buffer, PERIOD_SIZE);
            amp *= sensitivity;
            if (amp > 1.0f) amp = 1.0f;
            if (amp < 0.0f) amp = 0.0f;
            int r, g, b;
            map_amplitude_to_color(amp, &r, &g, &b);
            set_led_color(r, g, b);
        } else {
            /* Fallback: simulate audio */
            float amp = simulate_audio_amplitude();
            amp *= sensitivity;
            if (amp > 1.0f) amp = 1.0f;
            if (amp < 0.0f) amp = 0.0f;
            int r, g, b;
            map_amplitude_to_color(amp, &r, &g, &b);
            set_led_color(r, g, b);
        }
#else
        /* No ALSA at all — simulate */
        float amp = simulate_audio_amplitude();
        amp *= sensitivity;
