#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29
#define CSV_FILENAME   "color_data.csv"
#define SAMPLE_US      500000   /* 500 ms */
#define INTEGRATION_MS 154

/* TCS34725 register addresses */
#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_ID      0x12
#define TCS34725_CDATAL  0x14
#define TCS34725_CDATAH  0x15
#define TCS34725_RDATAL  0x16
#define TCS34725_RDATAH  0x17
#define TCS34725_GDATAL  0x18
#define TCS34725_GDATAH  0x19
#define TCS34725_BDATAL  0x1A
#define TCS34725_BDATAH  0x1B

#define TCS34725_ENABLE_PON  0x01
#define TCS34725_ENABLE_AEN  0x02

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_fp        = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can clean up and exit.      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a TCS34725 register.                              */
/* ------------------------------------------------------------------ */
static int tcs_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair.                          */
/* ------------------------------------------------------------------ */
static int tcs_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "i2cReadWordData(reg=0x%02X) failed: %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *out = (uint16_t)(rc & 0xFFFF);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the TCS34725: power on, set integration time, enable.    */
/* ------------------------------------------------------------------ */
static int tcs34725_init(int handle)
{
    /* Power on */
    if (tcs_write_reg(handle, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0)
        return -1;
    gpioDelay(3000);  /* 3 ms power-up delay */

    /* Integration time: 256 – (t/2.4 ms) → 256 – (154/2.4) ≈ 85.83 → 86 */
    uint8_t atime = (uint8_t)(256 - (INTEGRATION_MS / 240.0f));
    if (tcs_write_reg(handle, TCS34725_ATIME, atime) < 0)
        return -1;

    /* Enable RGBC ADC */
    if (tcs_write_reg(handle, TCS34725_ENABLE,
                      TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0)
        return -1;

    gpioDelay((INTEGRATION_MS + 1) * 1000);  /* wait for first conversion */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read calibrated (16-bit) C/R/G/B values.                            */
/* ------------------------------------------------------------------ */
static int tcs34725_read_calibrated(int handle,
                                    uint16_t *c, uint16_t *r,
                                    uint16_t *g, uint16_t *b)
{
    if (tcs_read_reg16(handle, TCS34725_CDATAL, c) < 0) return -1;
    if (tcs_read_reg16(handle, TCS34725_RDATAL, r) < 0) return -1;
    if (tcs_read_reg16(handle, TCS34725_GDATAL, g) < 0) return -1;
    if (tcs_read_reg16(handle, TCS34725_BDATAL, b) < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append one CSV row.                                                 */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t c, uint16_t r,
                     uint16_t g, uint16_t b)
{
    time_t now = time(NULL);
    fprintf(fp, "%ld,%u,%u,%u,%u\n", (long)now, c, r, g, b);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times.                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_fp != NULL) {
        fclose(g_fp);
        g_fp = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- verify sensor identity ------------------------------------- */
    int id = i2cReadByteData(g_i2c_handle, TCS34725_ID);
    if (id < 0) {
        fprintf(stderr, "Cannot read TCS34725 ID register: %s\n",
                pigpio_error(id));
        cleanup();
        return EXIT_FAILURE;
    }
    if (id != 0x44 && id != 0x10) {
        fprintf(stderr, "Unexpected TCS34725 ID: 0x%02X (expected 0x44 or 0x10)\n",
                id);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- init sensor ------------------------------------------------ */
    if (tcs34725_init(g_i2c_handle) < 0) {
        fprintf(stderr, "TCS34725 init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- open CSV --------------------------------------------------- */
    g_fp = fopen(CSV_FILENAME, "a");
    if (g_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_fp) == 0) {
        fprintf(g_fp, "timestamp,c_clear,c_red,c_green,c_blue\n");
        fflush(g_fp);
    }

    /* --- signals ---------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        uint16_t c, r, g, b;

        if (tcs34725_read_calibrated(g_i2c_handle, &c, &r, &g, &b) == 0) {
            log_data(g_fp, c, r, g, b);
        } else {
            fprintf(stderr, "Sensor read failed — logging zeros\n");
            log_data(g_fp, 0, 0, 0, 0);
        }

        gpioDelay(SAMPLE_US);
    }

    /* --- graceful shutdown ------------------------------------------ */
    cleanup();
    return EXIT_SUCCESS;
}

