    time_t now = time(NULL);
    fprintf(fp, "%ld,%u,%u,%u,%u\n", (long)now, c, r, g, b);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times.                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_fp != NULL) {
        fclose(g_fp);
        g_fp = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- verify sensor identity ------------------------------------- */
    int id = i2cReadByteData(g_i2c_handle, TCS34725_ID);
    if (id < 0) {
        fprintf(stderr, "Cannot read TCS34725 ID register: %s\n",
                pigpio_error(id));
        cleanup();
        return EXIT_FAILURE;
    }
    if (id != 0x44 && id != 0x10) {
        fprintf(stderr, "Unexpected TCS34725 ID: 0x%02X (expected 0x44 or 0x10)\n",
                id);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- init sensor ------------------------------------------------ */
    if (tcs34725_init(g_i2c_handle) < 0) {
        fprintf(stderr, "TCS34725 init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- open CSV --------------------------------------------------- */
    g_fp = fopen(CSV_FILENAME, "a");
    if (g_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_fp) == 0) {
        fprintf(g_fp, "timestamp,c_clear,c_red,c_green,c_blue\n");
        fflush(g_fp);
    }

    /* --- signals ---------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        uint16_t c, r, g, b;

        if (tcs34725_read_calibrated(g_i2c_handle, &c, &r, &g, &b) == 0) {
            log_data(g_fp, c, r, g, b);
        } else {
            fprintf(stderr, "Sensor read failed — logging zeros\n");
            log_data(g_fp, 0, 0, 0, 0);
        }

        gpioDelay(SAMPLE_US);
    }

    /* --- graceful shutdown ------------------------------------------ */
    cleanup();
    return EXIT_SUCCESS;
}

