        usleep(STEP_DELAY);
    }
    printf("Nighttime phase ended\n");
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (program_running) {
        if (sunrise_phase() != 0) break;
        if (daytime_phase() != 0) break;
        if (sunset_phase() != 0) break;
        if (nighttime_phase() != 0) break;
    }

    set_relay_state(RELAY1_PIN, 1);
    set_relay_state(RELAY2_PIN, 1);
    set_relay_state(RELAY3_PIN, 1);
    set_relay_state(RELAY4_PIN, 1);

    gpioTerminate();
    return 0;
}

