#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define DEBOUNCE_MS 200
#define CAPTURE_DURATION 5
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP);
    return 0;
}

static int init_logging(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

static int log_motion_event(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        perror("localtime failed");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s Motion detected on GPIO %d\n", timestamp, SENSOR_PIN) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static int capture_video(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[128];
    char command[256];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        perror("localtime failed");
        return -1;
    }
    strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S.h264", timeinfo);

    snprintf(command, sizeof(command), "raspivid -o %s%s -t %d000 -w 640 -h 480",
             VIDEO_DIR, filename, CAPTURE_DURATION);

    printf("Capturing video: %s%s\n", VIDEO_DIR, filename);
    int ret = system(command);
    if (ret == -1) {
        perror("system() failed");
        return -1;
    }
    if (!WIFEXITED(ret) || WEXITSTATUS(ret) != 0) {
        fprintf(stderr, "Video capture failed (exit status %d).\n", WEXITSTATUS(ret));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction failed");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    if (init_logging() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_PIN);

    uint32_t last_trigger_tick = 0;

    while (running) {
        int sensor_value = gpioRead(SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading GPIO %d.\n", SENSOR_PIN);
            break;
        }

        if (sensor_value == 0) {
            uint32_t now = gpioTick();
            if (now - last_trigger_tick >= DEBOUNCE_MS * 1000) {
                printf("Motion detected!\n");
                if (log_motion_event() != 0) {
                    fprintf(stderr, "Failed to log motion event.\n");
                }
                if (capture_video() != 0) {
                    fprintf(stderr, "Failed to capture video.\n");
                }
                last_trigger_tick = now;
            }
        }
        gpioDelay(50000);
    }

    printf("\nCleaning up...\n");
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

