            log_data(log_file, x, y, z);
            retries = 0;
        } else {
            fprintf(stderr, "Error reading gyro data, attempting re-initialization...\n");
            retries = 0;
            while (retries < MAX_RETRIES && running) {
                retries++;
                usleep(100000);
                if (init_mpu6050(i2c_fd) == 0) {
                    break;
                }
                fprintf(stderr, "Re-initialization attempt %d failed\n", retries);
            }
            if (retries == MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, continuing without logging\n");
            }
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

