#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define NUM_RELAYS 4

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static const int relay_pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_moisture_sensor(void) {
    return rand() % 100;
}

static int control_relay(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n", gpio_pin, pigpio_error(gpioRead(gpio_pin)));
        return -1;
    }
    return 0;
}

static void log_data(int moisture_level, const int relay_states[NUM_RELAYS]) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Moisture: %d, Relay1: %d, Relay2: %d, Relay3: %d, Relay4: %d\n",
                timestamp, moisture_level, relay_states[0], relay_states[1], relay_states[2], relay_states[3]);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 1);
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int relay_states[NUM_RELAYS] = {0, 0, 0, 0};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error setting GPIO %d as output\n", relay_pins[i]);
            cleanup();
            return 1;
        }
        if (control_relay(relay_pins[i], 1) != 0) {
            cleanup();
            return 1;
        }
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    srand(time(NULL));

    while (running) {
        int moisture_level = read_moisture_sensor();

        for (int i = 0; i < NUM_RELAYS; i++) {
            if (moisture_level < MOISTURE_THRESHOLD) {
                if (control_relay(relay_pins[i], 0) == 0) {
                    relay_states[i] = 1;
                }
            } else {
                if (control_relay(relay_pins[i], 1) == 0) {
                    relay_states[i] = 0;
                }
            }
        }

        log_data(moisture_level, relay_states);
        gpioDelay(5000000);
    }

    cleanup();
    return 0;
}

