#define FREEFALL_DURATION_S   0.5
#define FREEFALL_POLL_MS      100

/* Alarm GPIO pin (BCM numbering) */
#define ALARM_GPIO 27

/* Log file name */
#define LOG_FILE "freefall.log"

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can clean up and exit       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an ADXL345 register; returns 0 on success, -1 on  */
/* I2C write failure.                                                  */
/* ------------------------------------------------------------------ */
static int adxl345_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an ADXL345 register; returns 0 on success, -1 on */
/* I2C read failure.                                                   */
/* ------------------------------------------------------------------ */
static int adxl345_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data (DATAX0..DATAZ1) and convert to   */
/* g-force values.  Returns 0 on success, -1 on I2C failure.           */
/* ------------------------------------------------------------------ */
static int read_acceleration(int handle, float *x, float *y, float *z)
{
    char raw[6];
    int rc = i2cReadI2CBlockData(handle, ADXL345_REG_DATAX0, raw, 6);
    if (rc != 6) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData failed: expected 6 bytes, got %d\n", rc);
        return -1;
    }

    /* 16-bit two's-complement, left-justified in 10-bit mode */
    int16_t x_raw = (int16_t)(((uint8_t)raw[1] << 8) | (uint8_t)raw[0]);
    int16_t y_raw = (int16_t)(((uint8_t)raw[3] << 8) | (uint8_t)raw[2]);
    int16_t z_raw = (int16_t)(((uint8_t)raw[5] << 8) | (uint8_t)raw[4]);

    /* ±2 g range, 4 mg/LSB => divide by 256 */
    *x = (float)x_raw / 256.0f;
    *y = (float)y_raw / 256.0f;
    *z = (float)z_raw / 256.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the ADXL345: verify device ID, set ±2 g, 10-bit, standby  */
/* → measurement mode.  Returns 0 on success, -1 on failure.           */
/* ------------------------------------------------------------------ */
static int init_adxl345(int handle)
{
    uint8_t devid = 0;
    if (adxl345_read_reg(handle, ADXL345_REG_DEVID, &devid) != 0)
        return -1;

    if (devid != 0xE5) {
        fprintf(stderr, "[ERROR] ADXL345 DEVID mismatch: got 0x%02X, expected 0xE5\n", devid);
        return -1;
    }

    /* Standby mode so configuration changes take effect */
    if (adxl345_write_reg(handle, ADXL345_REG_POWER_CTL, 0x00) != 0)
        return -1;

    /* DATA_FORMAT: 0x00 → ±2 g, right-justified, 10-bit, no full-res */
    if (adxl345_write_reg(handle, ADXL345_REG_DATA_FORMAT, 0x00) != 0)
        return -1;

    /* POWER_CTL: 0x08 → measurement mode */
    if (adxl345_write_reg(handle, ADXL345_REG_POWER_CTL, 0x08) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a confirmed free-fall event to the CSV log file.                 */
/* ------------------------------------------------------------------ */
static void log_freefall(float x, float y, float z)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open %s for appending\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Trigger the alarm GPIO high for 5 seconds, checking g_running so   */
/* we can exit promptly if a SIGINT arrives during the assertion.      */
/* ------------------------------------------------------------------ */
static void trigger_alarm(int gpio_pin)
{
    if (gpioWrite(gpio_pin, 1) != 0)
        fprintf(stderr, "[WARN] gpioWrite(%d, 1) failed\n", gpio_pin);

    /* Sleep in 100 ms slices so SIGINT is noticed promptly */
    for (int i = 0; i < 50 && g_running; i++)
        gpioDelay(100000); /* 100 ms */

    if (gpioWrite(gpio_pin, 0) != 0)
        fprintf(stderr, "[WARN] gpioWrite(%d, 0) failed\n", gpio_pin);
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at ADXL345 address --- */
    g_i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                ADXL345_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialise ADXL345 --- */
    if (init_adxl345(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] ADXL345 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure alarm GPIO --- */
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", ALARM_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALARM_GPIO, 0);

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed\n");
    }

    printf("Free-fall detection started.  Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        float x, y, z;

        if (read_acceleration(g_i2c_handle, &x, &y, &z) != 0) {
            /* I2C error — back off briefly and retry */
            gpioDelay(100000);
            continue;
        }

        /* Detect free-fall: all axes below threshold */
        if (fabsf(x) < FREEFALL_THRESHOLD_G &&
            fabsf(y) < FREEFALL_THRESHOLD_G &&
            fabsf(z) < FREEFALL_THRESHOLD_G) {

            /* Confirm after 0.5 s */
            gpioDelay((uint32_t)(FREEFALL_DURATION_S * 1e6));

            if (!g_running)
                break;

            if (read_acceleration(g_i2c_handle, &x, &y, &z) != 0) {
                gpioDelay(100000);
                continue;
            }

            if (fabsf(x) < FREEFALL_THRESHOLD_G &&
                fabsf(y) < FREEFALL_THRESHOLD_G &&
                fabsf(z) < FREEFALL_THRESHOLD_G) {

                printf("[ALERT] Free-fall confirmed: X=%.3f g  Y=%.3f g  Z=%.3f g\n",
                       x, y, z);
                log_freefall(x, y, z);
                trigger_alarm(ALARM_GPIO);
            }
        }

        gpioDelay(FREEFALL_POLL_MS * 1000); /* 100 ms */
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioWrite(ALARM_GPIO, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

