#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 18
#define LOG_FILE "distance_log.txt"
#define MAX_DISTANCE_US 23200
#define TIMEOUT_US 100000
#define TRIGGER_PULSE_US 10
#define CYCLE_DELAY_US 200000

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_state = 0;
static pthread_mutex_t data_mutex;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        start_tick = tick;
        echo_state = 1;
    } else if (level == 0 && echo_state == 1) {
        end_tick = tick;
        echo_state = 2;
    }
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000);
    return 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static int read_distance(uint32_t *distance_us) {
    uint32_t timeout_start = gpioTick();
    echo_state = 0;
    start_tick = 0;
    end_tick = 0;

    trigger_sensor();

    while (echo_state != 2) {
        if (gpioTick() - timeout_start > TIMEOUT_US) {
            return -1;
        }
        gpioDelay(100);
    }

    uint32_t pulse_width = end_tick - start_tick;
    if (pulse_width > MAX_DISTANCE_US) {
        return -2;
    }

    *distance_us = pulse_width;
    return 0;
}

static double calculate_distance_cm(uint32_t pulse_width_us) {
    return (double)pulse_width_us / 58.0;
}

static int log_distance(double distance_cm) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    long timestamp_ns = (long)ts.tv_sec * 1000000000L + ts.tv_nsec;
    if (fprintf(log_file, "%ld,%.2f\n", timestamp_ns, distance_cm) < 0) {
        perror("fprintf");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (pthread_mutex_init(&data_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        return 1;
    }

    if (initialize_gpio() != 0) {
        pthread_mutex_destroy(&data_mutex);
        return 1;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        pthread_mutex_destroy(&data_mutex);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
        gpioTerminate();
        pthread_mutex_destroy(&data_mutex);
        return 1;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        uint32_t pulse_width = 0;
        int ret = read_distance(&pulse_width);

        if (ret == 0) {
            double distance_cm = calculate_distance_cm(pulse_width);
            if (log_distance(distance_cm) != 0) {
                fprintf(stderr, "Error logging distance\n");
            }
        } else if (ret == -1) {
            fprintf(stderr, "Timeout waiting for echo\n");
        } else if (ret == -2) {
            fprintf(stderr, "Distance out of range\n");
        }

        gpioDelay(CYCLE_DELAY_US);
    }

    printf("\nCleaning up...\n");
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    pthread_mutex_destroy(&data_mutex);
    printf("Exiting.\n");
    return 0;
}

