/*
 * Raspberry Pi 5 – LIS3DH Free-Fall / Impact Detector with Buzzer
 *
 * Wiring:
 *   LIS3DH SDA  -> GPIO2  (I2C bus 1 SDA)
 *   LIS3DH SCL  -> GPIO3  (I2C bus 1 SCL)
 *   LIS3DH VDD  -> 3.3 V
 *   LIS3DH GND  -> GND
 *   Buzzer +    -> GPIO17 (BCM)
 *   Buzzer -    -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o impact_detect impact_detect.c -lgpiod -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- LIS3DH constants (datasheet) ---- */
#define LIS3DH_ADDR             0x19   /* SA0 tied to GND */
#define LIS3DH_REG_CTRL1        0x20
#define LIS3DH_REG_CTRL4        0x23
#define LIS3DH_REG_OUT_X_L      0x28
#define LIS3DH_REG_WHO_AM_I     0x0F
#define LIS3DH_WHO_AM_I_VAL     0x33

/* ---- Defaults ---- */
#define DEFAULT_FREEFALL_THRESH 0.2f   /* g */
#define DEFAULT_IMPACT_THRESH   1.5f   /* g */
#define DEFAULT_BUZZER_GPIO     17
#define DEFAULT_I2C_BUS         "/dev/i2c-1"
#define DEFAULT_SAMPLE_MS       50
#define MAX_RETRIES             3

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_buzzer = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (write(fd, buf, 2) == 2)
            return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        usleep(10000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write (reg select 0x%02X) failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, MAX_RETRIES, strerror(errno));
            usleep(10000);
            continue;
        }
        if (read(fd, val, 1) == 1)
            return 0;
        fprintf(stderr, "I2C read from reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        usleep(10000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C burst write (reg 0x%02X) failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, MAX_RETRIES, strerror(errno));
            usleep(10000);
            continue;
        }
        ssize_t n = read(fd, buf, len);
        if (n == (ssize_t)len)
            return 0;
        fprintf(stderr, "I2C burst read from reg 0x%02X failed (attempt %d/%d): got %zd of %zu (%s)\n",
                reg, attempt + 1, MAX_RETRIES, n, len, strerror(errno));
        usleep(10000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
static int init_lis3dh(int fd)
{
    uint8_t who;
    if (i2c_read_reg(fd, LIS3DH_REG_WHO_AM_I, &who) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I – sensor absent or bus error.\n");
        return -1;
    }
    if (who != LIS3DH_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                who, LIS3DH_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL1: 0x57 = 100 Hz ODR, all axes enabled, normal mode */
    if (i2c_write_reg(fd, LIS3DH_REG_CTRL1, 0x57) != 0)
        return -1;

    /* CTRL4: 0x00 = +/-2 g full scale, high-resolution off */
    if (i2c_write_reg(fd, LIS3DH_REG_CTRL4, 0x00) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_accel(int fd, float *x, float *y, float *z)
{
    uint8_t raw[6];
    if (i2c_read_burst(fd, LIS3DH_REG_OUT_X_L | 0x80, raw, 6) != 0)
        return -1;

    int16_t rx = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t ry = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t rz = (int16_t)((raw[5] << 8) | raw[4]);

    /* +/-2 g => 1 mg/LSB => divide by 1000 to get g */
    *x = (float)rx / 1000.0f;
    *y = (float)ry / 1000.0f;
    *z = (float)rz / 1000.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
static float magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ------------------------------------------------------------------ */
static void trigger_buzzer(struct gpiod_line *line)
{
    if (gpiod_line_set_value(line, 1) < 0)
        fprintf(stderr, "Warning: failed to set buzzer HIGH: %s\n", strerror(errno));
    usleep(1000000);                       /* 1 s */
    if (gpiod_line_set_value(line, 0) < 0)
        fprintf(stderr, "Warning: failed to set buzzer LOW: %s\n", strerror(errno));
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_buzzer) {
        gpiod_line_set_value(g_buzzer, 0);
        gpiod_line_release(g_buzzer);
        g_buzzer = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    const char *i2c_bus = DEFAULT_I2C_BUS;
    int buzzer_gpio = DEFAULT_BUZZER_GPIO;
    float freefall_thresh = DEFAULT_FREEFALL_THRESH;
    float impact_thresh   = DEFAULT_IMPACT_THRESH;
    int   sample_ms       = DEFAULT_SAMPLE_MS;

    int opt;
    while ((opt = getopt(argc, argv, "b:g:f:i:s:")) != -1) {
        switch (opt) {
        case 'b': i2c_bus = optarg; break;
        case 'g': buzzer_gpio = atoi(optarg); break;
        case 'f': freefall_thresh = (float)atof(optarg); break;
        case 'i': impact_thresh   = (float)atof(optarg); break;
        case 's': sample_ms = atoi(optarg); break;
        default:
            fprintf(stderr,
                    "Usage: %s [-b i2c_bus] [-g buzzer_gpio] [-f freefall_g] [-i impact_g] [-s sample_ms]\n",
                    argv[0]);
            return EXIT_FAILURE;
        }
    }

