        fprintf(stderr, "Thresholds and sample rate must be positive.\n");
        return EXIT_FAILURE;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(i2c_bus, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", i2c_bus, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3DH_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                LIS3DH_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Init sensor ---- */
    if (init_lis3dh(g_i2c_fd) != 0) {
        fprintf(stderr, "LIS3DH initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip and request buzzer line ---- */
    g_chip = gpiod_chip_open_by_name("gpiochip4");   /* RP1 on Pi 5 */
    if (!g_chip) {
        g_chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!g_chip) {
        fprintf(stderr, "Cannot open GPIO chip: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_buzzer = gpiod_chip_get_line(g_chip, buzzer_gpio);
    if (!g_buzzer) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", buzzer_gpio, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_buzzer, "impact_buzzer", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO %d as output: %s\n",
                buzzer_gpio, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring LIS3DH on %s (addr 0x%02X).  Free-fall < %.2f g, Impact > %.2f g.\n",
           i2c_bus, LIS3DH_ADDR, freefall_thresh, impact_thresh);
    printf("Buzzer on GPIO%d.  Press Ctrl+C to exit.\n", buzzer_gpio);

    bool in_freefall = false;

    while (g_running) {
        float x, y, z;
        if (read_accel(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Sensor read failed – continuing.\n");
            usleep(sample_ms * 1000);
            continue;
        }

        float mag = magnitude(x, y, z);

        if (mag < freefall_thresh) {
            if (!in_freefall) {
                printf("Free-fall detected (mag %.3f g).\n", mag);
                in_freefall = true;
            }
        } else {
            in_freefall = false;
        }

        if (!in_freefall && mag > impact_thresh) {
            printf("Impact detected (mag %.3f g).\n", mag);
            trigger_buzzer(g_buzzer);
        }

        usleep(sample_ms * 1000);
    }

