    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(i2c_bus, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", i2c_bus, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3DH_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                LIS3DH_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Init sensor ---- */
    if (init_lis3dh(g_i2c_fd) != 0) {
