        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip and request buzzer line ---- */
    g_chip = gpiod_chip_open_by_name("gpiochip4");   /* RP1 on Pi 5 */
    if (!g_chip) {
