#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

#define DEFAULT_I2C_ADDRESS 0x19
#define DEFAULT_THRESHOLD 2.0f
#define LOG_FILE "/var/log/high_acceleration.log"
#define ACCEL_SCALE 0.0000610352f  /* 1/16384 g/LSB for ±2 g, 12-bit left-justified */

#define REG_CTRL_REG1 0x20
#define REG_CTRL_REG4 0x23
#define REG_OUT_X_L 0x28

static int i2c_handle = -1;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static float threshold = DEFAULT_THRESHOLD;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_lis3dh(int handle) {
    /* High-resolution mode, 12-bit left-justified, 100 Hz ODR, all axes enabled */
    if (i2cWriteByteData(handle, REG_CTRL_REG1, 0x57) < 0) return -1;
    /* ±2 g full-scale, high-resolution */
    if (i2cWriteByteData(handle, REG_CTRL_REG4, 0x08) < 0) return -1;
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, REG_OUT_X_L | 0x80, buffer, 6) != 6) {
        *x = *y = *z = 0.0f;
        return -1;
    }
    int16_t raw_x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);
    *x = (float)raw_x * ACCEL_SCALE;
    *y = (float)raw_y * ACCEL_SCALE;
    *z = (float)raw_z * ACCEL_SCALE;
    return 0;
}

static void log_acceleration(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, X: %.4f g, Y: %.4f g, Z: %.4f g\n", ts, x, y, z);
    fclose(fp);
}

static void shutdown_system(void) {
    printf("Shutting down system...\n");
    fflush(stdout);
    int rc = system("sudo shutdown -h now");
    if (rc == -1) perror("system() failed");
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                if (i2c_address < 0x18 || i2c_address > 0x29) {
                    fprintf(stderr, "Invalid I2C address 0x%02X (must be 0x18–0x29)\n", i2c_address);
                    return 0;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Threshold must be > 0\n");
                    return 0;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_addr] [-t threshold_g]\n", argv[0]);
                return 0;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 0;
    }

    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", i2c_address, i2c_handle);
        gpioTerminate();
        return 0;
    }

    if (init_lis3dh(i2c_handle) < 0) {
        fprintf(stderr, "Error initializing LIS3DH\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 0;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Monitoring acceleration (threshold %.2f g)...\n", threshold);

    while (program_running) {
        float x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) < 0) {
            fprintf(stderr, "Error reading acceleration\n");
        } else {
            if (fabsf(x) > threshold || fabsf(y) > threshold || fabsf(z) > threshold) {
                log_acceleration(x, y, z);
                shutdown_system();
                break;
            }
        }
        gpioDelay(100000); /* 100 ms */
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

