    } else if (data.right == 0) {
        printf("Turning right\n");
        /* motor_right(); */
    } else {
        printf("Stopping\n");
        /* motor_stop(); */
    }
}

static void check_alert(SensorData buffer[], int count) {
    if (count < BUFFER_SIZE) return;
    int alert = 1;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (buffer[i].center == 0) { alert = 0; break; }
    }
    if (alert) {
        printf("Line lost for 5 readings! Alerting.\n");
        /* alert_on(); */
        sleep_ms(ALERT_DURATION_S * 1000);
        /* alert_off(); */
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left_line = NULL, *center_line = NULL, *right_line = NULL, *alert_line = NULL;
    SensorData buffer[BUFFER_SIZE];
    int buffer_index = 0, buffer_count = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip4\")");
        return EXIT_FAILURE;
    }

    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);
    if (!left_line || !center_line || !right_line || !alert_line) {
        fprintf(stderr, "Failed to get one or more GPIO lines\n");
        goto cleanup;
    }

    if (gpiod_line_request_input(left_line, CONSUMER) < 0) {
        perror("gpiod_line_request_input(left)");
        goto cleanup;
    }
    if (gpiod_line_request_input(center_line, CONSUMER) < 0) {
        perror("gpiod_line_request_input(center)");
        goto cleanup;
    }
    if (gpiod_line_request_input(right_line, CONSUMER) < 0) {
        perror("gpiod_line_request_input(right)");
        goto cleanup;
    }
    if (gpiod_line_request_output(alert_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(alert)");
        goto cleanup;
    }

    printf("Line following robot started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int lv = gpiod_line_get_value(left_line);
        int cv = gpiod_line_get_value(center_line);
        int rv = gpiod_line_get_value(right_line);

        if (lv < 0 || cv < 0 || rv < 0) {
            fprintf(stderr, "Error reading sensor values: %s\n", strerror(errno));
            sleep_ms(POLL_INTERVAL_MS);
            continue;
        }

        SensorData data = { .left = lv, .center = cv, .right = rv };
        log_data(data, buffer, &buffer_index, &buffer_count);
        follow_line(data);
        check_alert(buffer, buffer_count);
        sleep_ms(POLL_INTERVAL_MS);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (alert_line) gpiod_line_set_value(alert_line, 0);
    if (left_line)   gpiod_line_release(left_line);
    if (center_line) gpiod_line_release(center_line);
    if (right_line)  gpiod_line_release(right_line);
    if (alert_line)  gpiod_line_release(alert_line);
    if (chip)        gpiod_chip_close(chip);
    printf("Exiting.\n");
    return ret;
}

