#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Si7210 I2C address (7-bit, documented) */
#define SI7210_ADDR 0x30

/* Si7210 register addresses (from datasheet) */
#define SI7210_REG_DEVICE_ID 0x00
#define SI7210_REG_MFR_ID   0x01
#define SI7210_REG_CTRL     0x02
#define SI7210_REG_STATUS   0x03
#define SI7210_REG_DATA     0x04

/* Expected device ID for Si7210 */
#define SI7210_DEVICE_ID    0x72

/* Relay GPIO pin (BCM numbering) */
#define RELAY_PIN 17

/* Magnetic field threshold (mT) */
#define MAGNETIC_FIELD_THRESHOLD 5.0f

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Log file path */
#define LOG_FILE "magnetic_events.txt"

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int  initialize_i2c(void);
static int  read_sensor_data(float *magnetic_field);
static void control_relay(int state);
static void log_event(const char *message);
static void signal_handler(int signal);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Initializes the I2C interface and verifies sensor presence */
static int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    /* Verify sensor identity by reading DEVICE_ID register */
    int device_id = i2cReadByteData(i2c_handle, SI7210_REG_DEVICE_ID);
    if (device_id < 0) {
        fprintf(stderr, "Error reading DEVICE_ID register: %d\n", device_id);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    if (device_id != SI7210_DEVICE_ID) {
        fprintf(stderr, "Unexpected DEVICE_ID: 0x%02X (expected 0x%02X)\n",
                device_id, SI7210_DEVICE_ID);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    printf("Si7210 sensor detected (DEVICE_ID=0x%02X)\n", device_id);
    return 0;
}

/* Reads magnetic field data from the Si7210 sensor */
static int read_sensor_data(float *magnetic_field) {
    if (magnetic_field == NULL) {
        return -1;
    }

    /* Read 2 bytes of magnetic field data from the DATA register */
    char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, SI7210_REG_DATA, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading magnetic field data: %d\n", result);
        return -1;
    }

    /* Combine the two bytes into a 16-bit signed integer (little-endian) */
    int16_t raw_data = (int16_t)((buffer[1] << 8) | buffer[0]);

    /* Convert raw data to magnetic field strength (mT) */
    /* Si7210 conversion factor: 1 LSB = 0.1 mT */
    *magnetic_field = (float)raw_data * 0.1f;

    return 0;
}

/* Controls the relay connected to GPIO 17 */
static void control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
}

/* Logs events to the magnetic_events.txt file */
static void log_event(const char *message) {
    if (message == NULL) {
        return;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set relay pin as output and ensure it is off initially */
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    /* Initialize I2C */
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Magnetic field monitoring started. Press Ctrl+C to exit.\n");

    int relay_state = 0;

    while (program_running) {
        float magnetic_field;

        if (read_sensor_data(&magnetic_field) == 0) {
            char log_message[128];
            snprintf(log_message, sizeof(log_message),
                     "Magnetic Field: %.2f mT", magnetic_field);
            log_event(log_message);

            if (magnetic_field > MAGNETIC_FIELD_THRESHOLD) {
                if (!relay_state) {
                    control_relay(1);
                    relay_state = 1;
                    log_event("Relay activated");
                }
            } else {
                if (relay_state) {
                    control_relay(0);
                    relay_state = 0;
                    log_event("Relay deactivated");
                }
            }
        } else {
            log_event("Error reading sensor data");
            control_relay(0);
            relay_state = 0;
        }

        gpioDelay(100000); /* 100 ms delay (pigpio uses microseconds) */
    }

    /* Cleanup */
    printf("\nCleaning up...\n");
    control_relay(0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    log_event("Program terminated");

    return 0;
}

