#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define RELAY_GPIO 18
#define PORT 5000
#define LOG_FILE "relay_log.txt"
#define BUFFER_SIZE 1024

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static int set_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        log_event("Error: Failed to write to relay GPIO");
        return -1;
    }
    return 0;
}

static int handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0);
    if (bytes_received < 0) {
        perror("recv failed");
        return -1;
    }
    if (bytes_received == 0) {
        printf("Client disconnected\n");
        return 0;
    }
    buffer[bytes_received] = '\0';
    buffer[strcspn(buffer, "\r\n")] = '\0';
    printf("Received command: %s\n", buffer);

    if (strcasecmp(buffer, "ON") == 0) {
        if (set_relay(1) == 0) {
            log_event("Relay turned ON");
            const char *response = "OK\n";
            send(client_socket, response, strlen(response), 0);
        } else {
            const char *response = "ERROR\n";
            send(client_socket, response, strlen(response), 0);
        }
    } else if (strcasecmp(buffer, "OFF") == 0) {
        if (set_relay(0) == 0) {
            log_event("Relay turned OFF");
            const char *response = "OK\n";
            send(client_socket, response, strlen(response), 0);
        } else {
            const char *response = "ERROR\n";
            send(client_socket, response, strlen(response), 0);
        }
    } else {
        log_event("Invalid command received");
        const char *response = "Invalid command\n";
        send(client_socket, response, strlen(response), 0);
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Socket creation failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("Listen failed");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);
    log_event("Server started");

    while (running) {
        struct sockaddr_in client_address;
        socklen_t client_address_len = sizeof(client_address);
        int client_socket = accept(server_fd, (struct sockaddr *)&client_address, &client_address_len);
        if (client_socket < 0) {
            if (errno == EINTR) continue;
            perror("Accept failed");
            break;
        }
        printf("Connection accepted from %s:%d\n",
               inet_ntoa(client_address.sin_addr),
               ntohs(client_address.sin_port));
        handle_client(client_socket);
        close(client_socket);
    }

    printf("Shutting down...\n");
    set_relay(0);
    log_event("Server stopped");
    if (server_fd >= 0) close(server_fd);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

