/*
 * Raspberry Pi Zero W – dual SLF3S-1300F liquid-flow sensor monitor
 *
 * Sensors : Sensirion SLF3S-1300F (40 ml/min version)
 * Bus     : I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor 1: I2C address 0x21
 * Sensor 2: I2C address 0x22
 * Relay   : GPIO 18 (BCM), active-high
 *
 * Build   : gcc -Wall -Wextra -O2 -o flow_monitor flow_monitor.c -lpigpio -lrt
 * Run     : sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */
#define I2C_BUS              1
#define SENSOR1_ADDR         0x21
#define SENSOR2_ADDR         0x22
#define RELAY_GPIO           18
#define FLOW_THRESHOLD       5.0f          /* ml/min */
#define POLL_INTERVAL_US     100000        /* 100 ms */
#define LOG_FILE             "flow_log.txt"

/* SLF3S-1300F start-measurement command (MSB first) */
#define START_MEAS_CMD_MSB   0x36
#define START_MEAS_CMD_LSB   0x15

/* --------------------------- Global state ------------------------------ */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle1 = -1;
static int  g_i2c_handle2 = -1;
static FILE *g_log_fp     = NULL;

/* ------------------------- Function prototypes ------------------------- */
static void signal_handler(int sig);
static void cleanup(void);
static uint8_t crc8(const uint8_t *data, int len);
static int  init_i2c_sensor(int addr);
static int  read_flow_rate(int handle, float *flow_out);
static void log_flow_data(float f1, float f2);
static void control_relay(float f1, float f2);

/* ----------------------------- CRC-8 ---------------------------------- */
/* Sensirion CRC-8: polynomial 0x31, init 0xFF, no final XOR */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* --------------------------- I2C helpers ------------------------------- */
static int init_i2c_sensor(int addr)
{
    int handle = i2cOpen(I2C_BUS, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(0x%02X) failed: %d\n", addr, handle);
        return -1;
    }

    /* Send start-measurement command (MSB first) */
    uint8_t cmd[2] = { START_MEAS_CMD_MSB, START_MEAS_CMD_LSB };
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] start-measurement write to 0x%02X failed\n", addr);
        i2cClose(handle);
        return -1;
    }

    return handle;
}

/*
 * Read one 3-byte measurement frame from the SLF3S-1300F.
 * Frame layout: [MSB][LSB][CRC]
 * Flow (ml/min) = (raw_be / 65535.0) * 40.0
 */
static int read_flow_rate(int handle, float *flow_out)
{
    uint8_t buf[3];
    int n = i2cReadDevice(handle, (char *)buf, 3);
    if (n != 3) {
        fprintf(stderr, "[WARN] i2cReadDevice returned %d (expected 3)\n", n);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[WARN] CRC mismatch on sensor 0x%02X\n",
                (handle == g_i2c_handle1) ? SENSOR1_ADDR : SENSOR2_ADDR);
        return -1;
    }

    uint16_t raw = (uint16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw / 65535.0f * 40.0f;
    return 0;
}

/* --------------------------- Logging ----------------------------------- */
static void log_flow_data(float f1, float f2)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_log_fp, "%s.%03ld, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
            tbuf, ts.tv_nsec / 1000000L, f1, f2);
    fflush(g_log_fp);
}

/* --------------------------- Relay control ----------------------------- */
static void control_relay(float f1, float f2)
{
    int state = (f1 < FLOW_THRESHOLD || f2 < FLOW_THRESHOLD) ? 1 : 0;
    if (gpioWrite(RELAY_GPIO, state) != 0)
        fprintf(stderr, "[ERROR] gpioWrite(%d) failed\n", RELAY_GPIO);
}

/* --------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    /* De-energize relay first for safety */
    if (g_i2c_handle1 >= 0 || g_i2c_handle2 >= 0)
        gpioWrite(RELAY_GPIO, 0);

    if (g_i2c_handle1 >= 0) {
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
    }
    if (g_i2c_handle2 >= 0) {
        i2cClose(g_i2c_handle2);
        g_i2c_handle2 = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d) failed\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);  /* ensure relay starts de-energized */

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("[FATAL] fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize I2C sensors */
    g_i2c_handle1 = init_i2c_sensor(SENSOR1_ADDR);
    if (g_i2c_handle1 < 0) { cleanup(); return EXIT_FAILURE; }

    g_i2c_handle2 = init_i2c_sensor(SENSOR2_ADDR);
    if (g_i2c_handle2 < 0) { cleanup(); return EXIT_FAILURE; }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = read_flow_rate(g_i2c_handle1, &f1);
        int ok2 = read_flow_rate(g_i2c_handle2, &f2);

        if (ok1 == 0 && ok2 == 0) {
            log_flow_data(f1, f2);
            control_relay(f1, f2);
        } else {
            fprintf(stderr, "[WARN] Skipping cycle due to read/CRC error\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

