        syslog(LOG_ERR, "gpioSetMode(%u, %u) failed", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_set_pull(unsigned pin, unsigned pull)
{
    if (gpioSetPullUpDown(pin, pull) != 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(%u, %u) failed", pin, pull);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        syslog(LOG_ERR, "gpioWrite(%u, %u) failed", pin, level);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        syslog(LOG_ERR, "gpioRead(%u) failed", pin);
        return -1;
    }
    return v;
}

static int motor_stop(void)
{
    int rc = 0;
    rc |= safe_write(MOTOR_ENA_PIN, 0);
    rc |= safe_write(MOTOR_IN1_PIN, 0);
    rc |= safe_write(MOTOR_IN2_PIN, 0);
    return rc;
}

static int motor_run(void)
{
    int rc = 0;
    rc |= safe_write(MOTOR_ENA_PIN, 1);
    rc |= safe_write(MOTOR_IN1_PIN, 1);
    rc |= safe_write(MOTOR_IN2_PIN, 0);
    return rc;
}

static void cleanup(void)
{
    motor_stop();
    gpioTerminate();
    closelog();
}

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "gpioInitialise failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (safe_set_mode(RAIN_SENSOR_PIN, PI_INPUT) != 0 ||
        safe_set_mode(MOTOR_ENA_PIN, PI_OUTPUT)  != 0 ||
        safe_set_mode(MOTOR_IN1_PIN, PI_OUTPUT)  != 0 ||
        safe_set_mode(MOTOR_IN2_PIN, PI_OUTPUT)  != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (safe_set_pull(RAIN_SENSOR_PIN, PI_PUD_UP) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure motor is stopped at startup */
    if (motor_stop() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Rain sensor monitoring started (GPIO %d). Motor: ENA=%d IN1=%d IN2=%d",
           RAIN_SENSOR_PIN, MOTOR_ENA_PIN, MOTOR_IN1_PIN, MOTOR_IN2_PIN);

    int prev_rain = 1;   /* assume dry at startup (pull-up high) */
    int dry_count = 0;
    int armed = 1;

    while (g_running) {
        int rain = safe_read(RAIN_SENSOR_PIN);
        if (rain < 0) {
            usleep(POLL_INTERVAL_US);
            continue;
        }

        int rising = (prev_rain == 1 && rain == 0);

        if (rising && armed) {
            syslog(LOG_INFO, "Rain detected (rising edge). Closing window...");
            if (motor_run() != 0) {
                syslog(LOG_ERR, "Motor start failed");
            } else {
                syslog(LOG_INFO, "Motor started");
            }

            /* Hold motor for 5 s; pigpio gpioDelay is a busy-wait, but
             * we break it into 100 ms slices so signals are caught promptly. */
            for (int i = 0; i < 50 && g_running; i++) {
                gpioDelay(100000); /* 100 ms */
            }

            if (motor_stop() != 0) {
                syslog(LOG_ERR, "Motor stop failed");
            } else {
                syslog(LOG_INFO, "Motor stopped");
            }
            armed = 0;
        }

        if (!rising) {
            if (rain == 1) {
                dry_count++;
                if (dry_count >= DRY_COOLDOWN) {
                    armed = 1;
                    syslog(LOG_INFO, "Sensor dry for %d polls; re-arming",
                           DRY_COOLDOWN);
                }
            } else {
                dry_count = 0;
            }
        }

        prev_rain = rain;
        usleep(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

