#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22

#define LOCK_PULSE_US  2000
#define UNLOCK_PULSE_US 1000
#define STOP_PULSE_US  0

#define DEBOUNCE_US    50000   /* 50 ms debounce after release */
#define POLL_US        10000   /* 10 ms poll interval */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo_pulse(int pulse_us)
{
    int rc = gpioServo(SERVO_PIN, pulse_us);
    if (rc < 0) {
        fprintf(stderr, "Error: gpioServo(%d) failed (rc=%d)\n", pulse_us, rc);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    set_servo_pulse(STOP_PULSE_US);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(SERVO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) < 0 ||
        gpioSetMode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(button) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Door lock control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            printf("Locking door...\n");
            fflush(stdout);
            if (set_servo_pulse(LOCK_PULSE_US) < 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            usleep(DEBOUNCE_US);
            while (g_running && gpioRead(LOCK_BUTTON) == 0) {
                usleep(POLL_US);
            }
            usleep(DEBOUNCE_US);
        }

        if (gpioRead(UNLOCK_BUTTON) == 0) {
            printf("Unlocking door...\n");
            fflush(stdout);
            if (set_servo_pulse(UNLOCK_PULSE_US) < 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            usleep(DEBOUNCE_US);
            while (g_running && gpioRead(UNLOCK_BUTTON) == 0) {
                usleep(POLL_US);
            }
            usleep(DEBOUNCE_US);
        }

        usleep(POLL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

