#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define PIR_PIN 4
#define FLOODLIGHT_PIN 17
#define LOG_FILE "security_log.txt"
#define POLL_INTERVAL_US 100000
#define FLOODLIGHT_DURATION_S 60

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int activate_floodlight(int duration_s) {
    if (gpioWrite(FLOODLIGHT_PIN, 1) != 0) {
        fprintf(stderr, "Failed to turn floodlight ON\n");
        return -1;
    }

    if (log_event("Floodlight activated") != 0) {
        gpioWrite(FLOODLIGHT_PIN, 0);
        return -1;
    }

    for (int i = 0; i < duration_s && g_running; i++) {
        sleep(1);
    }

    if (gpioWrite(FLOODLIGHT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to turn floodlight OFF\n");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Floodlight deactivated after %d seconds", duration_s);

    if (log_event(log_message) != 0) {
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set floodlight pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(FLOODLIGHT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize floodlight to OFF\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioWrite(FLOODLIGHT_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        gpioWrite(FLOODLIGHT_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Security system started. PIR=GPIO%d, Floodlight=GPIO%d\n", PIR_PIN, FLOODLIGHT_PIN);
    printf("Press Ctrl+C to exit.\n");

    int last_pir_state = 0;

    while (g_running) {
        int pir_state = gpioRead(PIR_PIN);
        if (pir_state < 0) {
            fprintf(stderr, "Failed to read PIR pin\n");
            break;
        }

        if (pir_state == 1 && last_pir_state == 0) {
            printf("Motion detected!\n");
            if (activate_floodlight(FLOODLIGHT_DURATION_S) != 0) {
                fprintf(stderr, "Floodlight activation failed\n");
                break;
            }
        }

        last_pir_state = pir_state;
        usleep(POLL_INTERVAL_US);
    }

    gpioWrite(FLOODLIGHT_PIN, 0);
    gpioTerminate();
    printf("Security system stopped.\n");
    return EXIT_SUCCESS;
}

