/*
 * MPR121 Capacitive Touch Sensor -> Relay Toggle
 * Board:  Raspberry Pi 5 (40-pin header)
 * Sensor: MPR121 on I2C bus 1, address 0x5A
 * Relay:  GPIO17 (BCM) active-high
 *
 * Build:  gcc -O2 -Wall -Wextra -o mpr121_relay mpr121_relay.c -lpigpio -lrt
 * Run:    sudo ./mpr121_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- MPR121 I2C address ---- */
#define MPR121_ADDR 0x5A

/* ---- MPR121 register addresses ---- */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ELECONFIG      0x5E
#define MPR121_SOFTRESET      0x80
#define MPR121_MHD_R          0x2B
#define MPR121_NHD_R          0x2C
#define MPR121_NCL_R          0x2D
#define MPR121_FDL_R          0x2E
#define MPR121_MHD_F          0x2F
#define MPR121_NHD_F          0x30
#define MPR121_NCL_F          0x31
#define MPR121_FDL_F          0x32
#define MPR121_E0TTH          0x41
#define MPR121_E0RTH          0x42
#define MPR121_DEBOUNCE       0x5B
#define MPR121_CONFIG1        0x5C
#define MPR121_CONFIG2        0x5D
#define MPR121_AUTOCONFIG0    0x7B
#define MPR121_AUTOCONFIG1    0x7C
#define MPR121_USL            0x7D
#define MPR121_LSL            0x7E
#define MPR121_TL             0x7F

/* ---- Relay GPIO ---- */
#define RELAY_GPIO 17

/* ---- Debounce time (ms) ---- */
#define DEBOUNCE_TIME_MS 200

/* ---- Global state ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static bool g_relay_state = false;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */
static int mpr121_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

static int mpr121_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ---- Relay control ---- */
static int relay_set(bool state)
{
    int rc = gpioWrite(RELAY_GPIO, state ? 1 : 0);
    if (rc < 0) {
        fprintf(stderr, "gpioWrite failed (pin=%d): %s\n",
                RELAY_GPIO, pigpio_error(rc));
        return -1;
    }
    g_relay_state = state;
    printf("Relay %s\n", state ? "ON" : "OFF");
    return 0;
}

/* ---- MPR121 initialization ---- */
static int mpr121_init(void)
{
    /* Soft reset */
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    gpioDelay(2000); /* 2 ms settle */

    /* Baseline filtering (rising) */
    if (mpr121_write_reg(MPR121_MHD_R, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_R, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_R, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_R, 0x00) < 0) return -1;

    /* Baseline filtering (falling) */
    if (mpr121_write_reg(MPR121_MHD_F, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_F, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_F, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_F, 0x00) < 0) return -1;

    /* Touch / release thresholds for electrode 0 */
    if (mpr121_write_reg(MPR121_E0TTH, 0x0F) < 0) return -1;
    if (mpr121_write_reg(MPR121_E0RTH, 0x0A) < 0) return -1;

    /* Debounce: 3 samples for both touch and release */
    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI=6 samples, SFI=4 samples, CDT=0.5 us */
    if (mpr121_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;
    /* CDC=16 µA, ESI=1 ms */
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Auto-config: enable, retries=2, lower/upper range */
    if (mpr121_write_reg(MPR121_AUTOCONFIG0, 0x0B) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTOCONFIG1, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_USL, 0xC8) < 0) return -1;
    if (mpr121_write_reg(MPR121_LSL, 0x82) < 0) return -1;
    if (mpr121_write_reg(MPR121_TL, 0xB4) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking */
    if (mpr121_write_reg(MPR121_ELECONFIG, 0x0C) < 0) return -1;

    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /* Put MPR121 into standby (disable electrodes) */
        (void)i2cWriteByteData(g_i2c_handle, MPR121_ELECONFIG, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    /* Ensure relay is OFF */
    if (g_relay_state) {
        (void)gpioWrite(RELAY_GPIO, 0);
        g_relay_state = false;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed (pin=%d): %s\n",
                RELAY_GPIO, pigpio_error(gpioGetMode(RELAY_GPIO)));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (relay_set(false) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at MPR121 address */
    g_i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor presence by reading TOUCHSTATUS_L */
    uint8_t dummy;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_L, &dummy) < 0) {
        fprintf(stderr, "MPR121 not detected at address 0x%02X\n", MPR121_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 relay controller running. Press Ctrl+C to exit.\n");

    uint32_t last_touch_time = 0;
    bool last_touched = false;

    while (g_running) {
        uint8_t lo, hi;
        if (mpr121_read_reg(MPR121_TOUCHSTATUS_L, &lo) < 0 ||
            mpr121_read_reg(MPR121_TOUCHSTATUS_H, &hi) < 0) {
            gpioDelay(100000); /* 100 ms backoff on error */
            continue;
        }

        uint16_t touch_status = (uint16_t)((hi << 8) | lo);
        bool touched = (touch_status & 0x0001) != 0;

        /* Detect rising edge on electrode 0 */
        if (touched && !last_touched) {
            uint32_t now = gpioTick();
            if (now - last_touch_time > (uint32_t)(DEBOUNCE_TIME_MS * 1000)) {
                last_touch_time = now;
                if (relay_set(!g_relay_state) < 0) {
                    fprintf(stderr, "Failed to toggle relay\n");
                }
            }
        }
        last_touched = touched;

        gpioDelay(10000); /* 10 ms poll interval */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

