#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <stdarg.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define LOG_FILE "security.log"
#define BUFFER_SIZE 1024
#define PWM_FREQUENCY 50
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;

static void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(priority, format, args);
    va_end(args);
    if (log_file) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
        fprintf(log_file, "%s ", timestamp);
        va_start(args, format);
        vfprintf(log_file, format, args);
        va_end(args);
        fprintf(log_file, "\n");
        fflush(log_file);
    }
}

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_message(LOG_ERR, "Invalid angle: %d", angle);
        return -1;
    }
    int pulse_width = MIN_PULSE_WIDTH + (int)((float)angle / 180.0f * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));
    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        log_message(LOG_ERR, "Failed to set servo pulse width: %d", pulse_width);
        return -1;
    }
    log_message(LOG_INFO, "Servo angle set to: %d", angle);
    return 0;
}

static int read_pir_sensor(void) {
    int value = gpioRead(PIR_PIN);
    if (value < 0) {
        log_message(LOG_ERR, "Failed to read PIR sensor");
        return -1;
    }
    return value;
}

static void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0);
    if (bytes_received < 0) {
        log_message(LOG_ERR, "recv failed: %s", strerror(errno));
        close(client_socket);
        return;
    }
    if (bytes_received == 0) {
        log_message(LOG_INFO, "Client disconnected");
        close(client_socket);
        return;
    }
    buffer[bytes_received] = '\0';
    buffer[strcspn(buffer, "\r\n")] = '\0';
    log_message(LOG_INFO, "Received command: %s", buffer);
    if (strncmp(buffer, "the library's API call", 22) == 0) {
        char *angle_str = buffer + 22;
        angle_str += strspn(angle_str, " ");
        if (*angle_str == '\0') {
            log_message(LOG_ERR, "Missing angle in command");
            const char *response = "Error: Missing angle\n";
            send(client_socket, response, strlen(response), 0);
        } else {
            int angle = atoi(angle_str);
            if (set_servo_angle(angle) == 0) {
                const char *response = "OK\n";
                send(client_socket, response, strlen(response), 0);
            } else {
                const char *response = "Error: Invalid angle\n";
                send(client_socket, response, strlen(response), 0);
            }
        }
    } else if (strcmp(buffer, "PIR") == 0) {
        int pir_value = read_pir_sensor();
        if (pir_value >= 0) {
            char response[32];
            snprintf(response, sizeof(response), "PIR:%d\n", pir_value);
            send(client_socket, response, strlen(response), 0);
        } else {
            const char *response = "Error: Failed to read PIR\n";
            send(client_socket, response, strlen(response), 0);
        }
    } else {
        log_message(LOG_ERR, "Invalid command: %s", buffer);
        const char *response = "Error: Invalid command\n";
        send(client_socket, response, strlen(response), 0);
    }
    close(client_socket);
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set SERVO_PIN mode");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        log_message(LOG_ERR, "Failed to set PIR_PIN mode");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) != 0) {
        log_message(LOG_ERR, "Failed to set PIR pull-down");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int setup_socket(void) {
    struct sockaddr_in address;
    int opt = 1;
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_message(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_message(LOG_ERR, "setsockopt failed: %s", strerror(errno));
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Bind failed: %s", strerror(errno));
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed: %s", strerror(errno));
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    log_message(LOG_INFO, "Listening on port %d", PORT);
    return 0;
}

static void cleanup(void) {
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    closelog();
}

int main(void) {
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        closelog();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_message(LOG_ERR, "Failed to set signal handler: %s", strerror(errno));
        cleanup();
        return 1;
    }
    if (setup_gpio() != 0) {
        cleanup();
        return 1;
    }
    if (setup_socket() != 0) {
        cleanup();
        return 1;
    }
    while (running) {
        struct sockaddr_in client_address;
        socklen_t addrlen = sizeof(client_address);
        int client_socket = accept(server_fd, (struct sockaddr *)&client_address, &addrlen);
        if (client_socket < 0) {
            if (errno == EINTR && !running) break;
            log_message(LOG_ERR, "Accept failed: %s", strerror(errno));
            continue;
        }
        handle_client(client_socket);
    }
    log_message(LOG_INFO, "Shutting down");
    cleanup();
    return 0;
