#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define BH1750_ADDR    0x23
#define RELAY_PIN      23
#define LUX_THRESHOLD  150.0f
#define LOG_FILE       "grow_log.txt"
#define SAMPLE_US      2000000  /* 2 s */
#define BH1750_CONV_US 120000   /* 120 ms */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure relay is off before terminating pigpio */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise GPIO %d low.\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed on bus %d addr 0x%02X (rc=%d).\n",
                I2C_BUS, BH1750_ADDR, g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }
    return 0;
}

static int init_log(void)
{
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error: failed to open log file");
        return -1;
    }
    return 0;
}

/*
 * Trigger a one-time high-resolution (1 lux) measurement and read the
 * 2-byte result.  Returns 0 on success and stores the lux value in *lux.
 * Returns -1 on any I2C error.
 */
static int read_bh1750(float *lux)
{
    char buf[2];
    int  rc;

    /* Power on + reset (0x01) then trigger one-time high-res mode (0x20) */
    rc = i2cWriteByte(g_i2c_handle, 0x01);
    if (rc < 0) {
        fprintf(stderr, "Error: BH1750 power-on reset failed (rc=%d).\n", rc);
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    rc = i2cWriteByte(g_i2c_handle, 0x20);
    if (rc < 0) {
        fprintf(stderr, "Error: BH1750 one-time high-res trigger failed (rc=%d).\n", rc);
        return -1;
    }

    gpioDelay(BH1750_CONV_US); /* 120 ms conversion time */

    rc = i2cReadDevice(g_i2c_handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error: BH1750 read failed (rc=%d).\n", rc);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static void log_data(float lux)
{
    time_t     t  = time(NULL);
    struct tm  tm;
    char       ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Warning: localtime_r failed; logging without timestamp.\n");
        fprintf(g_log_file, "UNKNOWN, %.2f\n", lux);
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(g_log_file, "%s, %.2f\n", ts, lux);
    }
    fflush(g_log_file);
}

static void control_relay(float lux)
{
    int level = (lux < LUX_THRESHOLD) ? 1 : 0;
    if (gpioWrite(RELAY_PIN, level) < 0) {
        fprintf(stderr, "Warning: gpioWrite failed on pin %d.\n", RELAY_PIN);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error: sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error: sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }
    if (init_i2c() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (init_log() < 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Grow-light controller started.  Logging to %s\n", LOG_FILE);

    while (g_running) {
        float lux;

        if (read_bh1750(&lux) == 0) {
            log_data(lux);
            control_relay(lux);
            printf("Lux: %.2f  Relay: %s\n", lux, (lux < LUX_THRESHOLD) ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Warning: sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 20 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

