/*
 * Raspberry Pi 3 Model B+ — Load-cell (TAL220B + HX711) weight monitor
 * with solenoid lock activation on threshold breach.
 *
 * Wiring:
 *   HX711 DOUT  -> GPIO23 (physical pin 16)
 *   HX711 SCK   -> GPIO24 (physical pin 18)
 *   Solenoid    -> GPIO25 (physical pin 22) via transistor/MOSFET
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o weight_monitor weight_monitor.c -lgpiod -lm
 *
 * Run:
 *   ./weight_monitor [--threshold 1000] [--scale 1.0] [--duration 200]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <syslog.h>
#include <gpiod.h>

#define HX711_DOUT_LINE	23
#define HX711_SCK_LINE	24
#define SOLENOID_LINE	25

#define DEFAULT_THRESHOLD	1000.0
#define DEFAULT_SCALE		1.0
#define DEFAULT_DURATION_MS	200
#define DEFAULT_TARE_SAMPLES	10
#define DEFAULT_READ_SAMPLES	5
#define DEFAULT_HX711_TIMEOUT_MS	1000
#define DEFAULT_HX711_MAX_RETRIES	3
#define POLL_INTERVAL_MS	500

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
	(void)sig;
	g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
	struct timespec ts = {
		.tv_sec  = ms / 1000,
		.tv_nsec = (long)(ms % 1000) * 1000000L
	};
	nanosleep(&ts, NULL);
}

/*
 * Read a 24-bit two's-complement value from the HX711.
 * Returns 0 on success, -1 on timeout or error.
 */
static int hx711_read(struct gpiod_line *dout, struct gpiod_line *sck,
                      int32_t *out)
{
	int val;
	int retry;

	for (retry = 0; retry < DEFAULT_HX711_MAX_RETRIES; retry++) {
		/* Wait for DOUT to go LOW (data ready). */
		for (int waited = 0; waited < DEFAULT_HX711_TIMEOUT_MS; waited++) {
			val = gpiod_line_get_value(dout);
			if (val < 0) {
				syslog(LOG_ERR, "gpiod_line_get_value(DOUT) failed: %m");
				break;
			}
			if (val == 0)
				goto ready;
			sleep_ms(1);
		}

		syslog(LOG_WARNING, "HX711 DOUT timeout (attempt %d/%d)",
		       retry + 1, DEFAULT_HX711_MAX_RETRIES);
		continue;

ready:
		int32_t data = 0;
		for (int i = 0; i < 24; i++) {
			if (gpiod_line_set_value(sck, 1) < 0) {
				syslog(LOG_ERR, "SCK high failed: %m");
				return -1;
			}
			sleep_ms(1);

			val = gpiod_line_get_value(dout);
			if (val < 0) {
				syslog(LOG_ERR, "DOUT read failed: %m");
				return -1;
			}
			data = (data << 1) | (val & 1);

			if (gpiod_line_set_value(sck, 0) < 0) {
				syslog(LOG_ERR, "SCK low failed: %m");
				return -1;
			}
			sleep_ms(1);
		}

		/* 25th pulse: select Channel A, gain 128. */
		if (gpiod_line_set_value(sck, 1) < 0) {
			syslog(LOG_ERR, "SCK high (25th) failed: %m");
			return -1;
		}
		sleep_ms(1);
		if (gpiod_line_set_value(sck, 0) < 0) {
			syslog(LOG_ERR, "SCK low (25th) failed: %m");
			return -1;
		}
		sleep_ms(1);

		/* Sign-extend 24-bit two's complement to 32-bit. */
		if (data & 0x800000)
			data |= 0xFF000000;

		*out = data;
		return 0;
	}

	syslog(LOG_ERR, "HX711 DOUT never went LOW after %d retries",
	       DEFAULT_HX711_MAX_RETRIES);
	return -1;
}

static double hx711_tare(struct gpiod_line *dout, struct gpiod_line *sck,
                         int samples)
{
	double sum = 0.0;
	int32_t raw;

	for (int i = 0; i < samples; i++) {
		if (hx711_read(dout, sck, &raw) != 0) {
			syslog(LOG_ERR, "Tare read %d failed", i);
			return NAN;
		}
		sum += (double)raw;
		sleep_ms(100);
	}
	return sum / samples;
}

static double hx711_read_weight(struct gpiod_line *dout, struct gpiod_line *sck,
                                 int samples, double scale)
{
	double sum = 0.0;
	int32_t raw;

	for (int i = 0; i < samples; i++) {
		if (hx711_read(dout, sck, &raw) != 0) {
			syslog(LOG_ERR, "Weight read %d failed", i);
			return NAN;
		}
		sum += (double)raw;
		sleep_ms(100);
	}
	return (sum / samples) * scale;
}

static void activate_solenoid(struct gpiod_line *sol, int duration_ms)
{
	if (gpiod_line_set_value(sol, 1) < 0) {
		syslog(LOG_ERR, "Failed to set solenoid HIGH: %m");
		return;
	}
	syslog(LOG_INFO, "Solenoid activated for %d ms", duration_ms);
	sleep_ms(duration_ms);
	if (gpiod_line_set_value(sol, 0) < 0) {
		syslog(LOG_ERR, "Failed to set solenoid LOW: %m");
	}
	syslog(LOG_INFO, "Solenoid deactivated");
}

int main(int argc, char *argv[])
{
	const char *chip_name = "gpiochip0";
	double threshold = DEFAULT_THRESHOLD;
	double scale = DEFAULT_SCALE;
	int duration_ms = DEFAULT_DURATION_MS;
	int opt;

	while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
		switch (opt) {
		case 't':
			threshold = atof(optarg);
			break;
		case 's':
			scale = atof(optarg);
			break;
		case 'd':
			duration_ms = atoi(optarg);
			break;
		default:
			fprintf(stderr,
			        "Usage: %s [--threshold <g>] [--scale <f>] [--duration <ms>]\n",
			        argv[0]);
			return EXIT_FAILURE;
		}
	}

	openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

	struct sigaction sa;
	memset(&sa, 0, sizeof(sa));
	sa.sa_handler = signal_handler;
	sigemptyset(&sa.sa_mask);
	sa.sa_flags = 0;
	if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
		syslog(LOG_ERR, "sigaction failed: %m");
		closelog();
		return EXIT_FAILURE;
	}

	struct gpiod_chip *chip = gpiod_chip_open_by_name(chip_name);
	if (!chip) {
		syslog(LOG_ERR, "gpiod_chip_open_by_name(%s) failed: %m", chip_name);
		closelog();
		return EXIT_FAILURE;
	}

	struct gpiod_line *dout = gpiod_chip_get_line(chip, HX711_DOUT_LINE);
	struct gpiod_line *sck  = gpiod_chip_get_line(chip, HX711_SCK_LINE);
	struct gpiod_line *sol  = gpiod_chip_get_line(chip, SOLENOID_LINE);

	if (!dout || !sck || !sol) {
		syslog(LOG_ERR, "gpiod_chip_get_line failed: %m");
		gpiod_chip_close(chip);
		closelog();
		return EXIT_FAILURE;
	}

	if (gpiod_line_request_input(dout, "hx711_dout") < 0) {
		syslog(LOG_ERR, "Request DOUT as input failed: %m");
		goto cleanup;
	}
	if (gpiod_line_request_output(sck, "hx711_sck", 0) < 0) {
		syslog(LOG_ERR, "Request SCK as output failed: %m");
		goto cleanup;
	}
	if (gpiod_line_request_output(sol, "solenoid", 0) < 0) {
