#include <stdbool.h>
#include <pigpio.h>

#include <mosquitto.h>

#define MQTT_HOST          "localhost"
#define MQTT_PORT          1883
#define MQTT_CLIENT_ID     "relay_controller_1"
#define MQTT_TOPIC         "home/lights/control"
#define MQTT_KEEPALIVE     60
#define MQTT_QOS           0
#define GPIO_PIN           17
#define RECONNECT_DELAY_S  5
#define PAYLOAD_MAX        256

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void on_connect(struct mosquitto *mosq, void *userdata, int result)
{
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to %s:%d, client ID %s",
               MQTT_HOST, MQTT_PORT, MQTT_CLIENT_ID);
        int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to %s: %s",
                   MQTT_TOPIC, mosquitto_strerror(rc));
        } else {
            syslog(LOG_INFO, "Subscribed to %s", MQTT_TOPIC);
        }
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(result));
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)mosq;
    (void)userdata;
    if (rc == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT disconnected cleanly");
    } else {
        syslog(LOG_ERR, "MQTT unexpected disconnect: %s", mosquitto_strerror(rc));
    }
}

static void on_message(struct mosquitto *mosq, void *userdata,
                       const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (!message || !message->payload || message->payloadlen <= 0) {
        syslog(LOG_ERR, "Received empty MQTT message on %s", MQTT_TOPIC);
        return;
    }

    /* Ensure NUL-termination for safe string handling */
    char payload[PAYLOAD_MAX + 1];
    int len = message->payloadlen;
    if (len > PAYLOAD_MAX) len = PAYLOAD_MAX;
    memcpy(payload, message->payload, (size_t)len);
    payload[len] = '\0';

    syslog(LOG_INFO, "Received on %s: %s", MQTT_TOPIC, payload);

    if (strcmp(payload, "ON") == 0) {
        if (gpioWrite(GPIO_PIN, 1) == 0) {
            syslog(LOG_INFO, "Relay ON");
        } else {
            syslog(LOG_ERR, "Failed to set GPIO%d HIGH", GPIO_PIN);
        }
    } else if (strcmp(payload, "OFF") == 0) {
        if (gpioWrite(GPIO_PIN, 0) == 0) {
            syslog(LOG_INFO, "Relay OFF");
        } else {
            syslog(LOG_ERR, "Failed to set GPIO%d LOW", GPIO_PIN);
        }
    } else {
        syslog(LOG_ERR, "Invalid payload: %s", payload);
    }
}

static void on_subscribe(struct mosquitto *mosq, void *userdata,
                         int mid, int qos_count, const int *granted_qos)
{
    (void)mosq;
    (void)userdata;
    (void)mid;
    if (qos_count > 0 && granted_qos[0] == MQTT_QOS) {
        syslog(LOG_INFO, "Subscribed to %s with QoS %d", MQTT_TOPIC, MQTT_QOS);
    } else {
        syslog(LOG_ERR, "Subscribe to %s failed (qos_count=%d, qos=%d)",
               MQTT_TOPIC, qos_count, qos_count > 0 ? granted_qos[0] : -1);
    }
}

static void on_log(struct mosquitto *mosq, void *userdata, int level, const char *message)
{
    (void)mosq;
    (void)userdata;
    const char *level_str = "UNKNOWN";
    switch (level) {
        case MOSQ_LOG_DEBUG:   level_str = "DEBUG";   break;
        case MOSQ_LOG_INFO:    level_str = "INFO";    break;
        case MOSQ_LOG_NOTICE:  level_str = "NOTICE";  break;
        case MOSQ_LOG_WARNING: level_str = "WARNING"; break;
        case MOSQ_LOG_ERR:     level_str = "ERROR";   break;
    }
    syslog(LOG_INFO, "MQTT %s: %s", level_str, message);
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(GPIO_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to initialise GPIO%d LOW", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    syslog(LOG_INFO, "GPIO%d initialised as output, relay OFF", GPIO_PIN);
    return 0;
}

static void cleanup_gpio(void)
{
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    syslog(LOG_INFO, "GPIO%d terminated", GPIO_PIN);
}

static int init_mqtt(void)
{
    int rc = mosquitto_lib_init();
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_lib_init failed: %s", mosquitto_strerror(rc));
        return -1;
    }

    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        syslog(LOG_ERR, "mosquitto_new failed: %s", mosquitto_strerror(MOSQ_ERR_NOMEM));
        mosquitto_lib_cleanup();
        return -1;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_message_callback_set(g_mosq, on_message);
    mosquitto_subscribe_callback_set(g_mosq, on_subscribe);
    mosquitto_log_callback_set(g_mosq, on_log);

    rc = mosquitto_connect(g_mosq, MQTT_HOST, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_connect to %s:%d failed: %s",
               MQTT_HOST, MQTT_PORT, mosquitto_strerror(rc));
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

static void cleanup_mqtt(void)
{
    if (g_mosq) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    mosquitto_lib_cleanup();
    syslog(LOG_INFO, "MQTT cleaned up");
}

int main(void)
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    if (init_mqtt() != 0) {
        cleanup_gpio();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Relay controller started on GPIO%d", GPIO_PIN);

    while (g_running) {
        int rc = mosquitto_loop(g_mosq, 1000, 1);
        if (rc == MOSQ_ERR_CONN_LOST || rc == MOSQ_ERR_NO_CONN) {
            syslog(LOG_WARNING, "MQTT connection lost, reconnecting in %d s",
                   RECONNECT_DELAY_S);
            sleep(RECONNECT_DELAY_S);
            if (!g_running) break;
            rc = mosquitto_reconnect(g_mosq);
            if (rc != MOSQ_ERR_SUCCESS) {
                syslog(LOG_ERR, "Reconnect failed: %s, retrying in %d s",
                       mosquitto_strerror(rc), RECONNECT_DELAY_S);
                sleep(RECONNECT_DELAY_S);
            }
        } else if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_loop error: %s", mosquitto_strerror(rc));
            sleep(RECONNECT_DELAY_S);
        }
    }

    syslog(LOG_INFO, "Shutting down relay controller");
    cleanup_mqtt();
    cleanup_gpio();
    closelog();
    return EXIT_SUCCESS;
}

