#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_TARGET_1 1000
#define SERVO_TARGET_2 1500
#define SERVO_TARGET_3 2000
#define SERVO_TARGET_4 500
#define SERVO_TARGET_5 2500
#define SERVO_HOLD_TIME 3

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {SERVO1_PIN, SERVO2_PIN, SERVO3_PIN, SERVO4_PIN, SERVO5_PIN};
    int targets[] = {SERVO_TARGET_1, SERVO_TARGET_2, SERVO_TARGET_3, SERVO_TARGET_4, SERVO_TARGET_5};
    int num_servos = sizeof(pins) / sizeof(pins[0]);

    for (int i = 0; i < num_servos; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_servos; i++) {
        int pulse_width = targets[i];
        if (pulse_width < SERVO_MIN_PULSE_WIDTH) pulse_width = SERVO_MIN_PULSE_WIDTH;
        if (pulse_width > SERVO_MAX_PULSE_WIDTH) pulse_width = SERVO_MAX_PULSE_WIDTH;

        if (gpioServo(pins[i], pulse_width) != 0) {
            fprintf(stderr, "Failed to set servo on GPIO %d to %d us\n", pins[i], pulse_width);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        printf("Servo %d: pulse width = %d us\n", i + 1, pulse_width);
        sleep(SERVO_HOLD_TIME);
    }

    for (int i = 0; i < num_servos; i++) {
        gpioServo(pins[i], 0);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

