#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define MOTOR_A_PWM_PIN    17
#define MOTOR_A_DIR_PIN    18
#define MOTOR_B_PWM_PIN    22
#define MOTOR_B_DIR_PIN    23

#define ENCODER_A_A_PIN    4
#define ENCODER_A_B_PIN    5
#define ENCODER_B_A_PIN    6
#define ENCODER_B_B_PIN   12

/* ---- Motor / encoder parameters ---- */
#define TARGET_RPM         50.0
#define ENCODER_TICKS_PER_REV 64
#define PWM_FREQUENCY      10000   /* 10 kHz */
#define PWM_RANGE          255
#define CONTROL_PERIOD_US  100000  /* 100 ms */
#define STALL_TIMEOUT_S    2.0

/* ---- PI controller gains ---- */
#define KP 1.0
#define KI 0.01

/* ---- Globals ---- */
static volatile int32_t encoder_a_ticks = 0;
static volatile int32_t encoder_b_ticks = 0;
static volatile bool running = true;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
static void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
static void set_motor_pwm(int motor, int duty);
static double calculate_rpm(int32_t *ticks, double *last_time, double *integral);
static int pi_control(double target, double measured, double *integral);

/* ------------------------------------------------------------------ */
/* Signal handler                                                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = false;
}

/* ------------------------------------------------------------------ */
/* Encoder ISRs (rising-edge count)                                     */
/* ------------------------------------------------------------------ */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *user)
{
    (void)gpio; (void)tick; (void)user;
    if (level == 1) {
        __sync_fetch_and_add(&encoder_a_ticks, 1);
    }
}

static void encoder_b_isr(int gpio, int level, uint32_t tick, void *user)
{
    (void)gpio; (void)tick; (void)user;
    if (level == 1) {
        __sync_fetch_and_add(&encoder_b_ticks, 1);
    }
}

/* ------------------------------------------------------------------ */
/* Motor PWM control                                                    */
/* ------------------------------------------------------------------ */
static void set_motor_pwm(int motor, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    if (motor == 1) {
        gpioPWM(MOTOR_A_PWM_PIN, duty);
    } else if (motor == 2) {
        gpioPWM(MOTOR_B_PWM_PIN, duty);
    }
}

/* ------------------------------------------------------------------ */
/* RPM calculation                                                      */
/* ------------------------------------------------------------------ */
static double calculate_rpm(int32_t *ticks, double *last_time, double *integral)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    double now = (double)ts.tv_sec + (double)ts.tv_nsec / 1.0e9;

    int32_t delta_ticks = __sync_fetch_and_sub(ticks, 0);
    double dt = now - *last_time;

    if (dt <= 0.0) {
        *last_time = now;
        return 0.0;
    }

    double rpm = ((double)delta_ticks / dt) * 60.0 / (double)ENCODER_TICKS_PER_REV;
    *last_time = now;

    /* Anti-windup clamping */
    if (rpm > 0.0) {
        *integral += rpm * dt;
    } else {
        *integral = 0.0;
    }

    return rpm;
}

/* ------------------------------------------------------------------ */
/* PI controller                                                        */
/* ------------------------------------------------------------------ */
static int pi_control(double target, double measured, double *integral)
{
    double error = target - measured;
    double output = KP * error + KI * (*integral);
    *integral = output;

    if (output < 0.0) output = 0.0;
    if (output > (double)PWM_RANGE) output = (double)PWM_RANGE;

    return (int)output;
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure motor control pins ---- */
    if (gpioSetMode(MOTOR_A_PWM_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_DIR_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_PWM_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_DIR_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set motor pin modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency and range */
    if (gpioSetPWMfrequency(MOTOR_A_PWM_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_A_PWM_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(MOTOR_B_PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Drive direction: forward (IN1/IN3 high, IN2/IN4 low) */
    gpioWrite(MOTOR_A_DIR_PIN, 1);
    gpioWrite(MOTOR_B_DIR_PIN, 1);

    /* ---- Configure encoder pins ---- */
    if (gpioSetMode(ENCODER_A_A_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_A_B_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_A_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set encoder pin modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable pull-ups on encoder inputs */
    gpioSetPullUpDown(ENCODER_A_A_PIN, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_A_B_PIN, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_A_PIN, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_B_PIN, PI_PUD_UP);

    /* ---- Register encoder ISRs (rising edge) ---- */
    if (gpioSetISRFuncEx(ENCODER_A_A_PIN, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register encoder A ISR.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ENCODER_B_A_PIN, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register encoder B ISR.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- Control loop state ---- */
    double last_a_time = 0.0;
    double last_b_time = 0.0;
    double integral_a = 0.0;
    double integral_b = 0.0;
    struct timespec ts_start;
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    last_a_time = (double)ts_start.tv_sec + (double)ts_start.tv_nsec / 1.0e9;
    last_b_time = last_a_time;

    printf("Motor control started. Target RPM: %.1f\n", TARGET_RPM);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main control loop ---- */
    while (running) {
        double rpm_a = calculate_rpm(&encoder_a_ticks, &last_a_time, &integral_a);
        double rpm_b = calculate_rpm(&encoder_b_ticks, &last_b_time, &integral_b);

        int duty_a = pi_control(TARGET_RPM, rpm_a, &integral_a);
        int duty_b = pi_control(TARGET_RPM, rpm_b, &integral_b);

        set_motor_pwm(1, duty_a);
        set_motor_pwm(2, duty_b);

        printf("Motor A: RPM = %.2f, PWM = %d\n", rpm_a, duty_a);
        printf("Motor B: RPM = %.2f, PWM = %d\n", rpm_b, duty_b);

        /* Stall detection */
        if (duty_a == 0 && duty_b == 0) {
            struct timespec ts_now;
            clock_gettime(CLOCK_MONOTONIC, &ts_now);
            double elapsed = (double)(ts_now.tv_sec - ts_start.tv_sec) +
                             (double)(ts_now.tv_nsec - ts_start.tv_nsec) / 1.0e9;
            if (elapsed > STALL_TIMEOUT_S) {
                fprintf(stderr, "Warning: Stall detected (no motion for %.1f s)\n", elapsed);
                ts_start = ts_now;
            }
        }

        gpioDelay(CONTROL_PERIOD_US);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpioWrite(MOTOR_A_DIR_PIN, 0);
    gpioWrite(MOTOR_B_DIR_PIN, 0);
    set_motor_pwm(1, 0);
    set_motor_pwm(2, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

