/*
 * Chicken Coop Light Controller
 * Board:  Raspberry Pi 4 Model B
 * Sensor: BH1750FVI on I2C bus 1 (address 0x23)
 * Relay:  Active-high relay on GPIO 17 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o chicken_coop chicken_coop.c -lpigpio -lrt
 * Run:    sudo ./chicken_coop
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define BH1750_ADDR          0x23          /* ADDR pin tied to GND            */
#define BH1750_PWR_ON        0x01
#define BH1750_CONT_HRES     0x10          /* Continuous High-Resolution mode */
#define BH1750_CONV_MS       180           /* Conversion time (datasheet)     */

#define GPIO_RELAY           17            /* BCM pin for relay control       */
#define LUX_THRESHOLD_DARK   50            /* Lux below  -> relay ON          */
#define LUX_THRESHOLD_LIGHT  200           /* Lux above  -> relay OFF         */
#define POLL_INTERVAL_S      5             /* Seconds between readings        */
#define LOG_FILE             "chicken_coop_log.txt"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Forward declarations ------------------------- */
static void signal_handler(int sig);
static void log_message(const char *msg);
static int  bh1750_init(void);
static int  bh1750_read_lux(int handle, uint16_t *lux_out);
static void relay_set(int state);
static void cleanup(void);

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Logging --------------------------------- */
static void log_message(const char *msg)
{
    if (!g_log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_file, "%s: %s\n", ts, msg);
    fflush(g_log_file);
}

/* --------------------------- BH1750 helpers ------------------------------- */
static int bh1750_init(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, BH1750_ADDR, g_i2c_handle);
        return -1;
    }

    /* Power on */
    if (i2cWriteByte(g_i2c_handle, BH1750_PWR_ON) < 0) {
        fprintf(stderr, "Error sending power-on command to BH1750\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Set continuous high-resolution mode */
    if (i2cWriteByte(g_i2c_handle, BH1750_CONT_HRES) < 0) {
        fprintf(stderr, "Error setting BH1750 mode\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Wait for first conversion to complete */
    gpioDelay(BH1750_CONV_MS * 1000);   /* microseconds */
    return 0;
}

/*
 * Read one 16-bit big-endian sample from the BH1750.
 * Returns 0 on success and stores the value in *lux_out.
 * Returns -1 on I2C error.
 */
static int bh1750_read_lux(int handle, uint16_t *lux_out)
{
    char buf[2];
    int  n = i2cReadDevice(handle, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read failed (got %d bytes)\n", n);
        return -1;
    }
    *lux_out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------- Relay ----------------------------------- */
static void relay_set(int state)
{
    if (gpioWrite(GPIO_RELAY, state ? 1 : 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite(%d) failed\n", GPIO_RELAY);
    }
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure relay is off before exiting */
    gpioWrite(GPIO_RELAY, 0);
    gpioTerminate();
}

/* --------------------------------- Main ----------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay pin */
    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_RELAY);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_RELAY, 0);   /* Relay off at startup */

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize BH1750 */
    if (bh1750_init() != 0) {
        log_message("BH1750 initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Chicken Coop Light Controller started");

    int relay_state = 0;   /* 0 = off, 1 = on */

    while (g_running) {
        uint16_t lux = 0;
        char msg[128];

        if (bh1750_read_lux(g_i2c_handle, &lux) == 0) {
            snprintf(msg, sizeof(msg), "Lux = %u, Relay = %s",
                     lux, relay_state ? "ON" : "OFF");
            log_message(msg);

            /* Hysteresis control */
            if (lux < LUX_THRESHOLD_DARK && !relay_state) {
                relay_set(1);
                relay_state = 1;
                log_message("Relay activated (dusk)");
            } else if (lux > LUX_THRESHOLD_LIGHT && relay_state) {
                relay_set(0);
                relay_state = 0;
                log_message("Relay deactivated (dawn)");
            }
        } else {
            /* Sensor read failed — log and turn relay off for safety */
            log_message("Sensor read failed — relay turned off for safety");
            relay_set(0);
            relay_state = 0;
        }

        /* Wait before next poll (interruptible by signals) */
        for (int i = 0; i < POLL_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    log_message("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

