#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_MS 50
#define LOOP_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);
    printf("[%s] Relay is now %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

int main(void) {
    int relay_state = 0;
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetMode(TOUCH_SENSOR_PIN) failed: %d\n", ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(RELAY_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetMode(RELAY_PIN) failed: %d\n", ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioWrite(RELAY_PIN, 0);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioWrite(RELAY_PIN, 0) failed: %d\n", ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    printf("Touch-controlled relay started. Touch GPIO%d to toggle GPIO%d. Press Ctrl+C to exit.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    fflush(stdout);

    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Error: gpioRead(TOUCH_SENSOR_PIN) failed: %d\n", touch_state);
            break;
        }

        if (touch_state == 1) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);

            touch_state = gpioRead(TOUCH_SENSOR_PIN);
            if (touch_state < 0) {
                fprintf(stderr, "Error: gpioRead(TOUCH_SENSOR_PIN) failed: %d\n", touch_state);
                break;
