#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO    27

#define FLOW_THRESHOLD_HIGH  5.0f
#define FLOW_THRESHOLD_LOW   4.5f

#define DEBOUNCE_US 1000000  /* 1 second in microseconds */
#define SAMPLE_US   1000000  /* 1 second sampling window */

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

static void log_event(const char *msg)
{
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", ts, msg);
    fflush(log_file);
}

static void flow_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)userdata;
    static uint32_t last_tick = 0;
    uint32_t diff = tick - last_tick; /* handles 32-bit wrap */
    if (diff > DEBOUNCE_US) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
        last_tick = tick;
    }
}

static float calculate_flow_rate(int pulses)
{
    /* YF-S201: 1 pulse per 1.1 ms => 900 pulses per second => 600 L/min */
    return (float)pulses * 600.0f / 60.0f;
}

static void control_solenoid(float flow_rate)
{
    static int solenoid_state = 1; /* 1 = open (HIGH), 0 = closed (LOW) */
    if (flow_rate > FLOW_THRESHOLD_HIGH && solenoid_state == 1) {
        if (gpioWrite(SOLENOID_GPIO, 0) == 0) {
            solenoid_state = 0;
            log_event("Solenoid valve closed (flow exceeded threshold)");
        } else {
            log_event("ERROR: failed to close solenoid");
        }
    } else if (flow_rate < FLOW_THRESHOLD_LOW && solenoid_state == 0) {
        if (gpioWrite(SOLENOID_GPIO, 1) == 0) {
            solenoid_state = 1;
            log_event("Solenoid valve opened (flow below threshold)");
        } else {
            log_event("ERROR: failed to open solenoid");
        }
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void cleanup(void)
{
    gpioWrite(SOLENOID_GPIO, 1);
    if (log_file) {
        log_event("Shutting down, solenoid returned to safe open state");
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flow sensor GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to initialise solenoid to open state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, flow_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register flow sensor ISR\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("water_flow.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Water flow monitoring started");

    while (running) {
        gpioDelay(SAMPLE_US);

        pthread_mutex_lock(&pulse_mutex);
        int pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        float flow_rate = calculate_flow_rate(pulses);

        char msg[128];
        snprintf(msg, sizeof(msg), "Flow rate: %.2f LPM (pulses: %d)", flow_rate, pulses);
        log_event(msg);

        control_solenoid(flow_rate);
    }

    cleanup();
    return EXIT_SUCCESS;
}

