#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define HX711_DATA_PIN 23
#define HX711_SCK_PIN  24
#define SERVO_PIN      18

#define DEFAULT_CALIBRATION_FACTOR 1.0
#define CONFIG_FILE "config.ini"
#define LOG_FILE "dispensing_log.json"
#define PORT 12345
#define BUFFER_SIZE 1024
#define HX711_TIMEOUT_MAX 1000
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define SERVO_SETTLE_US 1000000
#define STABILIZE_DELAY_US 1000000

static volatile sig_atomic_t running = 1;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static int server_fd = -1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static void log_error(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "{\"timestamp\": \"%04d-%02d-%02dT%02d:%02d:%02d\", \"error\": \"%s\"}\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int read_config(void) {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) return -1;
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "calibration_factor=", 19) == 0) {
            calibration_factor = atof(line + 19);
            if (calibration_factor <= 0.0) calibration_factor = DEFAULT_CALIBRATION_FACTOR;
            break;
        }
    }
    fclose(fp);
    return 0;
}

static int hx711_read_raw(void) {
    int data = 0;
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioWrite(HX711_SCK_PIN, 0);

    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN)) {
        if (++timeout > HX711_TIMEOUT_MAX) {
            log_error("HX711 timeout: sensor not ready or absent");
            return -1;
        }
        gpioDelay(1);
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(HX711_DATA_PIN)) data |= 1;
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1);
    }

    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);

    if (data & 0x800000) data |= ~0xFFFFFF;
    return data;
}

static double hx711_read_grams(void) {
    int raw = hx711_read_raw();
    if (raw == -1) return -1.0;
    return (double)raw / calibration_factor;
}

static int set_servo_pulse(int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        log_error("Invalid servo pulse width");
        return -1;
    }
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        log_error("gpioServo failed");
        return -1;
    }
    return 0;
}

static int dispense_ingredient(double target_weight) {
    if (target_weight <= 0.0) {
        log_error("Invalid target weight");
        return -1;
    }
    double actual_weight = 0.0;
    double known_weight = 100.0;
    int raw_reading = hx711_read_raw();
    if (raw_reading == -1) return -1;
    double tare = (double)raw_reading;

    int pulse_width = SERVO_MIN_PULSE_WIDTH;
    if (set_servo_pulse(pulse_width) < 0) return -1;
    gpioDelay(SERVO_SETTLE_US);

    while (actual_weight < target_weight) {
        pulse_width += 10;
        if (pulse_width > SERVO_MAX_PULSE_WIDTH) {
            log_error("Dispensing limit reached");
            set_servo_pulse(SERVO_MIN_PULSE_WIDTH);
            return -1;
        }
        if (set_servo_pulse(pulse_width) < 0) return -1;
        gpioDelay(SERVO_SETTLE_US);

        gpioDelay(STABILIZE_DELAY_US);
        raw_reading = hx711_read_raw();
        if (raw_reading == -1) {
            set_servo_pulse(SERVO_MIN_PULSE_WIDTH);
            return -1;
        }
        actual_weight = ((double)raw_reading - tare) / calibration_factor;
    }

    set_servo_pulse(SERVO_MIN_PULSE_WIDTH);
    return 0;
}

static void log_dispensing_event(double target_weight, double actual_weight, const char *error_message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        log_error("Failed to open log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "{\"timestamp\": \"%04d-%02d-%02dT%02d:%02d:%02d\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error\": \"%s\"}\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, target_weight, actual_weight, error_message ? error_message : "None");
    fclose(fp);
}

static void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0);
    if (bytes_received <= 0) {
        if (bytes_received < 0) log_error("recv failed");
        close(client_socket);
        return;
    }
    buffer[bytes_received] = '\0';
    double target_weight = atof(buffer);
    if (target_weight <= 0.0) {
        const char *msg = "Invalid target weight";
        send(client_socket, msg, strlen(msg), 0);
        log_dispensing_event(0.0, 0.0, msg);
        close(client_socket);
        return;
    }
    if (dispense_ingredient(target_weight) == 0) {
        double actual_weight = hx711_read_grams();
        char response[BUFFER_SIZE];
        snprintf(response, sizeof(response), "%.2f", actual_weight);
        send(client_socket, response, strlen(response), 0);
        log_dispensing_event(target_weight, actual_weight, NULL);
    } else {
        send(client_socket, "Dispensing failed", 16, 0);
        log_dispensing_event(target_weight, 0.0, "Dispensing failed");
    }
    close(client_socket);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (read_config() < 0) {
        fprintf(stderr, "Warning: using default calibration factor\n");
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        log_error("Failed to set servo pin mode");
        gpioTerminate();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        gpioTerminate();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(server_fd);
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind");
        close(server_fd);
        gpioTerminate();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d\n", PORT);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_socket = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_socket < 0) {
            if (errno == EINTR) continue;
            perror("accept");
            continue;
        }
        handle_client(client_socket);
    }

    if (server_fd >= 0) close(server_fd);
    gpioTerminate();
    printf("Server shut down cleanly\n");
    return 0;
}

