#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEFAULT_DEBOUNCE_MS 50

static volatile sig_atomic_t running = 1;
static int relay_state = 0;
static int debounce_ms = DEFAULT_DEBOUNCE_MS;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set touch sensor pin %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set relay pin %d as output\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialise relay pin %d to LOW\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    relay_state = 0;
    return 0;
}

static void cleanup_gpio(void) {
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Warning: Failed to turn off relay during cleanup\n");
    }
    gpioTerminate();
}

static void toggle_relay(void) {
    relay_state = !relay_state;
    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "Error: Failed to write to relay pin %d\n", RELAY_PIN);
        return;
    }
    log_relay_state(relay_state);
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_ms = atoi(optarg);
                if (debounce_ms <= 0) {
                    fprintf(stderr, "Error: debounce value must be positive\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-d debounce_ms]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    int last_touch_state = gpioRead(TOUCH_SENSOR_PIN);
    if (last_touch_state < 0) {
        fprintf(stderr, "Error: Failed to read touch sensor pin %d\n", TOUCH_SENSOR_PIN);
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    while (running) {
        int current_touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (current_touch_state < 0) {
            fprintf(stderr, "Error: Failed to read touch sensor pin %d\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (current_touch_state == 1 && last_touch_state == 0) {
            gpioDelay(debounce_ms * 1000);
            int confirmed_state = gpioRead(TOUCH_SENSOR_PIN);
            if (confirmed_state < 0) {
                fprintf(stderr, "Error: Failed to read touch sensor pin %d during debounce\n", TOUCH_SENSOR_PIN);
                break;
            }
            if (confirmed_state == 1) {
                toggle_relay();
            }
        }

        last_touch_state = current_touch_state;
        gpioDelay(10000);
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

