/*
 * servo_adjust.c — Adjust a hobby servo angle on a Raspberry Pi 4/5.
 *
 * Wiring:
 *   Servo signal  -> GPIO18 (BCM 18, physical pin 12)
 *   Servo V+      -> 5 V (physical pin 2 or 4)
 *   Servo GND     -> GND (physical pin 6 or 9)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o servo_adjust servo_adjust.c -lpigpio -lrt
 * Run:
 *   sudo ./servo_adjust
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18          /* BCM 18, physical pin 12 */
#define SERVO_FREQ     50          /* 50 Hz => 20 ms period */
#define SERVO_MIN_US   500         /* 0 degrees   */
#define SERVO_MAX_US   2500        /* 180 degrees */
#define SERVO_MID_US   1500        /* 90 degrees  */
#define ANGLE_STEP     10
#define ANGLE_MIN      0
#define ANGLE_MAX      180

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Terminal I/O                                                        */
/* ------------------------------------------------------------------ */
static struct termios g_orig_termios;

static int set_terminal_raw(void)
{
    struct termios raw;
    if (tcgetattr(STDIN_FILENO, &g_orig_termios) != 0) {
        perror("tcgetattr");
        return -1;
    }

    raw = g_orig_termios;
    raw.c_lflag &= ~(ICANON | ECHO);   /* non-canonical, no echo */
    raw.c_cc[VMIN]  = 1;               /* block until >= 1 byte  */
    raw.c_cc[VTIME] = 0;               /* no inter-byte timeout   */

    if (tcsetattr(STDIN_FILENO, TCSANOW, &raw) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static void restore_terminal(void)
{
    tcsetattr(STDIN_FILENO, TCSANOW, &g_orig_termios);
}

/* ------------------------------------------------------------------ */
/* Servo helpers                                                       */
/* ------------------------------------------------------------------ */
static int angle_to_pulse_us(int angle)
{
    if (angle < ANGLE_MIN) angle = ANGLE_MIN;
    if (angle > ANGLE_MAX) angle = ANGLE_MAX;

    int pw = SERVO_MIN_US +
             (int)((long)(angle - ANGLE_MIN) *
                   (SERVO_MAX_US - SERVO_MIN_US) /
                   (ANGLE_MAX - ANGLE_MIN));

    if (pw < SERVO_MIN_US) pw = SERVO_MIN_US;
    if (pw > SERVO_MAX_US) pw = SERVO_MAX_US;
    return pw;
}

static int set_servo_angle(int angle)
{
    int pw = angle_to_pulse_us(angle);
    int rc = gpioServo(SERVO_PIN, pw);
    if (rc < 0) {
        fprintf(stderr, "gpioServo(pin=%d, pw=%d) failed: %s\n",
                SERVO_PIN, pw, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop PWM pulses on the servo pin. */
    if (gpioServo(SERVO_PIN, 0) < 0) {
        fprintf(stderr, "Warning: gpioServo(stop) failed\n");
    }

    /* Release pigpio resources. */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int angle = 90;   /* start at 90 degrees */

    /* --- Initialise pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure servo pin ---------------------------------------- */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers -------------------------------------------- */
    if (install_signal_handlers() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Terminal raw mode ------------------------------------------ */
    if (set_terminal_raw() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Set up at-exit cleanup ------------------------------------- */
    if (atexit(cleanup) != 0) {
        fprintf(stderr, "atexit registration failed\n");
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main loop --------------------------------------------------- */
    printf("Servo control on GPIO%d (50 Hz, %d-%d us).\n",
           SERVO_PIN, SERVO_MIN_US, SERVO_MAX_US);
    printf("Angle: %d deg  (0-180).  + / - : step %d deg, q / Ctrl-C : quit\n",
           angle, ANGLE_STEP);
    fflush(stdout);

    if (set_servo_angle(angle) != 0) {
        restore_terminal();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int c = getchar();
        if (c == EOF) {
            break;  /* stdin closed */
        }

        switch (c) {
        case '+':
            angle += ANGLE_STEP;
            if (angle > ANGLE_MAX) angle = ANGLE_MAX;
            break;
        case '-':
            angle -= ANGLE_STEP;
            if (angle < ANGLE_MIN) angle = ANGLE_MIN;
            break;
        case 'q':
        case 'Q':
            g_running = 0;
            break;
        default:
            continue;  /* ignore other keys */
        }

        if (set_servo_angle(angle) != 0) {
            restore_terminal();
            return EXIT_FAILURE;
        }

        printf("\rAngle: %3d deg  (%d us)  ", angle, angle_to_pulse_us(angle));
        fflush(stdout);
    }

    /* --- Graceful exit ---------------------------------------------- */
    printf("\nShutting down...\n");
    restore_terminal();
    return EXIT_SUCCESS;
}

