/*
 * RPM monitor for a conveyor-belt motor using an A3144 Hall-effect sensor.
 *
 * Hardware:
 *   - Raspberry Pi 3 Model B+
 *   - A3144 Hall-effect sensor on GPIO 17 (BCM 17, physical pin 11)
 *   - Two-pole magnet on the motor shaft (one pulse per revolution)
 *   - Internal pull-up enabled (sensor output is active-low)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o motor_rpm motor_rpm.c -lgpiod
 *
 * Run:
 *   sudo ./motor_rpm
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_LINE_OFFSET 17          /* BCM 17 */
#define DEBOUNCE_MS      2           /* debounce window */
#define SAMPLE_INTERVAL  5           /* seconds between RPM calculations */
#define LOG_FILE         "motor_rpm.log"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static long long now_ms(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }
    return (long long)ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL;
}

static void get_iso8601_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        snprintf(buf, len, "1970-01-01T00:00:00");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handlers ---- */
    if (install_signal_handlers() == -1)
        goto cleanup;

    /* ---- Open log file ---- */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    /* ---- Get GPIO line ---- */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* ---- Request rising-edge events with internal pull-up ---- */
    if (gpiod_line_request_rising_edge_events_flags(line, "motor_rpm",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_rising_edge_events_flags");
        goto cleanup;
    }

    printf("Monitoring RPM on GPIO %d (BCM). Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    long long last_pulse_ms = 0;
    unsigned long pulse_count = 0;
    time_t last_sample = 0;

    /* ---- Main event loop ---- */
    while (g_running) {
        struct timespec ts = { 0, 100 * 1000 * 1000 }; /* 100 ms */
        int ev = gpiod_line_event_wait(line, &ts);

        if (ev < 0) {
            if (errno == EINTR)
                continue;
            perror("gpiod_line_event_wait");
            goto cleanup;
        }

        if (ev == 0)
            continue;                       /* timeout, no event */

        /* Drain all pending events */
        while (gpiod_line_event_wait(line, &ts) > 0)
            ;

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            perror("gpiod_line_event_read");
            goto cleanup;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE)
            continue;

        long long t = now_ms();
        if (t < 0)
            goto cleanup;

        if (last_pulse_ms != 0 && (t - last_pulse_ms) < DEBOUNCE_MS)
            continue;                       /* within debounce window */

        last_pulse_ms = t;
        pulse_count++;

        /* ---- Periodic RPM calculation ---- */
        time_t now = time(NULL);
        if (now == (time_t)-1) {
            perror("time");
            goto cleanup;
        }

        if (last_sample == 0)
            last_sample = now;

        if (now - last_sample >= SAMPLE_INTERVAL) {
            double rpm = 0.0;
            if (pulse_count > 0) {
                double elapsed = difftime(now, last_sample);
                rpm = (double)pulse_count / elapsed * 60.0;
            }

            char ts_buf[32];
            get_iso8601_timestamp(ts_buf, sizeof(ts_buf));

            if (fprintf(log_fp, "%s,%.2f\n", ts_buf, rpm) < 0) {
                perror("fprintf(log)");
                goto cleanup;
            }
            if (fflush(log_fp) == EOF) {
                perror("fflush(log)");
                goto cleanup;
            }

            printf("%s  RPM: %.2f\n", ts_buf, rpm);

            pulse_count = 0;
            last_sample = now;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);
    if (log_fp)
        fclose(log_fp);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");
    return ret;
}

