#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define POLL_DELAY_US 50000
#define FORCE_OFF_TIMEOUT_S 10

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set touch sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set relay pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay to OFF\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int last_touch = 0;
    time_t touch_start_time = 0;
    int timeout_active = 0;

    while (program_running) {
        int touch = gpioRead(TOUCH_SENSOR_PIN);
        if (touch < 0) {
            fprintf(stderr, "Error: failed to read touch sensor pin\n");
            break;
        }

        if (touch == 1 && last_touch == 0) {
            if (!timeout_active) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                    fprintf(stderr, "Error: failed to write relay pin\n");
                    break;
                }
                printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
            }
        }

        if (touch == 1 && !timeout_active) {
            if (touch_start_time == 0) {
                touch_start_time = time(NULL);
            } else if (time(NULL) - touch_start_time >= FORCE_OFF_TIMEOUT_S) {
                if (gpioWrite(RELAY_PIN, 0) != 0) {
                    fprintf(stderr, "Error: failed to force relay OFF\n");
                    break;
                }
                relay_state = 0;
                timeout_active = 1;
                printf("Force OFF: relay disabled\n");
            }
        } else if (touch == 0) {
            touch_start_time = 0;
            timeout_active = 0;
        }

        last_touch = touch;
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

