#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_PWM_PIN      18
#define VALVE_ENABLE_PIN   23
#define FLOW_SENSOR_PIN    24

#define PWM_FREQUENCY      1000
#define PWM_RANGE          255
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */
#define LOG_FILE_NAME      "flow_log.csv"

static volatile sig_atomic_t g_running = 1;
static volatile unsigned int g_pulse_count = 0;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; async-signal-safe                    */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* ISR — called by pigpio on every rising edge of the flow sensor      */
/* ------------------------------------------------------------------ */
static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;
    g_pulse_count++;
}

/* ------------------------------------------------------------------ */
/* Compute elapsed milliseconds since program start                    */
/* ------------------------------------------------------------------ */
static unsigned long elapsed_ms(void)
{
    static struct timespec start = {0, 0};
    struct timespec now;

    if (start.tv_sec == 0 && start.tv_nsec == 0) {
        clock_gettime(CLOCK_MONOTONIC, &start);
        return 0;
    }
    clock_gettime(CLOCK_MONOTONIC, &now);
    return (unsigned long)(now.tv_sec - start.tv_sec) * 1000UL
         + (unsigned long)(now.tv_nsec / 1000000L);
}

/* ------------------------------------------------------------------ */
/* Proportional controller: target (L/min) -> PWM duty cycle (0-255)   */
/* ------------------------------------------------------------------ */
static int compute_pwm_duty(float flow_rate, float target_flow)
{
    float error = target_flow - flow_rate;
    float duty = 1.0f + (error * 1.0f);   /* Kp = 1.0 */
    if (duty < 0.0f) duty = 0.0f;
    if (duty > (float)PWM_RANGE) duty = (float)PWM_RANGE;
    return (int)duty;
}

/* ------------------------------------------------------------------ */
/* Set PWM duty cycle on the valve PWM line                            */
/* ------------------------------------------------------------------ */
static void set_valve_position(int duty)
{
    if (gpioPWM(VALVE_PWM_PIN, duty) != 0) {
        fprintf(stderr, "Warning: gpioPWM failed for duty %d\n", duty);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup — safe to call from any exit path                           */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    set_valve_position(0);
    gpioWrite(VALVE_ENABLE_PIN, 0);
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    float target_flow = 0.0f;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t <target_flow_L_min>\n", argv[0]);
        return EXIT_FAILURE;
    }

    if (strcmp(argv[1], "-t") != 0) {
        fprintf(stderr, "Error: missing -t option\n");
        return EXIT_FAILURE;
    }

    if (argc < 3) {
        fprintf(stderr, "Error: target flow rate value required\n");
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    target_flow = strtof(argv[2], &endptr);
    if (endptr == argv[2] || *endptr != '\0') {
        fprintf(stderr, "Error: invalid target flow rate '%s'\n", argv[2]);
        return EXIT_FAILURE;
    }

    if (target_flow < 0.0f) {
        fprintf(stderr, "Error: target flow rate must be non-negative\n");
        return EXIT_FAILURE;
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO mode setup ---- */
    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", VALVE_PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", VALVE_ENABLE_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", FLOW_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- PWM configuration ---- */
    if (gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", VALVE_PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", VALVE_PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Enable line high ---- */
    if (gpioWrite(VALVE_ENABLE_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d\n", VALVE_ENABLE_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- ISR registration ---- */
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO %d\n", FLOW_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s'\n", LOG_FILE_NAME);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler\n");
    }

    printf("Flow control started. Target: %.2f L/min. Logging to %s\n",
           target_flow, LOG_FILE_NAME);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main control loop ---- */
    while (g_running) {
        unsigned int pulses = g_pulse_count;
        g_pulse_count = 0;

        /* Flow rate = pulses / (sample interval in seconds) * 60 s/min */
        float flow_rate = (float)pulses * 60.0f / (float)(SAMPLE_INTERVAL_US / 1000);

        int duty = compute_pwm_duty(flow_rate, target_flow);
        set_valve_position(duty);

        unsigned long ts_ms = elapsed_ms();

        if (fprintf(g_log_file, "%lu,%.2f,%d\n", ts_ms, flow_rate, duty) < 0) {
            fprintf(stderr, "Warning: failed to write to log file\n");
        }
        fflush(g_log_file);

        printf("ts=%6lu ms  flow=%.2f L/min  valve=%3d\n", ts_ms, flow_rate, duty);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

