#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19

#define PWM_FREQUENCY 100
#define PWM_RANGE 1000
#define SAMPLE_TIME_MS 100
#define TARGET_SPEED_RPM 60.0

static volatile int encoder1_count = 0;
static volatile int encoder2_count = 0;
static pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void motor1_forward(int speed) {
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    gpioWrite(MOTOR1_IN1, 1);
    gpioWrite(MOTOR1_IN2, 0);
    gpioPWM(MOTOR1_ENA, speed);
}

static void motor1_backward(int speed) {
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 1);
    gpioPWM(MOTOR1_ENA, speed);
}

static void motor1_stop(void) {
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioPWM(MOTOR1_ENA, 0);
}

static void motor2_forward(int speed) {
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    gpioWrite(MOTOR2_IN3, 1);
    gpioWrite(MOTOR2_IN4, 0);
    gpioPWM(MOTOR2_ENB, speed);
}

static void motor2_backward(int speed) {
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 1);
    gpioPWM(MOTOR2_ENB, speed);
}

static void motor2_stop(void) {
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);
    gpioPWM(MOTOR2_ENB, 0);
}

static void encoder1_callback(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    int b = gpioRead(ENCODER1_B);
    if (b < 0) return;
    pthread_mutex_lock(&encoder1_mutex);
    encoder1_count += (b == 0) ? 1 : -1;
    pthread_mutex_unlock(&encoder1_mutex);
}

static void encoder2_callback(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    int b = gpioRead(ENCODER2_B);
    if (b < 0) return;
    pthread_mutex_lock(&encoder2_mutex);
    encoder2_count += (b == 0) ? 1 : -1;
    pthread_mutex_unlock(&encoder2_mutex);
}

static double calculate_rpm(int *count, pthread_mutex_t *mutex) {
    int current_count;
    pthread_mutex_lock(mutex);
    current_count = *count;
    *count = 0;
    pthread_mutex_unlock(mutex);
    return (double)current_count * 60.0 / (PWM_FREQUENCY * SAMPLE_TIME_MS);
}

static double pid_calculate(double setpoint, double actual, double *integral, double *prev_error, double kp, double ki, double kd) {
    double error = setpoint - actual;
    *integral += error;
    double derivative = error - *prev_error;
    double output = kp * error + ki * (*integral) + kd * derivative;
    *prev_error = error;
    return output;
}

static void log_data(double m1_rpm, double m2_rpm, double p1, double i1, double d1, double o1, double p2, double i2, double d2, double o2) {
    if (log_file == NULL) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            m1_rpm, m2_rpm, p1, i1, d1, o1, p2, i2, d2, o2);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(MOTOR1_ENA, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_ENB, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set motor GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(MOTOR1_ENA, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR2_ENB, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ENCODER1_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER1_B, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER2_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER2_B, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set encoder GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(ENCODER1_A, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(ENCODER1_B, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(ENCODER2_A, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(ENCODER2_B, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set encoder pull-ups\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(ENCODER1_A, encoder1_callback, NULL) < 0 ||
        gpioSetAlertFuncEx(ENCODER2_A, encoder2_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set encoder alert functions\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("motor_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Motor1_RPM,Motor2_RPM,Motor1_P,Motor1_I,Motor1_D,Motor1_Output,Motor2_P,Motor2_I,Motor2_D,Motor2_Output\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    double kp = 0.1, ki = 0.01, kd = 0.001;
    double integral1 = 0, prev_error1 = 0, integral2 = 0, prev_error2 = 0;

    while (running) {
        double m1_rpm = calculate_rpm(&encoder1_count, &encoder1_mutex);
        double m2_rpm = calculate_rpm(&encoder2_count, &encoder2_mutex);

        double pid1 = pid_calculate(TARGET_SPEED_RPM, m1_rpm, &integral1, &prev_error1, kp, ki, kd);
        double pid2 = pid_calculate(TARGET_SPEED_RPM, m2_rpm, &integral2, &prev_error2, kp, ki, kd);

        int speed1 = (int)pid1;
        int speed2 = (int)pid2;

        if (speed1 > PWM_RANGE) speed1 = PWM_RANGE;
        if (speed1 < -PWM_RANGE) speed1 = -PWM_RANGE;
        if (speed2 > PWM_RANGE) speed2 = PWM_RANGE;
        if (speed2 < -PWM_RANGE) speed2 = -PWM_RANGE;

        if (speed1 > 0) motor1_forward(speed1);
        else if (speed1 < 0) motor1_backward(-speed1);
        else motor1_stop();

        if (speed2 > 0) motor2_forward(speed2);
        else if (speed2 < 0) motor2_backward(-speed2);
        else motor2_stop();

        log_data(m1_rpm, m2_rpm, kp, ki, kd, pid1, kp, ki, kd, pid2);

        gpioDelay(SAMPLE_TIME_MS * 1000);
    }

    motor1_stop();
    motor2_stop();
    gpioTerminate();
    if (log_file) fclose(log_file);
    return 0;
}

