/*
 * MPR121 Capacitive Touch Sensor -> Relay Controller
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: MPR121 at 0x5A (SA0 tied to GND)
 * Relay:  GPIO17 (BCM) active-HIGH
 * Log:    relay_log.txt
 *
 * Build:  gcc -O2 -Wall -Wextra -o mpr121_relay mpr121_relay.c -lpigpio -lrt
 * Run:    sudo ./mpr121_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1
#define MPR121_ADDR        0x5A          /* SA0 tied to GND */
#define RELAY_GPIO         17            /* BCM numbering */
#define LOG_FILE           "relay_log.txt"
#define POLL_DELAY_US      50000         /* 50 ms */

/* MPR121 register addresses (from datasheet) */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ELECONFIG      0x5E
#define MPR121_SOFTRESET      0x80
#define MPR121_MHDR           0x2B
#define MPR121_NHDR           0x2C
#define MPR121_NCLR           0x2D
#define MPR121_FDLR           0x2E
#define MPR121_MHDF           0x2F
#define MPR121_NHDF           0x30
#define MPR121_NCLF           0x31
#define MPR121_FDLF           0x32
#define MPR121_NHDT           0x33
#define MPR121_NCLT           0x34
#define MPR121_FDLT           0x35
#define MPR121_TOUCHTH_0      0x41
#define MPR121_RELEASETH_0    0x42

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static int  mpr121_write_reg(int handle, uint8_t reg, uint8_t value);
static int  mpr121_read_reg(int handle, uint8_t reg, uint8_t *value);
static int  mpr121_init(int handle);
static int  mpr121_read_touch_status(int handle, uint16_t *status);
static void log_relay_state(int state);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- I2C helpers ------------------------------- */
static int mpr121_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] I2C write to reg 0x%02X failed (pigpio rc=%d)\n",
                reg, rc);
        return -1;
    }
    return 0;
}

static int mpr121_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] I2C read from reg 0x%02X failed (pigpio rc=%d)\n",
                reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ----------------------------- MPR121 init ------------------------------- */
static int mpr121_init(int handle)
{
    uint8_t val;

    /* 1. Soft reset */
    if (mpr121_write_reg(handle, MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    gpioDelay(2000);  /* 2 ms settle after reset */

    /* 2. Baseline filtering (rising) */
    if (mpr121_write_reg(handle, MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDLR, 0x00) < 0) return -1;

    /* 3. Baseline filtering (falling) */
    if (mpr121_write_reg(handle, MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHDF, 0x05) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCLF, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDLF, 0x00) < 0) return -1;

    /* 4. Touch / release filtering */
    if (mpr121_write_reg(handle, MPR121_NHDT, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCLT, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDLT, 0x00) < 0) return -1;

    /* 5. Touch / release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(handle, MPR121_TOUCHTH_0 + 2 * i, 0x0F) < 0)
            return -1;
        if (mpr121_write_reg(handle, MPR121_RELEASETH_0 + 2 * i, 0x0A) < 0)
            return -1;
    }

    /* 6. Enable 12 electrodes, baseline tracking, run mode */
    if (mpr121_write_reg(handle, MPR121_ELECONFIG, 0x0C) < 0)
        return -1;

    /* Verify we can read back the config register */
    if (mpr121_read_reg(handle, MPR121_ELECONFIG, &val) < 0)
        return -1;
    if (val != 0x0C) {
        fprintf(stderr, "[ERROR] MPR121 config readback mismatch (got 0x%02X)\n",
                val);
        return -1;
    }

    return 0;
}

/* ----------------------------- Touch read -------------------------------- */
static int mpr121_read_touch_status(int handle, uint16_t *status)
{
    uint8_t lo, hi;

    if (mpr121_read_reg(handle, MPR121_TOUCHSTATUS_L, &lo) < 0)
        return -1;
    if (mpr121_read_reg(handle, MPR121_TOUCHSTATUS_H, &hi) < 0)
        return -1;

    *status = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_relay_state(int state)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Relay: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                state ? "ON" : "OFF");
    } else {
        fprintf(fp, "[timestamp-error] - Relay: %s\n", state ? "ON" : "OFF");
    }

    fclose(fp);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
