static int mpr121_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] I2C write to reg 0x%02X failed (pigpio rc=%d)\n",
                reg, rc);
        return -1;
    }
    return 0;
}

static int mpr121_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] I2C read from reg 0x%02X failed (pigpio rc=%d)\n",
                reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

