    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(handle, MPR121_TOUCHTH_0 + 2 * i, 0x0F) < 0)
            return -1;
        if (mpr121_write_reg(handle, MPR121_RELEASETH_0 + 2 * i, 0x0A) < 0)
            return -1;
    }

    /* 6. Enable 12 electrodes, baseline tracking, run mode */
    if (mpr121_write_reg(handle, MPR121_ELECONFIG, 0x0C) < 0)
        return -1;

    /* Verify we can read back the config register */
    if (mpr121_read_reg(handle, MPR121_ELECONFIG, &val) < 0)
        return -1;
    if (val != 0x0C) {
        fprintf(stderr, "[ERROR] MPR121 config readback mismatch (got 0x%02X)\n",
                val);
        return -1;
    }

    return 0;
}

