    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 relay controller running. Press Ctrl-C to exit.\n");

    int last_relay_state = -1;  /* force initial log */

    while (g_running) {
        uint16_t touch_status = 0;

        if (mpr121_read_touch_status(g_i2c_handle, &touch_status) < 0) {
            fprintf(stderr, "[WARN] Touch status read failed - continuing\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        int any_touched = (touch_status & 0x0FFF) ? 1 : 0;

        if (any_touched != last_relay_state) {
