/*
 * Timed water distribution scheduler for two Adafruit Solenoid Valves (PID 997)
 * on a Raspberry Pi 4 Model B.
 *
 * Valve 1 relay -> GPIO 17 (BCM)
 * Valve 2 relay -> GPIO 18 (BCM)
 *
 * Each valve is opened via its relay (GPIO HIGH = relay ON = valve OPEN)
 * and closed when the relay is de-energised (GPIO LOW = relay OFF = valve CLOSED).
 *
 * Build:  gcc -O2 -Wall -Wextra -o valve_scheduler valve_scheduler.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

#define VALVE1_OPEN_MS  500
#define VALVE1_PAUSE_MS 5000
#define VALVE2_OPEN_MS  1000
#define VALVE2_PAUSE_MS 10000

#define LOG_FILE "valve_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;
static struct gpiod_chip    *g_chip    = NULL;
static struct gpiod_line    *g_line1   = NULL;
static struct gpiod_line    *g_line2   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *message)
{
    if (!g_log_fp)
        return;

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return;
    }

    struct tm tm_buf;
    struct tm *tm_info = localtime_r(&now, &tm_buf);
    if (!tm_info) {
        perror("localtime_r()");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s %s\n", ts, message) < 0)
        perror("fprintf(log)");

    if (fflush(g_log_fp) == EOF)
        perror("fflush(log)");
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    g_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!g_chip) {
        /* Fall back to the first chip found (older kernels / different Pi models) */
        g_chip = gpiod_chip_open_by_number(0);
    }
    if (!g_chip) {
        perror("gpiod_chip_open");
        return -1;
    }

    g_line1 = gpiod_chip_get_line(g_chip, VALVE1_GPIO);
    if (!g_line1) {
        perror("gpiod_chip_get_line(17)");
        return -1;
    }

    g_line2 = gpiod_chip_get_line(g_chip, VALVE2_GPIO);
    if (!g_line2) {
        perror("gpiod_chip_get_line(18)");
        return -1;
    }

    /* Request both lines as outputs, initialised to LOW (valves closed) */
    if (gpiod_line_request_output(g_line1, "valve_scheduler", 0) < 0) {
        perror("gpiod_line_request_output(17)");
        return -1;
    }

    if (gpiod_line_request_output(g_line2, "valve_scheduler", 0) < 0) {
        perror("gpiod_line_request_output(18)");
        return -1;
    }

    return 0;
}

static void gpio_cleanup(void)
{
    /* Ensure valves are closed before releasing lines */
    if (g_line1) {
        if (gpiod_line_set_value(g_line1, 0) < 0)
            perror("gpiod_line_set_value(17, 0)");
        gpiod_line_release(g_line1);
        g_line1 = NULL;
    }

    if (g_line2) {
        if (gpiod_line_set_value(g_line2, 0) < 0)
            perror("gpiod_line_set_value(18, 0)");
        gpiod_line_release(g_line2);
        g_line2 = NULL;
    }

    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Valve control                                                       */
/* ------------------------------------------------------------------ */
static void activate_valve(struct gpiod_line *line, int gpio, int duration_ms,
                           const char *name)
{
    char msg[128];

    if (gpiod_line_set_value(line, 1) < 0) {
        snprintf(msg, sizeof(msg), "ERROR: %s (GPIO %d) failed to open", name, gpio);
        perror(msg);
        log_event(msg);
        return;
    }

    snprintf(msg, sizeof(msg), "%s (GPIO %d) opened for %d ms", name, gpio, duration_ms);
    log_event(msg);

    /* Sleep in 100 ms chunks so we can exit promptly on signal */
    int remaining = duration_ms;
    while (remaining > 0 && g_running) {
        int chunk = (remaining > 100) ? 100 : remaining;
        usleep(chunk * 1000);
        remaining -= chunk;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        snprintf(msg, sizeof(msg), "ERROR: %s (GPIO %d) failed to close", name, gpio);
        perror(msg);
        log_event(msg);
        return;
    }

    snprintf(msg, sizeof(msg), "%s (GPIO %d) closed", name, gpio);
    log_event(msg);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialisation failed. Exiting.\n");
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    log_event("Program started");

    while (g_running) {
        activate_valve(g_line1, VALVE1_GPIO, VALVE1_OPEN_MS, "Valve 1");
        if (!g_running)
            break;

        /* Pause between valve activations */
        int remaining = VALVE1_PAUSE_MS;
        while (remaining > 0 && g_running) {
            int chunk = (remaining > 100) ? 100 : remaining;
            usleep(chunk * 1000);
            remaining -= chunk;
        }
        if (!g_running)
            break;

        activate_valve(g_line2, VALVE2_GPIO, VALVE2_OPEN_MS, "Valve 2");
        if (!g_running)
            break;

        remaining = VALVE2_PAUSE_MS;
        while (remaining > 0 && g_running) {
            int chunk = (remaining > 100) ? 100 : remaining;
            usleep(chunk * 1000);
            remaining -= chunk;
        }
    }

    log_event("Program exiting");
    gpio_cleanup();

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    return EXIT_SUCCESS;
}

