#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_PIN 17
#define RELAY_PIN 18
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_MS 2000
#define POLL_INTERVAL_US 50000
#define LOG_FILE "door_events.log"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event_type) {
    if (!log_file) return;
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) return;
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    long ms = ts.tv_nsec / 1000000L;
    fprintf(log_file, "%s.%03ld - %s\n", timestamp, ms, event_type);
    fflush(log_file);
}

static void unlock_door(void) {
    if (gpioWrite(RELAY_PIN, 1) != 0) {
        log_event("ERROR: Failed to activate relay");
        return;
    }
    log_event("Door unlocked");
    gpioDelay(UNLOCK_DURATION_MS * 1000);
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        log_event("ERROR: Failed to deactivate relay");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set PIR pull-down\n");
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize relay to off\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    log_event("System started");

    int last_pir_state = gpioRead(PIR_PIN);
    if (last_pir_state < 0) {
        fprintf(stderr, "Failed to read PIR pin\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    uint64_t last_unlock_time = 0;

    while (running) {
        int pir_state = gpioRead(PIR_PIN);
        if (pir_state < 0) {
            log_event("ERROR: Failed to read PIR pin");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (pir_state == 1 && last_pir_state == 0) {
            struct timespec now;
            clock_gettime(CLOCK_REALTIME, &now);
            uint64_t now_ms = (uint64_t)now.tv_sec * 1000ULL + (uint64_t)(now.tv_nsec / 1000000L);

            if (last_unlock_time == 0 || (now_ms - last_unlock_time) >= RATE_LIMIT_MS) {
                log_event("Motion detected");
                unlock_door();
                last_unlock_time = now_ms;
            } else {
                log_event("Rate limited: motion detected, unlock skipped");
            }
        }

        last_pir_state = pir_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("System shutting down");
    gpioWrite(RELAY_PIN, 0);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

