    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    log_event("System started");

    int last_pir_state = gpioRead(PIR_PIN);
    if (last_pir_state < 0) {
        fprintf(stderr, "Failed to read PIR pin\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    uint64_t last_unlock_time = 0;

    while (running) {
        int pir_state = gpioRead(PIR_PIN);
        if (pir_state < 0) {
            log_event("ERROR: Failed to read PIR pin");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (pir_state == 1 && last_pir_state == 0) {
            struct timespec now;
            clock_gettime(CLOCK_REALTIME, &now);
            uint64_t now_ms = (uint64_t)now.tv_sec * 1000ULL + (uint64_t)(now.tv_nsec / 1000000L);

            if (last_unlock_time == 0 || (now_ms - last_unlock_time) >= RATE_LIMIT_MS) {
                log_event("Motion detected");
                unlock_door();
                last_unlock_time = now_ms;
            } else {
                log_event("Rate limited: motion detected, unlock skipped");
            }
        }

        last_pir_state = pir_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("System shutting down");
    gpioWrite(RELAY_PIN, 0);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

