#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_PATTERN_LENGTH 5
#define MAX_PATTERN_LENGTH 15
#define MIN_STEP_DURATION_MS 50
#define MAX_STEP_DURATION_MS 200
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255

typedef struct {
    int motor1_duty_cycle;
    int motor2_duty_cycle;
    int duration_ms;
} HapticStep;

typedef struct {
    HapticStep *steps;
    int length;
} HapticPattern;

volatile sig_atomic_t shutdown_requested = 0;

void signal_handler(int signal) {
    (void)signal;
    shutdown_requested = 1;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

void cleanup_gpio() {
    gpioWrite(MOTOR1_PIN, 0);
    gpioWrite(MOTOR2_PIN, 0);
    gpioTerminate();
}

HapticPattern generate_random_pattern() {
    HapticPattern pattern;
    int length = (rand() % (MAX_PATTERN_LENGTH - MIN_PATTERN_LENGTH + 1)) + MIN_PATTERN_LENGTH;
    pattern.length = length;
    pattern.steps = (HapticStep *)malloc(length * sizeof(HapticStep));
    if (pattern.steps == NULL) {
        fprintf(stderr, "Error: Memory allocation failed for pattern steps\n");
        pattern.length = 0;
        return pattern;
    }

    for (int i = 0; i < length; i++) {
        pattern.steps[i].motor1_duty_cycle = (rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1)) + MIN_DUTY_CYCLE;
        pattern.steps[i].motor2_duty_cycle = (rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1)) + MIN_DUTY_CYCLE;
        pattern.steps[i].duration_ms = (rand() % (MAX_STEP_DURATION_MS - MIN_STEP_DURATION_MS + 1)) + MIN_STEP_DURATION_MS;
    }

    return pattern;
}

void play_pattern(HapticPattern pattern) {
    for (int i = 0; i < pattern.length; i++) {
        if (shutdown_requested) {
            break;
        }

        if (gpioPWM(MOTOR1_PIN, pattern.steps[i].motor1_duty_cycle) != 0) {
            fprintf(stderr, "Error: Failed to set PWM for motor 1\n");
            break;
        }
        if (gpioPWM(MOTOR2_PIN, pattern.steps[i].motor2_duty_cycle) != 0) {
            fprintf(stderr, "Error: Failed to set PWM for motor 2\n");
            break;
        }

        gpioDelay(pattern.steps[i].duration_ms * 1000);
    }

    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
}

void free_pattern(HapticPattern pattern) {
    free(pattern.steps);
}

int main() {
    signal(SIGINT, signal_handler);

    if (initialize_gpio() != 0) {
        return 1;
    }

    srand(time(NULL));

    while (!shutdown_requested) {
        HapticPattern pattern = generate_random_pattern();
        play_pattern(pattern);
        free_pattern(pattern);
    }

    cleanup_gpio();
    return 0;
}

