#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN  4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN    27

#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE         "weight_log.txt"

#define DEFAULT_SCALE_FACTOR 1.0
#define DEFAULT_OFFSET       0.0
#define WEIGHT_THRESHOLD     10.0
#define NUM_CALIBRATION_READINGS 100
#define READ_TIMEOUT_US      500000
#define SAMPLE_DELAY_US      500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(long *out_value) {
    if (out_value == NULL) return -1;

    uint32_t start = gpioTick();
    while (gpioRead(HX711_DATA_PIN) == 1) {
        if ((gpioTick() - start) > READ_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout waiting for data pin low\n");
            return -1;
        }
        gpioDelay(100);
    }

    uint32_t data = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data |= 1;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1);
    }

    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    *out_value = (long)data;
    return 0;
}

static int calibrate_hx711(double *offset) {
    long sum = 0;
    int valid = 0;

    printf("Calibrating HX711 (zero load)...\n");
    for (int i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        long val;
        if (read_hx711(&val) == 0) {
            sum += val;
            valid++;
        }
        gpioDelay(10000);
    }

    if (valid == 0) {
        fprintf(stderr, "Calibration failed: no valid readings\n");
        return -1;
    }

    *offset = (double)sum / valid;
    printf("Calibration complete. Offset: %.2f\n", *offset);
    return 0;
}

static int load_calibration(double *scale, double *offset) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: could not open %s, using defaults\n", CALIBRATION_FILE);
        *scale = DEFAULT_SCALE_FACTOR;
        *offset = DEFAULT_OFFSET;
        return -1;
    }

    if (fscanf(fp, "%lf %lf", scale, offset) != 2) {
        fprintf(stderr, "Warning: invalid calibration file, using defaults\n");
        *scale = DEFAULT_SCALE_FACTOR;
        *offset = DEFAULT_OFFSET;
        fclose(fp);
        return -1;
    }

    fclose(fp);
    printf("Calibration loaded: scale=%.4f, offset=%.4f\n", *scale, *offset);
    return 0;
}

static int save_calibration(double scale, double offset) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: could not open %s for writing\n", CALIBRATION_FILE);
        return -1;
    }
    fprintf(fp, "%.4f %.4f\n", scale, offset);
    fclose(fp);
    printf("Calibration saved: scale=%.4f, offset=%.4f\n", scale, offset);
    return 0;
}

static int log_weight(double weight) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: could not open %s for logging\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fclose(fp);
    return 0;
}

static void control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1);
        printf("Solenoid engaged (weight %.2f kg > %.2f kg)\n", weight, WEIGHT_THRESHOLD);
    } else {
        gpioWrite(SOLENOID_PIN, 0);
        printf("Solenoid disengaged (weight %.2f kg <= %.2f kg)\n", weight, WEIGHT_THRESHOLD);
    }
}

int main(void) {
    double scale_factor = DEFAULT_SCALE_FACTOR;
    double offset = DEFAULT_OFFSET;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Fatal: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    gpioWrite(SOLENOID_PIN, 0);
    gpioWrite(HX711_CLOCK_PIN, 0);

    load_calibration(&scale_factor, &offset);

    if (calibrate_hx711(&offset) == 0) {
        save_calibration(scale_factor, offset);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Monitoring weight... (Ctrl+C to exit)\n");

    while (running) {
        long raw_value;
        if (read_hx711(&raw_value) != 0) {
            fprintf(stderr, "Read error, skipping cycle\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        double weight = ((double)raw_value - offset) / scale_factor;

        control_solenoid(weight);
        log_weight(weight);

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

