#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_GPIO 4
#define MOTOR_IN1_GPIO 17
#define MOTOR_IN2_GPIO 18
#define MOTOR_PWM_GPIO 27

#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_US 50000
#define MOTOR_RUN_TIME_US 5000000
#define CHECK_INTERVAL_US 60000000
#define POST_CLOSE_DELAY_US 60000000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_rain_sensor(void) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int v = gpioRead(RAIN_SENSOR_GPIO);
        if (v < 0) {
            syslog(LOG_ERR, "gpioRead failed on rain sensor GPIO%d: %s", RAIN_SENSOR_GPIO, pigpio_error(v));
            return -1;
        }
        if (v == 0) low_count++;
        if (i < DEBOUNCE_READINGS - 1) gpioDelay(DEBOUNCE_DELAY_US);
    }
    return (low_count >= 3) ? 1 : 0;
}

static int motor_close_window(void) {
    if (gpioWrite(MOTOR_IN1_GPIO, 1) < 0) {
        syslog(LOG_ERR, "Failed to set IN1 high: %s", pigpio_error(gpioRead(MOTOR_IN1_GPIO)));
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_GPIO, 0) < 0) {
        syslog(LOG_ERR, "Failed to set IN2 low: %s", pigpio_error(gpioRead(MOTOR_IN2_GPIO)));
        gpioWrite(MOTOR_IN1_GPIO, 0);
        return -1;
    }
    if (gpioPWM(MOTOR_PWM_GPIO, PWM_DUTY_CYCLE) < 0) {
        syslog(LOG_ERR, "Failed to start PWM on motor PWM GPIO: %s", pigpio_error(gpioPWM(MOTOR_PWM_GPIO, PWM_DUTY_CYCLE)));
        gpioWrite(MOTOR_IN1_GPIO, 0);
        gpioWrite(MOTOR_IN2_GPIO, 0);
        return -1;
    }
    syslog(LOG_INFO, "Motor started: IN1=1, IN2=0, PWM=%d", PWM_DUTY_CYCLE);
    gpioDelay(MOTOR_RUN_TIME_US);
    if (gpioPWM(MOTOR_PWM_GPIO, 0) < 0) {
        syslog(LOG_ERR, "Failed to stop PWM: %s", pigpio_error(gpioPWM(MOTOR_PWM_GPIO, 0)));
        return -1;
    }
    if (gpioWrite(MOTOR_IN1_GPIO, 0) < 0) {
        syslog(LOG_ERR, "Failed to clear IN1: %s", pigpio_error(gpioWrite(MOTOR_IN1_GPIO, 0)));
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_GPIO, 0) < 0) {
