#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define HX711_DT_PIN  23
#define HX711_SCK_PIN 24
#define LOCK_PIN      17

#define WEIGHT_THRESHOLD 100.0f
#define LOCK_DURATION    5
#define LOG_FILE         "stock_events.txt"
#define HX711_TIMEOUT_US 1000000
#define SAMPLE_INTERVAL  1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, message);
    } else {
        fprintf(fp, "[unknown time]: %s\n", message);
    }
    fclose(fp);
}

static int read_hx711(long *out) {
    if (gpioSetMode(HX711_DT_PIN, PI_INPUT) < 0) return -1;
    if (gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) return -1;

    uint32_t start = gpioTick();
    while (gpioRead(HX711_DT_PIN) == 1) {
        if (gpioTick() - start > HX711_TIMEOUT_US) {
            log_event("HX711 timeout waiting for data line to go low");
            return -1;
        }
        gpioDelay(100);
    }

    long count = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_SCK_PIN, 1) < 0) return -1;
        gpioDelay(1);
        count <<= 1;
        if (gpioRead(HX711_DT_PIN) == 1) count++;
        if (gpioWrite(HX711_SCK_PIN, 0) < 0) return -1;
        gpioDelay(1);
    }

    if (gpioWrite(HX711_SCK_PIN, 1) < 0) return -1;
    gpioDelay(1);
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) return -1;
    gpioDelay(1);

    if (count & 0x800000) count |= 0xFF000000L;

    *out = count;
    return 0;
}

static int activate_lock(int duration) {
    if (gpioSetMode(LOCK_PIN, PI_OUTPUT) < 0) {
        log_event("Failed to set lock pin as output");
        return -1;
    }
    if (gpioWrite(LOCK_PIN, 1) < 0) {
        log_event("Failed to activate lock");
        return -1;
    }
    log_event("Lock activated");

    for (int i = 0; i < duration && running; i++) {
        sleep(1);
    }

    if (gpioWrite(LOCK_PIN, 0) < 0) {
        log_event("Failed to deactivate lock");
        return -1;
    }
    log_event("Lock deactivated");
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_event("Stock monitoring started");

    while (running) {
        long raw;
        if (read_hx711(&raw) < 0) {
            log_event("HX711 read failed; skipping cycle");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float weight = (float)raw / 1000.0f;

        char msg[128];
        snprintf(msg, sizeof(msg), "Weight: %.2f g", weight);
        log_event(msg);

        if (weight < WEIGHT_THRESHOLD) {
            log_event("Weight below threshold; activating lock");
            if (activate_lock(LOCK_DURATION) < 0) {
                log_event("Lock activation failed");
            }
        }

        sleep(SAMPLE_INTERVAL);
    }

    log_event("Stock monitoring stopped");
    gpioTerminate();
    return 0;
}

