#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define HX711_DATA_PIN    4
#define HX711_CLOCK_PIN   17
#define SOLENOID_PIN      27

#define CALIBRATION_FILE  "calibration.txt"
#define LOG_FILE          "security.log"

#define WEIGHT_THRESHOLD  5.0
#define SOLENOID_DURATION 5
#define HX711_TIMEOUT_US  100000
#define HX711_SETTLE_US   1000000
#define SAMPLE_DELAY_US   100000

static volatile sig_atomic_t g_running = 1;
static double g_calibration_factor = 1.0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int hx711_read_raw(int32_t *out) {
    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) < 0) return -1;
    if (gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) return -1;

    uint32_t start = gpioTick();
    while (gpioRead(HX711_DATA_PIN) == 1) {
        if ((gpioTick() - start) > HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout: data line stuck high\n");
            return -1;
        }
        gpioDelay(100);
    }

    uint32_t data = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_CLOCK_PIN, 1) < 0) return -1;
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(HX711_DATA_PIN) == 1) data |= 1;
        if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) return -1;
        gpioDelay(1);
    }

    if (gpioWrite(HX711_CLOCK_PIN, 1) < 0) return -1;
    gpioDelay(1);
    if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) return -1;
    gpioDelay(1);

    if (data & 0x800000) data |= 0xFF000000;
    *out = (int32_t)data;
    return 0;
}

static int save_calibration(double factor) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (!fp) {
        perror("fopen calibration");
        return -1;
    }
    if (fprintf(fp, "%.6f\n", factor) < 0) {
        perror("fprintf calibration");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose calibration");
        return -1;
    }
    return 0;
}

static int load_calibration(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (!fp) {
        perror("fopen calibration");
        return -1;
    }
    if (fscanf(fp, "%lf", &g_calibration_factor) != 1) {
        fprintf(stderr, "Failed to read calibration factor\n");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose calibration");
        return -1;
    }
    return 0;
}

static int log_event(double weight) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }
    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s, Weight: %.2f kg\n", ts, weight) < 0) {
        perror("fprintf log");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose log");
        return -1;
    }
    return 0;
}

static int control_solenoid(int activate) {
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(SOLENOID_PIN, activate ? 1 : 0) < 0) return -1;
    if (activate) {
        gpioDelay(SOLENOID_DURATION * 1000000);
        if (gpioWrite(SOLENOID_PIN, 0) < 0) return -1;
    }
    return 0;
}

static int calibrate_sensor(void) {
    double known_weight;
    printf("Place a known weight on the load cell and enter its value in kg: ");
    fflush(stdout);
    if (scanf("%lf", &known_weight) != 1 || known_weight <= 0.0) {
        fprintf(stderr, "Invalid input for known weight\n");
        return -1;
    }
    int32_t raw;
    if (hx711_read_raw(&raw) != 0) {
        fprintf(stderr, "Failed to read raw value during calibration\n");
        return -1;
    }
    g_calibration_factor = (double)raw / known_weight;
    printf("Calibration factor: %.6f\n", g_calibration_factor);
    if (save_calibration(g_calibration_factor) != 0) {
        fprintf(stderr, "Failed to save calibration factor\n");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (calibrate_sensor() != 0) {
        fprintf(stderr, "Calibration failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    if (load_calibration() != 0) {
        fprintf(stderr, "Failed to load calibration. Using default.\n");
    }

    printf("Monitoring weight... (Ctrl+C to exit)\n");

    while (g_running) {
        int32_t raw;
        if (hx711_read_raw(&raw) != 0) {
            fprintf(stderr, "HX711 read error, retrying...\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        double weight = (double)raw / g_calibration_factor;

        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight %.2f kg exceeds threshold. Activating solenoid.\n", weight);
            if (control_solenoid(1) != 0) {
                fprintf(stderr, "Failed to activate solenoid\n");
            }
            if (log_event(weight) != 0) {
                fprintf(stderr, "Failed to log event\n");
            }
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    control_solenoid(0);
    gpioTerminate();
    return 0;
}

