#include <errno.h>
#include <gpiod.h>

#define SENSOR_PIN  16
#define RELAY_PIN   20
#define LOG_FILE    "relay_events.log"
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void log_event(FILE *log, int relay_state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(log, "%s Relay toggled to %s\n", timestamp,
                relay_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(log) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *relay_line = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (sensor_line == NULL) {
        fprintf(stderr, "Failed to get sensor line (GPIO%d): %s\n",
                SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (relay_line == NULL) {
        fprintf(stderr, "Failed to get relay line (GPIO%d): %s\n",
                RELAY_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(sensor_line, "ky022_sensor") < 0) {
        fprintf(stderr, "Failed to request sensor line as input: %s\n",
                strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(relay_line, "srdr05v_relay", 0) < 0) {
        fprintf(stderr, "Failed to request relay line as output: %s\n",
                strerror(errno));
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring KY-022 on GPIO%d, relay on GPIO%d. Press Ctrl+C to exit.\n",
           SENSOR_PIN, RELAY_PIN);

    while (running) {
        int sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor value: %s\n",
                    strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        /* KY-022 is active-low: LOW (0) means obstacle detected */
        if (sensor_value == 0) {
            int current_relay = gpiod_line_get_value(relay_line);
            if (current_relay < 0) {
                fprintf(stderr, "Failed to read relay state: %s\n",
                        strerror(errno));
                usleep(POLL_INTERVAL_US);
                continue;
            }

            int new_relay = current_relay ? 0 : 1;

            if (gpiod_line_set_value(relay_line, new_relay) < 0) {
                fprintf(stderr, "Failed to set relay value: %s\n",
                        strerror(errno));
                usleep(POLL_INTERVAL_US);
                continue;
            }

            log_event(log_file, new_relay);
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (relay_line != NULL) {
        gpiod_line_release(relay_line);
    }
    if (sensor_line != NULL) {
        gpiod_line_release(sensor_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

