#include <gpiod.h>

#define CONFIG_FILE "watering.conf"
#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 18
#define MIN_DURATION 1
#define MAX_DURATION 3600

static volatile sig_atomic_t g_stop = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_stop = 1;
}

static int read_duration(const char *filename, int *duration)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening config file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        if (ferror(fp))
            fprintf(stderr, "Error reading config file: %s\n", strerror(errno));
        else
            fprintf(stderr, "Config file is empty or has no data\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *key = strtok(line, "=");
    char *value = strtok(NULL, "\n");
    if (!key || !value || strcmp(key, "duration") != 0) {
        fprintf(stderr, "Invalid config format; expected 'duration=<seconds>'\n");
        return -1;
    }

    char *endptr = NULL;
    errno = 0;
    long val = strtol(value, &endptr, 10);
    if (errno != 0 || endptr == value || *endptr != '\0' || val < MIN_DURATION || val > MAX_DURATION) {
        fprintf(stderr, "Invalid duration value '%s'. Must be an integer between %d and %d.\n",
                value, MIN_DURATION, MAX_DURATION);
        return -1;
    }

    *duration = (int)val;
    return 0;
}

static int sleep_interruptible(unsigned int seconds)
{
    unsigned int remaining = seconds;
    while (remaining > 0 && !g_stop) {
        remaining = sleep(remaining);
    }
    return g_stop ? -1 : 0;
}

int main(void)
{
    int duration = 0;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (read_duration(CONFIG_FILE, &duration) != 0) {
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    if (gpiod_line_request_output(line, "watering-system", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    printf("Watering system started. Duration: %d seconds\n", duration);
    fflush(stdout);

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to activate valve: %s\n", strerror(errno));
        goto cleanup_line;
    }
    printf("Valve activated\n");
    fflush(stdout);

    if (sleep_interruptible((unsigned int)duration) == 0) {
        printf("Watering duration complete\n");
    } else {
        printf("Watering interrupted by signal\n");
    }
    fflush(stdout);

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to deactivate valve: %s\n", strerror(errno));
        goto cleanup_line;
    }
    printf("Valve deactivated\n");
    fflush(stdout);

    ret = EXIT_SUCCESS;

cleanup_line:
    gpiod_line_release(line);
cleanup_chip:
    gpiod_chip_close(chip);
    return ret;
}

