#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define LEFT_SENSOR_PIN    4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN  27

#define LEFT_FORWARD_PIN  22
#define LEFT_BACKWARD_PIN 23
#define RIGHT_FORWARD_PIN 24
#define RIGHT_BACKWARD_PIN 25

/* ---- Tuning constants ---- */
#define BASE_SPEED        150   /* 0..255 */
#define PWM_FREQUENCY     1000  /* Hz */
#define PWM_RANGE         255
#define SAMPLE_PERIOD_US  10000 /* 10 ms */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/*  Signal handler — graceful shutdown on Ctrl+C / SIGINT            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/*  Read a sensor pin; returns 0 (line detected / active low) or 1.   */
/*  Returns -1 on read error.                                         */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n",
                pin, pigpio_error(v));
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/*  Drive one motor: speed in [-255, 255].                            */
/*  Returns 0 on success, -1 on error.                                */
/* ------------------------------------------------------------------ */
static int drive_motor(int forward_pin, int backward_pin, int speed)
{
    if (speed > 0) {
        if (gpioPWM(forward_pin, speed) < 0) {
            fprintf(stderr, "Error setting PWM on GPIO %d: %s\n",
                    forward_pin, pigpio_error(speed));
            return -1;
        }
        if (gpioWrite(backward_pin, 0) < 0) {
            fprintf(stderr, "Error writing GPIO %d: %s\n",
                    backward_pin, pigpio_error(speed));
            return -1;
        }
    } else if (speed < 0) {
        if (gpioPWM(backward_pin, -speed) < 0) {
            fprintf(stderr, "Error setting PWM on GPIO %d: %s\n",
                    backward_pin, pigpio_error(speed));
            return -1;
        }
        if (gpioWrite(forward_pin, 0) < 0) {
            fprintf(stderr, "Error writing GPIO %d: %s\n",
                    forward_pin, pigpio_error(speed));
            return -1;
        }
    } else {
        if (gpioWrite(forward_pin, 0) < 0) {
            fprintf(stderr, "Error writing GPIO %d: %s\n",
                    forward_pin, pigpio_error(speed));
            return -1;
        }
        if (gpioWrite(backward_pin, 0) < 0) {
            fprintf(stderr, "Error writing GPIO %d: %s\n",
                    backward_pin, pigpio_error(speed));
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/*  Stop both motors.                                                 */
/* ------------------------------------------------------------------ */
static void stop_motors(void)
{
    gpioWrite(LEFT_FORWARD_PIN, 0);
    gpioWrite(LEFT_BACKWARD_PIN, 0);
    gpioWrite(RIGHT_FORWARD_PIN, 0);
    gpioWrite(RIGHT_BACKWARD_PIN, 0);
}

/* ------------------------------------------------------------------ */
/*  Log one control cycle to the trace file.                          */
/* ------------------------------------------------------------------ */
static void log_data(int left_sensor, int middle_sensor,
                     int right_sensor, int left_speed, int right_speed)
{
    if (!g_log_file)
        return;

    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    fprintf(g_log_file,
            "%s, L:%d, M:%d, R:%d, LeftSpeed:%d, RightSpeed:%d\n",
            timestamp, left_sensor, middle_sensor, right_sensor,
            left_speed, right_speed);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/*  Cleanup — called on every exit path.                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    stop_motors();

    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/*  Main                                                              */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins as inputs ---- */
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set sensor pin modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure motor pins as outputs ---- */
    if (gpioSetMode(LEFT_FORWARD_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(LEFT_BACKWARD_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(RIGHT_FORWARD_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(RIGHT_BACKWARD_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set motor pin modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Set PWM frequency and range for motor pins ---- */
    if (gpioSetPWMfrequency(LEFT_FORWARD_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(LEFT_BACKWARD_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RIGHT_FORWARD_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RIGHT_BACKWARD_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(LEFT_FORWARD_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(LEFT_BACKWARD_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(RIGHT_FORWARD_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(RIGHT_BACKWARD_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen("trace_log.txt", "a");
    if (!g_log_file) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Line-following robot started. Press Ctrl+C to stop.\n");

    /* ---- Main control loop ---- */
    while (g_running) {
        int left   = read_sensor(LEFT_SENSOR_PIN);
        int middle = read_sensor(MIDDLE_SENSOR_PIN);
        int right  = read_sensor(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Sensor read error — stopping motors\n");
            stop_motors();
            break;
        }

        int left_speed  = 0;
        int right_speed = 0;

        /* Active-low logic: 0 = line detected */
        if (middle == 0) {
            left_speed  = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (left == 0 && right == 1) {
            left_speed  = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
        } else if (left == 1 && right == 0) {
            left_speed  = BASE_SPEED;
            right_speed = BASE_SPEED / 2;
        } else {
            left_speed  = 0;
            right_speed = 0;
        }

        if (drive_motor(LEFT_FORWARD_PIN, LEFT_BACKWARD_PIN, left_speed) < 0 ||
            drive_motor(RIGHT_FORWARD_PIN, RIGHT_BACKWARD_PIN, right_speed) < 0) {
            fprintf(stderr, "Motor drive error — stopping motors\n");
            stop_motors();
            break;
        }

        log_data(left, middle, right, left_speed, right_speed);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

