    if (gpioSetMode(LEFT_FORWARD_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(LEFT_BACKWARD_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(RIGHT_FORWARD_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(RIGHT_BACKWARD_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set motor pin modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Set PWM frequency and range for motor pins ---- */
    if (gpioSetPWMfrequency(LEFT_FORWARD_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(LEFT_BACKWARD_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RIGHT_FORWARD_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RIGHT_BACKWARD_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(LEFT_FORWARD_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(LEFT_BACKWARD_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(RIGHT_FORWARD_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(RIGHT_BACKWARD_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen("trace_log.txt", "a");
    if (!g_log_file) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Line-following robot started. Press Ctrl+C to stop.\n");

    /* ---- Main control loop ---- */
    while (g_running) {
        int left   = read_sensor(LEFT_SENSOR_PIN);
        int middle = read_sensor(MIDDLE_SENSOR_PIN);
        int right  = read_sensor(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Sensor read error — stopping motors\n");
            stop_motors();
            break;
        }

        int left_speed  = 0;
        int right_speed = 0;

        /* Active-low logic: 0 = line detected */
        if (middle == 0) {
            left_speed  = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (left == 0 && right == 1) {
            left_speed  = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
        } else if (left == 1 && right == 0) {
            left_speed  = BASE_SPEED;
            right_speed = BASE_SPEED / 2;
        } else {
            left_speed  = 0;
            right_speed = 0;
        }

        if (drive_motor(LEFT_FORWARD_PIN, LEFT_BACKWARD_PIN, left_speed) < 0 ||
            drive_motor(RIGHT_FORWARD_PIN, RIGHT_BACKWARD_PIN, right_speed) < 0) {
            fprintf(stderr, "Motor drive error — stopping motors\n");
            stop_motors();
            break;
        }

        log_data(left, middle, right, left_speed, right_speed);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

