#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define BH1750_ADDR    0x23
#define RELAY_GPIO     23
#define LUX_THRESHOLD  150.0f
#define LOG_FILE       "grow_log.txt"
#define MEASURE_DELAY  0.180   /* seconds for BH1750 one-time high-res measurement */

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return;
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static int read_bh1750(int handle, float *lux_out) {
    char cmd = 0x10; /* One-Time High-Resolution Mode */
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        log_message("BH1750 write command failed");
        return -1;
    }
    time_sleep(MEASURE_DELAY);
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        log_message("BH1750 read failed");
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X\n", BH1750_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    int relay_state = 0;
    log_message("Grow lamp controller started");

    while (running) {
        float lux;
        if (read_bh1750(i2c_handle, &lux) == 0) {
            char msg[64];
            snprintf(msg, sizeof(msg), "Lux: %.2f", lux);
            log_message(msg);

            if (lux < LUX_THRESHOLD && relay_state == 0) {
                gpioWrite(RELAY_GPIO, 1);
                relay_state = 1;
                log_message("Grow lamp ON");
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                gpioWrite(RELAY_GPIO, 0);
                relay_state = 0;
                log_message("Grow lamp OFF");
            }
        } else {
            log_message("Sensor read error, continuing");
        }
        time_sleep(1.0);
    }

    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    log_message("Grow lamp controller stopped");
    return EXIT_SUCCESS;
}

