#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22

#define LOCK_PULSE_US  1000   /* ~0 degrees   */
#define UNLOCK_PULSE_US 2000  /* ~180 degrees */
#define MIN_PULSE_US   500
#define MAX_PULSE_US   2500
#define DEBOUNCE_US    100000 /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_servo_pulse(int pulse_us) {
    if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
        fprintf(stderr, "Error: pulse %d us out of range [%d, %d]\n",
                pulse_us, MIN_PULSE_US, MAX_PULSE_US);
        return -1;
    }
    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

static void lock_door(void) {
    if (set_servo_pulse(LOCK_PULSE_US) == 0) {
        printf("Door locked.\n");
        fflush(stdout);
    }
}

static void unlock_door(void) {
    if (set_servo_pulse(UNLOCK_PULSE_US) == 0) {
        printf("Door unlocked.\n");
        fflush(stdout);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set SERVO_PIN %d as output\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) < 0 ||
        gpioSetMode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set button pins as input\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: cannot set pull-up resistors\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control ready. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            lock_door();
            gpioDelay(DEBOUNCE_US);
        }
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            unlock_door();
            gpioDelay(DEBOUNCE_US);
        }
        gpioDelay(10000); /* 10 ms poll interval */
    }

    /* Clean shutdown: stop servo pulses and release pigpio */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

