/*
 * Haptic feedback system for Raspberry Pi 4 Model B
 * Pulses two Precision Microdrives 310-101 vibration motors sequentially.
 *
 * NOTE: The 310-101 requires 3 V at 60 mA typical and CANNOT be driven
 * directly from a Raspberry Pi GPIO pin.  An external driver circuit
 * (e.g. NPN transistor with flyback diode) is REQUIRED.
 *
 * Wiring:
 *   Motor 1 driver -> GPIO17 (BCM)
 *   Motor 2 driver -> GPIO27 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o haptic haptic.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <gpiod.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

#define MOTOR1_PULSE_MS 200
#define MOTOR2_PULSE_MS 300

#define CONSUMER "haptic-feedback"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_line_value(struct gpiod_line *line, int value)
{
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("gpiod_line_set_value");
    }
    return ret;
}

static int pulse_motor(struct gpiod_line *line, int duration_ms)
{
    if (set_line_value(line, 1) < 0)
        return -1;

    usleep(duration_ms * 1000);

    if (set_line_value(line, 0) < 0)
        return -1;

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *motor1_line = NULL;
    struct gpiod_line *motor2_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip4\")");
        return EXIT_FAILURE;
    }

    motor1_line = gpiod_chip_get_line(chip, MOTOR1_PIN);
    if (!motor1_line) {
        perror("gpiod_chip_get_line(MOTOR1_PIN)");
        goto cleanup;
    }

    motor2_line = gpiod_chip_get_line(chip, MOTOR2_PIN);
    if (!motor2_line) {
        perror("gpiod_chip_get_line(MOTOR2_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_output(motor1_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(motor1_line)");
        goto cleanup;
    }

    if (gpiod_line_request_output(motor2_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(motor2_line)");
        goto cleanup;
    }

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (pulse_motor(motor1_line, MOTOR1_PULSE_MS) < 0)
            goto cleanup;

        if (!g_running)
            break;

        if (pulse_motor(motor2_line, MOTOR2_PULSE_MS) < 0)
            goto cleanup;
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (motor1_line) {
        set_line_value(motor1_line, 0);
        gpiod_line_release(motor1_line);
    }
    if (motor2_line) {
        set_line_value(motor2_line, 0);
        gpiod_line_release(motor2_line);
    }
    if (chip)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nHaptic feedback system stopped.\n");

    return ret;
}

