/*
 * sound_alarm.c — Sound-triggered alarm for Raspberry Pi 5
 *
 * Build:  gcc -O2 -Wall -Wextra -o sound_alarm sound_alarm.c -lgpiod -lzmq
 * Run:    ./sound_alarm sound_sensor   (polls GPIO17, publishes on 5555)
 *         ./sound_alarm alarm_node     (subscribes 5555, lights GPIO27)
 *
 * GPIO17 (BCM) — LM393 sound sensor digital out (active-low: 0 = sound)
 * GPIO27 (BCM) — Alarm LED
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#include <gpiod.h>
#include <zmq.h>

#define GPIO_CHIP_NAME   "gpiochip4"   /* RP1 GPIO controller on Pi 5 */
#define SOUND_SENSOR_PIN 17            /* BCM 17 — LM393 digital out */
#define ALARM_LED_PIN    27            /* BCM 27 — alarm LED */
#define ZMQ_PORT         5555
#define POLL_INTERVAL_MS 10
#define ALARM_DURATION_S 1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/* ---------- Sound sensor node ---------- */

static int sound_sensor_node(struct gpiod_line *line, void *ctx)
{
    void *sock = ctx;
    int rc;

    while (g_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
            sleep_ms(POLL_INTERVAL_MS);
            continue;
        }

        /* LM393 digital out is active-low: 0 => sound detected */
        if (val == 0) {
            rc = zmq_send(sock, "SOUND_ALERTS", 12, 0);
            if (rc < 0) {
                fprintf(stderr, "zmq_send failed: %s\n", zmq_strerror(errno));
            } else {
                printf("Sound detected — alert sent\n");
            }
        }

        sleep_ms(POLL_INTERVAL_MS);
    }

    return 0;
}

/* ---------- Alarm node ---------- */

static int alarm_node(void *ctx)
{
    void *sock = zmq_socket(ctx, ZMQ_SUB);
    if (!sock) {
        fprintf(stderr, "zmq_socket failed: %s\n", zmq_strerror(errno));
        return -1;
    }

    if (zmq_connect(sock, "tcp://localhost:5555") < 0) {
        fprintf(stderr, "zmq_connect failed: %s\n", zmq_strerror(errno));
        zmq_close(sock);
        return -1;
    }

    if (zmq_setsockopt(sock, ZMQ_SUBSCRIBE, "SOUND_ALERTS", 12) < 0) {
        fprintf(stderr, "zmq_setsockopt failed: %s\n", zmq_strerror(errno));
        zmq_close(sock);
        return -1;
    }

    printf("Alarm node listening on tcp://localhost:%d\n", ZMQ_PORT);

    while (g_running) {
        zmq_msg_t msg;
        int rc = zmq_msg_recv(&msg, sock, ZMQ_NOBLOCK);
        if (rc < 0) {
            if (errno == EAGAIN) {
                sleep_ms(POLL_INTERVAL_MS);
                continue;
            }
            fprintf(stderr, "zmq_msg_recv failed: %s\n", zmq_strerror(errno));
            break;
        }

        printf("Alarm triggered — LED on for %d s\n", ALARM_DURATION_S);
        sleep_ms(ALARM_DURATION_S * 1000);
    }

    zmq_close(sock);
    return 0;
}

/* ---------- Main ---------- */

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ZeroMQ context */
    void *zmq_ctx = zmq_ctx_new();
    if (!zmq_ctx) {
        fprintf(stderr, "zmq_ctx_new failed: %s\n", zmq_strerror(errno));
        return EXIT_FAILURE;
    }

    /* GPIO chip */
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        zmq_ctx_destroy(zmq_ctx);
        return EXIT_FAILURE;
    }

    int ret = EXIT_FAILURE;

    if (strcmp(mode, "sound_sensor") == 0) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
        if (!line) {
            fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                    SOUND_SENSOR_PIN, strerror(errno));
            goto cleanup_chip;
        }

        if (gpiod_line_request_input(line, "sound_alarm") < 0) {
            fprintf(stderr, "gpiod_line_request_input failed: %s\n",
                    strerror(errno));
            goto cleanup_chip;
        }

        void *sock = zmq_socket(zmq_ctx, ZMQ_PUB);
        if (!sock) {
            fprintf(stderr, "zmq_socket failed: %s\n", zmq_strerror(errno));
            goto cleanup_line;
        }

        if (zmq_bind(sock, "tcp://*:*") < 0) {
            fprintf(stderr, "zmq_bind failed: %s\n", zmq_strerror(errno));
            zmq_close(sock);
            goto cleanup_line;
        }

        printf("Sound sensor node running on GPIO%d, publishing on port %d\n",
               SOUND_SENSOR_PIN, ZMQ_PORT);

        ret = sound_sensor_node(line, sock);

        zmq_close(sock);
    } else if (strcmp(mode, "alarm_node") == 0) {
        ret = alarm_node(zmq_ctx);
    } else {
        fprintf(stderr, "Invalid mode: %s\n", mode);
    }

    /* ---------- Cleanup ---------- */
cleanup_line:
    /* In sound_sensor mode the line was requested; release it. */
    gpiod_chip_release_line(chip, SOUND_SENSOR_PIN);
cleanup_chip:
    gpiod_chip_close(chip);
    zmq_ctx_destroy(zmq_ctx);

    return ret;
}

