#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define IR_GPIO 17
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MAX_PULSES 68
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_TOLERANCE 25

static volatile sig_atomic_t running = 1;
static MQTTClient mqtt_client;
static volatile sig_atomic_t mqtt_connected = 0;

typedef struct {
    uint32_t pulses[MAX_PULSES];
    int count;
    uint32_t last_tick;
} ir_data_t;

static ir_data_t ir_data = {0};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void ir_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    ir_data_t *data = (ir_data_t *)userdata;
    if (level == 0) {
        uint32_t duration = tick - data->last_tick;
        if (data->count < MAX_PULSES) {
            data->pulses[data->count++] = duration;
        } else {
            syslog(LOG_ERR, "Pulse buffer overflow");
        }
    }
    data->last_tick = tick;
}

static bool decode_nec(uint32_t *pulses, int count, uint32_t *address, uint32_t *command) {
    if (count < 34) return false;
    if (pulses[0] < NEC_HEADER_MARK - NEC_TOLERANCE || pulses[0] > NEC_HEADER_MARK + NEC_TOLERANCE) return false;
    if (pulses[1] < NEC_HEADER_SPACE - NEC_TOLERANCE || pulses[1] > NEC_HEADER_SPACE + NEC_TOLERANCE) return false;
    uint32_t addr = 0, cmd = 0, inv_addr = 0, inv_cmd = 0;
    for (int i = 0; i < 8; i++) {
        int idx = 2 + i * 2;
        if (idx + 1 >= count) return false;
        if (pulses[idx] < NEC_BIT_MARK - NEC_TOLERANCE || pulses[idx] > NEC_BIT_MARK + NEC_TOLERANCE) return false;
        if (pulses[idx + 1] > NEC_ONE_SPACE - NEC_TOLERANCE && pulses[idx + 1] < NEC_ONE_SPACE + NEC_TOLERANCE) {
            addr |= (1 << i);
        } else if (pulses[idx + 1] > NEC_ZERO_SPACE - NEC_TOLERANCE && pulses[idx + 1] < NEC_ZERO_SPACE + NEC_TOLERANCE) {
            addr &= ~(1 << i);
        } else {
            return false;
        }
    }
    for (int i = 0; i < 8; i++) {
        int idx = 18 + i * 2;
        if (idx + 1 >= count) return false;
        if (pulses[idx] < NEC_BIT_MARK - NEC_TOLERANCE || pulses[idx] > NEC_BIT_MARK + NEC_TOLERANCE) return false;
        if (pulses[idx + 1] > NEC_ONE_SPACE - NEC_TOLERANCE && pulses[idx + 1] < NEC_ONE_SPACE + NEC_TOLERANCE) {
            inv_addr |= (1 << i);
        } else if (pulses[idx + 1] > NEC_ZERO_SPACE - NEC_TOLERANCE && pulses[idx + 1] < NEC_ZERO_SPACE + NEC_TOLERANCE) {
            inv_addr &= ~(1 << i);
        } else {
            return false;
        }
    }
    for (int i = 0; i < 8; i++) {
        int idx = 34 + i * 2;
        if (idx + 1 >= count) return false;
        if (pulses[idx] < NEC_BIT_MARK - NEC_TOLERANCE || pulses[idx] > NEC_BIT_MARK + NEC_TOLERANCE) return false;
        if (pulses[idx + 1] > NEC_ONE_SPACE - NEC_TOLERANCE && pulses[idx + 1] < NEC_ONE_SPACE + NEC_TOLERANCE) {
            cmd |= (1 << i);
        } else if (pulses[idx + 1] > NEC_ZERO_SPACE - NEC_TOLERANCE && pulses[idx + 1] < NEC_ZERO_SPACE + NEC_TOLERANCE) {
            cmd &= ~(1 << i);
        } else {
            return false;
        }
    }
    for (int i = 0; i < 8; i++) {
        int idx = 50 + i * 2;
        if (idx + 1 >= count) return false;
        if (pulses[idx] < NEC_BIT_MARK - NEC_TOLERANCE || pulses[idx] > NEC_BIT_MARK + NEC_TOLERANCE) return false;
        if (pulses[idx + 1] > NEC_ONE_SPACE - NEC_TOLERANCE && pulses[idx + 1] < NEC_ONE_SPACE + NEC_TOLERANCE) {
            inv_cmd |= (1 << i);
        } else if (pulses[idx + 1] > NEC_ZERO_SPACE - NEC_TOLERANCE && pulses[idx + 1] < NEC_ZERO_SPACE + NEC_TOLERANCE) {
            inv_cmd &= ~(1 << i);
        } else {
            return false;
        }
    }
    if ((addr ^ inv_addr) != 0xFF) {
        syslog(LOG_WARNING, "NEC address checksum failed: 0x%02X vs 0x%02X", addr, inv_addr);
        return false;
    }
    if ((cmd ^ inv_cmd) != 0xFF) {
        syslog(LOG_WARNING, "NEC command checksum failed: 0x%02X vs 0x%02X", cmd, inv_cmd);
        return false;
    }
    *address = addr;
    *command = cmd;
    return true;
}

static void publish_mqtt(uint32_t address, uint32_t command) {
    if (!mqtt_connected) return;
    char payload[64];
    snprintf(payload, sizeof(payload), "{\"address\":%u,\"command\":%u}", address, command);
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos = 0;
    pubmsg.retained = 0;
    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(mqtt_client, MQTT_TOPIC, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish MQTT message: %s", MQTTClient_strerror(rc));
    }
}

static void process_ir_data(ir_data_t *data) {
    if (data->count < 34) return;
    uint32_t address, command;
    if (decode_nec(data->pulses, data->count, &address, &command)) {
        syslog(LOG_INFO, "Decoded NEC: address=0x%02X, command=0x%02X", address, command);
        publish_mqtt(address, command);
    } else {
        syslog(LOG_WARNING, "Failed to decode NEC frame");
    }
    memset(data, 0, sizeof(ir_data_t));
}

static int mqtt_connect_callback(void *context, char *cause, int return_code) {
    (void)context;
    (void)cause;
    if (return_code == MQTTCLIENT_SUCCESS) {
        mqtt_connected = 1;
        syslog(LOG_INFO, "MQTT connected");
    } else {
        syslog(LOG_ERR, "MQTT connection failed: %s", MQTTClient_strerror(return_code));
    }
    return 1;
}

static int mqtt_disconnect_callback(void *context, char *cause) {
    (void)context;
    (void)cause;
    mqtt_connected = 0;
    syslog(LOG_INFO, "MQTT disconnected");
    return 1;
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(IR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as input", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(IR_GPIO, PI_PUD_UP) != 0) {
        syslog(LOG_ERR, "Failed to set pull-up on GPIO %d", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(IR_GPIO, ir_callback, &ir_data) != 0) {
        syslog(LOG_ERR, "Failed to set alert callback on GPIO %d", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    int rc = MQTTClient_create(&mqtt_client, MQTT_HOST, "ir_decoder", MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to create MQTT client: %s", MQTTClient_strerror(rc));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    MQTTClient_setCallbacks(mqtt_client, NULL, mqtt_connect_callback, NULL, mqtt_disconnect_callback);

    rc = MQTTClient_connect(mqtt_client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", MQTTClient_strerror(rc));
        MQTTClient_destroy(&mqtt_client);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "IR decoder started on GPIO %d", IR_GPIO);

    while (running) {
        if (ir_data.count > 0 && (ir_data.last_tick - ir_data.pulses[ir_data.count - 1]) > 100000) {
            process_ir_data(&ir_data);
        }
        MQTTClient_yield();
        usleep(10000);
    }

    syslog(LOG_INFO, "Shutting down...");
    MQTTClient_disconnect(mqtt_client, 1000);
    MQTTClient_destroy(&mqtt_client);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

