#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <math.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define NUM_SENSORS      4
#define I2C_BUS          "/dev/i2c-1"
#define BH1750_ADDR      0x23
#define BH1750_PWR_ON    0x01
#define BH1750_CONT_HRES 0x10
#define CONV_TIME_MS     180
#define MULTICAST_ADDR   "239.255.255.250"
#define MULTICAST_PORT   5005
#define LOOP_DELAY_MS    1000

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static int i2c_write_byte(int fd, unsigned char byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, unsigned char *buf, int len)
{
    int total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF\n");
            return -1;
        }
        total += (int)n;
    }
    return 0;
}

static int read_bh1750(int fd, int addr, float *lux)
{
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02x) failed: %s\n", addr, strerror(errno));
        return -1;
    }

    if (i2c_write_byte(fd, BH1750_PWR_ON) < 0) return -1;
    if (i2c_write_byte(fd, BH1750_CONT_HRES) < 0) return -1;

    usleep(CONV_TIME_MS * 1000);

    unsigned char data[2];
    if (i2c_read_bytes(fd, data, 2) < 0) return -1;

    unsigned int raw = ((unsigned int)data[0] << 8) | data[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(const char *data)
{
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    unsigned char ttl = 1;
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("setsockopt(IP_MULTICAST_TTL)");
        close(sockfd);
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(sockfd, data, strlen(data), 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open(" I2C_BUS ")");
        return 1;
    }

    int addrs[NUM_SENSORS] = {0x23, 0x23, 0x23, 0x23};
    float lux_values[NUM_SENSORS];

    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (read_bh1750(i2c_fd, addrs[i], &lux_values[i]) < 0) {
                lux_values[i] = NAN;
            }
        }

        char data[256];
        int len = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (len + 32 >= (int)sizeof(data)) break;
            len += snprintf(data + len, sizeof(data) - (size_t)len,
                            "%d,%.1f;", i + 1, lux_values[i]);
        }
        if (len > 0) {
            data[len - 1] = '\0';
            if (send_multicast(data) < 0) {
                fprintf(stderr, "Failed to send multicast data\n");
            }
        }

        for (int i = 0; i < 10 && !terminate; i++) {
            usleep(100000);
        }
    }

    close(i2c_fd);
    return 0;
}

