#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define AWM7300V_ADDR  0x28
#define LOG_FILE       "airflow_log.txt"
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 100
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

static void msleep(unsigned ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "read: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "read: short read (%zd of %zu bytes)\n", n, len);
        return -1;
    }
    return 0;
}

static int read_airflow(int fd, float *flow_out)
{
    uint8_t buf[2];
    int attempt;

    for (attempt = 0; attempt < MAX_RETRIES; attempt++) {
        /* Issue a zero-length write to generate a repeated-start condition. */
        if (write(fd, buf, 0) < 0) {
            fprintf(stderr, "write (zero-length) attempt %d: %s\n",
                    attempt + 1, strerror(errno));
            msleep(RETRY_DELAY_MS);
            continue;
        }

        if (i2c_read_bytes(fd, buf, sizeof(buf)) == 0) {
            uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
            uint16_t flow_raw = raw & 0x3FFF;          /* 14-bit data */
            *flow_out = (float)flow_raw * 0.0001f;     /* SLPM */
            return 0;
        }

        if (errno == EIO) {
            fprintf(stderr, "I2C bus error (attempt %d/%d)\n",
                    attempt + 1, MAX_RETRIES);
        } else if (errno == ENXIO) {
            fprintf(stderr, "Sensor not responding (ENXIO) — check wiring/address\n");
            return -1;
        } else {
            fprintf(stderr, "I2C read error (attempt %d/%d): %s\n",
                    attempt + 1, MAX_RETRIES, strerror(errno));
        }
        msleep(RETRY_DELAY_MS);
    }
    return -1;
}

static int log_airflow(FILE *fp, float flow)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime: buffer too small\n");
        return -1;
    }
    if (fprintf(fp, "%s, %.4f SLPM\n", ts, flow) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = i2c_open(I2C_BUS, AWM7300V_ADDR);
    if (g_i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float flow;
        if (read_airflow(g_i2c_fd, &flow) == 0) {
            if (log_airflow(g_log_fp, flow) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Failed to read airflow after %d retries.\n", MAX_RETRIES);
        }
        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down...\n");
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

