/*
 * AS7341 10-Channel Spectral Sensor Logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   AS7341 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   AS7341 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   AS7341 VDD  -> 3.3 V
 *   AS7341 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o spectral_logger spectral_logger.c
 * Run:    ./spectral_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- AS7341 register definitions (from the datasheet) ---- */
#define AS7341_I2C_ADDR          0x39
#define AS7341_ENABLE            0x80
#define AS7341_ATIME             0x81
#define AS7341_WTIME             0x83
#define AS7341_ID                0x92
#define AS7341_STATUS            0x93
#define AS7341_CFG6              0x96
#define AS7341_ASTATUS           0x97
#define AS7341_CH0_DATA_L        0x98
#define AS7341_CH0_DATA_H        0x99
#define AS7341_CH1_DATA_L        0x9A
#define AS7341_CH1_DATA_H        0x9B
#define AS7341_CH2_DATA_L        0x9C
#define AS7341_CH2_DATA_H        0x9D
#define AS7341_CH3_DATA_L        0x9E
#define AS7341_CH3_DATA_H        0x9F
#define AS7341_CH4_DATA_L        0xA0
#define AS7341_CH4_DATA_H        0xA1
#define AS7341_CH5_DATA_L        0xA2
#define AS7341_CH5_DATA_H        0xA3
#define AS7341_CH6_DATA_L        0xA4
#define AS7341_CH6_DATA_H        0xA5
#define AS7341_CH7_DATA_L        0xA6
#define AS7341_CH7_DATA_H        0xA7
#define AS7341_CH8_DATA_L        0xA8
#define AS7341_CH8_DATA_H        0xA9
#define AS7341_CH9_DATA_L        0xAA
#define AS7341_CH9_DATA_H        0xAB

#define AS7341_ENABLE_PON        0x01
#define AS7341_ENABLE_SP_EN      0x02
#define AS7341_ID_VALUE          0x41

#define I2C_BUS                  "/dev/i2c-1"
#define LOG_FILE                 "spectral_log.csv"
#define SAMPLE_INTERVAL_SEC      5

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
static int as7341_init(int fd)
{
    uint8_t id = 0;

    /* Verify device identity */
    if (i2c_read_reg8(fd, AS7341_ID, &id) != 0)
        return -1;
    if (id != AS7341_ID_VALUE) {
        fprintf(stderr, "AS7341 ID mismatch: got 0x%02X, expected 0x%02X\n",
                id, AS7341_ID_VALUE);
        return -1;
    }

    /* Power on */
    if (i2c_write_reg8(fd, AS7341_ENABLE, AS7341_ENABLE_PON) != 0)
        return -1;
    usleep(10000);  /* 10 ms power-up settle */

    /* Set integration time (ATIME) — 0x00 = 2.78 ms per channel */
    if (i2c_write_reg8(fd, AS7341_ATIME, 0x00) != 0)
        return -1;

    /* Set wait time (WTIME) — 0x00 = 2.78 ms */
    if (i2c_write_reg8(fd, AS7341_WTIME, 0x00) != 0)
        return -1;

    /* Configure SMUX: CFG6 selects the 10-channel sequence */
    if (i2c_write_reg8(fd, AS7341_CFG6, 0x00) != 0)
        return -1;

    /* Enable spectral measurement */
    if (i2c_write_reg8(fd, AS7341_ENABLE,
                       AS7341_ENABLE_PON | AS7341_ENABLE_SP_EN) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int as7341_read_spectral(int fd, uint16_t *ch)
{
    /* Check status: bit 0 (AVALID) indicates data is new */
    uint8_t status = 0;
    if (i2c_read_reg8(fd, AS7341_STATUS, &status) != 0)
        return -1;
    if (!(status & 0x01)) {
        fprintf(stderr, "AS7341 data not yet valid (status=0x%02X)\n", status);
        return -1;
    }

    /* Read all 10 spectral channels */
    if (i2c_read_reg16(fd, AS7341_CH0_DATA_L, &ch[0]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_CH1_DATA_L, &ch[1]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_CH2_DATA_L, &ch[2]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_CH3_DATA_L, &ch[3]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_CH4_DATA_L, &ch[4]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_CH5_DATA_L, &ch[5]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_CH6_DATA_L, &ch[6]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_CH7_DATA_L, &ch[7]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_CH8_DATA_L, &ch[8]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_CH9_DATA_L, &ch[9]) != 0) return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static float compute_lux_approx(const uint16_t *ch)
{
    /*
     * Simplified lux approximation from the 10 spectral channels.
     * F1..F8 are the visible-band channels; Clear (CH0) and NIR (CH9)
     * are subtracted to avoid saturation and highlight the visible
     * signal.  A production system would use a calibrated white-point
     * transform.
     */
    float r = (float)ch[1];
    float g = (float)ch[2];
    float b = (float)ch[3];
    float clear = (float)ch[0];
    float nir   = (float)ch[9];

    float vis = r + g + b;
    float denom = clear + nir + 1.0f;
    if (denom < 1.0f) denom = 1.0f;

    return (vis / denom) * 1000.0f;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, const uint16_t *ch, float lux)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        strncpy(ts, "1970-01-01 00:00:00", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    }

    fprintf(fp, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
            ts,
            ch[0], ch[1], ch[2], ch[3], ch[4],
            ch[5], ch[6], ch[7], ch[8], ch[9],
            lux);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Put sensor in standby */
        (void)i2c_write_reg8(g_i2c_fd, AS7341_ENABLE, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AS7341_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                AS7341_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (as7341_init(g_i2c_fd) != 0) {
        fprintf(stderr, "AS7341 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp,
                "timestamp,ch0,ch1,ch2,ch3,ch4,ch5,ch6,ch7,ch8,ch9,lux\n");
        fflush(g_log_fp);
    }

    printf("AS7341 spectral logger started.  Press Ctrl-C to stop.\n");

    while (g_running) {
        uint16_t ch[10];
        float lux;

        if (as7341_read_spectral(g_i2c_fd, ch) != 0) {
            fprintf(stderr, "Spectral read failed; retrying next cycle.\n");
        } else {
            lux = compute_lux_approx(ch);
            log_data(g_log_fp, ch, lux);
            printf("Lux: %.2f  (F1:%u F2:%u F3:%u F4:%u F5:%u F6:%u F7:%u F8:%u Clear:%u NIR:%u)\n",
                   lux,
                   ch[1], ch[2], ch[3], ch[4], ch[5],
                   ch[6], ch[7], ch[8], ch[0], ch[9]);
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

