    if (i2c_write_reg8(fd, AS7341_ENABLE, AS7341_ENABLE_PON) != 0)
        return -1;
    usleep(10000);  /* 10 ms power-up settle */

    /* Set integration time (ATIME) — 0x00 = 2.78 ms per channel */
    if (i2c_write_reg8(fd, AS7341_ATIME, 0x00) != 0)
        return -1;

    /* Set wait time (WTIME) — 0x00 = 2.78 ms */
    if (i2c_write_reg8(fd, AS7341_WTIME, 0x00) != 0)
        return -1;

    /* Configure SMUX: CFG6 selects the 10-channel sequence */
    if (i2c_write_reg8(fd, AS7341_CFG6, 0x00) != 0)
        return -1;

    /* Enable spectral measurement */
    if (i2c_write_reg8(fd, AS7341_ENABLE,
                       AS7341_ENABLE_PON | AS7341_ENABLE_SP_EN) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int as7341_read_spectral(int fd, uint16_t *ch)
{
    /* Check status: bit 0 (AVALID) indicates data is new */
    uint8_t status = 0;
    if (i2c_read_reg8(fd, AS7341_STATUS, &status) != 0)
        return -1;
    if (!(status & 0x01)) {
        fprintf(stderr, "AS7341 data not yet valid (status=0x%02X)\n", status);
        return -1;
    }

    /* Read all 10 spectral channels */
    if (i2c_read_reg16(fd, AS7341_CH0_DATA_L, &ch[0]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_CH1_DATA_L, &ch[1]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_CH2_DATA_L, &ch[2]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_CH3_DATA_L, &ch[3]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_CH4_DATA_L, &ch[4]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_CH5_DATA_L, &ch[5]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_CH6_DATA_L, &ch[6]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_CH7_DATA_L, &ch[7]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_CH8_DATA_L, &ch[8]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_CH9_DATA_L, &ch[9]) != 0) return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static float compute_lux_approx(const uint16_t *ch)
{
    /*
     * Simplified lux approximation from the 10 spectral channels.
     * F1..F8 are the visible-band channels; Clear (CH0) and NIR (CH9)
     * are subtracted to avoid saturation and highlight the visible
     * signal.  A production system would use a calibrated white-point
     * transform.
     */
    float r = (float)ch[1];
    float g = (float)ch[2];
    float b = (float)ch[3];
    float clear = (float)ch[0];
    float nir   = (float)ch[9];

    float vis = r + g + b;
    float denom = clear + nir + 1.0f;
    if (denom < 1.0f) denom = 1.0f;

    return (vis / denom) * 1000.0f;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, const uint16_t *ch, float lux)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        strncpy(ts, "1970-01-01 00:00:00", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    }

    fprintf(fp, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
            ts,
            ch[0], ch[1], ch[2], ch[3], ch[4],
            ch[5], ch[6], ch[7], ch[8], ch[9],
            lux);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Put sensor in standby */
        (void)i2c_write_reg8(g_i2c_fd, AS7341_ENABLE, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AS7341_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                AS7341_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (as7341_init(g_i2c_fd) != 0) {
        fprintf(stderr, "AS7341 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp,
                "timestamp,ch0,ch1,ch2,ch3,ch4,ch5,ch6,ch7,ch8,ch9,lux\n");
        fflush(g_log_fp);
    }

    printf("AS7341 spectral logger started.  Press Ctrl-C to stop.\n");

    while (g_running) {
        uint16_t ch[10];
        float lux;

        if (as7341_read_spectral(g_i2c_fd, ch) != 0) {
            fprintf(stderr, "Spectral read failed; retrying next cycle.\n");
        } else {
            lux = compute_lux_approx(ch);
            log_data(g_log_fp, ch, lux);
            printf("Lux: %.2f  (F1:%u F2:%u F3:%u F4:%u F5:%u F6:%u F7:%u F8:%u Clear:%u NIR:%u)\n",
                   lux,
                   ch[1], ch[2], ch[3], ch[4], ch[5],
                   ch[6], ch[7], ch[8], ch[0], ch[9]);
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

code:
/*
 * D7S seismic sensor reader for Raspberry Pi Zero W
 *
 * Reads tri-axial acceleration data from an Omron D7S over I2C
 * and logs timestamped values to a CSV file.
 *
 * Build:  gcc -O2 -Wall -Wextra -o d7s_reader d7s_reader.c
 * Run:    ./d7s_reader [-a i2c_addr] [-i interval_s] [-f filename]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- D7S constants (per Omron D7S datasheet) ---- */
#define D7S_DEFAULT_I2C_ADDR 0x28
#define D7S_REG_X_AXIS_LSB   0x00
#define D7S_REG_X_AXIS_MSB   0x01
#define D7S_REG_Y_AXIS_LSB   0x02
#define D7S_REG_Y_AXIS_MSB   0x03
#define D7S_REG_Z_AXIS_LSB   0x04
#define D7S_REG_Z_AXIS_MSB   0x05
#define D7S_REG_STATUS       0x06
#define D7S_REG_CTRL         0x07

#define D7S_CTRL_RESET       0x01
#define D7S_CTRL_START       0x02
#define D7S_CTRL_MODE_MASK  0x0C
#define D7S_CTRL_MODE_CONT  0x04

#define D7S_STATUS_READY    0x01

#define D7S_SENSITIVITY     0.0000625f   /* g/LSB at 12-bit range */

#define I2C_BUS            "/dev/i2c-1"
#define DEFAULT_FILENAME   "seismic_data.csv"
#define DEFAULT_INTERVAL   1
#define MAX_RETRIES        3
#define RETRY_DELAY_MS     10

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_csv_fp = NULL;
static FILE    *g_err_fp = NULL;

/* ---- Prototypes ---- */
static void  signal_handler(int sig);
static void  log_error(const char *msg);
static int   i2c_write_reg8(int fd, uint8_t reg, uint8_t val);
static int   i2c_read_reg8(int fd, uint8_t reg, uint8_t *val);
static int   d7s_init(int fd);
static int   d7s_read_xyz(int fd, float *x, float *y, float *z);
static void  get_timestamp(char *buf, size_t len);
static int   log_data(FILE *fp, const char *ts, float x, float y, float z);
static void  cleanup(void);

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    if (g_err_fp) {
        fprintf(g_err_fp, "%s: %s (errno %d: %s)\n",
                ts, msg, errno, strerror(errno));
        fflush(g_err_fp);
    }
    fprintf(stderr, "%s: %s (errno %d: %s)\n",
            ts, msg, errno, strerror(errno));
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        log_error("I2C write_reg8 failed");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        log_error("I2C read_reg8: write reg failed");
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        log_error("I2C read_reg8: read data failed");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int d7s_init(int fd)
{
    /* Software reset */
    if (i2c_write_reg8(fd, D7S_REG_CTRL, D7S_CTRL_RESET) < 0)
        return -1;
    usleep(10000);  /* 10 ms settle */

    /* Start continuous conversion mode */
    if (i2c_write_reg8(fd, D7S_REG_CTRL,
                       D7S_CTRL_MODE_CONT | D7S_CTRL_START) < 0)
        return -1;

    /* Verify status bit 0 is ready */
    uint8_t status = 0;
    for (int i = 0; i < 10; i++) {
        if (i2c_read_reg8(fd, D7S_REG_STATUS, &status) == 0) {
            if (status & D7S_STATUS_READY)
                return 0;
        }
        usleep(5000);
    }
    log_error("D7S status never ready after init");
    return -1;
}

/* ------------------------------------------------------------------ */
static int d7s_read_xyz(int fd, float *x, float *y, float *z)
{
    uint8_t xl, xh, yl, yh, zl, zh;
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_reg8(fd, D7S_REG_X_AXIS_LSB, &xl) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_REG_X_AXIS_MSB, &xh) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_REG_Y_AXIS_LSB, &yl) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_REG_Y_AXIS_MSB, &yh) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_REG_Z_AXIS_LSB, &zl) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_REG_Z_AXIS_MSB, &zh) < 0) return -1;

    raw_x = (int16_t)((xh << 8) | xl);
    raw_y = (int16_t)((yh << 8) | yl);
    raw_z = (int16_t)((zh << 8) | zl);

    *x = (float)raw_x * D7S_SENSITIVITY;
    *y = (float)raw_y * D7S_SENSITIVITY;
    *z = (float)raw_z * D7S_SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm);
}

/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, const char *ts, float x, float y, float z)
{
    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z) < 0) {
        log_error("fprintf to CSV failed");
        return -1;
    }
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_csv_fp) { fflush(g_csv_fp); fclose(g_csv_fp); g_csv_fp = NULL; }
    if (g_err_fp) { fflush(g_err_fp); fclose(g_err_fp); g_err_fp = NULL; }
    if (g_i2c_fd >= 0) { close(g_i2c_fd); g_i2c_fd = -1; }
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int i2c_addr   = D7S_DEFAULT_I2C_ADDR;
    int interval   = DEFAULT_INTERVAL;
    const char *filename = DEFAULT_FILENAME;
    int opt;

    while ((opt = getopt(argc, argv, "a:i:f:h")) != -1) {
        switch (opt) {
            case 'a': i2c_addr = (int)strtol(optarg, NULL, 0); break;
            case 'i': interval = atoi(optarg); break;
            case 'f': filename = optarg; break;
            case 'h':
            default:
                fprintf(stderr,
                        "Usage: %s [-a i2c_addr] [-i interval_s] [-f filename]\n",
                        argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (interval <= 0) {
        fprintf(stderr, "Interval must be positive\n");
        return EXIT_FAILURE;
    }

    /* Open error log */
    g_err_fp = fopen("seismic_error.log", "a");
    if (!g_err_fp) {
        fprintf(stderr, "Cannot open seismic_error.log: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open CSV */
    g_csv_fp = fopen(filename, "a");
    if (!g_csv_fp) {
        log_error("Cannot open CSV file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_csv_fp) == 0) {
        fprintf(g_csv_fp, "timestamp,x_g,y_g,z_g\n");
        fflush(g_csv_fp);
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        log_error("Cannot open I2C bus");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, i2c_addr) < 0) {
        log_error("Cannot set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (d7s_init(g_i2c_fd) < 0) {
        log_error("D7S initialization failed (sensor absent or bus error)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("D7S reader started. I2C addr=0x%02X, interval=%ds, file=%s\n",
           i2c_addr, interval, filename);
    printf("Press Ctrl+C to stop.\n");

    /* Main loop */
    while (g_running) {
        float x, y, z;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (d7s_read_xyz(g_i2c_fd, &x, &y, &z) == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1)
                usleep(RETRY_DELAY_MS * 1000);
        }

        if (ok) {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            if (log_data(g_csv_fp, ts, x, y, z) < 0)
                log_error("Failed to log data row");
        } else {
            log_error("D7S read failed after retries");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int s = 0; s < interval * 10 && g_running; s++)
            usleep(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

