#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define BH1750_PWR_ON  0x01
#define BH1750_RESET   0x07
#define BH1750_CONT_HRES 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define MULTICAST_TTL  1
#define SAMPLE_INTERVAL 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_sockfd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int init_bh1750(int fd) {
    if (i2c_write_byte(fd, BH1750_PWR_ON) < 0) return -1;
    usleep(10000);
    if (i2c_write_byte(fd, BH1750_RESET) < 0) return -1;
    usleep(10000);
    if (i2c_write_byte(fd, BH1750_CONT_HRES) < 0) return -1;
    usleep(180000);
    return 0;
}

static int read_bh1750(int fd, float *lux_out) {
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(float lux) {
    char buffer[32];
    int len = snprintf(buffer, sizeof(buffer), "%.2f", lux);
    if (len < 0 || (size_t)len >= sizeof(buffer)) {
        fprintf(stderr, "snprintf failed\n");
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);
    if (sendto(g_sockfd, buffer, (size_t)len, 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                BH1750_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }
    if (init_bh1750(g_i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    g_sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (g_sockfd < 0) {
        fprintf(stderr, "socket failed: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }
    int ttl = MULTICAST_TTL;
    if (setsockopt(g_sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "setsockopt IP_MULTICAST_TTL failed: %s\n", strerror(errno));
        close(g_sockfd);
        close(g_i2c_fd);
        return 1;
    }

    while (g_running) {
        float lux;
        if (read_bh1750(g_i2c_fd, &lux) < 0) {
            fprintf(stderr, "BH1750 read error, retrying in %d s...\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }
        if (send_multicast(lux) < 0) {
            fprintf(stderr, "Multicast send error\n");
        }
        sleep(SAMPLE_INTERVAL);
    }

    if (g_sockfd >= 0) close(g_sockfd);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

