#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <termios.h>
#include <errno.h>
#include <sys/select.h>
#include <time.h>
#include <signal.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define READ_TIMEOUT_SEC 2
#define INTER_BYTE_TIMEOUT_SEC 0
#define INTER_BYTE_TIMEOUT_USEC 500000
#define LINE_BUF_SIZE 256

static volatile sig_atomic_t g_terminate = 0;
static int g_uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_terminate = 1;
}

static int init_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    /* Clear O_NONBLOCK so reads block per termios VMIN/VTIME settings */
    if (fcntl(fd, F_SETFL, 0) < 0) {
        fprintf(stderr, "Error clearing O_NONBLOCK: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, baud);
    cfsetospeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag = 0;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | INLCR | ICRNL);

    tty.c_oflag = 0;
    tty.c_lflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = READ_TIMEOUT_SEC * 10; /* deciseconds */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static void cleanup_uart(int fd) {
    if (fd >= 0) {
        tcflush(fd, TCIOFLUSH);
        close(fd);
    }
}

static int parse_radar_line(const char *line, time_t *timestamp, float *range) {
    char *copy = strdup(line);
    if (!copy) {
        fprintf(stderr, "strdup failed: %s\n", strerror(errno));
        return -1;
    }

    char *saveptr = NULL;
    char *ts_str = strtok_r(copy, ",", &saveptr);
    char *range_str = strtok_r(NULL, ",", &saveptr);

    if (!ts_str || !range_str) {
        fprintf(stderr, "Malformed line (missing fields): %s\n", line);
        free(copy);
        return -1;
    }

    errno = 0;
    char *endptr = NULL;
    long ts_val = strtol(ts_str, &endptr, 10);
    if (errno != 0 || endptr == ts_str || *endptr != '\0') {
        fprintf(stderr, "Invalid timestamp: %s\n", ts_str);
        free(copy);
        return -1;
    }

    errno = 0;
    endptr = NULL;
    float range_val = strtof(range_str, &endptr);
    if (errno != 0 || endptr == range_str || *endptr != '\0') {
        fprintf(stderr, "Invalid range: %s\n", range_str);
        free(copy);
        return -1;
    }

    *timestamp = (time_t)ts_val;
    *range = range_val;
    free(copy);
    return 0;
}

static void log_radar_data(time_t timestamp, float range) {
    struct tm *tm_info = localtime(&timestamp);
    if (!tm_info) {
        fprintf(stderr, "localtime failed: %s\n", strerror(errno));
        return;
    }

    char time_str[32];
    if (strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("Timestamp: %s, Range: %.2f meters\n", time_str, range);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (g_uart_fd < 0) {
        return EXIT_FAILURE;
    }

    char line_buf[LINE_BUF_SIZE];
    size_t line_len = 0;
    char read_buf[256];
    time_t timestamp;
    float range;

    printf("Radar data acquisition started on %s at 115200 8N1.\n", UART_DEVICE);
    fflush(stdout);

    while (!g_terminate) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(g_uart_fd, &readfds);

        struct timeval tv;
        tv.tv_sec = READ_TIMEOUT_SEC;
        tv.tv_usec = 0;

        int sel_ret = select(g_uart_fd + 1, &readfds, NULL, NULL, &tv);
        if (sel_ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "select() error: %s\n", strerror(errno));
            break;
        }
        if (sel_ret == 0) {
            fprintf(stderr, "Warning: UART read timeout (sensor absent or no data)\n");
            continue;
        }

        ssize_t bytes_read = read(g_uart_fd, read_buf, sizeof(read_buf) - 1);
        if (bytes_read < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "read() error: %s\n", strerror(errno));
            break;
        }
        if (bytes_read == 0) {
            fprintf(stderr, "UART closed unexpectedly\n");
            break;
        }

        for (ssize_t i = 0; i < bytes_read; i++) {
            char c = read_buf[i];

            if (c == '\n') {
                line_buf[line_len] = '\0';

                if (line_len > 0) {
                    if (parse_radar_line(line_buf, &timestamp, &range) == 0) {
                        log_radar_data(timestamp, range);
                    }
                }
                line_len = 0;
            } else if (c != '\r') {
                if (line_len < LINE_BUF_SIZE - 1) {
                    line_buf[line_len++] = c;
                } else {
                    fprintf(stderr, "Line too long, discarding buffer\n");
                    line_len = 0;
                }
            }
        }
    }

    cleanup_uart(g_uart_fd);
    g_uart_fd = -1;

    printf("Radar data acquisition stopped.\n");
    return EXIT_SUCCESS;
}

